-- DROP SCHEMA "Reports";
CREATE SCHEMA "Reports" AUTHORIZATION "HIS-STAGING";

-- "Reports".bi_collection source
CREATE OR REPLACE VIEW "Reports".bi_collectionAS SELECT organization_id,    unit_id,    depositdate::date AS depositdate,    unit_name,    patientname,    cash,    cheque,    creditcard,    debitcard,    mpesa,    loyaltycard,    e_transfer   FROM allcollectionsummary  WHERE deposit = ANY (ARRAY['DCD Bill'::text, 'ERD Bill'::text, 'IPD Advance'::text, 'IPD Bill'::text, 'OPD Advance'::text, 'OPD Bill'::text, 'Patient Advance'::text])  ORDER BY unit_id;

-- "Reports".bi_collection_new source
CREATE OR REPLACE VIEW "Reports".bi_collection_newAS SELECT count(*) AS ptcount,    unit_name,    gender_name,    created_date,    type,    unit_id,    gender_id,    organization_id   FROM get_patientcountdetails  GROUP BY gender_id, unit_name, gender_name, created_date, type, unit_id, organization_id;

-- "Reports".bi_dashboard_revenue_collection_patientcount source
CREATE MATERIALIZED VIEW "Reports".bi_dashboard_revenue_collection_patientcountTABLESPACE pg_defaultAS SELECT row_to_json(detaillist.*) AS payment,    grtotal.detaillist1 AS revenue,    detaillist2.ptcount AS patientcount,    detaillist.trandate,    detaillist.organization_id,    detaillist.unit_id   FROM ( SELECT bi_finaltotalnew.trandate,            bi_finaltotalnew.organization_id,            bi_finaltotalnew.unit_id,            sum(bi_finaltotalnew.totalcash) AS cash,            sum(bi_finaltotalnew.cheque) AS cheque,            sum(bi_finaltotalnew.creditcard) AS creditcard,            sum(bi_finaltotalnew.debitcard) AS debitcard,            sum(bi_finaltotalnew.online) AS online           FROM "Reports".bi_finaltotalnew          GROUP BY bi_finaltotalnew.trandate, bi_finaltotalnew.organization_id, bi_finaltotalnew.unit_id) detaillist     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,            detaillist1.trandate,            detaillist1.organization_id,            detaillist1.unit_id           FROM ( SELECT pay.trandate,                    pay.organization_id,                    pay.unit_id,                    sum(pay.lab) AS lab,                    sum(pay.radiology) AS radiology                   FROM ( SELECT get_groupwisetotal.trandate,                            get_groupwisetotal.organization_id,                            get_groupwisetotal.unit_id,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'Pathology'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS lab,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'Radiology'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS radiology                           FROM "Reports".get_groupwisetotal                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name, get_groupwisetotal.organization_id, get_groupwisetotal.unit_id) pay                  GROUP BY pay.trandate, pay.organization_id, pay.unit_id) detaillist1) grtotal ON grtotal.trandate = detaillist.trandate AND grtotal.organization_id = detaillist.organization_id AND grtotal.unit_id = detaillist.unit_id     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,            ptcount.trandate,            ptcount.organization_id,            ptcount.unit_id           FROM ( SELECT ptcounts.created_date AS trandate,                    ptcounts.organization_id,                    ptcounts.unit_id,                    COALESCE(sum(ptcounts.op), 0::numeric) AS op,                    COALESCE(sum(ptcounts.ip), 0::numeric) AS ip,                    COALESCE(sum(ptcounts.male), 0::numeric) AS male,                    COALESCE(sum(ptcounts.female), 0::numeric) AS female                   FROM ( SELECT bi_collection_new.created_date,                                CASE                                    WHEN bi_collection_new.type = 'OP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS op,                                CASE                                    WHEN bi_collection_new.type = 'IP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS ip,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Male'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS male,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Female'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS female,                            bi_collection_new.organization_id,                            bi_collection_new.unit_id,                            bi_collection_new.ptcount                           FROM "Reports".bi_collection_new) ptcounts                  GROUP BY ptcounts.created_date, ptcounts.organization_id, ptcounts.unit_id) ptcount) detaillist2 ON detaillist2.trandate = detaillist.trandate AND detaillist2.organization_id = detaillist.organization_id AND detaillist2.unit_id = detaillist.unit_idWITH NO DATA;

-- "Reports".bi_finaltotal source
CREATE OR REPLACE VIEW "Reports".bi_finaltotalAS SELECT bi_image_collection.organization_id,    bi_image_collection.unit_id,    bi_image_collection.depositdate AS trandate,    sum(bi_image_collection.cash) AS totalcash,    sum(bi_image_collection.e_transfer) AS online,    grtran.sono,    grtran.x_ray,    grtran.echo,    grtran.doppler,    grtran.ct,    grtran.ecg,    grtran.mri,    grtran.path,    grtran.consultation   FROM "Reports".bi_image_collection     JOIN ( SELECT bi_group_total.organization_id,            bi_group_total.unit_id,            bi_group_total.trandate,            sum(bi_group_total.totalcash) AS totalcash,            sum(bi_group_total.online) AS online,            sum(bi_group_total.sono) AS sono,            sum(bi_group_total.x_ray) AS x_ray,            sum(bi_group_total.echo) AS echo,            sum(bi_group_total.doppler) AS doppler,            sum(bi_group_total.ct) AS ct,            sum(bi_group_total.ecg) AS ecg,            sum(bi_group_total.mri) AS mri,            sum(bi_group_total.path) AS path,            sum(bi_group_total.consultation) AS consultation           FROM "Reports".bi_group_total          GROUP BY bi_group_total.organization_id, bi_group_total.unit_id, bi_group_total.trandate) grtran ON bi_image_collection.unit_id = grtran.unit_id AND bi_image_collection.depositdate = grtran.trandate  GROUP BY bi_image_collection.organization_id, bi_image_collection.unit_id, bi_image_collection.depositdate, grtran.sono, grtran.x_ray, grtran.echo, grtran.doppler, grtran.ct, grtran.ecg, grtran.mri, grtran.path, grtran.consultation;

-- "Reports".bi_finaltotalnew source
CREATE OR REPLACE VIEW "Reports".bi_finaltotalnewAS SELECT organization_id,    unit_id,    depositdate AS trandate,    sum(cash) AS totalcash,    sum(e_transfer) AS online,    sum(cheque) AS cheque,    sum(creditcard) AS creditcard,    sum(debitcard) AS debitcard,    sum(mpesa) AS mpesa,    sum(loyaltycard) AS loyaltycard   FROM "Reports".bi_collection  GROUP BY organization_id, unit_id, depositdate;

-- "Reports".bi_group_total source
CREATE OR REPLACE VIEW "Reports".bi_group_totalAS SELECT organisation_id AS organization_id,    unit_id,    bill_date_time AS trandate,    sum(net_amt) AS totalcash,    0 AS online,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1194 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS sono,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1185 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS x_ray,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1186 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS echo,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1187 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS doppler,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1196 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS ct,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1510 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS ecg,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1197 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS mri,    COALESCE(sum(        CASE            WHEN sub_speciality_id = ANY (ARRAY[1193, 1184, 1189]) THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS path,    COALESCE(sum(        CASE            WHEN sub_speciality_id = 1195 THEN net_amt            ELSE NULL::double precision        END), 0::double precision) AS consultation,    unit_name,    unit_address   FROM "Reports".image_groupwiserevenucount  GROUP BY organisation_id, unit_id, bill_date_time, sub_speciality_id, unit_name, unit_address;

-- "Reports".bi_groupwiserevenucount source
CREATE OR REPLACE VIEW "Reports".bi_groupwiserevenucountAS SELECT bm.bill_date_time::date AS bill_date_time,    sp.speciality_id,    sp.speciality_name,    ssp.sub_speciality_id,    ssp.sub_speciality_name,    sum(bd.gross_amount - bd.discount) AS net_amt,    count(bm.patient_id) AS patient_id,    bm.unit_id,    bm.bill_cancelled,    row_number() OVER (ORDER BY (bm.bill_date_time::date)) AS serialno,    um.unit_name,    um.unit_address,    bm.organisation_id   FROM billing.m_billing_master bm     JOIN billing.t_billing_details bd ON bd.billing_master_id = bm.billing_master_id     JOIN service.m_service_master sm ON bd.service_id = sm.service_master_id     JOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_id     JOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_id     JOIN unitinformation um ON bm.unit_id = um.unit_id     JOIN billing.t_payment_reciept_master pr ON bm.billing_master_id = pr.billing_master_id     JOIN billing.t_payment_reciept_details rd ON pr.payment_reciept_id = rd.payment_receipt_master_id  WHERE bm.bill_cancelled = 'N'::bpchar AND bm.bill_status_id = 3  GROUP BY (bm.bill_date_time::date), sp.speciality_id, sp.speciality_name, ssp.sub_speciality_id, ssp.sub_speciality_name, bm.unit_id, bm.bill_cancelled, um.unit_name, um.unit_address, bm.organisation_id;

-- "Reports".bi_image_collection source
CREATE OR REPLACE VIEW "Reports".bi_image_collectionAS SELECT organization_id,    unit_id,    depositdate::date AS depositdate,    unit_name,    patientname,    cash,    e_transfer,    net_amount,    transaction_type_desc,    referral_name,    cash + e_transfer AS netcash,    outstanding   FROM image_allcollectionsummary_all  WHERE organization_id = 10 AND (deposit = ANY (ARRAY['OPD Bill'::text, 'Mis.Income'::text]))  ORDER BY unit_id;

-- "Reports".bi_image_expenses source
CREATE OR REPLACE VIEW "Reports".bi_image_expensesAS SELECT organization_id,    unit_id,    depositdate,    unit_name,    patientname,    cash,    e_transfer,    net_amount,    transaction_type_desc,    referral_name,    cash + e_transfer AS netcash   FROM image_allcollectionsummary_all  WHERE organization_id = 10 AND deposit = 'Expenses'::text  ORDER BY unit_id;

-- "Reports".bi_image_outstandingbills source
CREATE OR REPLACE VIEW "Reports".bi_image_outstandingbillsAS SELECT DISTINCT bm.billing_master_id,    bm.bill_number,    bm.bill_date_time,    bm.total_bill_amount,    bm.concession_amount + bm.discount_amount AS totaldiscount,    bm.net_amount,    bm.cr_amount,    bm.outstanding,    vm.visit_type_id,    umm.unit_name,    umm.unit_address,    umm.unit_contact,    umm.unit_contact_2,    pm.patientname,    pm.patient_id,    pm.uhid_number,    umm.unit_id,    bm.bill_status_id,    status_master.bill_status_desc,    umm.image,    bm.organisation_id,    payment.amount AS paidamount   FROM billing.m_billing_master bm     JOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_id     JOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_id     JOIN m_user_master um ON bdet.created_by = um.user_id     JOIN m_unit_master umm ON bdet.unit_id = umm.unit_id     JOIN patient.patientinformation pm ON bm.patient_id = pm.patient_id     LEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_id     LEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_id     LEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_id     LEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_id     LEFT JOIN doctor.m_doctor_master encounterdoctor ON adm.doctor_id = encounterdoctor.doctor_id     LEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_id     LEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_id     LEFT JOIN opd.t_patient_sponsor_details sd ON adm.admission_id = sd.admission_id     LEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_id     LEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_id     LEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_id     LEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_id     LEFT JOIN ( SELECT prm.billing_master_id,            sum(prm.amount) AS amount           FROM billing.t_payment_reciept_master prm             JOIN billing.m_billing_master bmm ON prm.billing_master_id = bmm.billing_master_id          WHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULL          GROUP BY prm.billing_master_id) payment ON bm.billing_master_id = payment.billing_master_id  WHERE (bm.visit_type_id = ANY (ARRAY[2, 3])) AND bm.outstanding &lt;&gt; 0::double precisionUNION SELECT DISTINCT bm.billing_master_id,    bm.bill_number,    bm.bill_date_time,    bm.total_bill_amount,    bm.concession_amount + bm.discount_amount AS totaldiscount,    bm.net_amount,    bm.cr_amount,    bm.outstanding,    vm.visit_type_id,    umm.unit_name,    umm.unit_address,    umm.unit_contact,    umm.unit_contact_2,    pm.patientname,    pm.patient_id,    pm.uhid_number,    umm.unit_id,    bm.bill_status_id,    status_master.bill_status_desc,    umm.image,    bm.organisation_id,    payment.amount AS paidamount   FROM billing.m_billing_master bm     JOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_id     JOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_id     JOIN m_user_master um ON bdet.created_by = um.user_id     JOIN m_unit_master umm ON bdet.unit_id = umm.unit_id     JOIN patient.patientinformation pm ON bm.patient_id = pm.patient_id     LEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_id     LEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_id     LEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_id     LEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_id     LEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_id     LEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_id     LEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_id     LEFT JOIN opd.t_patient_sponsor_details sd ON em.encounter_id = sd.encounter_id     LEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_id     LEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_id     LEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_id     LEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_id     LEFT JOIN ( SELECT prm.billing_master_id,            sum(prm.amount) AS amount           FROM billing.t_payment_reciept_master prm             JOIN billing.m_billing_master bmm ON prm.billing_master_id = bmm.billing_master_id          WHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULL          GROUP BY prm.billing_master_id) payment ON bm.billing_master_id = payment.billing_master_id  WHERE bm.visit_type_id = 1 AND bm.outstanding &lt;&gt; 0::double precision;

-- "Reports".bi_months_dashboard_revenue_collection_patientcount source
CREATE MATERIALIZED VIEW "Reports".bi_months_dashboard_revenue_collection_patientcountTABLESPACE pg_defaultAS SELECT row_to_json(detaillist.*) AS payment,    grtotal.detaillist1 AS revenue,    detaillist2.ptcount AS patientcount,    detaillist.trandate,    detaillist.organization_id,    detaillist.unit_id   FROM ( SELECT to_char(bi_finaltotalnew.trandate::timestamp with time zone, 'Month,YY'::text) AS trandate,            bi_finaltotalnew.organization_id,            bi_finaltotalnew.unit_id,            sum(bi_finaltotalnew.totalcash) AS cash,            sum(bi_finaltotalnew.cheque) AS cheque,            sum(bi_finaltotalnew.creditcard) AS creditcard,            sum(bi_finaltotalnew.debitcard) AS debitcard,            sum(bi_finaltotalnew.online) AS online           FROM "Reports".bi_finaltotalnew          GROUP BY (to_char(bi_finaltotalnew.trandate::timestamp with time zone, 'Month,YY'::text)), bi_finaltotalnew.organization_id, bi_finaltotalnew.unit_id) detaillist     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,            detaillist1.trandate,            detaillist1.organization_id,            detaillist1.unit_id           FROM ( SELECT pay.trandate,                    pay.organization_id,                    pay.unit_id,                    sum(pay.lab) AS lab,                    sum(pay.radiology) AS radiology                   FROM ( SELECT to_char(get_groupwisetotal.trandate::timestamp with time zone, 'Month,YY'::text) AS trandate,                            get_groupwisetotal.organization_id,                            get_groupwisetotal.unit_id,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'Pathology'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS lab,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'Radiology'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS radiology                           FROM "Reports".get_groupwisetotal                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name, get_groupwisetotal.organization_id, get_groupwisetotal.unit_id) pay                  GROUP BY pay.trandate, pay.organization_id, pay.unit_id) detaillist1) grtotal ON grtotal.trandate = detaillist.trandate AND grtotal.organization_id = detaillist.organization_id AND grtotal.unit_id = detaillist.unit_id     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,            ptcount.trandate,            ptcount.organization_id,            ptcount.unit_id           FROM ( SELECT to_char(ptcounts.created_date::timestamp with time zone, 'Month,YY'::text) AS trandate,                    ptcounts.organization_id,                    ptcounts.unit_id,                    COALESCE(sum(ptcounts.op), 0::numeric) AS op,                    COALESCE(sum(ptcounts.ip), 0::numeric) AS ip,                    COALESCE(sum(ptcounts.male), 0::numeric) AS male,                    COALESCE(sum(ptcounts.female), 0::numeric) AS female                   FROM ( SELECT bi_collection_new.created_date,                                CASE                                    WHEN bi_collection_new.type = 'OP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS op,                                CASE                                    WHEN bi_collection_new.type = 'IP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS ip,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Male'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS male,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Female'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS female,                            bi_collection_new.organization_id,                            bi_collection_new.unit_id,                            bi_collection_new.ptcount                           FROM "Reports".bi_collection_new) ptcounts                  GROUP BY (to_char(ptcounts.created_date::timestamp with time zone, 'Month,YY'::text)), ptcounts.organization_id, ptcounts.unit_id) ptcount) detaillist2 ON detaillist2.trandate = detaillist.trandate AND detaillist2.organization_id = detaillist.organization_id AND detaillist2.unit_id = detaillist.unit_idWITH NO DATA;

-- "Reports".deptcollectionkau source
CREATE OR REPLACE VIEW "Reports".deptcollectionkauAS SELECT msm.speciality_id,    sum(tbd.net_amt) AS "netSum",    tbd.organization_id,    tbd.unit_id,    to_char(tbd.created_date, 'YYYY-MM-DD'::text) AS "createdDate"   FROM billing.t_billing_details tbd     JOIN service.m_service_master msm ON tbd.service_id = msm.service_master_id  GROUP BY (to_char(tbd.created_date, 'YYYY-MM-DD'::text)), tbd.organization_id, tbd.unit_id, msm.speciality_id;

-- "Reports".doctorinformationipd source
CREATE OR REPLACE VIEW "Reports".doctorinformationipdAS SELECT DISTINCT t_admission.admission_id,    m_doctor_master.doctor_id,    ((('Dr. '::text || ' '::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS doctorname,    m_gender_master.gender_name AS docgender,    m_doctor_category.doctor_category_description,    m_speciality_master.speciality_name AS docspeciality,    age(m_doctor_master.dob) AS docage,    m_doctor_master.dob AS docdob,    m_doctor_master.country_calling_code,    m_doctor_master.mobile_number AS docmobile,    m_doctor_master.email AS docemail,    m_doctor_master.doctor_image,    m_doctor_master.registration_number AS docreg,    m_doctor_master.slot_time_span,    m_doctor_master.doctor_episod_time_span,    m_speciality_master.speciality_id   FROM adt.t_admission     LEFT JOIN doctor.m_doctor_master ON t_admission.doctor_id = m_doctor_master.doctor_id     LEFT JOIN m_gender_master ON m_doctor_master.gender_id = m_gender_master.gender_id     LEFT JOIN m_doctor_category ON m_doctor_master.doc_category_id = m_doctor_category.doctor_category_id     LEFT JOIN doctor.t_doctor_speciality_mapper ON t_admission.doctor_id = t_doctor_speciality_mapper.doctor_id     LEFT JOIN doctor.m_speciality_master ON t_doctor_speciality_mapper.speciality_id = m_speciality_master.speciality_id  ORDER BY t_admission.admission_id;

-- "Reports".get_groupwisetotal source
CREATE OR REPLACE VIEW "Reports".get_groupwisetotalAS SELECT organisation_id AS organization_id,    unit_id,    bill_date_time AS trandate,    sum(net_amt) AS totalcash,    0 AS online,    sub_speciality_id,    sub_speciality_name,    COALESCE(sum(net_amt), 0::double precision) AS netsum,    speciality_id,    speciality_name   FROM "Reports".bi_groupwiserevenucount  WHERE (sub_speciality_id IN ( SELECT mssm.sub_speciality_id           FROM doctor.m_sub_speciality_master mssm          WHERE (mssm.speciality_id IN ( SELECT tuabc.radiology_speciality_id                   FROM t_unit_application_billing_configuration tuabc)))) OR (sub_speciality_id IN ( SELECT mssm.sub_speciality_id           FROM doctor.m_sub_speciality_master mssm          WHERE (mssm.speciality_id IN ( SELECT tlc.lab_speciality_id                   FROM t_lab_configuration tlc))))  GROUP BY organisation_id, unit_id, bill_date_time, sub_speciality_id, sub_speciality_name, speciality_id, speciality_name;

-- "Reports".getopdconsultatationdoctorwise source
CREATE OR REPLACE VIEW "Reports".getopdconsultatationdoctorwiseAS SELECT DISTINCT m_billing_master.billing_master_id,    t_patient_registration.uhid_number,    (t_patient_registration.first_name::text || ' '::text) || t_patient_registration.last_name::text AS patientname,    t_patient_registration.mobile_number,    t_patient_details.address,    t_encounter_master.encounter_number,    t_encounter_master.encounter_date,    m_billing_master.bill_number,    m_billing_master.bill_date_time,    (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,    m_doctor_master.first_name,    m_doctor_master.last_name,    m_billing_master.total_bill_amount,    m_billing_master.discount_amount,    m_billing_master.net_amount,    m_service_master.service_standard_name AS new_visit_service,    m_service_master_1.service_standard_name AS followup_visit_service,    m_service_master_2.service_standard_name AS second_visit_service,    m_doctor_master.doctor_id,    (m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,    m_user_master.user_id,    t_encounter_master.unit_id,    unitinformation.unit_name,    unitinformation.unit_address,    unitinformation.unit_address_2,    patientinformation.age,    patientinformation.gender_name,    t_encounter_master.encounter_time,    m_service_master.service_master_id AS new_visit_service_id,    m_service_master_1.service_master_id AS followup_visit_service_id   FROM patient.t_patient_registration     JOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_id     JOIN opd.t_encounter_master ON t_patient_details.patient_id = t_encounter_master.patient_id     JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_encounter_master.doctor_id     JOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_id     JOIN billing.t_payment_reciept_master ON m_billing_master.billing_master_id = t_payment_reciept_master.billing_master_id     JOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = t_encounter_master.doctor_id     JOIN service.m_service_master ON m_doctor_consultation_service_mapper.new_visit_service_id = m_service_master.service_master_id     JOIN service.m_service_master m_service_master_1 ON m_doctor_consultation_service_mapper.followup_visit_service_id = m_service_master_1.service_master_id     JOIN service.m_service_master m_service_master_2 ON m_doctor_consultation_service_mapper.secondary_visit_service_id = m_service_master_2.service_master_id     LEFT JOIN m_user_master ON m_user_master.user_id = m_billing_master.created_by     LEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_id     LEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_id     JOIN patient.patientinformation ON t_encounter_master.patient_id = patientinformation.patient_id  WHERE m_billing_master.visit_type_id = 1;

-- "Reports".grouptoal source
CREATE MATERIALIZED VIEW "Reports".grouptoalTABLESPACE pg_defaultAS SELECT trandate,    row_to_json(grouptoal.*) AS subspeclity   FROM ( SELECT get_groupwisetotal.trandate,            get_groupwisetotal.speciality_name,            get_groupwisetotal.sub_speciality_name,            sum(get_groupwisetotal.netsum) AS amount           FROM "Reports".get_groupwisetotal          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name, get_groupwisetotal.sub_speciality_name) grouptoalWITH NO DATA;

-- "Reports".image_groupwiserevenucount source
CREATE OR REPLACE VIEW "Reports".image_groupwiserevenucountAS SELECT bm.bill_date_time::date AS bill_date_time,    sp.speciality_id,    sp.speciality_name,    ssp.sub_speciality_id,    ssp.sub_speciality_name,    sum(bd.gross_amount - bd.discount) AS net_amt,    count(bm.patient_id) AS patient_id,    bm.unit_id,    bm.bill_cancelled,    row_number() OVER (ORDER BY (bm.bill_date_time::date)) AS serialno,    um.unit_name,    um.unit_address,    bm.organisation_id   FROM billing.m_billing_master bm     JOIN billing.t_billing_details bd ON bd.billing_master_id = bm.billing_master_id     JOIN service.m_service_master sm ON bd.service_id = sm.service_master_id     JOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_id     JOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_id     JOIN unitinformation um ON bm.unit_id = um.unit_id     JOIN billing.t_payment_reciept_master pr ON bm.billing_master_id = pr.billing_master_id     JOIN billing.t_payment_reciept_details rd ON pr.payment_reciept_id = rd.payment_receipt_master_id  WHERE bm.organisation_id = 10 AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_status_id = 3  GROUP BY (bm.bill_date_time::date), sp.speciality_id, sp.speciality_name, ssp.sub_speciality_id, ssp.sub_speciality_name, bm.unit_id, bm.bill_cancelled, um.unit_name, um.unit_address, bm.organisation_id;

-- "Reports".investigationslip source
CREATE OR REPLACE VIEW "Reports".investigationslipAS SELECT DISTINCT t_order_master.order_id,    t_order_master.order_date,    t_order_master.order_no,    t_order_details.order_details_id,    t_order_details.order_qty,    m_service_master.service_standard_name,    prefix.prefix_id,    pim.uhid_number,    concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,    gm.gender_name,    pim.bar_code,    age(pim.dob) AS age,    pim.mobile_number,    pim.email,    pim.mobile_number AS patientmobile,    pim.email AS patientemail,    ''::character varying AS reg_type,    gm.gender_name AS patientgender,    ''::character varying(200) AS patient_category,    pim.created_date AS regdate,    pim.is_vip,    pim.dob AS patientdob,    pim.identification_number,    pim.identification_expiry_date,    pd.address AS patientaddress,    pd.zip_code,    pim.mobile_number::character varying(100) AS phone_number,    pim.patient_id,    ''::character varying(100) AS marital_status_name,    m_unit_master.unit_id,    m_unit_master.unit_name,    m_unit_master.unit_address,    m_unit_master.unit_address_2,    m_unit_master.unit_email_id,    m_unit_master.unit_logo,    m_unit_master.post_code,    m_unit_master.unit_contact,    m_unit_master.unit_contact_2,    m_unit_master.unit_contact_3,    m_unit_master.unit_country_code,    m_unit_master.registration_number,    m_unit_master.unit_website,    cm.currency_name,    cm.sub_currency,    COALESCE(t_order_details.ord_cancelled, 'N'::character varying::bpchar) AS ord_cancelled,    dm.doctor_id,    concat('Dr.', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) AS doctorname,    ''::character varying(100) AS docgender,    ''::character varying(200) AS doctor_category_description,    m_speciality_master.speciality_name AS docspeciality,    0 AS docage,    ''::text AS docdob,    0 AS country_calling_code,    0 AS docmobile,    ''::text AS docemail,    ''::text AS doctor_image,    dm.registration_number AS docreg,    ''::text AS slot_time_span,    ''::text AS doctor_episod_time_span,    t_encounter_master.encounter_id,    m_speciality_master.speciality_id,    m_speciality_master.speciality_name AS groupname,    t_order_master.created_by,    t_order_details.created_by AS dtlscreated_by,    m_service_master.speciality_id AS groupid,    t_order_details.is_investigation_order,    t_order_details.order_date AS orddetaildate,    t_order_details.order_sch_date,    m_unit_master.image,    date_part('Year'::text, age(CURRENT_TIMESTAMP, pim.dob::timestamp with time zone))::integer AS ageyear   FROM t_order_master     JOIN t_order_details ON t_order_master.order_id = t_order_details.order_id AND t_order_master.visit_type_id = 1     LEFT JOIN opd.t_encounter_master ON t_order_master.encounter_id = t_encounter_master.encounter_id     JOIN patient.t_patient_registration pim ON t_order_master.patient_id = pim.patient_id     JOIN patient.t_patient_details pd ON pd.patient_id = pim.patient_id     JOIN m_prefix_master prefix ON prefix.prefix_id = pim.prefix_id     JOIN m_gender_master gm ON gm.gender_id = pim.gender_id     LEFT JOIN service.m_service_master ON t_order_details.service_id = m_service_master.service_master_id     LEFT JOIN m_unit_master ON t_order_master.org_unit_id = m_unit_master.unit_id     LEFT JOIN m_currency_master cm ON cm.unit_id = m_unit_master.unit_id     LEFT JOIN doctor.m_doctor_master dm ON t_encounter_master.doctor_id = dm.doctor_id     LEFT JOIN doctor.m_speciality_master ON m_service_master.speciality_id = m_speciality_master.speciality_id     JOIN service.t_unit_service_mapper service_mppr ON service_mppr.service_id = t_order_details.service_id AND service_mppr.unit_id = t_order_details.org_unit_id     JOIN service.t_unit_service_master_details service_dtls ON service_dtls.service_master_id = service_mppr.service_id AND service_dtls.unit_id = t_order_details.org_unit_id  WHERE t_order_details.is_investigation_order = 'Y'::bpchar AND m_service_master.status = 'A'::bpchar AND t_order_details.old_ord_dtl_id IS NULL AND service_dtls.is_package = 'I'::bpchar;

-- "Reports".loyaltycard source
CREATE OR REPLACE VIEW "Reports".loyaltycardAS SELECT m_loyalty_card.loyalty_card_id,    t_patient_loyalty_card_mppr.is_deleted,    t_patient_loyalty_card_mppr.is_verified,    m_loyalty_card.card_no,    patientinformation.uhid_number,    patientinformation.patientname   FROM t_patient_loyalty_card_mppr     JOIN m_loyalty_card ON t_patient_loyalty_card_mppr.loyalty_card_id = m_loyalty_card.loyalty_card_id     LEFT JOIN patient.patientinformation ON m_loyalty_card.patient_id = patientinformation.patient_id  WHERE t_patient_loyalty_card_mppr.is_deleted = 'N'::bpchar;

-- "Reports".nabh_nursing source
CREATE OR REPLACE VIEW "Reports".nabh_nursingAS SELECT DISTINCT t_patient_registration.prefix_id,    t_patient_registration.uhid_number,    (((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,    m_gender_master.gender_name,    age(t_patient_registration.dob) AS age,    t_patient_registration.mobile_number,    t_patient_registration.patient_id,    t_admission.admission_id,    um.unit_address_2,    um.unit_address,    um.unit_name,    abs(date_part('Year'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    abs(date_part('month'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,    abs(date_part('Day'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,    ((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,    ((('Dr.'::text || ' '::text) || dmt.first_name::text) || ' '::text) || dmt.last_name::text AS doctornametreating,    t_admission.admission_number,    t_admission.created_date,    m_bed_master.bed_desc,    ((('Dr.'::text || ' '::text) || refdoctor.first_name::text) || ' '::text) || refdoctor.last_name::text AS refdoctor,    wm.ward_name   FROM patient.t_patient_registration     LEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_id     LEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_id     JOIN adt.t_admission ON t_patient_registration.patient_id = t_admission.patient_id     LEFT JOIN patientinformation patinfo ON t_patient_registration.patient_id = patinfo.patient_id     JOIN m_unit_master um ON um.unit_id = t_admission.unit_id     LEFT JOIN doctor.m_doctor_master dm ON t_admission.admitting_doctor_id = dm.doctor_id     LEFT JOIN doctor.m_doctor_master dmt ON t_admission.doctor_id = dmt.doctor_id     JOIN adt.t_admission_details ON t_admission.admission_id = t_admission_details.admission_id     LEFT JOIN adt.m_bed_master ON t_admission_details.bed_id = m_bed_master.bed_id     LEFT JOIN opd.t_consult_doctor cd ON t_admission.admission_id = cd.admission_id     LEFT JOIN doctor.m_doctor_master refdoctor ON cd.ref_to_doctor_id = refdoctor.doctor_id     LEFT JOIN adt.m_ward_master wm ON t_admission_details.ward_id = wm.ward_id  WHERE t_admission_details.admission_details_id = (( SELECT t_admission_details_1.admission_details_id           FROM adt.t_admission_details t_admission_details_1          WHERE t_admission_details_1.admission_id = t_admission.admission_id          ORDER BY t_admission_details_1.admission_details_id DESC         LIMIT 1));
-- "Reports".paymentsnew source
CREATE MATERIALIZED VIEW "Reports".paymentsnewTABLESPACE pg_defaultAS SELECT row_to_json(detaillist.*) AS payment,    grtotal.detaillist1 AS revenue,    detaillist2.ptcount AS patientcount,    detaillist.trandate   FROM ( SELECT bi_finaltotalnew.trandate,            sum(bi_finaltotalnew.totalcash) AS cash,            sum(bi_finaltotalnew.cheque) AS cheque,            sum(bi_finaltotalnew.creditcard) AS creditcard,            sum(bi_finaltotalnew.debitcard) AS debitcard,            sum(bi_finaltotalnew.online) AS online           FROM "Reports".bi_finaltotalnew          GROUP BY bi_finaltotalnew.trandate) detaillist     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,            detaillist1.trandate           FROM ( SELECT pay.trandate,                    sum(pay.lab) AS lab,                    sum(pay.radiology) AS radilogy                   FROM ( SELECT get_groupwisetotal.trandate,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'LAB'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS lab,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'RADIOLOGY'::text THEN sum(get_groupwisetotal.netsum)                                    ELSE NULL::double precision                                END AS radiology                           FROM "Reports".get_groupwisetotal                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name) pay                  GROUP BY pay.trandate) detaillist1) grtotal ON grtotal.trandate = detaillist.trandate     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,            ptcount.trandate           FROM ( SELECT ptcounts.created_date AS trandate,                    COALESCE(sum(ptcounts.op), 0::numeric) AS op,                    COALESCE(sum(ptcounts.ip), 0::numeric) AS ip,                    COALESCE(sum(ptcounts.male), 0::numeric) AS male,                    COALESCE(sum(ptcounts.female), 0::numeric) AS female                   FROM ( SELECT bi_collection_new.created_date,                                CASE                                    WHEN bi_collection_new.type = 'OP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS op,                                CASE                                    WHEN bi_collection_new.type = 'IP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS ip,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Male'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS male,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Female'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS female,                            bi_collection_new.organization_id,                            bi_collection_new.unit_id,                            bi_collection_new.ptcount                           FROM "Reports".bi_collection_new) ptcounts                  GROUP BY ptcounts.created_date) ptcount) detaillist2 ON detaillist2.trandate = detaillist.trandateWITH NO DATA;

-- "Reports".paymentsnewmonths source
CREATE MATERIALIZED VIEW "Reports".paymentsnewmonthsTABLESPACE pg_defaultAS SELECT row_to_json(detaillist.*) AS payment,    grtotal.detaillist1 AS revenue,    detaillist2.ptcount AS patientcount,    detaillist.trandate   FROM ( SELECT to_char(bi_finaltotalnew.trandate::timestamp with time zone, 'Month,YY'::text) AS trandate,            sum(bi_finaltotalnew.totalcash) AS cash,            sum(bi_finaltotalnew.cheque) AS cheque,            sum(bi_finaltotalnew.creditcard) AS creditcard,            sum(bi_finaltotalnew.debitcard) AS debitcard,            sum(bi_finaltotalnew.online) AS online           FROM "Reports".bi_finaltotalnew          GROUP BY (to_char(bi_finaltotalnew.trandate::timestamp with time zone, 'Month,YY'::text))) detaillist     JOIN ( SELECT row_to_json(detaillist1.*) AS detaillist1,            detaillist1.trandate           FROM ( SELECT pay.trandate,                    sum(pay.lab) AS lab,                    sum(pay.radiology) AS radilogy                   FROM ( SELECT to_char(get_groupwisetotal.trandate::timestamp with time zone, 'Month,YY'::text) AS trandate,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'LAB'::text THEN COALESCE(sum(get_groupwisetotal.netsum), 0::double precision)                                    ELSE NULL::double precision                                END AS lab,                                CASE                                    WHEN get_groupwisetotal.speciality_name::text = 'RADIOLOGY'::text THEN COALESCE(sum(get_groupwisetotal.netsum), 0::double precision)                                    ELSE NULL::double precision                                END AS radiology                           FROM "Reports".get_groupwisetotal                          GROUP BY get_groupwisetotal.trandate, get_groupwisetotal.speciality_name) pay                  GROUP BY pay.trandate) detaillist1) grtotal ON grtotal.trandate = detaillist.trandate     JOIN ( SELECT row_to_json(ptcount.*) AS ptcount,            ptcount.trandate           FROM ( SELECT to_char(ptcounts.created_date::timestamp with time zone, 'Month,YY'::text) AS trandate,                    COALESCE(sum(ptcounts.op), 0::numeric) AS op,                    COALESCE(sum(ptcounts.ip), 0::numeric) AS ip,                    COALESCE(sum(ptcounts.male), 0::numeric) AS male,                    COALESCE(sum(ptcounts.female), 0::numeric) AS female                   FROM ( SELECT bi_collection_new.created_date,                                CASE                                    WHEN bi_collection_new.type = 'OP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS op,                                CASE                                    WHEN bi_collection_new.type = 'IP'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS ip,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Male'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS male,                                CASE                                    WHEN bi_collection_new.gender_name::text = 'Female'::text THEN bi_collection_new.ptcount                                    ELSE NULL::bigint                                END AS female,                            bi_collection_new.organization_id,                            bi_collection_new.unit_id,                            bi_collection_new.ptcount                           FROM "Reports".bi_collection_new) ptcounts                  GROUP BY (to_char(ptcounts.created_date::timestamp with time zone, 'Month,YY'::text))) ptcount) detaillist2 ON detaillist2.trandate = detaillist.trandateWITH NO DATA;

-- "Reports".prescription_dischargemedicine source
CREATE OR REPLACE VIEW "Reports".prescription_dischargemedicineAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,    age(pr.dob)::interval(6) AS age,    gm.gender_name,    pr.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pr.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pd.address AS patientaddress,    pr.mobile_number,    pr.dob AS patientdob,    abs(date_part('Year'::text, age(to_char(pr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,    em.admission_id,    presdtl.is_discharge_medication,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.issue_quantity            ELSE tidd.issue_quantity        END AS issue_quantity,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tb.batch_no            ELSE tbb.batch_no        END AS batch_no,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tb.expiry_date            ELSE tbb.expiry_date        END AS expiry_date,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.rate            ELSE tidd.rate        END AS rate,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.tax_percentage            ELSE tidd.tax_percentage        END AS tax_percentage,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.tax_amount            ELSE tidd.tax_amount        END AS tax_amount,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.total_amount            ELSE tidd.total_amount        END AS total_amount,        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.net_amount            ELSE tidd.net_amount        END AS net_amount,    em.admission_number,    tid.issue_id,    prefredtl.prescription_detail_id   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN pharmacy.t_issue_detail tid ON tid.prescription_detail_id = presdtl.id     LEFT JOIN pharmacy.t_issue_detail tidd ON tidd.parent_issue_detail_id = tid.id     LEFT JOIN inventory.t_batch tb ON tid.batch_id = tb.id     LEFT JOIN inventory.t_batch tbb ON tidd.batch_id = tbb.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     JOIN patient.t_patient_registration pr ON pr.patient_id = pres.patient_id     JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_id     JOIN m_gender_master gm ON gm.gender_id = pr.gender_id     LEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_active = true AND presdtl.is_deleted = false AND presdtl.is_discharge_medication = true AND        CASE            WHEN tidd.parent_issue_detail_id IS NULL THEN tid.issue_quantity            ELSE tidd.issue_quantity        END IS NOT NULL;

-- "Reports".prescriptioncasesheet source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheetAS SELECT DISTINCT 0 AS srno,    concat(pr.prefix_desc, '', pinfo.first_name, ' ', pinfo.middle_name, ' ', pinfo.last_name) AS patientname,    age(pinfo.dob) AS age,    gm.gender_name,    pinfo.uhid_number,    em.encounter_number AS visitnumber,    em.encounter_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",        CASE            WHEN presdtl.item_id IS NULL THEN presdtl.item_name            ELSE itm.name        END::character varying(500) AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    concat(instr.instruction_desc, ' ', presdtl.instruction_desc::character varying)::character varying(100) AS "instructionDesc",        CASE            WHEN gen.id IS NULL THEN presdtl.generic_name            ELSE gen.name        END::character varying(500) AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    tpd.address AS patientaddress,    pinfo.mobile_number,    pinfo.dob AS patientdob,    abs(date_part('Year'::text, age(pinfo.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,    laginstrc.instruction_desc,    laginstrc.converted_text,    COALESCE(laginstrc.language_id, 1) AS language_id,    presdtl.id AS detailid,    um.unit_website,    presdtl.duration,    presdtl.duration_unit,    instr.instruction_desc AS "Instr_instruction",    presdtl.instruction_desc AS presc_instruction   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     LEFT JOIN t_translated_instruction laginstrc ON instr.instruction_id = laginstrc.instruction_id AND laginstrc.status = 'A'::bpchar     JOIN patient.t_patient_registration pinfo ON pinfo.patient_id = pres.patient_id     JOIN m_prefix_master pr ON pr.prefix_id = pinfo.prefix_id     LEFT JOIN m_gender_master gm ON gm.gender_id = pinfo.gender_id     LEFT JOIN patient.t_patient_details tpd ON tpd.patient_id = pinfo.patient_id     LEFT JOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_active = true AND presdtl.is_deleted = false AND presdtl.status_id &lt;&gt; 9  ORDER BY presdtl.id;

-- "Reports".prescriptioncasesheet_easyemr source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheet_easyemrAS SELECT DISTINCT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    concat(pr.prefix_desc, '', pinfo.first_name, ' ', pinfo.middle_name, ' ', pinfo.last_name) AS patientname,    age(pinfo.dob) AS age,    gm.gender_name,    pinfo.uhid_number,    em.encounter_number AS visitnumber,    em.encounter_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    COALESCE(itm.name, presdtl.item_name) AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",        CASE            WHEN presdtl.instruction_desc IS NULL THEN instr.instruction_desc::text            ELSE presdtl.instruction_desc        END::character varying(250) AS "instructionDesc",    COALESCE(gen.name, presdtl.generic_name) AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    tpd.address AS patientaddress,    pinfo.mobile_number,    pinfo.dob AS patientdob,    abs(date_part('Year'::text, age(pinfo.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,        CASE            WHEN presdtl.instruction_id IS NULL THEN presdtl.instruction_desc::character varying            ELSE instr.instruction_desc        END AS instruction_desc,    laginstrc.converted_text,    COALESCE(laginstrc.language_id, 1) AS language_id,    msm.speciality_id,    msm.speciality_name,    ( SELECT array_to_string(ARRAY( SELECT m_degree_master.degree_desc                   FROM doctor.t_doctor_doc_mapper                     JOIN m_degree_master ON m_degree_master.degree_id = t_doctor_doc_mapper.degree_id                  WHERE t_doctor_doc_mapper.doctor_id = em.doctor_id AND t_doctor_doc_mapper.status = 'A'::bpchar), ', '::text) AS array_to_string) AS doc_degree,    qm.qualification_desc,    presdtl.duration,    em.follow_up_date   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     LEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id AND instr.status = 'A'::bpchar     LEFT JOIN t_translated_instruction laginstrc ON instr.instruction_id = laginstrc.instruction_id AND laginstrc.status = 'A'::bpchar     JOIN patient.t_patient_registration pinfo ON pinfo.patient_id = pres.patient_id     JOIN m_prefix_master pr ON pr.prefix_id = pinfo.prefix_id     LEFT JOIN m_gender_master gm ON gm.gender_id = pinfo.gender_id     LEFT JOIN patient.t_patient_details tpd ON tpd.patient_id = pinfo.patient_id     JOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id     LEFT JOIN doctor.m_speciality_master msm ON msm.speciality_id = em.dept_id     LEFT JOIN m_qualification_master qm ON dm.qualification_id = qm.qualification_id  WHERE presdtl.is_active = true AND presdtl.is_deleted = false AND pres.status_id &lt;&gt; 9;

-- "Reports".prescriptioncasesheet_handover source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheet_handoverAS SELECT DISTINCT 0 AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,        CASE            WHEN pres.visit_type_id = 1 THEN em.encounter_number            ELSE adm.admission_number        END AS visitnumber,        CASE            WHEN pres.visit_type_id = 1 THEN em.encounter_date            ELSE adm.created_date        END AS visitdate,    um.unit_id,    um.unit_name,    um.unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",        CASE            WHEN COALESCE(presdtl.instruction_id, 0) = 0 THEN presdtl.instruction_desc::character varying            ELSE instr.instruction_desc        END AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    laginstrc.instruction_desc,    laginstrc.converted_text,    laginstrc.language_id,    ts.id AS saleid   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     LEFT JOIN t_translated_instruction laginstrc ON instr.instruction_id = laginstrc.instruction_id AND laginstrc.status = 'A'::bpchar     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     LEFT JOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_id     LEFT JOIN adt.t_admission adm ON adm.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id     JOIN pharmacy.t_sale ts ON ts.prescription_id = pres.id     JOIN pharmacy.t_sale_detail tsd ON tsd.sale_id = ts.id AND tsd.prescription_detail_id = presdtl.id  WHERE presdtl.is_active = true AND presdtl.is_deleted = false;

-- "Reports".prescriptioncasesheet_ipdonly source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheet_ipdonlyAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,    em.admission_id,    presdtl.instruction_desc::character varying(250) AS instruction_desc,    laginstrc.converted_text,    COALESCE(laginstrc.language_id, 1) AS language_id,    presdtl.is_non_formulary,    pres.id AS presid,    presdtl.id AS detailid,    um.unit_website   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id AND presdtl.status_id &lt;&gt; 9     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     LEFT JOIN t_translated_instruction laginstrc ON instr.instruction_id = laginstrc.instruction_id AND laginstrc.status = 'A'::bpchar     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_non_formulary = 'N'::bpchar AND presdtl.is_active = true AND pres.status_id &lt;&gt; 9;

-- "Reports".prescriptioncasesheet_ipdonlynonformulary source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheet_ipdonlynonformularyAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY presdtl.item_name) AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    presdtl.item_name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    ''::text AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    0::boolean AS is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,    em.admission_id,    laginstrc.instruction_desc,    laginstrc.converted_text,    laginstrc.language_id,    presdtl.is_non_formulary,    pres.id AS presid   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id AND presdtl.status_id &lt;&gt; 9     LEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     LEFT JOIN t_translated_instruction laginstrc ON instr.instruction_id = laginstrc.instruction_id AND laginstrc.status = 'A'::bpchar     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_non_formulary = 'Y'::bpchar;

-- "Reports".prescriptioncasesheet_svc source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheet_svcAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    concat(pr.prefix_desc, '', pinfo.first_name, ' ', pinfo.last_name) AS patientname,    age(pinfo.dob) AS age,    gm.gender_name,    pinfo.uhid_number,    em.encounter_number AS visitnumber,    em.encounter_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    COALESCE(itm.name, presdtl.item_name) AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",        CASE            WHEN presdtl.instruction_desc IS NULL THEN instr.instruction_desc::text            ELSE presdtl.instruction_desc        END::character varying(250) AS "instructionDesc",    COALESCE(gen.name, presdtl.generic_name) AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    tpd.address AS patientaddress,    pinfo.mobile_number,    pinfo.dob AS patientdob,    abs(date_part('Year'::text, age(pinfo.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.unit_website,    um.image,    dm.doctor_id,        CASE            WHEN presdtl.instruction_id IS NULL THEN presdtl.instruction_desc::character varying            ELSE instr.instruction_desc        END AS instruction_desc,    ''::character varying(250) AS converted_text,    1 AS language_id,    msm.speciality_id,    msm.speciality_name,    ( SELECT array_to_string(ARRAY( SELECT m_degree_master.degree_desc                   FROM doctor.t_doctor_doc_mapper                     JOIN m_degree_master ON m_degree_master.degree_id = t_doctor_doc_mapper.degree_id                  WHERE t_doctor_doc_mapper.doctor_id = em.doctor_id AND t_doctor_doc_mapper.status = 'A'::bpchar), ', '::text) AS array_to_string) AS doc_degree,    qm.qualification_desc,    presdtl.duration,    em.follow_up_date,    presdtl.duration_unit,    presdtl.id AS presdtl_id,    presdtl.status_id,    presdtl.is_non_formulary,    presdtl.id AS detailid,    pinfo.patient_remark   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     LEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     LEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id AND instr.status = 'A'::bpchar     LEFT JOIN patient.t_patient_registration pinfo ON pinfo.patient_id = pres.patient_id     JOIN m_prefix_master pr ON pr.prefix_id = pinfo.prefix_id     LEFT JOIN m_gender_master gm ON gm.gender_id = pinfo.gender_id     LEFT JOIN patient.t_patient_details tpd ON tpd.patient_id = pinfo.patient_id     JOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id     LEFT JOIN doctor.m_speciality_master msm ON msm.speciality_id = em.dept_id     LEFT JOIN m_qualification_master qm ON dm.qualification_id = qm.qualification_id  WHERE presdtl.is_active = true AND presdtl.is_deleted = false AND pres.status_id &lt;&gt; 9  ORDER BY presdtl.id DESC;

-- "Reports".prescriptioncasesheetdetails source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheetdetailsAS SELECT DISTINCT 0 AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.encounter_number AS visitnumber,    em.encounter_date AS visitdate,    um.unit_id,    um.unit_name,    um.unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     JOIN m_item itm ON itm.id = presdtl.item_id     JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     JOIN m_generic gen ON itm.generic_id = gen.id     JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_medication_stop = 'N'::bpchar AND presdtl.is_active = true AND pres.status_id &lt;&gt; 9UNION SELECT DISTINCT 0 AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.admission_id AS encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     JOIN m_item itm ON itm.id = presdtl.item_id     JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     JOIN m_generic gen ON itm.generic_id = gen.id     JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_medication_stop = 'N'::bpchar AND presdtl.is_active = true AND pres.status_id &lt;&gt; 9;

-- "Reports".prescriptioncasesheetipd source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheetipdAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.admission_id   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     JOIN m_item itm ON itm.id = presdtl.item_id     JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     JOIN m_generic gen ON itm.generic_id = gen.id     JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_active = true AND pres.status_id &lt;&gt; 9;

-- "Reports".prescriptioncasesheetnew_ipd source
CREATE OR REPLACE VIEW "Reports".prescriptioncasesheetnew_ipdAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,    pinfo.patientname,    pinfo.age,    pinfo.gender_name,    pinfo.uhid_number,    em.admission_number AS visitnumber,    em.created_date AS visitdate,    um.unit_id,    um.unit_name,    um.image AS unit_logo,    um.unit_address,    um.organization_id,    presdtl.item_id AS "itemId",    itm.name AS "itemName",    prefredtl.dose AS "doseDesc",    su.unit AS "strengthDesc",    prefredtl.frequency_id AS "frequencyId",    freq.description AS "frequencyDesc",    prefredtl.route_id AS "roaId",    presdtl.statflag,    roa.description AS "roaDesc",    prefredtl.start_date AS startdate,    prefredtl.stop_date AS enddate,    presdtl.instruction_id AS "instructionId",    instr.instruction_desc AS "instructionDesc",    gen.name AS "genericName",    pres.encounter_id,    presdtl.order_qty AS qty,    (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,    dm.registration_number,    pinfo.patient_id,    um.unit_address_2,    pres.id,    pres.prescription_no,    pres.prescription_date,    pinfo.patientaddress,    pinfo.mobile_number,    pinfo.patientdob,    abs(date_part('Year'::text, age(pinfo.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,    presdtl.is_medication_stop,    presdtl.updated_date,    presdtl.justification_stop,    pres.visit_type_id,    itm.is_narcotic,    um.unit_contact,    um.unit_email_id,    um.image,    dm.doctor_id,    em.admission_id,    presdtl.is_discharge_medication   FROM pharmacy.t_prescription pres     JOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.id     JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.id     JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.id     LEFT JOIN m_item itm ON itm.id = presdtl.item_id     LEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_id     LEFT JOIN m_generic gen ON itm.generic_id = gen.id     LEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_id     LEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_id     JOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_id     JOIN adt.t_admission em ON em.admission_id = pres.admission_id     JOIN m_unit_master um ON um.unit_id = pres.unit_id     LEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_id  WHERE presdtl.is_active = true AND pres.status_id &lt;&gt; 9;-- DROP SCHEMA abdm;
