-- adt.admissionpaper source
CREATE OR REPLACE VIEW adt.admissionpaperAS SELECT t_admission.admission_number,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS admissionunder,t_admission.created_date AS admissiondate,m_speciality_master.speciality_name,m_ward_master.ward_name,m_room_master.room_desc,m_bed_master.bed_number,m_bed_category_master.bed_category_desc,((((m_prefix_master.prefix_desc || '. '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || t_patient_registration.last_name::text AS patientname,m_gender_master.gender_name,t_admission_details.admission_id,m_meal_preference_master.meal_preference_desc,m_admission_type_master.admission_type_desc,t_patient_registration.uhid_number,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_logo,m_unit_master.unit_name,t_patient_registration.dob,age(t_patient_registration.dob) AS age,t_patient_details.address,m_billing_bed_category_master.billing_bed_desc,t_admission.status,m_organization_master.organization_contact,m_organization_master.organization_email_id,m_unit_wise_logo.imgFROM adt.t_admissionLEFT JOIN adt.t_admission_details ON t_admission.admission_id = t_admission_details.admission_idLEFT JOIN adt.m_ward_master ON t_admission_details.ward_id = m_ward_master.ward_idLEFT JOIN adt.m_room_master ON t_admission_details.room_id = m_room_master.room_idLEFT JOIN adt.m_bed_master ON t_admission_details.bed_id = m_bed_master.bed_idLEFT JOIN doctor.m_doctor_master ON t_admission.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master ON t_admission.speciality_id = m_speciality_master.speciality_idLEFT JOIN adt.m_bed_category_master ON t_admission_details.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN patient.t_patient_registration ON t_admission.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN adt.m_billing_bed_category_master ON t_admission_details.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_meal_preference_master ON t_admission_details.meal_pref_id = m_meal_preference_master.meal_preference_idLEFT JOIN adt.m_admission_type_master ON t_admission.visit_type_id = m_admission_type_master.admission_type_idLEFT JOIN m_organization_master ON t_admission_details.organization_id = m_organization_master.organization_idLEFT JOIN m_unit_master ON t_admission_details.unit_id = m_unit_master.unit_idLEFT JOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idLEFT JOIN m_unit_wise_logo ON m_unit_master.unit_id = m_unit_wise_logo.unitid;

-- adt.admpaper source
CREATE OR REPLACE VIEW adt.admpaperAS SELECT DISTINCT t_admission.admission_id,t_admission_details.doa,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,prefix.prefix_id,pr.uhid_number,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,''::character varying AS bar_code,age(pr.dob) AS age,pr.mobile_number,pr.email,pr.mobile_number AS patientmobile,pr.email AS patientemail,''::character varying AS reg_type,gm.gender_name AS patientgender,''::character varying(200) AS patient_category,pr.created_date AS regdate,1::character(1) AS is_vip,pr.dob AS patientdob,''::character varying AS identification_number,pr.created_date AS identification_expiry_date,pd.address AS patientaddress,pd.zip_code,pr.mobile_number::character varying(100) AS phone_number,pr.patient_id,''::character varying(100) AS marital_status_name,t_admission.admission_number,t_admission.status,m_admission_type_master.admission_type_desc,m_ward_master.ward_name,m_room_master.room_desc,m_bed_master.bed_number AS bed_desc,m_bed_category_master.bed_category_desc,m_billing_bed_category_master.billing_bed_desc,m_meal_preference_master.meal_preference_desc,m_floor_master.floor_name,t_admission_details.is_short_leave,t_admission_details.is_discharge,t_admission_details.is_cancel,(((m_prefix_master.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS cancelby,t_admission_details.cancel_date,t_admission_details.is_close,t_admission_details.remark,t_admission_details.is_high_risk,t_admission_details.is_critical,t_admission_details.pdd,t_admission_details.is_medico_legal,t_admission_details.is_transfer_of_care,concat('Dr.', m_doctor_master.first_name, ' ', m_doctor_master.last_name) AS doctorname,m_speciality_master.speciality_name,rm.relation_name,concat(kinprefix.prefix_desc, ' ', kd.kin_name)::character varying AS kin_name,kd.mobile_no AS kinmobileno,kd.address AS kinaddress,t_admission.created_date AS admissiondate,unitinformation.image,t_company_master.company_desc,t_patient_sponsor_details.payee_id,mlc.fir_no,mlc.mlc_contact_no,mlc.police_buckle_no,mlc.police_station_name,mlc.remark AS mlcremarks,mlc.accompanied_by,mlc.created_date AS mlcdate,relation.relation_name AS mlcrelationname,unitinformation.image AS hospitalimage,m_refferel.referral_name,((('Dr.'::text || ' '::text) || admittingdoctor.first_name::text) || ' '::text) || admittingdoctor.last_name::text AS admdoctorname,abs(date_part('Year'::text, age(to_char(pr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,dist.district_name,COALESCE(city.city_name, ''::character varying)::character varying(50) AS city_name,prefix.prefix_desc,pr.dob,concat(prefix.prefix_desc, '', pr.first_name)::character varying AS first_name,pr.last_name,t_patient_sponsor_details.payment_entitlement_id,sp.speciality_name AS admittingingdoctor_specialityFROM adt.t_admissionJOIN adt.t_admission_details ON t_admission.admission_id = t_admission_details.admission_idJOIN m_unit_master unitinformation ON t_admission.unit_id = unitinformation.unit_idJOIN patient.t_patient_registration pr ON t_admission.patient_id = pr.patient_idJOIN patient.t_patient_details pd ON pr.patient_id = pd.patient_idLEFT JOIN m_district_master dist ON pd.district_id = dist.district_idLEFT JOIN m_city_master city ON pd.city_id = city.city_idLEFT JOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idJOIN m_gender_master gm ON pr.gender_id = gm.gender_idJOIN doctor.m_doctor_master ON t_admission.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_doctor_master admittingdoctor ON t_admission.admitting_doctor_id = admittingdoctor.doctor_idLEFT JOIN adt.m_admission_type_master ON t_admission_details.admission_type_id = m_admission_type_master.admission_type_idLEFT JOIN adt.m_ward_master ON t_admission_details.ward_id = m_ward_master.ward_idLEFT JOIN adt.m_room_master ON t_admission_details.room_id = m_room_master.room_idLEFT JOIN adt.m_bed_master ON t_admission_details.bed_id = m_bed_master.bed_idLEFT JOIN adt.m_bed_category_master ON t_admission_details.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN adt.m_billing_bed_category_master ON t_admission_details.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_meal_preference_master ON t_admission_details.meal_pref_id = m_meal_preference_master.meal_preference_idLEFT JOIN adt.m_floor_master ON t_admission_details.floor_id = m_floor_master.floor_idJOIN m_user_master umc ON t_admission.created_by = umc.user_idLEFT JOIN m_employee_master ON umc.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master ON m_employee_master.prefix_id = m_prefix_master.prefix_idLEFT JOIN doctor.m_speciality_master ON t_admission.speciality_id = m_speciality_master.speciality_idLEFT JOIN m_kin_details kd ON kd.patient_id = t_admission.patient_id AND kd.status = 'A'::bpcharLEFT JOIN m_relation_master rm ON kd.relation_id = rm.relation_idLEFT JOIN m_prefix_master kinprefix ON kd.prefix_id = kinprefix.prefix_idLEFT JOIN opd.t_patient_sponsor_details ON t_admission.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master ON t_patient_sponsor_details.payee_id = t_company_master.company_idLEFT JOIN m_payment_entitlement_master payentitle ON payentitle.payment_entitlement_id = t_patient_sponsor_details.payment_entitlement_idLEFT JOIN adt.t_medico_legal mlc ON t_admission.admission_id = mlc.admission_idLEFT JOIN m_relation_master relation ON mlc.mlc_relation_id = relation.relation_idLEFT JOIN t_referal_details admreff ON t_admission.admission_id = admreff.admission_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN doctor.m_speciality_master sp ON t_admission.admitting_speciality_id = sp.speciality_idWHERE t_patient_sponsor_details.status = 'A'::bpchar AND t_admission_details.admission_details_id = (( SELECT t_admission_details_1.admission_details_idFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = t_admission.admission_idORDER BY t_admission_details_1.admission_details_id DESCLIMIT 1))ORDER BY t_admission.admission_id, t_admission_details.doa;

-- adt.get_patient_transfer_details source
CREATE OR REPLACE VIEW adt.get_patient_transfer_detailsAS SELECT pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS p_name,bcm1.bed_category_desc AS from_bed_category,COALESCE(bcm2.bed_category_desc, '--'::text) AS to_bed_category,tsm.transfer_status_desc,COALESCE(bbcm1.billing_bed_desc, '--'::character varying) AS from_billing_bed_category,COALESCE(bbcm2.billing_bed_desc, '--'::character varying) AS to_billing_bed_category,COALESCE(wm1.ward_name, '--'::character varying) AS from_ward,COALESCE(wm2.ward_name, '--'::character varying) AS to_ward,COALESCE(rm1.room_desc, '--'::text) AS from_room,COALESCE(rm2.room_desc, '--'::text) AS to_room,COALESCE(bm1.bed_number, '--'::character varying) AS from_bed,COALESCE(bm2.bed_number, '--'::character varying) AS to_bed,t.created_date,t.updated_date,u.unit_name,u.unit_address,u.unit_contact,wm1.ward_id AS fromward_id,wm2.ward_id AS toward_id,tsm.transfer_status_id,u.unit_id,u.image,ttr.created_date AS requestdate,ttr.transfer_request_id,t.transfer_idFROM adt.t_transfer tJOIN adt.t_admission a ON t.admission_id = a.admission_idJOIN patient.t_patient_registration pr ON a.patient_id = pr.patient_idLEFT JOIN adt.m_bed_category_master bcm1 ON t.from_bed_category_id = bcm1.bed_category_idLEFT JOIN adt.m_bed_category_master bcm2 ON t.to_bed_category_id = bcm2.bed_category_idLEFT JOIN adt.m_billing_bed_category_master bbcm1 ON t.from_billing_bed_category_id = bbcm1.billing_bed_category_idLEFT JOIN adt.m_billing_bed_category_master bbcm2 ON t.from_billing_bed_category_id = bbcm2.billing_bed_category_idLEFT JOIN adt.m_ward_master wm1 ON t.from_ward_id = wm1.ward_idLEFT JOIN adt.m_ward_master wm2 ON t.to_ward_id = wm2.ward_idLEFT JOIN adt.m_room_master rm1 ON t.from_room_id = rm1.room_idLEFT JOIN adt.m_room_master rm2 ON t.to_room_id = rm2.room_idLEFT JOIN adt.m_bed_master bm1 ON t.from_bed_id = bm1.bed_idLEFT JOIN adt.m_bed_master bm2 ON t.to_bed_id = bm2.bed_idJOIN m_unit_master u ON t.unit_id = u.unit_idLEFT JOIN adt.t_transfer_request ttr ON ttr.transfer_request_id = t.transfer_request_idLEFT JOIN adt.m_transfer_status_master tsm ON t.transfer_status_id = tsm.transfer_status_idORDER BY t.transfer_id;-- DROP FUNCTION adt.get_admission_analysis(date);
CREATE OR REPLACE FUNCTION adt.get_admission_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, admission_id integer, admission_date date, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_medico_legal character, is_high_risk character)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select a.unit_id,a.organization_id,a.patient_id,a.admission_id,ad.doa::date as admission_date,a.visit_type_id,a.speciality_id,a.doctor_id,apm.payment_entitlement_id,extract(year from age(pr.dob))::integer as patient_age,pr.gender_id,ad.is_medico_legal,ad.is_high_riskfrom adt.t_admission ajoin adt.t_admission_details ad using (admission_id)join adt.t_admission_patient_mapping apm on (a.patient_id = apm.admission_patient_id)join patient.t_patient_registration pr using(patient_id)where ((a.updated_date::date &gt;= p_date ::date and a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::date and a.created_date::date &lt; current_date))group by a.unit_id,a.organization_id,a.patient_id,a.admission_id,ad.doa,apm.payment_entitlement_id,pr.dob,pr.gender_id,ad.is_medico_legal,ad.is_high_risk;end;$function$;

-- DROP FUNCTION adt.get_discharge_analysis(date);
CREATE OR REPLACE FUNCTION adt.get_discharge_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, admission_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, discharge_type_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_medico_legal character, is_high_risk character)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select d.unit_id,d.organization_id,a.patient_id,d.admission_id,d.visit_type_id,a.speciality_id,d.doctor_id,d.discharge_type_id,apm.payment_entitlement_id,extract(year from age(pr.dob))::integer as patient_age,pr.gender_id,ad.is_medico_legal,ad.is_high_riskfrom adt.t_admission ajoin adt.t_discharge d using (admission_id)join adt.t_admission_details ad using (admission_id)join adt.t_admission_patient_mapping apm on (a.patient_id = apm.admission_patient_id)join patient.t_patient_registration pr using(patient_id)where ((d.updated_date::date &gt;= p_date ::date and d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::date and d.created_date::date &lt; current_date))group by d.unit_id,d.organization_id,a.patient_id,d.admission_id,ad.doa,d.visit_type_id,apm.payment_entitlement_id,a.speciality_id,pr.dob,d.doctor_id,pr.gender_id,ad.is_medico_legal,d.discharge_type_id,ad.is_high_risk;end;$function$;

