-- assets.get_asset_opbalance source
CREATE OR REPLACE VIEW assets.get_asset_opbalanceAS SELECT ob.id,ob.opb_no,ob.added_date,ob.unit_id,m_store.store_name,mstatus.status,concat(em.first_name, ' ', em.last_name) AS empaddedby,concat(emapp.first_name, ' ', emapp.last_name) AS empapprovby,ob.approved_date,m_item.name AS itemname,obd.quantity,obd.serial_number,obd.remark,obd.warranty_from,obd.warranty_to,frequency.description,obd.year_of_manufacture,vendor.name AS vendor,unit.unit_name,unit.unit_addressFROM inventory.t_opening_balance obJOIN inventory.t_opening_balance_detail obd ON ob.id = obd.opening_balance_idJOIN m_store ON ob.store_id = m_store.store_idLEFT JOIN m_status mstatus ON ob.status_id = mstatus.idLEFT JOIN m_user_master usermaster ON ob.added_by = usermaster.user_idLEFT JOIN m_employee_master em ON usermaster.user_id = em.user_idLEFT JOIN m_user_master usermasterapprov ON ob.approved_by = usermasterapprov.user_idLEFT JOIN m_employee_master emapp ON usermaster.user_id = emapp.user_idJOIN m_item ON obd.item_id = m_item.idLEFT JOIN inventory.m_pms_frequency frequency ON obd.pms_frequency_id = frequency.idLEFT JOIN m_vendor vendor ON obd.vendor_id = vendor.idJOIN unitinformation unit ON ob.unit_id = unit.unit_id;-- DROP SCHEMA billing;
