-- billing.creditnotes source
CREATE OR REPLACE VIEW billing.creditnotesAS SELECT DISTINCT cnm.credit_note_id,cnm.credit_note_date,cnm.bill_id AS crditnoteagainst,cnm.cr_total_amount,cnm.cr_tax_amount,cnm.cr_net_amount,cnm.cr_deu_amount,cnm.credit_note_remark AS ce_remark,cnm.cancel_or_discount,om.organization_desc,om.organization_address,om.organization_logo,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,curm.currency_name,curm.sub_currency,cnm.created_date,cnm.credit_note_no,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(reg.first_name, ''::character varying), ' ', COALESCE(reg.middle_name, ''::character varying), ' ', COALESCE(reg.last_name, ''::character varying)) AS patientname,reg.uhid_number,gm.gender_name,age(reg.dob) AS age,reg.mobile_number,bm.bill_number,sm.service_standard_name,(em.first_name::text || ' '::text) || em.last_name::text AS username,bdm.rate,bdm.quantity,bdm.net_amt,bm.visit_type_id,m_visit_type_master.visit_type_name,cnd.cr_tax_amount AS detail_cr_tax_amount,cnd.cr_discount_amount,cnd.cr_additional_discount,bdm.gross_amount,cnd.cr_net_amount AS cr_net_amount_details,um.image,cnd.credit_note_detail_id,cnm.cr_reason_id,rm.reason_desc,usm.user_id,cnm.statusFROM billing.m_credit_note_master cnmLEFT JOIN billing.t_credit_note_detail cnd ON cnm.credit_note_id = cnd.credit_note_idLEFT JOIN billing.m_billing_master bm ON cnm.bill_id = bm.billing_master_idLEFT JOIN patient.t_patient_registration reg ON bm.patient_id = reg.patient_idLEFT JOIN m_prefix_master pm ON reg.prefix_id = pm.prefix_idLEFT JOIN m_gender_master gm ON reg.gender_id = gm.gender_idLEFT JOIN m_organization_master om ON cnm.organisation_id = om.organization_idLEFT JOIN m_unit_master um ON cnm.unit_id = um.unit_idLEFT JOIN m_currency_master curm ON curm.unit_id = um.unit_idLEFT JOIN m_user_master usm ON cnm.created_by = usm.user_idLEFT JOIN m_employee_master em ON usm.user_id = em.user_idLEFT JOIN billing.t_billing_details bdm ON cnd.billing_details_id = bdm.billing_details_idLEFT JOIN service.m_service_master sm ON bdm.service_id = sm.service_master_idLEFT JOIN billing.t_credit_note_discount_detail cndd ON cnd.billing_details_id = cndd.credit_note_detail_idLEFT JOIN t_company_master tcm ON cnm.bill_payee_id = tcm.company_idLEFT JOIN m_prefix_master upm ON em.prefix_id = upm.prefix_idLEFT JOIN adt.m_reason_master rm ON rm.reason_master_id = cnm.cr_reason_idLEFT JOIN m_visit_type_master ON bm.visit_type_id = m_visit_type_master.visit_type_id;

-- billing.dashboard_collection source
CREATE OR REPLACE VIEW billing.dashboard_collectionAS WITH cte AS (SELECT sum(dd.amount) AS collection,dm.deposit_no AS receiptno,dd.trans_transaction_date AS trandate,vm.visit_type_id,vm.visit_type_name,pmm.payment_mode_id,pmm.payment_mode_desc,dm.unit_id,COALESCE(entitle_op.payment_entitlement_id, entitle_ip.payment_entitlement_id, 0) AS payment_entitlement_id,COALESCE(entitle_op.payment_entitlement_desc, entitle_ip.payment_entitlement_desc, 'Self'::text) AS payment_entitlement_descFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idLEFT JOIN m_visit_type_master vm ON dm.visit_type_id = vm.visit_type_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = dm.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = dm.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master entitle_op ON entitle_op.payment_entitlement_id = spd.payment_entitlement_idLEFT JOIN m_payment_entitlement_master entitle_ip ON entitle_ip.payment_entitlement_id = spdip.payment_entitlement_idWHERE pmm.payment_mode_id &lt;&gt; 10 AND dd.amount &lt;&gt; 0::double precisionGROUP BY dm.deposit_no, dd.trans_transaction_date, vm.visit_type_id, vm.visit_type_name, pmm.payment_mode_id, pmm.payment_mode_desc, dm.unit_id, entitle_op.payment_entitlement_id, entitle_ip.payment_entitlement_idUNIONSELECT sum(prd.amount) AS collection,rm.reciept_number AS receiptno,prd.date_of_transaction AS trandate,vm.visit_type_id,vm.visit_type_name,pmm.payment_mode_id,pmm.payment_mode_desc,prd.unit_id,entitle.payment_entitlement_id,entitle.payment_entitlement_descFROM billing.m_billing_master bmJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN billing.t_payment_reciept_master rm ON bm.billing_master_id = rm.billing_master_idJOIN billing.t_payment_reciept_details prd ON rm.payment_reciept_id = prd.payment_receipt_master_idJOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idLEFT JOIN billing.m_transaction_type_master trantype ON trantype.transaction_type_id = prd.transaction_type_idJOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.status = 'A'::"char" AND bpd.priority_id = 1LEFT JOIN m_payment_entitlement_master entitle ON entitle.payment_entitlement_id = bpd.payment_entitlement_idWHERE COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar AND COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar AND (bm.bill_status_id = ANY (ARRAY[2, 3])) AND pmm.payment_mode_id &lt;&gt; 10GROUP BY rm.reciept_number, prd.date_of_transaction, vm.visit_type_id, vm.visit_type_name, pmm.payment_mode_id, pmm.payment_mode_desc, prd.unit_id, entitle.payment_entitlement_id, entitle.payment_entitlement_desc)SELECT collection,receiptno,trandate,visit_type_id,visit_type_name,payment_mode_id,payment_mode_desc,unit_id,payment_entitlement_id,payment_entitlement_descFROM cte;

-- billing.dashboard_revenue source
CREATE OR REPLACE VIEW billing.dashboard_revenueAS WITH cte AS (SELECT DISTINCT bm.billing_master_id,sum(bd.net_amt) AS net,bm.bill_date_time AS date,bm.unit_id,bm.visit_type_id,vm.visit_type_code::character varying(255) AS visit_type_name,sp.speciality_id AS dept_id,sp.speciality_name AS department,cm.company_id,cm.company_desc,dm.doctor_id,concat(dm.first_name, ' ', dm.last_name) AS doctor,entitle.payment_entitlement_id,entitle.payment_entitlement_desc,CASEWHEN bm.visit_type_id = 1 THEN doc_sp_opd.speciality_idELSE doc_sp_ipd.speciality_idEND AS doc_sp_id,CASEWHEN bm.visit_type_id = 1 THEN doc_sp_opd.speciality_nameELSE doc_sp_ipd.speciality_nameEND AS doc_sp_name,CASEWHEN bm.visit_type_id = 1 THEN doc_opd.doctor_idELSE doc_ipd.doctor_idEND AS doc_id,CASEWHEN bm.visit_type_id = 1 THEN concat(doc_opd.first_name, ' ', doc_opd.last_name)ELSE concat(doc_ipd.first_name, ' ', doc_ipd.last_name)END AS doc_nameFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON od.order_details_id = bd.order_details_idJOIN m_visit_type_master vm ON vm.visit_type_id = bm.visit_type_idJOIN service.m_service_master sm ON sm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = sm.speciality_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master en ON en.encounter_id = bm.encounter_idLEFT JOIN doctor.m_speciality_master doc_sp_ipd ON doc_sp_ipd.speciality_id = ta.admitting_speciality_idLEFT JOIN doctor.m_speciality_master doc_sp_opd ON doc_sp_opd.speciality_id = en.dept_idJOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.status = 'A'::"char" AND bpd.priority_id = 1LEFT JOIN m_payment_entitlement_master entitle ON entitle.payment_entitlement_id = bpd.payment_entitlement_idLEFT JOIN t_company_master cm ON cm.company_id = bpd.payee_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = od.ord_doc_idLEFT JOIN doctor.m_doctor_master doc_ipd ON doc_ipd.doctor_id = ta.admitting_doctor_idLEFT JOIN doctor.m_doctor_master doc_opd ON doc_opd.doctor_id = en.doctor_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND od.ord_cancelled = 'N'::bpcharGROUP BY bm.billing_master_id, bm.bill_date_time, bm.unit_id, bm.visit_type_id, vm.visit_type_code, sp.speciality_id, sp.speciality_name, cm.company_id, cm.company_desc, dm.doctor_id, dm.first_name, dm.last_name, entitle.payment_entitlement_id, entitle.payment_entitlement_desc, doc_sp_ipd.speciality_id, doc_sp_ipd.speciality_name, doc_sp_opd.speciality_id, doc_sp_opd.speciality_name, doc_opd.doctor_id, doc_ipd.doctor_idUNIONSELECT DISTINCT ts.id,sum(ts.net_amount) AS net,ts.added_date AS date,ts.unit_id,vm.visit_type_id,vm.visit_type_code::character varying(255) AS visit_type_name,0 AS dept_id,'PHARMACY'::character varying AS department,COALESCE(cm.company_id, cmip.company_id) AS company_id,COALESCE(cm.company_desc, cmip.company_desc::character varying) AS company_desc,COALESCE(dm.doctor_id, t_temp_doctor.id) AS doctor_id,CASEWHEN dm.doctor_id IS NULL THEN t_temp_doctor.doctor_name::textELSE (dm.first_name::text || ' '::text) || dm.last_name::textEND AS doctor,0 AS payment_entitlement_id,'PHARMACY'::text AS payment_entitlement_desc,0 AS doc_sp_id,'PHARMACY'::text AS doc_sp_name,0 AS doc_id,CASEWHEN dm.doctor_id IS NULL THEN t_temp_doctor.doctor_name::textELSE (dm.first_name::text || ' '::text) || dm.last_name::textEND AS doc_nameFROM pharmacy.t_sale tsLEFT JOIN m_visit_type_master vm ON vm.visit_type_id = ts.visit_type_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = ts.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = ts.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN t_company_master cm ON cm.company_id = spd.payee_idLEFT JOIN t_company_master cmip ON cmip.company_id = spdip.payee_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = ts.temp_doctor_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = ts.doctor_idWHERE ts.is_active = trueGROUP BY ts.id, ts.unit_id, ts.added_date, vm.visit_type_id, vm.visit_type_code, cm.company_id, cmip.company_id, cm.company_desc, cmip.company_desc, dm.doctor_id, t_temp_doctor.id, t_temp_doctor.doctor_name)SELECT net,date,unit_id,visit_type_id,visit_type_name,dept_id,department,company_id,company_desc,doctor_id,doctor,payment_entitlement_id,payment_entitlement_desc,doc_sp_id,doc_sp_name,doc_id,doc_nameFROM cte;

-- billing.debitnotes source
CREATE OR REPLACE VIEW billing.debitnotesAS SELECT t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_gender_master.gender_name AS pentientgender,age(t_patient_registration.dob) AS age,m_billing_master.billing_master_id,m_billing_master.bill_number,m_billing_master.bill_date_time,m_billing_master.net_amount,m_billing_master.discount_amount,m_billing_master.concession_amount,m_billing_master.gst,m_billing_master.total_bill_amount,m_billing_master.outstanding,m_billing_master.round_off,m_billing_master.bill_cancelled,t_billing_details.rate,t_billing_details.quantity,t_billing_details.concession,t_billing_details.gross_amount,m_service_master.service_standard_name,m_organization_master.organization_name,m_organization_master.organization_address,m_billing_master.dr_note_against_billid,( SELECT bm.bill_numberFROM billing.m_billing_master bmWHERE bm.billing_master_id = m_billing_master.dr_note_against_billid) AS againstbillno,(((um.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS user_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.encounter_id,doctorinformation.speciality_id,t_billing_details.ord_doc_id,m_billing_master.visit_type_id,m_visit_type_master.visit_type_name,t_billing_details.tax_per,t_billing_details.tax_amount,t_billing_details.net_amt,t_billing_details.discount AS dtlsdiscount,unitinformation.imageFROM billing.m_billing_masterLEFT JOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idLEFT JOIN opd.t_encounter_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idLEFT JOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN patient.t_patient_registration ON t_encounter_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_user_master ON m_billing_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master um ON m_employee_master.prefix_id = um.prefix_idLEFT JOIN doctor.doctorinformation ON m_billing_master.encounter_id = doctorinformation.encounter_idLEFT JOIN m_visit_type_master ON m_billing_master.visit_type_id = m_visit_type_master.visit_type_idWHERE m_billing_master.is_dr_note = 'Y'::bpchar AND m_billing_master.bill_cancelled = 'N'::bpchar AND m_billing_master.visit_type_id = 1UNION ALLSELECT t_patient_registration.uhid_number,(((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,m_gender_master.gender_name AS pentientgender,age(t_patient_registration.dob) AS age,m_billing_master.billing_master_id,m_billing_master.bill_number,m_billing_master.bill_date_time,m_billing_master.net_amount,m_billing_master.discount_amount,m_billing_master.concession_amount,m_billing_master.gst,m_billing_master.total_bill_amount,m_billing_master.outstanding,m_billing_master.round_off,m_billing_master.bill_cancelled,t_billing_details.rate,t_billing_details.quantity,t_billing_details.concession,t_billing_details.gross_amount,m_service_master.service_standard_name,m_organization_master.organization_name,m_organization_master.organization_address,m_billing_master.dr_note_against_billid,( SELECT bm.bill_numberFROM billing.m_billing_master bmWHERE bm.billing_master_id = m_billing_master.dr_note_against_billid) AS againstbillno,(((um.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS user_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.admission_id AS encounter_id,doctorinformation.speciality_id,t_billing_details.ord_doc_id,m_billing_master.visit_type_id,m_visit_type_master.visit_type_name,t_billing_details.tax_per,t_billing_details.tax_amount,t_billing_details.net_amt,t_billing_details.discount AS dtlsdiscount,unitinformation.imageFROM billing.m_billing_masterLEFT JOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idLEFT JOIN adt.t_admission ON m_billing_master.admission_id = t_admission.admission_idLEFT JOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN patient.t_patient_registration ON t_admission.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_user_master ON m_billing_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master um ON m_employee_master.prefix_id = um.prefix_idLEFT JOIN doctor.doctorinformationipd doctorinformation ON m_billing_master.admission_id = doctorinformation.admission_idLEFT JOIN m_visit_type_master ON m_billing_master.visit_type_id = m_visit_type_master.visit_type_idWHERE m_billing_master.is_dr_note = 'Y'::bpchar AND m_billing_master.bill_cancelled = 'N'::bpchar AND (m_billing_master.visit_type_id = ANY (ARRAY[2, 3]));
-- billing.departmentwise_opandip source
CREATE OR REPLACE VIEW billing.departmentwise_opandipAS SELECT 1 AS srno,'Consultation'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND bd.package_consumption_amt = 0::double precisionGROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 2 AS srno,'OP Lab'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = 1GROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 2 AS srno,'OP Lab'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = 2GROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 3 AS srno,'PHARMACY'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_id,'OP Pharmacy'::character varying AS dept,CASEWHEN ts.visit_type_id IS NULL THEN 1ELSE ts.visit_type_idEND AS visit_type_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_id, ts.visit_type_idUNIONSELECT 4 AS srno,'OP Revenue'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND bd.package_consumption_amt = 0::double precisionGROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 4 AS srno,'OP Revenue'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = 1GROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 4 AS srno,'OP Revenue'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,spp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_speciality_master spp ON en.dept_id = spp.speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = 2GROUP BY sp.speciality_name, spp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT 4 AS srno,'OP Revenue'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_id,'OP Pharmacy'::character varying AS dept,CASEWHEN ts.visit_type_id IS NULL THEN 1ELSE ts.visit_type_idEND AS visit_type_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_id, ts.visit_type_idUNIONSELECT 5 AS srno,'IP Revenue'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,docsp.speciality_name AS dept,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN doctor.m_speciality_master sp ON bd.ord_doc_spl_id = sp.speciality_idJOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN doctor.m_speciality_master docsp ON ta.speciality_id = docsp.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.visit_type_id &lt;&gt; 1GROUP BY docsp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idORDER BY 1;

-- billing.departmentwise_pathology source
CREATE OR REPLACE VIEW billing.departmentwise_pathologyAS SELECT DISTINCT 0 AS srno,ssp.sub_speciality_name::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = (( SELECT tlc.lab_speciality_idFROM t_lab_configuration tlcWHERE tlc.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idUNIONSELECT DISTINCT 0 AS srno,ssp.sub_speciality_name::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,bm.visit_type_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND msm.speciality_id = (( SELECT tlc.lab_speciality_idFROM t_lab_configuration tlcWHERE tlc.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_idORDER BY 2;

