CREATE OR REPLACE VIEW billing.departmentwise_pathology_countAS SELECT 0 AS srno,ssp.sub_speciality_name::text AS lebel,count(bd.service_id) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON od.order_details_id = bd.order_details_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND od.ord_cancelled = 'N'::bpchar AND msm.speciality_id = (( SELECT t_lab_configuration.lab_speciality_idFROM t_lab_configurationWHERE t_lab_configuration.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 0 AS srno,ssp.sub_speciality_name::text AS lebel,count(bd.service_id) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON od.order_details_id = bd.order_details_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND od.ord_cancelled = 'N'::bpchar AND msm.speciality_id = (( SELECT t_lab_configuration.lab_speciality_idFROM t_lab_configurationWHERE t_lab_configuration.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_idORDER BY 2;

