ent_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND msm.speciality_id = 2 AND pmop.payment_entitlement_id = 3 AND psd.payee_id &lt;&gt; 39 AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,'CORPORATE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idJOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND msm.speciality_id = 2 AND pmop.payment_entitlement_id = 3 AND psd.payee_id &lt;&gt; 39 AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 4 AS srno,'Dr.YSR AAROGYASRI'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idJOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND msm.speciality_id = 2 AND pmop.payment_entitlement_id = 3 AND psd.payee_id = 39 AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 4 AS srno,'Dr.YSR AAROGYASRI'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idJOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND msm.speciality_id = 2 AND pmop.payment_entitlement_id = 3 AND psd.payee_id = 39 AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idORDER BY 1;

-- billing.departmentwise_radiology_count source
CREATE OR REPLACE VIEW billing.departmentwise_radiology_countAS SELECT 0 AS srno,ssp.sub_speciality_name::text AS lebel,count(bd.service_id) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND msm.speciality_id = (( SELECT uab.radiology_speciality_idFROM t_unit_application_billing_configuration uabWHERE uab.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 0 AS srno,ssp.sub_speciality_name::text AS lebel,count(bd.service_id) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_sub_speciality_master ssp ON msm.sub_speciality_id = ssp.sub_speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND msm.speciality_id = (( SELECT uab.radiology_speciality_idFROM t_unit_application_billing_configuration uabWHERE uab.unit_id = bm.unit_id))GROUP BY ssp.sub_speciality_name, (bm.bill_date_time::date), bm.unit_idORDER BY 2;

-- billing.departmentwise_revenue source
CREATE OR REPLACE VIEW billing.departmentwise_revenueAS SELECT 0 AS srno,sp.speciality_name::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,bm.visit_type_id,sp.speciality_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON od.order_details_id = bd.order_details_idJOIN opd.t_encounter_master en ON bm.encounter_id = en.encounter_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND od.ord_cancelled = 'N'::bpcharGROUP BY sp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_id, sp.speciality_idUNION ALLSELECT 0 AS srno,sp.speciality_name::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_id,bm.visit_type_id,sp.speciality_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON od.order_details_id = bd.order_details_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN adt.t_admission ta ON ta.admission_id = bm.admission_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idWHERE od.ord_cancelled = 'N'::bpchar AND bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.visit_type_id &lt;&gt; 1GROUP BY sp.speciality_name, (bm.bill_date_time::date), bm.unit_id, bm.visit_type_id, sp.speciality_idORDER BY 2;

-- billing.deposit source
