ture,m_deposit_master.signeture_image,t_payment_deposit_details.transaction_no,unitinformation.image,m_deposit_master.admission_idFROM billing.m_deposit_masterLEFT JOIN opd.t_encounter_master ON t_encounter_master.encounter_id = m_deposit_master.encounter_idLEFT JOIN billing.t_payment_deposit_details ON m_deposit_master.deposit_master_id = t_payment_deposit_details.deposit_idLEFT JOIN m_payment_mode_master ON t_payment_deposit_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON t_payment_deposit_details.bank_id = m_bank_master.bank_idLEFT JOIN billing.m_card_type_master ON t_payment_deposit_details.card_type_id = m_card_type_master.card_type_idLEFT JOIN m_user_master ON m_deposit_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pum ON m_employee_master.prefix_id = pum.prefix_idLEFT JOIN patient.patientinformation ON m_deposit_master.patient_id = patientinformation.patient_idLEFT JOIN billing.m_deposite_type_master ON m_deposit_master.deposit_type_id = m_deposite_type_master.deposite_type_idLEFT JOIN m_visit_type_master ON m_deposit_master.visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN m_unit_master unitinformation ON m_deposit_master.unit_id = unitinformation.unit_idLEFT JOIN m_organization_master ON m_deposit_master.org_id = m_organization_master.organization_idWHERE m_deposit_master.visit_type_id = 1GROUP BY m_deposit_master.deposit_master_id, m_deposit_master.created_date, m_payment_mode_master.payment_mode_desc, m_organization_master.organization_name, unitinformation.unit_id, unitinformation.unit_name, unitinformation.unit_address, unitinformation.unit_address_2, unitinformation.unit_email_id, unitinformation.unit_logo, unitinformation.post_code, unitinformation.unit_contact, unitinformation.unit_contact_2, unitinformation.unit_contact_3, unitinformation.unit_country_code, unitinformation.registration_number