sion_idFROM billing.m_deposit_masterLEFT JOIN adt.t_admission ON t_admission.admission_id = m_deposit_master.admission_idLEFT JOIN billing.t_payment_deposit_details ON m_deposit_master.deposit_master_id = t_payment_deposit_details.deposit_idLEFT JOIN m_payment_mode_master ON t_payment_deposit_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON t_payment_deposit_details.bank_id = m_bank_master.bank_idLEFT JOIN billing.m_card_type_master ON t_payment_deposit_details.card_type_id = m_card_type_master.card_type_idLEFT JOIN m_user_master ON m_deposit_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pum ON m_employee_master.prefix_id = pum.prefix_idLEFT JOIN patient.patientinformation ON m_deposit_master.patient_id = patientinformation.patient_idLEFT JOIN billing.m_deposite_type_master ON m_deposit_master.deposit_type_id = m_deposite_type_master.deposite_type_idLEFT JOIN m_visit_type_master ON m_deposit_master.visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN unitinformation ON m_deposit_master.unit_id = unitinformation.unit_idLEFT JOIN m_organization_master ON m_deposit_master.org_id = m_organization_master.organization_idWHERE m_deposit_master.visit_type_id = 2ORDER BY m_deposit_master.deposit_master_id;

-- billing.getopdcross_consultation source
CREATE OR REPLACE VIEW billing.getopdcross_consultationAS SELECT DISTINCT bm.billing_master_id,bm.bill_date_time,pim.doctorname,en.doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_idFROM opd.t_encounter_master enJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = en.doctor_idJOIN billing.m_billing_master bm ON bm.encounter_id = en.encounter_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN doctor.m_doctor_master dm ON bd.ord_doc_id = dm.doctor_idJOIN m_patient_visit_metadata pim ON en.encounter_id = pim.encouter_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = en.doctor_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master sp ON en.dept_id = sp.speciality_idWHERE en.doctor_id &lt;&gt; bd.ord_doc_id AND bm.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.new_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND bm.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_date_time,pim.doctorname,en.doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_idFROM opd.t_encounter_master enJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = en.doctor_idJOIN billing.m_billing_master bm ON bm.encounter_id = en.encounter_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN doctor.m_doctor_master dm ON bd.ord_doc_id = dm.doctor_idJOIN m_patient_visit_metadata pim ON en.encounter_id = pim.encouter_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = en.doctor_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master sp ON en.dept_id = sp.speciality_idWHERE en.doctor_id &lt;&gt; bd.ord_doc_id AND bm.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.followup_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND bm.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_date_time,pim.doctorname,en.doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_idFROM opd.t_encounter_master enJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = en.doctor_idJOIN billing.m_billing_master bm ON bm.encounter_id = en.encounter_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN doctor.m_doctor_master dm ON bd.ord_doc_id = dm.doctor_idJOIN m_patient_visit_metadata pim ON en.encounter_id = pim.encouter_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = en.doctor_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master sp ON en.dept_id = sp.speciality_idWHERE en.doctor_id &lt;&gt; bd.ord_doc_id AND bm.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.secondary_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND bm.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,tod.ord_doc_id AS doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_idFROM adt.t_admission taJOIN billing.m_billing_master bm ON bm.admission_id = ta.admission_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details tod ON tod.order_details_id = bd.order_details_idJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = tod.ord_doc_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idLEFT JOIN doctor.m_speciality_master sp ON tod.ord_doc_spl_id = sp.speciality_idWHERE ta.doctor_id &lt;&gt; tod.ord_doc_id AND bm.visit_type_id = 2 AND bm.bill_cancelled = 'N'::bpchar AND m_service_master.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1));
