number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,t_payment_reciept_details.payment_mode_id,t_payment_reciept_details.amount AS paymentamount,m_bank_master.bank_name,t_payment_reciept_details.check_number,t_payment_reciept_details.cheque_date,t_payment_reciept_details.card_holder_name,t_payment_reciept_details.date_of_transaction,t_payment_reciept_details.card_number,t_payment_reciept_details.expiry_date,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,m_visit_type_master.visit_type_name,t_payment_reciept_details.transaction_no,unitinformation.image,transtype.transaction_type_name,deposit.consumed_amount,deposit.deposite_consumption_number,em.dept_id,concat(empprifix.prefix_desc, '', empprintgivenby.first_name, ' ', empprintgivenby.last_name) AS empprintgivenbyFROM billing.t_payment_reciept_masterLEFT JOIN billing.t_payment_reciept_details ON t_payment_reciept_master.payment_reciept_id = t_payment_reciept_details.payment_receipt_master_idLEFT JOIN billing.m_billing_master ON t_payment_reciept_master.billing_master_id = m_billing_master.billing_master_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = m_billing_master.encounter_idLEFT JOIN m_payment_mode_master ON t_payment_reciept_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN patient.t_patient_registration ON m_billing_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN billing.m_bank_master ON t_payment_reciept_details.bank_id = m_bank_master.bank_idLEFT JOIN m_user_master ON t_payment_reciept_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN m_visit_type_master ON m_billing_master.visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN billing.t_payment_deposite_consumption deposit ON m_billing_master.billing_master_id = deposit.bill_id AND deposit.status = 'A'::bpcharLEFT JOIN billing.m_transaction_type_master transtype ON t_payment_reciept_details.transaction_type_id = transtype.transaction_type_idLEFT JOIN m_user_master printgivenby ON t_payment_reciept_master.print_given_by = printgivenby.user_idLEFT JOIN m_employee_master empprintgivenby ON printgivenby.user_id = empprintgivenby.user_idLEFT JOIN m_prefix_master empprifix ON empprintgivenby.prefix_id = empprifix.prefix_idWHERE t_payment_reciept_master.status = 'A'::bpchar;

