ion.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,cm.currency_name,cm.sub_currency,t_payment_reciept_details.payment_mode_id,t_payment_reciept_details.amount AS paymentamount,m_bank_master.bank_name,t_payment_reciept_details.check_number,t_payment_reciept_details.cheque_date,t_payment_reciept_details.card_holder_name,t_payment_reciept_details.date_of_transaction,t_payment_reciept_details.card_number,t_payment_reciept_details.expiry_date,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,m_visit_type_master.visit_type_name,t_payment_reciept_details.transaction_no,unitinformation.image,transtype.transaction_type_name,deposit.consumed_amount,deposit.deposite_consumption_numberFROM billing.t_payment_reciept_masterLEFT JOIN billing.t_payment_reciept_details ON t_payment_reciept_master.payment_reciept_id = t_payment_reciept_details.payment_receipt_master_idLEFT JOIN billing.m_billing_master ON t_payment_reciept_master.billing_master_id = m_billing_master.billing_master_idLEFT JOIN m_payment_mode_master ON t_payment_reciept_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN patient.t_patient_registration ON m_billing_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN m_unit_master unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_currency_master cm ON cm.unit_id = unitinformation.unit_idLEFT JOIN billing.m_bank_master ON t_payment_reciept_details.bank_id = m_bank_master.bank_idLEFT JOIN m_user_master ON t_payment_reciept_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN m_visit_type_master ON m_billing_master.visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN billing.t_payment_deposite_consumption deposit ON m_billing_master.billing_master_id = deposit.bill_id AND deposit.status = 'A'::bpcharLEFT JOIN billing.m_transaction_type_master transtype ON t_payment_reciept_details.transaction_type_id = transtype.transaction_type_idWHERE t_payment_reciept_master.status = 'A'::bpchar;

-- billing.ipd_opd_doctorwiserevenue source
CREATE OR REPLACE VIEW billing.ipd_opd_doctorwiserevenueAS SELECT DISTINCT bm.bill_number,bm.bill_date_time,CASEWHEN bm.visit_type_id = 1 THEN opd.encounter_numberELSE adm.admission_numberEND AS opipnumber,pim.uhid_number,concat(pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,CASEWHEN dmipd.doctor_id IS NOT NULL THEN concat(dmipd.first_name, ' ', dmipd.last_name)WHEN dmopd.doctor_id IS NOT NULL THEN concat(dmopd.first_name, ' ', dmopd.last_name)ELSE 'Hospital'::textEND AS doctorname,CASEWHEN bm.visit_type_id = 1 THEN spopd.speciality_nameELSE spipd.speciality_nameEND AS department,dsp.speciality_name,dssp.sub_speciality_name,bd.gross_amount,COALESCE(bd.discount + bd.concession, 0::double precision) AS discount,bd.net_amt,bm.outstanding,um.unit_name,um.unit_address,bm.unit_id,COALESCE(bm.discount_amount + bm.concession_amount, 0::double precision) AS discount_amount,bm.total_bill_amount,bm.net_amount,bm.billing_master_id,0 AS amount,bm.bill_date_time AS date_of_transaction,bd.billing_details_id,CASEWHEN dmipd.doctor_id IS NULL THEN dmopd.doctor_idELSE dmipd.doctor_idEND AS doctor_id,dsp.speciality_id,''::character varying(1000) AS procedurename,adm.created_date AS doa,deposit.depositamount,deposit.consumed,cm.company_desc,CASEWHEN bm.visit_type_id = 1 THEN mrmopd.referral_nameELSE mrmipd.referral_nameEND AS referral_name,bm.visit_type_id,vm.visit_type_codeFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_id AND bd.status = 'A'::"char"JOIN t_order_details od ON bd.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master dsp ON sm.speciality_id = dsp.speciality_idJOIN doctor.m_sub_speciality_master dssp ON sm.sub_speciality_id = dssp.sub_speciality_idJOIN m_visit_type_master vm ON vm.visit_type_id = bm.visit_type_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master opd ON bm.encounter_id = opd.encounter_idJOIN patient.t_patient_registration pim ON bm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master dmipd ON adm.doctor_id = dmipd.doctor_idLEFT JOIN doctor.m_doctor_master dmopd ON opd.doctor_id = dmopd.doctor_idLEFT JOIN doctor.m_speciality_master spipd ON adm.speciality_id = spipd.speciality_idLEFT JOIN doctor.m_speciality_master spopd ON opd.dept_id = spopd.speciality_idJOIN m_unit_master um ON um.unit_id = bm.unit_idLEFT JOIN billing.t_bill_payee_details psd ON psd.bill_id = bm.billing_master_id AND psd.priority_id = 1 AND psd.status = 'A'::"char"LEFT JOIN t_company_master cm ON cm.company_id = psd.payee_idLEFT JOIN t_referal_details rdopd ON bm.encounter_id = rdopd.encounter_idLEFT JOIN t_referal_details rdipd ON bm.admission_id = rdipd.admission_idLEFT JOIN adt.m_referral_master mrmopd ON rdopd.referral_id = mrmopd.referral_idLEFT JOIN adt.m_referral_master mrmipd ON rdipd.referral_id = mrmipd.referral_idLEFT JOIN ( SELECT sum(mdm.deposit_amount) AS depositamount,sum(mdm.consumed_deposit) AS consumed,mdm.patient_idFROM billing.m_deposit_master mdmGROUP BY mdm.patient_id) deposit ON deposit.patient_id = bm.patient_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.status = 'A'::"char" AND bd.net_amt &lt;&gt; 0::double precisionORDER BY bm.billing_master_id;

-- billing.ipdintrimbiil source
CREATE OR REPLACE VIEW billing.ipdintrimbiilAS SELECT DISTINCT ordermaster.admission_id AS orderdadmission_id,orderdetails.created_date,orderdetails.order_details_id,orderdetails.service_id,patreg.prefix_id,patreg.uhid_number,patreg.patientname,patreg.gender_name,patreg.bar_code,patreg.age,patreg.mobile_number,patreg.email,patreg.patientmobile,patreg.patientemail,patreg.reg_type,patreg.patientgender,patreg.patient_category,patreg.regdate,patreg.is_vip,patreg.patientdob,patreg.identification_number,patreg.identification_expiry_date,patreg.patientaddress,patreg.zip_code,patreg.phone_number,patreg.patient_id,patreg.marital_status_name,ordermaster.order_no,orderdetails.order_qty,servicemaster.service_standard_name,servicemaster.service_standard_code,orderdetails.order_date,orderdetails.order_sch_date,orderdetails.service_amt,orderdetails.ord_concession,orderdetails.ord_discount,orderdetails.net_amount,orderdetails.tax_id,COALESCE(orderdetails.tax_per, 0::numeric) AS tax_per,orderdetails.tax_amount,COALESCE(orderdetails.self_payable, 0::numeric) AS self_payable,COALESCE(orderdetails.credit_payable, 0::numeric) AS credit_payable,orderdetails.service_rendered,orderdetails.service_chargeable,unitservic5_.discount_value,doctormaster.admission_id,doctormaster.doctor_id,doctormaster.doctorname,doctormaster.docgender,doctormaster.doctor_category_description,doctormaster.docspeciality,doctormaster.docage,doctormaster.docdob,doctormaster.country_calling_code,doctormaster.docmobile,doctormaster.docemail,doctormaster.doctor_image,doctormaster.docreg,doctormaster.slot_time_span,doctormaster.doctor_episod_time_span,doctormaster.speciality_id,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,m_organization_master.organization_address,m_organization_master.organization_contact,m_organization_master.organization_email_id,m_organization_master.organization_logo,m_organization_master.organization_desc,orderdetails.ord_cancelled,unitinformation.image,t_company_master.company_descFROM t_order_details orderdetailsLEFT JOIN t_order_master ordermaster ON orderdetails.order_id = ordermaster.order_idLEFT JOIN adt.t_admission adm ON adm.admission_id = ordermaster.admission_idLEFT JOIN patient.patientinformation patreg ON patreg.patient_id = adm.patient_idLEFT JOIN m_prefix_master prefix ON patreg.prefix_id = prefix.prefix_idLEFT JOIN service.m_service_master servicemaster ON orderdetails.service_id = servicemaster.service_master_idLEFT JOIN service.t_unit_service_master_details unitservic5_ ON servicemaster.service_master_id = unitservic5_.service_master_idLEFT JOIN doctor.doctorinformationipd doctormaster ON adm.admission_id = doctormaster.admission_idLEFT JOIN unitinformation ON adm.unit_id = unitinformation.unit_idLEFT JOIN m_organization_master ON adm.organization_id = m_organization_master.organization_idLEFT JOIN opd.t_patient_sponsor_details ON adm.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master ON t_patient_sponsor_details.payee_id = t_company_master.company_idWHERE orderdetails.service_is_billed = 0 AND orderdetails.service_rendered = 1 AND ordermaster.visit_type_id = 2 AND orderdetails.ord_cancelled = 'N'::bpcharORDER BY ordermaster.admission_id;

-- billing.ipdoctorwiserevenue source
CREATE OR REPLACE VIEW billing.ipdoctorwiserevenueAS SELECT DISTINCT bm.bill_number,bm.bill_date_time,adm.admission_number AS opipnumber,mp.uhid_number,mp.patientname,mp.doctorname,spipd.speciality_name AS department,dsp.speciality_name,dssp.sub_speciality_name,bd.gross_amount,COALESCE(bd.discount + bd.concession, 0::double precision) AS discount,bd.net_amt,bm.outstanding,mp.unit_name,mp.unit_address,bm.unit_id,COALESCE(bm.discount_amount + bm.concession_amount, 0::double precision) AS discount_amount,bm.total_bill_amount,bm.net_amount,bm.billing_master_id,0 AS amount,bm.bill_date_time AS date_of_transaction,bd.billing_details_id,dmipd.doctor_id,dsp.speciality_id,''::character varying(1000) AS procedurename,mp.doa,deposit.depositamount,deposit.consumed,mp.company_descFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_id AND bd.status = 'A'::"char"JOIN t_order_details od ON bd.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master dsp ON sm.speciality_id = dsp.speciality_idJOIN doctor.m_sub_speciality_master dssp ON sm.sub_speciality_id = dssp.sub_speciality_idJOIN adt.t_admission adm ON bm.admission_id = adm.admission_idJOIN m_patient_visit_metadata mp ON adm.admission_id = mp.admission_id AND mp.visit_type_id = 2JOIN patient.t_patient_registration pim ON bm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master dmipd ON adm.doctor_id = dmipd.doctor_idLEFT JOIN doctor.m_speciality_master spipd ON adm.speciality_id = spipd.speciality_idLEFT JOIN ( SELECT sum(mdm.deposit_amount) AS depositamount,sum(mdm.consumed_deposit) AS consumed,mdm.patient_idFROM billing.m_deposit_master mdmGROUP BY mdm.patient_id) deposit ON deposit.patient_id = bm.patient_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.status = 'A'::"char" AND bm.visit_type_id = 2ORDER BY bm.billing_master_id;

-- billing.op_ip_revenue source
CREATE OR REPLACE VIEW billing.op_ip_revenueAS SELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND bd.package_consumption_amt = 0::double precisionGROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_idUNIONSELECT 2 AS srno,'IP REVENUE'::text AS lebel,sum(bm.net_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,'General'::text AS lebel,sum(tbd.bill_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN billing.t_bill_payee_details tbd ON tbd.bill_id = bm.billing_master_id AND tbd.payee_id = 1WHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 4 AS srno,'Corporate'::text AS lebel,sum(tbd.bill_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar AND (psd.payee_id &lt;&gt; ALL (ARRAY[39, 42]))JOIN billing.t_bill_payee_details tbd ON tbd.bill_id = bm.billing_master_id AND tbd.payee_id &lt;&gt; 1LEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 5 AS srno,'Insurance'::text AS lebel,sum(tbd.bill_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar AND (psd.payee_id &lt;&gt; ALL (ARRAY[39, 42]))JOIN billing.t_bill_payee_details tbd ON tbd.bill_id = bm.billing_master_id AND tbd.payee_id &lt;&gt; 1LEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 2GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 6 AS srno,'Dr.YSR AAROGYASRI'::text AS lebel,sum(tbd.bill_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar AND psd.payee_id = 39JOIN billing.t_bill_payee_details tbd ON tbd.bill_id = bm.billing_master_id AND tbd.payee_id &lt;&gt; 1LEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 7 AS srno,'EHS'::text AS lebel,sum(tbd.bill_amount) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar AND psd.payee_id = 42JOIN billing.t_bill_payee_details tbd ON tbd.bill_id = bm.billing_master_id AND tbd.payee_id &lt;&gt; 1LEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idORDER BY 1;

-- billing.op_ip_revenue_summary source
