master msm ON msm.service_master_id = bd.service_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idORDER BY 1;

-- billing.opbilling_revenue source
CREATE OR REPLACE VIEW billing.opbilling_revenueAS SELECT 1 AS srno,'OP CONSULTATION'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND bd.package_consumption_amt = 0::double precisionGROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 2 AS srno,'General'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1, 3])) AND bd.package_consumption_amt = 0::double precision AND bm.bill_status_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,CASEWHEN pmop.payment_entitlement_desc = 'Self'::text THEN 'Cash'::textELSE NULL::textEND AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN billing.t_bill_payee_details tbpd ON tbpd.bill_id = bm.billing_master_id AND tbpd.payee_id = 1LEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1])) AND bd.package_consumption_amt = 0::double precisionGROUP BY pmop.payment_entitlement_desc, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,CASEWHEN pmop.payment_entitlement_desc = 'Company'::text THEN 'Corp Cash'::textELSE NULL::textEND AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN billing.t_bill_payee_details tbpd ON tbpd.bill_id = bm.billing_master_id AND tbpd.payee_id = 1LEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[3])) AND bd.package_consumption_amt = 0::double precision AND bm.bill_status_id = 3GROUP BY pmop.payment_entitlement_desc, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 4 AS srno,'Corporate Credit'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[2, 3])) AND bm.bill_status_id &lt;&gt; 3 AND bd.package_consumption_amt = 0::double precisionGROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 5 AS srno,'OP BILLING'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 6 AS srno,'General'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1, 3])) AND bm.bill_status_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 7 AS srno,CASEWHEN pmop.payment_entitlement_desc = 'Self'::text THEN 'Cash'::textELSE NULL::textEND AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1]))GROUP BY pmop.payment_entitlement_desc, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 7 AS srno,CASEWHEN pmop.payment_entitlement_desc = 'Company'::text THEN 'Corp Cash'::textELSE NULL::textEND AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[3])) AND bm.bill_status_id = 3GROUP BY pmop.payment_entitlement_desc, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 7 AS srno,'Corporate Credit'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[2, 3])) AND bm.bill_status_id &lt;&gt; 3GROUP BY pmop.payment_entitlement_desc, (bm.bill_date_time::date), bm.unit_idUNIONSELECT 8 AS srno,'OP Due Recovered'::text AS lebel,sum(tprd.amount) AS net,tprd.date_of_transaction::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN billing.t_payment_reciept_master tprm ON tprm.billing_master_id = bm.billing_master_idJOIN billing.t_payment_reciept_details tprd ON tprd.payment_receipt_master_id = tprm.payment_reciept_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_date_time::date &lt;&gt; tprd.date_of_transaction::date AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1, 2, 3]))GROUP BY (tprd.date_of_transaction::date), bm.unit_idUNIONSELECT 9 AS srno,'OP Refunded'::text AS lebel,sum(brdet.amount) AS net,brdet.created_date::date AS bill_date_time,brdet.unit_idFROM billing.t_payment_refund_details brdetJOIN billing.t_payment_refund_master bm ON bm.payment_refund_id = brdet.payment_refund_idJOIN billing.m_credit_note_master bcnid ON bm.credit_note_id = bcnid.credit_note_idJOIN billing.m_billing_master billmst ON billmst.billing_master_id = bcnid.bill_idWHERE billmst.visit_type_id = 1 AND bcnid.status = 'A'::bpcharGROUP BY brdet.unit_id, (brdet.created_date::date)UNIONSELECT 10 AS srno,'Corporate Credit'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND pmop.payment_entitlement_id = 2GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 11 AS srno,'OP PHARMACY'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_idUNIONSELECT 12 AS srno,'General'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.total_credit_payable = 0::double precision AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_idUNIONSELECT 13 AS srno,'Corporate'::text AS lebel,sum(tsd.net_amount) + sum(tsd.package_consumption_amt) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1 AND ts.total_credit_payable &lt;&gt; 0::double precisionGROUP BY (ts.added_date::date), ts.unit_idORDER BY 1;

-- billing.opbilling_revenue_summary source
CREATE OR REPLACE VIEW billing.opbilling_revenue_summaryAS SELECT 1 AS srno,'OP CONSULTATION'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND bd.package_consumption_amt = 0::double precisionGROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 2 AS srno,'OP BILLING'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,'OP PHARMACY'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_idORDER BY 1;

-- billing.opconsultation_revenue source
CREATE OR REPLACE VIEW billing.opconsultation_revenueAS SELECT 1 AS srno,'OP CONSULTATION'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_timeFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_date_time::date &gt;= '2021-09-11'::date AND bm.bill_date_time::date &lt;= '2021-09-11'::date AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date)UNIONSELECT 2 AS srno,'General'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_timeFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_date_time::date &gt;= '2021-09-11'::date AND bm.bill_date_time::date &lt;= '2021-09-11'::date AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1, 3])) AND bm.bill_status_id = 3GROUP BY bm.visit_type_id, (bm.bill_date_time::date)UNIONSELECT 3 AS srno,CASEWHEN pmop.payment_entitlement_desc = 'Self'::text THEN 'Cash'::textWHEN pmop.payment_entitlement_desc = 'Company'::text THEN 'Corp Cash'::textELSE pmop.payment_entitlement_descEND AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_timeFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_date_time::date &gt;= '2021-09-11'::date AND bm.bill_date_time::date &lt;= '2021-09-11'::date AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[1, 3])) AND bm.bill_status_id = 3GROUP BY bm.visit_type_id, pmop.payment_entitlement_desc, (bm.bill_date_time::date)UNIONSELECT 4 AS srno,'Corporate'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_timeFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_date_time::date &gt;= '2021-09-11'::date AND bm.bill_date_time::date &lt;= '2021-09-11'::date AND bm.visit_type_id = 1 AND (pmop.payment_entitlement_id = ANY (ARRAY[2, 3])) AND bm.bill_status_id &lt;&gt; 3GROUP BY bm.visit_type_id, (bm.bill_date_time::date)ORDER BY 1, 2;

-- billing.opdoctorwiserevenue_subconsultation source
CREATE OR REPLACE VIEW billing.opdoctorwiserevenue_subconsultationAS SELECT m_billing_master.billing_master_id,m_billing_master.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,dm.doctor_id,m_speciality_master.speciality_name,m_speciality_master.speciality_id,t_billing_details.gross_amount,t_billing_details.discount,t_billing_details.net_amt,t_billing_details.billing_details_id,m_billing_master.unit_id,'OP Consultation'::text AS labelFROM opd.t_encounter_masterJOIN doctor.m_doctor_master dm ON dm.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = t_encounter_master.doctor_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_idWHERE m_billing_master.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.new_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND m_billing_master.bill_cancelled = 'N'::bpcharUNIONSELECT m_billing_master.billing_master_id,m_billing_master.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,dm.doctor_id,m_speciality_master.speciality_name,m_speciality_master.speciality_id,t_billing_details.gross_amount,t_billing_details.discount,t_billing_details.net_amt,t_billing_details.billing_details_id,m_billing_master.unit_id,'OP Consultation'::text AS labelFROM opd.t_encounter_masterJOIN doctor.m_doctor_master dm ON dm.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = t_encounter_master.doctor_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_idWHERE m_billing_master.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.followup_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND m_billing_master.bill_cancelled = 'N'::bpcharUNIONSELECT m_billing_master.billing_master_id,m_billing_master.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,dm.doctor_id,m_speciality_master.speciality_name,m_speciality_master.speciality_id,t_billing_details.gross_amount,t_billing_details.discount,t_billing_details.net_amt,t_billing_details.billing_details_id,m_billing_master.unit_id,'OP Consultation'::text AS labelFROM opd.t_encounter_masterJOIN doctor.m_doctor_master dm ON dm.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN doctor.m_doctor_consultation_service_mapper ON m_doctor_consultation_service_mapper.doctor_id = t_encounter_master.doctor_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idJOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_idWHERE m_billing_master.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.secondary_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1)) AND m_billing_master.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,tod.ord_doc_id AS doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_id,'Cross Consultation'::text AS labelFROM adt.t_admission taJOIN billing.m_billing_master bm ON bm.admission_id = ta.admission_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details tod ON tod.order_details_id = bd.order_details_idJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = tod.ord_doc_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idLEFT JOIN doctor.m_speciality_master sp ON tod.ord_doc_spl_id = sp.speciality_idWHERE ta.doctor_id &lt;&gt; tod.ord_doc_id AND bm.visit_type_id = 2 AND bm.bill_cancelled = 'N'::bpchar AND m_service_master.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1))UNIONSELECT DISTINCT bm.billing_master_id,bm.bill_date_time,concat('Dr.', '.', dm.first_name, ' ', dm.last_name) AS doctorname,tod.ord_doc_id AS doctor_id,sp.speciality_name,sp.speciality_id,bd.gross_amount,bd.discount,bd.net_amt,bd.billing_details_id,bm.unit_id,'Non Invasive Procedures'::text AS labelFROM adt.t_admission taJOIN billing.m_billing_master bm ON bm.admission_id = ta.admission_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details tod ON tod.order_details_id = bd.order_details_idJOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = tod.ord_doc_idJOIN service.m_service_master ON bd.service_id = m_service_master.service_master_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idLEFT JOIN doctor.m_speciality_master sp ON tod.ord_doc_spl_id = sp.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND (m_service_master.service_master_id IN ( SELECT ts.service_master_idFROM service.t_unit_service_master_details tsWHERE ts.is_procedure = 'Y'::bpchar AND ts.procedure_type_id = 1))ORDER BY 12 DESC;

-- billing.opdpaymentreceipt source
CREATE OR REPLACE VIEW billing.opdpaymentreceiptAS SELECT t_payment_reciept_master.payment_reciept_id,t_payment_reciept_master.amount,t_payment_reciept_master.reciept_number,t_payment_reciept_master.date_of_reciept,t_payment_reciept_master.receipt_type,t_payment_reciept_master.counter_id,t_payment_reciept_master.settlement_id,t_payment_reciept_master.payee_id,t_payment_reciept_master.received_from,t_payment_reciept_master.identification_number,t_payment_reciept_master.remark,t_payment_reciept_master.is_printed,t_payment_reciept_master.is_financial_clearance,t_payment_reciept_master.status AS payment_status,t_payment_reciept_master.created_date AS payment_created_date,t_payment_reciept_master.created_by AS payment_created_by,t_payment_reciept_master.pharmacy_sale_id,m_billing_master.billing_master_id,m_billing_master.encounter_id,m_billing_master.visit_type_id,m_billing_master.patient_id,m_billing_master.bill_number,m_billing_master.bill_date_time,m_billing_master.net_amount,m_billing_master.discount_amount,m_billing_master.is_credit_bill,m_billing_master.organisation_id,m_billing_master.created_date,m_billing_master.created_by,m_billing_master.updated_date,m_billing_master.concession_amount,m_billing_master.gst,m_billing_master.total_bill_amount,m_billing_master.outstanding,m_billing_master.round_off,m_billing_master.status,m_billing_master.updated_by,m_billing_master.bill_status_id,m_billing_master.admission_id,m_billing_master.cr_amount,m_billing_master.settlement_date,m_billing_master.bill_cancelled,m_billing_master.bill_cancel_reason_id,m_billing_master.bill_cancel_datetime,m_billing_master.bill_cancel_by,m_billing_master.bill_cancel_remark,m_billing_master.is_interim_or_final_bill,m_billing_master.is_doctor_referral_posted,m_billing_master.is_invoice_creation,m_billing_master.is_dr_note,m_billing_master.dr_note_against_billid,m_billing_master.is_addendum_bill,m_billing_master.old_bill_id,m_payment_mode_master.payment_mode_desc,t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,t_payment_reciept_details.payment_mode_id,t_payment_reciept_details.amount AS paymentamount,m_bank_master.bank_name,t_payment_reciept_details.check_number,t_payment_reciept_details.cheque_date,t_payment_reciept_details.card_holder_name,t_payment_reciept_details.date_of_transaction,t_payment_reciept_details.card_number,t_payment_reciept_details.expiry_date,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,m_visit_type_master.visit_type_name,t_payment_reciept_details.transaction_no,unitinformation.imageFROM billing.t_payment_reciept_masterLEFT JOIN billing.t_payment_reciept_details ON t_payment_reciept_master.payment_reciept_id = t_payment_reciept_details.payment_receipt_master_idLEFT JOIN billing.m_billing_master ON t_payment_reciept_master.billing_master_id = m_billing_master.billing_master_idLEFT JOIN m_payment_mode_master ON t_payment_reciept_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN patient.t_patient_registration ON m_billing_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN billing.m_bank_master ON t_payment_reciept_details.bank_id = m_bank_master.bank_idLEFT JOIN m_user_master ON t_payment_reciept_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN m_visit_type_master ON m_billing_master.visit_type_id = m_visit_type_master.visit_type_idWHERE t_payment_reciept_master.status = 'A'::bpchar;

-- billing.patientwise_servicedetails source
CREATE OR REPLACE VIEW billing.patientwise_servicedetailsAS SELECT DISTINCT tpr.uhid_number,concat(tpr.first_name, ' ', tpr.middle_name, ' ', tpr.last_name) AS patientname,abs(date_part('Year'::text, age(tpr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,CASEWHEN tpr.gender_id = 1 THEN 'Male'::textELSE 'Female'::textEND AS gender,CASEWHEN en.doctor_id IS NULL THEN 'CMO'::textELSE concat('Dr.', doc.first_name, ' ', doc.last_name)END AS doctorname,sp.speciality_name::text AS lebel,msm.service_standard_name,bm.billing_master_id,bm.net_amount,bd.rate,bd.gross_amount,bd.discount + bd.concession AS discount,bd.net_amt AS net,bm.net_amount - bm.outstanding AS paid,pm.payment_entitlement_desc,cm.company_desc,bm.bill_date_time::date AS bill_date_time,'OP Patient'::text AS visitype,en.encounter_number AS visitno,bm.unit_id,bd.billing_details_id,bm.visit_type_id,docsp.speciality_name AS docsp,bd.quantity,bm.patient_id,bd.service_id,concat('Dr.', serdoc.first_name, ' ', serdoc.last_name) AS servicedoc,serdoc.doctor_id AS ser_docid,bd.ord_doc_spl_id,serdocsp.speciality_name AS serdocsp,bm.bill_numberFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idJOIN patient.t_patient_registration tpr ON tpr.patient_id = bm.patient_idJOIN opd.t_encounter_master en ON en.encounter_id = bm.encounter_idLEFT JOIN doctor.m_doctor_master doc ON en.doctor_id = doc.doctor_idLEFT JOIN doctor.m_doctor_master serdoc ON bd.ord_doc_id = serdoc.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON en.dept_id = docsp.speciality_idLEFT JOIN doctor.m_speciality_master serdocsp ON bd.ord_doc_spl_id = serdocsp.speciality_idJOIN opd.t_patient_sponsor_details psd ON psd.encounter_id = bm.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN t_company_master cm ON psd.payee_id = cm.company_idJOIN m_payment_entitlement_master pm ON pm.payment_entitlement_id = psd.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bd.status = 'A'::"char" AND bm.visit_type_id = 1UNIONSELECT DISTINCT tpr.uhid_number,concat(tpr.first_name, ' ', tpr.middle_name, ' ', tpr.last_name) AS patientname,abs(date_part('Year'::text, age(tpr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,CASEWHEN tpr.gender_id = 1 THEN 'Male'::textELSE 'Female'::textEND AS gender,concat('Dr.', doc.first_name, ' ', doc.last_name) AS doctorname,sp.speciality_name::text AS lebel,msm.service_standard_name,bm.billing_master_id,bm.net_amount,bd.rate,bd.gross_amount,bd.discount + bd.concession AS discount,bd.net_amt AS net,bm.net_amount - bm.outstanding AS paid,pm.payment_entitlement_desc,cm.company_desc,bm.bill_date_time::date AS bill_date_time,'IP Patient'::text AS visitype,ta.admission_number AS visitno,bm.unit_id,bd.billing_details_id,bm.visit_type_id,docsp.speciality_name AS docsp,bd.quantity,bm.patient_id,bd.service_id,concat('Dr.', serdoc.first_name, ' ', serdoc.last_name) AS servicedoc,serdoc.doctor_id AS ser_docid,bd.ord_doc_spl_id,serdocsp.speciality_name AS serdocsp,bm.bill_numberFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idJOIN patient.t_patient_registration tpr ON tpr.patient_id = bm.patient_idJOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN doctor.m_doctor_master doc ON ta.doctor_id = doc.doctor_idLEFT JOIN doctor.m_doctor_master serdoc ON bd.ord_doc_id = serdoc.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON ta.speciality_id = docsp.speciality_idLEFT JOIN doctor.m_speciality_master serdocsp ON bd.ord_doc_spl_id = serdocsp.speciality_idJOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharJOIN t_company_master cm ON psd.payee_id = cm.company_idJOIN m_payment_entitlement_master pm ON pm.payment_entitlement_id = psd.payment_entitlement_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bd.status = 'A'::"char" AND bm.visit_type_id &lt;&gt; 1ORDER BY 8;

-- billing.refund_cn source
CREATE OR REPLACE VIEW billing.refund_cnAS SELECT DISTINCT t_payment_refund_master.payment_refund_id,t_payment_refund_master.payment_refund_voucher_no,t_payment_refund_master.date_of_refund,t_payment_refund_master.is_cn_or_deposit,t_payment_refund_master.t_refund_cn_id,t_payment_refund_master.amount_refunded,unitinfo.unit_id,unitinfo.unit_name,unitinfo.unit_address,unitinfo.unit_address_2,unitinfo.unit_email_id,unitinfo.unit_logo,unitinfo.post_code,unitinfo.unit_contact,unitinfo.unit_contact_2,unitinfo.unit_contact_3,unitinfo.unit_country_code,unitinfo.registration_number,unitinfo.unit_website,m_currency_master.currency_name,m_currency_master.sub_currency,(((epm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,m_payment_mode_master.payment_mode_desc,m_bank_master.bank_name,t_payment_refund_details.card_number,t_payment_refund_details.cheque_number,t_payment_refund_details.date AS chequedate,t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_credit_note_master.credit_note_no AS againstcreditnoteno,t_payment_refund_details.payment_mode_id,''::text AS service_standard_name,0 AS rate,0 AS tax_amount,0 AS tax_per,0 AS quantity,0 AS concession,t_payment_refund_details.amount AS gross_amount,0 AS servicenetamt,unitinfo.image,m_credit_note_master.ce_remark AS remark,t_payment_refund_details.transaction_no,trantype.transaction_type_descFROM billing.t_payment_refund_masterJOIN billing.t_payment_refund_details ON t_payment_refund_master.payment_refund_id = t_payment_refund_details.payment_refund_idJOIN billing.m_credit_note_master ON t_payment_refund_master.credit_note_id = m_credit_note_master.credit_note_idJOIN billing.t_credit_note_detail ON m_credit_note_master.credit_note_id = t_credit_note_detail.credit_note_idJOIN t_order_details ON t_credit_note_detail.order_detail_id = t_order_details.order_details_idJOIN service.m_service_master ON t_order_details.service_id = m_service_master.service_master_idLEFT JOIN patient.t_patient_registration ON t_payment_refund_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_user_master ON t_payment_refund_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master epm ON m_employee_master.prefix_id = epm.prefix_idJOIN m_unit_master unitinfo ON t_payment_refund_master.unit_id = unitinfo.unit_idLEFT JOIN m_currency_master ON unitinfo.unit_id = m_currency_master.unit_idLEFT JOIN m_payment_mode_master ON t_payment_refund_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON t_payment_refund_details.bank_id = m_bank_master.bank_idLEFT JOIN billing.m_transaction_type_master trantype ON trantype.transaction_type_id = t_payment_refund_details.transaction_type_idWHERE t_payment_refund_master.is_cn_or_deposit = 1UNIONSELECT DISTINCT t_payment_refund_master.payment_refund_id,t_payment_refund_master.payment_refund_voucher_no,t_payment_refund_master.date_of_refund,t_payment_refund_master.is_cn_or_deposit,t_payment_refund_master.t_refund_cn_id,t_payment_refund_master.amount_refunded,unitinfo.unit_id,unitinfo.unit_name,unitinfo.unit_address,unitinfo.unit_address_2,unitinfo.unit_email_id,unitinfo.unit_logo,unitinfo.post_code,unitinfo.unit_contact,unitinfo.unit_contact_2,unitinfo.unit_contact_3,unitinfo.unit_country_code,unitinfo.registration_number,unitinfo.unit_website,m_currency_master.currency_name,m_currency_master.sub_currency,(((epm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,m_payment_mode_master.payment_mode_desc,m_bank_master.bank_name,t_payment_refund_details1.card_number,t_payment_refund_details1.cheque_number,t_payment_refund_details1.date AS chequedate,t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_deposit_master.deposit_no AS againstcreditnoteno,t_payment_refund_details1.payment_mode_id,''::text AS service_standard_name,0 AS rate,0 AS tax_amount,0 AS tax_per,0 AS quantity,0 AS concession,t_payment_refund_details1.amount AS gross_amount,0 AS servicenetamt,unitinfo.image,t_refund_cn.remark,t_payment_refund_details1.transaction_no,''::text AS transaction_type_descFROM billing.t_payment_refund_masterJOIN ( SELECT t_payment_refund_details.payment_refund_id,t_payment_refund_details.payment_mode_id,t_payment_refund_details.bank_id,t_payment_refund_details.card_number,t_payment_refund_details.cheque_number,t_payment_refund_details.date,t_payment_refund_details.transaction_no,sum(t_payment_refund_details.amount) AS amountFROM billing.t_payment_refund_detailsGROUP BY t_payment_refund_details.payment_refund_id, t_payment_refund_details.payment_mode_id, t_payment_refund_details.bank_id, t_payment_refund_details.card_number, t_payment_refund_details.cheque_number, t_payment_refund_details.date, t_payment_refund_details.transaction_no) t_payment_refund_details1 ON t_payment_refund_master.payment_refund_id = t_payment_refund_details1.payment_refund_idJOIN billing.t_refund_cn ON t_payment_refund_master.t_refund_cn_id = t_refund_cn.t_refund_cn_idJOIN billing.m_deposit_master ON t_refund_cn.deposit_id = m_deposit_master.deposit_master_idJOIN billing.t_payment_deposit_details ON m_deposit_master.deposit_master_id = t_payment_deposit_details.deposit_idLEFT JOIN patient.t_patient_registration ON t_payment_refund_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_user_master ON t_payment_refund_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master epm ON m_employee_master.prefix_id = epm.prefix_idJOIN m_unit_master unitinfo ON t_payment_refund_master.unit_id = unitinfo.unit_idLEFT JOIN m_currency_master ON unitinfo.unit_id = m_currency_master.unit_idLEFT JOIN m_payment_mode_master ON t_payment_refund_details1.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON t_payment_refund_details1.bank_id = m_bank_master.bank_idWHERE t_payment_refund_master.is_cn_or_deposit = 0;-- DROP FUNCTION billing.package_consumption_item_me_cancel_log(int4, int4, int4, int4, int4, int4, timestamp, int4);
CREATE OR REPLACE FUNCTION billing.package_consumption_item_me_cancel_log(pkg_id integer, pat_id integer, itm_id integer, v_t_id integer, visit_id integer, cr_by integer, cr_date timestamp without time zone, is_o_c integer)RETURNS integerLANGUAGE plpgsqlAS $function$begininsertintobilling.t_package_consumption_service_detail_log(pacakge_consumption_service_detail_id,package_quantity,balance_package_quantity,is_ordered_cancelled,created_by,created_date) (select pcsd.pacakge_consumption_service_detail_id,pcsd.package_quantity,pcsd.balance_package_quantity,is_o_c,cr_by,cr_datefrombilling.t_package_consumption_master pcminner join billing.t_package_consumption_service_detail pcsd onpcsd.package_consumption_master_id = pcm.package_consumption_master_idwherepcm.package_id = pkg_idand pcm.patient_id = pat_idand pcm.visit_type = v_t_idand pcsd.item_id = itm_id);
return 1;end;$function$;

-- DROP FUNCTION billing.package_consumption_item_order_log(int4, int4, int4, int4, int4, timestamp, int4);
CREATE OR REPLACE FUNCTION billing.package_consumption_item_order_log(pkg_id integer, pat_id integer, i_id integer, v_t_id integer, cr_by integer, cr_date timestamp without time zone, is_o_c integer)RETURNS integerLANGUAGE plpgsqlAS $function$begininsertintobilling.t_package_consumption_service_detail_log(pacakge_consumption_service_detail_id,package_quantity,balance_package_quantity,is_ordered_cancelled,created_by,created_date) (select pcsd.pacakge_consumption_service_detail_id,pcsd.package_quantity,pcsd.balance_package_quantity,is_o_c,cr_by,cr_datefrombilling.t_package_consumption_master pcminner join billing.t_package_consumption_service_detail pcsd onpcsd.package_consumption_master_id = pcm.package_consumption_master_idwherepcm.package_id = pkg_idand pcm.patient_id = pat_idand pcm.visit_type = v_t_idand pcm.package_type_id = 5and to_date(to_char(now(),'DD-MM-YYYY'),'DD-MM-YYYY') between pcm.validity_from and pcm.validity_toand pcsd.item_id = i_id);
 RETURN 1;end;$function$;

