CREATE OR REPLACE FUNCTION billing.package_consumption_service_cancel_log(pkg_id integer, pat_id integer, s_id integer, v_t_id integer, visit_id integer, cr_by integer, cr_date timestamp without time zone, is_o_c integer)RETURNS integerLANGUAGE plpgsqlAS $function$begininsertintobilling.t_package_consumption_service_detail_log(pacakge_consumption_service_detail_id,package_quantity,balance_package_quantity,is_ordered_cancelled,created_by,created_date) (select pcsd.pacakge_consumption_service_detail_id,pcsd.package_quantity,pcsd.balance_package_quantity,is_o_c,cr_by,cr_datefrombilling.t_package_consumption_master pcminner join billing.t_package_consumption_service_detail pcsd onpcsd.package_consumption_master_id = pcm.package_consumption_master_idwherepcm.package_id = pkg_idand pcm.patient_id = pat_idand ((pcm.encounter_id = visit_idand visit_type = v_t_id)or (pcm.admission_id = visit_idand visit_type = v_t_id))and pcsd.service_id = s_id);
return 1;end;$function$;

