-- DROP PROCEDURE billing.reject_refund(int4, float8);
CREATE OR REPLACE PROCEDURE billing.reject_refund(IN depo_id integer, IN r_amount double precision)LANGUAGE plpgsqlAS $procedure$ declare details record;amount double precision := r_amount;update_amt double precision;beginupdatebilling.m_deposit_mastersetavailable_deposit = coalesce(available_deposit, 0) + r_amount,refund_amount = coalesce(refund_amount, 0) - r_amountwheredeposit_master_id = depo_id;for details inselecttpdd.deposit_details_id,tpdd.balance_amount,tpdd.refund_amountfrombilling.t_payment_deposit_details tpddwheretpdd.deposit_id = depo_idorder bytpdd.deposit_details_id loopcasewhen details.refund_amount &gt;= r_amount then r_amount := r_amount;update_amt := r_amount;else r_amount := (r_amount - coalesce(details.refund_amount, 0));
update_amt := details.refund_amount;endcase;raise notice '% - % - % ',details.deposit_details_id,details.refund_amount,r_amount;updatebilling.t_payment_deposit_detailssetbalance_amount = coalesce(balance_amount, 0) + update_amt,refund_amount = coalesce(refund_amount, 0) - update_amtwheredeposit_details_id = details.deposit_details_idand r_amount &gt; 0;end loop;--commit;end;$procedure$;-- DROP SCHEMA blood_bank;
