-- doctor.doctorinformation source
CREATE OR REPLACE VIEW doctor.doctorinformationAS SELECT DISTINCT m_doctor_master.doctor_id,((('Dr. '::text || ' '::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_gender_master.gender_name AS docgender,m_doctor_category.doctor_category_description,m_speciality_master.speciality_name AS docspeciality,age(m_doctor_master.dob) AS docage,m_doctor_master.dob AS docdob,m_doctor_master.country_calling_code,m_doctor_master.mobile_number AS docmobile,m_doctor_master.email AS docemail,m_doctor_master.doctor_image,m_doctor_master.registration_number AS docreg,m_doctor_master.slot_time_span,m_doctor_master.doctor_episod_time_span,t_encounter_master.encounter_id,m_speciality_master.speciality_idFROM opd.t_encounter_masterLEFT JOIN doctor.m_doctor_master ON t_encounter_master.doctor_id = m_doctor_master.doctor_idLEFT JOIN m_gender_master ON m_doctor_master.gender_id = m_gender_master.gender_idLEFT JOIN m_doctor_category ON m_doctor_master.doc_category_id = m_doctor_category.doctor_category_idLEFT JOIN doctor.t_doctor_speciality_mapper ON t_encounter_master.doctor_id = t_doctor_speciality_mapper.doctor_idLEFT JOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_id;

-- doctor.doctorinformationipd source
CREATE OR REPLACE VIEW doctor.doctorinformationipdAS SELECT DISTINCT t_admission.admission_id,m_doctor_master.doctor_id,((('Dr. '::text || ' '::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_gender_master.gender_name AS docgender,m_doctor_category.doctor_category_description,m_speciality_master.speciality_name AS docspeciality,age(m_doctor_master.dob) AS docage,m_doctor_master.dob AS docdob,m_doctor_master.country_calling_code,m_doctor_master.mobile_number AS docmobile,m_doctor_master.email AS docemail,m_doctor_master.doctor_image,m_doctor_master.registration_number AS docreg,m_doctor_master.slot_time_span,m_doctor_master.doctor_episod_time_span,m_speciality_master.speciality_idFROM adt.t_admissionLEFT JOIN doctor.m_doctor_master ON t_admission.doctor_id = m_doctor_master.doctor_idLEFT JOIN m_gender_master ON m_doctor_master.gender_id = m_gender_master.gender_idLEFT JOIN m_doctor_category ON m_doctor_master.doc_category_id = m_doctor_category.doctor_category_idLEFT JOIN doctor.t_doctor_speciality_mapper ON t_admission.speciality_id = t_doctor_speciality_mapper.doctor_speciality_idLEFT JOIN doctor.m_speciality_master ON t_doctor_speciality_mapper.speciality_id = m_speciality_master.speciality_idORDER BY t_admission.admission_id;

-- doctor.doctorshare source
CREATE OR REPLACE VIEW doctor.doctorshareAS SELECT doctormaster.first_name,doctormaster.last_name,speciality.speciality_name,billmaster.bill_number,billmaster.bill_date_time,servicemaster.service_standard_name,share.bill_dtl_id,share.ord_dtl_id,share.admission_id AS visit_id,share.visit_type_id,share.service_id,share.unit_rate,share.total_amount,share.discount,share.due_share_amt,share.share_per,share.doc_share,share.processed_share_amt,share.hosp_share,share.processed_share_date,share.doc_id,share.doc_spec_id,share.doctor_share_idFROM billing.t_doctor_share shareJOIN doctor.m_doctor_master doctormaster ON share.doc_id = doctormaster.doctor_idJOIN doctor.m_speciality_master speciality ON share.doc_spec_id = speciality.speciality_idJOIN service.m_service_master servicemaster ON share.service_id = servicemaster.service_master_idJOIN billing.t_billing_details billdetails ON share.bill_dtl_id = billdetails.billing_details_idJOIN billing.m_billing_master billmaster ON billdetails.billing_master_id = billmaster.billing_master_idWHERE share.doc_share &lt;&gt; 0::double precision AND share.visit_type_id = 1UNIONSELECT doctormaster.first_name,doctormaster.last_name,speciality.speciality_name,billmaster.bill_number,billmaster.bill_date_time,servicemaster.service_standard_name,share.bill_dtl_id,share.ord_dtl_id,share.admission_id AS visit_id,share.visit_type_id,share.service_id,share.unit_rate,share.total_amount,share.discount,share.due_share_amt,share.share_per,share.doc_share,share.processed_share_amt,share.hosp_share,share.processed_share_date,share.doc_id,share.doc_spec_id,share.doctor_share_idFROM billing.t_doctor_share shareJOIN doctor.m_doctor_master doctormaster ON share.doc_id = doctormaster.doctor_idJOIN doctor.m_speciality_master speciality ON share.doc_spec_id = speciality.speciality_idJOIN service.m_service_master servicemaster ON share.service_id = servicemaster.service_master_idJOIN billing.t_billing_details billdetails ON share.bill_dtl_id = billdetails.billing_details_idJOIN billing.m_billing_master billmaster ON billdetails.billing_master_id = billmaster.billing_master_idWHERE share.doc_share &lt;&gt; 0::double precision AND share.visit_type_id = 2;

-- doctor.doctorsharedetails source
CREATE OR REPLACE VIEW doctor.doctorsharedetailsAS SELECT doctormaster.first_name,doctormaster.last_name,speciality.speciality_name,billmaster.bill_number,billmaster.bill_date_time,servicemaster.service_standard_name,share.bill_dtl_id,share.ord_dtl_id,share.admission_id AS visit_id,share.visit_type_id,share.service_id,share.unit_rate,share.total_amount,share.discount,share.due_share_amt,share.share_per,share.doc_share,share.processed_share_amt,share.hosp_share,share.processed_share_date,share.doc_id,share.doc_spec_id,share.doctor_share_id,speciality.speciality_id,unit.unit_name,unit.unit_address,unit.unit_id,unit.image,share.concession,share.net_amountFROM billing.t_doctor_share shareJOIN doctor.m_doctor_master doctormaster ON share.doc_id = doctormaster.doctor_idJOIN doctor.m_speciality_master speciality ON share.doc_spec_id = speciality.speciality_idJOIN service.m_service_master servicemaster ON share.service_id = servicemaster.service_master_idJOIN billing.t_billing_details billdetails ON share.bill_dtl_id = billdetails.billing_details_idJOIN billing.m_billing_master billmaster ON billdetails.billing_master_id = billmaster.billing_master_idLEFT JOIN m_unit_master unit ON share.org_unit_id = unit.unit_idWHERE share.doc_share &lt;&gt; 0::double precision;

-- doctor.ipddoctorinformation source
CREATE OR REPLACE VIEW doctor.ipddoctorinformationAS SELECT m_doctor_master.doctor_id,((('Dr. '::text || ' '::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_gender_master.gender_name,m_doctor_category.doctor_category_description,m_speciality_master.speciality_name,age(m_doctor_master.dob) AS docage,m_doctor_master.dob,m_doctor_master.country_calling_code,m_doctor_master.mobile_number,m_doctor_master.email,m_doctor_master.doctor_image,m_doctor_master.registration_number AS docregFROM adt.t_admissionLEFT JOIN doctor.m_doctor_master ON t_admission.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master ON t_admission.speciality_id = m_speciality_master.speciality_idLEFT JOIN m_gender_master ON m_doctor_master.gender_id = m_gender_master.gender_idLEFT JOIN m_doctor_category ON m_doctor_master.doc_category_id = m_doctor_category.doctor_category_id;-- DROP FUNCTION doctor.doctor_schedule_visit_details_procedure();
CREATE OR REPLACE FUNCTION doctor.doctor_schedule_visit_details_procedure()RETURNS triggerLANGUAGE plpgsqlAS $function$beginINSERT INTO doctor.m_doctor_schedule_visit_details(visit_type_id, visit_duration, visit_color, doctor_schedule_id, created_by, created_date, updated_by, updated_date, status)VALUES(1, NEW.time_per_slot,'Green', NEW.schedule_id, NEW.created_by, now(), NEW.updated_by, now(), 'A');
INSERT INTO doctor.m_doctor_schedule_visit_details(visit_type_id, visit_duration, visit_color, doctor_schedule_id, created_by, created_date, updated_by, updated_date, status)VALUES(2, NEW.time_per_slot,'Green', NEW.schedule_id, NEW.created_by, now(), NEW.updated_by, now(), 'A');
--For video in person and follow upINSERT INTO doctor.m_doctor_schedule_visit_details(visit_type_id, visit_duration, visit_color, doctor_schedule_id, created_by, created_date, updated_by, updated_date, status)VALUES(4, NEW.time_per_slot,'Green', NEW.schedule_id, NEW.created_by, now(), NEW.updated_by, now(), 'A');
INSERT INTO doctor.m_doctor_schedule_visit_details(visit_type_id, visit_duration, visit_color, doctor_schedule_id, created_by, created_date, updated_by, updated_date, status)VALUES(5, NEW.time_per_slot,'Green', NEW.schedule_id, NEW.created_by, now(), NEW.updated_by, now(), 'A');
RETURN NEW;END;$function$;

-- DROP FUNCTION doctor.insert_schedule_logs();
CREATE OR REPLACE FUNCTION doctor.insert_schedule_logs()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.add_remove=0 then --add scheduleinsert into public.t_schedule_logs (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'INSERT','HIS',0,new.org_id);
END IF;IF NEW.add_remove=1 then --remove/inactive scheduleinsert into public.t_schedule_logs (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'DELETE','HIS',0,new.org_id);
END IF;IF NEW.add_remove=2 then --activate scheduleinsert into public.t_schedule_logs (table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application, appointment_status_id,org_id)values('DoctorSchedule','PENDING',now(),new.schedule_id ,'NORMAL',0,0,now(),'ACTIVE','HIS',0,new.org_id);
END IF;RETURN NEW;END;$function$;

