CREATE OR REPLACE VIEW inventory.get_materialreturndetailsAS SELECT r.return_no,r.added_date AS return_date,s1.store_name AS from_store,s2.store_name AS to_store,item.code,item.name AS itemname,gm.name AS genericname,rd.return_qty,tb.batch_no,tb.expiry_date,unit.unit,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS addedby,(((em2.first_name::text || ' '::text) || em2.middle_name::text) || ' '::text) || em2.last_name::text AS approvedby,(((em3.first_name::text || ' '::text) || em3.middle_name::text) || ' '::text) || em3.last_name::text AS carriername,aps.status,rr.reason AS returnreason,u.unit_name,u.unit_address,u.unit_contact,r.id,u.unit_id,u.image,item.id AS item_id,rd.accepted_qty,rd.rejected_qty,rd.id AS return_id,s2.store_id,tb.cop,tb.rateFROM inventory.t_return rJOIN inventory.t_return_detail rd ON r.id = rd.return_idJOIN m_store s1 ON r.from_store_id = s1.store_idJOIN m_store s2 ON r.to_store_id = s2.store_idLEFT JOIN m_employee_master em1 ON r.added_by = em1.user_idLEFT JOIN m_employee_master em2 ON r.approved_by = em2.user_idLEFT JOIN m_employee_master em3 ON r.carrier_id = em3.user_idLEFT JOIN m_status aps ON r.approval_status_id = aps.idLEFT JOIN inventory.t_batch tb ON rd.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic gm ON gm.id = item.generic_idLEFT JOIN m_return_reason rr ON rd.reason_id = rr.idLEFT JOIN m_uom_unit unit ON rd.uom_unit_id = unit.idLEFT JOIN m_unit_master u ON r.unit_id = u.unit_idWHERE rd.is_active = true AND rd.is_deleted = false;

-- inventory.get_materialreturnlist source
CREATE OR REPLACE VIEW inventory.get_materialreturnlistAS SELECT r.return_no,r.added_date AS return_date,s1.store_name AS from_store,s2.store_name AS to_store,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS addedby,(((em2.first_name::text || ' '::text) || em2.middle_name::text) || ' '::text) || em2.last_name::text AS approvedby,(((em3.first_name::text || ' '::text) || em3.middle_name::text) || ' '::text) || em3.last_name::text AS carriername,aps.status,u.unit_name,u.unit_address,u.unit_contact,r.id,r.remark,u.imageFROM inventory.t_return rLEFT JOIN m_store s1 ON r.from_store_id = s1.store_idLEFT JOIN m_store s2 ON r.to_store_id = s2.store_idLEFT JOIN m_employee_master em1 ON r.added_by = em1.user_idLEFT JOIN m_employee_master em2 ON r.approved_by = em2.user_idLEFT JOIN m_employee_master em3 ON r.carrier_id = em3.user_idLEFT JOIN m_status aps ON r.approval_status_id = aps.idLEFT JOIN unitinformation u ON r.unit_id = u.unit_id;

-- inventory.get_non_billableconsumption source
CREATE OR REPLACE VIEW inventory.get_non_billableconsumptionAS SELECT nbc.consumption_no,nbc.added_date,m_store.store_name,usermaster.user_name,nbc.id,m_item.code,m_item.name AS itemname,m_generic.name AS generic,uomtype.type AS uomtype,uomunit.unit AS uomunit,batch.batch_no,batch.expiry_date,nbcd.consumed_qty,nbcd.accepted_qty,nbcd.reject_qty,um.unit_name,um.unit_address,m_status.status,statusapp.status AS statusapp,nbc.remark,stock.available_qty,um.image,um.unit_idFROM inventory.t_non_billable_consumption nbcJOIN inventory.t_non_billable_consumption_detail nbcd ON nbc.id = nbcd.non_billable_consumption_idJOIN m_store ON nbc.store_id = m_store.store_idLEFT JOIN m_user_master usermaster ON nbc.added_by = usermaster.user_idJOIN inventory.t_batch batch ON nbcd.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type uomtype ON nbcd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON nbcd.uom_unit_id = uomunit.idLEFT JOIN m_unit_master um ON nbc.unit_id = um.unit_idLEFT JOIN m_status ON nbc.status_id = m_status.idLEFT JOIN m_status statusapp ON nbc.approval_status_id = statusapp.idJOIN inventory.t_store_stock stock ON batch.id = stock.batch_id AND stock.store_id = nbc.store_idWHERE nbcd.is_active = true;

-- inventory.getconsumableacceptance source
CREATE OR REPLACE VIEW inventory.getconsumableacceptanceAS SELECT nbc.id,nbc.consumption_no,nbc.remark,m_store.store_name,nbc.added_by,nbc.approved_by,status.status,statusapp.status AS approvalstatus,usermapp.user_name AS appuser,userm.user_name AS adduser,m_item.code,m_item.name AS itemname,batch.batch_no,batch.expiry_date,uomtype.type AS uomtype,uomunit.unit AS uomunit,storestock.available_qty,nbcd.consumed_qty,nbcd.accepted_qty,nbcd.reject_qty,nbcd.reject_note,nbc.added_date,um.unit_name,um.unit_address,um.imageFROM inventory.t_non_billable_consumption nbcJOIN inventory.t_non_billable_consumption_detail nbcd ON nbc.id = nbcd.non_billable_consumption_idJOIN m_store ON nbc.store_id = m_store.store_idJOIN m_status status ON nbc.status_id = status.idJOIN m_status statusapp ON nbc.approval_status_id = statusapp.idJOIN inventory.t_batch batch ON nbcd.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idJOIN inventory.t_store_stock storestock ON batch.id = storestock.batch_id AND storestock.store_id = nbc.store_idLEFT JOIN m_uom_type uomtype ON nbcd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON nbcd.uom_unit_id = uomunit.idLEFT JOIN m_user_master userm ON nbc.added_by = userm.user_idLEFT JOIN m_user_master usermapp ON nbc.approved_by = usermapp.user_idLEFT JOIN m_unit_master um ON nbc.unit_id = um.unit_idWHERE nbc.is_active = true AND nbc.is_deleted = false;

-- inventory.getstoreindent source
CREATE OR REPLACE VIEW inventory.getstoreindentAS SELECT indentmaster.id AS indentid,indentmaster.added_date,indentmaster.indent_no,storefrom.store_name AS fromstore,storeto.store_name AS tostore,indenttype.type,m_status.status,m_item.name AS itemname,m_uom_unit.unit AS uom,m_uom_type.type AS uomtype,indentdetails.indent_quantity,indentdetails.authorized_quantity,indentdetails.pending_quantity,indentdetails.reject_quantity,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,m_generic.name AS generic,concat(emp.first_name, ' ', emp.last_name)::character varying(100) AS user_name,unitinformation.image,concat(empathorize.first_name, ' ', empathorize.last_name)::character varying(100) AS empathorizeFROM inventory.t_store_indent indentmasterJOIN inventory.t_store_indent_detail indentdetails ON indentmaster.id = indentdetails.store_indent_idLEFT JOIN m_store storefrom ON indentmaster.from_store_id = storefrom.store_idLEFT JOIN m_store storeto ON indentmaster.to_store_id = storeto.store_idLEFT JOIN inventory.m_indent_type indenttype ON indentmaster.indent_type_id = indenttype.idLEFT JOIN m_status ON indentmaster.status_id = m_status.idLEFT JOIN m_item ON indentdetails.item_id = m_item.idLEFT JOIN m_uom_unit ON indentdetails.uom_unit_id = m_uom_unit.idLEFT JOIN m_uom_type ON indentdetails.uom_type_id = m_uom_type.idLEFT JOIN m_unit_master unitinformation ON indentmaster.unit_id = unitinformation.unit_idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_user_master um ON indentmaster.added_by = um.user_idLEFT JOIN m_employee_master emp ON emp.user_id = um.user_idLEFT JOIN m_user_master umathorize ON indentmaster.approved_by = umathorize.user_idLEFT JOIN m_employee_master empathorize ON empathorize.user_id = umathorize.user_idWHERE indentdetails.is_active = true;

-- inventory.getstoreindentlist source
CREATE OR REPLACE VIEW inventory.getstoreindentlistAS SELECT DISTINCT indentmaster.id AS indentid,indentmaster.added_date::date AS added_date,indentmaster.indent_no,storefrom.store_name AS fromstore,storeto.store_name AS tostore,indenttype.type,m_status.status,prioritymaster.priority_desc,storefrom.store_id AS fromstoreid,storeto.store_id AS tostoreid,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,prioritymaster.priority_id,indenttype.id AS typeid,m_status.id AS status_id,unitinformation.image,indentdetails.item_id,m_item.code,m_item.name AS itemname,indentdetails.indent_quantity,indentdetails.authorized_quantity,indentdetails.pending_quantityFROM inventory.t_store_indent indentmasterJOIN inventory.t_store_indent_detail indentdetails ON indentmaster.id = indentdetails.store_indent_idLEFT JOIN m_store storefrom ON indentmaster.from_store_id = storefrom.store_idLEFT JOIN m_store storeto ON indentmaster.to_store_id = storeto.store_idLEFT JOIN inventory.m_indent_type indenttype ON indentmaster.indent_type_id = indenttype.idLEFT JOIN m_status ON indentmaster.status_id = m_status.idLEFT JOIN m_item ON m_item.id = indentdetails.item_idLEFT JOIN adt.m_priority_master prioritymaster ON indentmaster.priority_id = prioritymaster.priority_idLEFT JOIN m_unit_master unitinformation ON indentmaster.unit_id = unitinformation.unit_idWHERE indentdetails.is_active = true AND indentdetails.is_deleted = false;-- DROP FUNCTION inventory.update_current_stock();
CREATE OR REPLACE FUNCTION inventory.update_current_stock()RETURNS triggerLANGUAGE plpgsqlAS $function$beginupdate inventory.t_batch tb set current_quantity = (select sum(available_qty) from inventory.t_store_stock where batch_id = new.batch_id)where id = new.batch_id ;RETURN NEW;END;$function$;

-- DROP FUNCTION inventory.updatembarcodetrigger();
CREATE OR REPLACE FUNCTION inventory.updatembarcodetrigger()RETURNS triggerLANGUAGE plpgsqlAS $function$BEGINupdate inventory.t_batch set pre_printed_barcode = right(cast(concat('0000000',new.id) as varchar),8)where id = new.id and unit_id = 11 ; RETURN NEW;END;$function$;

