-- lab.barcodeforlabsample source
CREATE OR REPLACE VIEW lab.barcodeforlabsampleAS SELECT DISTINCT sm.lab_sample_id AS sample_id,sm.sample_no,sampletype.sample_desc,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,sm.sample_id AS barcodesampleid,samdetail.sample_collection_datetime,samdetail.sample_barcode,samdetail.order_details_id,samdetail.lab_sample_dtls_id AS lab_sample_detils_idFROM lab.t_lab_sample_master smJOIN patient.t_patient_registration pr ON pr.patient_id = sm.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN lab.t_lab_sample_dtls samdetail ON samdetail.lab_sample_id = sm.lab_sample_idJOIN lab.m_sample_master sampletype ON samdetail.sample_type_id = sampletype.sample_id;

-- lab.get_machine_data source
CREATE OR REPLACE VIEW lab.get_machine_dataAS SELECT DISTINCT testmaster.test_desc,mmp.machine_parameter_desc AS machineparname,CASEWHEN om.admission_id IS NULL THEN em.encounter_numberWHEN om.admission_id IS NOT NULL THEN adm.admission_numberELSE NULL::character varyingEND AS opipdno,om.order_date AS date,samplemaster.sample_id AS sample_no,prefix.prefix_desc AS prefix,reg.last_name,reg.first_name,reg.middle_name,abs(date_part('Year'::text, age(to_char(reg.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,abs(date_part('Month'::text, age(to_char(reg.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(to_char(reg.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,gm.gender_name AS sex,mmm.machine_desc,om.admission_id,om.encounter_id,samplemaster.lab_sample_id,mmm.machine_id,um.unit_id,um.organization_id,reg.patient_id,reg.dob::date AS dob,mmp.code AS machineparacode,reg.blood_group,mbm.bed_number AS bed_no,lsm.sample_desc AS specimen_type,CASEWHEN om.admission_id IS NULL THEN 'OP'::textELSE 'IP'::textEND AS patient_type,CASEWHEN adm.admitting_doctor_id IS NULL THEN concat('Dr.', mdmop.first_name, ' ', mdmop.last_name)ELSE concat('Dr.', mdmip.first_name, ' ', mdmip.last_name)END AS dr_name,msm.speciality_name AS department,mum.unit_name AS para_unitFROM t_order_master omJOIN lab.t_lab_sample_master samplemaster ON om.order_id = samplemaster.order_idJOIN lab.t_lab_sample_dtls sampledetail ON samplemaster.lab_sample_id = sampledetail.lab_sample_idJOIN lab.m_test_master testmaster ON sampledetail.test_id = testmaster.test_idJOIN lab.t_test_parameter_mppr testparmapper ON sampledetail.test_id = testparmapper.test_id AND testparmapper.org_id = om.org_id AND testparmapper.org_unit_id = om.org_unit_idJOIN lab.m_parameter_master parammaster ON testparmapper.parameter_id = parammaster.parameter_idJOIN lab.t_machine_parameter_mppr machinepara ON testparmapper.parameter_id = machinepara.parameter_id AND machinepara.organisation_id = om.org_id AND machinepara.unit_id = om.org_unit_idJOIN lab.m_machine_parameter mmp ON machinepara.machin_parameter_id = mmp.machin_parameter_idJOIN lab.m_machine_master mmm ON mmp.machine_id = mmm.machine_idLEFT JOIN adt.t_admission adm ON om.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON om.encounter_id = em.encounter_idJOIN patient.t_patient_registration reg ON om.patient_id = reg.patient_idJOIN m_gender_master gm ON gm.gender_id = reg.gender_idJOIN m_prefix_master prefix ON reg.prefix_id = prefix.prefix_idJOIN m_unit_master um ON um.unit_id = om.org_unit_idLEFT JOIN adt.t_admission_details tad ON adm.admission_id = tad.admission_idLEFT JOIN adt.m_bed_master mbm ON tad.bed_id = mbm.bed_idJOIN lab.m_sample_master lsm ON sampledetail.sample_type_id = lsm.sample_idLEFT JOIN doctor.m_doctor_master mdmop ON em.doctor_id = mdmop.doctor_idLEFT JOIN doctor.m_doctor_master mdmip ON adm.admitting_doctor_id = mdmip.doctor_idLEFT JOIN doctor.m_speciality_master msm ON adm.speciality_id = msm.speciality_idLEFT JOIN lab.m_unit_master mum ON testmaster.unit_id = mum.unit_idWHERE machinepara.status = 'A'::bpchar AND testparmapper.test_para_status = 'A'::bpchar;

-- lab.get_turnaroundtime source
CREATE OR REPLACE VIEW lab.get_turnaroundtimeAS SELECT sample_dtls.test_id,testmaster.test_desc,COALESCE(date_part('day'::text, test_result.result_enter_datetime - sample_dtls.sample_collection_datetime) * 24::double precision + date_part('hour'::text, test_result.result_enter_datetime - sample_dtls.sample_collection_datetime), 0::double precision) AS collection_to_accept,COALESCE(date_part('day'::text, test_result.result_authorised_datetime - test_result.result_enter_datetime) * 24::double precision + date_part('hour'::text, test_result.result_authorised_datetime - test_result.result_enter_datetime), 0::double precision) AS accept_to_resultentry,COALESCE(date_part('day'::text, audittrail.created_date - test_result.result_authorised_datetime) * 24::double precision + date_part('hour'::text, audittrail.created_date - test_result.result_authorised_datetime), 0::double precision) AS resultentry_to_release,sample_dtls.sample_collection_datetime::date AS sample_collection_datetime,sample_dtls.org_unit_id,um.unit_name,um.unit_address,um.unit_id,um.image,um.unit_contact,um.unit_website,um.unit_email_id,COALESCE(date_part('day'::text, test_result.result_validated_datetime - test_result.result_enter_datetime) * 24::double precision + date_part('hour'::text, test_result.result_validated_datetime - test_result.result_enter_datetime), 0::double precision) AS resultentry_to_authorised,ssp.sub_speciality_id,ssp.sub_speciality_nameFROM lab.t_lab_sample_dtls sample_dtlsJOIN lab.t_lab_test_result test_result ON test_result.lab_sample_dtls_id = sample_dtls.lab_sample_dtls_idJOIN lab.m_test_master testmaster ON sample_dtls.test_id = testmaster.test_idLEFT JOIN lab.t_sample_audit_trail audittrail ON test_result.lab_sample_dtls_id = audittrail.sample_dtls_id AND audittrail.test_status_id = 8JOIN doctor.m_sub_speciality_master ssp ON sample_dtls.sub_dept_id = ssp.sub_speciality_idLEFT JOIN unitinformation um ON sample_dtls.org_unit_id = um.unit_id;

-- lab.get_turnaroundtime_details source
CREATE OR REPLACE VIEW lab.get_turnaroundtime_detailsAS SELECT DISTINCT sample_dtls.test_id,testmaster.test_desc,COALESCE(date_part('day'::text, test_result.result_enter_datetime - sample_dtls.sample_collection_datetime) * 24::double precision + date_part('hour'::text, test_result.result_enter_datetime - sample_dtls.sample_collection_datetime), 0::double precision) AS collection_to_accept,COALESCE(date_part('day'::text, test_result.result_authorised_datetime - test_result.result_enter_datetime) * 24::double precision + date_part('hour'::text, test_result.result_authorised_datetime - test_result.result_enter_datetime), 0::double precision) AS accept_to_resultentry,COALESCE(date_part('day'::text, audittrailrelease.created_date - sample_dtls.sample_collection_datetime) * 24::double precision + date_part('hour'::text, audittrailrelease.created_date - sample_dtls.sample_collection_datetime), 0::double precision) AS resultentry_to_release,sample_dtls.sample_collection_datetime,sample_dtls.org_unit_id,um.unit_name,um.unit_address,um.unit_id,'\x'::bytea AS image,um.unit_contact,um.unit_website,um.unit_email_id,COALESCE(date_part('day'::text, test_result.result_validated_datetime - test_result.result_enter_datetime) * 24::double precision + date_part('hour'::text, test_result.result_validated_datetime - test_result.result_enter_datetime), 0::double precision) AS resultentry_to_authorised,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.last_name) AS patientname,pim.uhid_number,CASEWHEN tom.visit_type_id = 1 THEN 'OPD'::textELSE 'IPD'::textEND AS opipno,tom.order_date,sample_dtls.updated_date,test_result.result_enter_datetime,test_result.result_validated_datetime,audittrail.created_date,sample_dtls.sample_accept_datetime,audittrailrelease.created_date AS reportreleasetime,COALESCE(date_part('day'::text, audittrailrelease.created_date - sample_dtls.sample_collection_datetime) * 24::double precision + date_part('minute'::text, audittrailrelease.created_date - sample_dtls.sample_collection_datetime), 0::double precision) AS resultentry_to_releaseminute,pim.patient_id,ssp.sub_speciality_id,ssp.sub_speciality_name,tom.visit_type_id,vm.visit_type_name,testmaster.urgent_tat_time,testmaster.norml_tat_timeFROM lab.t_lab_sample_dtls sample_dtlsJOIN lab.t_lab_test_result test_result ON test_result.lab_sample_dtls_id = sample_dtls.lab_sample_dtls_idJOIN lab.m_test_master testmaster ON sample_dtls.test_id = testmaster.test_idLEFT JOIN lab.t_sample_audit_trail audittrail ON test_result.lab_sample_dtls_id = audittrail.sample_dtls_id AND audittrail.test_status_id = 3LEFT JOIN lab.t_sample_audit_trail audittrailrelease ON test_result.lab_sample_dtls_id = audittrailrelease.sample_dtls_id AND audittrailrelease.test_status_id = 8JOIN patient.t_patient_registration pim ON pim.patient_id = sample_dtls.patient_idJOIN doctor.m_sub_speciality_master ssp ON sample_dtls.sub_dept_id = ssp.sub_speciality_idJOIN t_order_master tom ON tom.order_id = sample_dtls.order_idLEFT JOIN m_visit_type_master vm ON tom.visit_type_id = vm.visit_type_idJOIN m_prefix_master prefix ON pim.prefix_id = prefix.prefix_idLEFT JOIN unitinformation um ON sample_dtls.org_unit_id = um.unit_id;

-- lab.investigationslip source
CREATE OR REPLACE VIEW lab.investigationslipAS SELECT DISTINCT t_order_master.order_id,t_order_master.order_date,t_order_master.order_no,t_order_details.order_details_id,t_order_details.order_qty,m_service_master.service_standard_name,pr.prefix_id,pr.uhid_number,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,pr.bar_code,age(pr.dob) AS age,pr.mobile_number,pr.email,pr.mobile_number AS patientmobile,pr.email AS patientemail,''::character varying AS reg_type,gm.gender_name AS patientgender,''::character varying(200) AS patient_category,pr.created_date AS regdate,pr.is_vip,pr.dob AS patientdob,''::character varying AS identification_number,pr.created_date AS identification_expiry_date,''::text AS patientaddress,''::character varying(50) AS zip_code,pr.mobile_number::character varying(100) AS phone_number,pr.patient_id,''::character varying(100) AS marital_status_name,unitinfo.unit_id,unitinfo.unit_name,unitinfo.unit_address,unitinfo.unit_address_2,unitinfo.unit_email_id,unitinfo.unit_logo,unitinfo.post_code,unitinfo.unit_contact,unitinfo.unit_contact_2,unitinfo.unit_contact_3,unitinfo.unit_country_code,unitinfo.registration_number,unitinfo.unit_website,m_currency_master.currency_name,m_currency_master.sub_currency,COALESCE(t_order_details.ord_cancelled, 'N'::character varying::bpchar) AS ord_cancelled,doctormaster.doctor_id,doctormaster.doctorname,doctormaster.docgender,doctormaster.doctor_category_description,doctormaster.docspeciality,doctormaster.docage,doctormaster.docdob,doctormaster.country_calling_code,doctormaster.docmobile,doctormaster.docemail,doctormaster.doctor_image,doctormaster.docreg,doctormaster.slot_time_span,doctormaster.doctor_episod_time_span,doctormaster.encounter_id,doctormaster.speciality_id,m_speciality_master.speciality_name AS groupname,t_order_master.created_by,t_order_details.created_by AS dtlscreated_by,m_service_master.speciality_id AS groupidFROM t_order_masterJOIN t_order_details ON t_order_master.order_id = t_order_details.order_id AND t_order_master.visit_type_id = 1LEFT JOIN opd.t_encounter_master ON t_order_master.encounter_id = t_encounter_master.encounter_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = t_encounter_master.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = pr.gender_idLEFT JOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idLEFT JOIN service.m_service_master ON t_order_details.service_id = m_service_master.service_master_idLEFT JOIN m_unit_master unitinfo ON t_order_master.org_unit_id = unitinfo.unit_idLEFT JOIN m_currency_master ON unitinfo.unit_id = m_currency_master.unit_idLEFT JOIN doctor.doctorinformation doctormaster ON t_encounter_master.encounter_id = doctormaster.encounter_idLEFT JOIN doctor.m_speciality_master ON m_service_master.speciality_id = m_speciality_master.speciality_idORDER BY t_order_details.order_details_id;

-- lab.lab_master source
CREATE OR REPLACE VIEW lab.lab_masterAS SELECT tm.test_id,tm.test_code,tm.test_desc,tm.test_alies,ssm.sub_speciality_name,sm.sample_desc,tm.no_of_sample_req,tm.sample_volume,um1.unit_name AS test_unit,cm.container_name,rtm.report_type_name,tecm.technique_name,tm.identification_no,prem.prerequisites_name,tm.pro_release,tm.test_status,tm.is_outsourced,tm.is_centrifugation_requried,tm.is_unique_barcode,tm.foot_note,tm.urgent_tat_id,tm.urgent_tat_time,tm.norml_tat_id,tm.norml_tat_time,hm.header_desc,tpm.para_sequence,tpm.header_sequence,pm.parameter_id,pm.parameter_code,pm.parameter_name,pm.alies_name,um2.unit_name AS parameter_unit,pm.refrange_type_id,pm.param_precision,pm.delta_per,pm.delta_days_id,prm.age_group_id,agm.age_type_grp_name,gm.gender_name,prm.min_value,prm.max_value,prm.less_than,prm.more_than,''::text AS multitextaul_range,prm.remark,pm.is_multyparameter,pm.is_formula,pm.is_editable,pm.is_machine_wise_panic_values,fm.formula,fm.formula_latex,tm.org_id,tm.org_unit_id,hv.help_valueFROM lab.m_test_master tmLEFT JOIN lab.t_test_parameter_mppr tpm ON tm.test_id = tpm.test_idLEFT JOIN lab.m_parameter_master pm ON tpm.parameter_id = pm.parameter_idLEFT JOIN doctor.m_sub_speciality_master ssm ON tm.dept_id = ssm.sub_speciality_idLEFT JOIN lab.m_sample_master sm ON tm.sample_id = sm.sample_idLEFT JOIN lab.m_unit_master um1 ON tm.unit_id = um1.unit_idLEFT JOIN lab.m_unit_master um2 ON pm.unit_id = um2.unit_idLEFT JOIN lab.m_container_master cm ON tm.container_id = cm.container_idLEFT JOIN lab.m_report_type_master rtm ON tm.report_type_id = rtm.report_type_idLEFT JOIN lab.m_technique_master tecm ON tm.technique_id = tecm.technique_idLEFT JOIN lab.m_prerequisites_master prem ON tm.prerequisits_id = prem.prerequisites_idLEFT JOIN lab.m_header_master hm ON tpm.header_id = hm.header_idLEFT JOIN lab.m_param_refreng_master prm ON pm.parameter_id = prm.parameter_idLEFT JOIN lab.m_age_group_master agm ON prm.age_group_id = agm.age_group_idLEFT JOIN m_gender_master gm ON prm.gender_id = gm.gender_idLEFT JOIN lab.m_formula_master fm ON pm.parameter_id = fm.parameter_idLEFT JOIN lab.m_formula_details fd ON fm.formula_id = fd.formula_idLEFT JOIN lab.m_help_value_master hv ON pm.parameter_id = hv.parameter_idWHERE tm.test_status = 'A'::bpchar AND tpm.test_para_status = 'A'::bpchar AND tpm.is_deleted = 'N'::bpchar AND tpm.is_deleted = 'N'::bpchar AND pm.status = 'A'::bpchar AND prm.refreng_status = 'A'::bpchar AND prm.is_deleted = 'N'::bpcharUNIONSELECT tm.test_id,tm.test_code,tm.test_desc,tm.test_alies,ssm.sub_speciality_name,sm.sample_desc,tm.no_of_sample_req,tm.sample_volume,um1.unit_name AS test_unit,cm.container_name,rtm.report_type_name,tecm.technique_name,tm.identification_no,prem.prerequisites_name,tm.pro_release,tm.test_status,tm.is_outsourced,tm.is_centrifugation_requried,tm.is_unique_barcode,tm.foot_note,tm.urgent_tat_id,tm.urgent_tat_time,tm.norml_tat_id,tm.norml_tat_time,hm.header_desc,tpm.para_sequence,tpm.header_sequence,pm.parameter_id,pm.parameter_code,pm.parameter_name,pm.alies_name,um2.unit_name AS parameter_unit,pm.refrange_type_id,pm.param_precision,pm.delta_per,pm.delta_days_id,pmr.age_group_id,agm.age_type_grp_name,gm.gender_name,0 AS min_value,0 AS max_value,0 AS less_than,0 AS more_than,pmr.multitextaul_range,pmr.remark,pm.is_multyparameter,pm.is_formula,pm.is_editable,pm.is_machine_wise_panic_values,fm.formula,fm.formula_latex,tm.org_id,tm.org_unit_id,hv.help_valueFROM lab.m_test_master tmLEFT JOIN lab.t_test_parameter_mppr tpm ON tm.test_id = tpm.test_idLEFT JOIN lab.m_parameter_master pm ON tpm.parameter_id = pm.parameter_idLEFT JOIN doctor.m_sub_speciality_master ssm ON tm.dept_id = ssm.sub_speciality_idLEFT JOIN lab.m_sample_master sm ON tm.sample_id = sm.sample_idLEFT JOIN lab.m_unit_master um1 ON tm.unit_id = um1.unit_idLEFT JOIN lab.m_unit_master um2 ON pm.unit_id = um2.unit_idLEFT JOIN lab.m_container_master cm ON tm.container_id = cm.container_idLEFT JOIN lab.m_report_type_master rtm ON tm.report_type_id = rtm.report_type_idLEFT JOIN lab.m_technique_master tecm ON tm.technique_id = tecm.technique_idLEFT JOIN lab.m_prerequisites_master prem ON tm.prerequisits_id = prem.prerequisites_idLEFT JOIN lab.m_header_master hm ON tpm.header_id = hm.header_idLEFT JOIN lab.m_param_multitextual_range pmr ON pm.parameter_id = pmr.parameter_idLEFT JOIN lab.m_age_group_master agm ON pmr.age_group_id = agm.age_group_idLEFT JOIN m_gender_master gm ON pmr.gender_id = gm.gender_idLEFT JOIN lab.m_formula_master fm ON pm.parameter_id = fm.parameter_idLEFT JOIN lab.m_formula_details fd ON fm.formula_id = fd.formula_idLEFT JOIN lab.m_help_value_master hv ON pm.parameter_id = hv.parameter_idWHERE tm.test_status = 'A'::bpchar AND tpm.test_para_status = 'A'::bpchar AND tpm.is_deleted = 'N'::bpchar AND tpm.is_deleted = 'N'::bpchar AND pm.status = 'A'::bpchar AND pmr.status = 'A'::bpchar AND pmr.is_deleted = 'N'::bpchar;-- DROP FUNCTION lab.duplicate_interface_value();
CREATE OR REPLACE FUNCTION lab.duplicate_interface_value()RETURNS triggerLANGUAGE plpgsqlAS $function$beginupdate lab.t_lab_machine_interface set status = 'I' where unit_id = new.unit_idand organisation_id = new.organisation_id and sample_no = new.sample_no and parameter_name = new.parameter_name and machine_name = new.machine_name ;RETURN NEW;END;$function$;

-- DROP FUNCTION lab.generate_sample_no(text, text, int4);
CREATE OR REPLACE FUNCTION lab.generate_sample_no(sample_no text, sample_prefix text, width integer)RETURNS character varyingLANGUAGE plpgsqlAS $function$DECLAREsample_no_width integer;sample_prfix text;add_zero text := '';BEGINsample_prfix = sample_prefix;sample_no_width = character_length(sample_no);
IF (width - sample_no_width) &gt; 0 THENFOR i IN 1..(width - sample_no_width) LOOPadd_zero := add_zero||'0';END LOOP;RETURN sample_prfix||add_zero||sample_no;END IF;RETURN sample_prfix||sample_no;END;$function$;

-- DROP FUNCTION lab.out_source_insert();
CREATE OR REPLACE FUNCTION lab.out_source_insert()RETURNS triggerLANGUAGE plpgsqlAS $function$ BEGIN INSERTINTOlab.t_out_source_logger(out_sourced_id,order_id,org_id,org_unit_id,lab_sample_dtls_id,status,created_by,created_date)VALUES(NEW.out_sourced_id,NEW.order_id,NEW.org_id,NEW.org_unit_id,NEW.lab_sample_dtls_id,NEW.status,NEW.created_by,NEW.created_date);
RETURN NEW;END;$function$;

-- DROP FUNCTION lab.out_source_update();
CREATE OR REPLACE FUNCTION lab.out_source_update()RETURNS triggerLANGUAGE plpgsqlAS $function$ BEGIN INSERTINTOlab.t_out_source_logger(out_sourced_id,order_id,org_id,org_unit_id,lab_sample_dtls_id,status,updated_by,updated_date)VALUES(NEW.out_sourced_id,NEW.order_id,NEW.org_id,NEW.org_unit_id,NEW.lab_sample_dtls_id,NEW.status,NEW.updated_by,NEW.updated_date);
RETURN NEW;END;$function$;

-- DROP FUNCTION lab.sample_audit_trail_insert();
CREATE OR REPLACE FUNCTION lab.sample_audit_trail_insert()RETURNS triggerLANGUAGE plpgsqlAS $function$ BEGIN INSERTINTOlab.t_sample_audit_trail(order_details_id,test_id,sample_dtls_id,test_status_id,created_by,created_date,org_id,org_unit_id,assign_unit,performed_unit)VALUES(NEW.order_details_id,NEW.test_id,NEW.lab_sample_dtls_id,NEW.sample_status_id,NEW.created_by,NEW.created_date,NEW.org_id,NEW.org_unit_id,new.assign_unit,new.performed_unit);
