-- DROP FUNCTION lab.sample_audit_trail_update();
CREATE OR REPLACE FUNCTION lab.sample_audit_trail_update()RETURNS triggerLANGUAGE plpgsqlAS $function$ BEGIN INSERTINTOlab.t_sample_audit_trail(order_details_id,test_id,sample_dtls_id,test_status_id,created_by,created_date,org_id,org_unit_id,assign_unit,performed_unit)VALUES(NEW.order_details_id,NEW.test_id,NEW.lab_sample_dtls_id,NEW.sample_status_id,NEW.updated_by,NEW.updated_date,NEW.org_id,NEW.org_unit_id,NEW.assign_unit,new.performed_unit);
