-- DROP FUNCTION lab.save_sample_acc_rej_details(int4, int4, int4, int4, bpchar, int4, int4, int4, int4);
CREATE OR REPLACE FUNCTION lab.save_sample_acc_rej_details(labsmpdtlsid integer, patientid integer, labsampleid integer, samplestatusid integer, samplestatus character, deptid integer, orgid integer, orgunitid integer, createdby integer)RETURNS integerLANGUAGE plpgsqlAS $function$ DECLARE ins_scc INTEGER;BEGININSERTINTOlab.t_smp_accept_reject_mppr(lab_smp_dtls_id,patient_id,lab_sample_id,dept_id,sample_status_id,sample_status,org_id,org_unit_id,created_by,created_date)VALUES(labsmpdtlsid,patientid,labsampleid,deptid,samplestatusid,samplestatus,orgid,orgunitid,createdby,now()) RETURNING lab_smp_dtls_id INTO ins_scc; RETURN ins_scc; END;$function$;

