CREATE OR REPLACE VIEW opd.appointmentslipAS SELECT t_patient_registration.patient_id,'OPD'::text AS visit_type_id,t_patient_registration.uhid_number,(((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || COALESCE(t_patient_registration.middle_name, ''::character varying)::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,((('Dr. '::text || ' '::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_speciality_master.speciality_name,m_patient_category_master.patient_category,m_organization_master.organization_name,t_patient_registration.identification_number,m_identification_master.identification_name,t_patient_registration.mobile_number,t_patient_registration.email,m_slot_master.from_time,m_slot_master.to_time,m_slot_master.appointment_date,m_appointment_master.appointment_id,t_patient_details.address,t_patient_details.zip_code,t_patient_details.phone_number,m_organization_master.organization_address,m_gender_master.gender_name,t_patient_registration.created_date,age(t_patient_registration.dob) AS age,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS user_name,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,cm.currency_name,cm.sub_currency,appstatus.appointment_status_desc,appstatus.appointment_status_id,abs(date_part('Year'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,m_doctor_master.first_name,m_doctor_master.last_name,m_doctor_master.doctor_id,m_appointment_master.appointment_type_id,'\x'::bytea AS image,m_appointment_master.remark,t_patient_registration.dob,t_patient_registration.blood_group,unitinformation.image AS unitimageFROM opd.m_appointment_masterJOIN patient.t_patient_registration ON m_appointment_master.patient_id = t_patient_registration.patient_idJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN opd.m_slot_master ON m_appointment_master.slot_id = m_slot_master.slot_idLEFT JOIN doctor.m_doctor_master ON m_slot_master.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master ON m_slot_master.speciality_id = m_speciality_master.speciality_idJOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idJOIN m_organization_master ON t_patient_registration.organization_id = m_organization_master.organization_idJOIN m_unit_master unitinformation ON m_appointment_master.unit_id = unitinformation.unit_idLEFT JOIN m_currency_master cm ON cm.unit_id = m_appointment_master.unit_idLEFT JOIN adt.m_identification_master ON t_patient_registration.identification_type_id = m_identification_master.identification_idLEFT JOIN m_user_master ON m_appointment_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN opd.m_appointment_status_master appstatus ON m_appointment_master.appointment_status_id = appstatus.appointment_status_id;

