.first_name,m_doctor_master.last_name,appdoctor.doctor_id,m_appointment_master.appointment_type_id,m_unit_master.image,m_refferel.referral_name,t_encounter_master.unit_token_number,t_encounter_master.encounter_id,bm.billing_master_id,bm.bill_number,CASEWHEN bm.bill_status_id &lt;&gt; 3 THEN 'Bill Not Generated'::character varyingELSE bsm.bill_status_descEND AS bill_status_desc,modmaster.modality_id,modmaster.modality_desc,bm.bill_status_id,t_encounter_master.follow_up_date,m_appointment_master.app_date_time,sm.doctor_id AS appdoctor,concat('Dr.', appdoctor.first_name, ' ', appdoctor.last_name) AS appdoctorname,concat('Dr.', dd.first_name, ' ', dd.last_name) AS prefdoctorname,m_appointment_master.remark,m_unit_master.image AS unitimageFROM opd.m_appointment_masterLEFT JOIN patient.t_patient_registration ON m_appointment_master.patient_id = t_patient_registration.patient_idLEFT JOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN opd.t_encounter_master ON t_encounter_master.appointment_id = m_appointment_master.appointment_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idJOIN m_organization_master ON t_patient_registration.organization_id = m_organization_master.organization_idJOIN m_unit_master ON m_appointment_master.unit_id = m_unit_master.unit_idLEFT JOIN m_currency_master cm ON m_unit_master.unit_id = cm.unit_idLEFT JOIN adt.m_identification_master ON t_patient_registration.identification_type_id = m_identification_master.identification_idLEFT JOIN m_user_master ON m_appointment_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN opd.m_appointment_status_master appstatus ON m_appointment_master.appointment_status_id = appstatus.appointment_status_idLEFT JOIN doctor.m_doctor_master ON t_encounter_master.doctor_id = m_doctor_master.doctor_idLEFT JOIN m_prefix_master pmm ON pmm.prefix_id = m_doctor_master.prefix_idLEFT JOIN t_referal_details admreff ON t_encounter_master.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN billing.m_billing_master bm ON bm.encounter_id = t_encounter_master.encounter_idLEFT JOIN billing.m_billing_status_master bsm ON bsm.bill_status_id = bm.bill_status_idLEFT JOIN opd.m_slot_master sm ON m_appointment_master.slot_id = sm.slot_idLEFT JOIN doctor.m_doctor_master appdoctor ON sm.doctor_id = appdoctor.doctor_idLEFT JOIN doctor.m_speciality_master ON sm.speciality_id = m_speciality_master.speciality_idLEFT JOIN m_modality_master modmaster ON sm.modality_id = modmaster.modality_idLEFT JOIN doctor.m_doctor_master dd ON t_encounter_master.preferred_doc_id = dd.doctor_id;

