ils.kin_name,m_kin_details.mobile_no,m_relation_master.relation_name,m_kin_details.phone_no,m_kin_details.identification_no,m_kin_details.address,m_kin_details.is_guarantor,m_visit_type_master.visit_type_name,m_patient_category_master.patient_category,t_patient_registration.created_date AS regdate,t_patient_registration.is_vip,t_patient_registration.dob,t_patient_registration.identification_number,t_patient_registration.identification_expiry_date,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,t_patient_details.address AS patientaddress,t_patient_details.zip_code,t_patient_details.phone_number,''::character varying(200) AS source_desc,age(t_patient_registration.dob::date::timestamp with time zone) AS age,m_marital_status_master.marital_status_name,m_payment_entitlement_master.payment_entitlement_desc AS payment_entitlement_type,'Out Patient'::text AS visit_type_lable,'Self'::text AS entitlement_type_lable,t_patient_registration.image,date_part('Year'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone))::integer AS ageyear,abs(date_part('month'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS ageday,unitinformation.image AS hospitalimage,payee.company_desc,t_patient_registration.middle_name AS guardian,COALESCE(qm.qualification_desc, ''::character varying(100)) AS qualification_desc,0::bigint AS enccount,concat('Dr.', dm.first_name, ' ', dm.last_name) AS docname,sponser.employee_no_manual AS username,''::text AS emp_address,''::text AS emp_no,payee.company_idFROM opd.t_encounter_masterLEFT JOIN opd.t_encounter_details ON t_encounter_master.encounter_id = t_encounter_details.encounter_idLEFT JOIN doctor.doctorinformation ON t_encounter_master.encounter_id = doctorinformation.encounter_idLEFT JOIN doctor.m_doctor_master dm ON t_encounter_master.doctor_id = dm.doctor_idJOIN patient.t_patient_registration ON t_encounter_master.patient_id = t_patient_registration.patient_idJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idJOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_kin_details ON t_encounter_master.kin_details_id = m_kin_details.kin_idLEFT JOIN m_visit_type_master ON t_encounter_master.visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idLEFT JOIN patient.m_patient_registration_type_master ON t_patient_registration.registration_type_id = m_patient_registration_type_master.idLEFT JOIN m_relation_master ON m_kin_details.relation_id = m_relation_master.relation_idLEFT JOIN m_unit_master unitinformation ON t_encounter_master.unit_id = unitinformation.unit_idLEFT JOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idLEFT JOIN m_marital_status_master ON t_patient_details.marital_status_id = m_marital_status_master.marital_status_idLEFT JOIN m_payment_entitlement_master ON t_encounter_master.payment_entitlement_type_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN opd.t_patient_sponsor_details sponser ON t_encounter_master.encounter_id = sponser.encounter_id AND sponser.priority_id = 1 AND sponser.status = 'A'::bpcharLEFT JOIN t_company_master payee ON sponser.payee_id = payee.company_id AND sponser.priority_id = 1 AND sponser.status = 'A'::bpcharLEFT JOIN m_qualification_master qm ON doctorinformation.doctor_id = qm.qualification_idLEFT JOIN m_user_master ON m_user_master.user_id = t_encounter_master.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_id;

