ty_id,m_gender_master.gender_name,m_kin_details.kin_name,m_kin_details.mobile_no,m_relation_master.relation_name,m_kin_details.phone_no,m_kin_details.identification_no,m_kin_details.address,m_kin_details.is_guarantor,m_visit_type_master.visit_type_name,m_patient_category_master.patient_category,t_patient_registration.created_date AS regdate,t_patient_registration.is_vip,t_patient_registration.dob,t_patient_registration.identification_number,t_patient_registration.identification_expiry_date,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,ccm.currency_name,ccm.sub_currency,t_patient_details.address AS patientaddress,t_patient_details.zip_code,t_patient_details.phone_number,m_source_master.source_desc,age(t_patient_registration.dob::date::timestamp with time zone) AS age,m_marital_status_master.marital_status_name,m_payment_entitlement_master.payment_entitlement_desc AS payment_entitlement_type,'Out Patient'::text AS visit_type_lable,'Self'::text AS entitlement_type_lable,t_patient_registration.image,date_part('Year'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone))::integer AS ageyear,abs(date_part('month'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS ageday,unitinformation.image AS hospitalimage,payee.company_desc,t_patient_registration.middle_name AS guardian,COALESCE(qm.qualification_desc, ''::character varying(100)) AS qualification_desc,0::bigint AS enccount,concat('Dr. ', dm.first_name, ' ', dm.last_name) AS docname,sponser.employee_no_manual AS username,m_employee_details.address AS emp_address,m_employee_master.registration_number AS emp_no,m_speciality_master.speciality_name,sponser.employee_name,sponser.relation,m_refferel.referral_name,dm.doctor_id AS opdoctorid,CASEWHEN sponser.payment_entitlement_id = 1 THEN t_encounter_master.encounter_date::date + 15ELSE t_encounter_master.encounter_date::date + 7END AS nextvisit_date,t_patient_registration.blood_group,concat('Dr.', dd.first_name, ' ', dd.middle_name, ' ', dd.last_name) AS consultdoctorname,m_occupation_master.occupation_nameFROM opd.t_encounter_masterLEFT JOIN opd.t_encounter_details ON t_encounter_master.encounter_id = t_encounter_details.encounter_idLEFT JOIN doctor.m_doctor_master dm ON t_encounter_master.doctor_id = dm.doctor_idLEFT JOIN t_referal_details admreff ON t_encounter_master.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN patient.t_patient_registration ON t_encounter_master.patient_id = t_patient_registration.patient_idJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idJOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_kin_details ON t_encounter_master.kin_details_id = m_kin_details.kin_idLEFT JOIN m_visit_type_master ON t_encounter_master.system_generated_visit_type_id = m_visit_type_master.visit_type_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idLEFT JOIN patient.m_patient_registration_type_master ON t_patient_registration.registration_type_id = m_patient_registration_type_master.idLEFT JOIN m_relation_master ON m_kin_details.relation_id = m_relation_master.relation_idJOIN m_unit_master unitinformation ON t_encounter_master.unit_id = unitinformation.unit_idLEFT JOIN m_currency_master ccm ON ccm.unit_id = t_encounter_master.unit_idJOIN m_organization_master ON t_encounter_master.organization_id = m_organization_master.organization_idJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idLEFT JOIN m_source_master ON t_encounter_master.source_id = m_source_master.source_idLEFT JOIN m_marital_status_master ON t_patient_details.marital_status_id = m_marital_status_master.marital_status_idLEFT JOIN m_payment_entitlement_master ON t_encounter_master.payment_entitlement_type_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN opd.t_patient_sponsor_details sponser ON t_encounter_master.encounter_id = sponser.encounter_id AND sponser.priority_id = 1 AND sponser.status = 'A'::bpcharLEFT JOIN t_company_master payee ON sponser.payee_id = payee.company_id AND sponser.priority_id = 1 AND sponser.status = 'A'::bpcharLEFT JOIN m_qualification_master qm ON dm.qualification_id = qm.qualification_idLEFT JOIN m_user_master ON m_user_master.user_id = t_encounter_master.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_employee_details ON m_employee_master.employee_id = m_employee_details.employee_idLEFT JOIN doctor.m_speciality_master ON m_speciality_master.speciality_id = t_encounter_master.dept_idLEFT JOIN doctor.m_doctor_master dd ON t_encounter_master.preferred_doc_id = dd.doctor_idLEFT JOIN m_occupation_master ON m_occupation_master.occupation_id = t_patient_registration.occupation_id;

-- opd.getvital source
CREATE OR REPLACE VIEW opd.getvitalAS SELECT t_vital.created_by,t_vital.created_date,m_vital_master.vital_name,t_vital.value,m_vital_master.unit,CASEWHEN COALESCE(dm.user_id, 0) = 0 THEN (m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::textELSE (('Dr.'::text || ''::text) || (dm.first_name::text || ' '::text)) || dm.last_name::textEND AS doctorname,t_vital.encounter_idFROM patient.t_appointment_vital_mapper t_vitalLEFT JOIN emr.m_vital_master ON t_vital.vital_id = m_vital_master.vital_idLEFT JOIN doctor.m_doctor_master dm ON t_vital.created_by = dm.user_idLEFT JOIN m_user_master um ON t_vital.created_by = um.user_idLEFT JOIN m_employee_master ON um.user_id = m_employee_master.user_idWHERE t_vital.value::text &lt;&gt; ''::text AND t_vital.is_entered_in_error = 'N'::bpchar AND t_vital.is_post_facto = 'N'::bpchar;

-- opd.patientcard source
CREATE OR REPLACE VIEW opd.patientcardAS SELECT t_patient_registration.patient_id,(((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,m_gender_master.gender_name,t_patient_registration.bar_code,t_patient_registration.is_vip,age(t_patient_registration.dob) AS age,t_patient_registration.country_calling_code,t_patient_registration.mobile_number,t_patient_registration.email,t_patient_registration.uhid_numberFROM patient.t_patient_registrationLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_id;-- DROP SCHEMA otims;
