-- otims.get_ot_register source
CREATE OR REPLACE VIEW otims.get_ot_registerAS SELECT DISTINCT reqmst.pro_req_id,pim.uhid_number,concat(pm.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,reqmst.visit_type_id,visittype.visit_type_name,um.user_name AS username,reqmst.primary_procedure_id,servicemaster.service_standard_name AS procedurename,typemaster.procedure_type_desc,anes_type.anesthesia_type_desc,tabletype.table_desc,time_sheet.procedure_start_time,time_sheet.procedure_end_time,reqmst.ot_bill_completion_date_time,typemaster.procedure_type_id,unit.unit_name,unit.unit_address,ordermaster.amount,rolemaster.procedure_role_name,unit.unit_id,unit.image,reqmst.admission_id,proc_config.service_id,sp.speciality_nameFROM otims.t_procedure_req_mst reqmstJOIN patient.t_patient_registration pim ON reqmst.patient_id = pim.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pim.prefix_idJOIN m_visit_type_master visittype ON reqmst.visit_type_id = visittype.visit_type_idLEFT JOIN m_user_master um ON reqmst.request_by = um.user_idLEFT JOIN otims.t_procedure_order_master ordermaster ON reqmst.pro_req_id = ordermaster.pro_req_idLEFT JOIN otims.t_procedure_order_service orderservice ON reqmst.pro_req_id = orderservice.procedure_request_id AND reqmst.primary_procedure_id = orderservice.service_idLEFT JOIN service.m_service_master servicemaster ON ordermaster.service_id = servicemaster.service_master_idLEFT JOIN otims.t_procedure_configuration proc_config ON servicemaster.service_master_id = proc_config.service_idLEFT JOIN doctor.m_speciality_master sp ON sp.speciality_id = servicemaster.speciality_idLEFT JOIN otims.m_procedure_type_master typemaster ON proc_config.procedure_type_id = typemaster.procedure_type_idLEFT JOIN otims.m_anesthesia_type_master anes_type ON proc_config.anesthesia_type_id = anes_type.anesthesia_type_idLEFT JOIN otims.m_operation_table_type tabletype ON proc_config.operation_theatre_type_id = tabletype.operation_table_type_idLEFT JOIN otims.t_ot_completion_time_sheet time_sheet ON reqmst.pro_req_id = time_sheet.pro_req_idLEFT JOIN m_unit_master unit ON reqmst.unit_id = unit.unit_idLEFT JOIN otims.t_ot_completion_staff staff ON reqmst.pro_req_id = staff.proc_req_idLEFT JOIN otims.m_procedure_role_master rolemaster ON staff.service_id = rolemaster.procedure_role_id;

-- otims.get_ot_register_completed source
CREATE OR REPLACE VIEW otims.get_ot_register_completedAS SELECT DISTINCT reqmst.pro_req_id,pim.uhid_number,pim.patientname,reqmst.visit_type_id,visittype.visit_type_name,um.user_name AS username,reqmst.primary_procedure_id,servicemaster.service_standard_name AS procedurename,typemaster.procedure_type_desc,anes_type.anesthesia_type_desc,tabletype.table_desc,time_sheet.procedure_start_time,time_sheet.procedure_end_time,reqmst.ot_bill_completion_date_time,typemaster.procedure_type_id,unit.unit_name,unit.unit_address,ordermaster.amount,rolemaster.role_name,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctor,staff.created_date::date AS staffcompletiondate,unit.unit_id,unit.imageFROM otims.t_procedure_req_mst reqmstJOIN patientinformation pim ON reqmst.patient_id = pim.patient_idJOIN m_visit_type_master visittype ON reqmst.visit_type_id = visittype.visit_type_idLEFT JOIN m_user_master um ON reqmst.request_by = um.user_idLEFT JOIN otims.t_procedure_order_master ordermaster ON reqmst.pro_req_id = ordermaster.pro_req_idLEFT JOIN otims.t_procedure_order_service orderservice ON reqmst.pro_req_id = orderservice.procedure_request_id AND reqmst.primary_procedure_id = orderservice.service_idLEFT JOIN service.m_service_master servicemaster ON reqmst.primary_procedure_id = servicemaster.service_master_idLEFT JOIN otims.t_procedure_configuration proc_config ON servicemaster.service_master_id = proc_config.service_idLEFT JOIN otims.m_procedure_type_master typemaster ON proc_config.procedure_type_id = typemaster.procedure_type_idLEFT JOIN otims.m_anesthesia_type_master anes_type ON proc_config.anesthesia_type_id = anes_type.anesthesia_type_idLEFT JOIN otims.m_operation_table_type tabletype ON proc_config.operation_theatre_type_id = tabletype.operation_table_type_idLEFT JOIN otims.t_ot_completion_time_sheet time_sheet ON reqmst.pro_req_id = time_sheet.pro_req_idLEFT JOIN unitinformation unit ON reqmst.unit_id = unit.unit_idJOIN otims.t_ot_completion_staff staff ON reqmst.pro_req_id = staff.proc_req_idLEFT JOIN doctor.m_doctor_master docmaster ON staff.doctor_id = docmaster.doctor_idLEFT JOIN otims.t_procedure_staff_schedule staff_schedule ON reqmst.pro_req_id = staff_schedule.pro_req_idLEFT JOIN m_role_master rolemaster ON staff_schedule.role_id = rolemaster.role_idWHERE ordermaster.is_primary_secondary = 'Y'::"char";

-- otims.get_ot_reservation source
CREATE OR REPLACE VIEW otims.get_ot_reservationAS SELECT DISTINCT otr.ot_reservation_id,otr.ot_reservation_no,pim.patient_id,pim.patientname,theatre.theatre_name,ottable.table_name,staffschedule.created_date,staffschedule.f_time,visittype.visit_type_name,servicemaster.service_standard_name,om.is_primary_secondary,fordoctor.user_id,fordoctor.doctor,um.unit_name,um.unit_address,um.unit_id,um.imageFROM otims.t_ot_reservation otrJOIN patientinformation pim ON otr.patient_id = pim.patient_idJOIN otims.t_procedure_ot_schedule staffschedule ON otr.schedule_id = staffschedule.procedure_schedule_idJOIN otims.m_operation_theatre theatre ON staffschedule.theatre_id = theatre.operation_theatre_idJOIN otims.m_operation_table ottable ON staffschedule.table_id = ottable.operation_table_idJOIN otims.t_procedure_req_mst reqmaster ON otr.pro_req_id = reqmaster.pro_req_idJOIN m_visit_type_master visittype ON reqmaster.visit_type_id = visittype.visit_type_idJOIN otims.t_procedure_order_master om ON om.pro_req_id = otr.pro_req_idJOIN service.m_service_master servicemaster ON om.service_id = servicemaster.service_master_idLEFT JOIN otims.t_procedure_order_staff orderstaff ON orderstaff.procedure_order_id = om.procedure_order_idLEFT JOIN m_unit_master um ON otr.unit_id = um.unit_idLEFT JOIN ( SELECT DISTINCT doctorsched.pro_req_id,doctorsched.user_id,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctorFROM otims.t_procedure_staff_schedule doctorschedLEFT JOIN doctor.m_doctor_master docmaster ON doctorsched.user_id = docmaster.user_idWHERE doctorsched.role_id = 3) fordoctor ON otr.pro_req_id = fordoctor.pro_req_id;

-- otims.get_otprocedure_details source
CREATE OR REPLACE VIEW otims.get_otprocedure_detailsAS SELECT DISTINCT pr.uhid_number AS uhidnumber,concat(COALESCE(prefix_mst.prefix_code), ' ', COALESCE(pr.first_name), ' ', COALESCE(pr.last_name)) AS "patientName",pr.patient_id AS patientid,to_char(adtdtls.doa, 'dd/MM/yyyy'::text) AS doa,to_char(adtdtls.pdd, 'dd/MM/yyyy'::text) AS pdd,to_char(pr.dob, 'DD/MM/YYYY'::text) AS birthdate,prm.admission_id AS admissionid,prm.encounter_id AS encounterid,prm.pro_req_id AS proreqid,bm.bed_number AS bednumber,ward.ward_name AS wardname,prm.visit_type_id AS visittypeid,to_char(prm.prefered_time::interval, 'hh24:mi:ss'::text) AS prefertime,gender.gender_code AS gendercode,concat(date_part('year'::text, age(CURRENT_TIMESTAMP, pr.dob::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, pr.dob::timestamp with time zone)), 'M ') AS age,to_char(prm.prefered_date_time, 'DD-MM-YYYY'::text) AS scheduledate,prm.procedure_status_id AS proceduerstatusid,prost.status AS procedurestatusname,prm.emergency,otdetails.total_hrs AS totalduration,servicemaster.service_standard_name AS procedurename,staff.doctor,staff.service_standard_name AS servicename,ordermaster.is_primary_secondary,proctype.procedure_type_desc,servicemaster1.service_standard_name AS servicedetail,proctype.procedure_type_id,prm.visit_type_id,prm.primary_procedure_id,anesthesia.anesthesia_type_name,tbl.table_name,otdetails.ot_sheet_no,unitmaster.unit_name,unitmaster.unit_address,staff.role_id,prm.unit_id,staff.doctor_id,staff.speciality_name,staff.speciality_id,prm.ot_bill_completion_date_time,prm.created_date,unitmaster.imageFROM otims.t_procedure_req_mst prmJOIN otims.m_procedure_order_status prost ON prm.procedure_status_id = prost.idJOIN otims.t_ot_completion_details otdetails ON otdetails.pro_req_id = prm.pro_req_idLEFT JOIN otims.m_operation_table tbl ON otdetails.ot_table_id = tbl.operation_table_idJOIN patient.t_patient_registration pr ON prm.patient_id = pr.patient_idJOIN m_prefix_master prefix_mst ON pr.prefix_id = prefix_mst.prefix_idLEFT JOIN adt.t_admission admission ON prm.admission_id = admission.admission_idLEFT JOIN adt.t_admission_details adtdtls ON admission.admission_id = adtdtls.admission_id AND adtdtls.status = 'A'::bpcharLEFT JOIN adt.m_bed_master bm ON adtdtls.bed_id = bm.bed_idLEFT JOIN adt.m_ward_master ward ON bm.ward_id = ward.ward_idLEFT JOIN opd.t_encounter_master encounter ON prm.encounter_id = encounter.encounter_idJOIN m_gender_master gender ON pr.gender_id = gender.gender_idLEFT JOIN unitinformation unitmaster ON prm.unit_id = unitmaster.unit_idLEFT JOIN otims.t_procedure_order_master ordermaster ON prm.pro_req_id = ordermaster.pro_req_idLEFT JOIN otims.t_procedure_order_service orderservice ON prm.pro_req_id = orderservice.procedure_request_idLEFT JOIN service.m_service_master servicemaster ON ordermaster.service_id = servicemaster.service_master_idLEFT JOIN service.m_service_master servicemaster1 ON orderservice.service_id = servicemaster1.service_master_idLEFT JOIN otims.t_procedure_configuration proc_config ON servicemaster.service_master_id = proc_config.service_idLEFT JOIN otims.m_procedure_type_master proctype ON proc_config.procedure_type_id = proctype.procedure_type_idLEFT JOIN otims.m_anesthesia_type_master anesthesia ON proc_config.anesthesia_type_id = anesthesia.anesthesia_type_idLEFT JOIN ( SELECT staff_1.proc_req_id,rolemaster.role_name,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctor,servicemaster_1.service_standard_name,rolemaster.role_id,docmaster.doctor_id,sm.speciality_name,sm.speciality_idFROM otims.t_ot_completion_staff staff_1JOIN doctor.m_doctor_master docmaster ON staff_1.doctor_id = docmaster.doctor_idJOIN otims.t_procedure_staff_schedule staff_schedule ON staff_1.proc_req_id = staff_schedule.pro_req_idLEFT JOIN m_role_master rolemaster ON staff_schedule.role_id = rolemaster.role_idLEFT JOIN service.m_service_master servicemaster_1 ON staff_1.service_id = servicemaster_1.service_master_idLEFT JOIN doctor.m_speciality_master sm ON servicemaster_1.speciality_id = sm.speciality_id) staff ON prm.pro_req_id = staff.proc_req_idWHERE (prm.procedure_status_id = ANY (ARRAY[2, 3, 4])) AND prm.emergency = true AND ordermaster.status = 'A'::bpcharUNIONSELECT DISTINCT pr.uhid_number AS uhidnumber,concat(COALESCE(prefix_mst.prefix_code), ' ', COALESCE(pr.first_name), ' ', COALESCE(pr.last_name)) AS "patientName",pr.patient_id AS patientid,to_char(adtdtls.doa, 'dd/MM/yyyy'::text) AS doa,to_char(adtdtls.pdd, 'dd/MM/yyyy'::text) AS pdd,to_char(pr.dob, 'DD/MM/YYYY'::text) AS birthdate,prm.admission_id AS admissionid,prm.encounter_id AS encounterid,prm.pro_req_id AS proreqid,bm.bed_number AS bednumber,ward.ward_name AS wardname,prm.visit_type_id AS visittypeid,to_char(prm.prefered_time::interval, 'hh24:mi:ss'::text) AS prefertime,gender.gender_code AS gendercode,concat(date_part('year'::text, age(CURRENT_TIMESTAMP, pr.dob::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, pr.dob::timestamp with time zone)), 'M ') AS age,to_char(prm.prefered_date_time, 'DD-MM-YYYY'::text) AS scheduledate,prm.procedure_status_id AS proceduerstatusid,prost.status AS procedurestatusname,prm.emergency,0 AS totalduration,servicemaster.service_standard_name AS procedurename,staff.doctor,staff.service_standard_name AS servicename,ordermaster.is_primary_secondary,proctype.procedure_type_desc,servicemaster1.service_standard_name AS servicedetail,proctype.procedure_type_id,prm.visit_type_id,prm.primary_procedure_id,anesthesia.anesthesia_type_name,tbl.table_name,''::text AS ot_sheet_no,unitmaster.unit_name,unitmaster.unit_address,staff.role_id,prm.unit_id,staff.doctor_id,staff.speciality_name,staff.speciality_id,prm.ot_bill_completion_date_time,prm.created_date,unitmaster.imageFROM otims.t_procedure_req_mst prmJOIN otims.t_procedure_schedule schedule ON prm.pro_req_id = schedule.pro_req_idJOIN otims.m_procedure_order_status prost ON prm.procedure_status_id = prost.idJOIN otims.t_procedure_configuration proconfig ON prm.primary_procedure_id = proconfig.service_idJOIN otims.t_procedure_ot_schedule otdetails ON schedule.procedure_schedule_id = otdetails.procedure_schedule_idJOIN otims.m_operation_theatre ot ON otdetails.theatre_id = ot.operation_theatre_idJOIN otims.m_operation_table tbl ON otdetails.table_id = tbl.operation_table_idLEFT JOIN doctor.m_doctor_master doc ON doc.user_id = prm.created_byJOIN patient.t_patient_registration pr ON prm.patient_id = pr.patient_idJOIN m_prefix_master prefix_mst ON pr.prefix_id = prefix_mst.prefix_idLEFT JOIN adt.t_admission admission ON prm.admission_id = admission.admission_idLEFT JOIN adt.t_admission_details adtdtls ON admission.admission_id = adtdtls.admission_id AND adtdtls.status = 'A'::bpcharLEFT JOIN adt.m_bed_master bm ON adtdtls.bed_id = bm.bed_idLEFT JOIN adt.m_ward_master ward ON bm.ward_id = ward.ward_idLEFT JOIN opd.t_encounter_master encounter ON prm.encounter_id = encounter.encounter_idJOIN m_gender_master gender ON pr.gender_id = gender.gender_idLEFT JOIN unitinformation unitmaster ON prm.unit_id = unitmaster.unit_idLEFT JOIN otims.t_procedure_order_master ordermaster ON prm.pro_req_id = ordermaster.pro_req_idLEFT JOIN otims.t_procedure_order_service orderservice ON prm.pro_req_id = orderservice.procedure_request_idLEFT JOIN service.m_service_master servicemaster ON ordermaster.service_id = servicemaster.service_master_idLEFT JOIN service.m_service_master servicemaster1 ON orderservice.service_id = servicemaster1.service_master_idLEFT JOIN otims.t_procedure_configuration proc_config ON servicemaster.service_master_id = proc_config.service_idLEFT JOIN otims.m_procedure_type_master proctype ON proc_config.procedure_type_id = proctype.procedure_type_idLEFT JOIN otims.m_anesthesia_type_master anesthesia ON proc_config.anesthesia_type_id = anesthesia.anesthesia_type_idLEFT JOIN ( SELECT staff_1.proc_req_id,rolemaster.role_name,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctor,servicemaster_1.service_standard_name,rolemaster.role_id,docmaster.doctor_id,sm.speciality_name,sm.speciality_idFROM otims.t_ot_completion_staff staff_1JOIN doctor.m_doctor_master docmaster ON staff_1.doctor_id = docmaster.doctor_idJOIN otims.t_procedure_staff_schedule staff_schedule ON staff_1.proc_req_id = staff_schedule.pro_req_idLEFT JOIN m_role_master rolemaster ON staff_schedule.role_id = rolemaster.role_idLEFT JOIN service.m_service_master servicemaster_1 ON staff_1.service_id = servicemaster_1.service_master_idLEFT JOIN doctor.m_speciality_master sm ON servicemaster_1.speciality_id = sm.speciality_id) staff ON prm.pro_req_id = staff.proc_req_idWHERE (prm.procedure_status_id = ANY (ARRAY[2, 3, 4])) AND schedule.status = 'A'::bpchar AND otdetails.status = 'A'::bpchar AND ordermaster.status = 'A'::bpchar AND prm.emergency = falseORDER BY 1, 24 DESC;

-- otims.get_otsummary source
CREATE OR REPLACE VIEW otims.get_otsummaryAS SELECT reqmst.pro_req_id,pim.uhid_number,concat(pm.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,gm.gender_name,age(pim.dob) AS age,pd.address AS patientaddress,pim.mobile_number,visittype.visit_type_name,CASEWHEN reqmst.encounter_id IS NULL THEN ta.admission_numberELSE tem.encounter_numberEND AS admno_visitno,CASEWHEN reqmst.encounter_id IS NULL THEN tad.doaELSE tem.encounter_dateEND AS adm_visit_date,reqmst.encounter_id,reqmst.admission_id,wm.ward_name,td.discharge_date,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) AS admittingdrname,concat('Dr.', ' ', tr_doctormaster.first_name, ' ', tr_doctormaster.last_name) AS tri_doctorname,concat('Dr.', ' ', en_doctormaster.first_name, ' ', en_doctormaster.last_name) AS encounter_doctorname,unitinformation.unit_name,unitinformation.image,unitinformation.unit_address,unitinformation.unit_contact,unitinformation.unit_email_id,( SELECT COALESCE(count(tocs.ot_completion_staff_id), 0::bigint) AS countFROM otims.t_ot_completion_staff tocsWHERE tocs.proc_req_id = reqmst.pro_req_id) AS cnt_billifmaterial,( SELECT count(toce.ot_completion_equipment_id) AS countFROM otims.t_ot_completion_equipment toceWHERE toce.pro_req_id = reqmst.pro_req_id) AS cnt_equipment,otdetails.ot_date,unitinformation.unit_idFROM otims.t_procedure_req_mst reqmstJOIN patient.t_patient_registration pim ON reqmst.patient_id = pim.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pim.prefix_idJOIN m_gender_master gm ON gm.gender_id = pim.gender_idJOIN patient.t_patient_details pd ON pd.patient_id = pim.patient_idLEFT JOIN m_visit_type_master visittype ON reqmst.visit_type_id = visittype.visit_type_idLEFT JOIN adt.t_admission ta ON reqmst.admission_id = ta.admission_idLEFT JOIN adt.t_admission_details tad ON tad.admission_id = ta.admission_id AND tad.status = 'A'::bpcharLEFT JOIN adt.m_ward_master wm ON wm.ward_id = tad.ward_idLEFT JOIN opd.t_encounter_master tem ON tem.encounter_id = reqmst.encounter_idLEFT JOIN adt.t_discharge td ON td.admission_id = ta.admission_idLEFT JOIN doctor.m_doctor_master doctormaster ON ta.admitting_doctor_id = doctormaster.doctor_idLEFT JOIN doctor.m_doctor_master tr_doctormaster ON ta.doctor_id = tr_doctormaster.doctor_idLEFT JOIN doctor.m_doctor_master en_doctormaster ON tem.doctor_id = en_doctormaster.doctor_idLEFT JOIN otims.t_ot_completion_details otdetails ON otdetails.pro_req_id = reqmst.pro_req_idJOIN m_unit_master unitinformation ON unitinformation.unit_id = reqmst.unit_id;-- DROP SCHEMA patient;
