-- patient.groupwise_receipt_report source
CREATE OR REPLACE VIEW patient.groupwise_receipt_reportAS SELECT DISTINCT bd.service_id,sm.service_standard_name,bd.rate,bd.quantity,bd.concession,bd.gross_amount,bd.co_pay_percentage,bd.unit_id,bd.created_by,bd.created_date,bd.discount,bd.tax_amount,bd.net_amt,bd.self_payable,em.encounter_number,em.encounter_date,sm.speciality_id,dsm.speciality_name,ssm.sub_speciality_id,ssm.sub_speciality_name,ad.admission_id,bm.patient_id,(((pm.prefix_desc || ' '::text) || pr.first_name::text) || pr.middle_name::text) || pr.last_name::text AS patient_name,bm.visit_type_id,vtm.visit_type_name,bd.billing_details_id,um.user_id,(((upm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,ui.unit_name,ui.unit_address,bm.bill_number,prm.reciept_number,prm.date_of_reciept,prm.amountFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idLEFT JOIN service.m_service_master sm ON bd.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN doctor.m_speciality_master dsm ON sm.speciality_id = dsm.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN adt.t_admission ad ON bm.admission_id = ad.admission_idLEFT JOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idLEFT JOIN m_user_master um ON bd.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master upm ON emp.prefix_id = upm.prefix_idLEFT JOIN unitinformation ui ON bd.unit_id = ui.unit_idLEFT JOIN billing.t_payment_reciept_master prm ON bm.billing_master_id = prm.billing_master_idWHERE bm.bill_status_id = 3ORDER BY bm.bill_number;

-- patient.mis_issue_to_department_list_report source
CREATE OR REPLACE VIEW patient.mis_issue_to_department_list_reportAS SELECT DISTINCT indentmaster.id AS indentid,indentmaster.added_date::date AS added_date,indentmaster.indent_no,storefrom.store_name AS fromstore,storeto.store_name AS tostore,indenttype.type,m_status.status,prioritymaster.priority_desc,storefrom.store_id AS fromstoreid,storeto.store_id AS tostoreid,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,prioritymaster.priority_id,indenttype.id AS typeid,m_status.id AS status_idFROM inventory.t_store_indent indentmasterJOIN inventory.t_store_indent_detail indentdetails ON indentmaster.id = indentdetails.store_indent_idLEFT JOIN m_store storefrom ON indentmaster.from_store_id = storefrom.store_idLEFT JOIN m_store storeto ON indentmaster.to_store_id = storeto.store_idLEFT JOIN inventory.m_indent_type indenttype ON indentmaster.indent_type_id = indenttype.idLEFT JOIN m_status ON indentmaster.status_id = m_status.idLEFT JOIN adt.m_priority_master prioritymaster ON indentmaster.priority_id = prioritymaster.priority_idLEFT JOIN unitinformation ON indentmaster.unit_id = unitinformation.unit_idORDER BY indentmaster.id;

-- patient.mis_issue_to_department_list_report_details source
CREATE OR REPLACE VIEW patient.mis_issue_to_department_list_report_detailsAS SELECT DISTINCT indentmaster.id AS indentid,indentmaster.added_date::date AS added_date,indentmaster.indent_no,storefrom.store_name AS fromstore,storeto.store_name AS tostore,indenttype.type,m_status.status,prioritymaster.priority_desc,storefrom.store_id AS fromstoreid,storeto.store_id AS tostoreid,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,prioritymaster.priority_id,indenttype.id AS typeid,m_status.id AS status_id,'\x'::bytea AS image,m_item.name,uomtype.type AS uomtype,uomunit.unit AS uomunit,indentdetails.indent_quantity,indentdetails.authorized_quantity,indentdetails.pending_quantity,m_item.hsn_code,m_item.id AS itemid,m_item.code,indentdetails.reject_quantity,um.user_id,concat(emp.first_name, ' ', emp.last_name) AS emp,mapper.min_qtyFROM inventory.t_store_indent indentmasterJOIN inventory.t_store_indent_detail indentdetails ON indentmaster.id = indentdetails.store_indent_id AND indentdetails.is_active = trueJOIN m_item ON indentdetails.item_id = m_item.idJOIN m_uom_type uomtype ON indentdetails.uom_type_id = uomtype.idJOIN m_uom_unit uomunit ON indentdetails.uom_unit_id = uomunit.idLEFT JOIN m_store storefrom ON indentmaster.from_store_id = storefrom.store_idLEFT JOIN m_store storeto ON indentmaster.to_store_id = storeto.store_idJOIN m_store_item_mapper mapper ON mapper.item_id = indentdetails.item_id AND indentmaster.from_store_id = mapper.store_idLEFT JOIN inventory.m_indent_type indenttype ON indentmaster.indent_type_id = indenttype.idJOIN m_status ON indentmaster.approval_status_id = m_status.idLEFT JOIN adt.m_priority_master prioritymaster ON indentmaster.priority_id = prioritymaster.priority_idLEFT JOIN m_unit_master unitinformation ON indentmaster.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON um.user_id = indentmaster.added_byLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idWHERE indentmaster.is_active = true AND indentdetails.is_active = true AND indentdetails.is_deleted = false;

-- patient.mis_issue_to_department_list_report_new source
CREATE OR REPLACE VIEW patient.mis_issue_to_department_list_report_newAS SELECT DISTINCT indentmaster.id AS indentid,indentmaster.added_date::date AS added_date,indentmaster.indent_no,storefrom.store_name AS fromstore,storeto.store_name AS tostore,indenttype.type,m_status.status,prioritymaster.priority_desc,storefrom.store_id AS fromstoreid,storeto.store_id AS tostoreid,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,prioritymaster.priority_id,indenttype.id AS typeid,m_status.id AS status_id,unitinformation.imageFROM inventory.t_store_indent indentmasterJOIN inventory.t_store_indent_detail indentdetails ON indentmaster.id = indentdetails.store_indent_idLEFT JOIN m_store storefrom ON indentmaster.from_store_id = storefrom.store_idLEFT JOIN m_store storeto ON indentmaster.to_store_id = storeto.store_idLEFT JOIN inventory.m_indent_type indenttype ON indentmaster.indent_type_id = indenttype.idLEFT JOIN m_status ON indentmaster.status_id = m_status.idLEFT JOIN adt.m_priority_master prioritymaster ON indentmaster.priority_id = prioritymaster.priority_idLEFT JOIN unitinformation ON indentmaster.unit_id = unitinformation.unit_idORDER BY indentmaster.id;

-- patient.mis_patient_charge_detail_report source
CREATE OR REPLACE VIEW patient.mis_patient_charge_detail_reportAS SELECT DISTINCT bm.billing_master_id,bm.encounter_id,bm.visit_type_id,bm.patient_id,bm.bill_number,bm.bill_date_time,bm.net_amount,bm.discount_amount,CASEWHEN bm.is_credit_bill = 'Y'::"char" THEN 'Credit'::textELSE 'Self'::textEND AS credit_paid,bm.unit_id,bm.concession_amount,bm.gst,bm.total_bill_amount,bm.outstanding,bm.round_off,bm.bill_status_id,bm.admission_id,bm.cr_amount,bm.total_self_payable,bm.total_credit_payable,bm.disallowed_amount,bd.service_id,sm.service_standard_name,bd.rate,bd.quantity,bd.concession,bd.gross_amount,bd.discount,bd.tax_per,bd.tax_amount,bd.net_amt,bd.self_payable,bd.credit_payable,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,vtm.visit_type_name,em.encounter_number,em.encounter_date,adm.admission_number,adm.admitting_doctor_id,adm.created_date,((('Dr. '::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS opd_doctor,((('Dr.'::text || ' '::text) || addm.first_name::text) || ' '::text) || addm.last_name::text AS admitting_doctor,CASEWHEN bm.bill_status_id = 1 THEN 'Pending'::textWHEN bm.bill_status_id = 2 THEN 'On Hold'::textELSE 'Settle'::textEND AS bill_status,(((upm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,um.user_id,bd.billing_details_id,u.unit_name,u.unit_addressFROM billing.m_billing_master bmLEFT JOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idLEFT JOIN service.m_service_master sm ON bd.service_id = sm.service_master_idLEFT JOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idLEFT JOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_idLEFT JOIN doctor.m_doctor_master addm ON adm.admitting_doctor_id = addm.doctor_idLEFT JOIN unitinformation u ON bm.unit_id = u.unit_idLEFT JOIN m_user_master um ON bd.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master upm ON emp.prefix_id = upm.prefix_id;

-- patient.mis_pending_purchase_order_report source
CREATE OR REPLACE VIEW patient.mis_pending_purchase_order_reportAS SELECT DISTINCT po.id AS poid,po.unit_id,u.unit_name,u.unit_address,po.vendor_id,ve.name AS vendor_name,s.store_id,s.store_name,po.po_number,po.total_amount,dt.type AS discount_type,po.discount,po.total_discount,po.total_tax_amount,po.total_other_amount,po.net_amount,po.round_off_amount,st.status,po.remark,po.status_id,po.grn_id,(((pm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,po.added_date,po.added_by,um.user_idFROM procurement.t_purchase_order poLEFT JOIN unitinformation u ON po.unit_id = u.unit_idLEFT JOIN m_vendor ve ON po.vendor_id = ve.idLEFT JOIN m_store s ON po.store_id = s.store_idLEFT JOIN m_discount_type dt ON po.discount_type_id = dt.idLEFT JOIN m_status st ON po.status_id = st.idLEFT JOIN m_user_master um ON po.added_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master pm ON emp.prefix_id = pm.prefix_idWHERE po.status_id = 2ORDER BY po.id;

-- patient.mis_ward_wise_monthly_income_report source
CREATE OR REPLACE VIEW patient.mis_ward_wise_monthly_income_reportAS SELECT DISTINCT prm.amount,prm.date_of_reciept,prm.reciept_number,bm.bill_number,bm.bill_date_time,bm.net_amount,adm.admission_id,adm.admission_number,admd.ward_id,wm.ward_name,um.user_id,(((pm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,pmm.payment_mode_id,pmm.payment_mode_desc,prm.unit_id,u.unit_name,u.unit_address,adm.patient_id,(((((ppm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_nameFROM billing.m_billing_master bmLEFT JOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idLEFT JOIN billing.t_payment_reciept_master prm ON bm.billing_master_id = prm.billing_master_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_idLEFT JOIN adt.m_ward_master wm ON admd.ward_id = wm.ward_idLEFT JOIN unitinformation u ON prm.unit_id = u.unit_idLEFT JOIN m_user_master um ON prm.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master pm ON emp.prefix_id = pm.prefix_idLEFT JOIN billing.t_payment_reciept_details prd ON prm.payment_reciept_id = prd.payment_receipt_master_idLEFT JOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idLEFT JOIN patient.t_patient_registration pr ON adm.patient_id = pr.patient_idLEFT JOIN m_prefix_master ppm ON pr.prefix_id = ppm.prefix_idWHERE bm.bill_status_id = 3 AND bm.visit_type_id = 2ORDER BY prm.reciept_number;

-- patient.opdcaspaper source
CREATE OR REPLACE VIEW patient.opdcaspaperAS SELECT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_dateFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN m_general_ledger_master genledmst ON genledmst.general_ledger_id = spc.general_ledger_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idWHERE billmst.visit_type_id = 1;

-- patient.patientinformation source
CREATE OR REPLACE VIEW patient.patientinformationAS SELECT t_patient_registration.prefix_id,t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_gender_master.gender_name,t_patient_registration.bar_code,age(t_patient_registration.dob) AS age,t_patient_registration.mobile_number,t_patient_registration.email,t_patient_registration.mobile_number AS patientmobile,t_patient_registration.email AS patientemail,m_patient_registration_type_master.reg_type,m_gender_master.gender_name AS patientgender,m_patient_category_master.patient_category,t_patient_registration.created_date AS regdate,t_patient_registration.is_vip,t_patient_registration.dob AS patientdob,t_patient_registration.identification_number,t_patient_registration.identification_expiry_date,t_patient_details.address AS patientaddress,t_patient_details.zip_code,t_patient_details.phone_number,t_patient_registration.patient_id,m_marital_status_master.marital_status_name,t_patient_registration.image,m_gender_master.gender_idFROM patient.t_patient_registrationLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idLEFT JOIN patient.m_patient_registration_type_master ON t_patient_registration.registration_type_id = m_patient_registration_type_master.idLEFT JOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idLEFT JOIN m_marital_status_master ON t_patient_details.marital_status_id = m_marital_status_master.marital_status_id;

-- patient.registration source
CREATE OR REPLACE VIEW patient.registrationAS SELECT unit_id,uhid_number,prefix_id,first_name,middle_name,last_name,gender_id,bar_code,vip_remark,is_blacklist,patient_category_id,status,updated_by,updated_date,created_by,created_date,patient_id,is_vip,organization_id,dob,identification_type_id,identification_number,mobile_number,email,country_calling_code,is_unknown_reg,alise_name,identification_expiry_date,occupation_id,registration_type_id,previous_id,is_otc_reg,is_pre_reg,emp_doc_id,emp_dep_type_id,emp_doc_dep_id,image_path,user_id,is_primary,uuidFROM patient.t_patient_registration;-- DROP FUNCTION patient.before_update_patient_diagnosis_appo();
CREATE OR REPLACE FUNCTION patient.before_update_patient_diagnosis_appo()RETURNS triggerLANGUAGE plpgsqlAS $function$BEGINIF (NEW.type &lt;&gt; OLD.type OR NEW.diagnosis_type &lt;&gt; OLD.diagnosis_type) and old.is_deleted='Y' THENINSERT INTO patient.t_patient_diagnosis_appo_mapper(organization_id,unit_id,encounter_id,patient_id,diagnosis_id,type,remark,updated_by,updated_date,status,admission_id,justification_cancel,is_diagnosis_cancel,diagnosis_type,is_deleted)VALUES(OLD.organization_id,OLD.unit_id,old.encounter_id,old.patient_id,old.diagnosis_id,old.type,old.remark,old.updated_by,now(),'I',old.admission_id,old.justification_cancel,old.is_diagnosis_cancel,old.diagnosis_type,'Y');
END IF; RETURN NEW;END;$function$;

