-- pharmacy.get_inpatientissue source
CREATE OR REPLACE VIEW pharmacy.get_inpatientissueAS SELECT DISTINCT pim.uhid_number,pim.patientname,visitmaster.visit_type_name,issue.added_date,prescription.prescription_date,((('Dr.'::text || ' '::text) || doctormaster.first_name::text) || ' '::text) || doctormaster.last_name::text AS doctorname,ward.ward_name,bed.bed_decs,um.unit_id,um.unit_name,um.unit_address,um.imageFROM pharmacy.t_issue issueJOIN pharmacy.t_issue_detail issuedetails ON issue.id = issuedetails.issue_idJOIN pharmacy.t_sale sales ON issue.sale_id = sales.idJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN patientinformation pim ON sales.patient_id = pim.patient_idJOIN m_visit_type_master visitmaster ON issue.visit_type_id = visitmaster.visit_type_idJOIN adt.t_admission admission ON issue.admission_id = admission.admission_idLEFT JOIN adt.t_admission_details admdetails ON admission.admission_id = admdetails.admission_idLEFT JOIN pharmacy.t_prescription prescription ON issue.prescription_id = prescription.idLEFT JOIN doctor.m_doctor_master doctormaster ON issue.doctor_id = doctormaster.doctor_idLEFT JOIN adt.m_ward_master ward ON admdetails.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON admdetails.bed_id = bed.bed_idLEFT JOIN m_unit_master um ON issue.unit_id = um.unit_idWHERE admdetails.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = admission.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1)) AND issuedetails.is_active = true;

-- pharmacy.medicinelist_new source
CREATE OR REPLACE VIEW pharmacy.medicinelist_newAS SELECT t_sale.id,CASEWHEN t_sale.sale_type_id = 1 THEN concat('IP-', t_sale.admission_id)::character varyingELSE t_sale.bill_noEND::character varying(50) AS bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_contact,m_item.hsn_code,t_batch.cop,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,m_store.store_name,m_store.store_id,m_sale_type.type,mpc.classification,t_sale_detail.item_id,mm.name AS manufacturer,m_item.manufacturer_id,t_sale.patient_id,t_sale.visit_type_id,CASEWHEN t_sale.admission_id IS NULL THEN pntmst1.company_descELSE pntmst.company_descEND AS company,CASEWHEN t_sale.admission_id IS NULL THEN 'OPD No'::textELSE 'Adm No'::textEND AS opiplabel,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS issuedby,(((p_m1.prefix_desc || ' '::text) || empm.first_name::text) || ' '::text) || empm.last_name::text AS createdbyFROM pharmacy.t_sale t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_store ON m_store.store_id = t_sale.store_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN pharmacy.m_sale_type ON m_sale_type.id = t_sale.sale_type_idLEFT JOIN m_pharmacological_classification mpc ON mpc.id = m_item.pharmacological_classification_idLEFT JOIN m_manufacturer mm ON mm.id = m_item.manufacturer_idLEFT JOIN m_patient_visit_metadata pntmst ON pntmst.admission_id = t_sale.admission_idLEFT JOIN m_patient_visit_metadata pntmst1 ON pntmst1.encouter_id = t_sale.encounter_idLEFT JOIN m_user_master ON t_sale.added_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN pharmacy.t_prescription tp ON t_sale.prescription_id = tp.idLEFT JOIN m_user_master userm ON tp.added_by = userm.user_idLEFT JOIN m_employee_master empm ON userm.user_id = empm.user_idLEFT JOIN m_prefix_master p_m1 ON empm.prefix_id = p_m1.prefix_idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = true;-- DROP FUNCTION pharmacy.cash(int8);
CREATE OR REPLACE FUNCTION pharmacy.cash(pid bigint)RETURNS bigintLANGUAGE plpgsqlAS $function$DECLARE passed bigint;BEGINSelect sum(t_paymentmode.amount) into passed FROM pharmacy.t_sale t_saleJOIN pharmacy.t_sale_payment_mode t_paymentmode on t_sale.id = t_paymentmode.sale_idjoin public.m_payment_mode_master pm on pm.payment_mode_id = t_paymentmode.payment_mode_idWhere t_sale.id = Pid and t_paymentmode.payment_mode_id = 1;RETURN passed;END;$function$;

