-- DROP FUNCTION pharmacy.t_sale();
CREATE OR REPLACE FUNCTION pharmacy.t_sale()RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, category character varying, generic_id integer, stock_count integer, is_deleted boolean, total_count integer)LANGUAGE plpgsqlAS $function$ declarebeginSelect ss.added_date::date as stock_date,ss.unit_id,ss.organization_id as hospital_id,ss.store_id,g.product_category_id,p.category,i.generic_id,SUM( ss.available_qty):: integer as stock_count,ss.is_deleted,count(ss.id) as total_count from inventory.t_store_stock ss join inventory.t_batch b on b.id = ss.batch_idjoin public.m_item i on i.id = b.item_idjoin public.m_generic g on g.id = i.generic_id join public.m_product_category p on p.id = g.product_category_idWHERE ss. added_date IN (SELECT ss.added_dateFROM inventory.t_store_stock ssWHERE(ss.updated_date::DATE&gt;='2019-01-01' OR ss.added_date::DATE&gt;='2019-12-21')AND ss.is_deleted = False)AND ss.is_deleted = falseGROUP BY ss.unit_id,ss.organization_id,ss.store_id,g.product_category_id,p.category,i.generic_id,ss.is_deleted,cast(ss.added_date as date)order by cast(ss.added_date as date) asc;end;$function$;

-- DROP FUNCTION pharmacy.t_sale(date);
CREATE OR REPLACE FUNCTION pharmacy.t_sale(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, registration_date date, city_id integer, state_id integer, country_id integer, gender_id integer, patient_category_id integer, patient_id integer, age integer, patient_statistics integer, status character)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectpd.unit_id,pd.organization_id,pr.created_date :: date registration_date ,pd.city_id,pd.state_id,pd.country_id,pr.gender_id ,pr.patient_category_id,pr.patient_id,extract (yearfromage(pr.dob)):: integer as age,count(distinct coalesce( pr.patient_id, 0)) :: integer as patient_statistics,pr.statusfrompatient.t_patient_registration prjoin patient.t_patient_details pd onpd.patient_id = pr.patient_idwhere((pr.updated_date::date &gt;= p_dateand pr.updated_date::date &lt; current_date)or (pr.created_date::date &gt;= p_dateand pr.created_date::date &lt; current_date))and pr.registration_type_id = 1group bypr.created_date,pd.unit_id,pd.organization_id,pd.city_id,pd.state_id,pd.country_id,pr.patient_id,pr.patient_category_id,pr.gender_id,pr.status ,age;end;$function$;

-- DROP FUNCTION pharmacy.update_validation();
CREATE OR REPLACE FUNCTION pharmacy.update_validation()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif pharmacy.t_prescription.is_validate is false or pharmacy.t_prescription.is_validate is null thenUPDATE pharmacy.t_prescriptionSET is_validate= true WHERE id = new.id;END IF;RETURN NEW;END;$function$;

