-- DROP SCHEMA "procedure";
CREATE SCHEMA "procedure" AUTHORIZATION "HIS-STAGING";

-- "procedure".get_computestock source
CREATE OR REPLACE VIEW "procedure".get_computestockAS SELECT DISTINCT comstock.id,stoptran.request_no,stoptran.added_date,upstock.upload_no,m_store.store_name,stoptran.start_date_time,stoptran.stop_date_time,um.user_name,m_status.status,m_item.name AS itemname,batch.expiry_date,storestock.available_qty AS applicationstock,comstockdet.approved_quantity,batch.cop,batch.rate,stoptranitemdetails.is_deleted,usd.qty,unit.unit_name,unit.unit_address,unit.imageFROM inventory.t_compute_stock comstockJOIN inventory.t_upload_stock upstock ON comstock.upload_stock_id = upstock.idJOIN inventory.t_compute_stock_detail comstockdet ON comstock.id = comstockdet.compute_stock_idJOIN inventory.t_upload_stock_detail usd ON upstock.id = usd.upload_stock_idJOIN inventory.t_stop_transaction stoptran ON upstock.stop_transaction_id = stoptran.idJOIN inventory.t_stop_transaction_item_detail stoptranitemdetails ON stoptran.id = stoptranitemdetails.stop_transaction_idJOIN inventory.t_batch batch ON stoptranitemdetails.batch_id = batch.idJOIN inventory.t_store_stock storestock ON batch.id = storestock.batch_id AND storestock.store_id = upstock.store_idJOIN m_item ON batch.item_id = m_item.idJOIN m_store ON upstock.store_id = m_store.store_idJOIN m_user_master um ON upstock.added_by = um.user_idJOIN m_status ON comstock.status_id = m_status.idLEFT JOIN m_unit_master unit ON comstock.unit_id = unit.unit_idWHERE comstockdet.is_active = true;

-- "procedure".get_deliveryworklist source
CREATE OR REPLACE VIEW "procedure".get_deliveryworklistAS SELECT DISTINCT issue.id,issue.issue_no,visittype.visit_type_name,issue.added_date,em.created_date AS encounterdate,adm.created_date AS admdate,pres.prescription_no,pim.uhid_number,pim.patientname,pim.gender_name,pim.ageyear,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctorname,wm.ward_name,bedmaster.bed_number,priority.priority_desc,m_status.status,salestatus.status AS salestatus,m_item.name AS itemname,m_generic.name AS generic,presd.order_qty,presd.dis_presribed_qty,uomtype.type AS uomtype,uomunit.unit AS uomunit,stock.available_qty,m_rack.name AS rack,um.unit_name,um.unit_address,batch.batch_no,batch.expiry_date,issue.visit_type_id,m_item.hsn_codeFROM pharmacy.t_issue issueJOIN pharmacy.t_issue_detail issuedetail ON issue.id = issuedetail.issue_idJOIN inventory.t_batch batch ON issuedetail.batch_id = batch.idJOIN m_visit_type_master visittype ON issue.visit_type_id = visittype.visit_type_idLEFT JOIN opd.t_encounter_master em ON issue.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON issue.admission_id = adm.admission_idLEFT JOIN pharmacy.t_prescription pres ON issue.prescription_id = pres.idLEFT JOIN pharmacy.t_prescription_detail presd ON pres.id = presd.prescription_idLEFT JOIN m_item ON presd.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN adt.m_priority_master priority ON pres.priority_id = priority.priority_idLEFT JOIN patientinformation pim ON adm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master docmaster ON issue.doctor_id = docmaster.doctor_idLEFT JOIN ( SELECT t_admission_details.admission_details_id,t_admission_details.admission_id,t_admission_details.ward_id,t_admission_details.bed_idFROM adt.t_admission_detailsORDER BY t_admission_details.admission_details_id DESC) admd ON adm.admission_id = admd.admission_idLEFT JOIN adt.m_ward_master wm ON admd.ward_id = wm.ward_idLEFT JOIN adt.m_bed_master bedmaster ON admd.bed_id = bedmaster.bed_idLEFT JOIN m_status ON issue.status_id = m_status.idLEFT JOIN pharmacy.t_sale sale ON issue.sale_id = sale.idLEFT JOIN m_status salestatus ON sale.status_id = salestatus.idLEFT JOIN pharmacy.t_assign_picker_detail pickerd ON issuedetail.assign_picker_detail_id = pickerd.idLEFT JOIN m_uom_type uomtype ON pickerd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON pickerd.uom_unit_id = uomunit.idLEFT JOIN inventory.t_store_stock stock ON pickerd.batch_id = stock.batch_id AND issue.store_id = stock.store_idLEFT JOIN procurement.t_shelf_item shelf ON pickerd.batch_id = shelf.batch_idLEFT JOIN m_rack ON shelf.rack_id = m_rack.id AND shelf.store_id = issue.store_idLEFT JOIN unitinformation um ON issue.unit_id = um.unit_idWHERE m_item.is_narcotic = true;

-- "procedure".get_expired_stock source
CREATE OR REPLACE VIEW "procedure".get_expired_stockAS SELECT storestock.store_id,m_store.store_name,item.id AS itemid,item.code,item.name,batch.lot_no,batch.batch_no,batch.quantity,batch.cop,batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.image,mg.name AS generic_nameFROM inventory.t_batch batchJOIN m_item item ON batch.item_id = item.idLEFT JOIN m_generic mg ON item.generic_id = mg.idJOIN inventory.t_store_stock storestock ON batch.id = storestock.batch_idJOIN m_store ON storestock.store_id = m_store.store_idLEFT JOIN unitinformation ON batch.unit_id = unitinformation.unit_idORDER BY item.id;

-- "procedure".get_grn source
CREATE OR REPLACE VIEW "procedure".get_grnAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.invoice_number,t_good_receipt_note.invoice_date,t_good_receipt_note.inward_number,t_good_receipt_note.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_good_receipt_note_detail.batch_no,t_good_receipt_note_detail.cop,t_good_receipt_note_detail.mrp,t_good_receipt_note_detail.discount,t_good_receipt_note_detail.tax_percentage,t_good_receipt_note_detail.tax_amount,t_good_receipt_note_detail.total_discount,t_good_receipt_note_detail.total_other_amount AS total_other_amount_detail,t_good_receipt_note_detail.net_amount,m_store.store_id,t_good_receipt_note.total_tax_ammount,COALESCE(t_good_receipt_note.total_other_amount, 0::double precision) AS total_other_amount,t_good_receipt_note_detail.grn_approved_quantity,t_good_receipt_note_detail.grn_received_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,t_good_receipt_note.total_amount,COALESCE(t_good_receipt_note.total_discount, 0::double precision) AS grntotaldiscount,unitinformation.image,unitinformation.unit_id,t_good_receipt_note.added_by,um.user_name,t_good_receipt_note.updated_by,umapproval.user_name AS umapprovaluser,(emp.first_name::text || ' '::text) || emp.last_name::text AS empuser,(empapproval.first_name::text || ' '::text) || empapproval.last_name::text AS empapprovaluser,m_status.status,( SELECT array_to_string(ARRAY( SELECT t_purchase_order.po_numberFROM procurement.t_purchase_orderWHERE t_purchase_order.id = t_good_receipt_note.po_id), ', '::text) AS array_to_string) AS po_number,t_good_receipt_note.is_consignment,t_good_receipt_note.added_date,m_item.hsn_code,t_good_receipt_note_detail.expiry_date,m_item.code,t_good_receipt_note_detail.id AS receipt_note_detail,t_good_receipt_note_detail.total_amount AS item_totalamt,t_good_receipt_note_detail.bonus_received_quantity,t_good_receipt_note.bill_type_name,t_good_receipt_note.round_off,t_good_receipt_note.net_amount AS grnnetamt,m_uom_unit.unit,t_good_receipt_note.remark,muom.conversions,unitinformation.unit_contact,unitinformation.unit_email_id,t_good_receipt_note.pay_due_dateFROM procurement.t_good_receipt_noteJOIN procurement.t_good_receipt_note_detail ON t_good_receipt_note.id = t_good_receipt_note_detail.grn_idJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_item ON t_good_receipt_note_detail.item_id = m_item.idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_store_item_mapper ON t_good_receipt_note_detail.item_id = m_store_item_mapper.item_id AND t_good_receipt_note.is_deleted = falseLEFT JOIN m_unit_master unitinformation ON t_good_receipt_note.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON t_good_receipt_note.added_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_user_master umapproval ON t_good_receipt_note.approved_by = umapproval.user_idLEFT JOIN m_employee_master empapproval ON umapproval.user_id = empapproval.user_idLEFT JOIN m_status ON t_good_receipt_note.approve_status_id = m_status.idLEFT JOIN procurement.t_purchase_order po ON t_good_receipt_note.po_id = po.idLEFT JOIN m_uom_unit ON t_good_receipt_note_detail.grn_uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_of_measurement muom ON t_good_receipt_note_detail.item_id = muom.item_id AND muom.uom_type_id = t_good_receipt_note_detail.grn_uom_type_idWHERE t_good_receipt_note_detail.is_deleted = false AND t_good_receipt_note_detail.is_active = trueORDER BY t_good_receipt_note_detail.id;

-- "procedure".get_grn_list source
CREATE OR REPLACE VIEW "procedure".get_grn_listAS SELECT DISTINCT grn.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.inward_number,grn.inward_date,v.name,st.store_name,grn.store_id,ast.type,rt.type AS request_type,s.status,dt.type AS discount_type,grn.discount,grn.total_amount,grn.total_tax_ammount,grn.total_other_amount,grn.round_off,grn.net_amount,grn.remark,grn.added_date,grn.po_id,grn.unit_id,u.unit_name,u.unit_address,grn.vendor_id,grn.added_by,(((pm.prefix_desc || ' '::text) || em.first_name::text) || ' '::text) || em.last_name::text AS user_name,um.user_id,u.imageFROM procurement.t_good_receipt_note grnLEFT JOIN m_vendor v ON grn.vendor_id = v.idLEFT JOIN unitinformation u ON grn.unit_id = u.unit_idLEFT JOIN m_store st ON grn.store_id = st.store_idLEFT JOIN m_asset_type ast ON grn.asset_type_id = ast.idLEFT JOIN m_request_type rt ON grn.request_id = rt.idLEFT JOIN m_status s ON grn.status_id = s.idLEFT JOIN m_discount_type dt ON grn.discount_type_id = dt.idLEFT JOIN m_user_master um ON grn.added_by = um.user_idLEFT JOIN m_employee_master em ON um.user_id = em.user_idLEFT JOIN m_prefix_master pm ON em.prefix_id = pm.prefix_idORDER BY grn.id;

-- "procedure".get_grn_list_details source
CREATE OR REPLACE VIEW "procedure".get_grn_list_detailsAS SELECT DISTINCT grn.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.inward_number,grn.inward_date,v.name,st.store_name,grn.store_id,ast.type,rt.type AS request_type,s.status,dt.type AS discount_type,grn.discount,grn.total_amount,grn.total_tax_ammount,grn.total_other_amount,grn.round_off,grn.net_amount,grn.remark,grn.added_date,grn.po_id,grn.unit_id,u.unit_name,u.unit_address,grn.vendor_id,grn.added_by,(((pm.prefix_desc || ' '::text) || em.first_name::text) || ' '::text) || em.last_name::text AS user_name,um.user_id,u.image,m_item.name AS itemname,m_item.id AS itemid,grndetails.grn_approved_quantity,grndetails.grn_received_quantity,grndetails.cop,grndetails.expiry_date,grndetails.mrp,grndetails.tax_percentage,grndetails.tax_amount,grndetails.total_amount AS totalamountdetails,grndetails.total_discount AS discountdetails,grndetails.net_amount AS netamountdetails,batch.batch_no,m_item.hsn_code,grndetails.lot_number,grndetails.grn_lease_quantity,grndetails.bonus_lease_quantity,COALESCE(CASEWHEN grndetails.grn_uom_type_id = 1 THEN uommapper1.conversionsWHEN grndetails.grn_uom_type_id = 2 THEN uommapper2.conversionsWHEN grndetails.grn_uom_type_id = 3 THEN uommapper3.conversionsELSE NULL::integerEND, 0) AS pack,batch.cop AS epr,grndetails.discount AS disper,grndetails.bonus_received_quantity,grn.approve_status_id,grndetails.id AS grndetailsid,po.po_number,grn.is_consignment,grn.bill_type_nameFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail grndetails ON grn.id = grndetails.grn_id AND grndetails.is_active = trueJOIN inventory.t_batch batch ON grndetails.batch_id = batch.idLEFT JOIN inventory.t_batch_uom_mapper uommapper1 ON grndetails.batch_id = uommapper1.batch_id AND uommapper1.uom_type_id = 1LEFT JOIN inventory.t_batch_uom_mapper uommapper2 ON grndetails.batch_id = uommapper2.batch_id AND uommapper2.uom_type_id = 2LEFT JOIN inventory.t_batch_uom_mapper uommapper3 ON grndetails.batch_id = uommapper3.batch_id AND uommapper3.uom_type_id = 3JOIN m_item ON grndetails.item_id = m_item.idLEFT JOIN m_vendor v ON grn.vendor_id = v.idLEFT JOIN m_unit_master u ON grn.unit_id = u.unit_idLEFT JOIN m_store st ON grn.store_id = st.store_idLEFT JOIN m_asset_type ast ON grn.asset_type_id = ast.idLEFT JOIN m_request_type rt ON grn.request_id = rt.idLEFT JOIN m_status s ON grn.approve_status_id = s.idLEFT JOIN procurement.t_purchase_order po ON po.id = grn.po_idLEFT JOIN m_discount_type dt ON grn.discount_type_id = dt.idLEFT JOIN m_user_master um ON grn.added_by = um.user_idLEFT JOIN m_employee_master em ON um.user_id = em.user_idLEFT JOIN m_prefix_master pm ON em.prefix_id = pm.prefix_idWHERE grndetails.is_active = true AND grndetails.is_deleted = false;

-- "procedure".get_grn_nikhil source
CREATE OR REPLACE VIEW "procedure".get_grn_nikhilAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.invoice_number,t_good_receipt_note.invoice_date,t_good_receipt_note.inward_number,t_good_receipt_note.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_good_receipt_note_detail.batch_no,t_good_receipt_note_detail.cop,t_good_receipt_note_detail.mrp,t_good_receipt_note_detail.discount,t_good_receipt_note_detail.tax_percentage,t_good_receipt_note_detail.tax_amount,t_good_receipt_note_detail.total_discount,t_good_receipt_note_detail.total_other_amount AS total_other_amount_detail,t_good_receipt_note_detail.net_amount,m_store.store_id,t_good_receipt_note.total_tax_ammount,COALESCE(t_good_receipt_note.total_other_amount, 0::double precision) AS total_other_amount,t_good_receipt_note_detail.grn_approved_quantity,t_good_receipt_note_detail.grn_received_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,t_good_receipt_note.total_amount,COALESCE(t_good_receipt_note.total_discount, 0::double precision) AS grntotaldiscount,unitinformation.image,unitinformation.unit_id,t_good_receipt_note.added_by,um.user_name,t_good_receipt_note.updated_by,umapproval.user_name AS umapprovaluser,(emp.first_name::text || ' '::text) || emp.last_name::text AS empuser,(empapproval.first_name::text || ' '::text) || empapproval.last_name::text AS empapprovaluser,m_status.status,( SELECT array_to_string(ARRAY( SELECT t_purchase_order.po_numberFROM procurement.t_purchase_orderWHERE t_purchase_order.id = t_good_receipt_note.po_id), ', '::text) AS array_to_string) AS po_number,t_good_receipt_note.is_consignment,t_good_receipt_note.added_date,m_item.hsn_code,t_good_receipt_note_detail.expiry_date,m_item.code,t_good_receipt_note_detail.id AS receipt_note_detail,t_good_receipt_note_detail.total_amount AS item_totalamt,t_good_receipt_note_detail.bonus_received_quantity,t_good_receipt_note.bill_type_name,t_good_receipt_note.round_off,t_good_receipt_note.net_amount AS grnnetamt,m_uom_unit.unit,t_good_receipt_note.remark,muom.conversions,unitinformation.unit_contact,unitinformation.unit_email_id,t_good_receipt_note.pay_due_dateFROM procurement.t_good_receipt_noteJOIN procurement.t_good_receipt_note_detail ON t_good_receipt_note.id = t_good_receipt_note_detail.grn_idJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_item ON t_good_receipt_note_detail.item_id = m_item.idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_store_item_mapper ON t_good_receipt_note_detail.item_id = m_store_item_mapper.item_id AND t_good_receipt_note.is_deleted = falseLEFT JOIN m_unit_master unitinformation ON t_good_receipt_note.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON t_good_receipt_note.added_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_user_master umapproval ON t_good_receipt_note.approved_by = umapproval.user_idLEFT JOIN m_employee_master empapproval ON umapproval.user_id = empapproval.user_idLEFT JOIN m_status ON t_good_receipt_note.approve_status_id = m_status.idLEFT JOIN procurement.t_purchase_order po ON t_good_receipt_note.po_id = po.idLEFT JOIN m_uom_unit ON t_good_receipt_note_detail.grn_uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_of_measurement muom ON t_good_receipt_note_detail.item_id = muom.item_id AND muom.uom_type_id = t_good_receipt_note_detail.grn_uom_type_idWHERE t_good_receipt_note_detail.is_deleted = false AND t_good_receipt_note_detail.is_active = trueORDER BY t_good_receipt_note_detail.id;

-- "procedure".get_grn_purchasegst_invoice source
CREATE OR REPLACE VIEW "procedure".get_grn_purchasegst_invoiceAS SELECT DISTINCT grn.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.inward_number,grn.inward_date,m_vendor.name AS vendorname,grn.total_amount,grn.total_discount,grn.net_amount,grn.total_tax_ammount,grn.added_date,grn.unit_id,COALESCE(tax5.taxamount, 0::double precision) AS tax5,COALESCE(tax12.taxamount, 0::double precision) AS tax12,COALESCE(tax18.taxamount, 0::double precision) AS tax18,COALESCE(tax28.taxamount, 0::double precision) AS tax28,COALESCE(tax5.taxable, 0::double precision) AS taxable5,COALESCE(tax12.taxable, 0::double precision) AS taxable12,COALESCE(tax18.taxable, 0::double precision) AS taxable18,COALESCE(tax28.taxable, 0::double precision) AS taxable28,COALESCE(tax0.taxable, 0::double precision) AS taxable0,COALESCE(tax0.taxamount, 0::double precision) AS tax0,sm.store_id,sm.store_nameFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail td ON grn.id = td.grn_idJOIN m_vendor ON m_vendor.id = grn.vendor_idJOIN m_store sm ON sm.store_id = grn.store_idLEFT JOIN ( SELECT sum(td_1.net_amount) AS taxamount,(sum(td_1.total_amount) - sum(td_1.total_discount)) * 100::double precision / (100::double precision + td_1.tax_percentage) AS taxable,td_1.tax_percentage,td_1.grn_idFROM procurement.t_good_receipt_note_detail td_1WHERE td_1.tax_percentage = 0::double precisionGROUP BY td_1.tax_percentage, td_1.grn_id) tax0 ON tax0.grn_id = grn.idLEFT JOIN ( SELECT (sum(td_1.total_amount) - sum(td_1.total_discount)) * td_1.tax_percentage / 100::double precision AS taxamount,sum(td_1.total_amount) - sum(td_1.total_discount) * 100::double precision / (100::double precision + td_1.tax_percentage) AS taxable,td_1.tax_percentage,td_1.grn_idFROM procurement.t_good_receipt_note_detail td_1WHERE td_1.tax_percentage = 5::double precisionGROUP BY td_1.tax_percentage, td_1.grn_id) tax5 ON tax5.grn_id = grn.idLEFT JOIN ( SELECT (sum(td_1.total_amount) - sum(td_1.total_discount)) * td_1.tax_percentage / 100::double precision AS taxamount,sum(td_1.total_amount) - sum(td_1.total_discount) * 100::double precision / (100::double precision + td_1.tax_percentage) AS taxable,td_1.tax_percentage,td_1.grn_idFROM procurement.t_good_receipt_note_detail td_1WHERE td_1.tax_percentage = 12::double precisionGROUP BY td_1.tax_percentage, td_1.grn_id) tax12 ON tax12.grn_id = grn.idLEFT JOIN ( SELECT (sum(td_1.total_amount) - sum(td_1.total_discount)) * td_1.tax_percentage / 100::double precision AS taxamount,sum(td_1.total_amount) - sum(td_1.total_discount) * 100::double precision / (100::double precision + td_1.tax_percentage) AS taxable,td_1.tax_percentage,td_1.grn_idFROM procurement.t_good_receipt_note_detail td_1WHERE td_1.tax_percentage = 18::double precisionGROUP BY td_1.tax_percentage, td_1.grn_id) tax18 ON tax18.grn_id = grn.idLEFT JOIN ( SELECT (sum(td_1.total_amount) - sum(td_1.total_discount)) * td_1.tax_percentage / 100::double precision AS taxamount,sum(td_1.total_amount) - sum(td_1.total_discount) * 100::double precision / (100::double precision + td_1.tax_percentage) AS taxable,td_1.tax_percentage,td_1.grn_idFROM procurement.t_good_receipt_note_detail td_1WHERE td_1.tax_percentage = 28::double precisionGROUP BY td_1.tax_percentage, td_1.grn_id) tax28 ON tax28.grn_id = grn.id;

-- "procedure".get_grn_purchasegst_invoice_itemwise source
CREATE OR REPLACE VIEW "procedure".get_grn_purchasegst_invoice_itemwiseAS SELECT DISTINCT grn.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.inward_number,grn.inward_date,m_vendor.name AS vendorname,grn.total_amount,grn.total_discount,grn.net_amount,grn.total_tax_ammount,grn.added_date,grn.unit_id,td.id AS grndetailid,(td.total_amount - td.total_discount) * td.tax_percentage / 100::double precision AS taxamount,td.total_amount - td.total_discount AS taxable,mi.id AS itemid,mi.name AS itemname,td.tax_percentage,um.unit_name,um.unit_address,td.total_amount AS totaldetails,td.total_discount AS disdetails,td.total_net_amount,mi.hsn_codeFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail td ON grn.id = td.grn_idJOIN m_item mi ON mi.id = td.item_idJOIN m_vendor ON m_vendor.id = grn.vendor_idJOIN m_unit_master um ON um.unit_id = grn.unit_id;

-- "procedure".get_grn_return source
CREATE OR REPLACE VIEW "procedure".get_grn_returnAS SELECT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_batch.batch_no,t_batch.cop,t_batch.rate,t_returnable_gatepass_detail.tax_percentage,t_batch.cop * uom.conversions::double precision * t_returnable_gatepass_detail.return_qty::double precision * t_returnable_gatepass_detail.tax_percentage / 100::double precision AS total_tax_amount,t_returnable_gatepass_detail.total_amt,t_returnable_gatepass_detail.net_amount,m_store.store_id,t_returnable_gatepass_detail.approved_qty,t_returnable_gatepass_detail.reject_qty,t_returnable_gatepass_detail.return_qty,unit.unit_name,unit.unit_address,unit.image,t_returnable_gatepass_detail.id AS returnable_gatepass_detail_id,t_batch.expiry_date,concat(prefix.prefix_desc, '.', emp.first_name, ' ', emp.last_name) AS emp,um.user_name,t_returnable_gatepass.remarkFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_idLEFT JOIN m_unit_master unit ON t_returnable_gatepass.unit_id = unit.unit_idLEFT JOIN m_user_master um ON um.user_id = t_returnable_gatepass.added_byLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master prefix ON emp.prefix_id = prefix.prefix_idJOIN m_uom_type mut ON mut.id = t_returnable_gatepass_detail.uom_type_idJOIN m_uom_unit muu ON muu.id = t_returnable_gatepass_detail.uom_unit_idJOIN m_unit_of_measurement uom ON uom.item_id = m_item.id AND uom.uom_type_id = t_returnable_gatepass_detail.uom_type_id AND uom.uom_unit_id = t_returnable_gatepass_detail.uom_unit_idWHERE t_returnable_gatepass_detail.is_active = trueORDER BY t_returnable_gatepass_detail.id;

-- "procedure".get_grn_return_list source
CREATE OR REPLACE VIEW "procedure".get_grn_return_listAS SELECT DISTINCT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_store.store_id,unitinformation.unit_name,unitinformation.unit_address,t_returnable_gatepass.total_amt,t_returnable_gatepass.total_tax_amount,t_returnable_gatepass.net_amount,t_returnable_gatepass.remark,approvalstatus.status AS approvalstatus,m_status.status,requesttype.type AS requesttype,approvalstatus.id AS approvalstatus_id,m_status.id AS status_id,m_vendor.id AS vendor_id,unitinformation.unit_id,unitinformation.imageFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_idJOIN unitinformation ON t_returnable_gatepass.unit_id = unitinformation.unit_idJOIN m_status approvalstatus ON t_returnable_gatepass.approval_status_id = approvalstatus.idLEFT JOIN m_status ON t_returnable_gatepass.status_id = m_status.idLEFT JOIN m_request_type requesttype ON t_returnable_gatepass.request_type_id = requesttype.idLEFT JOIN m_asset_type assettype ON t_returnable_gatepass.asset_type_id = t_returnable_gatepass.asset_type_id;

-- "procedure".get_grn_return_list_details source
CREATE OR REPLACE VIEW "procedure".get_grn_return_list_detailsAS SELECT DISTINCT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_store.store_id,unitinformation.unit_name,unitinformation.unit_address,t_returnable_gatepass.total_amt,t_returnable_gatepass.total_tax_amount,t_returnable_gatepass.net_amount,t_returnable_gatepass.remark,approvalstatus.status AS approvalstatus,m_status.status,requesttype.type AS requesttype,approvalstatus.id AS approvalstatus_id,m_status.id AS status_id,m_vendor.id AS vendor_id,unitinformation.unit_id,unitinformation.image,t_returnable_gatepass_detail.id AS returnable_gatepass_detail,m_item.code,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,t_batch.batch_no,t_batch.expiry_date,t_returnable_gatepass_detail.return_qty,t_batch.cop,t_returnable_gatepass_detail.tax_percentage,t_returnable_gatepass_detail.total_amt AS total_amt_detail,t_returnable_gatepass_detail.total_tax_amount AS tax_amount_detail,t_returnable_gatepass_detail.net_amount AS net_amount_detail,m_item.id AS itemid,t_batch.rateFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_idJOIN m_unit_master unitinformation ON t_returnable_gatepass.unit_id = unitinformation.unit_idLEFT JOIN m_uom_type uomtype ON t_returnable_gatepass_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON t_returnable_gatepass_detail.uom_unit_id = uomunit.idJOIN m_status approvalstatus ON t_returnable_gatepass.approval_status_id = approvalstatus.idLEFT JOIN m_status ON t_returnable_gatepass.status_id = m_status.idLEFT JOIN m_request_type requesttype ON t_returnable_gatepass.request_type_id = requesttype.idLEFT JOIN m_asset_type assettype ON t_returnable_gatepass.asset_type_id = t_returnable_gatepass.asset_type_idWHERE t_returnable_gatepass_detail.is_active = true AND t_returnable_gatepass_detail.is_deleted = false;

-- "procedure".get_grnsettlement source
CREATE OR REPLACE VIEW "procedure".get_grnsettlementAS SELECT DISTINCT rsm.id,rsm.receipt_number,rsm.amount_received_from,rsm.amount_data,rsm.added_date AS recdate,grn.grn_number,grn.added_date AS grndate,grn.bill_type_name,COALESCE(grn.paid_amount, 0::double precision) AS paid_amount,COALESCE(grn.balance_amount, 0::double precision) AS balance_amount,m_vendor.name AS vendor,m_store.store_name,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.net_amount,paymode.payment_mode_desc,rsd.amount,rsd.cheque_number,rsd.cheque_date,bank.bank_name,m_status.status AS paymentstatus,grnstatus.status AS grnstatus,um.unit_name,um.unit_address,usermaster.user_name,grn.id AS grn_id,um.image,um.unit_id,m_store.store_id,m_vendor.id AS vendor_idFROM procurement.t_grn_settlement_receipt_detail rsdJOIN procurement.t_grn_settlement_receipt rsm ON rsm.id = rsd.grn_settlement_idJOIN procurement.t_good_receipt_note grn ON grn.id = rsd.grn_idJOIN m_vendor ON grn.vendor_id = m_vendor.idJOIN m_store ON grn.store_id = m_store.store_idJOIN m_payment_mode_master paymode ON rsd.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON rsd.bank_id = bank.bank_idLEFT JOIN m_status ON rsd.status_id = m_status.idLEFT JOIN m_status grnstatus ON grn.status_id = grnstatus.idLEFT JOIN m_unit_master um ON grn.unit_id = um.unit_idLEFT JOIN m_user_master usermaster ON rsm.added_by = usermaster.user_idWHERE (rsd.status_id = ANY (ARRAY[20, 8])) AND rsm.is_active = true;

-- "procedure".get_grnsettlement_new source
CREATE OR REPLACE VIEW "procedure".get_grnsettlement_newAS SELECT DISTINCT rsm.id,rsm.receipt_number,rsm.amount_received_from,rsm.amount_data,rsm.added_date AS recdate,grn.grn_number,grn.added_date AS grndate,grn.bill_type_name,grn.paid_amount,grn.balance_amount,m_vendor.name AS vendor,m_store.store_name,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.net_amount,paymode.payment_mode_desc,COALESCE(rsd.amount, 0) AS amount,rsd.cheque_number,rsd.cheque_date,bank.bank_name,m_status.status AS paymentstatus,grnstatus.status AS grnstatus,um.unit_name,um.unit_address,usermaster.user_name,grn.id AS grn_id,um.image,um.unit_id,m_vendor.id AS vendor_idFROM procurement.t_grn_settlement_receipt_detail rsdJOIN procurement.t_grn_settlement_receipt rsm ON rsm.id = rsd.grn_settlement_idJOIN procurement.t_good_receipt_note grn ON grn.id = rsd.grn_idJOIN m_vendor ON grn.vendor_id = m_vendor.idJOIN m_store ON grn.store_id = m_store.store_idJOIN m_payment_mode_master paymode ON rsd.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON rsd.bank_id = bank.bank_idLEFT JOIN m_status ON rsd.status_id = m_status.idLEFT JOIN m_status grnstatus ON grn.status_id = grnstatus.idLEFT JOIN m_unit_master um ON grn.unit_id = um.unit_idLEFT JOIN m_user_master usermaster ON rsm.added_by = usermaster.user_idUNIONSELECT DISTINCT rsm.id,rsm.receipt_number,rsm.amount_received_from,rsm.amount_data,rsm.added_date AS recdate,grn.grn_number,grn.added_date AS grndate,grn.bill_type_name,grn.paid_amount,grn.balance_amount,m_vendor.name AS vendor,m_store.store_name,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.net_amount,paymode.payment_mode_desc,COALESCE(rsd.amount, 0) AS amount,rsd.cheque_number,rsd.cheque_date,bank.bank_name,m_status.status AS paymentstatus,grnstatus.status AS grnstatus,um.unit_name,um.unit_address,usermaster.user_name,grn.id AS grn_id,um.image,um.unit_id,m_vendor.id AS vendor_idFROM procurement.t_good_receipt_note grnLEFT JOIN procurement.t_grn_settlement_receipt_detail rsd ON grn.id = rsd.grn_idLEFT JOIN procurement.t_grn_settlement_receipt rsm ON rsm.id = rsd.grn_settlement_idLEFT JOIN m_vendor ON grn.vendor_id = m_vendor.idLEFT JOIN m_store ON grn.store_id = m_store.store_idLEFT JOIN m_payment_mode_master paymode ON rsd.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON rsd.bank_id = bank.bank_idLEFT JOIN m_status ON rsd.status_id = m_status.idLEFT JOIN m_status grnstatus ON grn.status_id = grnstatus.idLEFT JOIN m_unit_master um ON grn.unit_id = um.unit_idLEFT JOIN m_user_master usermaster ON rsm.added_by = usermaster.user_id;

-- "procedure".get_issueworklist source
CREATE OR REPLACE VIEW "procedure".get_issueworklistAS SELECT DISTINCT issue.id,issue.issue_no,visittype.visit_type_name,issue.added_date,em.created_date AS encounterdate,adm.created_date AS admdate,pres.prescription_no,pim.uhid_number,pim.patientname,pim.gender_name,pim.ageyear,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctorname,wm.ward_name,bedmaster.bed_number,priority.priority_desc,m_status.status,salestatus.status AS salestatus,m_item.name AS itemname,m_generic.name AS generic,presd.order_qty,presd.dis_presribed_qty,uomtype.type AS uomtype,uomunit.unit AS uomunit,0 AS available_qty,m_rack.name AS rack,um.unit_name,um.unit_address,batch.batch_no,batch.expiry_date,issue.visit_type_idFROM pharmacy.t_issue issueJOIN pharmacy.t_issue_detail issuedetail ON issue.id = issuedetail.issue_idJOIN inventory.t_batch batch ON issuedetail.batch_id = batch.idJOIN m_visit_type_master visittype ON issue.visit_type_id = visittype.visit_type_idLEFT JOIN opd.t_encounter_master em ON issue.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON issue.admission_id = adm.admission_idLEFT JOIN pharmacy.t_prescription pres ON issue.prescription_id = pres.idLEFT JOIN pharmacy.t_prescription_detail presd ON pres.id = presd.prescription_idLEFT JOIN m_item ON presd.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN adt.m_priority_master priority ON pres.priority_id = priority.priority_idLEFT JOIN patientinformation pim ON adm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master docmaster ON issue.doctor_id = docmaster.doctor_idLEFT JOIN ( SELECT t_admission_details.admission_details_id,t_admission_details.admission_id,t_admission_details.ward_id,t_admission_details.bed_idFROM adt.t_admission_detailsORDER BY t_admission_details.admission_details_id DESCLIMIT 1) admd ON adm.admission_id = admd.admission_idLEFT JOIN adt.m_ward_master wm ON admd.ward_id = wm.ward_idLEFT JOIN adt.m_bed_master bedmaster ON admd.bed_id = bedmaster.bed_idLEFT JOIN m_status ON issue.status_id = m_status.idLEFT JOIN pharmacy.t_sale sale ON issue.sale_id = sale.idLEFT JOIN m_status salestatus ON sale.status_id = salestatus.idLEFT JOIN pharmacy.t_assign_picker_detail pickerd ON issuedetail.assign_picker_detail_id = pickerd.idLEFT JOIN m_uom_type uomtype ON issuedetail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON issuedetail.uom_unit_id = uomunit.idLEFT JOIN procurement.t_shelf_item shelf ON pickerd.batch_id = shelf.batch_idLEFT JOIN m_rack ON shelf.rack_id = m_rack.id AND shelf.store_id = issue.store_idLEFT JOIN unitinformation um ON issue.unit_id = um.unit_idWHERE m_item.is_narcotic = true AND issuedetail.is_active = true;

-- "procedure".get_itemwise_grnlist source
CREATE OR REPLACE VIEW "procedure".get_itemwise_grnlistAS SELECT DISTINCT grn.id,grn.grn_number,v.name AS vendor_name,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.inward_number,grn.inward_date,v.name,st.store_name,grn.store_id,ast.type,rt.type AS request_type,s.status,dt.type AS discount_type,grn.discount,grn.total_amount,grn.total_tax_ammount,grn.total_other_amount,grn.round_off,grn.net_amount,grn.remark,grn.added_date,grn.po_id,grn.unit_id,u.unit_name,u.unit_address,grn.vendor_id,grn.added_by,(((pm.prefix_desc || ' '::text) || em.first_name::text) || ' '::text) || em.last_name::text AS user_name,um.user_id,u.image,m_item.name AS itemname,m_item.id AS itemid,grndetails.grn_approved_quantity,grndetails.bonus_approved_quantity,grndetails.grn_received_quantity,grndetails.cop,grndetails.expiry_date,grndetails.mrp,grndetails.tax_percentage,grndetails.tax_amount,grndetails.total_amount AS totalamountdetails,grndetails.total_discount AS discountdetails,grndetails.net_amount AS netamountdetails,batch.batch_no,m_item.hsn_code,batch.rate,grndetails.item_id,tax.name AS tax,grndetails.cop * grndetails.grn_received_quantity::double precision AS purchase_value,grndetails.mrp * grndetails.grn_received_quantity::double precision AS sale_valueFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail grndetails ON grn.id = grndetails.grn_id AND grndetails.is_active = trueJOIN inventory.t_batch batch ON grndetails.batch_id = batch.idJOIN m_item ON grndetails.item_id = m_item.idLEFT JOIN m_vendor v ON grn.vendor_id = v.idLEFT JOIN unitinformation u ON grn.unit_id = u.unit_idLEFT JOIN m_store st ON grn.store_id = st.store_idLEFT JOIN m_asset_type ast ON grn.asset_type_id = ast.idLEFT JOIN m_request_type rt ON grn.request_id = rt.idLEFT JOIN m_status s ON grn.status_id = s.idLEFT JOIN m_discount_type dt ON grn.discount_type_id = dt.idLEFT JOIN m_user_master um ON grn.added_by = um.user_idLEFT JOIN m_employee_master em ON um.user_id = em.user_idLEFT JOIN m_prefix_master pm ON em.prefix_id = pm.prefix_idJOIN m_tax tax ON grndetails.tax_id = tax.idWHERE grndetails.is_active = true AND grndetails.is_deleted = falseORDER BY grn.id;

-- "procedure".get_itemwise_salesbills source
CREATE OR REPLACE VIEW "procedure".get_itemwise_salesbillsAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_contact,m_item.hsn_code,t_batch.cop,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,m_store.store_name,m_store.store_id,m_sale_type.type,mpc.classification,t_sale_detail.item_id,mm.name AS manufacturer,m_item.manufacturer_id,m_item.generic_id,generic.name AS generic,t_sale_detail.id AS salesdetailid,mpc.id AS pharmacological_classification_id,t_batch.lcopFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN m_store ON m_store.store_id = t_sale.store_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN pharmacy.m_sale_type ON m_sale_type.id = t_sale.sale_type_idLEFT JOIN m_pharmacological_classification mpc ON mpc.id = m_item.pharmacological_classification_idLEFT JOIN m_manufacturer mm ON mm.id = m_item.manufacturer_idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = trueUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_contact,m_item.hsn_code,t_batch.cop,unitinformation.unit_id,unitinformation.image,''::text AS opidnumber,m_store.store_name,m_store.store_id,m_sale_type.type,mpc.classification,t_sale_detail.item_id,mm.name AS manufacturer,m_item.manufacturer_id,m_item.generic_id,generic.name AS generic,t_sale_detail.id AS salesdetailid,mpc.id AS pharmacological_classification_id,t_batch.lcopFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN m_store ON m_store.store_id = t_sale.store_idLEFT JOIN pharmacy.m_sale_type ON m_sale_type.id = t_sale.sale_type_idLEFT JOIN m_pharmacological_classification mpc ON mpc.id = m_item.pharmacological_classification_idLEFT JOIN m_manufacturer mm ON mm.id = m_item.manufacturer_idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- "procedure".get_pharmacybilloutstanding source
CREATE OR REPLACE VIEW "procedure".get_pharmacybilloutstandingAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patientname,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,pharmacy.cash(t_sale.id) AS cashamount,COALESCE(pharmacy.cheque(t_sale.id), 0::bigint) AS chequeamount,COALESCE(pharmacy.creditcard(t_sale.id), 0::bigint) AS creditcardamount,COALESCE(pharmacy.debitcard(t_sale.id), 0::bigint) AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales'::text AS salestype,companybill.companydueamt,selfbill.selfdueamt,companymaster.company_id AS payee_id,companymaster.company_desc,mode1.paidamount,selfcompanymaster.company_id AS selfpayeeid,'\x'::bytea AS image,t_sale.status_idFROM pharmacy.t_saleLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN ( SELECT sum(t_sale_payment_mode.amount) AS paidamount,t_sale_payment_mode.sale_idFROM pharmacy.t_sale_payment_modeJOIN pharmacy.t_sale t_sale_1 ON t_sale_payment_mode.sale_id = t_sale_1.id AND t_sale_payment_mode.is_active = trueGROUP BY t_sale_payment_mode.sale_id) mode1 ON t_sale.id = mode1.sale_idLEFT JOIN ( SELECT sum(billpayee.due_amount) AS companydueamt,billpayee.t_sale_id,billpayee.payee_idFROM pharmacy.t_pharmacy_bill_payee_details billpayeeJOIN pharmacy.t_sale t_sale_1 ON t_sale_1.id = billpayee.t_sale_id AND billpayee.payee_id &gt; 1GROUP BY billpayee.t_sale_id, billpayee.payee_id) companybill ON t_sale.id = companybill.t_sale_idLEFT JOIN ( SELECT sum(billpayee.due_amount) AS selfdueamt,billpayee.t_sale_id,billpayee.payee_idFROM pharmacy.t_pharmacy_bill_payee_details billpayeeJOIN pharmacy.t_sale t_sale_1 ON t_sale_1.id = billpayee.t_sale_id AND billpayee.payee_id = 1GROUP BY billpayee.t_sale_id, billpayee.payee_id) selfbill ON t_sale.id = selfbill.t_sale_idLEFT JOIN t_company_master companymaster ON companybill.payee_id = companymaster.company_idLEFT JOIN t_company_master selfcompanymaster ON selfbill.payee_id = selfcompanymaster.company_idWHERE t_sale.outstanding_amount &gt; 0.1::double precision AND t_sale.status_id &lt;&gt; 9;

-- "procedure".get_pharmacybilloutstanding_sw source
CREATE OR REPLACE VIEW "procedure".get_pharmacybilloutstanding_swAS SELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,concat(registration.first_name, ' ', registration.last_name) AS patientname,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,COALESCE(pharmacy.cash(t_sale.id), 0::bigint) AS cashamount,COALESCE(pharmacy.cheque(t_sale.id), 0::bigint) AS chequeamount,COALESCE(pharmacy.creditcard(t_sale.id), 0::bigint) AS creditcardamount,COALESCE(pharmacy.debitcard(t_sale.id), 0::bigint) AS debitcardamount,unit.unit_name,unit.unit_address,unit.unit_address_2,unit.unit_id,t_sale.visit_type_id,'Sales'::text AS salestype,0 AS companydueamt,t_sale.net_amount - t_sale.outstanding_amount AS selfdueamt,companymaster.company_id AS payee_id,companymaster.company_desc,t_sale.net_amount - t_sale.outstanding_amount AS paidamount,0 AS selfpayeeid,'\x'::bytea AS image,COALESCE(pharmacy.e_transfer(t_sale.id), 0::bigint) AS etransfer,t_temp_patient_registration.patient_name AS temppatientname,t_temp_patient_registration.temp_uhid AS temp_uhid1,t_temp_patient_registration.mobile_number AS tempmobile,registration.mobile_numberFROM pharmacy.t_saleLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_unit_master unit ON t_sale.unit_id = unit.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN ( SELECT sum(billpayee.due_amount) AS companydueamt,billpayee.t_sale_id,billpayee.payee_idFROM pharmacy.t_pharmacy_bill_payee_details billpayeeJOIN pharmacy.t_sale t_sale_1 ON t_sale_1.id = billpayee.t_sale_idWHERE billpayee.payee_id &lt;&gt; (( SELECT tuabc.self_payee_idFROM t_unit_application_billing_configuration tuabcWHERE tuabc.unit_id = t_sale_1.unit_id))GROUP BY billpayee.t_sale_id, billpayee.payee_id) companybill ON t_sale.id = companybill.t_sale_idLEFT JOIN t_company_master companymaster ON companybill.payee_id = companymaster.company_idWHERE t_sale.outstanding_amount &lt;&gt; 0::double precision AND t_sale.status_id &lt;&gt; 9;

-- "procedure".get_pharmacycollection source
CREATE OR REPLACE VIEW "procedure".get_pharmacycollectionAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,CASEWHEN t_sale.sale_type_id = 2 THEN ((registration.first_name::text || ' '::text) || registration.last_name::text)::character varyingELSE t_temp_patient_registration.patient_nameEND AS patient_name,CASEWHEN t_sale.sale_type_id = 2 THEN t_patient_details.address::character varyingELSE t_temp_patient_registration.addressEND AS address,CASEWHEN t_sale.sale_type_id = 2 THEN registration.uhid_numberELSE t_temp_patient_registration.temp_uhidEND AS temp_uhid,CASEWHEN t_sale.sale_type_id = 2 THEN ((m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text)::character varyingELSE t_temp_doctor.doctor_nameEND AS doctor_name,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.imageFROM pharmacy.t_saleLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN unitinformation um ON t_sale.unit_id = um.unit_idLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_id;

-- "procedure".get_po source
CREATE OR REPLACE VIEW "procedure".get_poAS SELECT DISTINCT t_purchase_order.id,t_purchase_order.po_number,t_purchase_order.added_date,t_purchase_order.approved_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_purchase_order_detail.po_quantity,t_purchase_order_detail.bonus_quantity,t_purchase_order_detail.cop,t_purchase_order_detail.mrp,t_purchase_order_detail.total_discount,t_purchase_order_detail.tax_percentage,t_purchase_order_detail.tax_amount,t_purchase_order_detail.total_other_amount AS total_other_amount_detail,t_purchase_order_detail.net_amount,m_store.store_id,t_purchase_order.total_tax_amount,t_purchase_order.total_other_amount,t_purchase_order_detail.po_approved_quantity,t_purchase_order_detail.bonus_approved_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,t_purchase_order.total_amount,t_purchase_order.added_by,um.user_name,t_purchase_order.updated_by,umapproval.user_name AS umapprovaluser,(((prefix.prefix_desc || '. '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS empuser,(((prefixapp.prefix_desc || '. '::text) || empapproval.first_name::text) || ' '::text) || empapproval.last_name::text AS empapprovaluser,m_status.status,m_vendor.phone_number,t_purchase_order.payment_term,concat(uomtype.type, ' / ', uomunit.unit) AS uomunit,t_purchase_order.updated_date,t_purchase_order.approved_by,(((prefixupd.prefix_desc || '. '::text) || empupdated.first_name::text) || ' '::text) || empupdated.last_name::text AS empupdateduser,t_purchase_order.remark,prefixupd.prefix_id AS prefixupd_id,prefixapp.prefix_id AS prefixapp_id,prefix.prefix_id,empreview.prefix_id AS prefixreview_id,(((prefixreview.prefix_desc || '. '::text) || empreview.first_name::text) || ' '::text) || empreview.last_name::text AS empreviewuser,unitinformation.image,t_purchase_order.reviewed_date,m_vendor.email_id,m_vendor.contact_person_name,t_purchase_order.is_consignment,m_item.hsn_code,t_purchase_order_detail.id AS purchase_order_detail,unitinformation.unit_contact,mat.type AS assettype,t_purchase_order_detail.specification,t_purchase_order_detail.expected_payment,t_purchase_order_detail.technical_specification,t_purchase_order_detail.support_terms,t_purchase_order_detail.warrenty_period,unitinformation.unit_email_id,t_purchase_order_detail.remark AS delremark,t_purchase_order.net_amount AS total_net,desg.employee_designation_descriptionFROM procurement.t_purchase_orderJOIN procurement.t_purchase_order_detail ON t_purchase_order.id = t_purchase_order_detail.purchase_order_idJOIN m_vendor ON m_vendor.id = t_purchase_order.vendor_idJOIN m_item ON t_purchase_order_detail.item_id = m_item.idJOIN m_store ON t_purchase_order.store_id = m_store.store_idJOIN m_store_item_mapper ON t_purchase_order_detail.item_id = m_store_item_mapper.item_idLEFT JOIN m_unit_master unitinformation ON t_purchase_order.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON t_purchase_order.added_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_user_master umapproval ON t_purchase_order.approved_by = umapproval.user_idLEFT JOIN m_employee_master empapproval ON umapproval.user_id = empapproval.user_idLEFT JOIN m_user_master umupdated ON t_purchase_order.updated_by = umupdated.user_idLEFT JOIN m_employee_master empupdated ON umupdated.user_id = empupdated.user_idLEFT JOIN m_status ON t_purchase_order.approve_status_id = m_status.idLEFT JOIN m_uom_type uomtype ON t_purchase_order_detail.po_uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON t_purchase_order_detail.po_uom_unit_id = uomunit.idLEFT JOIN m_prefix_master prefix ON emp.prefix_id = prefix.prefix_idLEFT JOIN m_prefix_master prefixapp ON empapproval.prefix_id = prefixapp.prefix_idLEFT JOIN m_prefix_master prefixupd ON empupdated.prefix_id = prefixupd.prefix_idLEFT JOIN m_user_master umreview ON t_purchase_order.reviewed_by = umreview.user_idLEFT JOIN m_employee_master empreview ON umreview.user_id = empreview.user_idLEFT JOIN m_prefix_master prefixreview ON empreview.prefix_id = prefixreview.prefix_idLEFT JOIN m_asset_type mat ON mat.id = t_purchase_order.asset_type_idLEFT JOIN m_employee_designation desg ON desg.employee_designation_id = empreview.emp_designation_idWHERE t_purchase_order_detail.is_active = true AND t_purchase_order_detail.is_deleted = falseORDER BY t_purchase_order_detail.id;

-- "procedure".get_purchase_gst source
CREATE OR REPLACE VIEW "procedure".get_purchase_gstAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.invoice_number,t_good_receipt_note.invoice_date,t_good_receipt_note.inward_number,t_good_receipt_note.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_good_receipt_note_detail.batch_no,t_good_receipt_note_detail.cop,t_good_receipt_note_detail.mrp,t_good_receipt_note_detail.discount,t_good_receipt_note_detail.tax_percentage,t_good_receipt_note_detail.tax_amount,tax.id AS taxid,tax.name AS taxname,tax.tax_percentage AS taxperc,taxdetail.id AS taxdetailid,taxdetail.tax_percentage AS taxdetailsperc,taxcompomaster.id AS taxcompomasterid,taxcompomaster.component,t_good_receipt_note_detail.total_discount,t_good_receipt_note_detail.total_other_amount AS total_other_amount_detail,t_good_receipt_note_detail.net_amount,m_store.store_id,t_good_receipt_note.total_tax_ammount,t_good_receipt_note.total_other_amount,t_good_receipt_note_detail.grn_approved_quantity,t_good_receipt_note_detail.grn_received_quantity,unitinformation.unit_name,unitinformation.unit_address,t_good_receipt_note.added_date,m_vendor.id AS vendor_id,unitinformation.unit_id,unitinformation.imageFROM procurement.t_good_receipt_noteJOIN procurement.t_good_receipt_note_detail ON t_good_receipt_note.id = t_good_receipt_note_detail.grn_idJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_item ON t_good_receipt_note_detail.item_id = m_item.idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_store_item_mapper ON t_good_receipt_note_detail.item_id = m_store_item_mapper.item_id AND t_good_receipt_note.is_deleted = falseLEFT JOIN m_unit_master unitinformation ON t_good_receipt_note.unit_id = unitinformation.unit_idJOIN m_tax tax ON t_good_receipt_note_detail.tax_id = tax.idJOIN m_tax_detail taxdetail ON tax.id = taxdetail.tax_idJOIN m_tax_component taxcompomaster ON taxdetail.tax_component_id = taxcompomaster.id;

-- "procedure".get_purchase_gst_invoice source
CREATE OR REPLACE VIEW "procedure".get_purchase_gst_invoiceAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.invoice_number,t_good_receipt_note.invoice_date,t_good_receipt_note.inward_number,t_good_receipt_note.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_store.store_id,m_unit_master.unit_name,m_unit_master.unit_address,t_good_receipt_note.added_date,m_vendor.id AS vendor_id,m_unit_master.unit_idFROM procurement.t_good_receipt_noteJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_unit_master ON t_good_receipt_note.unit_id = m_unit_master.unit_id;

-- "procedure".get_purchase_gst_new source
CREATE OR REPLACE VIEW "procedure".get_purchase_gst_newAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.vendor_id,m_vendor.name,m_store.store_id,m_store.store_name,tax.id AS taxid,tax.name AS tax,t_good_receipt_note_detail.tax_percentage,t_good_receipt_note.total_amount,t_good_receipt_note.total_tax_ammount,t_good_receipt_note.total_discount,t_good_receipt_note.net_amount AS total_netamount,sum((t_good_receipt_note_detail.cop * t_good_receipt_note_detail.grn_received_quantity::double precision - t_good_receipt_note_detail.total_discount) * (t_good_receipt_note_detail.tax_percentage / 100::double precision)) AS cal_tacamt,sum(t_good_receipt_note_detail.tax_amount) AS tax_amount,CASEWHEN t_good_receipt_note_detail.tax_percentage = 5::double precision THEN sum(t_good_receipt_note_detail.tax_amount)ELSE 0::double precisionEND AS tax5,CASEWHEN t_good_receipt_note_detail.tax_percentage = 12::double precision THEN sum(t_good_receipt_note_detail.tax_amount)ELSE 0::double precisionEND AS tax12,CASEWHEN t_good_receipt_note_detail.tax_percentage = 18::double precision THEN sum(t_good_receipt_note_detail.tax_amount)ELSE 0::double precisionEND AS tax18,CASEWHEN t_good_receipt_note_detail.tax_percentage = 28::double precision THEN sum(t_good_receipt_note_detail.tax_amount)ELSE 0::double precisionEND AS tax28,sum(t_good_receipt_note_detail.total_amount - t_good_receipt_note_detail.total_discount) AS taxableamt,CASEWHEN t_good_receipt_note_detail.tax_percentage = 0::double precision THEN sum(t_good_receipt_note_detail.total_amount - COALESCE(t_good_receipt_note_detail.total_discount, 0::double precision))ELSE 0::double precisionEND AS taxable0,CASEWHEN t_good_receipt_note_detail.tax_percentage = 5::double precision THEN sum(t_good_receipt_note_detail.total_amount - COALESCE(t_good_receipt_note_detail.total_discount, 0::double precision))ELSE 0::double precisionEND AS taxable5,CASEWHEN t_good_receipt_note_detail.tax_percentage = 12::double precision THEN sum(t_good_receipt_note_detail.total_amount - COALESCE(t_good_receipt_note_detail.total_discount, 0::double precision))ELSE 0::double precisionEND AS taxable12,CASEWHEN t_good_receipt_note_detail.tax_percentage = 18::double precision THEN sum(t_good_receipt_note_detail.total_amount - COALESCE(t_good_receipt_note_detail.total_discount, 0::double precision))ELSE 0::double precisionEND AS taxable18,CASEWHEN t_good_receipt_note_detail.tax_percentage = 28::double precision THEN sum(t_good_receipt_note_detail.total_amount - COALESCE(t_good_receipt_note_detail.total_discount, 0::double precision))ELSE 0::double precisionEND AS taxable28,sum(t_good_receipt_note_detail.total_other_amount) AS total_other_amount_detail,sum(t_good_receipt_note_detail.net_amount) AS net_amount_detail,sum(t_good_receipt_note_detail.total_amount) AS total_amount_detail,t_good_receipt_note.added_date,unit.unit_id,unit.unit_name,unit.unit_address,m_vendor.gst_no,sum(t_good_receipt_note_detail.total_discount) AS discount_amount_detail,t_good_receipt_note.approve_status_id,t_good_receipt_note.invoice_numberFROM procurement.t_good_receipt_noteJOIN procurement.t_good_receipt_note_detail ON t_good_receipt_note.id = t_good_receipt_note_detail.grn_idJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_item ON t_good_receipt_note_detail.item_id = m_item.idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_tax tax ON t_good_receipt_note_detail.tax_id = tax.idLEFT JOIN m_unit_master unit ON t_good_receipt_note.unit_id = unit.unit_idWHERE t_good_receipt_note.is_deleted = falseGROUP BY t_good_receipt_note.id, t_good_receipt_note.grn_number, t_good_receipt_note.vendor_id, m_vendor.name, m_store.store_id, m_store.store_name, tax.id, tax.name, t_good_receipt_note.unit_id, t_good_receipt_note.added_date, t_good_receipt_note_detail.tax_percentage, t_good_receipt_note.total_amount, t_good_receipt_note.total_tax_ammount, t_good_receipt_note.total_discount, t_good_receipt_note.net_amount, unit.unit_id, unit.unit_name, unit.unit_address, m_vendor.gst_no, t_good_receipt_note.approve_status_id, t_good_receipt_note.invoice_number;

-- "procedure".get_purchase_return_gst source
CREATE OR REPLACE VIEW "procedure".get_purchase_return_gstAS SELECT DISTINCT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_store.store_id,unitinformation.unit_name,unitinformation.unit_address,t_returnable_gatepass.total_amt,t_returnable_gatepass.total_tax_amount,t_returnable_gatepass.net_amount,t_returnable_gatepass.remark,approvalstatus.status AS approvalstatus,m_status.status,requesttype.type AS requesttype,approvalstatus.id AS approvalstatus_id,m_status.id AS status_id,m_vendor.id AS vendor_id,m_item.name AS itemnamem,rgd.tax_id,rgd.tax_percentage,tax.name AS tax,rgd.total_tax_amount AS taxdetailamt,unitinformation.unit_id,unitinformation.imageFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail rgd ON t_batch.id = rgd.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = rgd.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = rgd.vendor_idJOIN unitinformation ON t_returnable_gatepass.unit_id = unitinformation.unit_idJOIN m_status approvalstatus ON t_returnable_gatepass.approval_status_id = approvalstatus.idLEFT JOIN m_status ON t_returnable_gatepass.status_id = m_status.idLEFT JOIN m_request_type requesttype ON t_returnable_gatepass.request_type_id = requesttype.idLEFT JOIN m_asset_type assettype ON t_returnable_gatepass.asset_type_id = t_returnable_gatepass.asset_type_idLEFT JOIN m_tax tax ON rgd.tax_id = tax.id;

-- "procedure".get_quotation source
CREATE OR REPLACE VIEW "procedure".get_quotationAS SELECT DISTINCT t_quotation_vendor.id,t_quotation_vendor.vq_number,t_quotation_request.qr_no,t_quotation_vendor.added_date,t_quotation_vendor.due_date,t_quotation_vendor.approved_date,t_quotation_request.added_date AS request_date,t_quotation_request.approved_date AS request_approved_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_quotation_request_detail.quantity,t_quotation_request_detail.warranty_period,t_quotation_request_detail.expected_technical_specification,(m_employee_master.first_name::text || ''::text) || m_employee_master.last_name::text AS username,(m_employee_master_1.first_name::text || ''::text) || m_employee_master_1.last_name::text AS quotation_username,unitinformation.unit_name,unitinformation.unit_address,fill.id AS vq_id,unitinformation.imageFROM procurement.t_quotation_vendorJOIN procurement.t_quotation_vendor_detail ON t_quotation_vendor.id = t_quotation_vendor_detail.vq_idJOIN procurement.t_quotation_fill fill ON t_quotation_vendor.id = fill.vq_idJOIN procurement.t_quotation_fill_detail qfd ON fill.id = qfd.quotation_fill_idJOIN m_vendor ON m_vendor.id = fill.vendor_idJOIN procurement.t_quotation_request ON t_quotation_request.id = t_quotation_vendor.qr_idJOIN procurement.t_quotation_request_detail ON t_quotation_request_detail.qr_id = t_quotation_request.id AND t_quotation_vendor_detail.qr_detail_id = t_quotation_request_detail.idJOIN m_item ON t_quotation_request_detail.item_id = m_item.idJOIN m_store ON t_quotation_vendor.store_id = m_store.store_idLEFT JOIN m_user_master ON m_user_master.user_id = t_quotation_request.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_user_master m_user_master_1 ON m_user_master_1.user_id = t_quotation_vendor.added_byLEFT JOIN m_employee_master m_employee_master_1 ON m_employee_master_1.user_id = m_user_master_1.user_idLEFT JOIN unitinformation ON t_quotation_vendor.unit_id = unitinformation.unit_idWHERE t_quotation_vendor_detail.is_deleted = false;

-- "procedure".get_reorderlevel source
CREATE OR REPLACE VIEW "procedure".get_reorderlevelAS SELECT DISTINCT m_item.id,m_item.code,m_item.name AS itemname,m_store.store_name,storemapper.max_qty,storemapper.min_qty,batch.batch_no,batch.expiry_date,storestock.available_qty,classification.classification,m_store.store_id,um.unit_name,um.unit_address,classification.id AS pharmacological_classification_id,um.unit_id,um.imageFROM m_store_item_mapper storemapperJOIN m_item ON storemapper.item_id = m_item.idJOIN m_store ON storemapper.store_id = m_store.store_idJOIN inventory.t_store_stock storestock ON storemapper.store_id = storestock.store_id AND m_store.store_id = storestock.store_idJOIN inventory.t_batch batch ON storestock.batch_id = batch.id AND batch.item_id = storemapper.item_idJOIN m_pharmacological_classification classification ON m_item.pharmacological_classification_id = classification.idLEFT JOIN unitinformation um ON storestock.unit_id = um.unit_idWHERE storestock.available_qty &lt;= storemapper.min_qtyORDER BY m_item.name;

-- "procedure".get_salesbills source
CREATE OR REPLACE VIEW "procedure".get_salesbillsAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(prefix.prefix_desc, '', registration.first_name, ' ', registration.middle_name, ' ', registration.last_name) AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,CASEWHEN COALESCE(t_sale.doctor_id, 0) &lt;&gt; 0 THEN (('Dr. '::text || ''::text) || (m_doctor_master.first_name::text || ' '::text)) || m_doctor_master.last_name::textWHEN COALESCE(t_sale.admission_id, 0) &lt;&gt; 0 THEN (('Dr. '::text || ''::text) || (admdoc.first_name::text || ' '::text)) || admdoc.last_name::textWHEN COALESCE(t_sale.temp_doctor_id, 0) &lt;&gt; 0 THEN ('Dr. '::text || ''::text) || tempdoc.doctor_name::textWHEN COALESCE(endoc.doctor_id, 0) &lt;&gt; 0 THEN (('Dr. '::text || ''::text) || (endoc.first_name::text || ' '::text)) || endoc.last_name::textELSE (('Dr. '::text || ''::text) || (m_doctor_master.first_name::text || ' '::text)) || m_doctor_master.last_name::textEND AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,0::double precision AS taxamount,0::double precision AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,0::double precision AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,concat(mwm.ward_name, ' / ', mbm.bed_desc)::character varying AS billing_bed_desc,COALESCE(cmpayee.company_desc, COALESCE(cm.company_desc, cm1.company_desc)) AS company_desc,pres.prescription_no,pres.prescription_date::date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,COALESCE(cmpayee.address, COALESCE(cm.address, cm1.address)) AS comp_address,sm.store_id,sm.store_nameFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_id AND t_sale_detail.is_active = trueLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idJOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor tempdoc ON tempdoc.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master endoc ON endoc.doctor_id = em.doctor_idLEFT JOIN doctor.m_doctor_master admdoc ON adm.admitting_doctor_id = admdoc.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN adt.m_ward_master mwm ON mwm.ward_id = admd.ward_idLEFT JOIN adt.m_bed_master mbm ON mbm.bed_id = admd.bed_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN opd.t_patient_sponsor_details spd ON t_sale.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spd1 ON t_sale.encounter_id = spd1.encounter_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm1 ON spd1.payee_id = cm1.company_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN pharmacy.t_pharmacy_bill_payee_details payee ON payee.t_sale_id = t_sale.id AND payee.payee_id &gt; 1LEFT JOIN t_company_master cmpayee ON cmpayee.company_id = payee.payee_idLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idLEFT JOIN m_store sm ON sm.store_id = t_sale.store_idWHERE t_sale.patient_id IS NOT NULLUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,0::double precision AS taxamount,0::double precision AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,t_temp_patient_registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,0::double precision AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,'walkin'::text AS opidnumber,''::text AS billing_bed_desc,''::text AS company_desc,''::text AS prescription_no,t_sale.added_date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,''::text AS comp_address,sm.store_id,sm.store_nameFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_id AND t_sale_detail.is_active = trueLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN m_store sm ON sm.store_id = t_sale.store_idWHERE t_sale.temp_patient_id IS NOT NULL;

-- "procedure".get_salesbills_1 source
CREATE OR REPLACE VIEW "procedure".get_salesbills_1AS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(prefix.prefix_desc, '', registration.first_name, ' ', registration.middle_name, ' ', registration.last_name) AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,CASEWHEN t_sale.sale_type_id = 2 THEN (emdoctor.first_name::text || ' '::text) || emdoctor.last_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,0::double precision AS taxamount,0::double precision AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,0::double precision AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,m_billing_bed_category_master.billing_bed_desc,COALESCE(cm.company_desc, cm1.company_desc) AS company_desc,pres.prescription_no,pres.prescription_date::date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,COALESCE(cm.address, cm1.address) AS comp_address,mbm.bed_number,concat(emp1.first_name, ' ', emp1.last_name) AS emp1FROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idJOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN doctor.m_doctor_master emdoctor ON em.doctor_id = emdoctor.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN adt.m_billing_bed_category_master ON admd.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_master mbm ON mbm.bed_id = admd.bed_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN opd.t_patient_sponsor_details spd ON t_sale.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spd1 ON t_sale.encounter_id = spd1.encounter_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm1 ON spd1.payee_id = cm1.company_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idLEFT JOIN m_user_master usermaster1 ON usermaster1.user_id = pres.added_byLEFT JOIN m_employee_master emp1 ON usermaster1.user_id = emp1.user_idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = trueUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,0::double precision AS taxamount,0::double precision AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,pim.patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,0::double precision AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,'walkin'::text AS opidnumber,''::text AS billing_bed_desc,''::text AS company_desc,''::text AS prescription_no,t_sale.added_date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,''::text AS comp_address,''::text AS bed_number,''::text AS emp1FROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN patientinformation pim ON t_sale.patient_id = pim.patient_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- "procedure".get_salesbills_2 source
CREATE OR REPLACE VIEW "procedure".get_salesbills_2AS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,pim.patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,m_billing_bed_category_master.billing_bed_desc,COALESCE(cm.company_desc, cm1.company_desc) AS company_desc,pres.prescription_no,pres.prescription_date::date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,COALESCE(cm.address, cm1.address) AS comp_addressFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN patientinformation pim ON t_sale.patient_id = pim.patient_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN adt.m_billing_bed_category_master ON admd.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN opd.t_patient_sponsor_details spd ON t_sale.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spd1 ON t_sale.encounter_id = spd1.encounter_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm1 ON spd1.payee_id = cm1.company_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = trueUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,pim.patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,'walkin'::text AS opidnumber,''::text AS billing_bed_desc,''::text AS company_desc,''::text AS prescription_no,t_sale.added_date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,''::text AS comp_addressFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN patientinformation pim ON t_sale.patient_id = pim.patient_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- "procedure".get_salesbills_prescription source
CREATE OR REPLACE VIEW "procedure".get_salesbills_prescriptionAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,t_sale.admission_id,t_sale.prescription_id,pres.prescription_no,pres.prescription_date,m_generic.name AS genericFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.patient_id IS NOT NULLUNIONSELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,t_sale.admission_id,t_sale.prescription_id,pres.prescription_no,pres.prescription_date,m_generic.name AS genericFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true AND t_sale_detail.is_deleted = false;

