CREATE OR REPLACE VIEW "procedure".get_salesbills_returnAS SELECT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_return_detail.return_tax_amount,CASEWHEN t_sale.sale_type_id = 2 THEN ((registration.first_name::text || ' '::text) || registration.last_name::text)::character varyingELSE t_temp_patient_registration.patient_nameEND AS patient_name,CASEWHEN t_sale.sale_type_id = 2 THEN ((m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text)::character varyingELSE t_temp_doctor.doctor_nameEND AS doctor_name,registration.uhid_number,CASEWHEN t_sale.sale_type_id = 2 THEN t_patient_details.address::character varyingELSE t_temp_patient_registration.addressEND AS address,m_item.name,t_batch.batch_no,um.unit_name,um.unit_address,um.imageFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idLEFT JOIN unitinformation um ON t_return.unit_id = um.unit_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.id;

