istration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN unitinformation ON t_return.unit_id = unitinformation.unit_idLEFT JOIN m_counter_master counter ON t_sale.counter_id = counter.counter_id;

