me,unitinformation.unit_address,unitinformation.unit_address_2,t_sale.sale_type_id,counter.counter_id,counter.counter_desc,unitinformation.image,t_return_detail.sale_id,registration.mobile_number,t_sale.bill_no,t_batch.expiry_date,unitinformation.unit_idFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_unit_master unitinformation ON t_return.unit_id = unitinformation.unit_idLEFT JOIN m_counter_master counter ON t_sale.counter_id = counter.counter_id;

-- "procedure".get_salesbillsreturn source
CREATE OR REPLACE VIEW "procedure".get_salesbillsreturnAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(registration.first_name::text, ' ', registration.middle_name::text, ' ', registration.last_name::text) AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,CASEWHEN COALESCE(t_sale.doctor_id, 0) &lt;&gt; 0 THEN (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textWHEN COALESCE(t_sale.admission_id, 0) &lt;&gt; 0 THEN (admdoc.first_name::text || ' '::text) || admdoc.last_name::textWHEN COALESCE(t_sale.temp_doctor_id, 0) &lt;&gt; 0 THEN tempdoc.doctor_name::textWHEN COALESCE(endoc.doctor_id, 0) &lt;&gt; 0 THEN (endoc.first_name::text || ' '::text) || endoc.last_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,concat(mwm.ward_name, ' / ', mbm.bed_desc)::character varying AS billing_bed_desc,COALESCE(cmpayee.company_desc, COALESCE(cm.company_desc, cm1.company_desc)) AS company_desc,pres.prescription_no,pres.prescription_date::date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,COALESCE(cmpayee.address, COALESCE(cm.address, cm1.address)) AS comp_address,COALESCE(tr.return_qty, 0::bigint) AS return_qtyFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor tempdoc ON tempdoc.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master endoc ON endoc.doctor_id = em.doctor_idLEFT JOIN doctor.m_doctor_master admdoc ON adm.admitting_doctor_id = admdoc.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN adt.m_ward_master mwm ON mwm.ward_id = admd.ward_idLEFT JOIN adt.m_bed_master mbm ON mbm.bed_id = admd.bed_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueLEFT JOIN opd.t_patient_sponsor_details spd ON t_sale.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spd1 ON t_sale.encounter_id = spd1.encounter_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm1 ON spd1.payee_id = cm1.company_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN pharmacy.t_pharmacy_bill_payee_details payee ON payee.t_sale_id = t_sale.id AND payee.payee_id &gt; 1LEFT JOIN t_company_master cmpayee ON cmpayee.company_id = payee.payee_idLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idLEFT JOIN ( SELECT sum(trd.return_qty) AS return_qty,trd.sale_detail_idFROM pharmacy.t_return tr_1LEFT JOIN pharmacy.t_return_detail trd ON tr_1.id = trd.return_idGROUP BY trd.sale_detail_id) tr ON tr.sale_detail_id = t_sale_detail.idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = trueUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,unitinformation.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,t_temp_patient_registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,'walkin'::text AS opidnumber,''::text AS billing_bed_desc,''::text AS company_desc,''::text AS prescription_no,t_sale.added_date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,''::text AS comp_address,COALESCE(tr.return_qty, 0::bigint) AS return_qtyFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN ( SELECT sum(trd.return_qty) AS return_qty,trd.sale_detail_idFROM pharmacy.t_return tr_1LEFT JOIN pharmacy.t_return_detail trd ON tr_1.id = trd.return_idGROUP BY trd.sale_detail_id) tr ON tr.sale_detail_id = t_sale_detail.idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- "procedure".get_salesforipd source
CREATE OR REPLACE VIEW "procedure".get_salesforipdAS SELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patient_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_item.hsn_code,t_batch.cop,COALESCE(t_sale.bill_id, 0) AS bill_id,t_sale.admission_id,t_batch.id AS batch_id,m_item.id AS itemid,t_sale.unit_id,t_sale.outstanding_amount,t_sale.paid_amount,0::numeric AS netrefund,t_sale_detail.id AS saledetailid,pim.uhid_number,concat('Dr.', '', dm.first_name, ' ', dm.last_name) AS doctorname,pimd.address,um.unit_name,um.unit_address,um.unit_email_id,um.image,um.unit_contact,um.unit_website,ordd.sale_detail_id,''::text AS order_no,t_sale_detail.package_consumption_amt,ip.company_desc,ip.admission_numberFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN t_order_details ordd ON ordd.sale_detail_id = t_sale_detail.id AND ordd.ord_cancelled = 'N'::bpchar AND ordd.status = 'A'::bpchar AND ordd.is_drug = 'Y'::bpchar AND ordd.service_is_billed = 1JOIN patient.t_patient_registration pim ON t_sale.patient_id = pim.patient_idLEFT JOIN patient.t_patient_details pimd ON pim.patient_id = pimd.patient_idLEFT JOIN m_patient_visit_metadata ip ON ip.admission_id = t_sale.admission_idLEFT JOIN m_prefix_master prefix ON pim.prefix_id = prefix.prefix_idLEFT JOIN doctor.m_doctor_master dm ON t_sale.doctor_id = dm.doctor_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idLEFT JOIN m_unit_master um ON t_sale.unit_id = um.unit_idJOIN m_item ON t_batch.item_id = m_item.id AND t_sale.is_active = trueWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_deleted = false;

-- "procedure".get_salesforipd_interim source
CREATE OR REPLACE VIEW "procedure".get_salesforipd_interimAS SELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patient_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_item.hsn_code,t_batch.cop,COALESCE(t_sale.bill_id, 0) AS bill_id,t_sale.admission_id,t_batch.id AS batch_id,m_item.id AS itemid,t_sale.unit_id,t_sale.outstanding_amount,t_sale.paid_amount,COALESCE(ord.net_amount, 0::numeric) AS netrefund,t_sale_detail.id AS saledetailid,pim.uhid_number,concat('Dr.', '', dm.first_name, ' ', dm.last_name) AS doctorname,pimd.address,tibd.intrim_bill_id,0 AS order_details_id,um.unit_name,um.unit_address,um.unit_email_id,um.unit_contact,um.unit_websiteFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN t_order_details ordd ON ordd.sale_detail_id = t_sale_detail.id AND ordd.ord_cancelled = 'N'::bpchar AND ordd.status = 'A'::bpchar AND ordd.is_drug = 'Y'::bpcharJOIN billing.t_intrim_bill tibd ON tibd.admission_id = t_sale.admission_idJOIN patient.t_patient_registration pim ON t_sale.patient_id = pim.patient_idLEFT JOIN patient.t_patient_details pimd ON pim.patient_id = pimd.patient_idLEFT JOIN m_prefix_master prefix ON pim.prefix_id = prefix.prefix_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN adt.t_admission ta ON ta.admission_id = tibd.admission_idLEFT JOIN doctor.m_doctor_master dm ON ta.doctor_id = dm.doctor_idJOIN m_unit_master um ON um.unit_id = t_sale.unit_idJOIN m_item ON t_batch.item_id = m_item.id AND t_sale.is_active = trueLEFT JOIN ( SELECT sum(od.net_amount) AS net_amount,od.sale_detail_idFROM t_order_details odWHERE od.order_qty &lt; 0 AND od.ord_cancelled = 'N'::bpchar AND od.status = 'A'::bpchar AND od.is_drug = 'Y'::bpcharGROUP BY od.sale_detail_id) ord ON ord.sale_detail_id = t_sale_detail.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_deleted = false;

-- "procedure".get_salesforipd_return source
CREATE OR REPLACE VIEW "procedure".get_salesforipd_returnAS SELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_item.hsn_code,t_batch.cop,COALESCE(t_sale.bill_id, 0) AS bill_id,t_sale.admission_id,t_batch.id AS batch_id,m_item.id AS itemid,t_sale.unit_id,t_sale.outstanding_amount,t_sale.paid_amount,COALESCE(ord.net_amount, 0::numeric) AS netrefund,t_sale_detail.id AS saledetailid,ordd.sale_detail_id,t_sale.patient_id,t_sale.visit_type_id,ord.order_qtyFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN t_order_details ordd ON ordd.sale_detail_id = t_sale_detail.id AND ordd.ord_cancelled = 'N'::bpchar AND ordd.status = 'A'::bpchar AND ordd.is_drug = 'Y'::bpchar AND ordd.service_is_billed = 1JOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.id AND t_sale.is_active = trueLEFT JOIN ( SELECT sum(od.net_amount + od.package_consumption_amt) AS net_amount,od.sale_detail_id,sum(od.order_qty) AS order_qtyFROM t_order_details odWHERE od.order_qty &lt; 0 AND od.ord_cancelled = 'N'::bpchar AND od.status = 'A'::bpchar AND od.is_drug = 'Y'::bpchar AND od.service_is_billed = 1GROUP BY od.sale_detail_id) ord ON ord.sale_detail_id = t_sale_detail.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_deleted = false AND ord.net_amount &lt; 0::numeric;

-- "procedure".get_salesgrossmargin source
CREATE OR REPLACE VIEW "procedure".get_salesgrossmarginAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_batch.cop,t_sale.sale_type_id,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,t_sale.paid_amount,t_sale.status_idFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = true;

-- "procedure".get_stockvalue source
CREATE OR REPLACE VIEW "procedure".get_stockvalueAS SELECT m_item.id,m_item.code,m_item.hsn_code,m_item.name,m_store.store_name,t_batch.quantity,t_batch.batch_no,t_batch.expiry_date,t_batch.current_quantity,t_batch.cop,t_batch.rate,t_batch.selling_price,t_batch.vendor_id,t_batch.id AS batchid,m_store.store_id,m_vendor.name AS vendorname,um.unit_id,um.unit_name,um.unit_address,um.imageFROM inventory.t_store_stockJOIN inventory.t_batch ON t_store_stock.batch_id = t_batch.idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_store ON t_store_stock.store_id = m_store.store_idLEFT JOIN unitinformation um ON um.unit_id = t_store_stock.unit_idLEFT JOIN m_vendor ON m_vendor.id = t_batch.vendor_id;

-- "procedure".get_vendorwisereceipts source
CREATE OR REPLACE VIEW "procedure".get_vendorwisereceiptsAS SELECT DISTINCT rsm.id,rsm.receipt_number,rsm.amount_received_from,COALESCE(rsm.amount_data, 0::double precision) AS amount_data,rsm.added_date AS recdate,grn.grn_number,grn.added_date AS grndate,grn.bill_type_name,COALESCE(grn.paid_amount, 0::double precision) AS paid_amount,COALESCE(grn.balance_amount, 0::double precision) AS balance_amount,m_vendor.name AS vendor,m_store.store_name,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.net_amount,paymode.payment_mode_desc,rsd.amount,rsd.cheque_number,rsd.cheque_date,bank.bank_name,m_status.status AS paymentstatus,grnstatus.status AS grnstatus,um.unit_name,um.unit_address,usermaster.user_name,grn.id AS grn_id,um.image,um.unit_id,m_store.store_id,m_vendor.id AS vendor_idFROM procurement.t_good_receipt_note grnLEFT JOIN procurement.t_grn_settlement_receipt_detail rsd ON grn.id = rsd.grn_idLEFT JOIN procurement.t_grn_settlement_receipt rsm ON rsm.id = rsd.grn_settlement_idJOIN m_vendor ON grn.vendor_id = m_vendor.idJOIN m_store ON grn.store_id = m_store.store_idLEFT JOIN m_payment_mode_master paymode ON rsd.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON rsd.bank_id = bank.bank_idLEFT JOIN m_status ON rsd.status_id = m_status.idLEFT JOIN m_status grnstatus ON grn.status_id = grnstatus.idLEFT JOIN m_unit_master um ON grn.unit_id = um.unit_idLEFT JOIN m_user_master usermaster ON rsm.added_by = usermaster.user_id;

-- "procedure".getgst source
CREATE OR REPLACE VIEW "procedure".getgstAS SELECT DISTINCT sales.id,sales.bill_no,sales.tax_amount,sales.total_amount,sales.net_amount,m_item.name AS itemname,taxcompomaster.component,taxcompomaster.id AS taxcompoid,taxcompo.percentage,taxcompo.amount,sales.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,salesdetails.net_amount AS salesdetailsnet,salesdetails.tax_amount AS taxdetailamt,salesdetails.tax_percentage,unitinformation.unit_id,unitinformation.imageFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN inventory.t_batch batch ON salesdetails.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idJOIN pharmacy.t_sale_detail_tax_componenet taxcompo ON salesdetails.id = taxcompo.sale_detail_idJOIN m_tax_component taxcompomaster ON taxcompo.tax_component_id = taxcompomaster.idJOIN m_tax_detail taxdetail ON taxcompo.tax_component_id = taxdetail.tax_component_idJOIN unitinformation ON sales.unit_id = unitinformation.unit_idORDER BY sales.id;

-- "procedure".getgstsalesreturn source
CREATE OR REPLACE VIEW "procedure".getgstsalesreturnAS SELECT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_sale_detail.tax_id,t_sale_detail.tax_percentage,t_return_detail.return_tax_amount,t_sale_detail_tax_componenet.percentage AS taxcomper,t_sale_detail_tax_componenet.amount AS taxcompamount,taxcompomaster.component,taxcompomaster.id AS taxcompoid,m_item.name,t_batch.batch_no,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_sale.sale_type_id,unitinformation.unit_id,unitinformation.imageFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN pharmacy.t_sale_detail_tax_componenet ON t_sale_detail.id = t_sale_detail_tax_componenet.sale_detail_idJOIN m_tax_component taxcompomaster ON t_sale_detail_tax_componenet.tax_component_id = taxcompomaster.idJOIN unitinformation ON t_return.unit_id = unitinformation.unit_id;

-- "procedure".getgstsalesreturninvoice source
CREATE OR REPLACE VIEW "procedure".getgstsalesreturninvoiceAS SELECT DISTINCT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_sale_detail.tax_id,t_sale_detail.tax_percentage,t_return_detail.return_tax_amount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_sale.sale_type_id,unitinformation.unit_id,unitinformation.imageFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN unitinformation ON t_return.unit_id = unitinformation.unit_id;

-- "procedure".getpendingissuesdetails_1 source
CREATE OR REPLACE VIEW "procedure".getpendingissuesdetails_1AS SELECT tid.issue_id AS id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,concat(registration.first_name, ' ', registration.middle_name, ' ', registration.last_name) AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,CASEWHEN t_sale.encounter_id IS NOT NULL THEN (endoc.first_name::text || ' '::text) || endoc.last_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_name,m_unit_master.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,m_unit_master.unit_id,m_unit_master.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,mwm.ward_name AS billing_bed_desc,COALESCE(cm.company_desc, cm1.company_desc) AS company_desc,pres.prescription_no,pres.prescription_date,msm.schedule_description,storageunit.name AS storageunit,COALESCE(cm.address, cm1.address) AS comp_address,mbm.bed_desc,concat(emp1.first_name, ' ', emp1.last_name) AS emp1,sm.store_id,sm.store_name,issue.issue_noFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN doctor.m_doctor_master endoc ON endoc.doctor_id = em.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idLEFT JOIN m_store sm ON sm.store_id = t_sale.store_idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN adt.m_ward_master mwm ON mwm.ward_id = admd.ward_idLEFT JOIN adt.m_bed_master mbm ON admd.bed_id = mbm.bed_idJOIN m_unit_master ON t_sale.unit_id = m_unit_master.unit_id AND t_sale.is_active = trueLEFT JOIN opd.t_patient_sponsor_details spd ON t_sale.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spd1 ON t_sale.encounter_id = spd1.encounter_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm1 ON spd1.payee_id = cm1.company_id AND spd1.priority_id = 1 AND spd1.status = 'A'::bpcharLEFT JOIN pharmacy.t_prescription pres ON t_sale.prescription_id = pres.idLEFT JOIN pharmacy.t_issue_detail tid ON tid.sale_detail_id = t_sale_detail.idLEFT JOIN pharmacy.t_issue issue ON issue.id = tid.issue_idLEFT JOIN m_user_master usermaster1 ON usermaster1.user_id = pres.added_byLEFT JOIN m_employee_master emp1 ON usermaster1.user_id = emp1.user_idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = trueUNIONSELECT DISTINCT issue.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_name,m_unit_master.unit_contact,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,uom.unit AS uomunit,m_unit_master.unit_id,m_unit_master.image,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / t_sale_detail.tax_percentageEND AS taxamount,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_sale_detail.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS cop_with_tax,t_sale.admission_id,t_sale_detail.id AS salesdetailsid,t_temp_patient_registration.mobile_number AS patientmobile,m_status.status,m_status.id AS status_id,t_sale.round_off,t_sale.paid_amount,t_sale.outstanding_amount,m_item.is_kit,t_sale.encounter_id,t_sale.bill_id,CASEWHEN t_sale_detail.tax_percentage = 0::double precision THEN 0::double precisionELSE t_batch.rate * 100::double precision / (100::double precision + t_sale_detail.tax_percentage)END AS unitrate,concat(emp.first_name, ' ', emp.last_name) AS emp,'walkin'::text AS opidnumber,''::text AS billing_bed_desc,''::text AS company_desc,''::text AS prescription_no,t_sale.added_date AS prescription_date,msm.schedule_description,storageunit.name AS storageunit,''::text AS comp_address,''::text AS bed_desc,''::text AS emp1,sm.store_id,sm.store_name,issue.issue_noFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_uom_unit uom ON t_batch.uom_unit_id = uom.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_store sm ON sm.store_id = t_sale.store_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN m_user_master usermaster ON usermaster.user_id = t_sale.added_byLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idJOIN m_unit_master ON t_sale.unit_id = m_unit_master.unit_id AND t_sale.is_active = trueLEFT JOIN pharmacy.t_issue issue ON t_sale.id = issue.sale_idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- "procedure".getsalesgstinvoice source
CREATE OR REPLACE VIEW "procedure".getsalesgstinvoiceAS SELECT DISTINCT sales.id,sales.bill_no,sales.tax_amount,sales.total_amount,sales.net_amount,sales.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,salesdetails.net_amount AS salesdetailsnet,salesdetails.tax_amount AS taxdetailamt,salesdetails.tax_percentage,unitinformation.unit_id,unitinformation.imageFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN unitinformation ON sales.unit_id = unitinformation.unit_idORDER BY sales.id;

-- "procedure".getsalesgstwithtaxable source
CREATE OR REPLACE VIEW "procedure".getsalesgstwithtaxableAS SELECT DISTINCT sales.id,sales.bill_no::character varying AS bill_no,sales.total_amount,sales.tax_amount,sales.total_discount_amount,sales.net_amount,sales.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.image,CASEWHEN sales.temp_patient_id IS NULL THEN ((pt.first_name::text || ' '::text) || pt.last_name::text)::character varyingELSE ptt.patient_nameEND AS patient_name,COALESCE(( SELECT sum(t_return.total_return_amt) AS total_return_amtFROM pharmacy.t_returnWHERE t_return.sale_id = sales.id), 0::double precision) AS total_return_amt,sales.tax_amount AS totaltax,COALESCE(tax5.taxamount, 0::double precision) AS tax5,COALESCE(tax12.taxamount, 0::double precision) AS tax12,COALESCE(tax18.taxamount, 0::double precision) AS tax18,COALESCE(tax28.taxamount, 0::double precision) AS tax28,COALESCE(tax5.taxable, 0::double precision) AS taxable5,COALESCE(tax12.taxable, 0::double precision) AS taxable12,COALESCE(tax18.taxable, 0::double precision) AS taxable18,COALESCE(tax28.taxable, 0::double precision) AS taxable28,totalsales.net,COALESCE(tax0.taxable, 0::double precision) AS taxable0,COALESCE(tax0.taxamount, 0::double precision) AS tax0,sales.sale_type_id,saletype.type AS saletype,sales.store_id,store.store_name,COALESCE(sales.visit_type_id, 1) AS visit_type_idFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN m_unit_master unitinformation ON sales.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sales.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sales.patient_idLEFT JOIN pharmacy.m_sale_type saletype ON sales.sale_type_id = saletype.idLEFT JOIN m_store store ON sales.store_id = store.store_idJOIN ( SELECTCASEWHEN sum(t_sale_detail.package_consumption_amt) = 0::double precision THEN sum(t_sale_detail.net_amount)ELSE sum(t_sale_detail.package_consumption_amt)END AS net,t_sale_detail.sale_idFROM pharmacy.t_sale_detailGROUP BY t_sale_detail.sale_id) totalsales ON totalsales.sale_id = sales.idLEFT JOIN ( SELECT sum(t_sale_detail.tax_amount) AS taxamount,(sum(t_sale_detail.total_amount) - sum(t_sale_detail.discount_amount)) * 100::double precision / (100::double precision + t_sale_detail.tax_percentage) AS taxable,t_sale_detail.tax_percentage,t_sale_detail.sale_idFROM pharmacy.t_sale_detailWHERE t_sale_detail.tax_percentage = 0::double precision AND t_sale_detail.quantity &lt;&gt; 0GROUP BY t_sale_detail.tax_percentage, t_sale_detail.sale_id) tax0 ON tax0.sale_id = sales.idLEFT JOIN ( SELECT sum(t_sale_detail.tax_amount) AS taxamount,(sum(t_sale_detail.total_amount) - sum(t_sale_detail.discount_amount)) * 100::double precision / (100::double precision + 5::double precision) AS taxable,t_sale_detail.tax_percentage,t_sale_detail.sale_idFROM pharmacy.t_sale_detailWHERE t_sale_detail.tax_percentage = 5::double precision AND t_sale_detail.quantity &lt;&gt; 0GROUP BY t_sale_detail.tax_percentage, t_sale_detail.sale_id) tax5 ON tax5.sale_id = sales.idLEFT JOIN ( SELECT sum(t_sale_detail.tax_amount) AS taxamount,(sum(t_sale_detail.total_amount) - sum(t_sale_detail.discount_amount)) * 100::double precision / (100::double precision + 12::double precision) AS taxable,t_sale_detail.tax_percentage,t_sale_detail.sale_idFROM pharmacy.t_sale_detailWHERE t_sale_detail.tax_percentage = 12::double precision AND t_sale_detail.quantity &lt;&gt; 0GROUP BY t_sale_detail.tax_percentage, t_sale_detail.sale_id) tax12 ON tax12.sale_id = sales.idLEFT JOIN ( SELECT sum(t_sale_detail.tax_amount) AS taxamount,(sum(t_sale_detail.total_amount) - sum(t_sale_detail.discount_amount)) * 100::double precision / (100::double precision + 18::double precision) AS taxable,t_sale_detail.tax_percentage,t_sale_detail.sale_idFROM pharmacy.t_sale_detailWHERE t_sale_detail.tax_percentage = 18::double precision AND t_sale_detail.quantity &lt;&gt; 0GROUP BY t_sale_detail.tax_percentage, t_sale_detail.sale_id) tax18 ON tax18.sale_id = sales.idLEFT JOIN ( SELECT sum(t_sale_detail.tax_amount) AS taxamount,(sum(t_sale_detail.total_amount) - sum(t_sale_detail.discount_amount)) * 100::double precision / (100::double precision + 28::double precision) AS taxable,t_sale_detail.tax_percentage,t_sale_detail.sale_idFROM pharmacy.t_sale_detailWHERE t_sale_detail.tax_percentage = 28::double precision AND t_sale_detail.quantity &lt;&gt; 0GROUP BY t_sale_detail.tax_percentage, t_sale_detail.sale_id) tax28 ON tax28.sale_id = sales.idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = false;

-- "procedure".getsalesgstwithtaxabledetails source
CREATE OR REPLACE VIEW "procedure".getsalesgstwithtaxabledetailsAS SELECT DISTINCT sales.id,CASEWHEN sales.sale_type_id = 1 THEN concat('IPD-', sales.id)::character varyingELSE sales.bill_noEND AS bill_no,sales.total_amount,sales.tax_amount,sales.total_discount_amount,sales.net_amount,sales.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.image,CASEWHEN sales.temp_patient_id IS NULL THEN ((pt.first_name::text || ' '::text) || pt.last_name::text)::character varyingELSE ptt.patient_nameEND AS patient_name,COALESCE(( SELECT sum(trd.return_amt) AS total_return_amtFROM pharmacy.t_return trJOIN pharmacy.t_return_detail trd ON trd.return_id = tr.idWHERE trd.sale_detail_id = salesdetails.id), 0::double precision) AS total_return_amt,sales.tax_amount AS totaltax,m_item.name AS itemname,m_item.hsn_code,m_item.id AS itemid,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 0::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 0::double precision) AS taxable0,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 5::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 5::double precision) * 5::double precision / 100::double precision AS tax5,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 5::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 5::double precision) AS taxable5,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 12::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 12::double precision) * 12::double precision / 100::double precision AS tax12,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 12::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 12::double precision) AS taxable12,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 18::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 18::double precision) * 18::double precision / 100::double precision AS tax18,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 18::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 18::double precision) AS taxable18,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 28::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 28::double precision) * 28::double precision / 100::double precision AS tax28,CASEWHEN salesdetails.package_consumption_amt = 0::double precision AND salesdetails.tax_percentage = 28::double precision THEN salesdetails.net_amountELSE salesdetails.package_consumption_amtEND * 100::double precision / (100::double precision + 28::double precision) AS taxable28,salesdetails.net_amount AS net,sales.sale_type_id,saletype.type AS saletype,sales.store_id,salesdetails.id AS salesdetailsidFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN inventory.t_batch ON t_batch.id = salesdetails.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_unit_master unitinformation ON sales.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sales.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sales.patient_idLEFT JOIN pharmacy.m_sale_type saletype ON sales.sale_type_id = saletype.idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = false AND sales.is_active = true;

-- "procedure".getsalesreturngstwithtaxable source
CREATE OR REPLACE VIEW "procedure".getsalesreturngstwithtaxableAS SELECT DISTINCT sales.id,rt.return_no AS bill_no,sales.total_amount,sales.tax_amount,sales.total_discount_amount,sales.net_amount,rt.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.image,CASEWHEN sales.temp_patient_id IS NULL THEN ((pt.first_name::text || ' '::text) || pt.last_name::text)::character varyingELSE ptt.patient_nameEND AS patient_name,( SELECT sum(t_return.total_return_amt) AS total_return_amtFROM pharmacy.t_returnWHERE t_return.sale_id = sales.id) AS total_return_amt,sales.tax_amount AS totaltax,COALESCE(tax5.taxamount, 0::double precision) AS tax5,COALESCE(tax12.taxamount, 0::double precision) AS tax12,COALESCE(tax18.taxamount, 0::double precision) AS tax18,COALESCE(tax28.taxamount, 0::double precision) AS tax28,COALESCE(tax5.taxable, 0::double precision) AS taxable5,COALESCE(tax12.taxable, 0::double precision) AS taxable12,COALESCE(tax18.taxable, 0::double precision) AS taxable18,COALESCE(tax28.taxable, 0::double precision) AS taxable28,sales.sale_type_id,saletype.type AS saletype,sales.bill_no AS salesno,sales.store_idFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN pharmacy.t_return rt ON sales.id = rt.sale_idJOIN pharmacy.t_return_detail rtd ON salesdetails.id = rtd.sale_detail_idJOIN pharmacy.m_sale_type saletype ON sales.sale_type_id = saletype.idJOIN m_unit_master unitinformation ON sales.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sales.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sales.patient_idLEFT JOIN ( SELECT sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) * sale_detail.tax_percentage / 100::double precision AS taxamount,sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) AS taxable,sale_detail.tax_percentage,return_detail.sale_idFROM pharmacy.t_return_detail return_detailJOIN pharmacy.t_sale_detail sale_detail ON return_detail.sale_detail_id = sale_detail.idWHERE sale_detail.tax_percentage = 5::double precisionGROUP BY sale_detail.tax_percentage, return_detail.sale_id) tax5 ON tax5.sale_id = sales.idLEFT JOIN ( SELECT sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) * sale_detail.tax_percentage / 100::double precision AS taxamount,sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) AS taxable,sale_detail.tax_percentage,return_detail.sale_idFROM pharmacy.t_return_detail return_detailJOIN pharmacy.t_sale_detail sale_detail ON return_detail.sale_detail_id = sale_detail.idWHERE sale_detail.tax_percentage = 12::double precisionGROUP BY sale_detail.tax_percentage, return_detail.sale_id) tax12 ON tax12.sale_id = sales.idLEFT JOIN ( SELECT sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) * sale_detail.tax_percentage / 100::double precision AS taxamount,sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) AS taxable,sale_detail.tax_percentage,return_detail.sale_idFROM pharmacy.t_return_detail return_detailJOIN pharmacy.t_sale_detail sale_detail ON return_detail.sale_detail_id = sale_detail.idWHERE sale_detail.tax_percentage = 18::double precisionGROUP BY sale_detail.tax_percentage, return_detail.sale_id) tax18 ON tax18.sale_id = sales.idLEFT JOIN ( SELECT sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) * sale_detail.tax_percentage / 100::double precision AS taxamount,sum(return_detail.return_amt) * 100::double precision / (100::double precision + sale_detail.tax_percentage) AS taxable,sale_detail.tax_percentage,return_detail.sale_idFROM pharmacy.t_return_detail return_detailJOIN pharmacy.t_sale_detail sale_detail ON return_detail.sale_detail_id = sale_detail.idWHERE sale_detail.tax_percentage = 28::double precisionGROUP BY sale_detail.tax_percentage, return_detail.sale_id) tax28 ON tax28.sale_id = sales.idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = falseUNION ALLSELECT DISTINCT sale.id,issuereturn.return_no AS bill_no,sale.total_amount,sale.tax_amount,sale.total_discount_amount,sale.net_amount,issuereturn.added_date AS salesdate,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.image,CASEWHEN sale.temp_patient_id IS NULL THEN ((pt.first_name::text || ' '::text) || pt.last_name::text)::character varyingELSE ptt.patient_nameEND AS patient_name,( SELECT sum(batchm.amount) AS sumFROM pharmacy.t_issue_detail issuedJOIN pharmacy.t_issue_detail_batch_mapper batchm ON batchm.issue_detail_id = issued.idJOIN pharmacy.t_patient_issue_return_detail rd ON rd.issue_batch_mapper_id = batchm.idJOIN pharmacy.t_sale_detail saledet ON saledet.id = issued.sale_detail_idJOIN pharmacy.t_sale sa ON sa.id = saledet.sale_idWHERE sa.id = sale.id) AS total_return_amt,sale.tax_amount AS totaltax,COALESCE(tax5.taxamount, 0::double precision) AS tax5,COALESCE(tax12.taxamount, 0::double precision) AS tax12,COALESCE(tax18.taxamount, 0::double precision) AS tax18,COALESCE(tax28.taxamount, 0::double precision) AS tax28,COALESCE(tax5.taxable, 0::double precision) AS taxable5,COALESCE(tax12.taxable, 0::double precision) AS taxable12,COALESCE(tax18.taxable, 0::double precision) AS taxable18,COALESCE(tax28.taxable, 0::double precision) AS taxable28,sale.sale_type_id,saletype.type AS saletype,sale.bill_no AS salesno,sale.store_idFROM pharmacy.t_patient_issue_return issuereturnJOIN pharmacy.t_patient_issue_return_detail issueretrundetails ON issuereturn.id = issueretrundetails.patient_issue_return_idJOIN pharmacy.t_issue_detail_batch_mapper issuebatchmapper ON issueretrundetails.issue_batch_mapper_id = issuebatchmapper.idJOIN pharmacy.t_issue_detail issuedetails ON issuebatchmapper.issue_detail_id = issuedetails.idJOIN pharmacy.t_sale_detail salesdetail ON salesdetail.id = issuedetails.sale_detail_idJOIN pharmacy.t_sale sale ON salesdetail.sale_id = sale.idJOIN pharmacy.m_sale_type saletype ON sale.sale_type_id = saletype.idJOIN m_unit_master unitinformation ON issuereturn.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sale.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sale.patient_idLEFT JOIN ( SELECT sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) * issued.tax_percentage / 100::double precision AS taxamount,sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) AS taxable,issued.tax_percentage,sa.id,rd.patient_issue_return_idFROM pharmacy.t_issue_detail issuedJOIN pharmacy.t_issue_detail_batch_mapper batchm ON batchm.issue_detail_id = issued.idJOIN pharmacy.t_patient_issue_return_detail rd ON rd.issue_batch_mapper_id = batchm.idJOIN pharmacy.t_sale_detail saledet ON saledet.id = issued.sale_detail_idJOIN pharmacy.t_sale sa ON sa.id = saledet.sale_idWHERE issued.tax_percentage = 5::double precisionGROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax5 ON tax5.id = sale.idLEFT JOIN ( SELECT sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) * issued.tax_percentage / 100::double precision AS taxamount,sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) AS taxable,issued.tax_percentage,sa.id,rd.patient_issue_return_idFROM pharmacy.t_issue_detail issuedJOIN pharmacy.t_issue_detail_batch_mapper batchm ON batchm.issue_detail_id = issued.idJOIN pharmacy.t_patient_issue_return_detail rd ON rd.issue_batch_mapper_id = batchm.idJOIN pharmacy.t_sale_detail saledet ON saledet.id = issued.sale_detail_idJOIN pharmacy.t_sale sa ON sa.id = saledet.sale_idWHERE issued.tax_percentage = 12::double precisionGROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax12 ON tax12.id = sale.idLEFT JOIN ( SELECT sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) * issued.tax_percentage / 100::double precision AS taxamount,sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) AS taxable,issued.tax_percentage,sa.id,rd.patient_issue_return_idFROM pharmacy.t_issue_detail issuedJOIN pharmacy.t_issue_detail_batch_mapper batchm ON batchm.issue_detail_id = issued.idJOIN pharmacy.t_patient_issue_return_detail rd ON rd.issue_batch_mapper_id = batchm.idJOIN pharmacy.t_sale_detail saledet ON saledet.id = issued.sale_detail_idJOIN pharmacy.t_sale sa ON sa.id = saledet.sale_idWHERE issued.tax_percentage = 18::double precisionGROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax18 ON tax18.id = sale.idLEFT JOIN ( SELECT sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) * issued.tax_percentage / 100::double precision AS taxamount,sum(batchm.amount) * 100::double precision / (100::double precision + issued.tax_percentage) AS taxable,issued.tax_percentage,sa.id,rd.patient_issue_return_idFROM pharmacy.t_issue_detail issuedJOIN pharmacy.t_issue_detail_batch_mapper batchm ON batchm.issue_detail_id = issued.idJOIN pharmacy.t_patient_issue_return_detail rd ON rd.issue_batch_mapper_id = batchm.idJOIN pharmacy.t_sale_detail saledet ON saledet.id = issued.sale_detail_idJOIN pharmacy.t_sale sa ON sa.id = saledet.sale_idWHERE issued.tax_percentage = 28::double precisionGROUP BY issued.tax_percentage, sa.id, rd.patient_issue_return_id) tax28 ON tax28.id = sale.id;

