e precision) AS taxable18,COALESCE(sum(tax28.return_amt) * 100::double precision / (100::double precision + salesdetails.tax_percentage), 0::double precision) AS taxable28,sales.sale_type_id,saletype.type AS saletype,sales.bill_no AS salesno,sales.store_id,rt.id AS returnid,store.store_name,COALESCE(sales.visit_type_id, 1) AS visit_type_idFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN pharmacy.t_return_detail rtd ON salesdetails.id = rtd.sale_detail_idJOIN pharmacy.t_return rt ON rtd.return_id = rt.idLEFT JOIN pharmacy.t_return_detail tax0 ON salesdetails.id = tax0.sale_detail_id AND salesdetails.tax_percentage = 0::double precision AND tax0.sale_id = salesdetails.sale_id AND tax0.return_id = rt.idLEFT JOIN pharmacy.t_return_detail tax5 ON salesdetails.id = tax5.sale_detail_id AND salesdetails.tax_percentage = 5::double precision AND tax5.sale_id = salesdetails.sale_id AND tax5.return_id = rt.idLEFT JOIN pharmacy.t_return_detail tax12 ON salesdetails.id = tax12.sale_detail_id AND salesdetails.tax_percentage = 12::double precision AND tax12.sale_id = salesdetails.sale_id AND tax12.return_id = rt.idLEFT JOIN pharmacy.t_return_detail tax18 ON salesdetails.id = tax18.sale_detail_id AND salesdetails.tax_percentage = 18::double precision AND tax18.sale_id = salesdetails.sale_id AND tax18.return_id = rt.idLEFT JOIN pharmacy.t_return_detail tax28 ON salesdetails.id = tax28.sale_detail_id AND salesdetails.tax_percentage = 28::double precisionJOIN pharmacy.m_sale_type saletype ON sales.sale_type_id = saletype.idJOIN m_unit_master unitinformation ON sales.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sales.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sales.patient_idLEFT JOIN m_store store ON sales.store_id = store.store_idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = falseGROUP BY sales.id, rt.return_no, sales.total_amount, sales.tax_amount, sales.total_discount_amount, sales.net_amount, rt.added_date, sales.unit_id, pt.first_name, pt.last_name, ptt.patient_name, sales.sale_type_id, salesdetails.tax_percentage, rt.sale_id, saletype.type, sales.bill_no, sales.store_id, rt.id, store.store_nameUNION ALLSELECT DISTINCT sale.id,issuereturn.return_no AS bill_no,sale.total_amount,sale.tax_amount,sale.total_discount_amount,sale.net_amount,issuereturn.added_date AS salesdate,sale.unit_id,CASEWHEN sale.temp_patient_id IS NULL THEN ((pt.first_name::text || ' '::text) || pt.last_name::text)::character varyingELSE ptt.patient_nameEND AS patient_name,sum(issuebatchmapper.amount) AS total_return_amt,sale.tax_amount AS totaltax,COALESCE(sum(tax0.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage) * issuedetails.tax_percentage / 100::double precision, 0::double precision) AS tax0,COALESCE(sum(tax5.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage) * issuedetails.tax_percentage / 100::double precision, 0::double precision) AS tax5,COALESCE(sum(tax12.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage) * issuedetails.tax_percentage / 100::double precision, 0::double precision) AS tax12,COALESCE(sum(tax18.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage) * issuedetails.tax_percentage / 100::double precision, 0::double precision) AS tax18,COALESCE(sum(tax28.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage) * issuedetails.tax_percentage / 100::double precision, 0::double precision) AS tax28,COALESCE(sum(tax0.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage), 0::double precision) AS taxable0,COALESCE(sum(tax5.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage), 0::double precision) AS taxable5,COALESCE(sum(tax12.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage), 0::double precision) AS taxable12,COALESCE(sum(tax18.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage), 0::double precision) AS taxable18,COALESCE(sum(tax28.amount) * 100::double precision / (100::double precision + issuedetails.tax_percentage), 0::double precision) AS taxable28,sale.sale_type_id,saletype.type AS saletype,sale.bill_no AS salesno,sale.store_id,issuereturn.id AS returnid,store.store_name,COALESCE(sale.visit_type_id, 1) AS visit_type_idFROM pharmacy.t_patient_issue_return issuereturnJOIN pharmacy.t_patient_issue_return_detail issueretrundetails ON issuereturn.id = issueretrundetails.patient_issue_return_idJOIN pharmacy.t_issue_detail_batch_mapper issuebatchmapper ON issueretrundetails.issue_batch_mapper_id = issuebatchmapper.idJOIN pharmacy.t_issue_detail issuedetails ON issuebatchmapper.issue_detail_id = issuedetails.idLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax0 ON tax0.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 0::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax5 ON tax5.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 5::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax12 ON tax12.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 12::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax18 ON tax18.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 18::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax28 ON tax28.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 28::double precisionJOIN pharmacy.t_sale_detail salesdetail ON salesdetail.id = issuedetails.sale_detail_idJOIN pharmacy.t_sale sale ON salesdetail.sale_id = sale.idJOIN pharmacy.m_sale_type saletype ON sale.sale_type_id = saletype.idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sale.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sale.patient_idLEFT JOIN m_store store ON sale.store_id = store.store_idGROUP BY sale.id, issuereturn.return_no, sale.total_amount, sale.tax_amount, sale.total_discount_amount, sale.net_amount, issuereturn.added_date, sale.unit_id, pt.first_name, pt.last_name, ptt.patient_name, sale.sale_type_id, issuedetails.tax_percentage, saletype.type, sale.bill_no, sale.store_id, issuereturn.id, store.store_name;

-- "procedure".getsalesreturnitemwise source
CREATE OR REPLACE VIEW "procedure".getsalesreturnitemwiseAS SELECT DISTINCT mi.id AS item_id,mi.hsn_code,mi.name AS itemname,uomunit.unit AS uomunit,salesdetails.tax_percentage,rtd.return_qty AS quantity,rtd.return_amt * 100::double precision / (100::double precision + salesdetails.tax_percentage) * salesdetails.tax_percentage / 100::double precision AS taxamount,rtd.return_amt * 100::double precision / (100::double precision + salesdetails.tax_percentage) AS taxable,ms.store_id,ms.store_name,rtd.return_amt AS net,rtd.id,rt.added_date,sales.unit_id,rt.id AS returnidFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN m_item mi ON salesdetails.item_id = mi.idLEFT JOIN m_unit_of_measurement uom ON mi.id = uom.item_id AND uom.uom_type_id = 3LEFT JOIN m_uom_unit uomunit ON uom.uom_unit_id = uomunit.idJOIN pharmacy.t_return rt ON sales.id = rt.sale_idJOIN pharmacy.t_return_detail rtd ON salesdetails.id = rtd.sale_detail_idLEFT JOIN pharmacy.t_return_detail tax5 ON salesdetails.id = tax5.sale_detail_id AND salesdetails.tax_percentage = 5::double precisionLEFT JOIN pharmacy.t_return_detail tax12 ON salesdetails.id = tax12.sale_detail_id AND salesdetails.tax_percentage = 12::double precisionLEFT JOIN pharmacy.t_return_detail tax18 ON salesdetails.id = tax18.sale_detail_id AND salesdetails.tax_percentage = 18::double precisionLEFT JOIN pharmacy.t_return_detail tax28 ON salesdetails.id = tax28.sale_detail_id AND salesdetails.tax_percentage = 28::double precisionLEFT JOIN m_store ms ON ms.store_id = sales.store_idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = false AND salesdetails.tax_percentage &lt;&gt; 0::double precisionUNIONSELECT DISTINCT mi.id AS item_id,mi.hsn_code,mi.name AS itemname,uomunit.unit AS uomunit,salesdetail.tax_percentage,issuebatchmapper.return_accepted_quantity AS quantity,issuebatchmapper.amount * 100::double precision / (100::double precision + salesdetail.tax_percentage) * salesdetail.tax_percentage / 100::double precision AS taxamount,issuebatchmapper.amount * 100::double precision / (100::double precision + salesdetail.tax_percentage) AS taxable,ms.store_id,ms.store_name,issuebatchmapper.amount AS net,issuedetails.id,issuereturn.added_date,issuereturn.unit_id,issuereturn.id AS returnidFROM pharmacy.t_patient_issue_return issuereturnJOIN pharmacy.t_patient_issue_return_detail issueretrundetails ON issuereturn.id = issueretrundetails.patient_issue_return_idJOIN pharmacy.t_issue_detail_batch_mapper issuebatchmapper ON issueretrundetails.issue_batch_mapper_id = issuebatchmapper.idJOIN pharmacy.t_issue_detail issuedetails ON issuebatchmapper.issue_detail_id = issuedetails.idLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax5 ON tax5.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 5::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax12 ON tax12.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 12::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax18 ON tax18.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 18::double precisionLEFT JOIN pharmacy.t_issue_detail_batch_mapper tax28 ON tax28.issue_detail_id = issuedetails.id AND issuedetails.tax_percentage = 28::double precisionJOIN pharmacy.t_sale_detail salesdetail ON salesdetail.id = issuedetails.sale_detail_idJOIN m_item mi ON salesdetail.item_id = mi.idLEFT JOIN m_unit_of_measurement uom ON mi.id = uom.item_id AND uom.uom_type_id = 3LEFT JOIN m_uom_unit uomunit ON uom.uom_unit_id = uomunit.idJOIN pharmacy.t_sale sale ON salesdetail.sale_id = sale.idJOIN m_store ms ON ms.store_id = sale.store_idWHERE issuedetails.tax_percentage &lt;&gt; 0::double precision;

-- "procedure".getsalesreturnitemwise_1 source
CREATE OR REPLACE VIEW "procedure".getsalesreturnitemwise_1AS SELECT DISTINCT mi.id AS item_id,mi.hsn_code,mi.name AS itemname,uomunit.unit AS uomunit,salesdetails.tax_percentage,sum(rtd.return_qty) AS quantity,sum(rtd.return_amt) * 100::double precision / (100::double precision + salesdetails.tax_percentage) * salesdetails.tax_percentage / 100::double precision AS taxamount,sum(rtd.return_amt) * 100::double precision / (100::double precision + salesdetails.tax_percentage) AS taxable,sum(rtd.return_amt) AS net,ms.store_name,sales.store_id,rtd.id AS returnid,rt.added_date,sales.unit_id,unitinformation.unit_name,unitinformation.unit_addressFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN pharmacy.t_return rt ON sales.id = rt.sale_idJOIN pharmacy.t_return_detail rtd ON salesdetails.id = rtd.sale_detail_idJOIN m_item mi ON mi.id = salesdetails.item_idJOIN m_unit_of_measurement uom ON mi.id = uom.item_id AND uom.uom_type_id = 3JOIN m_uom_unit uomunit ON uom.uom_unit_id = uomunit.idJOIN m_store ms ON ms.store_id = sales.store_idJOIN pharmacy.m_sale_type saletype ON sales.sale_type_id = saletype.idJOIN m_unit_master unitinformation ON sales.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sales.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sales.patient_idWHERE salesdetails.quantity &lt;&gt; 0 AND sales.is_deleted = false AND salesdetails.tax_percentage &lt;&gt; 0::double precisionGROUP BY mi.id, mi.hsn_code, mi.name, uomunit.unit, salesdetails.tax_percentage, sales.store_id, rtd.id, ms.store_name, rt.added_date, sales.unit_id, unitinformation.unit_name, unitinformation.unit_addressUNION ALLSELECT DISTINCT mi.id AS item_id,mi.hsn_code,mi.name AS itemname,uomunit.unit AS uomunit,salesdetail.tax_percentage,sum(issueretrundetails.accept_qty) AS quantity,sum(issuebatchmapper.amount) * 100::double precision / (100::double precision + salesdetail.tax_percentage) * salesdetail.tax_percentage / 100::double precision AS taxamount,sum(issuebatchmapper.amount) * 100::double precision / (100::double precision + salesdetail.tax_percentage) AS taxable,sum(issuebatchmapper.amount) AS net,ms.store_name,sale.store_id,issueretrundetails.id AS returnid,issuereturn.added_date,sale.unit_id,unitinformation.unit_name,unitinformation.unit_addressFROM pharmacy.t_patient_issue_return issuereturnJOIN pharmacy.t_patient_issue_return_detail issueretrundetails ON issuereturn.id = issueretrundetails.patient_issue_return_idJOIN pharmacy.t_issue_detail_batch_mapper issuebatchmapper ON issueretrundetails.issue_batch_mapper_id = issuebatchmapper.idJOIN pharmacy.t_issue_detail issuedetails ON issuebatchmapper.issue_detail_id = issuedetails.idJOIN pharmacy.t_sale_detail salesdetail ON salesdetail.id = issuedetails.sale_detail_idJOIN m_item mi ON mi.id = salesdetail.item_idJOIN m_unit_of_measurement uom ON mi.id = uom.item_id AND uom.uom_type_id = 3JOIN m_uom_unit uomunit ON uom.uom_unit_id = uomunit.idJOIN pharmacy.t_sale sale ON salesdetail.sale_id = sale.idJOIN m_unit_master unitinformation ON sale.unit_id = unitinformation.unit_idJOIN m_store ms ON ms.store_id = sale.store_idJOIN pharmacy.m_sale_type saletype ON sale.sale_type_id = saletype.idLEFT JOIN pharmacy.t_temp_patient_registration ptt ON ptt.id = sale.temp_patient_idLEFT JOIN patient.t_patient_registration pt ON pt.patient_id = sale.patient_idWHERE issuedetails.tax_percentage &lt;&gt; 0::double precisionGROUP BY mi.id, mi.hsn_code, mi.name, uomunit.unit, salesdetail.tax_percentage, sale.store_id, issueretrundetails.id, ms.store_name, issuereturn.added_date, sale.unit_id, unitinformation.unit_name, unitinformation.unit_address;

-- "procedure".getstock_pur_sale source
CREATE OR REPLACE VIEW "procedure".getstock_pur_saleAS SELECT mi.id AS itemid,mi.name AS itemname,COALESCE(pur.purqty, 0::bigint) AS purqty,COALESCE(obl.obqty, 0::bigint) AS obqty,COALESCE(sal.salqty, 0::bigint) AS salqty,COALESCE(return.grnreturn_qty, 0::bigint) AS grnreturn_qty,COALESCE(stockadqty.qty, 0::bigint) AS stockadjqty,COALESCE(stock.stockqty, 0::bigint) AS stockqty,mi.unit_idFROM m_item miLEFT JOIN ( SELECT grnd.item_id,sum(grnd.grn_received_quantity * uom.conversions) AS purqtyFROM procurement.t_good_receipt_note_detail grndJOIN m_unit_of_measurement uom ON uom.item_id = grnd.item_id AND uom.uom_type_id = grnd.grn_uom_type_id AND uom.is_active = trueGROUP BY grnd.item_id) pur ON pur.item_id = mi.idLEFT JOIN ( SELECT obd.item_id,sum(obd.quantity * uom.conversions) AS obqtyFROM inventory.t_opening_balance_detail obdJOIN m_unit_of_measurement uom ON uom.item_id = obd.item_id AND uom.uom_type_id = obd.uom_type_id AND uom.is_active = trueGROUP BY obd.item_id) obl ON obl.item_id = mi.idLEFT JOIN ( SELECT tsd.item_id,sum(tsd.quantity * uom.conversions) AS salqtyFROM pharmacy.t_sale_detail tsdJOIN m_unit_of_measurement uom ON uom.item_id = tsd.item_id AND uom.uom_type_id = tsd.uom_type_id AND uom.is_active = trueGROUP BY tsd.item_id) sal ON sal.item_id = mi.idLEFT JOIN ( SELECT tb.item_id,sum(rgd.approved_qty * uom.conversions) AS grnreturn_qtyFROM inventory.t_returnable_gatepass_detail rgdJOIN inventory.t_batch tb ON tb.id = rgd.batch_idJOIN m_unit_of_measurement uom ON uom.item_id = tb.item_id AND uom.uom_type_id = rgd.uom_type_id AND uom.is_active = trueGROUP BY tb.item_id) return ON return.item_id = mi.idLEFT JOIN ( SELECT tb.item_id,sum(tb.current_quantity) AS stockqtyFROM inventory.t_batch tbJOIN m_unit_of_measurement uom ON uom.item_id = tb.item_id AND uom.uom_type_id = 2 AND uom.is_active = trueGROUP BY tb.item_id) stock ON stock.item_id = mi.idLEFT JOIN ( SELECT tb.item_id,sum(ss.variance_qty * uom.conversions) AS qty,sum(ss.approved_upload_quantity * uom.conversions) AS appqtyFROM inventory.t_upload_stock_detail ssJOIN inventory.t_batch tb ON tb.id = ss.batch_idJOIN m_unit_of_measurement uom ON uom.item_id = tb.item_id AND uom.uom_type_id = ss.uom_type_id AND uom.is_active = trueGROUP BY tb.item_id) stockadqty ON stockadqty.item_id = mi.idJOIN m_generic gm ON gm.id = mi.generic_idJOIN m_product_category pc ON pc.id = gm.product_category_idWHERE mi.is_active = true AND (COALESCE(pur.purqty, 0::bigint) + COALESCE(obl.obqty, 0::bigint) + COALESCE(sal.salqty, 0::bigint) + COALESCE(return.grnreturn_qty, 0::bigint) + COALESCE(stock.stockqty, 0::bigint)) &lt;&gt; 0ORDER BY mi.name;

-- "procedure".partywise_productwisetransactions source
CREATE OR REPLACE VIEW "procedure".partywise_productwisetransactionsAS SELECT DISTINCT t_sale.id,CASEWHEN t_sale.admission_id IS NULL THEN t_sale.bill_noWHEN t_sale.encounter_id IS NULL THEN concat('IPD-', t_sale.id)::character varyingELSE t_sale.bill_noEND AS bill_no,t_sale.added_date,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,CASEWHEN t_sale_detail.net_amount = 0::double precision THEN t_sale_detail.package_consumption_amtELSE t_sale_detail.net_amountEND AS net_amount_detail,t_batch.cop,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,CASEWHEN t_sale.patient_id IS NULL THEN t_temp_patient_registration.patient_name::textELSE pim.patientnameEND AS patientname,'Sale'::text AS lebel,m_store.store_id,m_store.store_name,t_sale_detail.id AS detailid,3 AS orderid,tss.available_qty,t_sale_detail.batch_id,tss.t_qtyFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN inventory.t_store_stock tss ON t_batch.id = tss.batch_id AND tss.store_id = t_sale.store_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patientinformation pim ON t_sale.patient_id = pim.patient_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_deleted = falseLEFT JOIN m_store ON t_sale.store_id = m_store.store_idWHERE t_sale.is_active = true AND t_sale.is_deleted = false AND t_sale_detail.is_active = true AND t_sale.is_from_billable_consumption = falseUNIONSELECT DISTINCT t_return.id,t_return.return_no AS bill_no,t_return.added_date,t_return_detail.return_qty AS quantity,t_batch.rate,t_return_detail.return_amt AS total_amount_details,t_sale_detail.tax_percentage,t_return_detail.return_tax_amount AS tax_amount_detail,0 AS discount_amount,t_return_detail.return_amt AS net_amount_detail,t_batch.cop,m_item.name,t_batch.batch_no,t_batch.expiry_date,um.unit_name,um.unit_address,m_item.id AS itemid,um.unit_id,um.image,CASEWHEN t_sale.sale_type_id = 2 THEN ((registration.first_name::text || ' '::text) || registration.last_name::text)::character varyingELSE t_temp_patient_registration.patient_nameEND AS patientname,'Sale Return'::text AS lebel,t_sale.store_id,''::text AS store_name,t_return_detail.id AS detailid,4 AS orderid,tss.available_qty,t_sale_detail.batch_id,tss.t_qtyFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idLEFT JOIN m_unit_master um ON t_return.unit_id = um.unit_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN inventory.t_store_stock tss ON t_batch.id = tss.batch_id AND tss.store_id = t_sale.store_idWHERE t_return.is_active = true AND t_return.is_deleted = falseUNIONSELECT DISTINCT grn.id,grn.grn_number AS bill_no,grn.added_date,grndts.grn_received_quantity AS quantity,grndts.mrp AS rate,grndts.total_amount AS total_amount_details,grndts.tax_percentage,grndts.tax_amount AS tax_amount_detail,grndts.total_discount AS discount_amount,grndts.net_amount AS net_amount_detail,grndts.cop,m_item.name,grndts.batch_no,grndts.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,m_vendor.name AS patientname,'Purchase'::text AS lebel,m_store.store_id,m_store.store_name,grndts.id AS detailid,2 AS orderid,tss.available_qty,grndts.batch_id,tss.t_qtyFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail grndts ON grn.id = grndts.grn_idJOIN inventory.t_batch batch ON grndts.batch_id = batch.idJOIN m_vendor ON m_vendor.id = batch.vendor_id AND batch.vendor_id IS NOT NULLJOIN m_item ON grndts.item_id = m_item.idLEFT JOIN m_unit_master unitinformation ON grn.unit_id = unitinformation.unit_idLEFT JOIN m_store ON grn.store_id = m_store.store_idLEFT JOIN inventory.t_store_stock tss ON batch.id = tss.batch_id AND tss.store_id = m_store.store_idWHERE grn.is_deleted = false AND grn.is_active = true AND grndts.is_active = trueUNIONSELECT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no AS bill_no,t_returnable_gatepass.added_date,t_returnable_gatepass_detail.approved_qty AS quantity,0 AS rate,t_returnable_gatepass_detail.net_amount AS total_amount_details,t_returnable_gatepass_detail.tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,t_returnable_gatepass_detail.net_amount AS net_amount_detail,t_batch.cop,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,m_vendor.name AS patientname,'Purchase Return'::text AS lebel,m_store.store_id,m_store.store_name,t_returnable_gatepass_detail.id AS detailid,2 AS orderid,COALESCE(tss.available_qty, 0) AS available_qty,t_batch.id AS batch_id,tss.t_qtyFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_idLEFT JOIN m_unit_master unitinformation ON t_returnable_gatepass.unit_id = unitinformation.unit_idLEFT JOIN inventory.t_store_stock tss ON t_batch.id = tss.batch_id AND tss.store_id = m_store.store_idWHERE t_returnable_gatepass_detail.is_active = true AND t_returnable_gatepass_detail.is_deleted = falseUNIONSELECT DISTINCT bal.id,bal.opb_no AS bill_no,bal.added_date,baldetail.quantity,baldetail.mrp AS rate,0 AS total_amount_details,0 AS tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,baldetail.mrp AS net_amount_detail,baldetail.cop,m_item.name,baldetail.batch_no,baldetail.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,m_store.store_name::text AS patientname,'Opbal'::text AS lebel,m_store.store_id,m_store.store_name,baldetail.id AS detailid,1 AS orderid,tss.available_qty,batch.id AS batch_id,tss.t_qtyFROM inventory.t_opening_balance balJOIN inventory.t_opening_balance_detail baldetail ON bal.id = baldetail.opening_balance_idLEFT JOIN m_store ON bal.store_id = m_store.store_idLEFT JOIN m_status ON bal.status_id = m_status.idLEFT JOIN m_item ON baldetail.item_id = m_item.idLEFT JOIN m_unit_master unitinformation ON bal.unit_id = unitinformation.unit_idLEFT JOIN inventory.t_batch batch ON baldetail.batch_no::text = batch.batch_no::text AND batch.item_id = baldetail.item_idLEFT JOIN inventory.t_store_stock tss ON batch.id = tss.batch_id AND tss.store_id = m_store.store_idWHERE bal.is_active = true AND bal.is_deleted = falseUNIONSELECT us.id,us.upload_no AS bill_no,us.added_date,abs(usd.variance_qty) AS quantity,tb.rate,0 AS total_amount_details,0 AS tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,0 AS net_amount_detail,tb.cop,item.name,tb.batch_no,tb.expiry_date,unit.unit_name,unit.unit_address,item.id AS itemid,unit.unit_id,unit.image,m_store.store_name AS patientname,'Stock Adjustment Out'::text AS lebel,m_store.store_id,m_store.store_name,usd.id AS detailid,2 AS orderid,COALESCE(tss.available_qty, 0) AS available_qty,tb.id AS batch_id,tss.t_qtyFROM inventory.t_upload_stock usLEFT JOIN inventory.t_upload_stock_detail usd ON us.id = usd.upload_stock_idLEFT JOIN m_store ON us.store_id = m_store.store_idLEFT JOIN inventory.t_stop_transaction stoptran ON us.stop_transaction_id = stoptran.idLEFT JOIN unitinformation unit ON unit.unit_id = us.unit_idLEFT JOIN inventory.t_batch tb ON usd.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN inventory.t_store_stock tss ON tb.id = tss.batch_id AND tss.store_id = m_store.store_idWHERE usd.variance_qty &lt; 0UNIONSELECT us.id,us.upload_no AS bill_no,us.added_date,abs(usd.variance_qty) AS quantity,tb.rate,0 AS total_amount_details,0 AS tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,0 AS net_amount_detail,tb.cop,item.name,tb.batch_no,tb.expiry_date,unit.unit_name,unit.unit_address,item.id AS itemid,unit.unit_id,unit.image,m_store.store_name AS patientname,'Stock Adjustment In'::text AS lebel,m_store.store_id,m_store.store_name,usd.id AS detailid,2 AS orderid,COALESCE(tss.available_qty, 0) AS available_qty,tb.id AS batch_id,tss.t_qtyFROM inventory.t_upload_stock usLEFT JOIN inventory.t_upload_stock_detail usd ON us.id = usd.upload_stock_idLEFT JOIN m_store ON us.store_id = m_store.store_idLEFT JOIN inventory.t_stop_transaction stoptran ON us.stop_transaction_id = stoptran.idLEFT JOIN unitinformation unit ON unit.unit_id = us.unit_idLEFT JOIN inventory.t_batch tb ON usd.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic g ON item.generic_id = g.idLEFT JOIN inventory.t_store_stock tss ON tb.id = tss.batch_id AND tss.store_id = m_store.store_idWHERE usd.variance_qty &gt; 0UNIONSELECT DISTINCT issue.id,issue.issue_no AS bill_no,issue.added_date,issue_detail.issue_quantity AS quantity,tb.rate,tb.rate * issue_detail.issue_quantity::double precision AS total_amount_details,tb.tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,tb.rate * issue_detail.issue_quantity::double precision AS net_amount_detail,tb.cop,m_item.name,tb.batch_no,tb.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,concat(fromstore.store_name::text, '-TO-', tostore.store_name::text) AS patientname,'Material Issue'::text AS lebel,fromstore.store_id,fromstore.store_name,issue_detail.id AS detailid,5 AS orderid,COALESCE(tss.available_qty, 0) AS available_qty,tb.id AS batch_id,tsstransit.t_qtyFROM inventory.t_material_issue issueJOIN inventory.t_material_issue_detail issue_detail ON issue.id = issue_detail.material_issue_idLEFT JOIN inventory.t_store_indent indent ON issue.store_indent_id = indent.idLEFT JOIN inventory.t_store_indent_detail indent_detail ON issue_detail.store_indent_detail_id = indent_detail.idLEFT JOIN m_store fromstore ON issue.from_store_id = fromstore.store_idLEFT JOIN m_store tostore ON issue.to_store_id = tostore.store_idLEFT JOIN m_item ON issue_detail.item_id = m_item.idLEFT JOIN inventory.t_material_issue_batch_mapper materialmapper ON issue_detail.id = materialmapper.material_issue_detail_idLEFT JOIN inventory.t_batch tb ON materialmapper.batch_id = tb.idLEFT JOIN m_unit_master unitinformation ON issue.unit_id = unitinformation.unit_idLEFT JOIN inventory.t_store_stock tss ON tb.id = tss.batch_id AND tss.store_id = fromstore.store_idLEFT JOIN inventory.t_store_stock tsstransit ON tb.id = tsstransit.batch_id AND tsstransit.store_id = tostore.store_idWHERE issue_detail.issue_quantity &lt;&gt; 0 AND issue.is_active = true AND issue.is_deleted = false AND issue.store_indent_id IS NOT NULLUNIONSELECT DISTINCT issue.id,issue.issue_no AS bill_no,issue.added_date,issue_detail.issue_quantity AS quantity,tb.rate,tb.rate * issue_detail.issue_quantity::double precision AS total_amount_details,tb.tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,tb.rate * issue_d