CREATE OR REPLACE VIEW "procedure".rptassetreturnacceptanceAS SELECT ar.id,ar.return_no,ar.approved_date,ar.remark,ar.added_date,ard.return_quantity,ard.accepted_quantity,ard.reject_quantity,ard.reject_note,tostore.store_name AS tostorename,fromstore.store_name AS fromstorename,status.status,(emp.first_name::text || ' '::text) || emp.last_name::text AS addedbyusername,m_item.name,t_batch.batch_no,um.unit_name,um.unit_address,um.unit_idFROM assets.t_asset_return arJOIN assets.t_asset_return_detail ard ON ar.id = ard.return_idLEFT JOIN m_store tostore ON ar.from_store_id = tostore.store_idLEFT JOIN m_store fromstore ON ar.to_store_id = fromstore.store_idLEFT JOIN m_status status ON ar.status_id = status.idLEFT JOIN m_user_master usermaster ON ar.added_by = usermaster.user_idLEFT JOIN m_employee_master emp ON usermaster.user_id = emp.user_idLEFT JOIN inventory.t_batch ON t_batch.id = ard.batch_idLEFT JOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_unit_master um ON um.unit_id = ar.unit_idWHERE ar.is_active = true AND ar.is_deleted = false;-- DROP FUNCTION "procedure".get_accident_emergency_analysis(date);
CREATE OR REPLACE FUNCTION procedure.get_accident_emergency_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, is_mlc character, triage_level_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn query selecta.unit_id::integer,a.organization_id::integer,ad.is_medico_legal::char as is_mlc,ad.triage_category_id::integer as triage_level_id,(casewhen t.from_ward_id in (select ward_idfromadt.m_ward_masterwhereis_er = 'Y')and t.to_ward_id in(select ward_idfromadt.m_ward_masterwhereis_er = 'N'and is_icu = 'N') then 1when t.from_ward_id in (select ward_idfromadt.m_ward_masterwhereis_er = 'Y')and t.to_ward_id in(select ward_idfromadt.m_ward_masterwhereis_icu = 'Y') then 2when t.from_ward_id in (select ward_idfromadt.m_ward_masterwhereis_er = 'Y')and tr.transfer_type_id = 2 then 3else 2end)::integer as transfer_from_er_id,generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,count(a.admission_id) as count,(casewhen a.status = 'A' then false::boolelse true::boolend) as is_deletedfromadt.t_admission ainner join adt.t_admission_details adusing(admission_id)inner join adt.t_transfer tusing (admission_id)inner join adt.t_transfer_request trusing (admission_id)where((a.updated_date::date &gt;= p_date::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))group bya.unit_id,a.organization_id,ad.is_medico_legal,ad.triage_category_id,transfer_from_er_id,date,a.status;end;$function$;

-- DROP FUNCTION "procedure".get_accident_er_analysis(date);
CREATE OR REPLACE FUNCTION procedure.get_accident_er_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, is_medico_legal character, triage_category_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginReturn query select s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa as date,s.count,s.is_deletedfrom (select ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,1 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),casewhen ta.status ilike 'A' then falseelse trueend as is_deleted, ta.created_date,ta.updated_datefrom adt.t_admission tajoin adt.t_admission_details tad on ta.admission_id=tad.admission_idwhere ta.visit_type_id=2 and ta.admission_id in (select admission_id from adt.t_admission_note where visit_type_id=4)group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,ta.status,tad.doa,ta.created_date,ta.updated_dateunionselect ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,2 as transfer_from_er_id,tad.doa::date,count(ta.admission_id),casewhen ta.status ilike 'A' then falseelse trueend as is_deleted,ta.created_date,ta.updated_date from adt.t_admission tajoin adt.t_admission_details tad on ta.admission_id=tad.admission_idwhere ta.visit_type_id=2and ta.admission_id in (select admission_id from adt.t_transfer where transfer_status_id=10)group by ta.unit_id,ta.organization_id,tad.is_medico_legal,tad.triage_category_id,tad.doa,ta.status,ta.created_date,ta.updated_date) swhere (s.updated_date::date &gt;= p_date::date and s.updated_date::date &lt; current_date)or (s.created_date::date &gt;= p_date::date and s.created_date::date &lt; current_date)group by s.unit_id,s.organization_id,s.is_medico_legal,s.triage_category_id,s.transfer_from_er_id,s.doa,s.count,s.is_deleted;end;$function$;

-- DROP FUNCTION "procedure".get_admission_analysis(date);
CREATE OR REPLACE FUNCTION procedure.get_admission_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, age_group_id integer, gender_id integer, is_mlc character, is_high_risk character, count bigint, admission_date date, is_vip character, is_planned character, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selecta.unit_id ::integer,a.organization_id ::integer,ad.admission_type_id ::integer,a.visit_type_id ::integer,a.speciality_id ::integer,a.doctor_id ::integer,apm.payment_entitlement_id ::integer,extract(yearfromage(pr.dob))::integer as age_group_id,pr.gender_id ::integer,ad.is_medico_legal,ad.is_high_risk,count(*),ad.doa::date as admission_date,pr.is_vip,(casewhen a.admission_id in (select admission_idfromadt.t_admission_note) then 'Y'::charelse 'N'::charend) as is_planned,(casewhen a.status = 'A' then false::boolelse true::boolend) as is_deletedfromadt.t_admission ajoin adt.t_admission_details ad on(a.admission_id = ad.admission_id)join opd.t_patient_sponsor_details apm on(a.admission_id = apm.admission_id)join patient.t_patient_registration pr on(pr.patient_id = a.patient_id)left join adt.t_admission_note an on(a.admission_id = an.admission_id)wheread.doa::date &gt;= p_date ::dategroup bya.unit_id,a.organization_id,a.admission_id,ad.admission_type_id,ad.doa,a.visit_type_id,a.speciality_id,a.doctor_id,apm.payment_entitlement_id,pr.dob,pr.gender_id,ad.is_medico_legal,ad.is_high_risk,pr.is_vip;end;$function$;

-- DROP FUNCTION "procedure".get_appointment_cancellation(date);
CREATE OR REPLACE FUNCTION procedure.get_appointment_cancellation(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, request_type_code character, date date, count bigint, appointment_status_code character varying, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select am.unit_id,am.organization_id,em.doctor_id,am.appointment_type_id as speciality_id,(case when am.appointment_status_id=2 then am.cancelled_by when am.appointment_status_id=3 then am.rescheduled_by end) as request_type_code,am.appointment_date::date as date,count(*)::bigint as count,asm.appointment_status_code,am.statusfrom opd.m_appointment_master amleft join opd.t_encounter_master em on am.appointment_id=em.appointment_idleft join opd.m_appointment_status_master asmon am.appointment_status_id=asm.appointment_status_idwhere (am.appointment_date::date &gt;= p_date ::date and am.appointment_date::date &lt; current_date) and(am.appointment_status_id=2 or am.appointment_status_id=3 or am.appointment_status_id=7)group by am.appointment_date,em.doctor_id,am.unit_id,am.organization_id,am.appointment_type_id,asm.appointment_status_code,am.appointment_status_id,am.cancelled_by,am.rescheduled_by,am.status;--order by am.appointment_date desc;end;$function$;

-- DROP FUNCTION "procedure".get_appointment_status(date);
CREATE OR REPLACE FUNCTION procedure.get_appointment_status(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, patient_id integer, speciality_id integer, is_cancelled boolean, is_reschedule boolean, is_overbooked boolean, date_time timestamp without time zone, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select am.unit_id,am.organization_id,em.doctor_id,am.patient_id,am.appointment_type_id,(case when am.appointment_status_id=2 then true else false end) ,(case when am.appointment_status_id=3 then true else false end) ,false,am.appointment_date,am.statusfrom opd.m_appointment_master amleft join opd.m_slot_master em on am.slot_id=em.slot_idwhere (am.appointment_date::date &gt;= p_date ::date and am.appointment_date::date &lt; current_date) and(am.appointment_status_id=2 or am.appointment_status_id=3);
end;$function$;

-- DROP FUNCTION "procedure".get_average_length_of_stay_diagnosis_wise(date);
CREATE OR REPLACE FUNCTION procedure.get_average_length_of_stay_diagnosis_wise(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, discharge_date date, total_discharge_days_count integer, total_discharge_count bigint, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY select s.unit_id,s.organization_id,s.patient_id,s.doctor_id,s.speciality_id,s.diagnosis_id,s.discharge_time::date as discharge_date ,(casewhen s.days&gt;0 and s.hours&gt;0 and s.minutes&gt;0 then s.days+1when s.days&gt;0 and s.hours=0 and s.minutes&gt;0 then s.days+1when s.days=0 and s.hours&gt;0 then 1when s.days=0 and s.hours=0 and s.minutes&gt;0 then 1when s.days &gt;0 then s.dayselse 0 end ) as total_discharge_days_count ,count (s.discharge_id) as total_discharge_count, false as is_deletedfrom (select ta.unit_id,ta.organization_id,ta.patient_id,td.doctor_id,ta.speciality_id,tca.diagnosis_id,td.discharge_time,date_part('days',age(td.discharge_time, tad.doa))::integer as days,date_part('hours',age(td.discharge_time, tad.doa))::integer as hours,date_part('minutes',age(td.discharge_time, tad.doa))::integer as minutes,td.discharge_idfrom adt.t_admission tajoin adt.t_admission_details tad on ta.admission_id=tad.admission_idjoin adt.t_discharge td on td.admission_id=ta.admission_idjoin adt.t_complaint_admission tca on ta.admission_id=tca.admission_idwhere ((ta.updated_date::date &gt;= p_date and ta.updated_date::date &lt; current_date)or (ta.created_date::date &gt;= p_dateand ta.created_date::date &lt; current_date))group by ta.admission_id,ta.unit_id,ta.organization_id,ta.patient_id,td.doctor_id,ta.speciality_id,tca.diagnosis_id,td.discharge_time,td.discharge_id,tad.doa) sgroup by s.unit_id,s.organization_id,s.patient_id,s.doctor_id,s.speciality_id,s.diagnosis_id,s.discharge_time::date,s.days,s.hours,s.minutes;end;$function$;

-- DROP FUNCTION "procedure".get_avg_length_of_stay(date);
CREATE OR REPLACE FUNCTION procedure.get_avg_length_of_stay(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selects.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.admission_type_id,sum(case when diff &lt;= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_discharge_days_count,count(distinct s.discharge_id):: bigint as total_discharge_count,generate_series(p_date::date , current_timestamp::date, '1day' )::date date,s.is_deletedfrom(selecta.unit_id ,a.organization_id,a.speciality_id ,d.doctor_id ,ad.admission_type_id,d.discharge_id,extract(epochfromd.discharge_date - ad.doa)::integer / 3600 as diff,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_discharge djoin adt.t_admission a ond.admission_id = a.admission_idand a.visit_type_id in (2)join adt.t_admission_details ad ond.admission_id = ad.admission_idwhere(d.updated_date::date &gt;= p_date and d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date and d.created_date::date &lt; current_date)group bya.unit_id ,a.organization_id,a.speciality_id ,d.discharge_date,d.doctor_id,ad.doa,d.discharge_id,a.status,ad.admission_type_id )sgroup bys.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.discharge_id,s.admission_type_id,s.is_deleted;end;$function$;

-- DROP FUNCTION "procedure".get_bed_availability(date);
CREATE OR REPLACE FUNCTION procedure.get_bed_availability(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_type_id integer, actual_bed_count bigint, total_bed_count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectbm.unit_id,bedtype.organization_id,bedtype.bed_type_id ,(selectcount(bedmast0.bed_id) actual_bed_countfromadt.m_bed_master bedmast0inner join adt.t_bed_log_status bedlog0 onbedmast0.bed_id = bedlog0.bed_idwhere(bedlog0.bed_status_id = 3or bedlog0.bed_status_id = 6)and bedmast0.bed_type_id = bedtype.bed_type_idand bedlog0.status = 'A'and ((bedlog0.updated_date::date &gt;= p_date ::dateand bedlog0.updated_date::date &lt; current_date)or (bedlog0.created_date::date &gt;= p_date::dateand bedlog0.created_date::date &lt; current_date)) ),(selectcount(bedmast3.bed_id) total_bed_countfromadt.m_bed_master bedmast3inner join adt.t_bed_log_status bedlog3 onbedmast3.bed_id = bedlog3.bed_idwherebedmast3.bed_type_id = bedtype.bed_type_idand bedlog3.status = 'A'and ((bedlog3.updated_date::date &gt;= p_date ::dateand bedlog3.updated_date::date &lt; current_date)or (bedlog3.created_date::date &gt;= p_date::dateand bedlog3.created_date::date &lt; current_date)) ),generate_series(bedlog.updated_date::date , current_timestamp::date, '1day')::date as date,casewhen bedlog.status ilike 'A' then falseelse trueend as is_deletedfromadt.m_bed_type_master bedtypeinner join adt.m_bed_master bm onbedtype.bed_type_id = bm.bed_type_idinner join adt.t_bed_log_status bedlog onbm.bed_id = bedlog.bed_idwherebedtype.status = 'A'group bybedtype.unit_id,bedtype.organization_id,bedtype.bed_type_id ,date,bedlog.status,bm.unit_idorder bybedtype.bed_type_id;end;$function$;

-- DROP FUNCTION "procedure".get_bed_reservation(date);
CREATE OR REPLACE FUNCTION procedure.get_bed_reservation(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, patient_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, is_doa_flexible character, count integer, date date)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectad.unit_id,ad.organization_id,adm.bed_category_id,ad.patient_id,ad.doctor_speciality_id,ad.treating_doctor_id,ad.admission_type_id,ad.is_flexiable_date,count(distinct coalesce( ad.patient_id, 0)) :: integer as bed_count,adm.doa::datefromadt.t_admission_note adjoin adt.t_admission_patient_mapping adm onad.admission_note_id=adm.admission_note_idwhere(ad.updated_date::date &gt;= p_date and ad.updated_date::date &lt; current_date)or (ad.created_date::date &gt;= p_date and ad.created_date::date &lt; current_date)and ad.admission_status = 'R'group byad.unit_id,ad.organization_id,ad.patient_id,ad.doctor_speciality_id,ad.treating_doctor_id,ad.admission_type_id,ad.is_flexiable_date,adm.bed_category_id,adm.doa;end;$function$;

-- DROP FUNCTION "procedure".get_birth_registration(date);
CREATE OR REPLACE FUNCTION procedure.get_birth_registration(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, gender character varying, baby_uhid character varying, baby_name character varying, outcome character varying, trimester character varying, date date, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select r.unit_id,r.organization_id,r.patient_id,r.sex,r.uhid_number_baby,r.baby_name,r.outcome,'trimester'::varchar as trimester,r.dob::date,r.statusfrom public.m_new_born_baby_reg rwhere--(r.updated_date::date &gt;= p_date ::date and r.updated_date::date &lt; current_date or r.created_date::date &gt;= p_date::date and r.created_date::date &lt; current_date);
--((TO_TIMESTAMP(r.updated_date, 'MM-DD-YYYY HH24:MI:SS'))::date &gt;= p_date ::date and (TO_TIMESTAMP(r.updated_date, 'MM-DD-YYYY HH24:MI:SS'))::date &lt; current_date or (TO_TIMESTAMP(r.created_date, 'MM-DD-YYYY HH24:MI:SS'))::date &gt;= p_date::date and (TO_TIMESTAMP(r.created_date, 'MM-DD-YYYY HH24:MI:SS'))::date &lt; current_date);
r.dob::date&gt;=p_date and r.dob::date&lt;current_date;end;$function$;

-- DROP FUNCTION "procedure".get_death_statistics(date);
CREATE OR REPLACE FUNCTION procedure.get_death_statistics(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, is_mlc character, diagnosis_id integer, count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectd.unit_id,d.organization_id,a.speciality_id,d.doctor_id,ad.admission_type_id,ad.is_medico_legal as is_mlc ,ca.diagnosis_id ,count(d.discharge_id) :: bigint count,generate_series(d.updated_date::date , current_timestamp::date, '1day' )::date date,casewhen d.status ilike 'A' then falseelse trueend as is_deletedfrom"adt".t_discharge djoin "adt".t_admission a ond.admission_id = a.admission_idjoin "adt".t_admission_details ad ond.admission_id = ad.admission_idjoin adt.t_complaint_admission ca onca.admission_id = a.admission_idwhered.is_death = 'Y'and d.discharge_date::date &gt;= p_date and d.discharge_date::date &lt; current_dategroup byd.unit_id,d.organization_id,ad.admission_type_id,d.doctor_id,a.speciality_id ,ad.is_medico_legal,ca.diagnosis_id,date,is_deleted ;end;$function$;

-- DROP FUNCTION "procedure".get_discharge_analysis(date);
CREATE OR REPLACE FUNCTION procedure.get_discharge_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_mlc character, is_high_risk character, discharge_date date, count bigint, discharge_type_id integer, is_vip character, is_planned character, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id::integer,d.organization_id::integer,ad.admission_type_id::integer,d.visit_type_id::integer,a.speciality_id::integer,d.doctor_id::integer,apm.payment_entitlement_id::integer,extract(yearfromage(pr.dob))::integer as patient_age,pr.gender_id::integer,ad.is_medico_legal::char,ad.is_high_risk::char,d.discharge_date::date,count(*),d.discharge_type_id::integer,pr.is_vip::char,(casewhen a.admission_id in (select admission_idfromadt.t_admission_note) then 'Y'::charelse 'N'::charend) as is_planned,(casewhen d.status = 'A' then false::boolelse true::boolend) as is_deletedfromadt.t_admission ajoin adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)join adt.t_admission_patient_mapping apm on(a.patient_id = apm.admission_patient_id)join patient.t_patient_registration prusing(patient_id)whered.discharge_date::date &gt;= p_date ::dategroup byd.unit_id,d.organization_id,ad.admission_type_id,d.visit_type_id,apm.payment_entitlement_id,a.speciality_id,pr.dob,d.doctor_id,pr.gender_id,ad.is_medico_legal,d.discharge_type_id,ad.is_high_risk,d.discharge_date,pr.is_vip,a.admission_id,d.status;end;$function$;

-- DROP FUNCTION "procedure".get_discharge_analysis_mis(date);
CREATE OR REPLACE FUNCTION procedure.get_discharge_analysis_mis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, bed_id integer, speciality_id integer, doctor_id integer, patient_id integer, marked_discharge boolean, ready_billing boolean, ready_discharge boolean, discharge_date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id,d.organization_id,ad.bed_category_id,ad.bed_id,a.speciality_id,d.doctor_id,a.patient_id,casewhen d.discharge_status_id = 1 then trueelse falseend as marked_discharge,casewhen d.discharge_status_id = 2 then trueelse falseend as ready_billing,casewhen d.discharge_status_id = 3 then trueelse falseend as ready_discharge,cast(d.updated_date as date) as discharge_date,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_admission ajoin adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)where((d.updated_date::date &gt;= p_date ::dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::dateand d.created_date::date &lt; current_date));
end;$function$;

-- DROP FUNCTION "procedure".get_ehc(date);
CREATE OR REPLACE FUNCTION procedure.get_ehc(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, ehc_id integer, date date, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select em.unit_id,em.organization_id,em.patient_id,0 as ehc_id,em.encounter_date::date,em.statusfromopd.t_encounter_master emwhere em.encounter_type_id=3and ((em.encounter_date::date &gt;= p_date:: date and em.encounter_date&lt; current_date ));
