CREATE SCHEMA procedure_old AUTHORIZATION "HIS-STAGING";

-- procedure_old.get_grn source
CREATE OR REPLACE VIEW procedure_old.get_grnAS SELECT DISTINCT t_good_receipt_note.id,t_good_receipt_note.grn_number,t_good_receipt_note.invoice_number,t_good_receipt_note.invoice_date,t_good_receipt_note.inward_number,t_good_receipt_note.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_good_receipt_note_detail.batch_no,t_good_receipt_note_detail.cop,t_good_receipt_note_detail.mrp,t_good_receipt_note_detail.discount,t_good_receipt_note_detail.tax_percentage,t_good_receipt_note_detail.tax_amount,t_good_receipt_note_detail.total_discount,t_good_receipt_note_detail.total_other_amount AS total_other_amount_detail,t_good_receipt_note_detail.net_amount,m_store.store_id,t_good_receipt_note.total_tax_ammount,t_good_receipt_note.total_other_amount,t_good_receipt_note_detail.grn_approved_quantity,t_good_receipt_note_detail.grn_received_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_websiteFROM procurement.t_good_receipt_noteJOIN procurement.t_good_receipt_note_detail ON t_good_receipt_note.id = t_good_receipt_note_detail.grn_idJOIN m_vendor ON m_vendor.id = t_good_receipt_note.vendor_idJOIN m_item ON t_good_receipt_note_detail.item_id = m_item.idJOIN m_store ON t_good_receipt_note.store_id = m_store.store_idJOIN m_store_item_mapper ON t_good_receipt_note_detail.item_id = m_store_item_mapper.item_id AND t_good_receipt_note.is_deleted = falseLEFT JOIN unitinformation ON t_good_receipt_note.unit_id = unitinformation.unit_idORDER BY t_good_receipt_note.id;

-- procedure_old.get_grn_list source
CREATE OR REPLACE VIEW procedure_old.get_grn_listAS SELECT DISTINCT grn.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.inward_number,grn.inward_date,v.name,st.store_name,grn.store_id,ast.type,rt.type AS request_type,s.status,dt.type AS discount_type,grn.discount,grn.total_amount,grn.total_tax_ammount,grn.total_other_amount,grn.round_off,grn.net_amount,grn.remark,grn.added_date,grn.po_id,grn.unit_id,u.unit_name,u.unit_address,grn.vendor_id,grn.added_by,(((pm.prefix_desc || ' '::text) || em.first_name::text) || ' '::text) || em.last_name::text AS user_name,um.user_idFROM procurement.t_good_receipt_note grnLEFT JOIN m_vendor v ON grn.vendor_id = v.idLEFT JOIN unitinformation u ON grn.unit_id = u.unit_idLEFT JOIN m_store st ON grn.store_id = st.store_idLEFT JOIN m_asset_type ast ON grn.asset_type_id = ast.idLEFT JOIN m_request_type rt ON grn.request_id = rt.idLEFT JOIN m_status s ON grn.status_id = s.idLEFT JOIN m_discount_type dt ON grn.discount_type_id = dt.idLEFT JOIN m_user_master um ON grn.added_by = um.user_idLEFT JOIN m_employee_master em ON um.user_id = em.user_idLEFT JOIN m_prefix_master pm ON em.prefix_id = pm.prefix_idORDER BY grn.id;

-- procedure_old.get_grn_return source
CREATE OR REPLACE VIEW procedure_old.get_grn_returnAS SELECT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_batch.batch_no,t_batch.cop,t_batch.rate,t_returnable_gatepass_detail.tax_percentage,t_returnable_gatepass_detail.total_tax_amount,t_returnable_gatepass_detail.total_amt,t_returnable_gatepass_detail.net_amount,m_store.store_id,t_returnable_gatepass_detail.approved_qty,t_returnable_gatepass_detail.reject_qty,t_returnable_gatepass_detail.return_qtyFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_id;

-- procedure_old.get_grn_return_list source
CREATE OR REPLACE VIEW procedure_old.get_grn_return_listAS SELECT DISTINCT t_returnable_gatepass.id,t_returnable_gatepass.ret_gp_no,t_returnable_gatepass.refrence_no,t_returnable_gatepass.added_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_store.store_id,unitinformation.unit_name,unitinformation.unit_address,t_returnable_gatepass.total_amt,t_returnable_gatepass.total_tax_amount,t_returnable_gatepass.net_amount,t_returnable_gatepass.remark,approvalstatus.status AS approvalstatus,m_status.status,requesttype.type AS requesttype,approvalstatus.id AS approvalstatus_id,m_status.id AS status_id,m_vendor.id AS vendor_idFROM m_itemJOIN inventory.t_batch ON m_item.id = t_batch.item_idJOIN inventory.t_returnable_gatepass_detail ON t_batch.id = t_returnable_gatepass_detail.batch_idJOIN inventory.t_returnable_gatepass ON t_returnable_gatepass.id = t_returnable_gatepass_detail.returnable_gatepass_idJOIN m_store ON t_returnable_gatepass.store_id = m_store.store_idJOIN m_vendor ON m_vendor.id = t_returnable_gatepass_detail.vendor_idJOIN unitinformation ON t_returnable_gatepass.unit_id = unitinformation.unit_idJOIN m_status approvalstatus ON t_returnable_gatepass.approval_status_id = approvalstatus.idLEFT JOIN m_status ON t_returnable_gatepass.status_id = m_status.idLEFT JOIN m_request_type requesttype ON t_returnable_gatepass.request_type_id = requesttype.idLEFT JOIN m_asset_type assettype ON t_returnable_gatepass.asset_type_id = t_returnable_gatepass.asset_type_id;

-- procedure_old.get_pharmacycollection source
CREATE OR REPLACE VIEW procedure_old.get_pharmacycollectionAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,CASEWHEN t_sale.sale_type_id = 2 THEN ((registration.first_name::text || ' '::text) || registration.last_name::text)::character varyingELSE t_temp_patient_registration.patient_nameEND AS patient_name,CASEWHEN t_sale.sale_type_id = 2 THEN t_patient_details.address::character varyingELSE t_temp_patient_registration.addressEND AS address,CASEWHEN t_sale.sale_type_id = 2 THEN registration.uhid_numberELSE t_temp_patient_registration.temp_uhidEND AS temp_uhid,CASEWHEN t_sale.sale_type_id = 2 THEN ((m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text)::character varyingELSE t_temp_doctor.doctor_nameEND AS doctor_name,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS usernameFROM pharmacy.t_saleLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_id;

-- procedure_old.get_po source
CREATE OR REPLACE VIEW procedure_old.get_poAS SELECT DISTINCT t_purchase_order.id,t_purchase_order.po_number,t_purchase_order.added_date,t_purchase_order.approved_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_purchase_order_detail.po_quantity,t_purchase_order_detail.bonus_quantity,t_purchase_order_detail.cop,t_purchase_order_detail.mrp,t_purchase_order_detail.total_discount,t_purchase_order_detail.tax_percentage,t_purchase_order_detail.tax_amount,t_purchase_order_detail.total_other_amount AS total_other_amount_detail,t_purchase_order_detail.net_amount,m_store.store_id,t_purchase_order.total_tax_amount,t_purchase_order.total_other_amount,t_purchase_order_detail.po_approved_quantity,t_purchase_order_detail.bonus_approved_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,t_purchase_order.total_amountFROM procurement.t_purchase_orderJOIN procurement.t_purchase_order_detail ON t_purchase_order.id = t_purchase_order_detail.purchase_order_idJOIN m_vendor ON m_vendor.id = t_purchase_order.vendor_idJOIN m_item ON t_purchase_order_detail.item_id = m_item.idJOIN m_store ON t_purchase_order.store_id = m_store.store_idJOIN m_store_item_mapper ON t_purchase_order_detail.item_id = m_store_item_mapper.item_idLEFT JOIN unitinformation ON t_purchase_order.unit_id = unitinformation.unit_id;

-- procedure_old.get_quotation source
CREATE OR REPLACE VIEW procedure_old.get_quotationAS SELECT DISTINCT t_quotation_vendor.id,t_quotation_vendor.vq_number,t_quotation_request.qr_no,t_quotation_vendor.added_date,t_quotation_vendor.due_date,t_quotation_vendor.approved_date,t_quotation_request.added_date AS request_date,t_quotation_request.approved_date AS request_approved_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,t_quotation_request_detail.quantity,t_quotation_request_detail.warranty_period,t_quotation_request_detail.expected_technical_specification,(m_employee_master.first_name::text || ''::text) || m_employee_master.last_name::text AS username,(m_employee_master_1.first_name::text || ''::text) || m_employee_master_1.last_name::text AS quotation_username,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_quotation_fill.id AS qfidFROM procurement.t_quotation_vendorJOIN procurement.t_quotation_vendor_detail ON t_quotation_vendor.id = t_quotation_vendor_detail.vq_idJOIN m_vendor ON m_vendor.id = t_quotation_vendor.vendor_idJOIN procurement.t_quotation_request ON t_quotation_request.id = t_quotation_vendor.qr_idJOIN procurement.t_quotation_request_detail ON t_quotation_request_detail.qr_id = t_quotation_request.idJOIN m_item ON t_quotation_request_detail.item_id = m_item.idJOIN m_store ON t_quotation_vendor.store_id = m_store.store_idLEFT JOIN m_user_master ON m_user_master.user_id = t_quotation_request.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_user_master m_user_master_1 ON m_user_master_1.user_id = t_quotation_vendor.added_byLEFT JOIN m_employee_master m_employee_master_1 ON m_employee_master_1.user_id = m_user_master_1.user_idLEFT JOIN unitinformation ON t_quotation_vendor.unit_id = unitinformation.unit_idLEFT JOIN procurement.t_quotation_fill ON t_quotation_vendor.id = t_quotation_fill.vq_id;

-- procedure_old.get_salesbills source
CREATE OR REPLACE VIEW procedure_old.get_salesbillsAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,abs(date_part('Year'::text, age(registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS age,m_gender_master.gender_nameFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_gender_master ON registration.gender_id = m_gender_master.gender_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.patient_id IS NOT NULLUNIONSELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_sale.sale_type_id,t_temp_patient_registration.patient_name::text AS patient_name,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_temp_patient_registration.age,m_gender_master.gender_nameFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = t_temp_patient_registration.idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_gender_master ON t_temp_patient_registration.gender_id = m_gender_master.gender_idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = trueWHERE t_sale.temp_patient_id IS NOT NULL;

-- procedure_old.get_salesbills_return source
CREATE OR REPLACE VIEW procedure_old.get_salesbills_returnAS SELECT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_return_detail.return_tax_amount,CASEWHEN t_sale.sale_type_id = 2 THEN ((registration.first_name::text || ' '::text) || registration.last_name::text)::character varyingELSE t_temp_patient_registration.patient_nameEND AS patient_name,CASEWHEN t_sale.sale_type_id = 2 THEN ((m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text)::character varyingELSE t_temp_doctor.doctor_nameEND AS doctor_name,registration.uhid_number,CASEWHEN t_sale.sale_type_id = 2 THEN t_patient_details.address::character varyingELSE t_temp_patient_registration.addressEND AS address,m_item.name,t_batch.batch_noFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.id;

-- procedure_old.get_salesbills_return_new source
CREATE OR REPLACE VIEW procedure_old.get_salesbills_return_newAS SELECT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_return_detail.return_tax_amount,t_temp_patient_registration.patient_name,t_temp_doctor.doctor_name,t_temp_patient_registration.temp_uhid AS uhid_number,t_temp_patient_registration.address,m_item.name,t_batch.batch_no,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_sale.sale_type_idFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN unitinformation ON t_return.unit_id = unitinformation.unit_idUNION ALLSELECT t_return.id,t_return.return_no,t_return.added_date,t_return.total_return_amt,t_return_detail.return_qty,t_return_detail.return_amt,t_return_detail.return_tax_amount,((registration.first_name::text || ' '::text) || registration.last_name::text)::character varying AS patient_name,((m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text)::character varying AS doctor_name,registration.uhid_number,t_patient_details.address::character varying AS address,m_item.name,t_batch.batch_no,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,t_sale.sale_type_idFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idJOIN pharmacy.t_sale_detail ON t_sale_detail.id = t_return_detail.sale_detail_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN unitinformation ON t_return.unit_id = unitinformation.unit_id;

-- procedure_old.get_salesgrossmargin source
CREATE OR REPLACE VIEW procedure_old.get_salesgrossmarginAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,t_batch.cop,t_sale.sale_type_id,m_item.name,t_batch.batch_no,t_batch.expiry_date,unitinformation.unit_name,unitinformation.unit_addressFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idJOIN unitinformation ON t_sale.unit_id = unitinformation.unit_id AND t_sale.is_active = true;

-- procedure_old.get_stockvalue source
CREATE OR REPLACE VIEW procedure_old.get_stockvalueAS SELECT m_item.id,m_item.code,m_item.hsn_code,m_item.name,m_store.store_name,t_batch.quantity,t_batch.batch_no,t_batch.expiry_date,t_batch.current_quantity,t_batch.cop,t_batch.rate,t_batch.selling_price,t_batch.vendor_id,t_batch.id AS batchid,m_store.store_id,m_vendor.name AS vendornameFROM inventory.t_store_stockJOIN inventory.t_batch ON t_store_stock.batch_id = t_batch.idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_store ON t_store_stock.store_id = m_store.store_idLEFT JOIN m_vendor ON m_vendor.id = t_batch.vendor_id;-- DROP FUNCTION procedure_old.adt_get_accident_emergency_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_accident_emergency_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, is_mlc character, triage_level_id integer, transfer_from_er_id integer, date date, count bigint, is_deleted boolean)LANGUAGE plpgsqlAS $function$ beginreturn query select a.unit_id::integer,a.organization_id::integer,ad.is_medico_legal::char as is_mlc,ad.triage_category_id::integer as triage_level_id,(case when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and t.to_ward_id in(select ward_id from adt.m_ward_master where is_er = 'N' and is_icu = 'N') then 1when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and t.to_ward_id in(select ward_id from adt.m_ward_master where is_icu = 'Y') then 2when t.from_ward_id in (select ward_id from adt.m_ward_master where is_er = 'Y') and tr.transfer_type_id = 2 then 3else 2end)::integer as transfer_from_er_id,generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,count(a.admission_id) as count,(case when a.status = 'A' then false::bool else true::bool end) as is_deletedfrom adt.t_admission a inner join adt.t_admission_details ad using(admission_id)inner join adt.t_transfer t using (admission_id)inner join adt.t_transfer_request tr using (admission_id)where ((a.updated_date::date &gt;= p_date::date and a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::date and a.created_date::date &lt; current_date))group by a.unit_id,a.organization_id,ad.is_medico_legal,ad.triage_category_id,transfer_from_er_id,date,a.status; end;$function$;

-- DROP FUNCTION procedure_old.adt_get_admission_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_admission_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, age_group_id integer, gender_id integer, is_mlc character, is_high_risk character, count bigint, admission_date date, is_vip character, is_planned character, is_deleted boolean)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select a.unit_id ::integer,a.organization_id ::integer,ad.admission_type_id ::integer,a.visit_type_id ::integer,a.speciality_id ::integer,a.doctor_id ::integer,apm.payment_entitlement_id ::integer,extract(year from age(pr.dob))::integer as age_group_id,pr.gender_id ::integer,ad.is_medico_legal,ad.is_high_risk,count(distinct a.admission_id),ad.doa::date as admission_date,pr.is_vip,(case when a.admission_id in (select admission_id from adt.t_admission_note) then 'Y'::charelse 'N'::char end) as is_planned,(case when a.status = 'A' then false::bool else true::bool end) as is_deleted from adt.t_admission ajoin adt.t_admission_details ad ON (a.admission_id = ad.admission_id)join opd.t_patient_sponsor_details apm on (a.admission_id = apm.admission_id)join patient.t_patient_registration pr ON (pr.patient_id = a.patient_id)left join adt.t_admission_note an ON (a.admission_id = an.admission_id)where ((a.updated_date::date &gt;= p_date ::date and a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::date and a.created_date::date &lt; current_date))group by a.unit_id,a.organization_id,a.admission_id,ad.admission_type_id,ad.doa,a.visit_type_id,a.speciality_id,a.doctor_id,apm.payment_entitlement_id,pr.dob,pr.gender_id,ad.is_medico_legal,ad.is_high_risk,pr.is_vip;end;$function$;

-- DROP FUNCTION procedure_old.adt_get_bed_availability(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_bed_availability(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_type_id integer, actual_bed_count bigint, total_bed_count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ beginreturn QUERYselectbm.unit_id,bm.organization_id,bedtype.bed_type_id ,(select count(bedmast0.bed_id) actual_bed_countfromadt.m_bed_master bedmast0inner join adt.t_bed_log_status bedlog0 onbedmast0.bed_id = bedlog0.bed_idwhere(bedlog0.bed_status_id = 3 or bedlog0.bed_status_id = 6)and bedmast0.bed_type_id = bedtype.bed_type_idand bedlog0.status = 'A'and ((bedlog0.updated_date::date &gt;= p_date ::dateand bedlog0.updated_date::date &lt; current_date)or (bedlog0.created_date::date &gt;= p_date::dateand bedlog0.created_date::date &lt; current_date))),(select count(bedmast3.bed_id) total_bed_countfromadt.m_bed_master bedmast3inner join adt.t_bed_log_status bedlog3 onbedmast3.bed_id = bedlog3.bed_idwherebedmast3.bed_type_id = bedtype.bed_type_idand bedlog3.status = 'A'and ((bedlog3.updated_date::date &gt;= p_date ::dateand bedlog3.updated_date::date &lt; current_date)or (bedlog3.created_date::date &gt;= p_date::dateand bedlog3.created_date::date &lt; current_date))),generate_series(bedlog.updated_date::date , CURRENT_TIMESTAMP::date, '1day')::date as date,CASE WHEN bedlog.status ilike 'A' then falseELSE TRUEEND AS is_deletedfrom adt.m_bed_type_master bedtypeinner join adt.m_bed_master bm on bedtype.bed_type_id=bm.bed_type_idinner join adt.t_bed_log_status bedlog on bm.bed_id=bedlog.bed_idwherebedtype.status = 'A'group by bm.unit_id,bm.organization_id,bedtype.bed_type_id ,date, bedlog.statusorder bybedtype.bed_type_id;end;$function$;

-- DROP FUNCTION procedure_old.adt_get_bed_occupancy_rate(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_bed_occupancy_rate(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, total_no_inpatient_count bigint, total_bed_count bigint, date date, is_deleted boolean, bed_type_id integer)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selects.unit_id,s.organization_id,s.admission_type_id,sum(case when diff &lt;= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_no_inpatient_count,b.total_bed_count,generate_series(p_date::date , current_timestamp::date, '1day')::date as date,casewhen b.status ilike 'A' then falseelse trueend as is_deleted,b.bed_type_idfrom(selecta.unit_id ,a.organization_id,ad.admission_type_id,a.admission_id,extract(epochfromtd.discharge_date - ad.doa)::integer / 3600 as difffromadt.t_discharge tdjoin adt.t_admission a ona.admission_id = td.admission_idand a.visit_type_id in (2)join adt.t_admission_details ad onad.admission_id = a.admission_idwhere((td.updated_date::date &gt;= p_dateand td.updated_date::date &lt; current_date)or (td.created_date::date &gt;= p_dateand td.created_date::date &lt; current_date))and a.status = 'A'group bya.unit_id ,a.organization_id,ad.doa,a.admission_id,ad.admission_type_id,td.discharge_date )sjoin (selecta.admission_id,a.status,bm.bed_type_id,count(distinct bm.bed_id) total_bed_countfromadt.t_admission ajoin adt.t_admission_details ad ona.admission_id = ad.admission_idjoin adt.m_bed_master bm onad.bed_id = bm.bed_idwhere((a.updated_date::date &gt;= p_dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_dateand a.created_date::date &lt; current_date))and a.status = 'A'group bya.admission_id,a.status,bm.bed_type_id )b ons.admission_id = b.admission_idgroup bys.unit_id ,s.organization_id,s.admission_type_id,b.total_bed_count,date,b.status,b.bed_type_idlimit 100;end;$function$;

