-- DROP FUNCTION procedure_old.adt_get_discharge_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_discharge_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, patient_age integer, gender_id integer, is_mlc character, is_high_risk character, discharge_date date, count bigint, discharge_type_id integer, is_vip character, is_planned character, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id::integer,d.organization_id::integer,ad.admission_type_id::integer,d.visit_type_id::integer,a.speciality_id::integer,d.doctor_id::integer,apm.payment_entitlement_id::integer,extract(yearfromage(pr.dob))::integer as patient_age,pr.gender_id::integer,ad.is_medico_legal::char,ad.is_high_risk::char,d.discharge_date::date,count(distinct d.discharge_id),d.discharge_type_id::integer,pr.is_vip::char,(casewhen a.admission_id in (select admission_idfromadt.t_admission_note) then 'Y'::charelse 'N'::charend) as is_planned,(casewhen d.status = 'A' then false::boolelse true::boolend) as is_deletedfromadt.t_admission ajoin adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)join adt.t_admission_patient_mapping apm on(a.patient_id = apm.admission_patient_id)join patient.t_patient_registration prusing(patient_id)where((d.updated_date::date &gt;= p_date ::dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::dateand d.created_date::date &lt; current_date))group byd.unit_id,d.organization_id,ad.admission_type_id,d.visit_type_id,apm.payment_entitlement_id,a.speciality_id,pr.dob,d.doctor_id,pr.gender_id,ad.is_medico_legal,d.discharge_type_id,ad.is_high_risk,d.discharge_date,pr.is_vip,a.admission_id,d.status;end;$function$;

