CREATE OR REPLACE FUNCTION procedure_old.adt_get_op_conversion_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, count bigint, date date, conversion_from_op_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn query selecta.unit_id,a.organization_id,a.speciality_id,a.doctor_id,count(a.admission_id) as count,generate_series(p_date::date , current_date::date, '1 day'::interval)::date as date,(casewhen t.from_ward_id in (select ward_idfromadt.t_admission_detailswherevisit_type_id = 1)and t.to_ward_id in(select ward_idfromadt.t_admission_detailswherevisit_type_id = 2) then 1when t.from_ward_id in (select ward_idfromadt.t_admission_detailswherevisit_type_id = 1)and t.to_ward_id in(select ward_idfromadt.m_ward_masterwhereis_icu = 'Y') then 2when t.from_ward_id in (select ward_idfromadt.t_admission_detailswherevisit_type_id = 1)and t.to_ward_id in(select ward_idfromadt.t_admission_detailswherevisit_type_id = 3) then 3end) as conversion_from_op_id,casewhen a.status = 'A' then falseelse trueend as is_deletedfromadt.t_admission ainner join adt.t_transfer tusing (admission_id)where((a.updated_date::date &gt;= p_date::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))group bya.unit_id,a.organization_id,a.speciality_id,a.doctor_id,conversion_from_op_id,date,a.status;end;$function$;

-- DROP FUNCTION procedure_old.adt_get_records_patient_transfer(date);
CREATE OR REPLACE FUNCTION procedure_old.adt_get_records_patient_transfer(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, transfer_to_id integer, bed_category_id integer, count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selecta.unit_id,a.organization_id,a.doctor_id,a.speciality_id,casewhen f_ward.is_icu = 'N'and t_ward.is_icu = 'N' then 1when f_ward.is_icu = 'N'and t_ward.is_icu = 'Y' then 2when f_ward.is_icu = 'Y'and t_ward.is_icu = 'N' then 3end as transfer_to_id,casewhen frombed.hierarchy_id &gt; tobed.hierarchy_id then 1when frombed.hierarchy_id &lt; tobed.hierarchy_id then 2when frombed.hierarchy_id = tobed.hierarchy_id then 3end as bed_category_id,count(distinct a.patient_id):: bigint as count,generate_series(p_date::date , current_timestamp::date, '1day')::date as date,casewhen t.status ilike 'A' then falseelse trueend as is_deletedfrom"adt".t_transfer tjoin "adt".t_admission a ont.admission_id = a.admission_idjoin "adt".m_ward_master f_ward ont.from_ward_id = f_ward.ward_idjoin "adt".m_ward_master t_ward ont.to_ward_id = t_ward.ward_idjoin (select bcm.hierarchy_id,t.from_bed_category_id,t.admission_idfromadt.t_transfer tjoin adt.m_bed_category_master bcm ont.from_bed_category_id = bcm.bed_category_id) frombed ona.admission_id = frombed.admission_idjoin (select bcm.hierarchy_id,t.to_bed_category_id,t.admission_idfromadt.t_transfer tjoin adt.m_bed_category_master bcm ont.to_bed_category_id = bcm.bed_category_id) tobed ontobed.admission_id = a.admission_idwhere((t.updated_date::date &gt;= p_dateand t.updated_date::date &lt; current_date)or (t.created_date::date &gt;= p_dateand t.created_date::date &lt; current_date))group bya.unit_id,a.organization_id,a.doctor_id,a.speciality_id,f_ward.is_icu,t_ward.is_icu,t.status,bed_category_idlimit 100;end;$function$;

