CREATE OR REPLACE FUNCTION procedure_old.adt_get_registration_visit_typewise(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, admission_date date, visit_type_id integer)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select a.unit_id ::integer,a.organization_id ::integer,ad.admission_id ::integer,a.patient_id ::integer,a.doctor_id ::integer,a.speciality_id ::integer,ca.diagnosis_id :: integer,ad.doa::date as admission_date,a.visit_type_id :: integerfrom adt.t_admission ajoin adt.t_admission_details ad ON (a.admission_id = ad.admission_id)join adt.t_complaint_admission ca ON (a.admission_id = ad.admission_id)where ((a.updated_date::date &gt;= p_date ::date and a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::date and a.created_date::date &lt; current_date))group by a.unit_id,a.organization_id,ad.admission_id,a.patient_id,a.doctor_id,a.speciality_id,ca.diagnosis_id,ad.doa,a.visit_type_id;end;$function$;

-- DROP FUNCTION procedure_old.emergency_analysis(date, date);
CREATE OR REPLACE FUNCTION procedure_old.emergency_analysis(f_date date, t_date date)RETURNS TABLE(admission_type_code character varying, admission_id integer, patient_id integer, triage_category_id integer, fromward character varying, toward character varying, hr integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERYselectatm.admission_type_code,ad.admission_id,COALESCE(a.patient_id,'0') as patient_id,COALESCE(ad.triage_category_id,'0') as triage_category_id,fw.ward_name as fromWard,tw.ward_name as toward,date_part('hour',ad.created_date) as hrfrom adt.m_admission_type_master atmjoinadt.t_admission_details ad on atm.admission_type_id=ad.admission_type_idjoinadt.t_admission a on ad.admission_id=a.admission_idleft join adt.t_transfer t on a.admission_id=t.admission_idleft joinadt.m_ward_master fw on t.from_ward_id =fw.ward_idleft joinadt.m_ward_master tw on t.to_ward_id = tw.ward_idwhere atm.admission_type_code='EIA'and date(ad.created_date) between f_date and t_date;END;$function$;

