CREATE OR REPLACE FUNCTION procedure_old.get_active_deposit_report(p_date date)RETURNS TABLE(unit_id integer, org_id integer, date_of_payment date, patient_id integer, payement_mode_id integer, amount double precision, status "char")LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select dm.unit_id,dm.org_id,dm.deposit_date::date as date_of_payment,dm.patient_id,pdd.payment_mode_id,sum(dm.deposit_amount) amount ,dm.status FROM billing.m_deposit_master dmJOIN billing.t_payment_deposit_details pdd on pdd.deposit_id = dm.deposit_master_id WHERE dm.deposit_date::date IN (SELECT dm.deposit_date::date FROM billing.m_deposit_master dmWHERE(dm.updated_date::DATE&gt;=p_date OR dm.created_date::DATE&gt;=p_date)AND dm.status = 'A') AND dm.status = 'A'GROUP by dm.deposit_date::date,dm.patient_id,pdd.payment_mode_id,dm.status,dm.unit_id,dm.org_id;END;$function$;

-- DROP FUNCTION procedure_old.get_admission_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.get_admission_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, payment_entitlement_id integer, age_group_id integer, gender_id integer, is_mlc character, is_high_risk character, count bigint, admission_date date, is_vip character, is_planned character, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selecta.unit_id ::integer,a.organization_id ::integer,ad.admission_type_id ::integer,a.visit_type_id ::integer,a.speciality_id ::integer,a.doctor_id ::integer,apm.payment_entitlement_id ::integer,extract(yearfromage(pr.dob))::integer as age_group_id,pr.gender_id ::integer,ad.is_medico_legal,ad.is_high_risk,count(distinct a.admission_id),ad.doa::date as admission_date,pr.is_vip,(casewhen a.admission_id in (select admission_idfromadt.t_admission_note) then 'Y'::charelse 'N'::charend) as is_planned,(casewhen a.status = 'A' then false::boolelse true::boolend) as is_deletedfromadt.t_admission ajoin adt.t_admission_details ad on(a.admission_id = ad.admission_id)join opd.t_patient_sponsor_details apm on(a.admission_id = apm.admission_id)join patient.t_patient_registration pr on(pr.patient_id = a.patient_id)left join adt.t_admission_note an on(a.admission_id = an.admission_id)where((a.updated_date::date &gt;= p_date ::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))group bya.unit_id,a.organization_id,a.admission_id,ad.admission_type_id,ad.doa,a.visit_type_id,a.speciality_id,a.doctor_id,apm.payment_entitlement_id,pr.dob,pr.gender_id,ad.is_medico_legal,ad.is_high_risk,pr.is_vip;end;$function$;

-- DROP FUNCTION procedure_old.get_admission_analysis_bed_type(date);
CREATE OR REPLACE FUNCTION procedure_old.get_admission_analysis_bed_type(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, date_of_admission date, no_of_admission integer, admission_type_id integer, bed_category_id integer, patient_category_id integer, payment_entitlement_id integer, speciality_id integer, doctor_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT pr.unit_id,pr.organization_id as hospital_id ,ad.doa :: DATE date_of_admission,COUNT (DISTINCT ad.admission_id) :: integer as no_of_admission,ad.admission_type_id,ad.bed_category_id,pr.patient_category_id,apm.payment_entitlement_id,a.speciality_id,a.doctor_id,a.statusFROM "adt".t_admission a JOIN "adt".t_admission_details ad ON a.admission_id = ad.admission_id JOIN "patient".t_patient_registration pr ON pr.patient_id = a.patient_idLEFT JOIN "adt".t_admission_note an ON an.admission_id = a.admission_idLEFT JOIN "adt".t_admission_patient_mapping apm ON an.admission_note_id = apm.admission_note_idWHERE ad.doa IN (SELECT ad.doa FROM "adt".t_admission_details adWHERE(a.updated_date::DATE&gt;=p_date OR a.created_date::DATE&gt;=p_date)AND a.status = 'A')AND a.status = 'A'GROUP BY a.status,ad.doa :: DATE ,pr.unit_id,pr.organization_id,ad.admission_type_id,pr.patient_category_id,a.speciality_id,ad.bed_category_id,a.doctor_id,apm.payment_entitlement_id; END;$function$;

-- DROP FUNCTION procedure_old.get_admission_type(date);
CREATE OR REPLACE FUNCTION procedure_old.get_admission_type(p_date date)RETURNS TABLE(admission_type_id integer, admission_type_desc character varying, admission_type_code character varying, status character, hospital_id integer)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectatm.admission_type_id ,atm.admission_type_desc,atm.admission_type_code ,atm.status,atm.organization_id as hospital_idfromadt.m_admission_type_master atmwhere(atm.updated_date::date &gt;= p_dateor atm.created_date::date &gt;= p_date)and atm.status = 'A';end ;$function$;

-- DROP FUNCTION procedure_old.get_age_wise_mortality_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_age_wise_mortality_report(p_date date)RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, age_group_id integer, gender_id integer, no_of_patient_expired integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT d.discharge_date :: DATE ,a.unit_id,a.organization_id as hospital_id ,EXTRACT(year from age(pr.dob)):: integer as age_group_id,pr.gender_id,count(a.patient_id) :: INTEGER as no_of_patient_expired,d.statusfrom adt.t_discharge d inner join adt.t_admission a on a.admission_id = d.admission_id inner join adt.t_admission_details ad on ad.admission_id = a.admission_idinner join patient.t_patient_registration pr on pr.patient_id = a.patient_idWHERE d.is_death = 'Y' AND d.discharge_date IN (SELECT d.discharge_dateFROM adt.t_discharge d WHERE(d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date)AND d.status = 'A') AND d.status = 'A'group by a.unit_id,a.organization_id,pr.gender_id,age_group_id,d.status,d.discharge_date;END;$function$;

-- DROP FUNCTION procedure_old.get_appointment_cancellation_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.get_appointment_cancellation_analysis(p_date date)RETURNS TABLE(encounter_date date, doctor_id integer, dept_id integer, unit_id integer, organziation_id integer, count integer, request_type_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT em.encounter_date :: date , em.doctor_id, em.dept_id,em.unit_id,em.organization_id as hospital_id,count(DISTINCT am.appointment_id) :: integer as no_of_appoinment_cancelled,CASE WHEN am.cancelled_by = 'P' OR am.rescheduled_by = 'P' THEN 1 --providerWHEN am.cancelled_by = 'C' OR am.rescheduled_by = 'C' THEN 2 --consumerEND as request_type_id ,em.status FROM opd.t_encounter_master emJOIN opd.m_appointment_master am on em.patient_id = am.patient_idWHERE -- em.encounter_date IN (SELECT em.encounter_date FROM opd.t_encounter_master em WHERE(em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date AND am.appointment_status_id = 2 OR am.appointment_status_id = 3 ) AND em.status = 'A') AND em.status = 'A'(em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date) AND (am.appointment_status_id = 2 OR am.appointment_status_id = 3) AND em.status = 'A'GROUP by em.doctor_id, em.dept_id,em.unit_id,em.organization_id,request_type_id,em.status ,em.encounter_date :: date ;END;$function$;

-- DROP FUNCTION procedure_old.get_appointment_status(date);
CREATE OR REPLACE FUNCTION procedure_old.get_appointment_status(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, doctor_id integer, patient_id integer, speciality_id integer, is_cancelled boolean, is_reschedule boolean, is_overbooked boolean, date_time timestamp without time zone, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select am.unit_id,am.organization_id,em.doctor_id,am.patient_id,am.appointment_type_id,(case when am.appointment_status_id=2 then true else false end) ,(case when am.appointment_status_id=3 then true else false end) ,false,am.appointment_date,am.statusfrom opd.m_appointment_master amleft join opd.m_slot_master em on am.slot_id=em.slot_idwhere (am.appointment_date::date &gt;= p_date ::date and am.appointment_date::date &lt; current_date) and(am.appointment_status_id=2 or am.appointment_status_id=3);
end;$function$;

-- DROP FUNCTION procedure_old.get_average_consultation_time(date);
CREATE OR REPLACE FUNCTION procedure_old.get_average_consultation_time(p_date date)RETURNS TABLE(encounter_date date, consultation_start_time bigint, consultation_stop_time bigint, doctor_id integer, speciality_id integer, consultation_type_id integer, unit_id integer, hospital_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select em.encounter_date :: DATE,coalesce(MAX(Extract(epoch from ed.consultation_start_time):: bigint),0) as consultation_start_time, coalesce(MAX(Extract(epoch from ed.consultation_stop_time):: bigint),0) as consultation_stop_time,em.doctor_id,em.dept_id as speciality_id,em.user_defined_visit_type_id as consultation_type_id,em.unit_id,em.organization_id AS hospital_id,em.statusFROM opd.t_encounter_master em JOIN opd.t_encounter_details ed on em.encounter_id = ed.encounter_idWHERE -- em.encounter_date IN (Select em.encounter_date FROM opd.t_encounter_master em WHERE (em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date) AND em.status = 'A') AND em.status = 'A' (em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date) AND em.status = 'A'GROUP BY em.encounter_date :: DATE,em.doctor_id,em.dept_id,consultation_type_id,em.status,em.unit_id ,em.status,em.organization_idORDER BY em.encounter_date :: DATE;END;$function$;

-- DROP FUNCTION procedure_old.get_average_length_of_stay_procedure_wise(date);
CREATE OR REPLACE FUNCTION procedure_old.get_average_length_of_stay_procedure_wise(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selects.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.diagnosis_id,sum(case when diff &lt;= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_discharge_days_count,count(distinct s.discharge_id):: bigint as total_discharge_count,generate_series(p_date::date , current_timestamp::date, '1day' )::date date,s.is_deletedfrom(selecta.unit_id ,a.organization_id,a.speciality_id ,d.doctor_id ,ca.diagnosis_id,d.discharge_id,extract(epochfromd.discharge_date - ad.doa)::integer / 3600 as diff,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_discharge djoin adt.t_admission a ond.admission_id = a.admission_idand a.visit_type_id in (2)join adt.t_admission_details ad ond.admission_id = ad.admission_idjoin adt.t_complaint_admission ca on ca.admission_id=a.admission_idwhere((d.updated_date::date &gt;= p_dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_dateand d.created_date::date &lt; current_date))group bya.unit_id ,a.organization_id,a.speciality_id ,d.discharge_date,d.doctor_id,ca.diagnosis_id,ad.doa,d.discharge_id,a.status,ad.admission_type_id )sgroup bys.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.diagnosis_id,s.discharge_id,s.is_deleted;end;$function$;

-- DROP FUNCTION procedure_old.get_avg_lenght_diagnosis_wise(date);
CREATE OR REPLACE FUNCTION procedure_old.get_avg_lenght_diagnosis_wise(p_date date)RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, avg_lenght_stay double precision, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT d.discharge_date :: DATE ,d.unit_id ,d.organization_id hospital_id,a.speciality_id ,d.doctor_id,ca.diagnosis_id ,AVG(extract(epoch from d.discharge_date - ad.doa)/3600) as avg_lenght_stay,d.statusFROM adt.t_discharge dJOIN adt.t_admission a on d.admission_id = d.admission_idJOIN adt.t_admission_details ad on ad.admission_id = a.admission_idJOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_idWhere d.discharge_date IN (SELECT d.discharge_date FROM "adt".t_discharge d WHERE (d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date)AND d.status = 'A')AND d.status = 'A'GROUP BY d.unit_id ,d.organization_id,d.discharge_date :: DATE ,a.speciality_id ,d.doctor_id,ca.diagnosis_id,d.status;END;$function$;

-- DROP FUNCTION procedure_old.get_avg_length_stay(date);
CREATE OR REPLACE FUNCTION procedure_old.get_avg_length_stay(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, total_discharge_days_count bigint, total_discharge_count bigint, date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selects.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.admission_type_id,sum(case when diff &lt;= 12 then 0.5 else (diff / 24) + (case when diff % 24 = 0 then 0 else 1 end ) end) :: bigint as total_discharge_days_count,count(distinct s.discharge_id):: bigint as total_discharge_count,generate_series(p_date::date , current_timestamp::date, '1day' )::date date,s.is_deletedfrom(selecta.unit_id ,a.organization_id,a.speciality_id ,d.doctor_id ,ad.admission_type_id,d.discharge_id,extract(epochfromd.discharge_date - ad.doa)::integer / 3600 as diff,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_discharge djoin adt.t_admission a ond.admission_id = a.admission_idand a.visit_type_id in (2)join adt.t_admission_details ad ond.admission_id = ad.admission_idwhere((d.updated_date::date &gt;= p_dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_dateand d.created_date::date &lt; current_date))group bya.unit_id ,a.organization_id,a.speciality_id ,d.discharge_date,d.doctor_id,ad.doa,d.discharge_id,a.status,ad.admission_type_id )sgroup bys.unit_id ,s.organization_id,s.speciality_id ,s.doctor_id,s.discharge_id,s.admission_type_id,s.is_deleted;end;$function$;

-- DROP FUNCTION procedure_old.get_avgerage_lenght_stay(date);
CREATE OR REPLACE FUNCTION procedure_old.get_avgerage_lenght_stay(p_date date)RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, disease_id integer, total_discharge integer, total_discharge_days integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT a.dod :: date as discharge_date,a.unit_id,a.organization_id as hospital_id , a.speciality_id,a.doctor_id,a.admission_type_id,a.diagnosis_id as disease_id,COUNT(distinct a.discharge_id):: INTEGER as total_discharge ,SUM(CASE WHEN date_diff&lt;=12 THEN 0.5 ELSE (date_diff/24) + (CASE WHEN date_diff%24 = 0 THEN 0 ELSE 1 END ) END) :: integer as total_discharge_days ,a.statusFROM (SELECT a.discharge_id,a.admission_id, extract (epoch from ((dod-doa)))::integer/3600 as date_diff, dod, doa,a.unit_id,a.organization_id, a.admission_id,a.speciality_id,a.doctor_id,a.admission_type_id,a.diagnosis_id,a.statusFROM (select DIstinct ON (a.unit_id,a.organization_id, a.admission_id,a.speciality_id,a.doctor_id,ad.admission_type_id)d.unit_id,d.organization_id, a.speciality_id,a.doctor_id,ad.admission_type_id,d.discharge_id,a.admission_id,ad.doa ,d.discharge_date,d.discharge_time,ca.diagnosis_id,d.status ,make_timestamp(EXTRACT(year from d.discharge_date):: integer ,EXTRACT(month from d.discharge_date) :: integer ,EXTRACT(day from d.discharge_date) :: integer ,EXTRACT(hour from d.discharge_time) :: integer,EXTRACT(minute from d.discharge_time) :: integer ,EXTRACT(second from d.discharge_time)) as dod FROM adt.t_discharge d JOIN adt.t_admission a on a.admission_id = d.admission_id AND a.visit_type_id NOT IN (3,4)JOIN adt.t_admission_details ad on ad.admission_id = a.admission_id JOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_id WHERE d.discharge_date IN (SELECT d.discharge_dateFROM adt.t_discharge dWHERE (d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date)AND d.discharge_status_id=5 AND d.is_death='N' AND d.status = 'A' )AND d.discharge_status_id=5 AND d.is_death='N' AND d.status = 'A')a)aGROUP BYa.dod :: date ,a.unit_id,a.organization_id, a.speciality_id,a.doctor_id,a.diagnosis_id,a.status,a.admission_type_id;END;$function$;

-- DROP FUNCTION procedure_old.get_bed_category_wise_billing(date);
CREATE OR REPLACE FUNCTION procedure_old.get_bed_category_wise_billing(p_date date)RETURNS TABLE(unit_id integer, org_id integer, bill_date_time date, bill_number character varying, doctor_id integer, speciality_id integer, patient_id integer, bed_category_id integer, bed_number character varying, sum double precision, status "char")LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT a.unit_id ,a.organization_id,bm.bill_date_time::date,bm.bill_number,dsm.doctor_id,dsm.speciality_id,bm.patient_id,b.bed_category_id,b.bed_number,sum(bm.net_amount),bm.statusfrom billing.m_billing_master bmJOIN adt.t_admission a on a.admission_id = bm.admission_idJOIN adt.t_admission_details ad on ad.admission_id = a.admission_idLEFT JOIN adt.m_bed_master b on b.bed_category_id = ad.bed_category_idLEFT JOIN doctor.t_doctor_speciality_mapper dsm on dsm.doctor_id = a.doctor_idWHERE bm.bill_date_time::date IN (SELECT bm.bill_date_time::dateFROM billing.m_billing_master bmWHERE(bm.updated_date::DATE&gt;=p_date OR bm.created_date::DATE&gt;=p_date)AND bm.status = 'A') AND bm.status = 'A'GROUP BY bm.bill_date_time::date,bm.bill_number,dsm.doctor_id,dsm.speciality_id,bm.patient_id,b.bed_category_id,b.bed_number,a.unit_id ,bm.status,a.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_bed_occupancy_rate(date);
CREATE OR REPLACE FUNCTION procedure_old.get_bed_occupancy_rate(p_date date)RETURNS TABLE(bed_occupied_date date, unit_id integer, hospital_id integer, admission_type_id integer, bed_category_id integer, status boolean, total_beds bigint, available_beds bigint, occupied_beds bigint, undermaintenance_count bigint)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT dt.date :: date as bed_occupied_date ,a.unit_id,a.organization_id as hospital_id,a.admission_type_id,a.bed_category_id,CASE WHEN a.status ilike 'A' then falseELSE TRUEEND AS is_deleted,(SELECT count(DISTINCT b.bed_id) from adt.m_bed_master as b) as total_beds,(select count(DISTINCT b.bed_id)from adt.m_bed_master as bwhere b.bed_id NOT IN (SELECT x FROM unnest(array_agg(DISTINCT a.bed_id)) x WHERE x IS NOT NULL UNION SELECT 0)AND b.bed_id NOT IN (SELECT x FROM unnest(array_agg(DISTINCT u.bed_id)) x WHERE x IS NOT NULL UNION SELECT 0)) as available_beds, (select count(DISTINCT b.bed_id)from adt.m_bed_master as bwhere b.bed_id IN (SELECT x FROM unnest(array_agg(DISTINCT a.bed_id)) x WHERE x IS NOT NULL UNION SELECT 0)) AS occupied_bed,count(DISTINCT u.bed_id) as under_maintenance_count FROM (SELECT generate_series('2015-01-01'::date , CURRENT_TIMESTAMP::date, '1day')as date ) dtLEFT JOIN (SELECT a.unit_id,a.organization_id,a.admission_type_id,a.bed_category_id,COUNT(DISTINCT a.bed_id) as occupied_bed,UNNEST(ARRAY_AGG(DISTINCT a.bed_id)) as bed_id,doa ,a.statusFROM (SELECT a.bed_id,a.unit_id,a.organization_id,a.admission_type_id,a.bed_category_id,a.status,generate_series(a.doa, CASE WHEN d.discharge_date IS NULL THEN CURRENT_TIMESTAMP::DATE ELSE d.discharge_date END, '1day') as doaFROM adt.t_admission_details aLEFT JOIN adt.t_discharge d ON a.admission_id=d.admission_id )aGROUP BY a.doa,a.unit_id,a.organization_id,a.admission_type_id,a.status,a.bed_category_id)a ON dt.date = a.doaLEFT JOIN (SELECT generate_series(created_date,actual_date,'1day' ) as dt, bed_id FROM adt.t_under_maintenance) u ON u.dt=dt.dateWHERE a.doa IN (SELECT ad.doa FROM "adt".t_admission_details adWHERE(ad.updated_date::DATE&gt;='2018-12-1' OR ad.created_date::DATE&gt;='2018-12-1')AND ad.status = 'A')GROUP BY dt.date, a.admission_type_id,a.bed_category_id,a.unit_id,a.organization_id,a.status;END;$function$;

-- DROP FUNCTION procedure_old.get_bed_reservation(date);
CREATE OR REPLACE FUNCTION procedure_old.get_bed_reservation(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, patient_id integer, speciality_id integer, doctor_id integer, admission_type_id integer, is_doa_flexible character, count integer, date date)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectad.unit_id,ad.organization_id,adm.bed_category_id,ad.patient_id,ad.doctor_speciality_id,ad.treating_doctor_id,ad.admission_type_id,ad.is_flexiable_date,count(distinct coalesce( ad.patient_id, 0)) :: integer as bed_count,adm.doa::datefromadt.t_admission_note adjoin adt.t_admission_patient_mapping adm on(ad.admission_note_id=adm.admission_note_id)where((ad.updated_date::date &gt;= p_dateand ad.updated_date::date &lt; current_date)or (ad.created_date::date &gt;= p_dateand ad.created_date::date &lt; current_date))and ad.admission_status = 'R'group byad.unit_id,ad.organization_id,ad.patient_id,ad.doctor_speciality_id,ad.treating_doctor_id,ad.admission_type_id,ad.is_flexiable_date,adm.bed_category_id,adm.doa;end;$function$;

-- DROP FUNCTION procedure_old.get_bi_patient_category_wise_billing_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_bi_patient_category_wise_billing_report(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bill_date_time date, bill_number character varying, visit_type_id integer, patient_id integer, patient_category_id integer, sum double precision, status "char")LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT pr.unit_id ,pr.organization_id,b.bill_date_time::date ,b.bill_number,b.visit_type_id,b.patient_id,pr.patient_category_id,sum(b.net_amount),b.statusFROM billing.m_billing_master bJOIN patient.t_patient_registration pr on b.patient_id = pr.patient_idJOIN public.m_patient_category_master pcm on pcm.patient_category_id = pr.patient_category_idWHERE b.bill_date_time::date IN (SELECT b.bill_date_time::dateFROM billing.m_billing_master bWHERE(b.updated_date::DATE&gt;=p_date OR b.created_date::DATE&gt;=p_date)AND b.status = 'A')AND b.status = 'A'GROUP BY b.bill_date_time::date ,b.bill_number,b.visit_type_id,b.patient_id,pr.patient_category_id,b.status,pr.unit_id ,pr.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_bi_pending_vendor_return(date);
CREATE OR REPLACE FUNCTION procedure_old.get_bi_pending_vendor_return(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, return_date date, vendor_id integer, ret_gp_no character varying, generic_id integer, product_category_id integer, brand_id integer, return_qty integer, reject_reason_id integer, value_cop double precision, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT rgd.unit_id,rgd.organization_id as hospital_id,rgd.added_date:: date as return_date ,rg.vendor_id, MAX(rg.ret_gp_no) :: character varying as ret_gp_no,i.generic_id,i.product_category_id,i.id brand_id,sum(rgd.return_qty):: integer as return_qty,rgd.reject_reason_id,sum(rgd.return_qty * b.cop) value_cop,rgd.is_deletedfrom inventory.t_returnable_gatepass_detail rgdJOIN inventory.t_returnable_gatepass rg on rg.id = rgd.returnable_gatepass_idJOIN inventory.t_batch b on b.id = rgd.batch_id JOIN public.m_item i on i.id = b.item_idWHERE rgd.added_date::date IN (SELECT rgd.added_date::dateFROM inventory.t_returnable_gatepass_detail rgdWHERE(rgd.updated_date::DATE&gt;=p_date OR rgd.added_date::DATE&gt;=p_date)AND rgd.is_deleted = false)AND b.is_deleted = falseGROUP BY rg.vendor_id,i.generic_id,i.product_category_id,i.id,rgd.reject_reason_id,rgd.unit_id,rgd.organization_id,rgd.is_deleted,rgd.added_date::date;END;$function$;

-- DROP FUNCTION procedure_old.get_billable_consumption(date);
CREATE OR REPLACE FUNCTION procedure_old.get_billable_consumption(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, added_date date, nursing_station_id integer, patient_id integer, bed_id integer, user_id integer, product_category_id integer, generic_id integer, batch_no character varying, consumable_quantity integer, mrp double precision, amount double precision, is_deleted boolean, is_billable boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY (SELECT bc.unit_id,bc.organization_id,bc.added_date ::date,nsm.nursing_station_id, bc.patient_id ,bm.bed_id,bc.added_by user_id,i.product_category_id,i.generic_id,MAX(b.batch_no):: character varying as batch_no ,sum(bcd.consumable_quantity):: integer as consumable_quantity,sum(b.rate) mrp,sum(bcd.consumable_quantity * b.rate) amount,bc.is_deleted,'TRUE':: boolean as is_billable FROM pharmacy.t_billable_consumption bc JOIN pharmacy.t_billable_consumption_detail bcd on bcd.billable_consumption_id = bc.idLEFT JOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = bc.ward_idLEFT JOIN adt.m_bed_master bm on bm.bed_id = bc.bed_idJOIN inventory.t_batch b on b.id = bcd.batch_idJOIN public.m_item i on i.id = b.item_idWHERE bc.added_date ::date IN (SELECT bc.added_date ::dateFROM pharmacy.t_billable_consumption bc WHERE(bc.updated_date::DATE&gt;='2017-10-17' OR bc.added_date::DATE&gt;='2017-10-17')AND bc.is_deleted = false)AND bc.is_deleted = falseGROUP BY nsm.nursing_station_id, bc.patient_id ,bc.added_by,i.product_category_id,i.generic_id,bm.bed_id,bc.added_date ::date,bc.unit_id,bc.is_deleted,bc.organization_id)UNION ( SELECT nbc.unit_id,nbc.organization_id,nbc.added_date ::date,nsm.nursing_station_id, NULL,NULL,nbc.added_by user_id,i.product_category_id,i.generic_id,MAX(b.batch_no):: character varying as batch_no ,sum(nbcd.consumed_qty):: integer as consumable_quantity,sum(b.rate) mrp,sum(nbcd.consumed_qty * b.rate) amount,nbc.is_deleted,'FALSE':: boolean as is_billable FROM inventory.t_non_billable_consumption nbc JOIN inventory.t_non_billable_consumption_detail nbcd on nbc.id = nbcd.non_billable_consumption_idLEFT JOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = nbc.ward_id--LEFT JOIN adt.m_bed_master bm on bm.bed_id = nbc.bed_idJOIN inventory.t_batch b on b.id = nbcd.batch_idJOIN public.m_item i on i.id = b.item_id WHERE nbc.added_date ::date IN (SELECT bc.added_date ::dateFROM inventory.t_non_billable_consumption bc WHERE(bc.updated_date::DATE&gt;='2017-10-17' OR bc.added_date::DATE&gt;='2017-10-17')AND bc.is_deleted = false)AND nbc.is_deleted = falseGROUP BY nsm.nursing_station_id, nbc.added_by,i.product_category_id,i.generic_id,nbc.added_date ::date,nbc.unit_id,nbc.is_deleted,nbc.organization_id);
 END;$function$;

-- DROP FUNCTION procedure_old.get_birth_registration(date);
CREATE OR REPLACE FUNCTION procedure_old.get_birth_registration(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, gender character varying, baby_uhid character varying, baby_name character varying, outcome character varying, trimester character varying, date date, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select r.unit_id,r.organization_id,r.patient_id,r.sex,r.uhid_number_baby,r.baby_name,r.outcome,'trimester'::varchar as trimester,r.dob::date,r.statusfrom public.m_new_born_baby_reg rwhere--(r.updated_date::date &gt;= p_date ::date and r.updated_date::date &lt; current_date or r.created_date::date &gt;= p_date::date and r.created_date::date &lt; current_date);
--((TO_TIMESTAMP(r.updated_date, 'MM-DD-YYYY HH24:MI:SS'))::date &gt;= p_date ::date and (TO_TIMESTAMP(r.updated_date, 'MM-DD-YYYY HH24:MI:SS'))::date &lt; current_date or (TO_TIMESTAMP(r.created_date, 'MM-DD-YYYY HH24:MI:SS'))::date &gt;= p_date::date and (TO_TIMESTAMP(r.created_date, 'MM-DD-YYYY HH24:MI:SS'))::date &lt; current_date);
r.dob::date&gt;=p_date and r.dob::date&lt;current_date;end;$function$;

-- DROP FUNCTION procedure_old.get_consignment_store_stock_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_consignment_store_stock_report(p_date date)RETURNS TABLE(item_id integer, vendor_id integer, grn_date date, grn_number character varying, quantity integer, cop double precision, value_cop double precision, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select b.item_id, grn.vendor_id,grn.added_date :: date as grn_date,MAX(grn.grn_number):: character varying as grn_number,sum(ss.available_qty):: integer as quantity,sum(b.cop) as cop,sum((b.quantity*b.cop)) as value_cop, b.unit_id ,b.organization_id as hospital_id ,b.is_deletedfrom inventory.t_batch bJOIN inventory.t_store_stock ss on ss.batch_id = b.idJOIN procurement.t_good_receipt_note_detail grnd on grnd.batch_id = b.idJOIN procurement.t_good_receipt_note grn ON grn.id = grnd.grn_idWHERE grn.added_date::date IN (SELECT grn.added_date::dateFROM procurement.t_good_receipt_note grn WHERE(grn.updated_date::DATE&gt;=p_date OR grn.added_date::DATE&gt;=p_date)AND grn.is_deleted = false)AND b.is_deleted = falseGROUP BYb.item_id,grn.vendor_id,grn_date, b.unit_id ,b.organization_id ,b.is_deletedORDER BY grn_date;END;$function$;

-- DROP FUNCTION procedure_old.get_crash_cart_utilization_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_crash_cart_utilization_report(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, crash_cart_date date, nursing_station_id integer, user_id integer, patient_id integer, bed_id integer, generic_id integer, brand_id integer, batch_no character varying, expiry_date date, approved_quantity integer, mrp double precision, amount double precision, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT ccr.unit_id,ccr.organization_id as hospital_id ,ccr.added_date :: date as crash_cart_date ,nsm.nursing_station_id, ccr.added_by user_id,ccr.patient_id, ccr.bed_id, i.generic_id ,ccd.item_id brand_id,MAX(b.batch_no):: character varying as batch_no,b.expiry_date::date ,MAX(ccd.approved_quantity) :: integer as approved_quantity,sum(b.rate) mrp,sum((ccd.approved_quantity*b.rate)) as amount,ccr.is_deletedFROM pharmacy.t_crash_cart_request ccr JOIN pharmacy.t_crash_cart_request_detail ccd on ccd.crash_cart_id = ccr.idJOIN pharmacy.t_crash_cart_batch_mapper ccb on ccb.crash_cart_detail_id = ccd.idJOIN inventory.t_batch b on b.id = ccb.batch_idJOIN adt.t_nursing_station_ward_mapper nsm on nsm.ward_id = ccr.ward_id JOIN public.m_item i on i.id = ccd.item_idWHERE ccr.added_date IN (SELECT ccr.added_dateFROM pharmacy.t_crash_cart_request ccr WHERE(ccr.updated_date::DATE&gt;=p_date OR ccr.added_date::DATE&gt;=p_date)AND ccr.is_deleted = False ) AND b.expiry_date IN (SELECT b.expiry_date FROM inventory.t_batch b WHERE(b.updated_date::DATE&gt;=p_date OR b.added_date::DATE&gt;=p_date)AND b.is_deleted = False ) AND b.is_deleted = False AND ccr.is_deleted = FalseGROUP BY nsm.nursing_station_id, ccr.added_by,ccr.patient_id, ccr.bed_id, i.generic_id ,ccd.item_id,b.expiry_date::date ,ccr.added_date,ccr.unit_id,ccr.is_deleted,ccr.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_death_statistics(date);
CREATE OR REPLACE FUNCTION procedure_old.get_death_statistics(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, discharge_date date, death_count integer, doctor_id integer, speciality_id integer, admission_type_id integer, is_medico_legal character, duration_of_stay bigint, is_high_risk character, diagnosis_id integer, status character, is_notifiable character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select d.unit_id,d.organization_id,d.discharge_date :: DATE ,count(d.discharge_id) :: integer death_count ,d.doctor_id,a.speciality_id,ad.admission_type_id,ad.is_medico_legal ,extract(epoch from(d.discharge_date - ad.doa )):: bigint/3600 duration_of_stay,ad.is_high_risk ,ca.diagnosis_id ,a.status,dm.is_notifiable FROM "adt".t_discharge d JOIN "adt".t_admission a on d.admission_id = a.admission_id JOIN "adt".t_admission_details ad on d.admission_id = ad.admission_id JOIN patient.t_patient_registration pr on pr.patient_id = a.patient_idJOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_idJOIN emr.m_diagnosis_master dm on dm.diagnosis_id = ca.diagnosis_id where d.is_death = 'Y' AND d.visit_type_id &lt;&gt; 4AND a.patient_id NOT IN (select nbd.patient_id from "patient".t_new_born_details nbd where is_still_birth = 'Y')AND d.discharge_date IN (SELECT d.discharge_date FROM "adt".t_discharge d WHERE(d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date)AND d.status = 'A')AND d.status = 'A'GROUP BY d.unit_id,d.discharge_date :: date ,d.organization_id,ad.admission_type_id,d.doctor_id,a.speciality_id ,ad.is_medico_legal,ad.is_high_risk ,ca.diagnosis_id ,a.status,dm.is_notifiable ,duration_of_stay;END;$function$;

-- DROP FUNCTION procedure_old.get_discharge_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.get_discharge_analysis(p_date date)RETURNS TABLE(organization_id integer, unit_id integer, discharge_date date, admission_type_id integer, visit_type_id integer, speciality_id integer, doctor_id integer, discharge_type_id integer, payment_entitlement_id integer, age integer, gender_id integer, is_mlc boolean, is_vip boolean, is_high_risk boolean, status boolean, count bigint)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERYSELECT admission.organization_id,admission.unit_id,discharge.discharge_date:: date,admissionDetails.admission_type_id, admission.visit_type_id, admission.speciality_id,admission.doctor_id,discharge.discharge_type_id,admissionPatient.payment_entitlement_id,extract(year from age(patientRegistration.dob)):: integer as age,patientRegistration.gender_id,false AS is_mlc,CASE WHEN patientRegistration.is_vip = 'N' THEN falseELSE True END AS vip,false AS high_risk,CASE WHEN discharge.status ilike 'A' then FALSEELSE TRUE END AS is_status,count(discharge.admission_id)FROM adt.t_admission admissionINNER JOIN adt.t_admission_details admissionDetails ON admissionDetails.admission_id = admission.admission_idINNER JOIN adt.m_admission_type_master admissionType ON admissionDetails.admission_type_id = admissionType.admission_type_idINNER JOIN public.m_visit_type_master visitType ON visitType.visit_type_id = admission.visit_type_idINNER JOIN doctor.m_speciality_master specialityMaster ON specialityMaster.speciality_id = admission.speciality_idLEFT JOIN adt.t_admission_note admissionNote ON admissionNote.admission_id = admission.admission_idLEFT JOIN adt.t_admission_patient_mapping admissionPatient ON admissionPatient.admission_note_id = admissionNote.admission_note_idINNER JOIN patient.t_patient_registration patientRegistration ON patientRegistration.patient_id = admission.patient_idINNER JOIN adt.t_discharge discharge on discharge.admission_id = admission.admission_idWHERE discharge.created_date IN (SELECT discharge.created_date FROM adt.t_discharge dischargeWHERE (discharge.updated_date::DATE&gt;=p_date OR discharge.created_date::DATE&gt;=p_date)AND discharge.status = 'A') AND discharge.status = 'A'GROUP BY admission.organization_id,admission.unit_id,discharge.discharge_date:: date,admission.admission_id,admissionDetails.admission_type_id, admission.visit_type_id,admission.speciality_id,admission.doctor_id,discharge.discharge_type_id,admissionPatient.payment_entitlement_id,age,patientRegistration.gender_id,is_mlc,vip,high_risk,is_statusorder by discharge.discharge_date:: date;END;$function$;

-- DROP FUNCTION procedure_old.get_discount(date);
CREATE OR REPLACE FUNCTION procedure_old.get_discount(p_date date)RETURNS TABLE(date date, sale_type_id integer, bill_no character varying, user_id integer, reason_id integer, amount double precision, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT (s.added_date):: date as discount_date ,s.sale_type_id, MAX(s.bill_no):: character varying as bill_no , s.added_by as user_id,d.id as reason_id, sum(s.total_discount_amount) as amount,s.unit_id, s.organization_id as hospital_id ,s.is_deletedfrom pharmacy.t_sale sJOIN public.m_discount_category d on d.id = s.discount_category_idWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;='2017-10-17 ' OR s.added_date::DATE&gt;='2017-10-17 ')AND s.is_deleted = false)AND s.is_deleted = falsegroup by s.added_date :: DATE ,s.sale_type_id,s.added_by ,d.id,s.unit_id,s.organization_id,s.is_deletedorder by s.added_date :: DATE ;END;$function$;

-- DROP FUNCTION procedure_old.get_doctor_wise_age_wise_disease_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_doctor_wise_age_wise_disease_report(p_date date)RETURNS TABLE(doa date, unit_id integer, hospital_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, age_group_id integer, no_of_patient integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT ad.doa :: DATE,a.unit_id,a.organization_id as hospital_id,a.speciality_id,a.doctor_id,ca.diagnosis_id,EXTRACT(year from age(pr.dob)):: INTEGER as age_group_id,COUNT(a.patient_id) :: INTEGER as no_of_patientFROM adt.t_admission aJOIN adt.t_admission_details ad ON ad.admission_id = a.admission_idJOIN adt.t_complaint_admission ca on ca.admission_id = a.admission_idJOIN patient.t_patient_registration pr on pr.patient_id = a.patient_idWHERE ad.doa IN (SELECT ad.doa FROM "adt".t_admission_details adWHERE(ad.updated_date::DATE&gt;=p_date OR ad.created_date::DATE&gt;=p_date)AND ad.status = 'A')AND ad.status = 'A'GROUP BY ad.doa,a.unit_id,a.organization_id,a.speciality_id,a.doctor_id,ca.diagnosis_id,age_group_id;END;$function$;

-- DROP FUNCTION procedure_old.get_drug_administration_delays(date);
CREATE OR REPLACE FUNCTION procedure_old.get_drug_administration_delays(p_date date)RETURNS TABLE(hospital_id integer, unit_id integer, delay_date timestamp without time zone, nursing_station_id integer, patient_id integer, gender_id integer, item_id integer, reason_id integer, user_id integer, time_gap time without time zone, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT prescription.organization_id as hospital_id, prescription.unit_id,prescription.added_date as delay_date,admissionDetail.ward_id as nursing_station_id,prescription.patient_id,patient.gender_id,prescriptionDetail.item_id, drugAdministrationDetail.reason_id, drugAdministrationDetail.added_by as user_id,(frequencyDetail.administration_time - drugAdministrationDetail.administration_time):: time as time_gap ,prescription.is_deletedFROM pharmacy.t_prescription prescriptionINNER JOIN pharmacy.t_prescription_detail prescriptionDetail ON prescription.id = prescriptionDetail.prescription_idINNER JOIN pharmacy.t_prescription_frequency_detail prescriptionFrequency ON prescriptionDetail.id = prescriptionFrequency.prescription_detail_id INNER JOIN pharmacy.t_drug_administration drugAdministration ON drugAdministration.prescription_id = prescription.idINNER JOIN pharmacy.t_drug_administration_detail drugAdministrationDetail ON drugAdministrationDetail.prescription_detail_id = prescriptionDetail.idINNER JOIN adt.t_admission admission ON admission.admission_id = prescription.admission_id INNER JOIN adt.t_admission_details admissionDetail ON admission.admission_id = admissionDetail.admission_idINNER JOIN patient.t_patient_registration patient ON patient.patient_id = prescription.patient_id INNER JOIN public.m_frequency frequency ON frequency.id = prescriptionFrequency.frequency_idINNER JOIN public.m_frequency_detail frequencyDetail ON frequency.id = frequencyDetail.frequency_idWHERE prescription.added_date::date IN (SELECT prescription.added_date::dateFROM pharmacy.t_prescription grn WHERE(prescription.updated_date::DATE&gt;= p_date OR prescription.added_date::DATE&gt;= p_date)AND prescription.is_deleted = false)AND prescription.is_deleted = falseGROUP BY prescription.organization_id,prescription.unit_id,prescription.added_date,admissionDetail.ward_id, prescription.patient_id,patient.gender_id,prescriptionDetail.item_id,drugAdministrationDetail.reason_id,drugAdministrationDetail.added_by,(frequencyDetail.administration_time - drugAdministrationDetail.administration_time),prescription.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_drug_consumption_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_drug_consumption_report(p_date date)RETURNS TABLE(drug_date date, visit_type_id integer, patient_id integer, doctor_id integer, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, unit_id integer, hospital_id integer, qty integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT d.added_date :: date as drug_date , d.visit_type_id,d.patient_id,p.doctor_id,i.product_category_id,i.generic_id,i.id brand_id,MAX(b.batch_no):: character varying,b.unit_id,b.organization_id as hospital_id ,COUNT(d.id):: integer qty,d.is_deletedFROM pharmacy.t_drug_administration dJOIN pharmacy.t_drug_administration_detail da on da.drug_administration_id = d.idJOIN pharmacy.t_prescription_detail pd on pd.id = da.prescription_detail_idJOIN pharmacy.t_prescription p on p.id = pd.prescription_idJOIN public.m_item i on i.id = pd.item_idJOIN inventory.t_batch b on b.item_id = i.idWHERE d.added_date::date IN (SELECT d.added_date::dateFROM pharmacy.t_drug_administration dWHERE(d.updated_date::DATE&gt;=p_date OR d.added_date::DATE&gt;=p_date)AND d.is_deleted = false)AND d.is_deleted = falseGROUP BY d.visit_type_id,d.patient_id,p.doctor_id,i.product_category_id,i.generic_id,i.id ,b.unit_id,b.organization_id,d.added_date::date,d.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_ehc(date);
CREATE OR REPLACE FUNCTION procedure_old.get_ehc(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, ehc_id integer, date date, status character)LANGUAGE plpgsqlAS $function$beginreturn QUERY select em.unit_id,em.organization_id,em.patient_id,0 as ehc_id,em.encounter_date::date,em.statusfromopd.t_encounter_master emwhere em.encounter_type_id=3and ((em.updated_date::date &gt;= p_date:: date and em.updated_date&lt; current_date )or em.created_date&gt;= p_date::date and em.created_date &lt; current_date);
end;$function$;

-- DROP FUNCTION procedure_old.get_er_72hrs_with_same_complaint(date);
CREATE OR REPLACE FUNCTION procedure_old.get_er_72hrs_with_same_complaint(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selecta.unit_id,a.organization_id,a.patient_id,extract(yearfromage(pr.dob))::integer as patient_age,cad.diagnosis_id,truefromadt.t_admission ajoin adt.t_admission_details adusing(admission_id)join adt.t_complaint_admission cadusing(admission_id)join patient.t_patient_registration prusing (patient_id)where((a.updated_date::date &gt;= p_date ::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))and a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')and exists (select 1fromadt.t_admission pajoin adt.t_complaint_admission pcadusing (admission_id)join adt.t_admission_details padmusing (admission_id)join adt.t_discharge dusing (admission_id)wherepa.patient_id = a.patient_idand a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')and pcad.icpc_system_id = cad.icpc_system_idand padm.is_discharge = 'D'and padm.doa &gt;= (ad.doa - ('72 hours')::interval)and ad.admission_id != padm.admission_id)group bya.patient_id,a.unit_id,a.organization_id,patient_age,cad.diagnosis_idunion selecta.unit_id,a.organization_id,a.patient_id,extract(yearfromage(pr.dob))::integer as patient_age,cad.diagnosis_id,falsefromadt.t_admission ajoin adt.t_admission_details adusing(admission_id)join adt.t_complaint_admission cadusing(admission_id)join patient.t_patient_registration prusing (patient_id)where((a.updated_date::date &gt;= p_date ::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))and a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')group bya.patient_id,a.unit_id,a.organization_id,patient_age,cad.diagnosis_id;end;$function$;

-- DROP FUNCTION procedure_old.get_expiry_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_expiry_report(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, product_category_id integer, store_id integer, generic_id integer, brand_id integer, expiry_date date, vendor_id integer, po_number character varying, grn_number character varying, grn_date date, uom_unit_id integer, quantity integer, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, scrapped boolean, batch_no character varying, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT b.unit_id,b.organization_id as hospital_id,i.product_category_id,po.store_id,i.generic_id,b.item_id brand_id,b.expiry_date,b.vendor_id,MAX(po.po_number):: character varying as po_number ,MAX(grn.grn_number) :: character varying as grn_number,grn.added_date::date grn_date,b.uom_unit_id,MAX(b.quantity):: integer as quantity ,sum(b.cop) cop,sum(b.rate) mrp,sum((b.quantity*b.cop)) as value_cop, sum((b.quantity*b.rate)) as value_mrp,CASE WHEN srd.batch_id = b.id then TrueElse FalseEND AS scrapped,MAX(b.batch_no):: character varying as batch_no,b.is_deletedFROM inventory.t_batch bJOIN public.m_item i on i.id = b.item_idLEFT JOIN procurement.t_purchase_order_detail pod on pod.item_id = i.idLEFT JOIN procurement.t_purchase_order po on po.id = pod.purchase_order_idLEFT JOIN procurement.t_good_receipt_note_detail grnd on grnd.batch_id = b.idLEFT JOIN procurement.t_good_receipt_note grn on grn.id = grnd.grn_idLEFT JOIN inventory.t_scrap_request_detail srd on srd.batch_id = b.idLEFT JOIN inventory.t_returnable_gatepass_detail rgd on rgd.batch_id = b.idLEFT JOIN inventory.t_returnable_gatepass rg on rg.id = rgd.returnable_gatepass_id WHERE b.expiry_date IN (SELECT b.expiry_dateFROM inventory.t_batch bWHERE(b.updated_date::DATE&gt;='2018-09-15 05:27:06.351' OR b.added_date::DATE&gt;='2018-09-15 05:27:06.351')AND b.is_deleted = False)AND b .is_deleted = False GROUP BY i.product_category_id,po.store_id,i.generic_id,b.item_id,b.expiry_date,b.vendor_id,grn.added_date,b.uom_unit_id,scrapped,b.unit_id,b.is_deleted,b.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_hr_medi_stock(date);
CREATE OR REPLACE FUNCTION procedure_old.get_hr_medi_stock(p_date date)RETURNS TABLE(store_id integer, generic_id integer, brand_id integer, quantity integer, batch_no character varying, expiry_date date, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select ss.store_id,im.generic_id,im.id as brand_id,sum(ss.available_qty):: integer as quantity,bm.batch_no,bm.expiry_date:: date,sum(bm.cop) as cop,sum(bm.rate ) as mrp,sum((bm.quantity*bm.cop)) as value_cop, sum((bm.quantity*bm.rate)) as value_mrp,bm.unit_id, bm.organization_id as hospital_id ,ss.is_deleted from inventory.t_batch bm inner join inventory.t_store_stock ss on ss.batch_id = bm.idinner join public.m_item im on bm.item_id = im.id WHERE im.is_high_risk_product = true AND bm.expiry_date IN (SELECT bm.expiry_dateFROM inventory.t_batch bmWHERE(bm.updated_date::DATE&gt;='2017-10-17' OR bm.added_date::DATE&gt;='2017-10-17')AND bm.is_deleted = false)AND bm.is_deleted = falsegroup by ss.store_id,im.generic_id,im.id ,bm.batch_no,bm.expiry_date,bm.unit_id,ss.is_deleted,bm.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_hr_medi_utili(date);
CREATE OR REPLACE FUNCTION procedure_old.get_hr_medi_utili(p_date date)RETURNS TABLE(nursing_station_id integer, date_consumption date, generic_id integer, brand_id integer, patient_id integer, doctor_id integer, batch_code character varying, quantity integer, staff_id integer, unit_id integer, organisation_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select nsm.nursing_station_id,s.added_date :: date as date_consumption,im.generic_id,im.id as brand_id,s.patient_id,p.doctor_id,MAX(bm.batch_no):: character varying as batch_no,sum(sd.quantity) :: integer as quantity,bm.added_by as user_id ,bm.unit_id,bm.organization_id,bm.is_deletedfrom inventory.t_batch bm join pharmacy.t_sale_detail sd on sd.batch_id = bm.idjoin pharmacy.t_sale s on sd.sale_id = s.idjoin pharmacy.t_prescription p on p.id = s.prescription_idjoin adt.t_admission a on p.visit_type_id = a.visit_type_id join adt.t_admission_details ad on a.admission_id = ad.admission_idjoin adt.t_nursing_station_ward_mapper nsm on ad.ward_id = nsm.ward_idjoin public.m_item im on bm.item_id = im.id WHERE im.is_high_risk_product = true AND bm.expiry_date IN (SELECT bm.expiry_dateFROM inventory.t_batch bmWHERE(bm.updated_date::DATE&gt;=p_date OR bm.added_date::DATE&gt;=p_date)AND bm.is_deleted = false)AND bm.is_deleted = falsegroup by nsm.nursing_station_id,s.added_date,im.generic_id,brand_id,s.patient_id,p.doctor_id,user_id ,bm.unit_id,bm.organization_id,bm.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_icu_48hrs(date);
CREATE OR REPLACE FUNCTION procedure_old.get_icu_48hrs(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,true from adt.t_admission a join adt.t_admission_details ad using(admission_id)join adt.t_transfer_request tr using (admission_id)join adt.t_complaint_admission cad using (admission_id)where tr.transfer_type_id = 3and ((tr.updated_date::date &gt;= p_date ::date and tr.updated_date::date &lt; current_date)or (tr.created_date::date &gt;= p_date::date and tr.created_date::date &lt; current_date))and exists (select 1 from adt.t_admission pa join adt.t_admission_details prad using(admission_id)join adt.t_transfer_request ptr using (admission_id)join adt.t_transfer t using(transfer_request_id)where pa.patient_id = a.patient_idand t.from_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')and t.from_date &gt;= (tr.created_date - ('48 hours')::interval)and ad.admission_id = prad.admission_id)group by a.patient_id, a.unit_id,a.organization_id,a.speciality_id,cad.diagnosis_idunion--total discharge from icu select a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,false from adt.t_admission a join adt.t_admission_details ad using(admission_id)join adt.t_transfer_request tr using (admission_id)join adt.t_complaint_admission cad using (admission_id) where ad.is_discharge = 'D'and tr.from_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')and ((tr.updated_date::date &gt;= p_date ::date and tr.updated_date::date &lt; current_date)or (tr.created_date::date &gt;= p_date::date and tr.created_date::date &lt; current_date))group by a.patient_id, a.unit_id,a.organization_id,a.speciality_id,cad.diagnosis_idunion--total transfers to icuselect a.unit_id,a.organization_id, a.patient_id,a.speciality_id,cad.diagnosis_id,false from adt.t_admission a join adt.t_admission_details ad using(admission_id)join adt.t_transfer_request tr using (admission_id)join adt.t_complaint_admission cad using (admission_id)where tr.to_ward_id in (select ward_id from adt.m_ward_master where is_icu = 'Y')and tr.transfer_type_id = 3and ((tr.updated_date::date &gt;= p_date ::date and tr.updated_date::date &lt; current_date)or (tr.created_date::date &gt;= p_date::date and tr.created_date::date &lt; current_date))group by a.patient_id, a.unit_id,a.organization_id,a.speciality_id,cad.diagnosis_id;end;$function$;

-- DROP FUNCTION procedure_old.get_inpatient_charges(date);
CREATE OR REPLACE FUNCTION procedure_old.get_inpatient_charges(p_date date)RETURNS TABLE(unit_id integer, organziation_id integer, service_rendered_date date, servcie_group_id integer, doctor_id integer, speciality_id integer, patient_id integer, service_master_id integer, sum double precision, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT a.unit_id,a.organization_id,od.ord_render_datetime::date as service_rendered_date,sm.speciality_id as service_group_id ,a.doctor_id ,a.speciality_id,om.patient_id,sm.service_master_id,sum(od.net_amount):: double precision,od.statusFROM public.t_order_details odJOIN service.m_service_master sm on od.service_id = sm.service_master_idJOIN public.t_order_master om on od.order_id = om.order_idJOIN adt.t_admission a on om.admission_id = a.admission_idWHERE om.visit_type_id &gt;1 AND od.service_rendered = 1 AND (om.admission_id NOT IN (SELECT bm.admission_idfrom billing.m_billing_master bm WHERE bm.admission_id is NOT NULL))AND od.ord_render_datetime::date IN (SELECT od.ord_render_datetime::dateFROM public.t_order_details odWHERE(od.updated_date::DATE&gt;=p_date OR od.created_date::DATE&gt;=p_date)AND od.status = 'A') AND od.status = 'A'GROUP BY service_group_id ,a.doctor_id ,a.speciality_id,om.patient_id,sm.service_master_id,service_rendered_date,a.unit_id,od.status,a.organization_id;END;$function$;

