CREATE OR REPLACE FUNCTION procedure_old.get_masters_appointment(p_date date)RETURNS TABLE(appointment_id integer, unit_id integer, hospital_id integer, appointment_date timestamp without time zone, doctor_id integer, appointment_status_id integer, patient_id integer, encounter_date timestamp without time zone, consultation_type_id integer, visit_type_id integer, speciality_id integer, reason_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select am.appointment_id,am.unit_id,am.organization_id as hospital_id,sm.appointment_date ,em.doctor_id ,am.appointment_status_id,am.patient_id,em.encounter_date ,em.user_defined_visit_type_id as consultation_type_id,sm.visit_type_id,sm.speciality_id ,am.cancel_reason_id as reason_id,am.statusFROM opd.m_appointment_master amJOIN opd.t_encounter_master em on em.appointment_id = am.appointment_idLEFT JOIN opd.m_slot_master sm on sm.slot_id = am.slot_idWHERE em.encounter_date IN (Select em.encounter_dateFROM opd.t_encounter_master em WHERE (em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date)AND em.status = 'A') OR sm.appointment_date IN (Select sm.appointment_dateFROM opd.m_slot_master sm WHERE (sm.updated_date::DATE&gt;=p_date OR sm.created_date::DATE&gt;=p_date)AND sm.status = 'A')AND em.status = 'A' AND sm.status = 'A'GROUP BY am.appointment_id,am.unit_id,am.organization_id,sm.appointment_date ,em.doctor_id ,am.appointment_status_id,em.encounter_date ,consultation_type_id,sm.visit_type_id,sm.speciality_id ,reason_id,am.status;END ;$function$;

