-- DROP FUNCTION procedure_old.get_morgue_utilization(date);
CREATE OR REPLACE FUNCTION procedure_old.get_morgue_utilization(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, morgue_number character varying, patient_id integer, kin_name character varying, phone_no character varying, occupied_date_time timestamp without time zone, expected_release_date_time timestamp without time zone, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT mr.unit_id,mr.organization_id,bed_number as morgue_number,mr.patient_id ,kd.kin_name,kd.phone_no,mr.created_date as occupied_date_time ,make_timestamp(EXTRACT(year from mr.expected_release_date):: integer ,EXTRACT(month from mr.expected_release_date) :: integer ,EXTRACT(day from mr.expected_release_date) :: integer ,EXTRACT(hour from mr.expected_release_time) :: integer,EXTRACT(minute from mr.expected_release_time) :: integer ,EXTRACT(second from mr.expected_release_time)) as expected_release_date_time,mr.statusFROM adt.t_mortuary_request mr JOIN adt.m_bed_master bm on bm.bed_id = mr.mortuary_bed_idJOIN adt.t_admission a on a.admission_id = mr.admission_idJOIN patient.t_patient_registration pr on pr.patient_id = mr.patient_idJOIN public.m_kin_details kd on kd.kin_id = mr.admission_kin_idWHERE mr.created_date IN (SELECT mr.created_date FROM adt.t_mortuary_request mr WHERE (mr.updated_date::DATE&gt;=p_date OR mr.created_date::DATE&gt;=p_date)AND mr.status = 'A')AND mr.status = 'A'GROUP BY bm.bed_number,mr.patient_id ,kd.kin_name,kd.phone_no,mr.created_date ,mr.unit_id,mr.organization_id,mr.status,expected_release_date_time;END;$function$;

-- DROP FUNCTION procedure_old.get_mortality_register(date);
CREATE OR REPLACE FUNCTION procedure_old.get_mortality_register(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, is_death character, reason_id integer, date timestamp without time zone, status character)LANGUAGE plpgsqlAS $function$ BeginReturn query SELECT at.unit_id,at.organization_id,at.patient_id,ad.doctor_id,sdm.speciality_id,aca.diagnosis_id,ad.is_death,ad.reason_id,ad.discharge_date,ad.statusFROM adt.t_admission atJOIN adt.t_discharge ad on at.admission_id=ad.admission_id and at.organization_id=ad.organization_idJOIN adt.t_complaint_admission aca on aca.admission_id=at.admission_id and aca.organization_id=at.organization_idJOIN doctor.t_doctor_speciality_mapper sdm on sdm.doctor_id=ad.doctor_idWHERE ad.discharge_date::date &gt;= p_date::date and ad.discharge_date::date &lt; current_dateGROUP BY at.unit_id,at.organization_id,at.patient_id,ad.doctor_id,sdm.speciality_id,aca.diagnosis_id,ad.is_death,ad.reason_id,ad.discharge_date,ad.statusORDER BY ad.discharge_date ;end;$function$;

-- DROP FUNCTION procedure_old.get_mortuary_utilization(date);
CREATE OR REPLACE FUNCTION procedure_old.get_mortuary_utilization(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, occupied_on_date date, expected_release_date date, morgue_number character varying, patient_id integer, kin_id integer, status character)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectad.unit_id,ad.organization_id,ad.expected_arrival_date::date,ad.expected_release_date::date,ad.toe_band_id,kd.death_registration_id,kd.kin_id,ad.statusfromadt.t_mortuary_request adinner join patient.t_death_registration kd onad.d_patient_id=kd.death_registration_id-- inner join adt.t_mortuary_request mr on-- ad.admission_id=mr.admission_idwhere((ad.updated_date::date &gt;= p_dateand ad.updated_date::date &lt; current_date)or (ad.created_date::date &gt;= p_dateand ad.created_date::date &lt; current_date))group byad.unit_id,ad.organization_id,ad.expected_arrival_date,ad.expected_release_date,ad.toe_band_id,kd.death_registration_id,kd.kin_id,ad.status;end;$function$;

-- DROP FUNCTION procedure_old.get_no_show_cases(date);
CREATE OR REPLACE FUNCTION procedure_old.get_no_show_cases(p_date date)RETURNS TABLE(appointment_date timestamp without time zone, organization_id integer, unit_id integer, speciality_id integer, doctor_id integer, patient_id integer, status boolean, count integer)LANGUAGE plpgsqlAS $function$BEGINRETURN QUERY select opd.created_date, opd.organization_id, opd.unit_id, sm.speciality_id, sm.doctor_id, opd.patient_id, 'false':: boolean, count(opd.patient_id):: Intfrom opd.m_appointment_master opdJOIN opd.m_slot_master sm ON sm.slot_id = opd.slot_id and sm.status ='A'where opd.appointment_status_id = 7AND opd.created_date IN (SELECT opd.created_dateFROM opd.m_appointment_master opdWHERE(opd.updated_date::DATE&gt;=p_date OR opd.created_date::DATE&gt;=p_date)AND opd.status = 'A')group by opd.created_date, opd.organization_id, opd.unit_id, sm.speciality_id, sm.doctor_id, opd.patient_id ;END;$function$;

-- DROP FUNCTION procedure_old.get_non_billable_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_non_billable_report(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, added_date date, ward_id integer, user_id integer, product_category_id integer, generic_id integer, batch_no character varying, cost double precision, amount double precision, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT nbc.unit_id,nbc.organization_id as hospital_id ,nbc.added_date:: date, nbc.ward_id ,nbc.added_by user_id,i.product_category_id ,i.generic_id,MAX(b.batch_no):: character varying as batch_no,SUM(b.rate) as cost,SUM(nbcd.accepted_qty * b.rate) as amount,nbc.is_deleted FROM inventory.t_non_billable_consumption nbcJOIN inventory.t_non_billable_consumption_detail nbcd on nbcd.non_billable_consumption_id = nbc.idJOIN inventory.t_batch b on b.id = nbcd.batch_idJOIN public.m_item i on i.id = b.item_idWHERE nbc.added_date IN (SELECT nbc.added_dateFROM inventory.t_non_billable_consumption nbcWHERE(nbc.updated_date::DATE&gt;=p_date OR nbc.added_date::DATE&gt;=p_date)AND nbc.is_deleted = false)AND nbc.is_deleted = falseGROUP BY nbc.added_date:: date, nbc.ward_id ,nbc.added_by,i.product_category_id ,i.generic_id,nbc.unit_id,nbc.is_deleted,nbc.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_notifiable_disease(date);
CREATE OR REPLACE FUNCTION procedure_old.get_notifiable_disease(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, appointment_date date, no_of_disease_diagnosed integer, diagnosis_id integer, patient_id integer, status boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT em.unit_id,em.organization_id as hospital_id,opd.created_date :: DATE as appointment_date,COUNT(pd.diagnosis_id) :: INTEGER as no_of_disease_diagnosed ,pd.diagnosis_id,em.patient_id,'false':: booleanfrom opd.t_encounter_master emJOIN opd.m_appointment_master opd on em.appointment_id = opd.appointment_idJOIN patient.t_patient_diagnosis_appo_mapper pd on pd.encounter_id = em.encounter_id JOIN patient.diagnosis_master dm on dm.diagnosis_id = pd.diagnosis_idWHERE em.encounter_date IN (SELECT em.encounter_date FROM opd.t_encounter_master emWHERE (em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date)AND em.status = 'A') AND em.status = 'A'GROUP BY opd.created_date :: DATE,pd.diagnosis_id,em.patient_id,em.unit_id,em.organization_id;END ; $function$;

-- DROP FUNCTION procedure_old.get_nursing_station_master();
CREATE OR REPLACE FUNCTION procedure_old.get_nursing_station_master()RETURNS TABLE(station_id integer, hospital_id integer, unit_id integer, nursing_station_code character varying, nursing_station_desc character varying, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select nm.nursing_station_id as station_id,nm.organization_id as hospital_id,nm.unit_id,nm.nursing_station_code,nm.nursing_station_desc,nm.statusFROM adt.m_nursing_station_master nmWHERE ((nm.updated_date::DATE&gt;='2019-01-01' and nm.updated_date::DATE&lt;current_timestamp) or(nm.created_date::DATE&gt;='2019-07-21' and nm.created_date::DATE&lt;current_timestamp))AND s.is_deleted = FALSE;END ;$function$;

-- DROP FUNCTION procedure_old.get_nursing_station_master(date);
CREATE OR REPLACE FUNCTION procedure_old.get_nursing_station_master(p_date date)RETURNS TABLE(station_id integer, hospital_id integer, unit_id integer, nursing_station_code character varying, nursing_station_desc character varying, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select nm.nursing_station_id as station_id,nm.organization_id as hospital_id,nm.unit_id,nm.nursing_station_code,nm.nursing_station_desc,nm.statusFROM adt.m_nursing_station_master nmWHERE ((nm.updated_date::DATE&gt;=p_date and nm.updated_date::DATE&lt;current_timestamp) or(nm.created_date::DATE&gt;=p_date and nm.created_date::DATE&lt;current_timestamp));
END ;$function$;

-- DROP FUNCTION procedure_old.get_opd_inflow_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_opd_inflow_report(p_date date)RETURNS TABLE(encounter_date date, dept_id integer, doctor_id integer, user_defined_visit_type_id integer, appointment_date timestamp without time zone, registration_date timestamp without time zone, unit_id integer, hospital_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT em.encounter_date :: date ,em.dept_id,em.doctor_id,em.user_defined_visit_type_id,em.encounter_date as appointment_date ,pr.created_date as registration_date ,em.unit_id ,em.organization_id as hospital_id ,em.statusFROM opd.t_encounter_master emJOIN patient.t_patient_registration pr on em.patient_id = pr.patient_idWHERE em.encounter_date IN (SELECT em.encounter_date FROM opd.t_encounter_master em WHERE( em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date) AND em.status = 'A' )AND em.status = 'A'GROUP BY em.encounter_date :: date ,em.dept_id,em.doctor_id,em.unit_id ,em.organization_id ,em.status,em.user_defined_visit_type_id,em.encounter_date,pr.created_date;END ;$function$;

-- DROP FUNCTION procedure_old.get_opd_register(date);
CREATE OR REPLACE FUNCTION procedure_old.get_opd_register(p_date date)RETURNS TABLE(encounter_date date, unit_id integer, hospital_id integer, dept_id integer, consultation_type_id integer, patient_id integer, no_of_consultation integer, status character)LANGUAGE plpgsqlAS $function$BEGINRETURN QUERY select em.encounter_date :: date ,em.unit_id,em.organization_id as hospital_id ,em.dept_id,em.user_defined_visit_type_id as consultation_type_id,em.patient_id,count(DISTINCT em.patient_id) :: integer as no_of_consultation,em.status from opd.t_encounter_master emWHERE em.encounter_date IN (SELECT em.encounter_dateFROM opd.t_encounter_master emWHERE(em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date)AND em.status = 'A')AND em.status = 'A' group by em.encounter_date :: date ,em.unit_id,em.organization_id,em.dept_id,em.patient_id,em.status, em.user_defined_visit_type_id ;END;$function$;

-- DROP FUNCTION procedure_old.get_overbooked_appointments(date);
CREATE OR REPLACE FUNCTION procedure_old.get_overbooked_appointments(p_date date)RETURNS TABLE(dept_id integer, doctor_id integer, patient_id integer, appointment_type_id integer, unit_id integer, hospital_id integer, encounter_date date, overbooked_status character varying, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT em.dept_id, em.doctor_id,em.patient_id,am.appointment_type_id,em.unit_id ,em.organization_id as hospital_id,em.encounter_date :: DATE,CASE WHEN (COUNT(am.slot_id) &gt; 1) THEN 'overbooked'ELSE 'not_overbooked' :: CHARACTER VARYINGEND as overbooked_status,em.statusFROM opd.t_encounter_master emJOIN opd.m_appointment_master am ON am.appointment_id = em.appointment_idWHERE em.encounter_date IN (SELECT em.encounter_dateFROM opd.t_encounter_master emWHERE(em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date)AND em.status = 'A') AND em.status = 'A'GROUP BY em.dept_id, em.doctor_id,em.patient_id,am.appointment_type_id,em.status,em.unit_id ,em.organization_id,em.encounter_date :: DATE;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_billing_for_admitted_patient(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_billing_for_admitted_patient(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, nursing_station_id integer, patient_id integer, bed_number character varying, service_group integer, service_standard_name character varying, status character, sum double precision)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT a.unit_id,a.organization_id,n.nursing_station_id ,a.patient_id ,bm.bed_number,sm.speciality_id as service_group,sm.service_standard_name,sm.status,sum(b.net_amount)FROM billing.m_billing_master bJOIN billing.t_billing_details bd on b.billing_master_id = bd.billing_master_id JOIN adt.t_admission a on a.admission_id = b.admission_idJOIN service.m_service_master sm on sm.service_master_id = bd.service_idLEFT JOIN adt.t_admission_details ad on ad.admission_id = a.admission_idLEFT JOIN adt.m_bed_master bm on bm.bed_id = ad.bed_idLEFT JOIN adt.t_nursing_station_ward_mapper n on ad.ward_id = n.ward_idWHERE b.bill_date_time::date IN (SELECT b.bill_date_time::dateFROM billing.m_billing_master bWHERE(b.updated_date::DATE&gt;=p_date OR b.created_date::DATE&gt;=p_date)AND b.status = 'A')AND b.status = 'A'GROUP BY n.nursing_station_id ,a.patient_id ,bm.bed_number,sm.speciality_id ,sm.service_standard_name,sm.status,a.unit_id,a.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_category_wise_billing_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_category_wise_billing_report(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bill_date_time date, bill_number character varying, visit_type_id integer, patient_id integer, patient_type_id integer, sum double precision, status "char")LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT pr.unit_id ,pr.organization_id,b.bill_date_time::date ,b.bill_number,b.visit_type_id,b.patient_id,pcm.patient_category_id,sum(b.net_amount),b.statusFROM billing.m_billing_master bJOIN patient.t_patient_registration pr on b.patient_id = pr.patient_idJOIN public.m_patient_category_master pcm on pcm.patient_category_id = pr.patient_category_idWHERE b.bill_date_time::date IN (SELECT b.bill_date_time::dateFROM billing.m_billing_master bWHERE(b.updated_date::DATE&gt;=p_date OR b.created_date::DATE&gt;=p_date)AND b.status = 'A')AND b.status = 'A'GROUP BY b.bill_date_time::date ,b.bill_number,b.visit_type_id,b.patient_id,b.status,pcm.patient_category_id,pr.unit_id ,pr.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_location_report_for_front_office(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_location_report_for_front_office(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, floor_id integer, bed_id integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select a.unit_id,a.organization_id,a.patient_id,ad.floor_id,ad.bed_idFROM "patient".t_patient_registration prJOIN "adt".t_admission a on pr.patient_id = a.patient_idJOIN "adt".t_admission_details ad on a.admission_id = ad.admission_id WHERE(a.updated_date::DATE&gt;=p_date OR a.created_date::DATE&gt;=p_date)AND a.status = 'A'GROUP BYa.unit_id,a.organization_id, a.patient_id,ad.floor_id,ad.bed_id;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_returns_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_returns_report(p_date date)RETURNS TABLE(return_date date, sale_type_id integer, bill_no character varying, bill_date date, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, return_qty integer, cop double precision, mrp double precision, value_cop double precision, value_mrp double precision, reason text, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT r.added_date :: date as return_date,s.sale_type_id,MAX(s.bill_no) :: character varying as bill_no,s.added_date :: date as bill_date,g.product_category_id,im.generic_id,im.id as brand_id,MAX(b.batch_no) :: character varying as batch_no ,sum(rd.return_qty)::integer as return_qty ,sum(b.cop) as cop,sum(b.rate ) as mrp,sum((b.quantity*b.cop)) as value_cop, sum((b.quantity*b.rate)) as value_mrp,MAX(rd.remark)::text as reason,r.unit_id,r.organization_id as hospital_id,s.is_deletedFROM pharmacy.t_sale s JOIN pharmacy.t_sale_detail sd on sd.sale_id = s.idJOIN inventory.t_batch b on sd.batch_id = b.idJOIN pharmacy.t_return r on r.sale_id = s.id JOIN pharmacy.t_return_detail rd on rd.return_id = r.idJOIN public.m_item im on b.item_id = im.idJOIN public.m_generic g on g.id = im.generic_idWHERE r.added_date IN (SELECT r.added_dateFROM pharmacy.t_return rWHERE(r.updated_date::DATE&gt;=p_date OR r.added_date::DATE&gt;=p_date)AND r.is_deleted = false)AND r.is_deleted = falseGROUP BY return_date,s.sale_type_id,bill_date,g.product_category_id,im.generic_id,brand_id,r.unit_id,r.organization_id,s.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_sales(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_sales(p_date date)RETURNS TABLE(date date, store_id integer, generic_id integer, product_category_id integer, quantity integer, bill_no character varying, batch_code character varying, visit_type_id integer, mrp double precision, amount double precision, unit_id integer, organisation_id integer, is_deleted boolean, total_sale integer, brand_id integer, patient_id integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT s.added_date ::date as date ,s.store_id,i.generic_id,g.product_category_id,SUM(sd.quantity):: integer as quantity,s.bill_no:: character varying as bill_no ,b.batch_no:: character varying as batch_no,s.visit_type_id,SUM(sd.rate) as mrp,SUM(sd.net_amount) as amount,sd.unit_id,sd.organization_id,s.is_deleted ,COUNT(DISTINCT s.id) ::integer as total_sale,i.id as brandId,s.patient_idFROM pharmacy.t_sale sJOIN pharmacy.t_sale_detail sd on sd.sale_id = s.idJOIN inventory.t_batch b on sd.batch_id = b.idJOIN public.m_item i on i.id = b.item_idJOIN public.m_generic g on g.id = i.generic_idWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE &gt;= '2017-10-17' OR s.added_date::DATE &gt;= '2018-10-17')AND s.is_deleted = false)AND s.is_deleted = falsegroup bys.added_date :: date,s.store_id,i.id,s.patient_id,s.is_deleted ,s.visit_type_id,i.generic_id,g.product_category_id,sd.unit_id,sd.organization_id,s.bill_no,b.batch_no;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_statistics(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_statistics(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, registration_date date, city_id integer, state_id integer, country_id integer, gender_id integer, patient_category_id integer, patient_id integer, age integer, patient_statistics integer, status character)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectpd.unit_id,pd.organization_id,pr.created_date :: date registration_date ,pd.city_id,pd.state_id,pd.country_id,pr.gender_id ,pr.patient_category_id,pr.patient_id,extract (yearfromage(pr.dob)):: integer as age,count(distinct coalesce( pr.patient_id, 0)) :: integer as patient_statistics,pr.statusfrompatient.t_patient_registration prjoin patient.t_patient_details pd onpd.patient_id = pr.patient_idwhere((pr.updated_date::date &gt;= p_dateand pr.updated_date::date &lt; current_date)or (pr.created_date::date &gt;= p_dateand pr.created_date::date &lt; current_date))and pr.registration_type_id = 1group bypr.created_date,pd.unit_id,pd.organization_id,pd.city_id,pd.state_id,pd.country_id,pr.patient_id,pr.patient_category_id,pr.gender_id,pr.status ,age;end;$function$;

-- DROP FUNCTION procedure_old.get_patient_transfer_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_transfer_analysis(p_date date)RETURNS TABLE(from_date date, unit_id integer, organization_id integer, doctor_id integer, speciality_id integer, transfer integer, bedcategorychange integer, count integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT t.from_date :: date,a.unit_id,a.organization_id,a.doctor_id,a.speciality_id, CASE WHEN f_ward.is_icu = 'N' AND t_ward.is_icu = 'N' THEN 1WHEN f_ward.is_icu = 'Y' AND t_ward.is_icu = 'N' THEN 3WHEN f_ward.is_icu = 'N' AND t_ward.is_icu = 'Y' THEN 2END AS Transfer,CASE WHEN frombed.hierarchy_id &gt; tobed.hierarchy_id THEN 1WHEN frombed.hierarchy_id &lt; tobed.hierarchy_id THEN 2WHEN frombed.hierarchy_id = tobed.hierarchy_id THEN 3END as BedCategoryChange,COUNT(DISTINCT a.patient_id):: integer,case when t.status ='A' then falseelse true end as is_deletedfrom "adt".t_transfer tJOIN "adt".t_admission a ON t.admission_id = a.admission_id join "adt".t_admission_details ad ON t.admission_id = ad.admission_id JOIN "adt".m_ward_master f_ward ON t.from_ward_id = f_ward.ward_idJOIN "adt".m_ward_master t_ward ON t.to_ward_id = t_ward.ward_idJOIN (select bcm.hierarchy_id, t.from_bed_category_id, t.admission_id from adt.t_transfer t JOIN adt.m_bed_category_master bcm ON t.from_bed_category_id = bcm.bed_category_id) frombed ON a.admission_id = frombed.admission_id JOIN(select bcm.hierarchy_id, t.to_bed_category_id, t.admission_id from adt.t_transfer t JOIN adt.m_bed_category_master bcm ON t.to_bed_category_id = bcm.bed_category_id) tobed ON tobed.admission_id = a.admission_id WHERE ad.doa IN (SELECT ad.doa FROM "adt".t_admission_details WHERE (t.updated_date :: DATE &gt;= '2018-12-01' OR t.created_date :: DATE &gt;= '2018-12-01 ' AND t.status = 'A')) GROUP BYt.from_date :: date,a.unit_id,a.organization_id,a.doctor_id,a.speciality_id,t.from_ward_id, t.to_ward_id,Transfer,BedCategoryChange,is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_patient_wise_transaction_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_patient_wise_transaction_report(p_date date)RETURNS TABLE(org_unit_id integer, org_id integer, ord_render_datetime date, service_standard_code character varying, service_standard_name character varying, service_group_id integer, ord_doc_id integer, visit_type_id integer, patient_id integer, sum double precision, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT od.org_unit_id,od.org_id,od.ord_render_datetime::date, sm.service_standard_code,sm.service_standard_name,sm.speciality_id as service_group_id,od.ord_doc_id,om.visit_type_id,om.patient_id,sum(od.net_amount):: double precision,sm.statusFROM service.m_service_master smJOIN public.t_order_details od on od.service_id = sm.service_master_idJOIN public.t_order_master om on om.order_id = od.order_idWHERE od.ord_render_datetime::date IN (SELECT od.ord_render_datetime::dateFROM public.t_order_details odWHERE(od.updated_date::DATE&gt;=p_date OR od.created_date::DATE&gt;=p_date)AND od.status = 'A')AND od.status = 'A'GROUP BY od.org_unit_id,od.org_id,od.ord_render_datetime::date, sm.service_standard_code,sm.service_standard_name,sm.speciality_id,od.ord_doc_id,om.visit_type_id,sm.status,om.patient_id;END;$function$;

-- DROP FUNCTION procedure_old.get_pending_prescription_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_pending_prescription_report(p_date date)RETURNS TABLE(destination_store integer, nursing_station_id integer, patient_id integer, bed_id integer, priority_id integer, doctor_id integer, prescription_date date, product_category_id integer, generic_id integer, qty_supplied bigint, qty_prescribed bigint, pending_qty bigint, agening text, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select pd.store_id as destination_store,nsm.nursing_station_id,psm.patient_id ,ad.bed_id,pm.priority_id,psm.doctor_id,pm.prescription_date :: date,g.product_category_id,i.generic_id,sum(psd.quantity) as qty_supplied ,sum(pd.order_qty ) as qty_prescribed,sum(pd.pending_qty) as pending_qty,(now()::date - date(pm.prescription_date)) ||' '|| 'days' :: character varying as agening,pd.unit_id,pd.organization_id as hospital_id ,pm.is_deletedfrom pharmacy.t_sale psm JOIN pharmacy.t_sale_detail psd on psd.sale_id = psm.idJOIN pharmacy.t_prescription_detail pd on pd.id = psd.prescription_detail_idJOIN pharmacy.t_prescription pm on pm.id = pd.prescription_idJOIN public.m_item i on pd.item_id = i.idJOIN public.m_generic g on g.id = i.generic_idJOIN adt.t_admission a on pm.visit_type_id = a.visit_type_id JOIN adt.t_admission_details ad on a.admission_id = ad.admission_idJOIN adt.t_nursing_station_ward_mapper nsm on ad.ward_id = nsm.ward_idWHERE pm.prescription_date IN (SELECT pm.prescription_datefrom pharmacy.t_prescription pmWHERE(pm.updated_date::DATE&gt;=p_date OR pm.added_date::DATE&gt;=p_date)AND pm.is_deleted = false)AND pm.is_deleted = falsegroup by pd.store_id,nsm.nursing_station_id,psm.patient_id ,ad.bed_id,pm.priority_id,psm.doctor_id,pd.item_id,pm.prescription_date,g.product_category_id,i.generic_id,pd.unit_id,pm.is_deleted,pd.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_pending_store_indent_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_pending_store_indent_report(p_date date)RETURNS TABLE(indenting_store integer, destination_store integer, indent_date date, indent_no character varying, priority_id integer, brand_id integer, product_category_id integer, generic_id integer, indent_quantity integer, qty_supplied integer, pending_quantity integer, agening character varying, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select sim.from_store_id as indenting_store,sim.to_store_id as destination_store,sim.added_date :: date as indent_date,sim.indent_no,sim.priority_id,sid.item_id as brand_id,g.product_category_id,im.generic_id,sum(sid.indent_quantity) :: integer as indent_quantity,sum(sid.authorized_quantity):: integer as qty_supplied,sum(sid.pending_quantity) :: integer as pending_quantity,CAST((now()::date - date(sid.added_date)) ||' '|| 'days' as character varying) as agening,sim.unit_id,sim.organization_id as hospital_id ,sim.is_deletedfrom inventory.t_store_indent simJOIN inventory.t_store_indent_detail sid on sim.id = sid.store_indent_idJOIN public.m_item im on sid.item_id = im.idJOIN public.m_generic g on g.id = im.generic_idWHERE sim.added_date IN (SELECT sim.added_datefrom inventory.t_store_indent simWHERE(sim.updated_date::DATE&gt;=p_date OR sim.added_date::DATE&gt;=p_date)AND sim.is_deleted = false)AND sim.is_deleted = falseGROUP BY g.product_category_id,im.generic_id,sim.from_store_id,sim.to_store_id,sim.added_date,sim.indent_no,sim.priority_id,brand_id,sim.is_deleted,sid.added_date :: date ,sim.unit_id,sim.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_product_category__stock(date);
CREATE OR REPLACE FUNCTION procedure_old.get_product_category__stock(p_date date)RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, category character varying, generic_id integer, stock_count integer, is_deleted boolean, total_count integer)LANGUAGE plpgsqlAS $function$ declarebeginSelect ss.added_date::date as stock_date,ss.unit_id,ss.organization_id as hospital_id,ss.store_id,g.product_category_id,p.category,i.generic_id,SUM( ss.available_qty):: integer as stock_count,ss.is_deleted,count(ss.id) as total_count from inventory.t_store_stock ss join inventory.t_batch b on b.id = ss.batch_idcjoin public.m_item i on i.id = b.item_idjoin public.m_generic g on g.id = i.generic_id join public.m_product_category p on p.id = g.product_category_idWHERE ss. added_date IN (SELECT ss.added_dateFROM inventory.t_store_stock ssWHERE(ss.updated_date::DATE&gt;=p_date OR ss.added_date::DATE&gt;=p_date)AND ss.is_deleted = False)AND ss.is_deleted = falseGROUP BY ss.unit_id,ss.organization_id,ss.store_id,g.product_category_id,p.category,i.generic_id,ss.is_deleted,cast(ss.added_date as date)order by cast(ss.added_date as date) asc;end;$function$;

-- DROP FUNCTION procedure_old.get_product_category_sales();
CREATE OR REPLACE FUNCTION procedure_old.get_product_category_sales()RETURNS TABLE(id integer, category character varying, type character varying, sale_type_id integer, unit_id integer, hospital_id integer, sales_count integer, sales_date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ DECLAREBEGINselect p.id,p.category,st."type" ,s.sale_type_id,s.unit_id,s.organization_id as hospital_id,COUNT(DISTINCT sd.quantity):: integer as sales_count,s.added_date :: date as sales_date,s.is_deletedfrom public.m_product_category pjoin public.m_generic g on p.id= g.product_category_idjoin public.m_item i on i.generic_id = g.idjoin inventory.t_batch b on b.item_id = i.idjoin pharmacy.t_sale_detail sd on sd.batch_id = b.id join pharmacy.t_sale s on s.id = sd.sale_id join pharmacy.m_sale_type st on st.id = s.sale_type_idWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;='2019-01-01' OR s.added_date::DATE&gt;='2019-07-12')AND s.is_deleted = FALSE)AND s.is_deleted = FALSEgroup by p.id,p.category ,(cast( s.added_date as date)),st."type",s.sale_type_id,s.unit_id,s.organization_id,s.is_deleted order by p.id asc; END;$function$;

-- DROP FUNCTION procedure_old.get_product_category_sales(date);
CREATE OR REPLACE FUNCTION procedure_old.get_product_category_sales(p_date date)RETURNS TABLE(id integer, category character varying, type character varying, sale_type_id integer, unit_id integer, hospital_id integer, sales_count integer, sales_date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$ DECLAREBEGINselect p.id,p.category,st."type" ,s.sale_type_id,s.unit_id,s.organization_id as hospital_id,COUNT(DISTINCT sd.quantity):: integer as sales_count,s.added_date :: date as sales_date,s.is_deletedfrom public.m_product_category pjoin public.m_generic g on p.id= g.product_category_idjoin public.m_item i on i.generic_id = g.idjoin inventory.t_batch b on b.item_id = i.idjoin pharmacy.t_sale_detail sd on sd.batch_id = b.id join pharmacy.t_sale s on s.id = sd.sale_id join pharmacy.m_sale_type st on st.id = s.sale_type_idWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;=p_date OR s.added_date::DATE&gt;=p_date)AND s.is_deleted = FALSE)AND s.is_deleted = FALSEgroup by p.id ,p.category ,(cast( s.added_date as date)),st."type",s.sale_type_id,s.unit_id,s.organization_id,s.is_deleted order by p.id asc; END;$function$;

-- DROP FUNCTION procedure_old.get_product_category_wise_sales();
CREATE OR REPLACE FUNCTION procedure_old.get_product_category_wise_sales()RETURNS TABLE(id integer, category character, type character, sale_type_id integer, net_amount integer, added_date date)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERY selectp.id, category,st."type",s.sale_type_id,sum(s.net_amount ),(cast( s.added_date as date))from public.m_product_category pjoin public.m_generic g on p.id= g.product_category_idjoin public.m_item i on i.generic_id = g.idjoin inventory.t_batch b on b.item_id = i.idjoin pharmacy.t_sale_detail sd on sd.batch_id = b.id join pharmacy.t_sale s on s.id = sd.sale_id join pharmacy.m_sale_type st on st.id = s.sale_type_idwheresd.added_date between '2019-01-01' and '2019-07-14' group byp.id ,p.category ,(cast( s.added_date as date)),st."type",s.sale_type_id;end;$function$;

-- DROP FUNCTION procedure_old.get_product_category_wise_sales(date);
CREATE OR REPLACE FUNCTION procedure_old.get_product_category_wise_sales(p_date date)RETURNS TABLE(sales_date date, unit_id integer, hospital_id integer, sale_type_id integer, product_category_id integer, sales_count integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select s.added_date :: date as sales_date,s.unit_id,s.organization_id as hospital_id,s.sale_type_id ,g.product_category_id,COUNT(DISTINCT sd.quantity):: integer as sales_count,s.is_deletedfrom pharmacy.t_sale sJOIN pharmacy.t_sale_detail sd on s.id = sd.sale_id JOIN inventory.t_batch b on b.id = sd.batch_idJOIN public.m_item i on i.id = b.item_idJOIN public.m_generic g on g.id = i.generic_idWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;=p_date OR s.added_date::DATE&gt;=p_date)AND s.is_deleted = FALSE)AND s.is_deleted = FALSEGROUP BY s.added_date,s.sale_type_id ,g.product_category_id,s.unit_id,s.is_deleted,s.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_product_category_wise_stock(date);
CREATE OR REPLACE FUNCTION procedure_old.get_product_category_wise_stock(p_date date)RETURNS TABLE(stock_date date, unit_id integer, hospital_id integer, store_id integer, product_category_id integer, stock_count integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select ss.added_date::date as stock_date,ss.unit_id,ss.organization_id as hospital_id,ss.store_id,g.product_category_id, SUM( ss.available_qty):: integer as stock_count,ss.is_deletedFROM inventory.t_store_stock ss JOIN inventory.t_batch b on b.id = ss.batch_idJOIN public.m_item i on i.id = b.item_idJOIN public.m_generic g on g.id = i.generic_id WHERE ss. added_date IN (SELECT ss.added_dateFROM inventory.t_store_stock ssWHERE(ss.updated_date::DATE&gt;=p_date OR ss.added_date::DATE&gt;=p_date)AND ss.is_deleted = False)AND ss.is_deleted = FalseGROUP BY ss.unit_id,ss.organization_id,ss.store_id,g.product_category_id,ss.is_deleted,ss.added_date:: dateORDER BY ss.added_date:: date, unit_id,ss.organization_id,ss.store_id, g.product_category_id;END;$function$;

-- DROP FUNCTION procedure_old.get_profit_margin_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_profit_margin_report(p_date date)RETURNS TABLE(product_category_id integer, generic_id integer, unit_id integer, organization_id integer, brand_id integer, batch_no character varying, vendor_id integer, grn_number character varying, grn_date date, cop double precision, mrp double precision, profit_margin double precision, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT i.product_category_id,i.generic_id, b.unit_id ,b.organization_id ,i.id as brand_id, MAX(b.batch_no):: character varying as batch_no,grc.vendor_id,MAX(grc.grn_number):: character varying grn_number,grc.added_date:: date as grn_date ,MAX(b.cop) as cop,max(b.rate) as mrp,Round((((sum(b.rate) - SUM(b.cop))/SUM(b.cop))*100)::numeric ,2):: double precision as profit_margin,b.is_deletedFROM inventory.t_batch bJOIN public.m_item i on i.id = b.item_id LEFT join procurement.t_good_receipt_note_detail grd on grd.item_id = i.idLEFT JOIN procurement.t_good_receipt_note grc on grc.id = grd.grn_idJOIN pharmacy.t_sale_detail sd on sd.batch_id = b.idJOIN pharmacy.t_sale s on s.id = sd.sale_id WHERE grc.added_date::date IN (SELECT grc.added_date::dateFROM procurement.t_good_receipt_note grcWHERE(grc.updated_date::DATE&gt;=p_date OR grc.added_date::DATE&gt;=p_date)AND grc.is_deleted = false)AND grc.is_deleted = falseGROUP BY i.product_category_id,i.generic_id,brand_id,grc.vendor_id,grc.added_date,b.unit_id,b.organization_id ,b.is_deletedORDER BY grc.added_date;END;$function$;

-- DROP FUNCTION procedure_old.get_records_without_icd(date);
CREATE OR REPLACE FUNCTION procedure_old.get_records_without_icd(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, first_name character varying, last_name character varying, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, data_summary_released text, diagnosis_code character varying)LANGUAGE plpgsqlAS $function$BEGINRETURN QUERYselect distincta.unit_id,a.organization_id,p.patient_id,p.first_name,p.last_name,wm.ward_name,bm.bed_number,a.created_date admission_date,d.discharge_date discharge_date,CASEWHEN tr.discharge_summary_note is null THEN'NO'ELSE'YES'endas data_summary_released,dm.code diagnosis_code from patient.t_patient_registration p INNER JOIN patient.t_patient_diagnosis_appo_mapper pd on p.patient_id=pd.patient_idINNER JOIN emr.m_diagnosis_master dm on pd.diagnosis_id=dm.diagnosis_idINNER JOIN adt.t_admission a on p.patient_id=a.patient_idINNER JOIN adt.t_admission_details ad on a.admission_id=ad.admission_idLEFT JOIN adt.m_ward_master wm ON ad.ward_id = wm.ward_idLEFT JOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_idINNER JOIN adt.t_discharge d on ad.admission_id=d.admission_idINNER JOIN adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_idwhere (a.created_date ::Date &gt;= p_date or a.updated_date:: Date&gt;=p_date ) and dm.code isnull -- comment this line or set as not null to see records, because there are no records with code null.and p.status='A';END;$function$;

-- DROP FUNCTION procedure_old.get_recordswithout_discharge_summary(date);
CREATE OR REPLACE FUNCTION procedure_old.get_recordswithout_discharge_summary(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, first_name character varying, last_name character varying, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, discharge_summary_released text)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERYselecta.unit_id,a.organization_id,p.patient_id, p.first_name,p.last_name,wm.ward_name,bm.bed_number,a.created_date,d.discharge_date,CASEWHEN tr.discharge_summary_note is null THEN'NO'ELSE'YES'endfrom patient.t_patient_registration p join adt.t_admission a on p.patient_id=a.patient_idjoin adt.t_admission_details ad on a.admission_id=ad.admission_idjoin adt.m_ward_master wm ON ad.ward_id = wm.ward_idjoin adt.m_bed_master bm ON ad.bed_id = bm.bed_idjoin adt.t_discharge d on ad.admission_id=d.admission_idjoin adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id and tr.discharge_summary_note isnullwhere (d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date )and a.status='A' and d.discharge_type_id in (1,2,3,4)unionselecta.unit_id,a.organization_id,p.patient_id,p.first_name,p.last_name,wm.ward_name,bm.bed_number,a.created_date,d.discharge_date,CASEWHEN tr.discharge_summary_note is null THEN'NO'ELSE'YES'endfrom patient.t_patient_registration p join adt.t_admission a on p.patient_id=a.patient_idjoin adt.t_admission_details ad on a.admission_id=ad.admission_idjoin adt.m_ward_master wm ON ad.ward_id = wm.ward_idjoin adt.m_bed_master bm ON ad.bed_id = bm.bed_idjoin adt.t_discharge d on ad.admission_id=d.admission_idjoin adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id and tr.discharge_summary_note isnullwhere (d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date )and d.discharge_status_id=5;end;$function$;

-- DROP FUNCTION procedure_old.get_registration_visit_typewise(date);
CREATE OR REPLACE FUNCTION procedure_old.get_registration_visit_typewise(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_id integer, patient_id integer, doctor_id integer, speciality_id integer, diagnosis_id integer, admission_date date, visit_type_id integer, status character)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select a.unit_id ::integer,a.organization_id ::integer,ad.admission_id ::integer,a.patient_id ::integer,a.doctor_id ::integer,a.speciality_id ::integer,ca.diagnosis_id :: integer,ad.doa::date as admission_date,a.visit_type_id :: integer,a.status as statusfrom adt.t_admission ajoin adt.t_admission_details ad ON (a.admission_id = ad.admission_id)join adt.t_complaint_admission ca ON (a.admission_id = ad.admission_id)where ((a.updated_date::date &gt;= p_date ::date and a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::date and a.created_date::date &lt; current_date))group by a.unit_id,a.organization_id,ad.admission_id,a.patient_id,a.doctor_id,a.speciality_id,ca.diagnosis_id,ad.doa,a.visit_type_id,a.status;end;$function$;

-- DROP FUNCTION procedure_old.get_revenue_for_day(date);
CREATE OR REPLACE FUNCTION procedure_old.get_revenue_for_day(p_date date)RETURNS TABLE(unit_id integer, organziation_id integer, bill_date_time date, service_group_id integer, visit_type_id integer, bill_amt double precision, rendered_not_billed_amt double precision, status "char")LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT b.unit_id,b.organization_id,b.bill_date_time::date, b.service_group_id, b.visit_type_id,sum(b.bill_amt) AS bill_amt,SUM(a.net_amount):: double precision AS rendered_not_billed_amt,b.statusFROM (SELECT bm.bill_date_time::date AS bill_date_time, sm.speciality_id as service_group_id, bm.visit_type_id,sum(bm.net_amount) AS bill_amt,bd.unit_id,bd.organization_id,bm.statusFROM billing.m_billing_master bm JOIN billing.t_billing_details bd on bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm on sm.service_master_id = bd.service_idGROUP BY bm.bill_date_time::date, sm.speciality_id ,bm.visit_type_id,bd.unit_id,bm.status,bd.organization_id) bLEFT JOIN (SELECT od.net_amount, od.order_date, sm.speciality_id,om.encounter_id,om.admission_idFROM public.t_order_details odJOIN public.t_order_master om on om.order_id = od.order_idJOIN service.m_service_master sm on sm.service_master_id = od.service_idWHERE od.service_rendered = 1 AND (( om.encounter_id NOT IN (SELECT bm.encounter_id from billing.m_billing_master bm WHERE bm.encounter_id is NOT NULL)) OR(om.admission_id NOT IN (SELECT bm.admission_id from billing.m_billing_master bm WHERE bm.admission_id is NOT NULL)))) aON a.order_date::date = b.bill_date_time::date AND a.speciality_id = b.service_group_idWHERE b.bill_date_time::date IN (SELECT bm.bill_date_time::dateFROM billing.m_billing_master bm WHERE(bm.updated_date::DATE&gt;=p_date OR bm.created_date::DATE&gt;=p_date)AND bm.status = 'A') AND b.status = 'A'GROUP BY b.bill_date_time::date, b.service_group_id ,b.visit_type_id,b.unit_id,b.organization_id,b.statusORDER BY b.bill_date_time::date, b.service_group_id ,b.visit_type_id,b.unit_id,b.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_salesbill(int8);
CREATE OR REPLACE FUNCTION procedure_old.get_salesbill(sales_id bigint)RETURNS TABLE(id bigint, bill_no character varying, added_date timestamp without time zone, total_amount double precision, discount double precision, net_amount double precision, tax_amount double precision, quantity integer, rate double precision, total_amount_details double precision, tax_percentage double precision, tax_amount_detail double precision, discount_amount double precision, net_amount_detail double precision)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select pharmacy.t_sale.id,pharmacy.t_sale.bill_no,pharmacy.t_sale.added_date,pharmacy.t_sale.total_amount,pharmacy.t_sale.discount,pharmacy.t_sale.net_amount,pharmacy.t_sale.tax_amount,pharmacy.t_sale_detail.quantity,pharmacy.t_sale_detail.rate,pharmacy.t_sale_detail.total_amount as total_amount_Details,pharmacy.t_sale_detail.tax_percentage,pharmacy.t_sale_detail.tax_amount as tax_amount_Detail ,pharmacy.t_sale_detail.discount_amount,pharmacy.t_sale_detail.net_amount as net_amount_Detailfrom pharmacy.t_sale inner join pharmacy.t_sale_detail on pharmacy.t_sale.id = pharmacy.t_sale_detail.sale_id where pharmacy.t_sale.id=sales_id and pharmacy.t_sale.is_active=true ;END;$function$;

-- DROP FUNCTION procedure_old.get_scrap_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_scrap_report(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, scrap_date date, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, cop double precision, amount double precision, scrap_reason_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT b.unit_id,b.organization_id,sr.added_date:: date as scrap_date, i.product_category_id, i.generic_id,i.id brand_id,MAX(b.batch_no):: character varying as batch_no , sum(b.cop) cop,sum((b.quantity*b.cop)) amount, sr.scrap_reason_id,b.is_deleted FROM inventory.t_batch bJOIN inventory.t_scrap_request_detail sr on sr.batch_id = b.idJOIN public.m_item i on i.id = b.item_idWHERE sr.added_date:: date IN (SELECT sr.added_date:: dateFROM inventory.t_scrap_request_detail srWHERE(sr.updated_date::DATE&gt;=p_date OR sr.added_date::DATE&gt;=p_date)AND sr.is_deleted = false)AND sr.is_deleted = false AND sr.status_id = 6GROUP BY sr.added_date, i.product_category_id, i.generic_id,brand_id, sr.scrap_reason_id,b.unit_id,b.is_deleted ,b.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_service_validity_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_service_validity_report(p_date date)RETURNS TABLE(organization_id integer, service_group_id integer, service_standard_name character varying, valid_from date, valid_till date, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT sm.organization_id,sm.speciality_id as service_group_id,sm.service_standard_name,sm.valid_from :: DATE ,sm.valid_till :: DATE ,sm.statusFROM service.m_service_master smWHERE sm.created_date IN (SELECT sm.created_dateFROM service.m_service_master smWHERE(sm.updated_date::DATE&gt;=p_date OR sm.created_date::DATE&gt;=p_date)AND sm.status = 'A')AND sm.status = 'A'GROUP BY sm.speciality_id ,sm.service_standard_name,sm.valid_from :: DATE ,sm.valid_till :: DATE ,sm.organization_id,sm.status;END;$function$;

-- DROP FUNCTION procedure_old.get_services_ordered_by_consultant(date);
CREATE OR REPLACE FUNCTION procedure_old.get_services_ordered_by_consultant(p_date date)RETURNS TABLE(order_date date, speciality_id integer, department_id integer, visit_type_id integer, ord_doctor_id integer, service_order_count integer, amount double precision, org_id integer, org_unit_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select od.order_date :: date,sm.speciality_id,sm.sub_speciality_id as department_id, om.visit_type_id ,om.ord_doctor_id,count(DISTINCT sm.service_master_id) :: integer as service_order_count,sum(od.net_amount) :: double precision as amount ,od.org_id, od.org_unit_id,sm.statusFROM service.m_service_master sm JOIN public.t_order_details od on sm.service_master_id = od.service_idJOIN public.t_order_master om on od.order_id = om.order_idWHERE od.order_date IN (SELECT od.order_dateFROM service.m_service_master sm WHERE(sm.updated_date::DATE&gt;=p_date OR sm.created_date::DATE&gt;=p_date)AND sm.status = 'A')AND sm.status = 'A' GROUP BY od.order_date :: date,sm.speciality_id, sm.sub_speciality_id,om.visit_type_id ,om.ord_doctor_id,od.org_id, sm.status,od.org_unit_id;END;$function$;

-- DROP FUNCTION procedure_old.get_services_rendered_to_patient(date);
CREATE OR REPLACE FUNCTION procedure_old.get_services_rendered_to_patient(p_date date)RETURNS TABLE(ord_render_datetime date, org_unit_id integer, hospital_id integer, speciality_id integer, patient_id integer, visit_type_id integer, org_doctor_id integer, service_master_id integer, services_rendered integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT od.ord_render_datetime ::date ,om.org_unit_id,sm.organization_id as hospital_id,sm.speciality_id as service_category_id, om.patient_id,om.visit_type_id,om.ord_doctor_id,sm.service_master_id,count(DISTINCT sm.service_master_id) :: integer as services_rendered,od.statusfrom public.t_order_details od JOIN public.t_order_master om on od.order_id = om.order_idJOIN service.m_service_master sm on sm.service_master_id = od.service_idWHERE od.ord_render_datetime IN (SELECT od.ord_render_datetimeFROM public.t_order_details odWHERE(sm.updated_date::DATE&gt;=p_date OR sm.created_date::DATE&gt;=p_date)AND sm.status = 'A')AND sm.status = 'A'group by od.ord_render_datetime :: date,om.org_unit_id,sm.organization_id,sm.speciality_id,om.patient_id,om.visit_type_id,sm.service_master_id,od.status,om.ord_doctor_id;END;$function$;

-- DROP FUNCTION procedure_old.get_still_birth(date);
CREATE OR REPLACE FUNCTION procedure_old.get_still_birth(p_date date)RETURNS TABLE(discharge_date date, unit_id integer, hospital_id integer, no_of_still_birth integer, mother_admission_id integer, mother_patient_id integer, child_patient_id integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT d.discharge_date :: date, pr.unit_id, pr.organization_id,count(nbd.new_born_id) :: integer no_of_still_birth ,nbd.mother_admission_id ,nbd.mother_id as mother_patient_id,nbd.patient_id as child_patient_id,d.status FROM adt.t_discharge d JOIN adt.t_admission a ON a.admission_id = d.admission_idJOIN "patient".t_patient_registration pr ON pr.patient_id = a.patient_idJOIN patient.t_new_born_details nbd on nbd.patient_id = pr.patient_idWHERE nbd.is_still_birth = 'Y' AND d.discharge_date IN (SELECT d.discharge_date FROM adt.t_discharge d WHERE (d.updated_date :: DATE &gt;= p_date OR d.created_date :: DATE &gt;= p_date AND d.status = 'A')AND d.status = 'A')GROUP BYd.discharge_date :: date , pr.unit_id,pr.organization_id,nbd.mother_admission_id ,child_patient_id,mother_patient_id,d.status; END;$function$;

-- DROP FUNCTION procedure_old.get_stock_adjustment_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_stock_adjustment_report(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, product_category_id integer, item_id integer, generic_id integer, batch_number character varying, expiry_date date, cost_of_product double precision, mrp double precision, quantity_uploaded bigint, value_of_cost_of_product double precision, value_of_mrp double precision, system_stock bigint, system_stock_of_cop double precision, system_stock_of_mrp double precision, difference_in_quantity bigint, difference_of_cop double precision, difference_of_mrp double precision, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select b.unit_id,b.organization_id as hospital_id,g.product_category_id,im.id as item_id,im.generic_id,b.batch_no,b.expiry_date,sum(b.cop) as cop,sum(b.rate) as mrp,sum(usd.qty) as quantity_uploaded,sum((b.cop) * (usd.qty)) as value_of_cost_of_product,sum((b.rate) * (usd.qty)) as value_of_mrp,sum(b.current_quantity) as system_stock,sum((b.cop) * (b.current_quantity)) as system_stock_of_cop,sum((b.rate) * (b.current_quantity)) as system_stock_of_mrp,sum( (b.current_quantity) - (usd.qty) ) as difference_in_quantity,sum(((b.current_quantity) - (usd.qty)) * (b.cop)) as difference_of_cop,sum(((b.current_quantity) - (usd.qty)) * (b.rate)) as difference_of_mrp,b.is_deletedfrom inventory.t_batch b JOIN inventory.t_upload_stock_detail usd on usd.batch_id = b.idJOIN public.m_item im on im.id = b.item_id JOIN public.m_generic g on g.id = im.generic_idWHERE b.added_date IN (SELECT b.added_datefrom inventory.t_batch bWHERE(b.updated_date::DATE&gt;=p_date OR b.added_date::DATE&gt;=p_date)AND b.is_deleted = false)AND b.is_deleted = falsegroup by b.unit_id,b.organization_id,g.product_category_id,im.id,im.generic_id,b.batch_no,b.expiry_date,b.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_stock_ledger_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_stock_ledger_report(p_date date)RETURNS TABLE(hospital_id integer, unit_id integer, store_id integer, generic_id integer, brand_id integer, product_category_id integer, batch_number character varying, expiry_date date, opening_balance bigint, quantity_received bigint, stock_in_transit bigint, sales bigint, quantity_returned bigint, sales_return bigint, stock bigint, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECTss.organization_id as hospital_id,ss.unit_id ,ss.store_id,i.generic_id,i.id as brand_id, g.product_category_id, b.batch_no,b.expiry_date, COALESCE(SUM(ss.available_qty),0) as opening_balance, COALESCE(SUM(grnd.grn_approved_quantity),0) as quantity_received,COALESCE(SUM(ss.t_qty),0) as stock_in_transit,COALESCE(SUM(sd.quantity),0) as sales,COALESCE(SUM(rgd.return_qty),0) as quantity_returned,COALESCE(SUM(rd.return_qty),0) as sales_returns, (COALESCE(SUM(ss.available_qty),0) + COALESCE(SUM(grnd.grn_approved_quantity),0) + COALESCE(SUM(rd.return_qty),0) + COALESCE(SUM(ss.t_qty),0) - COALESCE(SUM(sd.quantity),0) - COALESCE(SUM(rgd.return_qty),0)) stock_available,ss.is_deleted FROM inventory.t_store_stock ssJOIN inventory.t_batch b on b.id = ss.batch_id JOIN public.m_item i on i.id = b.item_idJOIN public.m_generic g on g.id = i.generic_id LEFT JOIN procurement.t_good_receipt_note_detail grnd on grnd.item_id = i.id left JOIN inventory.t_returnable_gatepass_detail rgd on rgd.grn_detail_id = grnd.id JOIN pharmacy.t_sale_detail sd on sd.batch_id = b.id JOIN pharmacy.t_return_detail rd on rd.sale_detail_id = sd.id WHERE ss.added_date IN (SELECT ss.added_dateFROM inventory.t_store_stock ssWHERE(ss.updated_date::DATE &gt;= p_date OR ss.added_date::DATE &gt;= p_date)AND ss.is_deleted = false)AND ss.is_deleted = false group by ss.organization_id,ss.unit_id ,ss.store_id,i.generic_id,i.id, g.product_category_id, b.batch_no,b.expiry_date,ss.is_deleted ; END; $function$;

-- DROP FUNCTION procedure_old.get_stock_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_stock_report(p_date date)RETURNS TABLE(store_id integer, product_category_id integer, generic_id integer, brand_id integer, batch_no character varying, expiry_date date, uom_id integer, quantity integer, poc double precision, mrp double precision, value_poc double precision, value_mrp double precision, unit_id integer, hospital_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY select ss.store_id,g.product_category_id,im.generic_id,im.id as brand_id,MAX(b.batch_no) :: character varying as batch_no ,b.expiry_date,um.id as uom_id ,sum(ss.available_qty):: integer as quantity,sum(b.cop) as poc,sum(b.rate) as mrp,sum((b.quantity*b.cop)) as value_poc, sum((b.quantity*b.rate)) as value_mrp,b.unit_id, b.organization_id as hospital_id,b.is_deletedFROM inventory.t_batch bJOIN inventory.t_store_stock ss on b.id = ss.batch_idJOIN public.m_item im on b.item_id = im.idJOIN public.m_uom_unit um on b.uom_unit_id = um.idJOIN public.m_generic g on g.id = im.generic_idGROUP BY ss.store_id,g.product_category_id ,im.generic_id,brand_id,um.id ,b.expiry_date,b.unit_id, b.organization_id,b.is_deleted;END;$function$;

-- DROP FUNCTION procedure_old.get_stock_transit_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_stock_transit_report(p_date date)RETURNS TABLE(issuing_store integer, receiving_store integer, indent_no character varying, indent_date date, issue_no character varying, issue_date date, brand_id integer, generic_id integer, batch_number character varying, uom_unit_id integer, quantity integer, cop double precision, value_cop double precision, unit_id integer, organisation_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERYselect sim.from_store_id issuing_store, sim.to_store_id receiving_store, MAX(sim.indent_no):: character varying indent_no,sim.added_date :: date indent_date,MAX(mim.issue_no) :: character varying issue_no ,mim.added_date :: date as issue_date ,i.id brand_id,i.generic_id,MAX(bm.batch_no):: character varying batch_number, bm.uom_unit_id ,SUM(ss.t_qty):: integer as quantity ,SUM(bm.cop) as cop,SUM(ss.t_qty*bm.cop) as value_cop,bm.unit_id ,bm.organization_id,mim.is_deletedFROm inventory.t_material_issue mimLEFT JOIN inventory.t_material_issue_detail mid on mid.material_issue_id = mim.idLEFT JOIN inventory.t_material_issue_batch_mapper mibm ON mibm.material_issue_detail_id = mid.idLEFT JOIN inventory.t_store_indent sim on sim.id = mim.store_indent_idjoin inventory.t_batch bm on bm.id = mibm.batch_idJOIN public.m_item i on i.id = bm.item_idJOIN inventory.t_store_stock ss on ss.batch_id = bm.idWHERE mim.added_date IN (SELECT mim.added_date FROM inventory.t_material_issue mimWHERE(mim.updated_date::DATE&gt;=p_date OR mim.added_date::DATE&gt;=p_date)AND mim.is_deleted = false) AND sim.added_date IN (SELECT sim.added_dateFROM inventory.t_store_indent simWHERE(sim.updated_date::DATE&gt;=p_date OR sim.added_date::DATE&gt;=p_date)AND sim.is_deleted = false) AND sim.is_deleted = false AND mim.is_deleted = falsegroup by sim.from_store_id, sim.to_store_id , bm.uom_unit_id ,issue_date ,indent_date,i.generic_id,brand_id,mim.is_deleted,bm.unit_id ,bm.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_tariff_master(date);
CREATE OR REPLACE FUNCTION procedure_old.get_tariff_master(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, service_group_id integer, service_standard_name character varying, patient_type integer, visit_type_id integer, billing_bed_category_id integer, valid_from timestamp without time zone, valid_to timestamp without time zone, tariff double precision, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT tm.unit_id,tm.organization_id,sm.speciality_id as service_group_id,sm.service_standard_name,usm.patient_type_id,usm.visit_type_id,usm.billing_bed_category_id,tm.valid_from,tm.valid_to,usm.rate as tariff,usm.statusFROM service.m_unit_service_tariff_master usm JOIN service.m_tariff_master tm on tm.tariff_id = usm.tariff_idJOIN service.m_service_master sm on sm.service_master_id = usm.service_id JOIN "public".m_patient_category_master pcm on pcm.patient_category_id = usm.patient_type_idWHERE usm.effective_date IN (SELECT usm.effective_dateFROM service.m_unit_service_tariff_master usm WHERE(usm.updated_date::DATE&gt;=p_date OR usm.created_date::DATE&gt;=p_date)AND usm.status = 'A')AND usm.status = 'A'GROUP BY tm.unit_id,tm.organization_id,service_group_id,sm.service_standard_name,patient_type,usm.visit_type_id,usm.patient_type_id,usm.billing_bed_category_id,tm.valid_from,tm.valid_to,usm.status,usm.rate ;END;$function$;

-- DROP FUNCTION procedure_old.get_timeliness_of_appointment(date);
CREATE OR REPLACE FUNCTION procedure_old.get_timeliness_of_appointment(p_date date)RETURNS TABLE(appointment_date date, avg_time_gap bigint, speciality_id integer, doctor_id integer, status character, unit_id integer, hospital_id integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT sm.appointment_date :: date,coalesce(AVG((EXTRACT ( EPOCH from (ed.consultation_start_time)):: bigint)- (EXTRACT( EPOCH from (am.created_date )):: bigint)):: BIGINT ,0) as avg_time_gap ,sm.speciality_id,sm.doctor_id,sm.status,sm.unit_id,sm.organization_id as hospital_idFrom opd.m_slot_master smJOIN opd.m_appointment_master am on sm.slot_id = am.slot_idJOIN opd.t_encounter_master em on em.appointment_id = am.appointment_id JOIN opd.t_encounter_details ed on ed.encounter_id = em.encounter_idWHERE -- sm.appointment_date IN (SELECT sm.appointment_date FROM opd.m_slot_master sm WHERE(sm.updated_date::DATE&gt;='2017-11-10' OR sm.created_date::DATE&gt;='2017-11-10') AND sm.status = 'A') AND sm.status = 'A'(sm.updated_date::DATE&gt;=p_date OR sm.created_date::DATE&gt;=p_date) AND sm.status = 'A'GROUP BY sm.appointment_date :: date,sm.speciality_id,sm.doctor_id,sm.status,sm.unit_id,sm.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_transaction_code_wise_report(date);
CREATE OR REPLACE FUNCTION procedure_old.get_transaction_code_wise_report(p_date date)RETURNS TABLE(bill_date_time date, service_group_id integer, service_standard_code character varying, service_standard_name character varying, visit_type_id integer, doctor_id integer, speciality_id integer, patient_id integer, sum double precision, status "char", unit_id integer, hospital_id integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY Select bm.bill_date_time::date, sm.speciality_id as service_group_id, sm.service_standard_code, sm.service_standard_name,bm.visit_type_id, em.doctor_id,d.speciality_id,bm.patient_id,sum(bm.net_amount),bm.status,bm.unit_id,bm.organisation_id as hospital_idfrom billing.m_billing_master bm JOIN billing.t_billing_details bd on bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master sm on sm.service_master_id = bd.service_idLEFT JOIN opd.t_encounter_master em on bm.encounter_id = em.encounter_id AND bm.visit_type_id = 1 LEFT JOIN doctor.t_doctor_speciality_mapper d on d.doctor_id = em.doctor_idWHERE bm.visit_type_id is NOT NULL AND bm.bill_date_time::date IN (SELECT bm.bill_date_time::datefrom billing.m_billing_master bm WHERE (bm.updated_date::DATE&gt;=p_date OR bm.created_date::DATE&gt;=p_date)AND bm.status = 'A') AND bm.status = 'A'GROUP BY sm.speciality_id,sm.service_standard_code,sm.service_standard_name,bm.visit_type_id,em.doctor_id,d.speciality_id,bm.patient_id,bm.bill_date_time::date,bm.status,bm.unit_id,bm.organisation_idORDER BY bm.bill_date_time::date;END;$function$;

-- DROP FUNCTION procedure_old.get_user_get_top10_issues();
CREATE OR REPLACE FUNCTION procedure_old.get_user_get_top10_issues()RETURNS TABLE(issue_id integer, user_id integer, user_name character varying, user_count integer, quantity integer, unit_id integer, hospital_id integer, build_date date, store_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginselect iss.id,iss.added_by as user_id, u.user_name,count(u.user_name):: integer User_count,s.organization_id as hospital_id,s.unit_id,s.store_id ,sum( sd.quantity ) as quantity,sl.added_date:: date as build_datefrom public.m_user_master u join pharmacy.t_issue iss on iss.added_by = u.user_idjoin public.m_store s on s.store_id = iss.store_idjoin pharmacy.t_sale sl on sl.store_id = s.store_idjoin pharmacy.t_sale_detail sd on sd.sale_id = sl.idWHERE sl.added_date IN (SELECT sl.added_dateFROM pharmacy.t_sale slWHERE(sl.updated_date::DATE&gt;='2019-01-01' OR sl.added_date::DATE&gt;='2019-07-12')AND sl.is_deleted = FALSE)AND sl.is_deleted = FALSEGROUP BY iss.id,s.organization_id,u.user_name,s.unit_id,iss.added_by,s.store_id,date(sl.added_date),quantityORDER BY quantity desc limit 10 ;END;$function$;

-- DROP FUNCTION procedure_old.get_user_getby_issues(date);
CREATE OR REPLACE FUNCTION procedure_old.get_user_getby_issues(p_date date)RETURNS TABLE(issue_id integer, user_id integer, user_count integer, quantity integer, unit_id integer, hospital_id integer, build_date timestamp without time zone, store_id integer, no_of_bills integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginreturn query Select iss.id :: integer as issue_id,iss.added_by as user_id, count(u.user_name):: integer User_count,sd.quantity,s.organization_id as hospital_id,s.unit_id,s.store_id ,s.added_date:: date as build_datefrom pharmacy.t_issue iss join public.m_user_master u on u.user_id = iss.added_byjoin public.m_store s on s.store_id = iss.store_idjoin pharmacy.t_sale sl on sl.store_id = s.store_idjoin pharmacy.t_sale_detail sd on sd.sale_id = sl.idWHERE sl.added_date IN (SELECT sl.added_dateFROM pharmacy.t_sale slWHERE(sl.updated_date::DATE&gt;=p_date OR sl.added_date::DATE&gt;=p_date)AND sl.is_deleted = FALSE)AND sl.is_deleted = FALSEGROUP BY issue_id,iss.organization_id,iss.unit_id,iss.added_by,s.store_id,date(sl.added_date),sd.quantity;END;$function$;

-- DROP FUNCTION procedure_old.get_user_getby_issues();
CREATE OR REPLACE FUNCTION procedure_old.get_user_getby_issues()RETURNS TABLE(issue_id integer, user_name character varying, unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginSelect iss.id :: integer as issue_id,s.added_by as user_id, count(u.user_name):: integer User_count,sd.quantity,s.organization_id as hospital_id,s.unit_id,s.store_id ,s.added_date:: date as build_datefrom pharmacy.t_issue iss join public.m_user_master u on u.user_id = iss.added_byjoin public.m_store s on s.store_id = iss.store_idjoin pharmacy.t_sale sl on sl.store_id = s.store_idjoin pharmacy.t_sale_detail sd on sd.sale_id = sl.idWHERE sl.added_date IN (SELECT sl.added_dateFROM pharmacy.t_sale slWHERE(sl.updated_date::DATE&gt;='2019-01-01' OR sl.added_date::DATE&gt;='2019-07-12')AND sl.is_deleted = FALSE)AND sl.is_deleted = FALSEGROUP BY issue_id,iss.organization_id,iss.unit_id,iss.added_by,s.store_id,date(sl.added_date),sd.quantityorder by iss.id asc;END;$function$;

-- DROP FUNCTION procedure_old.get_user_wise_issues();
CREATE OR REPLACE FUNCTION procedure_old.get_user_wise_issues()RETURNS TABLE(unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginSelect s.unit_id,s.organization_id as hospital_id,s.added_date:: date as build_date,s.added_by as user_id, s.store_id ,COUNT(DISTINCT s.id) :: integer as no_of_bills,s.is_deleted from pharmacy.t_sale sWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;='2019-01-01' OR s.added_date::DATE&gt;='2019-07-12')AND s.is_deleted = FALSE)AND s.is_deleted = FALSEGROUP BY s.added_date,user_id, s.store_id ,s.unit_id,s.is_deleted ,s.organization_idORDER BY CAST(s.added_date AS DATE),user_id, s.store_id,s.unit_id,s.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_user_wise_issues(date);
CREATE OR REPLACE FUNCTION procedure_old.get_user_wise_issues(p_date date)RETURNS TABLE(unit_id integer, hospital_id integer, build_date date, user_id integer, store_id integer, no_of_bills integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$ declarebeginSelect s.unit_id,s.organization_id as hospital_id,s.added_date:: date as build_date,s.added_by as user_id, s.store_id ,COUNT(DISTINCT s.id) :: integer as no_of_bills,s.is_deleted from pharmacy.t_sale sWHERE s.added_date IN (SELECT s.added_dateFROM pharmacy.t_sale sWHERE(s.updated_date::DATE&gt;=p_date OR s.added_date::DATE&gt;=p_date)AND s.is_deleted = FALSE)AND s.is_deleted = FALSEGROUP BY s.added_date,user_id, s.store_id ,s.unit_id,s.is_deleted ,s.organization_idORDER BY CAST(s.added_date AS DATE),user_id, s.store_id,s.unit_id,s.organization_id;END;$function$;

-- DROP FUNCTION procedure_old.get_visit_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.get_visit_analysis(p_date date)RETURNS TABLE(visist_date date, doctor_id integer, speciality_id integer, unit_id integer, organization_id integer, visit_type_id integer, no_of_patient_visited integer, status character)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT visit_date ,a.doctor_id,a.speciality_id,a.unit_id,a.organization_id,a.visit_type_id,COUNT(a.no_of_patient_visited) :: integer as no_of_patient_visited,a.statusFROM(SELECT em.encounter_date :: date as visit_date,em.doctor_id, em.dept_id as speciality_id,em.unit_id,1 as visit_type_id,em.organization_id,COUNT(COALESCE(em.patient_id,0)):: integer AS no_of_patient_visited,em.status FROM opd.t_encounter_master emWHERE em.encounter_date IN (SELECT em.encounter_dateFROM opd.t_encounter_master emWHERE (em.updated_date::DATE&gt;=p_date OR em.created_date::DATE&gt;=p_date)AND em.status = 'A') GROUP BY em.encounter_date :: date ,em.doctor_id, em.dept_id,em.unit_id,em.organization_id,em.statusUNION ALLSELECT ad.doa :: date as visit_date,am.doctor_id, am.speciality_id,am.unit_id,am.organization_id,am.visit_type_id, COUNT(COALESCE(am.patient_id,0))::integer AS no_of_patient_visited,am.status FROM "adt".t_admission aminner join adt.t_admission_details ad on am.admission_id = ad.admission_idWHERE am.visit_type_id != 1 AND NOT NULL AND ad.doa IN (SELECT a.doa FROM "adt".t_admission_details aWHERE (a.updated_date::DATE&gt;=p_date OR a.created_date::DATE&gt;=p_date )AND a.status = 'A')GROUP BY am.doctor_id,am.speciality_id,am.unit_id,am.visit_type_id,am.organization_id,ad.doa :: date ,am.status)aGROUP BY visit_date ,a.doctor_id,a.speciality_id,a.unit_id,a.status,a.organization_id,a.visit_type_id;END;$function$;

-- DROP FUNCTION procedure_old.mis_get_discharge_analysis(date);
CREATE OR REPLACE FUNCTION procedure_old.mis_get_discharge_analysis(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_category_id integer, bed_id integer, speciality_id integer, doctor_id integer, patient_id integer, marked_discharge boolean, ready_billing boolean, ready_discharge boolean, discharge_date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id,d.organization_id,ad.bed_category_id,ad.bed_id,a.speciality_id,d.doctor_id,a.patient_id,casewhen d.discharge_status_id = 1 then trueelse falseend as marked_discharge,casewhen d.discharge_status_id = 2 then trueelse falseend as ready_billing,casewhen d.discharge_status_id = 3 then trueelse falseend as ready_discharge,cast(d.updated_date as date) as discharge_date,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_admission ajoin adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)where((d.updated_date::date &gt;= p_date ::dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::dateand d.created_date::date &lt; current_date));
end;$function$;

-- DROP FUNCTION procedure_old.mis_get_planned_discharge(date);
CREATE OR REPLACE FUNCTION procedure_old.mis_get_planned_discharge(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, bed_catgeory_id integer, bed_id integer, speciality_id integer, doctor_id integer, patient_id integer, planned_discharge_date date, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id,d.organization_id,ad.bed_category_id as bed_catgeory_id,ad.bed_id,a.speciality_id,d.doctor_id,a.patient_id,ad.pdd::date as planned_discharge_date,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_admission ajoin adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)where((d.updated_date::date &gt;= p_date ::dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::dateand d.created_date::date &lt; current_date));
end;$function$;

-- DROP FUNCTION procedure_old.mis_get_visit_type_admission(date);
CREATE OR REPLACE FUNCTION procedure_old.mis_get_visit_type_admission(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, admission_date date, diagnosis_id integer, advance_amount_paid double precision, doctor_id integer, patient_id integer, bed_id integer, planned_discharge_date date, payment_entitlement_id integer, visit_type_id integer, speciality_id integer, is_deleted boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selectd.unit_id,d.organization_id,ad.doa::date,cad.diagnosis_id,dm.deposit_amount,d.doctor_id,a.patient_id,ad.bed_id,ad.pdd::date,apm.payment_entitlement_id,a.visit_type_id,a.speciality_id,casewhen a.status ilike 'A' then falseelse trueend as is_deletedfromadt.t_admission ajoin adt.t_complaint_admission cadusing(admission_id)join billing.m_deposit_master dmusing (admission_id)join adt.t_discharge dusing (admission_id)join adt.t_admission_details adusing (admission_id)join adt.t_admission_patient_mapping apm on(a.patient_id = apm.admission_patient_id)where((d.updated_date::date &gt;= p_date ::dateand d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::dateand d.created_date::date &lt; current_date));
end;$function$;

-- DROP FUNCTION procedure_old.per_med_rec_not_having_dis_summary();
CREATE OR REPLACE FUNCTION procedure_old.per_med_rec_not_having_dis_summary()RETURNS TABLE(unit_id integer, organization_id integer, no_of_discharges integer, no_of_dis_without_summ integer)LANGUAGE plpgsqlAS $function$beginreturn QUERY with tab1 as (select count(*)nodwodsum,dis.organization_id,dis.unit_idfrom t_discharge dis inner join t_admission ad using (admission_id)where ad.status = 'A'and dis.admission_id not in (select admission_id from m_discharge_summary)and dis.discharge_type_id in (select discharge_type_id from m_reason_for_discharge_master where discharge_type_code in('Normal','DAMA','Death','LAMA'))group by dis.organization_id,dis.unit_id),tab2 as(select count(*) nod,organization_id,unit_id from t_dischargewhere discharge_type_id in (select discharge_type_id from m_reason_for_discharge_master where discharge_type_code in('Normal','DAMA','Death','LAMA'))group by organization_id,unit_id)select tab1.nodwodsum, tab2.nod, tab1.organization_id,tab1.unit_idfrom tab1, tab2where tab1.organization_id =tab2.organization_idand tab1.unit_id = tab2.unit_id;end;$function$;

-- DROP FUNCTION procedure_old.qi_get_avg_length_stay(date);
CREATE OR REPLACE FUNCTION procedure_old.qi_get_avg_length_stay(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, speciality_id integer, doctor_id integer, diagnosis_id integer, inpatient_days integer, total_discharge integer)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERYselect s.unit_id , s.organization_id,s.patient_id, s.speciality_id , s.doctor_id, s.diagnosis_id,SUM(CASE WHEN diff&lt;=12 THEN 0.5 ELSE (diff/24) + (CASE WHEN diff%24 = 0 THEN 0 ELSE 1 END ) END) :: integer as inpatient_days,COUNT(distinct s.discharge_id):: INTEGER as total_discharge from(SELECT a.unit_id , a.organization_id,p.patient_id, a.speciality_id , d.doctor_id, ca.diagnosis_id ,d.discharge_id,extract(epoch from d.discharge_date - ad.doa)::integer/3600 as diffFROM adt.t_discharge dJOIN adt.t_admission a on d.admission_id = a.admission_id AND a.visit_type_id IN (2)JOIN adt.t_admission_details ad on d.admission_id = ad.admission_id JOIN adt.t_complaint_admission ca on ad.admission_id = ca.admission_idjoin patient.t_patient_registration p using (patient_id)where -- d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date a.status = 'A'GROUP BY a.unit_id ,p.patient_id,a.organization_id,a.speciality_id ,d.discharge_date,d.doctor_id,ca.diagnosis_id,ad.doa,d.discharge_id)s group by s.unit_id , s.organization_id,s.patient_id, s.speciality_id , s.doctor_id, s.diagnosis_id,s.discharge_id;end;$function$;

-- DROP FUNCTION procedure_old.qi_get_bed_occupancy(date);
CREATE OR REPLACE FUNCTION procedure_old.qi_get_bed_occupancy(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, inpatient_days integer, bed_category_id integer, available_beds integer)LANGUAGE plpgsqlAS $function$ declarebeginreturn QUERYselect s.unit_id,s.organization_id,s.patient_id,s.patient_age,SUM(CASE WHEN diff&lt;=12 THEN 0.5 ELSE (diff/24) + (CASE WHEN diff%24 = 0 THEN 0 ELSE 1 END ) END) :: integer as inpatient_days,b.bed_category_id,b.available_bedsfrom(SELECT a.unit_id , a.organization_id,p.patient_id,a.admission_id,extract(yearfromage(p.dob))::integer as patient_age,extract(epoch from d.discharge_date - ad.doa)::integer/3600 as diffFROM adt.t_discharge dJOIN adt.t_admission a on d.admission_id = a.admission_id AND a.visit_type_id IN (2)JOIN adt.t_admission_details ad on d.admission_id = ad.admission_id join patient.t_patient_registration p using (patient_id)where d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date and a.status = 'A'GROUP BY a.unit_id ,p.patient_id,a.organization_id,ad.doa,a.admission_id,d.discharge_date)s join(SELECT bm.bed_category_id,bed_status_id,a.admission_id,count(distinct bm.bed_id) available_beds from adt.t_admission a JOIN adt.t_admission_details ad on a.admission_id = ad.admission_id join adt.m_bed_master bm on ad.bed_id=bm.bed_id and (bed_status_id=6 or bed_status_id=3)where d.updated_date::DATE&gt;=p_date OR d.created_date::DATE&gt;=p_date and a.status = 'A'GROUP BY bm.bed_category_id,bed_status_id,a.admission_id)bon s.admission_id=b.admission_idgroup by s.unit_id , s.organization_id,s.patient_age,s.patient_id,b.bed_category_id,b.available_beds;end;$function$;

-- DROP FUNCTION procedure_old.qi_get_er_72hrs_with_same_complaint(date);
CREATE OR REPLACE FUNCTION procedure_old.qi_get_er_72hrs_with_same_complaint(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, diagnosis_id integer, is_return boolean)LANGUAGE plpgsqlAS $function$beginreturn QUERY selecta.unit_id,a.organization_id,a.patient_id,extract(yearfromage(pr.dob))::integer as patient_age,cad.diagnosis_id,truefromadt.t_admission ajoin adt.t_admission_details adusing(admission_id)join adt.t_complaint_admission cadusing(admission_id)join patient.t_patient_registration prusing (patient_id)where((a.updated_date::date &gt;= p_date ::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))and a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')and exists (select 1fromadt.t_admission pajoin adt.t_complaint_admission pcadusing (admission_id)join adt.t_admission_details padmusing (admission_id)join adt.t_discharge dusing (admission_id)wherepa.patient_id = a.patient_idand a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')and pcad.icpc_system_id = cad.icpc_system_idand padm.is_discharge = 'D'and padm.doa &gt;= (ad.doa - ('72 hours')::interval)and ad.admission_id != padm.admission_id)group bya.patient_id,a.unit_id,a.organization_id,patient_age,cad.diagnosis_idunion selecta.unit_id,a.organization_id,a.patient_id,extract(yearfromage(pr.dob))::integer as patient_age,cad.diagnosis_id,falsefromadt.t_admission ajoin adt.t_admission_details adusing(admission_id)join adt.t_complaint_admission cadusing(admission_id)join patient.t_patient_registration prusing (patient_id)where((a.updated_date::date &gt;= p_date ::dateand a.updated_date::date &lt; current_date)or (a.created_date::date &gt;= p_date::dateand a.created_date::date &lt; current_date))and a.visit_type_id in (select visit_type_idfromm_visit_type_masterwherevisit_type_code = 'ER')group bya.patient_id,a.unit_id,a.organization_id,patient_age,cad.diagnosis_id;end;$function$;

-- DROP FUNCTION procedure_old.qi_get_mortality_rate(date);
CREATE OR REPLACE FUNCTION procedure_old.qi_get_mortality_rate(p_date date)RETURNS TABLE(unit_id integer, organization_id integer, patient_id integer, patient_age integer, gender_id integer, is_dead boolean, diagnosis_id integer)LANGUAGE plpgsqlAS $function$ beginreturn QUERY select pr.unit_id, pr.organization_id, pr.patient_id,extract(year from age(pr.dob))::integer as patient_age,pr.gender_id,case d.discharge_type_id when 3 then true else false end as is_dead,cad.diagnosis_idfrom patient.t_patient_registration prjoin adt.t_admission a using (patient_id)join adt.t_discharge d using (admission_id)join adt.t_complaint_admission cad using (admission_id)where ((d.updated_date::date &gt;= p_date ::date and d.updated_date::date &lt; current_date)or (d.created_date::date &gt;= p_date::date and d.created_date::date &lt; current_date)) group by pr.unit_id,pr.organization_id,pr.patient_id,is_dead,cad.diagnosis_id;end;$function$;

