CREATE UNIQUE INDEX t_work_order_quotation_request_id_idx ON procurement.t_work_order_quotation_request USING btree (id);
-- procurement.t_work_order_quotation_request_detail definition-- Drop table-- DROP TABLE procurement.t_work_order_quotation_request_detail;
CREATE TABLE procurement.t_work_order_quotation_request_detail (id serial4 NOT NULL,organization_id int4 NOT NULL,unit_id int4 NOT NULL,work_order_quotation_request_id int4 NOT NULL,work_order_detail_id int4 NULL,current_vendor_id int4 NULL,specification varchar(100) NULL,status_id int4 NULL,is_active bool DEFAULT true NOT NULL,updated_by int4 NOT NULL,updated_date timestamp DEFAULT now()::timestamp(0) without time zone NOT NULL,added_by int4 NOT NULL,added_date timestamp DEFAULT now()::timestamp(0) without time zone NOT NULL,is_deleted bool DEFAULT false NOT NULL,quantity int4 NULL,remark varchar(100) NULL,expected_inclusion text NULL,item_id int4 NULL,batch_id int4 NULL);
