CREATE TABLE procurement.t_good_receipt_note_detail_log (id serial4 NOT NULL,organization_id int4 NOT NULL,unit_id int4 NOT NULL,grn_id int4 NOT NULL,item_id int4 NOT NULL,grn_approved_quantity int4 NULL,grn_received_quantity int4 NULL,grn_uom_type_id int4 NULL,grn_uom_unit_id int4 NULL,bonus_approved_quantity int4 NULL,bonus_received_quantity int4 NULL,bonus_uom_type_id int4 NULL,bonus_uom_unit_id int4 NULL,lot_number varchar(100) NULL,batch_no varchar(100) NULL,expiry_date date NULL,cop float8 NOT NULL,mrp float8 NOT NULL,discount float8 NULL,tax_id int4 NOT NULL,tax_percentage float8 NOT NULL,tax_amount float8 NOT NULL,total_amount float8 NOT NULL,total_discount float8 NULL,total_other_amount float8 DEFAULT 0 NULL,net_amount float8 NOT NULL,manufacturer_id int4 NULL,specification varchar(100) NULL,remark varchar(100) NULL,status_id int4 NOT NULL,is_active bool DEFAULT true NULL,updated_by int4 NULL,updated_date timestamp DEFAULT now()::timestamp(0) without time zone NOT NULL,added_by int4 NULL,added_date timestamp DEFAULT now()::timestamp(0) without time zone NOT NULL,is_deleted bool DEFAULT false NULL,rejected_quantity int4 NULL,reject_reason_id int4 NULL,reject_note varchar(100) NULL,approved_by int4 NULL,approved_date timestamp NULL,batch_id int4 NULL,model_number varchar(50) NULL,uom_type_id int4 NULL,uom_unit_id int4 NULL,warrenty_period text NULL,support_term text NULL,technical_specification text NULL,service_provider_id int4 NULL,expected_payment_terms text NULL,manufacture_year int4 NULL,warrenty_date date NULL,grn_lease_quantity int4 NULL,bonus_lease_quantity int4 NULL,po_detail_id int4 NULL,consignment_po_detail_id int4 NULL,po_details_id int4 NULL,credit_note_amount float8 NULL,lcop float8 NULL,warrenty_date_to date NULL,pending_quantity int4 NULL,round_off_amount float8 NULL,total_net_amount float8 NULL,grn_detail_id int4 NOT NULL,CONSTRAINT t_good_receipt_note_detail_log_pk PRIMARY KEY (id));
-- procurement.t_good_receipt_note_detail_log foreign keysALTER TABLE procurement.t_good_receipt_note_detail_log ADD CONSTRAINT t_good_receipt_note_detail_id_fkey FOREIGN KEY (item_id) REFERENCES public.m_item(id);
-- procurement.get_physical_inspection_details source
CREATE OR REPLACE VIEW procurement.get_physical_inspection_detailsAS SELECT phi.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.inward_number,grn.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,grnd.batch_no,grnd.cop,grnd.mrp,grnd.discount,grnd.tax_percentage,grnd.tax_amount,grnd.total_discount,grnd.total_other_amount AS total_other_amount_detail,grnd.net_amount,m_store.store_id,grn.total_tax_ammount,grn.total_other_amount,grnd.grn_approved_quantity,grnd.grn_received_quantity,u.unit_name,u.unit_address,u.unit_address_2,u.unit_website,s.status,um.user_name AS added_by,u.imageFROM procurement.t_physical_inspection phiJOIN procurement.t_physical_inspection_detail phid ON phi.id = phid.physical_inspection_idJOIN procurement.t_good_receipt_note grn ON phi.grn_id = grn.idJOIN procurement.t_good_receipt_note_detail grnd ON phid.grn_detail_id = grnd.id AND grnd.is_deleted &lt;&gt; trueLEFT JOIN m_vendor ON m_vendor.id = grn.vendor_idLEFT JOIN inventory.t_batch tb ON grnd.batch_id = tb.idLEFT JOIN m_item ON tb.item_id = m_item.idJOIN m_store ON grn.store_id = m_store.store_idLEFT JOIN m_unit_master u ON grn.unit_id = u.unit_idLEFT JOIN m_status s ON phi.status_id = s.idLEFT JOIN m_user_master um ON phi.added_by = um.user_idWHERE phid.is_active = true;

-- procurement.get_requestwasteassetdisposal source
CREATE OR REPLACE VIEW procurement.get_requestwasteassetdisposalAS SELECT wdw.id,sr.request_no,sr.id AS reqid,sr.added_date,m_store.store_name,assettype.type AS assettype,um.user_name,umw.user_name AS witness,m_status.status,m_item.code,m_item.name AS itemname,m_generic.name AS genericname,uomtype.type AS uomtype,uomunit.unit AS uomunit,batch.batch_no,batch.expiry_date,srd.scrap_quantity,unit.unit_name,unit.unit_address,unit.imageFROM inventory.t_waste_asset_disposal_worklist wdwJOIN inventory.t_waste_asset_disposal_worklist_detail wdwd ON wdw.id = wdwd.waste_asset_disposal_worklist_idLEFT JOIN inventory.t_asset_disposal_worklist_request dwr ON wdw.asset_disposal_worklist_request_id = dwr.idLEFT JOIN inventory.t_scrap_request sr ON dwr.scrap_request_id = sr.idLEFT JOIN inventory.t_scrap_request_detail srd ON sr.id = srd.scrap_request_idLEFT JOIN m_user_master umw ON dwr.witness_id = umw.user_idLEFT JOIN m_store ON sr.store_id = m_store.store_idLEFT JOIN m_asset_type assettype ON sr.asset_type_id = assettype.idLEFT JOIN m_user_master um ON sr.added_by = um.user_idLEFT JOIN m_status ON wdw.status_id = m_status.idLEFT JOIN inventory.t_batch batch ON srd.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON srd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON srd.uom_unit_id = uomunit.idLEFT JOIN m_scrap_reason reason ON srd.scrap_reason_id = reason.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idJOIN m_unit_master unit ON sr.unit_id = unit.unit_idWHERE wdwd.is_active = true;

-- procurement.get_workordercreationdetails source
CREATE OR REPLACE VIEW procurement.get_workordercreationdetailsAS SELECT woc.id,woc.work_order_no,item.name AS itemname,tax.name AS tax_per,wocd.wo_quantity,wocd.qo_bonus_quantity,wocd.amount,wocd.discount_percentage,wocd.discount_amount,wocd.tax_percentage,wocd.tax_amount,wocd.total_amount,wocd.net_amount,s.store_name,v.name AS vendorname,rt.type,woc.remark,status1.status,status2.status AS approvaer_status,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS addedusername,(((em2.first_name::text || ' '::text) || em2.middle_name::text) || ' '::text) || em2.last_name::text AS updatedusername,ct.code,u.unit_name,u.unit_address,u.unit_contact,woc.added_date::date AS addeddate,u.imageFROM procurement.t_work_order_creation wocJOIN procurement.t_work_order_creation_detail wocd ON woc.id = wocd.wo_creation_idJOIN m_store s ON woc.store_id = s.store_idJOIN m_vendor v ON woc.vendor_id = v.idJOIN m_request_type rt ON woc.request_type_id = rt.idJOIN m_status status1 ON woc.status_id = status1.idJOIN m_status status2 ON woc.approval_status_id = status2.idLEFT JOIN m_employee_master em1 ON woc.added_by = em1.user_idLEFT JOIN m_employee_master em2 ON woc.updated_by = em2.user_idJOIN procurement.m_contract_type ct ON woc.contract_type_id = ct.idLEFT JOIN inventory.t_batch tb ON wocd.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_tax tax ON wocd.tax_id = tax.idLEFT JOIN m_unit_master u ON woc.unit_id = u.unit_idWHERE wocd.is_active = true;

-- procurement.get_workordercreationdetails_new source
CREATE OR REPLACE VIEW procurement.get_workordercreationdetails_newAS SELECT woc.workorder_request_id AS id,woc.workorder_request_number AS work_order_no,wocd.item_name::character varying(500) AS itemname,tax.tax_percentage AS tax_per,wocd.item_quantity AS wo_quantity,wocd.item_net_amount AS amount,wocd.item_disc_percentage AS discount_percentage,wocd.item_disc_amount AS discount_amount,wocd.item_tax_amount AS tax_amount,wocd.item_net_amount AS total_amount,wocd.item_net_amount AS net_amount,s.store_name,v.name AS vendorname,rt.type,wocd.item_remark AS remark,status1.status,status2.status AS approvaer_status,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS addedusername,(((em2.first_name::text || ' '::text) || em2.middle_name::text) || ' '::text) || em2.last_name::text AS updatedusername,ct.code,u.unit_name,u.unit_address,u.unit_contact,woc.workorder_request_date AS addeddate,CASEWHEN woc.bill_type_id = 1 THEN 'Cash'::textWHEN woc.bill_type_id = 2 THEN 'Credit'::textELSE NULL::textEND AS bill_type,wocd.item_rate,wocd.item_mrp,wocd.item_disc_amount,wocd.item_tax,wocd.item_tax_amount,wocd.item_name,woc.delivery_date,u.image,wocd.item_remark,woc.payment_terms::text AS payment_terms,woc.guarantee_warranty,woc.payment_terms AS paymentterms,wocd.workorder_request_details_idFROM procurement.t_new_work_order_creation wocJOIN procurement.t_new_work_order_creation_details wocd ON woc.workorder_request_id = wocd.workorder_request_idJOIN m_store s ON woc.store_id = s.store_idJOIN m_vendor v ON woc.vendor_id = v.idJOIN m_request_type rt ON woc.against_type_id = rt.idJOIN m_status status1 ON woc.workorder_request_status_id = status1.idJOIN m_status status2 ON woc.workorder_approval_status_id = status2.idLEFT JOIN m_employee_master em1 ON woc.created_by = em1.user_idLEFT JOIN m_employee_master em2 ON woc.updated_by = em2.user_idJOIN procurement.m_contract_type ct ON woc.contract_type_id = ct.idLEFT JOIN m_item item ON wocd.item_id = item.idLEFT JOIN m_tax tax ON wocd.item_tax_id = tax.idLEFT JOIN m_unit_master u ON woc.unit_id = u.unit_idWHERE wocd.status = 'A'::bpcharORDER BY wocd.workorder_request_details_id;

-- procurement.get_workorderquotationselection source
CREATE OR REPLACE VIEW procurement.get_workorderquotationselectionAS SELECT qs.id,qr.id AS qrid,qr.work_order_quotation_request_no,qr.added_date,m_store.store_name,contracttype.description AS contracttype,reqtype.type AS reqtype,um.user_name,m_status.status,m_item.code,m_item.name AS itemname,qrd.quantity,m_vendor.name AS vendorname,unit.unit_name,unit.unit_address,unit.imageFROM procurement.t_wo_quotation_selection qsJOIN procurement.t_wo_quotation_selection_detail qsd ON qs.id = qsd.quotation_selection_idLEFT JOIN procurement.t_work_order_quotation_request qr ON qs.quotation_request_id = qr.idLEFT JOIN procurement.t_work_order_quotation_request_detail qrd ON qr.id = qrd.work_order_quotation_request_idLEFT JOIN m_item ON qrd.item_id = m_item.idLEFT JOIN inventory.t_batch batch ON qrd.batch_id = batch.idLEFT JOIN m_store ON qr.store_id = m_store.store_idLEFT JOIN procurement.m_contract_type contracttype ON qr.contract_type_id = contracttype.idLEFT JOIN m_request_type reqtype ON qr.request_type_id = reqtype.idLEFT JOIN m_user_master um ON qr.added_by = um.user_idLEFT JOIN m_status ON qs.status_id = m_status.idLEFT JOIN procurement.t_work_order wo ON wo.id = qr.work_order_idLEFT JOIN procurement.t_work_order_detail wod ON wo.id = wod.work_order_idLEFT JOIN m_vendor ON wod.vendor_id = m_vendor.idLEFT JOIN m_unit_master unit ON qs.unit_id = unit.unit_idWHERE qsd.is_active = true;

-- procurement.get_workorderrequestdetail source
CREATE OR REPLACE VIEW procurement.get_workorderrequestdetailAS SELECT woqr.id,woqr.work_order_quotation_request_no,item.name AS itemname,s.store_name,rt.type,status1.status,status2.status AS approvaer_status,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS addedusername,(((em2.first_name::text || ' '::text) || em2.middle_name::text) || ' '::text) || em2.last_name::text AS updatedusername,v.name AS vendor_name,woqrd.quantity,woqrd.specification,woqrd.remark,u.unit_name,u.unit_address,u.unit_contact,tb.batch_no,u.imageFROM procurement.t_work_order_quotation_request woqrJOIN procurement.t_work_order_quotation_request_detail woqrd ON woqr.id = woqrd.work_order_quotation_request_idJOIN m_store s ON woqr.store_id = s.store_idJOIN procurement.m_contract_type ct ON woqr.contract_type_id = ct.idJOIN m_request_type rt ON woqr.request_type_id = rt.idJOIN m_status status1 ON woqr.status_id = status1.idJOIN m_status status2 ON woqr.approval_status_id = status2.idLEFT JOIN m_employee_master em1 ON woqr.added_by = em1.user_idLEFT JOIN m_employee_master em2 ON woqr.updated_by = em2.user_idLEFT JOIN m_vendor v ON woqrd.current_vendor_id = v.idLEFT JOIN inventory.t_batch tb ON woqrd.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_unit_master u ON woqr.unit_id = u.unit_idWHERE woqrd.is_active = true;

-- procurement.getgrnsummery source
CREATE OR REPLACE VIEW procurement.getgrnsummeryAS SELECT grn.id,grn.grn_number,grn.added_date,v.name AS vendor_name,grn.invoice_number,grn.dc_number,s.store_name,grn.total_amount,grn.total_discount,grn.discount,grn.total_tax_ammount,grn.total_other_amount,grn.net_amount,u.unit_name,u.unit_address AS unit_address_2,status.id AS status_id,status.status,statusapproval.id AS approve_status_id,statusapproval.status AS approvalstatus,(emp.first_name::text || ' '::text) || emp.last_name::text AS addedbyusername,(empapprovalby.first_name::text || ' '::text) || empapprovalby.last_name::text AS approvedbyusername,grn.invoice_date,grn.dc_date,grn.inward_number,grn.inward_date,grn.approved_date,v.id AS vendor_id,u.unit_id,u.image,s.store_id,mat.type AS asstype,grn.asset_type_idFROM procurement.t_good_receipt_note grnLEFT JOIN m_vendor v ON v.id = grn.vendor_idJOIN m_store s ON grn.store_id = s.store_idJOIN m_asset_type mat ON mat.id = grn.asset_type_idJOIN m_unit_master u ON grn.unit_id = u.unit_idLEFT JOIN m_status status ON grn.status_id = status.idLEFT JOIN m_status statusapproval ON grn.approve_status_id = statusapproval.idLEFT JOIN m_user_master userm ON grn.added_by = userm.user_idLEFT JOIN m_employee_master emp ON userm.user_id = emp.user_idLEFT JOIN m_user_master userapprovalby ON grn.added_by = userapprovalby.user_idLEFT JOIN m_employee_master empapprovalby ON userapprovalby.user_id = empapprovalby.user_id;

-- procurement.getpurchaseordersummery source
CREATE OR REPLACE VIEW procurement.getpurchaseordersummeryAS SELECT po.id,po.po_number,po.added_date,po.total_amount,po.total_discount,po.discount,po.total_tax_amount,po.total_other_amount,po.net_amount,po.cancel_reason_id,s.store_name,atm.type,po.status_id,m_status.status,v.name,po.approved_date,po.approve_status_id,po.approved_by,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,(poapprovedbyemp.first_name::text || ' '::text) || poapprovedbyemp.last_name::text AS approvalusername,poapprovalstatus.status AS approvalstauts,um.unit_id,um.unit_address,um.unit_address_2,um.unit_contact,um.unit_contact_2,um.unit_logo,um.unit_website,um.unit_name,i.name AS item_name,pod.po_quantity,pod.bonus_quantity,pod.cop,pod.mrp,pod.tax_percentage,pod.discount AS d_discount,pod.total_amount AS d_total_amount,pod.net_amount AS d_net_amount,'\x'::bytea AS image,pod.tax_amountFROM procurement.t_purchase_order poLEFT JOIN m_vendor v ON po.vendor_id = v.idLEFT JOIN m_store s ON po.store_id = s.store_idLEFT JOIN m_asset_type atm ON po.asset_type_id = atm.idLEFT JOIN m_status ON po.status_id = m_status.idLEFT JOIN m_user_master ON m_user_master.user_id = po.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_user_master poapprovedby ON poapprovedby.user_id = po.approved_byLEFT JOIN m_employee_master poapprovedbyemp ON poapprovedbyemp.user_id = poapprovedby.user_idLEFT JOIN m_status poapprovalstatus ON po.approve_status_id = poapprovalstatus.idLEFT JOIN m_unit_master um ON um.unit_id = po.unit_idLEFT JOIN procurement.t_purchase_order_detail pod ON po.id = pod.purchase_order_idLEFT JOIN m_item i ON pod.item_id = i.id;

-- procurement.stock_details source
CREATE OR REPLACE VIEW procurement.stock_detailsAS SELECT grn.added_date,grn.vendor_id,v.name AS vendor_name,grn.store_id,s.store_name,m_item.manufacturer_id,m_manufacturer.name AS m_manufacturer_name,m_item.generic_id,generic.name AS m_generic_name,u.unit_name,u.unit_address,u.unit_contact,u.unit_id,u.image,tgrnd.grn_received_quantity AS qty,'Purchase'::text AS type,tgrnd.item_id,m_item.name AS itemFROM procurement.t_good_receipt_note grnJOIN procurement.t_good_receipt_note_detail tgrnd ON grn.id = tgrnd.grn_idJOIN m_item ON tgrnd.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN m_manufacturer ON m_manufacturer.id = m_item.manufacturer_idLEFT JOIN m_vendor v ON v.id = grn.vendor_idLEFT JOIN m_store s ON grn.store_id = s.store_idJOIN unitinformation u ON grn.unit_id = u.unit_idUNION ALLSELECT t_sale.added_date,0 AS vendor_id,''::character varying AS vendor_name,t_sale.store_id,s.store_name,m_item.manufacturer_id,m_manufacturer.name AS m_manufacturer_name,m_item.generic_id,generic.name AS m_generic_name,u.unit_name,u.unit_address,u.unit_contact,u.unit_id,u.image,t_sale_detail.quantity AS qty,'Issue'::text AS type,t_sale_detail.item_id,m_item.name AS itemFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN m_item ON t_sale_detail.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN m_manufacturer ON m_manufacturer.id = m_item.manufacturer_idLEFT JOIN m_store s ON t_sale.store_id = s.store_idJOIN unitinformation u ON t_sale.unit_id = u.unit_idUNION ALLSELECT us.added_date,0 AS vendor_id,''::character varying AS vendor_name,us.store_id,s.store_name,m_item.manufacturer_id,m_manufacturer.name AS m_manufacturer_name,m_item.generic_id,generic.name AS m_generic_name,u.unit_name,u.unit_address,u.unit_contact,u.unit_id,u.image,usd.variance_qty AS qty,'Adjust'::text AS type,tb.item_id,m_item.name AS itemFROM inventory.t_upload_stock usLEFT JOIN inventory.t_upload_stock_detail usd ON us.id = usd.upload_stock_idLEFT JOIN inventory.t_batch tb ON usd.batch_id = tb.idJOIN m_item ON tb.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN m_manufacturer ON m_manufacturer.id = m_item.manufacturer_idLEFT JOIN m_store s ON us.store_id = s.store_idJOIN unitinformation u ON us.unit_id = u.unit_id;-- DROP SCHEMA public;
