e)procedure_order_mst_id int4 NULL,is_appointable_radiology bpchar(1) DEFAULT 'N'::bpchar NULL,package_either_or_group_id int4 NULL,sale_detail_id int4 NULL,markup_status bool DEFAULT false NULL,patient_class_percentage numeric(15, 2) NULL,debit_note_service bool DEFAULT false NULL,disallowed_amount float8 NULL,accession_number varchar(100) NULL,is_from_addservice bpchar(1) DEFAULT 'N'::bpchar NULL,is_service_reviewed bool DEFAULT false NULL,dummy_service_amt int4 NULL,ref_doc_share_per numeric(15, 2) NULL,is_consultation_service bpchar(1) DEFAULT 'N'::bpchar NULL,force_add_removed int4 DEFAULT 0 NULL,is_consumed bool DEFAULT false NULL,is_order_visible_dept bpchar(1) NULL,review_applicable_date timestamp NULL,nursing_service_order_flag bpchar(1) DEFAULT 'N'::bpchar NULL,discount_category_id int4 NULL,discount_ownership int4 DEFAULT 0 NULL,hospital_share numeric(15, 2) NULL,p_image_name text NULL,p_image text NULL,is_charged_half_day bpchar(1) DEFAULT 'N'::bpchar NULL,cov_template_id int4 NULL,patient_coupon_template_mapper_id int4 NULL,is_dummy_service bool DEFAULT false NULL,is_hidden_service bool DEFAULT false NULL,pharmacy_discount_override int4 DEFAULT 0 NULL,redo_count int4 NULL,redo_reason varchar NULL,CONSTRAINT chk_t_order_details CHECK ((((status = 'A'::bpchar) AND (ord_cancelled = 'N'::bpchar)) OR ((status = 'I'::bpchar) AND (ord_cancelled = 'Y'::bpchar)) OR ((status = 'I'::bpchar) AND (ord_cancelled = 'N'::bpchar)))),CONSTRAINT t_order_details_pkey PRIMARY KEY (order_details_id));
