CREATE INDEX idx_t_order_details_priority_id ON public.t_order_details USING btree (priority_id);
CREATE INDEX idx_t_order_details_service_id ON public.t_order_details USING btree (service_id);
COMMENT ON TABLE public.t_order_details IS 'order details of billing';-- Column commentsCOMMENT ON COLUMN public.t_order_details.is_procedure IS 'N-No(default)Y-Yes';COMMENT ON COLUMN public.t_order_details.is_procedure_service IS 'N-No(defualt)Y-Yes(if service for procedure)';-- Table Triggerscreate trigger global_hospital_pharmacy_service afterinsertorupdateonpublic.t_order_details for each row execute function global_hospital_pharmacy_service();
