-- public.admbarcode source
CREATE OR REPLACE VIEW public.admbarcodeAS SELECT adm.admission_id,pr.first_name,pr.middle_name,pr.last_name,pr.dob::date AS birthdate,adm.admission_number,createbarcodecode128(adm.admission_id::character varying) AS barcode,cm.company_desc,pr.uhid_number,age(pr.dob) AS age,gm.gender_name,concat(dm.first_name, ' ', dm.last_name) AS doctorname,ent.payment_entitlement_id,ent.payment_entitlement_desc,abs(date_part('Day'::text, age(to_char(pr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS days,abs(date_part('Month'::text, age(to_char(pr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS months,abs(date_part('Year'::text, age(to_char(pr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyearFROM patient.t_patient_registration prJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN adt.t_admission adm ON pr.patient_id = adm.patient_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = adm.admitting_doctor_idLEFT JOIN opd.t_patient_sponsor_details sponsor ON adm.admission_id = sponsor.admission_id AND sponsor.priority_id = 1 AND sponsor.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master ent ON ent.payment_entitlement_id = sponsor.payment_entitlement_idLEFT JOIN t_company_master cm ON sponsor.payee_id = cm.company_id;

-- public.admbarcode_new source
CREATE OR REPLACE VIEW public.admbarcode_newAS SELECT adm.admission_id,pr.first_name,pr.middle_name,pr.last_name,pr.dob::date AS birthdate,adm.admission_number,createbarcodecode128(adm.admission_id::character varying) AS barcode,cm.company_desc,pr.patient_id,age(pr.dob) AS age,date_part('year'::text, age(pr.dob::date::timestamp with time zone))::text || ' Years'::text AS ageinyear,m_gender_master.gender_name,adm.created_date AS admdate,((('Dr.'::text || ' '::text) || admittingdoctor.first_name::text) || ' '::text) || admittingdoctor.last_name::text AS admdoctorname,m_ward_master.ward_name,m_bed_master.bed_number AS bed_desc,pr.uhid_number,pr.mobile_number,um.unit_id,um.unit_name,um.unit_address,t_admission_details.doa,pd.address,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,admittingdoctor.registration_numberFROM patient.t_patient_registration prJOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idJOIN adt.t_admission adm ON pr.patient_id = adm.patient_idLEFT JOIN opd.t_patient_sponsor_details sponsor ON adm.admission_id = sponsor.admission_id AND sponsor.priority_id = 1 AND sponsor.status = 'A'::bpcharLEFT JOIN t_company_master cm ON sponsor.payee_id = cm.company_idLEFT JOIN m_gender_master ON pr.gender_id = m_gender_master.gender_idLEFT JOIN doctor.m_doctor_master admittingdoctor ON adm.doctor_id = admittingdoctor.doctor_idJOIN adt.t_admission_details ON adm.admission_id = t_admission_details.admission_idLEFT JOIN adt.m_ward_master ON t_admission_details.ward_id = m_ward_master.ward_idLEFT JOIN adt.m_bed_master ON t_admission_details.bed_id = m_bed_master.bed_idLEFT JOIN m_unit_master um ON um.unit_id = adm.unit_idWHERE t_admission_details.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = adm.admission_id))ORDER BY adm.admission_id DESC;

-- public.advanceconsumed source
CREATE OR REPLACE VIEW public.advanceconsumedAS SELECT DISTINCT dm.deposit_master_id,vm.visit_type_code::text || 'D Advance'::text AS deposit,vm.visit_type_code,vm.visit_type_id,pmm.payment_mode_desc,dd.amount,dd.consumed_amount,0 AS tdsamt,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,pm.patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_desc,dm.payee_id,payee.company_desc,umm.imageFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN m_visit_type_master vm ON dm.visit_type_id = vm.visit_type_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON dm.patient_id = pm.patient_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN t_company_master payee ON dm.payee_id = payee.company_idUNIONSELECT DISTINCT dm.deposit_master_id,'patient Advance'::text AS deposit,'patient'::character varying AS visit_type_code,3 AS visit_type_id,pmm.payment_mode_desc,dd.amount,dd.consumed_amount,0 AS tdsamt,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,pm.patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_desc,dm.payee_id,payee.company_desc,umm.imageFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON dm.patient_id = pm.patient_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN t_company_master payee ON dm.payee_id = payee.company_idWHERE dm.encounter_id IS NULL AND dm.admission_id IS NULL AND dm.visit_type_id IS NULL;

-- public.advanceconsumed_againstbills source
CREATE OR REPLACE VIEW public.advanceconsumed_againstbillsAS SELECT DISTINCT bm.billing_master_id,deptconsdetail.consumed_amount,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,deptcons.dep_consumption_date,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.patient_id,pr.uhid_number,deptcons.deposite_consumption_number,bm.bill_number,bm.bill_date_time,'\x'::bytea AS image,dm.deposit_no,dm.deposit_date,dm.deposit_amount,visit.visit_type_id,visit.visit_type_name,concat(emp.first_name, ' ', emp.last_name) AS emp,bm.net_amount,cm.company_id,cm.company_desc::text AS company_descFROM billing.m_billing_master bmJOIN billing.t_payment_deposite_consumption deptcons ON bm.billing_master_id = deptcons.bill_idLEFT JOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.priority_id = 1 AND bpd.status = 'A'::"char"LEFT JOIN t_company_master cm ON cm.company_id = bpd.payee_idJOIN patient.t_patient_registration pr ON pr.patient_id = bm.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idJOIN m_user_master um ON deptcons.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idLEFT JOIN m_employee_master emp ON emp.user_id = um.user_idJOIN m_visit_type_master visit ON visit.visit_type_id = bm.visit_type_idJOIN billing.t_payment_deposite_consumption_details deptconsdetail ON deptconsdetail.dep_consumption_id = deptcons.dep_consumption_idJOIN billing.m_deposit_master dm ON dm.deposit_master_id = deptconsdetail.deposit_idWHERE deptcons.status = 'A'::bpcharUNION ALLSELECT DISTINCT bm.billing_master_id,deptconsdetail.consumed_amount,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,deptcons.dep_consumption_date,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.patient_id,pr.uhid_number,deptcons.deposite_consumption_number,bm.bill_number,bm.bill_date_time,'\x'::bytea AS image,compnayrecmaster.company_receipt_number::character varying(300) AS deposit_no,compnayrecmaster.company_receipt_date AS deposit_date,compnayrecmaster.receipt_amount AS deposit_amount,visit.visit_type_id,visit.visit_type_name,concat(emp.first_name, ' ', emp.last_name) AS emp,bm.net_amount,company.company_id,company.company_descFROM billing.m_company_receipt_master compnayrecmasterJOIN billing.t_company_receipt_detail companyrecdetail ON compnayrecmaster.company_receipt_id = companyrecdetail.company_receipt_idJOIN billing.t_payment_reciept_master rm ON rm.payment_reciept_id = compnayrecmaster.receipt_idJOIN billing.t_payment_reciept_details prd ON rm.payment_reciept_id = prd.payment_receipt_master_idJOIN billing.t_company_invoice_details invoice_details ON companyrecdetail.company_invoice_detail_id = invoice_details.company_invoice_detail_idJOIN billing.m_company_invoice_master invoice_master ON invoice_details.company_invoice_id = invoice_master.company_invoice_idJOIN billing.m_billing_master bm ON invoice_details.bill_id = bm.billing_master_idJOIN billing.t_payment_deposite_consumption deptcons ON compnayrecmaster.deposit_consumption_id = deptcons.dep_consumption_idJOIN billing.t_payment_deposite_consumption_details deptconsdetail ON deptconsdetail.dep_consumption_id = deptcons.dep_consumption_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = bm.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idJOIN t_company_master company ON company.company_id = invoice_details.bill_payee_idJOIN m_user_master um ON deptcons.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idLEFT JOIN m_employee_master emp ON emp.user_id = um.user_idJOIN m_visit_type_master visit ON visit.visit_type_id = bm.visit_type_idWHERE deptcons.status = 'A'::bpchar;

-- public.advancesummary source
CREATE OR REPLACE VIEW public.advancesummaryAS SELECT DISTINCT dd.deposit_details_id AS deposit_master_id,vm.visit_type_code::text || 'D Advance'::text AS deposit,vm.visit_type_code,vm.visit_type_id,pmm.payment_mode_desc,dd.amount,dd.consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_descFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN m_visit_type_master vm ON dm.visit_type_id = vm.visit_type_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idLEFT JOIN m_user_master um ON dd.created_by = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN opd.t_encounter_master em ON dm.encounter_id = em.encounter_idJOIN patient.t_patient_registration pm ON em.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE dm.status = 'A'::"char"UNIONSELECT DISTINCT dd.deposit_details_id AS deposit_master_id,vm.visit_type_code::text || 'D Advance'::text AS deposit,vm.visit_type_code,vm.visit_type_id,pmm.payment_mode_desc,dd.amount,dd.consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_descFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN m_visit_type_master vm ON dm.visit_type_id = vm.visit_type_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idLEFT JOIN m_user_master um ON dd.created_by = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN adt.t_admission adm ON dm.admission_id = adm.admission_idJOIN patient.t_patient_registration pm ON adm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE dm.status = 'A'::"char"UNIONSELECT dm.deposit_master_id,'Patient Advance'::text AS deposit,'Patient'::character varying AS visit_type_code,3 AS visit_type_id,pmm.payment_mode_desc,dd.amount,dd.consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_descFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idLEFT JOIN m_user_master um ON dd.created_by = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE dm.encounter_id IS NULL AND dm.admission_id IS NULL AND dm.visit_type_id IS NULL AND dm.status = 'A'::"char"ORDER BY 1;

-- public.allcollectionsummary source
CREATE OR REPLACE VIEW public.allcollectionsummaryAS SELECT opdipdcollectionsummary.deposit_master_id,opdipdcollectionsummary.deposit,opdipdcollectionsummary.visit_type_code,opdipdcollectionsummary.visit_type_id,opdipdcollectionsummary.user_name,opdipdcollectionsummary.user_id,opdipdcollectionsummary.unit_id,opdipdcollectionsummary.organization_id,opdipdcollectionsummary.unit_name,opdipdcollectionsummary.patientname,opdipdcollectionsummary.patient_id,opdipdcollectionsummary.uhid_number,opdipdcollectionsummary.depositdate,opdipdcollectionsummary.unit_address,opdipdcollectionsummary.unit_contact_2,opdipdcollectionsummary.unit_contact,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Cash'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS cash,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Cheque'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS cheque,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Card Payment'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS creditcard,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Debit Card'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS debitcard,COALESCE(sum(opdipdcollectionsummary.consumed_amount), 0::double precision) AS patadvused,COALESCE(sum(opdipdcollectionsummary.tdsamt)::double precision, 0::double precision) AS tdsamt,opdipdcollectionsummary.amttype,opdipdcollectionsummary.reciptno,COALESCE(opdipdcollectionsummary.counter_id, 0) AS counter_id,opdipdcollectionsummary.counter_desc,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Mpesa'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS mpesa,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Loyalty Card'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS loyaltycard,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'E-Transfer'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS e_transfer,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Available Fund'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS availablefund,COALESCE(sum(CASEWHEN opdipdcollectionsummary.payment_mode_desc = 'Doctor Credit'::text THEN opdipdcollectionsummary.amountELSE NULL::double precisionEND), 0::double precision) AS doctorcreditFROM opdipdcollectionsummaryGROUP BY opdipdcollectionsummary.deposit_master_id, opdipdcollectionsummary.deposit, opdipdcollectionsummary.visit_type_code, opdipdcollectionsummary.user_name, opdipdcollectionsummary.user_id, opdipdcollectionsummary.unit_id, opdipdcollectionsummary.organization_id, opdipdcollectionsummary.unit_name, opdipdcollectionsummary.patientname, opdipdcollectionsummary.patient_id, opdipdcollectionsummary.uhid_number, opdipdcollectionsummary.depositdate, opdipdcollectionsummary.unit_address, opdipdcollectionsummary.unit_contact_2, opdipdcollectionsummary.unit_contact, opdipdcollectionsummary.amttype, opdipdcollectionsummary.reciptno, opdipdcollectionsummary.visit_type_id, opdipdcollectionsummary.counter_id, opdipdcollectionsummary.counter_descUNION ALLSELECT get_pharmacycollection.id::integer AS deposit_master_id,get_pharmacycollection.salestype AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,get_pharmacycollection.username::character varying(100) AS user_name,get_pharmacycollection.user_id,get_pharmacycollection.unit_id,get_pharmacycollection.organization_id,get_pharmacycollection.unit_name,get_pharmacycollection.patientname,get_pharmacycollection.patient_id,get_pharmacycollection.temp_uhid AS uhid_number,get_pharmacycollection.receiptdate AS depositdate,get_pharmacycollection.unit_address,''::text AS unit_contact_2,''::character varying(200) AS unit_contact,COALESCE(get_pharmacycollection.cashamount, 0::bigint::double precision) AS cash,COALESCE(get_pharmacycollection.chequeamount, 0::bigint) AS cheque,COALESCE(get_pharmacycollection.creditcardamount, 0::bigint) AS creditcard,COALESCE(get_pharmacycollection.debitcardamount, 0::bigint) AS debitcard,0 AS patadvused,0 AS tdsamt,'Income'::text AS amttype,get_pharmacycollection.bill_no AS reciptno,COALESCE(get_pharmacycollection.counter_id, 0) AS counter_id,''::character varying(50) AS counter_desc,0 AS mpesa,0 AS loyaltycard,COALESCE(get_pharmacycollection.e_transfer, 0::bigint) AS e_transfer,0 AS availablefund,0 AS doctorcreditFROM get_pharmacycollectionWHERE get_pharmacycollection.salestype = 'Sales'::textUNION ALLSELECT get_pharmacycollection.id::integer AS deposit_master_id,get_pharmacycollection.salestype AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,get_pharmacycollection.username::character varying(100) AS user_name,get_pharmacycollection.user_id,get_pharmacycollection.unit_id,get_pharmacycollection.organization_id,get_pharmacycollection.unit_name,get_pharmacycollection.patientname,get_pharmacycollection.patient_id,get_pharmacycollection.temp_uhid AS uhid_number,get_pharmacycollection.receiptdate AS depositdate,get_pharmacycollection.unit_address,''::text AS unit_contact_2,''::character varying(200) AS unit_contact,COALESCE(get_pharmacycollection.cashamount, 0::bigint::double precision) AS cash,COALESCE(get_pharmacycollection.chequeamount, 0::bigint) AS cheque,COALESCE(get_pharmacycollection.creditcardamount, 0::bigint) AS creditcard,COALESCE(get_pharmacycollection.debitcardamount, 0::bigint) AS debitcard,0 AS patadvused,0 AS tdsamt,'Refund'::text AS amttype,get_pharmacycollection.bill_no AS reciptno,COALESCE(get_pharmacycollection.counter_id, 0) AS counter_id,''::character varying(50) AS counter_desc,0 AS mpesa,0 AS loyaltycard,COALESCE(get_pharmacycollection.e_transfer, 0::bigint) AS e_transfer,0 AS availablefund,0 AS doctorcreditFROM get_pharmacycollectionWHERE get_pharmacycollection.salestype = 'Sales Return'::text;

-- public.anil_allcollectionsummary source
CREATE OR REPLACE VIEW public.anil_allcollectionsummaryAS SELECT deposit_master_id,deposit,visit_type_code,CASEWHEN COALESCE(outstanding, 0::double precision) &lt;&gt; 0::double precision THEN 1ELSE visit_type_idEND AS visit_type_id,user_name,user_id,unit_id,COALESCE(organization_id, 0) AS organization_id,unit_name,patientname,patient_id,uhid_number,CASEWHEN COALESCE(outstanding, 0::double precision) &lt;&gt; 0::double precision THEN bill_date_timeELSE depositdateEND AS depositdate,unit_address,unit_contact_2,unit_contact,COALESCE(sum(CASEWHEN payment_mode_desc = 'Cash'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS cash,COALESCE(sum(CASEWHEN payment_mode_desc = 'Cheque'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS cheque,COALESCE(sum(CASEWHEN payment_mode_desc = 'Card Payment'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS creditcard,COALESCE(sum(CASEWHEN payment_mode_desc = 'Debit Card'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS debitcard,COALESCE(sum(consumed_amount), 0::double precision) AS patadvused,COALESCE(sum(tdsamt)::double precision, 0::double precision) AS tdsamt,amttype,reciptno,COALESCE(counter_id, 0) AS counter_id,counter_desc,COALESCE(sum(CASEWHEN payment_mode_desc = 'Mpesa'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS mpesa,COALESCE(sum(CASEWHEN payment_mode_desc = 'Loyalty Card'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS loyaltycard,COALESCE(sum(CASEWHEN payment_mode_desc = 'E-Transfer'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS e_transfer,COALESCE(sum(CASEWHEN payment_mode_desc = 'Available Fund'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS availablefund,COALESCE(sum(CASEWHEN payment_mode_desc = 'Doctor Credit'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS doctorcredit,total_bill_amount,discount_amount,net_amount,outstanding,paidamount,transaction_type_desc,bill_date_time,referral_nameFROM image_opdipdcollectionsummaryGROUP BY deposit_master_id, deposit, visit_type_code, user_name, user_id, unit_id, organization_id, unit_name, patientname, patient_id, uhid_number, depositdate, unit_address, unit_contact_2, unit_contact, amttype, reciptno, visit_type_id, counter_id, counter_desc, total_bill_amount, discount_amount, net_amount, outstanding, paidamount, transaction_type_desc, bill_date_time, referral_name;

-- public.bedoccupancy source
CREATE OR REPLACE VIEW public.bedoccupancyAS SELECT wm.ward_name,bedlog.unit_id,sum(CASEWHEN status.bed_status_code::text = 'OC'::text THEN 1ELSE 0END) AS occupied,sum(CASEWHEN status.bed_status_code::text = 'VAC'::text THEN 1ELSE 0END) AS vacant,sum(CASEWHEN status.bed_status_code::text = 'RES'::text THEN 1ELSE 0END) AS reserved,sum(CASEWHEN status.bed_status_code::text = 'PND'::text THEN 1ELSE 0END) AS pending,sum(CASEWHEN status.bed_status_code::text = 'VACRDY'::text THEN 1ELSE 0END) AS vacant_and_ready_to_receive_patient,sum(CASEWHEN status.bed_status_code::text = 'UNHOU'::text THEN 1ELSE 0END) AS under_housekeeping,sum(CASEWHEN status.bed_status_code::text = 'RET'::text THEN 1ELSE 0END) AS reserved_for_retention,bedlog.created_date,wm.ward_idFROM adt.t_bed_log_status bedlogJOIN adt.m_bed_master bm ON bm.bed_id = bedlog.bed_idJOIN adt.m_ward_master wm ON wm.ward_id = bm.ward_idJOIN adt.m_bed_status_master status ON status.bed_status_id = bedlog.bed_status_idGROUP BY wm.ward_name, bedlog.unit_id, bedlog.created_date, wm.ward_id;

-- public.bedoccupancy_dept source
CREATE OR REPLACE VIEW public.bedoccupancy_deptAS SELECT wm.ward_name,bedlog.unit_id,sum(CASEWHEN status.bed_status_code::text = 'OC'::text THEN 1ELSE 0END) AS occupied,sum(CASEWHEN status.bed_status_code::text = 'VAC'::text THEN 1ELSE 0END) AS vacant,sum(CASEWHEN status.bed_status_code::text = 'RES'::text THEN 1ELSE 0END) AS reserved,sum(CASEWHEN status.bed_status_code::text = 'PND'::text THEN 1ELSE 0END) AS pending,sum(CASEWHEN status.bed_status_code::text = 'VACRDY'::text THEN 1ELSE 0END) AS vacant_and_ready_to_receive_patient,sum(CASEWHEN status.bed_status_code::text = 'UNHOU'::text THEN 1ELSE 0END) AS under_housekeeping,sum(CASEWHEN status.bed_status_code::text = 'RET'::text THEN 1ELSE 0END) AS reserved_for_retention,bedlog.created_date,wm.ward_id,sp.speciality_id,sp.speciality_name,concat(dm.first_name, ' ', dm.last_name) AS doctor,dm.doctor_idFROM adt.t_bed_log_status bedlogJOIN adt.m_bed_master bm ON bm.bed_id = bedlog.bed_idJOIN adt.m_ward_master wm ON wm.ward_id = bm.ward_idJOIN adt.t_admission_details tad ON tad.ward_id = wm.ward_idJOIN adt.t_admission ta ON ta.admission_id = tad.admission_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = ta.speciality_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idJOIN adt.m_bed_status_master status ON status.bed_status_id = bedlog.bed_status_idGROUP BY wm.ward_name, bedlog.unit_id, bedlog.created_date, wm.ward_id, sp.speciality_id, sp.speciality_name, dm.first_name, dm.last_name, dm.doctor_id;

-- public.bedoccupancy_surgical source
CREATE OR REPLACE VIEW public.bedoccupancy_surgicalAS SELECT wm.ward_name,bedlog.unit_id,sum(CASEWHEN status.bed_status_code::text = 'OC'::text THEN 1ELSE 0END) AS occupied,sum(CASEWHEN status.bed_status_code::text = 'VAC'::text THEN 1ELSE 0END) AS vacant,sum(CASEWHEN status.bed_status_code::text = 'RES'::text THEN 1ELSE 0END) AS reserved,sum(CASEWHEN status.bed_status_code::text = 'PND'::text THEN 1ELSE 0END) AS pending,sum(CASEWHEN status.bed_status_code::text = 'VACRDY'::text THEN 1ELSE 0END) AS vacant_and_ready_to_receive_patient,sum(CASEWHEN status.bed_status_code::text = 'UNHOU'::text THEN 1ELSE 0END) AS under_housekeeping,sum(CASEWHEN status.bed_status_code::text = 'RET'::text THEN 1ELSE 0END) AS reserved_for_retention,bedlog.created_date,wm.ward_id,atm.admission_type_id,atm.admission_type_descFROM adt.t_bed_log_status bedlogJOIN adt.m_bed_master bm ON bm.bed_id = bedlog.bed_idJOIN adt.m_ward_master wm ON wm.ward_id = bm.ward_idJOIN adt.t_admission_details tad ON tad.ward_id = wm.ward_idJOIN adt.t_admission ta ON ta.admission_id = tad.admission_idJOIN adt.m_admission_type_master atm ON atm.admission_type_id = tad.admission_type_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = ta.speciality_idJOIN adt.m_bed_status_master status ON status.bed_status_id = bedlog.bed_status_idGROUP BY wm.ward_name, bedlog.unit_id, bedlog.created_date, wm.ward_id, atm.admission_type_id, atm.admission_type_desc;

-- public.bedoccupancy_test source
CREATE OR REPLACE VIEW public.bedoccupancy_testAS SELECT bedcategor0_.organization_id,bedcategor0_.unit_id,bedcategor0_.bed_category_id,bedcategor0_.bed_category_desc,( SELECT count(bedmaster1_.bed_id) AS countFROM adt.m_bed_master bedmaster1_JOIN adt.t_bed_log_status listbedlog2_ ON bedmaster1_.bed_id = listbedlog2_.bed_idWHERE listbedlog2_.bed_status_id = 3 AND bedmaster1_.bed_category_id = bedcategor0_.bed_category_id AND bedmaster1_.unit_id = 1 AND listbedlog2_.status = 'A'::bpchar AND listbedlog2_.updated_date::date = '2019-09-24'::date) AS vacantandready,( SELECT count(bedmaster3_.bed_id) AS countFROM adt.m_bed_master bedmaster3_JOIN adt.t_bed_log_status listbedlog4_ ON bedmaster3_.bed_id = listbedlog4_.bed_idWHERE listbedlog4_.bed_status_id = 2 AND bedmaster3_.bed_category_id = bedcategor0_.bed_category_id AND bedmaster3_.unit_id = 1 AND listbedlog4_.status = 'A'::bpchar AND listbedlog4_.updated_date::date = '2019-09-24'::date) AS underhousekeeping,( SELECT count(bedmaster5_.bed_id) AS countFROM adt.m_bed_master bedmaster5_JOIN adt.t_bed_log_status listbedlog6_ ON bedmaster5_.bed_id = listbedlog6_.bed_idWHERE listbedlog6_.bed_status_id = 5 AND bedmaster5_.bed_category_id = bedcategor0_.bed_category_id AND bedmaster5_.unit_id = 1 AND listbedlog6_.status = 'A'::bpchar AND listbedlog6_.updated_date::date = '2019-09-24'::date) AS occupied,( SELECT count(bedmaster5_.bed_id) AS countFROM adt.m_bed_master bedmaster5_JOIN adt.t_bed_log_status listbedlog6_ ON bedmaster5_.bed_id = listbedlog6_.bed_idWHERE listbedlog6_.bed_status_id = 6 AND bedmaster5_.bed_category_id = bedcategor0_.bed_category_id AND bedmaster5_.unit_id = 1 AND listbedlog6_.status = 'A'::bpchar AND listbedlog6_.updated_date::date = '2019-09-24'::date) AS vacants,unitinformation.unit_name,unitinformation.unit_addressFROM adt.m_bed_category_master bedcategor0_LEFT JOIN unitinformation ON bedcategor0_.unit_id = unitinformation.unit_idWHERE bedcategor0_.unit_id = 1 AND bedcategor0_.status = 'A'::bpcharORDER BY bedcategor0_.bed_category_id;

-- public.bedstatus_withpatientdetails source
CREATE OR REPLACE VIEW public.bedstatus_withpatientdetailsAS WITH admittedpatientlist AS (SELECT DISTINCT pr.uhid_number,adde.doa AS admission_date,((m_prefix_master.prefix_desc || ' '::text) || (((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text)) || pr.last_name::text AS name,gm.gender_name,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,pr.mobile_number,bm.bed_code AS bed_number,cm.company_desc,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS docname,(((ad_d.first_name::text || ' '::text) || ad_d.middle_name::text) || ' '::text) || ad_d.last_name::text AS sec_drname,ad.admission_id,ad.admission_number,dm.doctor_id,m_payment_entitlement_master.payment_entitlement_desc,m_payment_entitlement_master.payment_entitlement_id,cm.company_id,bm.bed_id,row_number() OVER (PARTITION BY bm.bed_id ORDER BY ad.admission_id DESC) AS srno1FROM adt.t_admission adJOIN patient.t_patient_registration pr ON ad.patient_id = pr.patient_idJOIN adt.t_admission_details adde ON ad.admission_id = adde.admission_idLEFT JOIN m_gender_master gm ON pr.gender_id = gm.gender_idLEFT JOIN doctor.m_doctor_master dm ON ad.doctor_id = dm.doctor_idLEFT JOIN doctor.m_doctor_master ad_d ON ad.admitting_doctor_id = ad_d.doctor_idJOIN adt.m_bed_master bm ON adde.bed_id = bm.bed_id AND bm.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details psd ON ad.admission_id = psd.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN t_company_master cm ON psd.payee_id = cm.company_idLEFT JOIN m_payment_entitlement_master ON psd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN m_prefix_master ON m_prefix_master.prefix_id = pr.prefix_idWHERE ad.status = 'A'::bpchar AND adde.status = 'A'::bpchar AND adde.nursing_acceptance = 'Y'::bpcharORDER BY bm.bed_id)SELECT bed.bed_id,bed.bed_status_id,bed.bed_desc,bedstatusmaster.bed_status_desc,ward.ward_name,ward.ward_id,um.unit_name,um.unit_address,um.unit_id,um.image,admittedpatientlist.name,admittedpatientlist.admission_number,admittedpatientlist.admission_date,admittedpatientlist.ageyear,admittedpatientlist.gender_name,admittedpatientlist.docname,admittedpatientlist.company_desc,admittedpatientlist.sec_drname,admittedpatientlist.srno1FROM adt.m_bed_master bedJOIN adt.m_bed_category_master bedcategory ON bed.bed_category_id = bedcategory.bed_category_id AND bed.status = 'A'::bpcharJOIN adt.m_bed_status_master bedstatusmaster ON bed.bed_status_id = bedstatusmaster.bed_status_idJOIN adt.m_ward_master ward ON bed.ward_id = ward.ward_idJOIN m_unit_master um ON bed.unit_id = um.unit_idLEFT JOIN admittedpatientlist ON bed.bed_id = admittedpatientlist.bed_id AND admittedpatientlist.srno1 = 1WHERE ward.ward_id &lt;&gt; ALL (ARRAY[22, 23, 10]);
-- public.bi_finaltotal source
CREATE OR REPLACE VIEW public.bi_finaltotalAS SELECT bi_image_collection.organization_id,bi_image_collection.unit_id,bi_image_collection.depositdate AS trandate,sum(bi_image_collection.cash) AS totalcash,sum(bi_image_collection.e_transfer) AS online,grtran.sono,grtran.x_ray,grtran.echo,grtran.doppler,grtran.ct,grtran.ecg,grtran.mri,grtran.path,grtran.consultationFROM "Reports".bi_image_collectionJOIN ( SELECT bi_group_total.organization_id,bi_group_total.unit_id,bi_group_total.trandate,sum(bi_group_total.totalcash) AS totalcash,sum(bi_group_total.online) AS online,sum(bi_group_total.sono) AS sono,sum(bi_group_total.x_ray) AS x_ray,sum(bi_group_total.echo) AS echo,sum(bi_group_total.doppler) AS doppler,sum(bi_group_total.ct) AS ct,sum(bi_group_total.ecg) AS ecg,sum(bi_group_total.mri) AS mri,sum(bi_group_total.path) AS path,sum(bi_group_total.consultation) AS consultationFROM "Reports".bi_group_totalGROUP BY bi_group_total.organization_id, bi_group_total.unit_id, bi_group_total.trandate) grtran ON bi_image_collection.unit_id = grtran.unit_id AND bi_image_collection.depositdate = grtran.trandateGROUP BY bi_image_collection.organization_id, bi_image_collection.unit_id, bi_image_collection.depositdate, grtran.sono, grtran.x_ray, grtran.echo, grtran.doppler, grtran.ct, grtran.ecg, grtran.mri, grtran.path, grtran.consultation;

-- public.billingreport source
CREATE OR REPLACE VIEW public.billingreportAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.patient_id,pr.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN concat(dmem.first_name, ' ', dmem.last_name)ELSE concat(dmadm.first_name, ' ', dmadm.last_name)END::character varying AS doctorname,pc.patient_category,pr.patient_category_id,'\x'::bytea AS image,m_refferel.referral_name AS doctornamenewFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = bm.encounter_idLEFT JOIN doctor.m_doctor_master dmem ON dmem.doctor_id = em.doctor_idLEFT JOIN doctor.m_doctor_master dmadm ON dmadm.doctor_id = ta.admitting_doctor_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN m_patient_category_master pc ON pc.patient_category_id = pr.patient_category_idLEFT JOIN t_referal_details admreff ON bm.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.status = 'A'::"char" AND bdet.status = 'A'::"char";

-- public.billingreport_bi source
CREATE OR REPLACE VIEW public.billingreport_biAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,pm.patient_category,pr.patient_category_id,umm.image,m_refferel.referral_name,COALESCE(m_refferel.referral_id, 0) AS referral_id,org.organization_nameFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idLEFT JOIN m_organization_master org ON umm.organization_id = org.organization_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN t_referal_details admreff ON bm.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.status = 'A'::"char" AND bdet.status = 'A'::"char";

-- public.billingreport_lab source
CREATE OR REPLACE VIEW public.billingreport_labAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.outstanding,concat(mem.first_name, ' ', mem.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.patient_id,pr.uhid_number,bm.gst,pr.patient_category_id,CASEWHEN bm.visit_type_id = 2 THEN ta.admission_numberELSE tem.encounter_numberEND AS opd_ipd_no,payeename.company_desc,bdet.net_amt,bdet.discount + bdet.concession AS discount_amount,bdet.billing_details_id,bdet.quantity,sm.service_standard_name,ssp.sub_speciality_id,ssp.sub_speciality_name,sm.speciality_id,bm.bill_remark,bdet.gross_amount,bm.bill_status_id,0 AS credit,CASEWHEN bm.bill_status_id = 3 THEN bdet.net_amtELSE 0::double precisionEND AS received,CASEWHEN bm.bill_status_id &lt;&gt; 3 THEN bdet.net_amtELSE 0::double precisionEND AS balanceFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN service.m_service_master sm ON sm.service_master_id = bdet.service_idJOIN doctor.m_speciality_master dept ON sm.speciality_id = dept.speciality_idJOIN doctor.m_sub_speciality_master ssp ON ssp.sub_speciality_id = sm.sub_speciality_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idLEFT JOIN m_employee_master mem ON mem.user_id = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master tem ON tem.encounter_id = bm.encounter_idJOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.priority_id = 1 AND bpd.status = 'A'::"char"LEFT JOIN t_company_master payeename ON payeename.company_id = bpd.payee_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.status = 'A'::"char" AND bdet.status = 'A'::"char";

-- public.billingreport_newbilllist source
CREATE OR REPLACE VIEW public.billingreport_newbilllistAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,concat(mem.first_name, ' ', mem.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN concat(dmem.first_name, ' ', dmem.last_name)ELSE concat(dmadm.first_name, ' ', dmadm.last_name)END::character varying AS doctorname,pm.patient_category,pr.patient_category_id,'\x'::bytea AS image,CASEWHEN bm.visit_type_id = 2 THEN m_reffereladm.referral_nameELSE m_refferelen.referral_nameEND AS doctornamenew,vm.visit_type_name::character varying(50) AS visit_type_code,CASEWHEN bm.visit_type_id = 2 THEN ta.admission_numberELSE tem.encounter_numberEND AS opd_ipd_no,CASEWHEN bm.visit_type_id = 2 THEN payeename.company_idELSE payeename1.company_idEND AS company_id,CASEWHEN bm.visit_type_id = 2 THEN payeename.company_descELSE payeename1.company_descEND AS company_desc,CASEWHEN bm.visit_type_id = 2 THEN adm_entilement.payment_entitlement_descELSE opd_entilement.payment_entitlement_descEND AS payment_entitlement_desc,CASEWHEN bm.visit_type_id = 2 THEN adm_entilement.payment_entitlement_idELSE opd_entilement.payment_entitlement_idEND AS payment_entitlement_id,CASEWHEN bm.visit_type_id = 2 THEN ipd_dept.speciality_nameELSE opd_dept.speciality_nameEND AS dept_name,CASEWHEN bm.visit_type_id = 2 THEN ipd_dept.speciality_idELSE opd_dept.speciality_idEND AS speciality_id,CASEWHEN bm.bill_status_id = 1 THEN 'Pending'::textWHEN bm.bill_status_id = 2 THEN 'OnHold'::textELSE 'Settled'::textEND AS bill_status,bm.bill_status_id,CASEWHEN bm.visit_type_id = 2 THEN ta.doctor_idELSE tem.doctor_idEND AS doctor_id,bm.bill_remarkFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idLEFT JOIN m_employee_master mem ON mem.user_id = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN t_referal_details enreff ON bm.encounter_id = enreff.encounter_idLEFT JOIN adt.m_referral_master m_refferelen ON enreff.referral_id = m_refferelen.referral_idLEFT JOIN t_referal_details admreff ON bm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_reffereladm ON admreff.referral_id = m_reffereladm.referral_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master tem ON tem.encounter_id = bm.encounter_idLEFT JOIN doctor.m_doctor_master dmem ON dmem.doctor_id = tem.doctor_idLEFT JOIN doctor.m_doctor_master dmadm ON dmadm.doctor_id = ta.admitting_doctor_idLEFT JOIN opd.t_patient_sponsor_details ON bm.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master adm_entilement ON t_patient_sponsor_details.payment_entitlement_id = adm_entilement.payment_entitlement_idLEFT JOIN opd.t_patient_sponsor_details sp ON bm.encounter_id = sp.encounter_id AND sp.priority_id = 1 AND sp.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master opd_entilement ON sp.payment_entitlement_id = opd_entilement.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = t_patient_sponsor_details.payee_idLEFT JOIN t_company_master payeename1 ON payeename1.company_id = sp.payee_idLEFT JOIN doctor.m_speciality_master opd_dept ON tem.dept_id = opd_dept.speciality_idLEFT JOIN doctor.m_speciality_master ipd_dept ON ta.speciality_id = ipd_dept.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.status = 'A'::"char" AND bdet.status = 'A'::"char";

-- public.billingreport_newbilllist_svh source
CREATE OR REPLACE VIEW public.billingreport_newbilllist_svhAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,concat(mem.first_name, ' ', mem.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN concat(dmem.first_name, ' ', dmem.last_name)ELSE concat(dmadm.first_name, ' ', dmadm.last_name)END::character varying AS doctorname,pm.patient_category,pr.patient_category_id,'\x'::bytea AS image,CASEWHEN bm.visit_type_id = 2 THEN m_reffereladm.referral_nameELSE m_refferelen.referral_nameEND AS doctornamenew,vm.visit_type_name::character varying(50) AS visit_type_code,CASEWHEN bm.visit_type_id = 2 THEN ta.admission_numberELSE tem.encounter_numberEND AS opd_ipd_no,CASEWHEN bm.visit_type_id = 2 THEN payeename.company_idELSE payeename1.company_idEND AS company_id,CASEWHEN bm.visit_type_id = 2 THEN payeename.company_descELSE payeename1.company_descEND AS company_desc,CASEWHEN bm.visit_type_id = 2 THEN adm_entilement.payment_entitlement_descELSE opd_entilement.payment_entitlement_descEND AS payment_entitlement_desc,CASEWHEN bm.visit_type_id = 2 THEN adm_entilement.payment_entitlement_idELSE opd_entilement.payment_entitlement_idEND AS payment_entitlement_id,CASEWHEN bm.visit_type_id = 2 THEN ipd_dept.speciality_nameELSE opd_dept.speciality_nameEND AS dept_name,CASEWHEN bm.visit_type_id = 2 THEN ipd_dept.speciality_idELSE opd_dept.speciality_idEND AS speciality_id,CASEWHEN bm.bill_status_id = 1 THEN 'Pending'::textWHEN bm.bill_status_id = 2 THEN 'OnHold'::textELSE 'Settled'::textEND AS bill_status,bm.bill_status_id,CASEWHEN bm.visit_type_id = 2 THEN ta.doctor_idELSE tem.doctor_idEND AS doctor_id,bm.bill_remark,sm.service_master_id,sm.service_standard_name,bdet.billing_details_id,bdet.quantity,bdet.rate,bdet.discount + bdet.concession AS discount,bdet.gross_amount,bdet.net_amtFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idLEFT JOIN m_employee_master mem ON mem.user_id = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN t_referal_details enreff ON bm.encounter_id = enreff.encounter_idLEFT JOIN adt.m_referral_master m_refferelen ON enreff.referral_id = m_refferelen.referral_idLEFT JOIN t_referal_details admreff ON bm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_reffereladm ON admreff.referral_id = m_reffereladm.referral_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master tem ON tem.encounter_id = bm.encounter_idLEFT JOIN doctor.m_doctor_master dmem ON dmem.doctor_id = tem.doctor_idLEFT JOIN doctor.m_doctor_master dmadm ON dmadm.doctor_id = ta.admitting_doctor_idLEFT JOIN opd.t_patient_sponsor_details ON bm.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master adm_entilement ON t_patient_sponsor_details.payment_entitlement_id = adm_entilement.payment_entitlement_idLEFT JOIN opd.t_patient_sponsor_details sp ON bm.encounter_id = sp.encounter_id AND sp.priority_id = 1 AND sp.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master opd_entilement ON sp.payment_entitlement_id = opd_entilement.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = t_patient_sponsor_details.payee_idLEFT JOIN t_company_master payeename1 ON payeename1.company_id = sp.payee_idLEFT JOIN doctor.m_speciality_master opd_dept ON tem.dept_id = opd_dept.speciality_idLEFT JOIN doctor.m_speciality_master ipd_dept ON ta.speciality_id = ipd_dept.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.status = 'A'::"char" AND bdet.status = 'A'::"char";

-- public.billingreportdetails source
CREATE OR REPLACE VIEW public.billingreportdetailsAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)WHEN bm.visit_type_id = 3 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,reciept_master.reciept_number,reciept_master.date_of_reciept,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,encounterdoctor.first_name,encounterdoctor.last_name,ssm.sub_speciality_name,servicedoctor.first_name AS servicedocfirstname,servicedoctor.last_name AS servicedoclastname,reciept_master.amount,status_master.bill_status_desc,t_company_master.company_desc,m_payment_entitlement_master.payment_entitlement_desc,payeedetails.due_amount,payeename.company_desc AS payee,t_company_master.company_id,payeedetails.payee_id,umm.unit_address_2,bdet.credit_payable,bdet.created_date,bdet.billing_details_id,'\x'::bytea AS image,adm.admission_number,bdet.self_payableFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON adm.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON adm.admission_id = sd.admission_idLEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_idWHERE (bm.visit_type_id = ANY (ARRAY[2, 3])) AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_status_id &lt;&gt; 3UNIONSELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,reciept_master.reciept_number,reciept_master.date_of_reciept,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,encounterdoctor.first_name,encounterdoctor.last_name,ssm.sub_speciality_name,servicedoctor.first_name AS servicedocfirstname,servicedoctor.last_name AS servicedoclastname,reciept_master.amount,status_master.bill_status_desc,t_company_master.company_desc,m_payment_entitlement_master.payment_entitlement_desc,payeedetails.due_amount,payeename.company_desc AS payee,t_company_master.company_id,payeedetails.payee_id,umm.unit_address_2,bdet.credit_payable,bdet.created_date,bdet.billing_details_id,umm.image,em.encounter_number AS admission_number,bdet.self_payableFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON em.encounter_id = sd.encounter_idLEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_idWHERE bm.visit_type_id = 1 AND bm.bill_cancelled = 'N'::bpchar AND bm.bill_status_id &lt;&gt; 3;

-- public.chequereceivedlist source
CREATE OR REPLACE VIEW public.chequereceivedlistAS SELECT DISTINCT pr.uhid_number,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pr.first_name, ''::character varying), ' ', COALESCE(pr.middle_name, ''::character varying), ' ', COALESCE(pr.last_name, ''::character varying)) AS patientname,pr.email,depopaydetail.payment_mode_id,depopaydetail.cheque_number,bm.bank_name,depopaydetail.amount AS deposit_amount,depopaydetail.created_date AS mdate,'Deposit'::text AS label,u.unit_name,u.unit_address_2,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_employee_master.user_id,u.unit_id,u.image,u.unit_addressFROM billing.m_deposit_master depomJOIN billing.t_payment_deposit_details depopaydetail ON depom.deposit_master_id = depopaydetail.deposit_idJOIN patient.t_patient_registration pr ON depom.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN billing.m_bank_master bm ON bm.bank_id = depopaydetail.bank_idJOIN m_unit_master u ON depom.unit_id = u.unit_idLEFT JOIN m_user_master ON depom.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idWHERE depopaydetail.payment_mode_id = 2UNION ALLSELECT DISTINCT pntmst.uhid_number,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,pntmst.email,payrecdetail.payment_mode_id,payrecdetail.check_number AS cheque_number,bm.bank_name,payrecdetail.amount AS deposit_amount,payrecdetail.date_of_transaction AS mdate,'Bill'::text AS label,u.unit_name,u.unit_address_2,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_employee_master.user_id,u.unit_id,u.image,u.unit_addressFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idJOIN billing.t_payment_reciept_master payrecmaster ON payrecmaster.billing_master_id = billmst.billing_master_idJOIN billing.t_payment_reciept_details payrecdetail ON payrecdetail.payment_receipt_master_id = payrecmaster.payment_reciept_idJOIN patient.t_patient_registration pntmst ON billmst.patient_id = pntmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN billing.m_bank_master bm ON bm.bank_id = payrecdetail.bank_idJOIN unitinformation u ON billmst.unit_id = u.unit_idLEFT JOIN m_user_master ON payrecmaster.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idWHERE payrecdetail.payment_mode_id = 2;

-- public.companybillstatus source
CREATE OR REPLACE VIEW public.companybillstatusAS SELECT DISTINCT mcim.company_invoice_id,mcim.invoice_date,mcim.invoice_number,mbm.billing_master_id,mbm.patient_id,tpr.uhid_number,concat(prefix.prefix_desc, '', tpr.first_name, ' ', tpr.last_name) AS patientname,visit.visit_type_id,visit.visit_type_name,CASEWHEN visit.visit_type_id = 1 THEN em.encounter_dateELSE ta.created_dateEND AS visitdate,CASEWHEN visit.visit_type_id = 1 THEN em.encounter_numberELSE ta.admission_numberEND AS visitnumber,CASEWHEN visit.visit_type_id = 1 THEN mvmopd.contract_nameELSE mvmipd.contract_nameEND AS contract_name,cm.company_id,cm.company_desc,mbm.bill_number,mbm.bill_date_time,mbm.total_bill_amount,mbm.discount_amount + mbm.concession_amount AS discount,mbm.net_amount,mbm.outstanding,mbm.total_self_payable,mbm.total_credit_payable,tcid.due_amount,tcid.payable_amount,mbm.net_amount - mbm.outstanding AS paid,CASEWHEN mcim.company_invoice_id IS NULL THEN 'Pending'::textWHEN mcim.due_amount = 0::double precision THEN 'Setteled'::textWHEN (tcid.payable_amount - tcid.due_amount) &lt;&gt; 0::double precision THEN 'Partially Setteled'::textWHEN mcim.company_invoice_id IS NOT NULL AND tcid.payable_amount = tcid.due_amount THEN 'Submitted'::textELSE '-'::textEND AS status,pem.payment_entitlement_id,pem.payment_entitlement_desc,mbm.unit_id,mbm.bill_cancelled,mbm.bill_status_id,CASEWHEN mcim.company_invoice_id IS NULL THEN 1WHEN mcim.due_amount = 0::double precision THEN 2WHEN (tcid.payable_amount - tcid.due_amount) &lt;&gt; 0::double precision THEN 3WHEN mcim.company_invoice_id IS NOT NULL AND tcid.payable_amount = tcid.due_amount THEN 4ELSE 0END AS statusidFROM billing.m_billing_master mbmJOIN patient.t_patient_registration tpr ON tpr.patient_id = mbm.patient_idLEFT JOIN m_prefix_master prefix ON prefix.prefix_id = tpr.prefix_idJOIN m_visit_type_master visit ON visit.visit_type_id = mbm.visit_type_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = mbm.encounter_idLEFT JOIN adt.t_admission ta ON ta.admission_id = mbm.admission_idLEFT JOIN billing.t_company_invoice_details tcid ON mbm.billing_master_id = tcid.bill_idLEFT JOIN billing.m_company_invoice_master mcim ON tcid.company_invoice_id = mcim.company_invoice_idLEFT JOIN m_payment_entitlement_master pem ON pem.payment_entitlement_id = mcim.payment_entitlement_idLEFT JOIN m_patient_visit_metadata mvmopd ON mvmopd.encouter_id = em.encounter_idLEFT JOIN m_patient_visit_metadata mvmipd ON mvmipd.admission_id = ta.admission_idLEFT JOIN t_company_master cm ON mcim.payee_id = cm.company_idLEFT JOIN opd.t_patient_sponsor_details tpsdip ON tpsdip.admission_id = mbm.admission_id AND tpsdip.priority_id = 1 AND tpsdip.payment_entitlement_id &lt;&gt; 1LEFT JOIN opd.t_patient_sponsor_details tpsdop ON tpsdop.encounter_id = mbm.encounter_id AND tpsdop.priority_id = 1 AND tpsdop.payment_entitlement_id &lt;&gt; 1WHERE mbm.bill_status_id &lt;&gt; 3;

-- public.dailydoctorconsultation source
CREATE OR REPLACE VIEW public.dailydoctorconsultationAS SELECT DISTINCT m_billing_master.billing_master_id,t_patient_registration.uhid_number,(t_patient_registration.first_name::text || ' '::text) || t_patient_registration.last_name::text AS patientname,t_patient_registration.mobile_number,t_patient_details.address,t_encounter_master.encounter_number,t_encounter_master.encounter_date,m_billing_master.bill_number,m_billing_master.bill_date_time,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_billing_master.total_bill_amount,m_billing_master.discount_amount,m_billing_master.net_amount,m_service_master.service_standard_name,m_doctor_master.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,t_encounter_master.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,patientinformation.age,patientinformation.gender_name,t_encounter_master.encounter_time,m_service_master.service_master_id AS new_visit_service_id,t_billing_details.service_id,t_billing_details.gross_amount,unitinformation.imageFROM patient.t_patient_registrationJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN opd.t_encounter_master ON t_patient_details.patient_id = t_encounter_master.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_payment_reciept_master ON m_billing_master.billing_master_id = t_payment_reciept_master.billing_master_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN m_user_master ON m_user_master.user_id = m_billing_master.created_byLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN patient.patientinformation ON t_encounter_master.patient_id = patientinformation.patient_idWHERE m_billing_master.visit_type_id = 1 AND m_billing_master.net_amount &lt;&gt; 0::double precision AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.new_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1))UNIONSELECT DISTINCT m_billing_master.billing_master_id,t_patient_registration.uhid_number,(t_patient_registration.first_name::text || ' '::text) || t_patient_registration.last_name::text AS patientname,t_patient_registration.mobile_number,t_patient_details.address,t_encounter_master.encounter_number,t_encounter_master.encounter_date,m_billing_master.bill_number,m_billing_master.bill_date_time,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_billing_master.total_bill_amount,m_billing_master.discount_amount,m_billing_master.net_amount,m_service_master.service_standard_name,m_doctor_master.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,t_encounter_master.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,patientinformation.age,patientinformation.gender_name,t_encounter_master.encounter_time,m_service_master.service_master_id AS new_visit_service_id,t_billing_details.service_id,t_billing_details.gross_amount,unitinformation.imageFROM patient.t_patient_registrationJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN opd.t_encounter_master ON t_patient_details.patient_id = t_encounter_master.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_payment_reciept_master ON m_billing_master.billing_master_id = t_payment_reciept_master.billing_master_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN m_user_master ON m_user_master.user_id = m_billing_master.created_byLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN patient.patientinformation ON t_encounter_master.patient_id = patientinformation.patient_idWHERE m_billing_master.visit_type_id = 1 AND m_billing_master.net_amount &lt;&gt; 0::double precision AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.followup_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1))UNIONSELECT DISTINCT m_billing_master.billing_master_id,t_patient_registration.uhid_number,(t_patient_registration.first_name::text || ' '::text) || t_patient_registration.last_name::text AS patientname,t_patient_registration.mobile_number,t_patient_details.address,t_encounter_master.encounter_number,t_encounter_master.encounter_date,m_billing_master.bill_number,m_billing_master.bill_date_time,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,m_billing_master.total_bill_amount,m_billing_master.discount_amount,m_billing_master.net_amount,m_service_master.service_standard_name,m_doctor_master.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,t_encounter_master.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,patientinformation.age,patientinformation.gender_name,t_encounter_master.encounter_time,m_service_master.service_master_id AS new_visit_service_id,t_billing_details.service_id,t_billing_details.gross_amount,unitinformation.imageFROM patient.t_patient_registrationJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN opd.t_encounter_master ON t_patient_details.patient_id = t_encounter_master.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_encounter_master.doctor_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_payment_reciept_master ON m_billing_master.billing_master_id = t_payment_reciept_master.billing_master_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN m_user_master ON m_user_master.user_id = m_billing_master.created_byLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN patient.patientinformation ON t_encounter_master.patient_id = patientinformation.patient_idWHERE m_billing_master.visit_type_id = 1 AND m_billing_master.net_amount &lt;&gt; 0::double precision AND (m_service_master.service_master_id IN ( SELECT DISTINCT m_doctor_consultation_service_mapper_1.secondary_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1));
-- public.dashboard source
CREATE OR REPLACE VIEW public.dashboardAS SELECT bm.visit_type_id,pmm.payment_mode_id,pmm.payment_mode_desc,sm.service_standard_name,sp.speciality_id,sp.speciality_name,COALESCE(spservice.speciality_id, 0) AS service_grp_id,COALESCE(spservice.speciality_name, 'Other'::character varying) AS service_grp_name,prd.amount,prd.date_of_transactionFROM billing.t_payment_reciept_master rmJOIN billing.t_payment_reciept_details prd ON rm.payment_reciept_id = prd.payment_receipt_master_idJOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idJOIN billing.m_billing_master bm ON bm.billing_master_id = rm.billing_master_idJOIN billing.t_billing_details bd ON bd.billing_master_id = bm.billing_master_idJOIN t_order_details tod ON tod.order_details_id = bd.order_details_idJOIN service.m_service_master sm ON sm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = sm.speciality_idLEFT JOIN doctor.m_speciality_master spservice ON spservice.speciality_id = tod.ord_doc_spl_id;

-- public.depositavilable source
CREATE OR REPLACE VIEW public.depositavilableAS SELECT COALESCE(sum(available_deposit), 0::double precision) AS depositamount,patient_idFROM billing.m_deposit_master dmGROUP BY patient_id;

-- public.dischargeslip source
CREATE OR REPLACE VIEW public.dischargeslipAS SELECT DISTINCT pim.patient_id,pim.uhid_number,pim.patientname,pim.age,pim.gender_name,pim.patientaddress,um.unit_id,um.unit_name,um.unit_contact,um.unit_contact_2,um.unit_address,um.unit_address_2,um.unit_logo,um.unit_website,om.organization_id,om.organization_name,ad.admission_id,ad.admission_number,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,om.organization_address,adet.doa,wm.ward_name,dc.discharge_date,dc.discharge_time,abs(date_part('Year'::text, age(pim.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,bm.bed_desc,temp.template_transaction_id,temp.template_object,um.imageFROM adt.t_discharge dcJOIN adt.t_admission ad ON ad.admission_id = dc.admission_idJOIN patient.patientinformation pim ON pim.patient_id = ad.patient_idJOIN unitinformation um ON dc.unit_id = um.unit_idJOIN m_organization_master om ON dc.organization_id = om.organization_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = ad.doctor_idJOIN m_user_master udm ON dc.created_by = udm.user_idJOIN adt.t_admission_details adet ON dc.admission_id = adet.admission_idJOIN adt.m_ward_master wm ON adet.ward_id = wm.ward_idJOIN adt.m_bed_master bm ON adet.bed_id = bm.bed_idLEFT JOIN t_template_transaction temp ON dc.admission_id = temp.admission_idWHERE dc.status = 'A'::bpchar AND adet.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = ad.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1));
-- public.dischargesummaryreport source
CREATE OR REPLACE VIEW public.dischargesummaryreportAS SELECT DISTINCT dissumm.discharge_summary_id,pim.patient_id,pim.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(pim.first_name, ''::character varying), ' ', COALESCE(pim.middle_name, ''::character varying), ' ', COALESCE(pim.last_name, ''::character varying)) AS patientname,age(pim.dob) AS age,gender.gender_name,tpd.address AS patientaddress,fieldmaster.discharge_field_id,disunit.discharge_changed_name::text AS fieldname,disdetail.discharge_field_description AS dissummary,dissumm.discharge_template_id,dtm.discharge_desc AS templatename,um.unit_id,um.unit_name,um.unit_contact,um.unit_contact_2,um.unit_address,um.unit_address_2,um.unit_logo,um.unit_website,om.organization_id,om.organization_name,ad.admission_id,ad.admission_number,concat('Dr.', dm.first_name, ' ', dm.last_name) AS doctorname,om.organization_address,spm.speciality_name,adet.doa,wm.ward_name,dc.discharge_date,dc.discharge_time,um.image,CASEWHEN disdetail.discharge_field_id = 10 THEN replace(replace(replace(split_part(disdetail.discharge_field_description, '&lt;'::text, 2), 'table ord-det-ids='::text, ''::text), '&gt;'::text, ''::text), ''''::text, ''::text)ELSE '0'::textEND AS order_details_id,disdetail.discharge_summary_detail_id,um.unit_email_id,bm.bed_number,pim.mobile_number,pim.dob,pim.blood_group,concat('Dr', dmuser.first_name, ' ', dmuser.last_name) AS docuser,disunit.discharge_changed_name,disunit.discharge_field_unit_wise_id,td.discharge_summary_temp_mppr_id,concat('Dr.', dmtreat.first_name, ' ', dmtreat.last_name) AS doctornametreat,ad.doctor_id,abs(date_part('Year'::text, age(to_char(pim.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,abs(date_part('Month'::text, age(to_char(pim.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(to_char(pim.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,rdm.discharge_type_name,ad.admitting_doctor_id,qualifdoctor.qualification_desc AS order_docqualification,dmg.degree_desc AS docdegree,qm.qualification_descFROM adt.m_discharge_summary_detail disdetailJOIN adt.m_discharge_summary dissumm ON disdetail.discharge_summary_id = dissumm.discharge_summary_idJOIN adt.m_discharge_summary_field_master fieldmaster ON disdetail.discharge_field_id = fieldmaster.discharge_field_idJOIN adt.m_discharge_summary_template_master dtm ON dtm.discharge_id = dissumm.discharge_template_idJOIN patient.t_patient_registration pim ON dissumm.patient_id = pim.patient_idJOIN patient.t_patient_details tpd ON tpd.patient_id = pim.patient_id AND tpd.status = 'A'::bpcharLEFT JOIN m_prefix_master ON m_prefix_master.prefix_id = pim.prefix_idLEFT JOIN m_gender_master gender ON pim.gender_id = gender.gender_idJOIN m_unit_master um ON dissumm.unit_id = um.unit_idJOIN m_organization_master om ON dissumm.organization_id = om.organization_idJOIN adt.t_admission ad ON ad.admission_id = dissumm.admission_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = ad.admitting_doctor_idLEFT JOIN doctor.m_doctor_master dmtreat ON dmtreat.doctor_id = ad.doctor_idJOIN m_user_master udm ON dissumm.created_by = udm.user_idLEFT JOIN doctor.m_doctor_master dmuser ON dmuser.user_id = udm.user_idJOIN doctor.m_speciality_master spm ON dissumm.department_id = spm.speciality_idJOIN adt.t_admission_details adet ON dissumm.admission_id = adet.admission_idJOIN adt.m_ward_master wm ON adet.ward_id = wm.ward_idJOIN adt.m_bed_master bm ON bm.bed_id = adet.bed_idLEFT JOIN adt.t_discharge dc ON ad.admission_id = dc.admission_id AND dc.status = 'A'::bpcharLEFT JOIN adt.m_reason_for_discharge_master rdm ON rdm.discharge_type_id = dc.discharge_type_idLEFT JOIN m_discharge_field_unit_wise disunit ON disunit.discharge_field_id = fieldmaster.discharge_field_id AND disunit.unit_id = dissumm.unit_id AND disunit.status = 'A'::bpcharLEFT JOIN adt.t_discharge_summary_template_mapper td ON fieldmaster.discharge_field_id = td.discharge_field_id AND td.discharge_summary_temp_id = dissumm.discharge_template_id AND td.unit_id = dissumm.unit_id AND td.status = 'A'::bpcharLEFT JOIN doctor.t_doctor_doc_mapper qualifdoctor ON dmtreat.doctor_id = qualifdoctor.doctor_id AND qualifdoctor.status = 'A'::bpcharLEFT JOIN m_qualification_master qm ON qm.qualification_id = dmtreat.qualification_idLEFT JOIN m_degree_master dmg ON dmg.degree_id = qualifdoctor.degree_idWHERE adet.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = ad.admission_id))ORDER BY td.discharge_summary_temp_mppr_id;

-- public.discountreportcategorywise source
CREATE OR REPLACE VIEW public.discountreportcategorywiseAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,''::text AS reciept_number,''::text AS date_of_reciept,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,ssm.sub_speciality_name,status_master.bill_status_desc,bdet.order_details_id,m_discount_type.type AS discounttype,orderdiscount.discount_category_id,umm.imageFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_details_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN billing.t_order_details_discount orderdiscount ON t_order_details.order_details_id = orderdiscount.order_details_idLEFT JOIN m_discount_type ON orderdiscount.discount_category_id = m_discount_type.id;

-- public.discountreportdetails source
CREATE OR REPLACE VIEW public.discountreportdetailsAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,''::text AS reciept_number,''::text AS date_of_reciept,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,encounterdoctor.first_name,encounterdoctor.last_name,ssm.sub_speciality_name,servicedoctor.first_name AS servicedocfirstname,servicedoctor.last_name AS servicedoclastname,0 AS amount,status_master.bill_status_desc,servicedoctor.doctor_id,bdet.order_details_id,umm.imageFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_details_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_id;

-- public.discountreportdetails_userwise source
CREATE OR REPLACE VIEW public.discountreportdetails_userwiseAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,vm.visit_type_code,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.patient_id,pr.uhid_number,bm.gst,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), COALESCE(emp.first_name, ''::character varying::text::character varying), ' ', COALESCE(emp.last_name, ''::character varying)) AS empname,CASEWHEN reqdis.request_type IS NULL THEN concat(COALESCE(prefix.prefix_desc, ''::character varying::text), COALESCE(emp.first_name, ''::character varying::text::character varying), ' ', COALESCE(emp.last_name, ''::character varying))ELSE concat(COALESCE(prefix.prefix_desc, ''::character varying::text), COALESCE(emp1.first_name, ''::character varying::text::character varying), ' ', COALESCE(emp1.last_name, ''::character varying))END AS requestsendby,CASEWHEN reqdis.request_type IS NULL THEN concat(COALESCE(prefix.prefix_desc, ''::character varying::text), COALESCE(emp.first_name, ''::character varying::text::character varying), ' ', COALESCE(emp.last_name, ''::character varying))ELSE concat(COALESCE(prefix.prefix_desc, ''::character varying::text), COALESCE(emp2.first_name, ''::character varying::text::character varying), ' ', COALESCE(emp2.last_name, ''::character varying))END AS requestsendto,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,ssm.speciality_name,ssm.speciality_id,status_master.bill_status_desc,bdet.order_details_id,umm.image,disstatus.auth_status_desc,distype.category,bm.bill_remark::character varying AS remark,reqdis.disc_type,reqdis.req_status,reqdis.request_typeFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idLEFT JOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master prefix ON emp.prefix_id = prefix.prefix_idLEFT JOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pr ON pr.patient_id = bm.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN doctor.m_speciality_master ssm ON sm.speciality_id = ssm.speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN billing.t_request_discount reqdis ON bm.billing_master_id = reqdis.bill_idLEFT JOIN m_user_master um1 ON reqdis.request_sent_by = um1.user_idLEFT JOIN m_employee_master emp1 ON um1.user_id = emp1.user_idLEFT JOIN m_prefix_master prefix1 ON emp1.prefix_id = prefix1.prefix_idLEFT JOIN billing.t_request_discount reqdis1 ON bm.billing_master_id = reqdis1.bill_idLEFT JOIN m_user_master um2 ON reqdis1.request_sent_to = um2.user_idLEFT JOIN m_employee_master emp2 ON um2.user_id = emp2.user_idLEFT JOIN m_prefix_master prefix2 ON emp2.prefix_id = prefix2.prefix_idLEFT JOIN billing.m_authorization_status_master disstatus ON reqdis.req_status = disstatus.auth_status_idLEFT JOIN m_discount_category distype ON distype.id = reqdis.disc_typeWHERE (bm.discount_amount + bm.concession_amount) &lt;&gt; 0::double precision AND bdet.status = 'A'::"char";

-- public.discountreportdoctorwise source
CREATE OR REPLACE VIEW public.discountreportdoctorwiseAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,um.user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,bm.gst,CASEWHEN bm.visit_type_id = 1 THEN billconsultantdoctorname(bm.encounter_id, 1)WHEN bm.visit_type_id = 2 THEN billconsultantdoctorname(bm.admission_id, 2)ELSE NULL::character varyingEND AS doctorname,bm.bill_status_id,sm.service_standard_name,bdet.discount,bdet.gross_amount,bdet.net_amt,bdet.quantity,bdet.rate,encounterdoctor.first_name,encounterdoctor.last_name,ssm.sub_speciality_name,servicedoctor.first_name AS servicedocfirstname,servicedoctor.last_name AS servicedoclastname,status_master.bill_status_desc,umm.imageFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_id;

-- public.doctorshare source
CREATE OR REPLACE VIEW public.doctorshareAS SELECT share.doctor_share_id,share.bill_dtl_id,share.ord_dtl_id,share.service_id,share.total_amount,share.concession,share.discount,share.tax_amt,share.net_amount,share.share_per,share.due_share_amt,share.hosp_share,share.doc_share,share.doc_id,doctormaster.alise_name,bm.bill_number,sm.service_standard_name,share.visit_type_id,(((prefix.prefix_desc || ''::text) || registration.first_name::text) || ' '::text) || registration.last_name::text AS patientname,share.processed_share_date,registration.uhid_number,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_id,sm.service_master_id,adm.admission_number AS op_ip_number,(('Dr.'::text || ''::text) || (doctormaster.first_name::text || ' '::text)) || doctormaster.last_name::text AS doctorname,bm.bill_status_id,m_unit_master.imageFROM billing.t_doctor_share shareJOIN doctor.m_doctor_master doctormaster ON doctormaster.doctor_id = share.doc_idJOIN billing.t_billing_details bd ON share.bill_dtl_id = bd.billing_details_idJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_id AND bm.bill_cancelled = 'N'::bpcharJOIN service.m_service_master sm ON share.service_id = sm.service_master_idJOIN adt.t_admission adm ON share.admission_id = adm.admission_idJOIN patient.t_patient_registration registration ON adm.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN m_unit_master ON share.org_unit_id = m_unit_master.unit_idJOIN t_order_details od ON share.ord_dtl_id = od.order_details_idUNIONSELECT share.doctor_share_id,share.bill_dtl_id,share.ord_dtl_id,share.service_id,share.total_amount,share.concession,share.discount,share.tax_amt,share.net_amount,share.share_per,share.due_share_amt,share.hosp_share,share.doc_share,share.doc_id,doctormaster.alise_name,bm.bill_number,sm.service_standard_name,share.visit_type_id,(((prefix.prefix_desc || ' '::text) || registration.first_name::text) || ' '::text) || registration.last_name::text AS patientname,share.processed_share_date,registration.uhid_number,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_id,sm.service_master_id,em.encounter_number AS op_ip_number,(('Dr.'::text || ''::text) || (doctormaster.first_name::text || ' '::text)) || doctormaster.last_name::text AS doctorname,bm.bill_status_id,m_unit_master.imageFROM billing.t_doctor_share shareJOIN doctor.m_doctor_master doctormaster ON doctormaster.doctor_id = share.doc_idJOIN billing.t_billing_details bd ON share.bill_dtl_id = bd.billing_details_idJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_id AND bm.bill_cancelled = 'N'::bpcharJOIN service.m_service_master sm ON share.service_id = sm.service_master_idJOIN opd.t_encounter_master em ON share.visit_id = em.encounter_idJOIN patient.t_patient_registration registration ON em.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN m_unit_master ON share.org_unit_id = m_unit_master.unit_idJOIN t_order_details od ON share.ord_dtl_id = od.order_details_id;

-- public.doctorwiseadmittedpatientcount source
CREATE OR REPLACE VIEW public.doctorwiseadmittedpatientcountAS SELECT pr.uhid_number,adde.doa AS admission_date,( SELECT cm_1.company_descFROM opd.t_patient_sponsor_details psd_1JOIN t_company_master cm_1 ON psd_1.payee_id = cm_1.company_idWHERE ad.admission_id = psd_1.admission_idORDER BY psd_1.patient_sponsor_details_id DESCLIMIT 1) AS company_desc,('Dr. '::text || (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text)) || dm.last_name::text AS docname,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_logo,ad.admission_id,ad.admission_number,dm.doctor_id,ad.speciality_id,sp.speciality_name,unitinformation.unit_id,'\x'::bytea AS image,m_payment_entitlement_master.payment_entitlement_desc,m_payment_entitlement_master.payment_entitlement_id,cm.company_id,CASEWHEN cm.company_id = 42 THEN 'É H S'::textWHEN cm.company_id = 39 THEN 'DR.YSR'::textELSE m_payment_entitlement_master.payment_entitlement_descEND AS payment_entitlement_newFROM adt.t_admission adJOIN patient.t_patient_registration pr ON ad.patient_id = pr.patient_idJOIN adt.t_admission_details adde ON ad.admission_id = adde.admission_idJOIN doctor.m_doctor_master dm ON ad.doctor_id = dm.doctor_idLEFT JOIN m_unit_master unitinformation ON ad.unit_id = unitinformation.unit_idLEFT JOIN doctor.m_speciality_master sp ON ad.speciality_id = sp.speciality_idLEFT JOIN opd.t_patient_sponsor_details ON ad.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master cm ON t_patient_sponsor_details.payee_id = cm.company_idWHERE adde.is_cancel = 'N'::bpchar AND adde.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = ad.admission_idORDER BY adde.admission_details_id DESCLIMIT 1))ORDER BY adde.doa;

-- public.get_asset_indent source
CREATE OR REPLACE VIEW public.get_asset_indentAS SELECT indent.id,indent.indent_no,indent.added_date,fromstore.store_name AS fromstore,tostore.store_name AS tostore,indenttype.type AS indenttype,prioritymaster.priority_desc,status.status,approvalstatus.status AS approvalstatus,usermaster.user_name AS addedby,approvedby.user_name AS approvedby,indent.approved_on,indent.remark,m_item.code,m_item.name AS itemname,indentdetail.indent_quantity,indentdetail.approved_indent_quantity,indentdetail.specification,indentdetail.pending_quantity,um.unit_name,um.unit_address,um.imageFROM assets.t_asset_indent indentJOIN assets.t_asset_indent_detail indentdetail ON indent.id = indentdetail.indent_idLEFT JOIN m_store fromstore ON indent.from_store_id = fromstore.store_idLEFT JOIN m_store tostore ON indent.to_store_id = tostore.store_idLEFT JOIN inventory.m_indent_type indenttype ON indent.indent_type_id = indenttype.idLEFT JOIN adt.m_priority_master prioritymaster ON indent.priority_id = prioritymaster.priority_idLEFT JOIN m_status status ON indent.status_id = status.idLEFT JOIN m_status approvalstatus ON indent.approval_status_id = approvalstatus.idLEFT JOIN m_user_master usermaster ON indent.added_by = usermaster.user_idLEFT JOIN m_user_master approvedby ON indent.approved_by = approvedby.user_idLEFT JOIN m_item ON indentdetail.item_id = m_item.idLEFT JOIN m_unit_master um ON indent.unit_id = um.unit_idWHERE indentdetail.is_active = true;

-- public.get_batch_exp_change source
CREATE OR REPLACE VIEW public.get_batch_exp_changeAS SELECT expiry.id,expiry.adjustment_number,expiry.added_date,expiry.added_by,expiry.approved_by,expiry.approved_on,m_store.store_name,m_status.status,approvalstatus.status AS approvalstatus,exp_detail.old_batch_no,exp_detail.new_batch_no,exp_detail.old_batch_expiry,exp_detail.new_batch_expiry,exp_detail.old_mrp,exp_detail.new_mrp,um.user_name AS username,uma.user_name AS usernameapproval,m_item.name AS itemname,m_item.code,unitinformation.unit_name,unitinformation.unit_address,unitinformation.imageFROM inventory.t_batch_exp expiryJOIN inventory.t_batch_exp_detail exp_detail ON expiry.id = exp_detail.batch_expiry_idJOIN m_store ON expiry.store_id = m_store.store_idLEFT JOIN m_status ON expiry.status_id = m_status.idLEFT JOIN m_status approvalstatus ON expiry.approval_status_id = approvalstatus.idJOIN inventory.t_batch batch ON exp_detail.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_user_master um ON expiry.added_by = um.user_idLEFT JOIN m_user_master uma ON expiry.added_by = uma.user_idLEFT JOIN m_unit_master unitinformation ON expiry.unit_id = unitinformation.unit_idWHERE exp_detail.is_active = true;

-- public.get_batch_exp_mrp_adjustment_list source
CREATE OR REPLACE VIEW public.get_batch_exp_mrp_adjustment_listAS SELECT expiry.id,expiry.adjustment_number,expiry.added_date,expiry.added_by,expiry.approved_by,expiry.approved_on,m_store.store_name,m_status.status,approvalstatus.status AS approvalstatus,exp_detail.old_batch_no,exp_detail.new_batch_no,exp_detail.old_batch_expiry,exp_detail.new_batch_expiry,exp_detail.old_mrp,exp_detail.new_mrp,um.login_name AS username,uma.login_name AS usernameapproval,m_item.name AS itemname,m_item.code,unitinformation.unit_name,unitinformation.unit_address,m_status.id AS status_id,unitinformation.unit_id,'\x'::bytea AS imageFROM inventory.t_batch_exp expiryJOIN inventory.t_batch_exp_detail exp_detail ON expiry.id = exp_detail.batch_expiry_idJOIN m_store ON expiry.store_id = m_store.store_idLEFT JOIN m_status ON expiry.status_id = m_status.idLEFT JOIN m_status approvalstatus ON expiry.approval_status_id = approvalstatus.idJOIN inventory.t_batch batch ON exp_detail.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_user_master um ON expiry.added_by = um.user_idLEFT JOIN m_user_master uma ON expiry.added_by = uma.user_idLEFT JOIN m_unit_master unitinformation ON expiry.unit_id = unitinformation.unit_id;

-- public.get_batchwise_stock source
CREATE OR REPLACE VIEW public.get_batchwise_stockAS SELECT DISTINCT t_batch.id,m_item.name,t_batch.batch_no,st.available_qty AS current_bal,t_batch.quantity,t_batch.cop,t_batch.rate,t_batch.lcop AS lending_rate,t_batch.added_date,t_batch.updated_date,t_batch.item_id AS itemid,st.store_id,m_store.store_name,t_batch.expiry_date,fortype.type AS fortype,fortype.id AS typeid,generic.name AS generic_name,m_unit_master.unit_name,m_unit_master.unit_address,m_manufacturer.name AS manufacturer,m_item.hsn_code,m_item.code,vendor.id AS vendorid,vendor.name AS vendor,m_unit_master.unit_id,t_batch.actual_lending_price,rack.name AS rack,rack.id AS rackidFROM inventory.t_store_stock stJOIN inventory.t_batch ON t_batch.id = st.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_storage_unit rack ON rack.id = m_item.storage_unit_idLEFT JOIN m_formulation_type fortype ON m_item.formulation_type_id = fortype.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN m_unit_master ON m_unit_master.unit_id = st.unit_idLEFT JOIN m_manufacturer ON m_manufacturer.id = m_item.manufacturer_idLEFT JOIN procurement.t_good_receipt_note_detail grndet ON st.batch_id = grndet.batch_idLEFT JOIN procurement.t_good_receipt_note grn ON grndet.grn_id = grn.idLEFT JOIN m_vendor vendor ON grn.vendor_id = vendor.idJOIN m_store ON st.store_id = m_store.store_id AND st.available_qty &lt;&gt; 0 AND m_item.is_active = true AND m_item.is_deleted = false;

-- public.get_bill_estimation source
CREATE OR REPLACE VIEW public.get_bill_estimationAS SELECT ce.id,pim.uhid_number,pim.patientname,pim.patientgender,sm.service_standard_name,ced.quantity,ced.total_amt,ced.self_payable,ced.credit_payable,payee.payee_amount,unit.unit_name,unit.unit_address,unit.unit_contact,unit.unit_email_id,unit.unit_website,unit.image,bcm.billing_bed_desc,ce.doa,ce.pdd,ce.created_date,pc.patient_category,abs(date_part('Year'::text, age(pim.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,unit.unit_country_code,unit.unit_contact_2FROM billing.t_cost_estimate ceLEFT JOIN billing.t_cost_estimate_details ced ON ce.id = ced.cost_estimation_idLEFT JOIN billing.t_cost_estimate_details_payee_mapper payee ON ced.id = payee.cost_estimate_details_idLEFT JOIN service.m_service_master sm ON payee.service_id = sm.service_master_idLEFT JOIN patientinformation pim ON ce.patient_id = pim.patient_idLEFT JOIN unitinformation unit ON ce.unit_id = unit.unit_idLEFT JOIN adt.m_billing_bed_category_master bcm ON ce.billing_bed_category_id = bcm.billing_bed_category_idLEFT JOIN m_patient_category_master pc ON ce.patiet_category_id = pc.patient_category_id;

-- public.get_billableconsumption source
CREATE OR REPLACE VIEW public.get_billableconsumptionAS SELECT bc.consumable_number,bc.added_date,m_store.store_name,visittype.visit_type_name,pim.uhid_number,(((pim.patientname || ' | '::text) || pim.ageyear) || ' | '::text) || pim.gender_name::text AS patientdetail,ward.ward_name,bed.bed_desc,usermaster.user_name,bc.id,m_item.code,m_item.name AS itemname,m_generic.name AS generic,uomtype.type AS uomtype,uomunit.unit AS uomunit,batch.batch_no,batch.expiry_date,bcd.consumable_quantity,um.unit_name,um.unit_address,m_item.is_kit,bc.encounter_id,um.imageFROM pharmacy.t_billable_consumption bcJOIN pharmacy.t_billable_consumption_detail bcd ON bc.id = bcd.billable_consumption_idJOIN m_store ON bc.store_id = m_store.store_idJOIN m_visit_type_master visittype ON bc.visit_type_id = visittype.visit_type_idJOIN patientinformation pim ON bc.patient_id = pim.patient_idLEFT JOIN adt.m_ward_master ward ON bc.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON bc.bed_id = bed.bed_idLEFT JOIN m_user_master usermaster ON bc.added_by = usermaster.user_idJOIN inventory.t_batch batch ON bcd.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type uomtype ON bcd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON bcd.uom_unit_id = uomunit.idLEFT JOIN m_unit_master um ON bc.unit_id = um.unit_id;

-- public.get_billableconsumption_return source
CREATE OR REPLACE VIEW public.get_billableconsumption_returnAS SELECT rbc.return_number,rbc.added_date,m_store.store_name,visittype.visit_type_name,pim.uhid_number,(((pim.patientname || ' | '::text) || pim.ageyear) || ' | '::text) || pim.gender_name::text AS patientdetail,ward.ward_name,bed.bed_desc,usermaster.user_name,rbc.id,m_item.code,m_item.name AS itemname,m_generic.name AS generic,uomtype.type AS uomtype,uomunit.unit AS uomunit,batch.batch_no,batch.expiry_date,bcd.consumable_quantity,um.unit_name,um.unit_address,rbcd.return_quantity,um.imageFROM pharmacy.t_return_billable_consumption rbcJOIN pharmacy.t_return_billable_consumption_detail rbcd ON rbc.id = rbcd.returnable_billable_consumption_idJOIN m_store ON rbc.store_id = m_store.store_idJOIN m_visit_type_master visittype ON rbc.visit_type_id = visittype.visit_type_idJOIN patientinformation pim ON rbc.patient_id = pim.patient_idLEFT JOIN adt.m_ward_master ward ON rbc.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON rbc.bed_id = bed.bed_idLEFT JOIN m_user_master usermaster ON rbc.added_by = usermaster.user_idJOIN pharmacy.t_billable_consumption_detail bcd ON rbcd.billable_consumption_detail_id = bcd.idJOIN inventory.t_batch batch ON bcd.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type uomtype ON bcd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON bcd.uom_unit_id = uomunit.idLEFT JOIN m_unit_master um ON rbc.unit_id = um.unit_id;

-- public.get_billcancellation source
CREATE OR REPLACE VIEW public.get_billcancellationAS SELECT pim.uhid_number,pim.patientname,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.discount_amount,bm.net_amount,bm.bill_cancel_by,bm.bill_cancel_datetime,bm.bill_cancel_remark,um.unit_name,um.unit_address,um.image,um.unit_email_id,um.unit_contact,um.unit_idFROM billing.m_billing_master bmJOIN patientinformation pim ON bm.patient_id = pim.patient_idLEFT JOIN m_user_master usermaster ON bm.bill_cancel_by = usermaster.user_idLEFT JOIN unitinformation um ON bm.unit_id = um.unit_idWHERE bm.bill_cancelled = 'Y'::bpchar;

-- public.get_billcancellation_details source
CREATE OR REPLACE VIEW public.get_billcancellation_detailsAS SELECT pim.uhid_number,concat(pm.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.discount_amount,bm.net_amount,bm.bill_cancel_by,bm.bill_cancel_datetime,bm.bill_cancel_remark,um.unit_name,um.unit_address,um.image,um.unit_email_id,um.unit_contact,um.unit_id,bd.billing_details_id,sm.service_master_id,sm.service_standard_name,bd.quantity,bd.rate,bd.discount + bd.concession AS discount,bd.gross_amount,bd.net_amt,bm.visit_type_id,bm.billing_master_id,visit.visit_type_name,mrm.reason_master_id,mrm.reason_desc,concat(emp.first_name, ' ', emp.last_name) AS emp,userm.user_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN patient.t_patient_registration pim ON pim.patient_id = bm.patient_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pim.prefix_idLEFT JOIN m_user_master usermaster ON bm.bill_cancel_by = usermaster.user_idJOIN m_unit_master um ON bm.unit_id = um.unit_idJOIN m_visit_type_master visit ON visit.visit_type_id = bm.visit_type_idLEFT JOIN adt.m_reason_master mrm ON mrm.reason_master_id = bm.bill_cancel_reason_idLEFT JOIN m_user_master userm ON userm.user_id = bm.bill_cancel_byLEFT JOIN m_employee_master emp ON emp.user_id = userm.user_idWHERE bm.bill_cancelled = 'Y'::bpchar AND bd.package_consumption_amt = 0::double precision;

-- public.get_birth_register source
CREATE OR REPLACE VIEW public.get_birth_registerAS SELECT pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS mother_name,nbb.father_name,nbb.uhid_number_baby,nbb.baby_name,nbb.number_of_babies,nbb.delivery_type,nbb.dob,nbb.tob AS timeofbirth,gen.gender_code,pr.created_date,u.unit_name,u.unit_address,u.unit_contact,u.unit_idFROM patient.t_patient_registration prJOIN m_new_born_baby_reg nbb ON pr.patient_id = nbb.patient_idJOIN m_gender_master gen ON gen.gender_id = pr.gender_idJOIN unitinformation u ON nbb.unit_id = u.unit_id;

-- public.get_cash_handover source
CREATE OR REPLACE VIEW public.get_cash_handoverAS SELECT handover.id,handover.date,handover.cob_number,handover.cash_handover_by_id,handover.cash_handover_to_id,handover.cash_handover_amount,handover.shift_close,deno.denomination,deno.quantity,deno.amount,um.user_name AS userfrom,umto.user_name AS userto,unit.unit_id,unit.unit_name,unit.unit_address,unit.imageFROM t_cash_handover_details handoverLEFT JOIN t_denomination_details deno ON handover.id = deno.cash_handover_transaction_idLEFT JOIN m_user_master um ON handover.cash_handover_by_id = um.user_idLEFT JOIN m_user_master umto ON handover.cash_handover_to_id = umto.user_idLEFT JOIN unitinformation unit ON unit.unit_id = handover.unit_idWHERE deno.status::text = 'A'::text;

-- public.get_company_details source
CREATE OR REPLACE VIEW public.get_company_detailsAS SELECT cm.company_code,cm.company_desc,cm.credit_limit,cm.contact_person_name,cm.address,cm.mobile_no,cm.email_id,cm.fax_no,cm.start_date,cm.end_date,ctm.company_type_desc,u.unit_name,u.unit_address,u.unit_contact,cm.unit_id,cm.company_type_id,u.imageFROM t_company_master cmLEFT JOIN m_company_type_master ctm ON cm.company_type_id = ctm.company_type_idLEFT JOIN unitinformation u ON cm.unit_id = u.unit_idWHERE cm.status = 'A'::"char";

-- public.get_companysettlement source
CREATE OR REPLACE VIEW public.get_companysettlementAS SELECT DISTINCT billing_master.billing_master_id,compnayrecmaster.company_receipt_id,compnayrecmaster.company_receipt_number,compnayrecmaster.company_receipt_date,companyrecdetail.net_receipt_amount,companyrecdetail.tds_amount,companyrecdetail.total_amount,billing_master.bill_number,billing_master.bill_date_time,billing_master.total_bill_amount,billing_master.outstanding,pr.uhid_number,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,company.company_desc,COALESCE(deposit_master.consumed_deposit, 0::double precision) AS consumed_deposit,entitlement_master.payment_entitlement_desc,paydetail.amount,paydetail.payment_mode_id,paymode.payment_mode_desc,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,company.company_id,entitlement_master.payment_entitlement_id,billing_master.net_amount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,'\x'::bytea AS image,billing_master.discount_amount + billing_master.concession_amount AS discount_amount,billing_master.total_credit_payableFROM billing.m_company_receipt_master compnayrecmasterJOIN billing.t_company_receipt_detail companyrecdetail ON compnayrecmaster.company_receipt_id = companyrecdetail.company_receipt_idJOIN billing.t_payment_reciept_master paymaster ON paymaster.payment_reciept_id = compnayrecmaster.receipt_idJOIN billing.t_payment_reciept_details paydetail ON paymaster.payment_reciept_id = paydetail.payment_receipt_master_idJOIN billing.t_company_invoice_details invoice_details ON companyrecdetail.company_invoice_detail_id = invoice_details.company_invoice_detail_idJOIN billing.m_company_invoice_master invoice_master ON invoice_details.company_invoice_id = invoice_master.company_invoice_idJOIN billing.m_billing_master billing_master ON invoice_details.bill_id = billing_master.billing_master_idJOIN patient.t_patient_registration pr ON pr.patient_id = billing_master.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idJOIN t_company_master company ON company.company_id = invoice_details.bill_payee_idLEFT JOIN billing.m_deposit_master deposit_master ON billing_master.billing_master_id = deposit_master.bill_idLEFT JOIN m_payment_entitlement_master entitlement_master ON invoice_master.payment_entitlement_id = entitlement_master.payment_entitlement_idLEFT JOIN m_payment_mode_master paymode ON paydetail.payment_mode_id = paymode.payment_mode_idJOIN m_user_master um ON compnayrecmaster.created_by = um.user_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idLEFT JOIN m_unit_master unitinformation ON compnayrecmaster.unit_id = unitinformation.unit_idWHERE paymaster.status::text = 'A'::"char"::textORDER BY compnayrecmaster.company_receipt_id;

-- public.get_companytds source
CREATE OR REPLACE VIEW public.get_companytdsAS SELECT receipt_master.company_receipt_number,receipt_master.company_receipt_date,receipt_master.receipt_amount,entitlement_master.payment_entitlement_desc,company.company_desc,receipt_master.tds_amount,receipt_master.net_receipt_amount,unit.unit_name,unit.unit_address,receipt_master.payee_id,unit.unit_idFROM billing.m_company_receipt_master receipt_masterJOIN m_payment_entitlement_master entitlement_master ON receipt_master.payment_entitlement_id = entitlement_master.payment_entitlement_idJOIN t_company_master company ON receipt_master.payee_id = company.company_idLEFT JOIN unitinformation unit ON receipt_master.unit_id = unit.unit_idWHERE receipt_master.tds_amount &lt;&gt; 0::double precision;

-- public.get_confirm_stock source
CREATE OR REPLACE VIEW public.get_confirm_stockAS SELECT cs.id,cs.stock_adjustment_no,cs.added_date,m_store.store_name,um.user_name,m_status.status,m_item.name AS itemname,batch.batch_no,batch.expiry_date,batch.current_quantity,batch.quantity,storestock.available_qty,batch.rate,batch.cop,storestock.available_qty::double precision * batch.cop AS totalcop,storestock.available_qty::double precision * batch.rate AS toalmrp,batch.current_quantity - storestock.available_qty AS difference_in_stock,(batch.current_quantity - storestock.available_qty)::double precision * batch.cop AS variance_at_cop,(batch.current_quantity - storestock.available_qty)::double precision * batch.rate AS variance_at_priceFROM inventory.t_confirm_stock csJOIN inventory.t_confirm_stock_detail csd ON cs.id = csd.confirm_stock_idJOIN m_store ON cs.store_id = m_store.store_idLEFT JOIN m_user_master um ON cs.added_by = um.user_idLEFT JOIN m_status ON cs.status_id = m_status.idJOIN inventory.t_batch batch ON csd.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idJOIN inventory.t_store_stock storestock ON batch.id = storestock.batch_id AND m_store.store_id = storestock.store_idWHERE csd.is_active = true;

-- public.get_consent_template source
CREATE OR REPLACE VIEW public.get_consent_templateAS SELECT DISTINCT tpcm.consent_transaction_id,tpcm.template_desc,ta.admission_number,pimipd.uhid_number,concat(prefixipd.prefix_desc, '', pimipd.first_name, ' ', pimipd.last_name) AS patientname,CASEWHEN pimipd.gender_id = 1 THEN 'Male'::textELSE 'Female'::textEND AS gender,abs(date_part('Year'::text, age(pimipd.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('Month'::text, age(pimipd.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pimipd.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,concat('Dr.', docmaster.first_name, ' ', docmaster.last_name) AS doctorname,sp.speciality_name,um.unit_id,um.unit_name,um.unit_address,um.image,tpcm.created_dateFROM t_patient_consent_mapper tpcmJOIN adt.m_consent_master mcm ON tpcm.consent_master_id = mcm.consent_master_idJOIN adt.m_consent_type_master ctm ON mcm.consent_type_id = ctm.consent_type_master_idJOIN adt.t_admission ta ON ta.admission_id = tpcm.admission_idJOIN patient.t_patient_registration pimipd ON pimipd.patient_id = ta.patient_idJOIN m_prefix_master prefixipd ON prefixipd.prefix_id = pimipd.prefix_idJOIN doctor.m_doctor_master docmaster ON ta.admitting_doctor_id = docmaster.doctor_idJOIN doctor.m_speciality_master sp ON ta.speciality_id = sp.speciality_idJOIN m_unit_master um ON um.unit_id = ta.unit_idWHERE tpcm.status = 'A'::bpcharUNIONSELECT DISTINCT tpcm.consent_transaction_id,tpcm.template_desc,tem.encounter_number AS admission_number,pimopd.uhid_number,concat(prefixopd.prefix_desc, '', pimopd.first_name, ' ', pimopd.last_name) AS patientname,CASEWHEN pimopd.gender_id = 1 THEN 'Male'::textELSE 'Female'::textEND AS gender,abs(date_part('Year'::text, age(pimopd.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('Month'::text, age(pimopd.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pimopd.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,concat('Dr.', docmaster.first_name, ' ', docmaster.last_name) AS doctorname,sp.speciality_name,um.unit_id,um.unit_name,um.unit_address,um.image,tpcm.created_dateFROM t_patient_consent_mapper tpcmJOIN adt.m_consent_master mcm ON tpcm.consent_master_id = mcm.consent_master_idJOIN adt.m_consent_type_master ctm ON mcm.consent_type_id = ctm.consent_type_master_idJOIN opd.t_encounter_master tem ON tem.encounter_id = tpcm.encounter_idJOIN patient.t_patient_registration pimopd ON pimopd.patient_id = tem.patient_idJOIN m_prefix_master prefixopd ON prefixopd.prefix_id = pimopd.prefix_idJOIN doctor.m_doctor_master docmaster ON tem.doctor_id = docmaster.doctor_idJOIN doctor.m_speciality_master sp ON tem.dept_id = sp.speciality_idJOIN m_unit_master um ON um.unit_id = tem.unit_idWHERE tpcm.status = 'A'::bpchar;

-- public.get_consignment_inward_details source
CREATE OR REPLACE VIEW public.get_consignment_inward_detailsAS SELECT ci.id,ci.inward_number,ci.added_date,s.store_name,v.name AS vendor_name,ci.remark,(((em1.first_name::text || ' '::text) || em1.middle_name::text) || ' '::text) || em1.last_name::text AS inwordby,m_status.status,i.code,i.name AS itemname,cid.batch_number,cid.expiry_date,cid.quantity,cid.cop,cid.tax_percentage,cid.total_amount,cid.discount_amount,cid.tax_amount,cid.net_amount,uom_unit.unit,u.unit_name,u.unit_address,u.unit_contact,u.imageFROM procurement.t_consignment_inward ciJOIN procurement.t_consignment_inward_detail cid ON ci.id = cid.inward_idJOIN m_store s ON ci.store_id = s.store_idJOIN m_vendor v ON ci.vendor_id = v.idLEFT JOIN m_employee_master em1 ON ci.added_by = em1.user_idJOIN m_status ON ci.status_id = m_status.idLEFT JOIN m_item i ON cid.item_id = i.idLEFT JOIN m_uom_unit uom_unit ON cid.uom_unit_id = uom_unit.idLEFT JOIN m_unit_master u ON ci.unit_id = u.unit_idWHERE cid.is_active = true;

-- public.get_crashcartrequest source
CREATE OR REPLACE VIEW public.get_crashcartrequestAS SELECT req.id,req.crash_cart_no,req.code_blue_date_time,m_store.store_name,visit.visit_type_name,CASEWHEN visit.visit_type_id = 1 THEN em.encounter_numberWHEN visit.visit_type_id = 2 THEN adm.admission_numberELSE NULL::character varyingEND AS visitno,pim.uhid_number,pim.patientname,((('Dr.'::text || ' '::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctorname,ward.ward_name,bed.bed_number,um.user_name,m_status.status,m_item.name,uomtype.type AS uomtype,uomunit.unit,request_detail.required_quantity,unitmaster.unit_name,unitmaster.unit_address,m_item.code,req.added_date,unitmaster.imageFROM pharmacy.t_crash_cart_request reqJOIN m_store ON req.store_id = m_store.store_idJOIN m_visit_type_master visit ON req.visit_type_id = visit.visit_type_idLEFT JOIN adt.t_admission adm ON req.admission_id = adm.admission_idJOIN patientinformation pim ON req.patient_id = pim.patient_idLEFT JOIN opd.t_encounter_master em ON req.encounter_id = em.encounter_idLEFT JOIN doctor.m_doctor_master docmaster ON req.doctor_id = docmaster.doctor_idLEFT JOIN adt.m_ward_master ward ON req.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON req.bed_id = bed.bed_idLEFT JOIN m_user_master um ON req.added_by = um.user_idLEFT JOIN m_status ON req.status_id = m_status.idJOIN pharmacy.t_crash_cart_request_detail request_detail ON req.id = request_detail.crash_cart_idLEFT JOIN m_item ON request_detail.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON request_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON request_detail.uom_unit_id = uomunit.idLEFT JOIN unitinformation unitmaster ON req.unit_id = unitmaster.unit_id;

-- public.get_death_register source
CREATE OR REPLACE VIEW public.get_death_registerAS SELECT dr.death_registration_id,(dr.first_name::text || ' '::text) || dr.last_name::text AS name,gm.gender_name,dr.mark_on_decease,dr.date_of_death,dr.is_medico_legal,u.unit_name,u.unit_address,u.unit_contact,dr.created_date,dr.uhid_number AS registration_no,u.unit_id,u.imageFROM patient.t_death_registration drLEFT JOIN m_gender_master gm ON dr.gender_id = gm.gender_idJOIN unitinformation u ON dr.unit_id = u.unit_idWHERE dr.status = 'A'::bpchar;

-- public.get_departmentwise_revenue source
CREATE OR REPLACE VIEW public.get_departmentwise_revenueAS SELECT DISTINCT pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS p_name,''::text AS service_standard_name,0 AS rate,0 AS service_id,CASEWHEN emm.dept_id &lt;&gt; 0 THEN smopd.speciality_nameWHEN COALESCE(emm.dept_id, 0) = 0 THEN 'Other'::character varyingELSE smipd.speciality_nameEND AS speciality_name,billmst.bill_number,billmst.bill_date_time,0 AS ord_doc_id,''::text AS first_name,''::text AS last_name,billmst.visit_type_id,billmst.unit_id,'2019-01-01 00:00:00'::timestamp without time zone AS orderdate,(((em.first_name::text || ' '::text) || em.middle_name::text) || ' '::text) || em.last_name::text AS username,u.unit_name,u.unit_address,u.unit_contact,''::text AS sub_speciality_name,CASEWHEN emm.dept_id &lt;&gt; 0 THEN smopd.speciality_idELSE smipd.speciality_idEND AS speciality_id,prd.amount AS net_amt,prm.date_of_reciept,'Bill'::text AS label,prm.reciept_number,prd.payment_reciept_details_id,'\x'::bytea AS imageFROM billing.m_billing_master billmstLEFT JOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN patient.t_patient_registration pr ON billmst.patient_id = pr.patient_idLEFT JOIN m_employee_master em ON billmst.created_by = em.user_idLEFT JOIN m_unit_master u ON billmst.unit_id = u.unit_idJOIN billing.t_payment_reciept_master prm ON billmst.billing_master_id = prm.billing_master_idJOIN billing.t_payment_reciept_details prd ON prm.payment_reciept_id = prd.payment_receipt_master_idLEFT JOIN opd.t_encounter_master emm ON billmst.encounter_id = emm.encounter_idLEFT JOIN adt.t_admission ON billmst.admission_id = t_admission.admission_idLEFT JOIN doctor.m_speciality_master smopd ON smopd.speciality_id = emm.dept_idLEFT JOIN doctor.m_speciality_master smipd ON smipd.speciality_id = t_admission.speciality_idWHERE billmst.bill_status_id = ANY (ARRAY[3, 2]);
-- public.get_departmentwise_revenue_summary source
CREATE OR REPLACE VIEW public.get_departmentwise_revenue_summaryAS SELECT NULL::integer AS unit_id,NULL::character varying(200) AS unit_name,NULL::text AS unit_address,NULL::character varying(200) AS unit_contact,NULL::character varying AS speciality_name,NULL::integer AS speciality_id,NULL::double precision AS net_amt,NULL::timestamp without time zone AS date_of_reciept,NULL::bytea AS image;

-- public.get_doctor_details source
CREATE OR REPLACE VIEW public.get_doctor_detailsAS SELECT DISTINCT pm.prefix_desc,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doc_name,dm.mobile_number,dm.email,sm.speciality_name,ssm.sub_speciality_name,dm.registration_number,dm.doc_code,gm.gender_name,u.unit_name,u.unit_address,u.unit_contact,dm.status,dm.is_rmo,dm.unit_id,u.imageFROM doctor.m_doctor_master dmLEFT JOIN m_prefix_master pm ON dm.prefix_id = pm.prefix_idLEFT JOIN m_gender_master gm ON dm.gender_id = gm.gender_idJOIN unitinformation u ON dm.unit_id = u.unit_idLEFT JOIN doctor.t_doctor_speciality_mapper tdsm ON dm.doctor_id = tdsm.doctor_idLEFT JOIN doctor.t_doctor_sub_speciality_mapper tdssm ON dm.doctor_id = tdssm.doctor_idLEFT JOIN doctor.m_speciality_master sm ON tdsm.speciality_id = sm.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON tdssm.sub_speciality_id = ssm.sub_speciality_idWHERE tdsm.status = 'A'::bpchar AND tdssm.status = 'A'::bpchar;

-- public.get_doctor_payment source
CREATE OR REPLACE VIEW public.get_doctor_paymentAS SELECT DISTINCT concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) AS ledger,log.processed_amt,log.retainer_ship_amt,log.paid_amt,log.created_date::date AS trans_date,log.org_id AS orgid,log.org_unit_id AS unitid,dm.doctor_id,unit.unit_name,unit.unit_address,unit.unit_id,unit.imageFROM billing.t_doc_share_voucher dsvJOIN billing.t_doc_share_voucher_dtls dsvd ON dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idJOIN billing.t_doctor_share ds ON ds.doctor_share_id = dsvd.doctor_share_idJOIN billing.t_doc_share_payment_voucher_logger log ON log.voucher_no::text = dsv.voucher_no::textJOIN doctor.m_doctor_master dm ON dm.doctor_id = ds.doc_idLEFT JOIN unitinformation unit ON dsv.org_unit_id = unit.unit_id;

-- public.get_doctorvoucher source
CREATE OR REPLACE VIEW public.get_doctorvoucherAS SELECT DISTINCT voucher.doc_share_vouche_id,voucher.voucher_no,voucher.total_doc_share_amout,voucher.processed_amt,voucher.due_share_amt,doctormaster.first_name,doctormaster.last_name,voucher.created_date,share.doc_id,unit.unit_name,unit.unit_address,unit.unit_id,unit.imageFROM billing.t_doc_share_voucher voucherJOIN billing.t_doc_share_voucher_dtls voucherdetail ON voucher.doc_share_vouche_id = voucherdetail.doc_share_vouche_idLEFT JOIN billing.t_doctor_share share ON voucherdetail.doctor_share_id = share.doctor_share_idJOIN doctor.m_doctor_master doctormaster ON share.doc_id = doctormaster.doctor_idLEFT JOIN unitinformation unit ON voucher.org_unit_id = unit.unit_id;

-- public.get_doctorwisepatientcount source
CREATE OR REPLACE VIEW public.get_doctorwisepatientcountAS SELECT om.organization_name,um.unit_name,en.appointment_id,en.encounter_date::date AS trandate,concat(dm.first_name, ' ', dm.last_name) AS doctor,sp.speciality_name,'OPD'::text AS labels,en.organization_id,'\x'::bytea AS imageFROM opd.t_encounter_master enJOIN doctor.m_speciality_master sp ON en.dept_id = sp.speciality_idJOIN doctor.m_doctor_master dm ON en.doctor_id = dm.doctor_idJOIN m_organization_master om ON en.organization_id = om.organization_idJOIN m_unit_master um ON en.unit_id = um.unit_idUNIONSELECT om.organization_name,um.unit_name,adm.admission_id AS appointment_id,adm.created_date::date AS trandate,concat(dm.first_name, ' ', dm.last_name) AS doctor,sp.speciality_name,'IPD'::text AS labels,adm.organization_id,'\x'::bytea AS imageFROM adt.t_admission admJOIN doctor.m_speciality_master sp ON adm.speciality_id = sp.speciality_idJOIN doctor.m_doctor_master dm ON adm.admitting_doctor_id = dm.doctor_idJOIN m_organization_master om ON adm.organization_id = om.organization_idJOIN m_unit_master um ON adm.unit_id = um.unit_id;

-- public.get_doctorwisepatientcount_total source
CREATE OR REPLACE VIEW public.get_doctorwisepatientcount_totalAS SELECT labels,organization_name,unit_name,doctor,speciality_name,trandate,count(appointment_id) AS totalFROM get_doctorwisepatientcountGROUP BY labels, organization_name, unit_name, doctor, speciality_name, trandate;

-- public.get_drug_recall source
CREATE OR REPLACE VIEW public.get_drug_recallAS SELECT recall.id,recall.recall_no,recall.added_date,reqtype.type AS reqtype,m_status.status,um.user_name,m_item.code,m_item.name,recalldetail.reason,unit.unit_name,unit.unit_address,unit.imageFROM inventory.t_drug_recall recallJOIN inventory.t_drug_recall_detail recalldetail ON recall.id = recalldetail.drug_recall_idLEFT JOIN m_request_type reqtype ON recall.request_type_id = reqtype.idLEFT JOIN m_status ON recall.status_id = m_status.idLEFT JOIN m_user_master um ON recall.added_by = um.user_idLEFT JOIN m_item ON recalldetail.item_id = m_item.idLEFT JOIN m_unit_master unit ON recall.unit_id = unit.unit_idWHERE recalldetail.is_active = true;

-- public.get_employee_details source
CREATE OR REPLACE VIEW public.get_employee_detailsAS SELECT pm.prefix_desc,(((em.first_name::text || ' '::text) || em.middle_name::text) || ' '::text) || em.last_name::text AS e_name,gm.gender_name,em.mobile_number,em.email,em.emp_code,sm.speciality_name,ssm.sub_speciality_name,em.registration_number,em.status,u.unit_name,u.unit_address,u.unit_contact,em.unit_id,u.imageFROM m_employee_master emLEFT JOIN m_prefix_master pm ON em.prefix_id = pm.prefix_idLEFT JOIN m_gender_master gm ON em.gender_id = gm.gender_idLEFT JOIN doctor.m_speciality_master sm ON em.speciality_id = sm.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON em.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN unitinformation u ON em.unit_id = u.unit_id;

-- public.get_enquiry_sendto_vendor source
CREATE OR REPLACE VIEW public.get_enquiry_sendto_vendorAS SELECT DISTINCT vq.id,qr.qr_no,qr.added_date,qr.added_by,vq.vq_number,vq.added_date AS vqdate,m_store.store_name,m_vendor.name AS vendor,vq.due_date,m_status.status,statusapp.status AS statusapp,m_item.code,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,qrd.quantity,qrd.expected_support_term,um.user_name,unit.unit_name,unit.unit_address,qrd.expected_payment,qrd.expected_technical_specification,unit.imageFROM procurement.t_quotation_request qrLEFT JOIN procurement.t_quotation_request_detail qrd ON qr.id = qrd.qr_idLEFT JOIN procurement.t_quotation_vendor vq ON qr.id = vq.qr_idLEFT JOIN m_store ON vq.store_id = m_store.store_idLEFT JOIN m_vendor ON vq.vendor_id = m_vendor.idLEFT JOIN m_status ON vq.status_id = m_status.idLEFT JOIN m_status statusapp ON vq.approval_status_id = statusapp.idLEFT JOIN m_item ON qrd.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON qrd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON qrd.uom_unit_id = uomunit.idLEFT JOIN m_user_master um ON vq.added_by = um.user_idLEFT JOIN m_unit_master unit ON vq.unit_id = unit.unit_idWHERE qrd.is_active = true;

-- public.get_expired_patientstatistics source
CREATE OR REPLACE VIEW public.get_expired_patientstatisticsAS SELECT pim.patient_id,pim.patientname,pim.gender_name,pim.patient_category,distype.discharge_type_id,distype.discharge_type_name,disstatus.discharge_status_id,disstatus.discharge_desc,ward.ward_name,discharge.discharge_date,unit.unit_name,unit.unit_address,pim.uhid_number,unit.unit_id,unit.imageFROM adt.t_discharge dischargeJOIN adt.m_reason_for_discharge_master distype ON discharge.discharge_type_id = distype.discharge_type_idJOIN adt.t_admission adm ON discharge.admission_id = adm.admission_idJOIN adt.t_admission_details admdetail ON adm.admission_id = admdetail.admission_idJOIN patientinformation pim ON adm.patient_id = pim.patient_idLEFT JOIN adt.m_ward_master ward ON admdetail.ward_id = ward.ward_idJOIN adt.m_discharge_status_master disstatus ON discharge.discharge_status_id = disstatus.discharge_status_idLEFT JOIN unitinformation unit ON discharge.unit_id = unit.unit_idWHERE distype.discharge_type_id = 3 AND admdetail.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adm.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1));
-- public.get_haemodailysisdetails source
CREATE OR REPLACE VIEW public.get_haemodailysisdetailsAS SELECT DISTINCT orderdetail.order_details_id AS orderdetailsid,sm.slot_id AS slotid,admission.admission_id AS admissionid,appmstr.appointment_id AS appointmentid,orderdetail.ord_doc_id AS orddoctorid,orderdetail.status,orderdetail.service_rendered AS servicerendered,patientreg.patient_id AS patientid,patientreg.uhid_number AS uhidnumber,patientreg.gender_id AS genderid,gendermaster.gender_code AS gendercode,to_char(patientreg.dob, 'DD-MM-YYYY HH:mm:ss'::text) AS dob,concat(date_part('year'::text, age(CURRENT_TIMESTAMP, patientreg.dob::timestamp with time zone)), 'Y ', date_part('month'::text, age(CURRENT_TIMESTAMP, patientreg.dob::timestamp with time zone)), 'M ', date_part('day'::text, age(CURRENT_TIMESTAMP, patientreg.dob::timestamp with time zone)), 'D ') AS agestring,encountermaster.encounter_id AS encounterid,encountermaster.doctor_id AS doctorid,(((('Dr. '::text || COALESCE(doctormaster.first_name)::text) || ' '::text) || COALESCE(doctormaster.middle_name)::text) || ' '::text) || COALESCE(doctormaster.last_name)::text AS doctorname,(((COALESCE(doctormasterip.first_name)::text || ' '::text) || COALESCE(doctormasterip.middle_name)::text) || ' '::text) || COALESCE(doctormasterip.last_name)::text AS admittingdoctorname,encountermaster.dept_id AS specialityid,specmaster.speciality_name AS specialityname,servicemaster.service_standard_name AS servicename,servicemaster.service_master_id AS serviceid,servicemaster.service_standard_code AS servicecode,orderdetail.priority_id AS priorityid,ordermaster.order_no AS orderno,to_char(dtl.doa, 'DD/MM/YYYY'::text) AS doa,to_char(dtl.pdd, 'DD/MM/YYYY'::text) AS pdd,to_char(orderdetail.order_date, 'dd/mm/yyyy'::text) AS orderdate,(((((prefixmaster.prefix_code::text || ' '::text) || COALESCE(patientreg.first_name)::text) || ' '::text) || COALESCE(patientreg.middle_name)::text) || ' '::text) || COALESCE(patientreg.last_name)::text AS patientname,bedmstr.bed_number AS bednumber,0 AS frombedid,orderdetail.accession_number AS accessionnumber,ordermaster.visit_type_id AS visittypeid,patientreg.identification_number AS identificationnumber,vm.visit_type_name AS visitname,pcm.patient_category AS patientcategory,encountermaster.encounter_number AS visitnumber,cm.country_code AS countrycode,sm.bed_id AS tobedid,bm.bed_number AS tobednumber,to_char(sm.from_time::interval, 'HH:MI'::text) AS appointmenttime,bm.ward_id AS towardid,bm.room_id AS toroomid,bedmstr.ward_id AS fromwardid,bedmstr.room_id AS fromroomid,to_char(orderdetail.order_date, 'DD/MM/YYYY'::text) AS appointmentdate,wm.ward_name AS wardname,hemodialysismapper.dialysis_app_mapper_id AS dialysisappmapperid,hemodialysismapper.chair_id AS chairid,hemodialysismapper.doctor_id AS dialysisdoctorid,hemodialysismapper.workbench_acceptance AS hemodialysisworkbenchacceptance,bm.bed_number AS chairname,hemodialysismapper.technician_acceptance AS technicianacceptance,hemodialysismapper.technician_id AS technicianid,concat(employeemaster.first_name, ' ', employeemaster.middle_name, ' ', employeemaster.last_name) AS technicianname,hemodialysismapper.machine_id AS machineid,itemmaster.name AS machinename,hemodialysismapper.dialysis_status_id AS dialysisstatusid,( SELECT to_char(pdr.dialysis_start_date, 'DD/MM/YYYY'::text) AS to_charFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_idLIMIT 1) AS dialysisstartdate,( SELECT to_char(pdr.dialysis_start_time::interval, 'HH24:MI'::text) AS to_charFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_idLIMIT 1) AS dialysisstarttime,( SELECT to_char(pdr.created_date, 'DD/MM/YYYY'::text) AS to_charFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dialysisenddate,( SELECT to_char(pdr.dialysis_end_time::interval, 'HH24:MI'::text) AS to_charFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dialysisendtime,admission.admission_number,( SELECT pdr.dialysis_event_idFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dialysis_event_id,( SELECT pdr.dialysis_durationFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dialysis_duration,( SELECT pdr.dia_net_ultraficationFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dia_net_ultrafication,( SELECT pdr.dia_vascular_access_typeFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dia_vascular_access_type,( SELECT pdr.dia_ktv_resultFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS dia_ktv_result,ordermaster.admission_id,( SELECT (date_part('day'::text, pdr.dialysis_start_date - pdr.dialysis_start_date) * 24::double precision + date_part('hour'::text, pdr.dialysis_end_time - pdr.dialysis_start_time)) * 60::double precision + date_part('minute'::text, pdr.dialysis_end_time - pdr.dialysis_start_time) AS minutessFROM patient.t_patient_dialysis_record pdrWHERE pdr.appointment_id = hemodialysismapper.appointment_idORDER BY pdr.patient_dialysis_rec_id DESCLIMIT 1) AS minutess,um.unit_name,um.unit_address,um.imageFROM opd.t_hemodialysis_appointment_mapper hemodialysismapperJOIN t_order_details orderdetail ON orderdetail.order_details_id = hemodialysismapper.order_details_idJOIN t_order_master ordermaster ON orderdetail.order_id = ordermaster.order_idJOIN patient.t_patient_registration patientreg ON ordermaster.patient_id = patientreg.patient_idJOIN m_prefix_master prefixmaster ON patientreg.prefix_id = prefixmaster.prefix_idJOIN m_gender_master gendermaster ON patientreg.gender_id = gendermaster.gender_idJOIN patient.t_patient_details patdtl ON patdtl.patient_id = patientreg.patient_idJOIN m_visit_type_master vm ON vm.visit_type_id = ordermaster.visit_type_id AND vm.status = 'A'::bpcharLEFT JOIN m_patient_category_master pcm ON pcm.patient_category_id = patientreg.patient_category_id AND pcm.status = 'A'::bpcharLEFT JOIN m_country_master cm ON cm.country_id = patdtl.country_idLEFT JOIN opd.t_encounter_master encountermaster ON ordermaster.encounter_id = encountermaster.encounter_idLEFT JOIN adt.t_admission admission ON ordermaster.admission_id = admission.admission_idLEFT JOIN billing.t_billing_details billingdet ON orderdetail.order_details_id = billingdet.order_details_idLEFT JOIN billing.m_billing_master billmaster ON orderdetail.service_bill_id = billmaster.billing_master_id AND billmaster.bill_cancelled = 'N'::bpcharLEFT JOIN doctor.m_doctor_master doctormaster ON hemodialysismapper.doctor_id = doctormaster.doctor_idLEFT JOIN doctor.m_speciality_master specmaster ON orderdetail.ord_doc_spl_id = specmaster.speciality_idJOIN opd.m_appointment_master appmstr ON appmstr.appointment_id = hemodialysismapper.appointment_idLEFT JOIN opd.m_slot_master sm ON sm.slot_id = appmstr.slot_idJOIN service.m_service_master servicemaster ON orderdetail.service_id = servicemaster.service_master_idLEFT JOIN adt.m_priority_master pm ON pm.priority_id = orderdetail.priority_idLEFT JOIN adt.m_bed_master bm ON bm.bed_id = sm.bed_idLEFT JOIN adt.t_admission_details dtl ON dtl.admission_id = admission.admission_id AND admission.status = 'A'::bpchar AND dtl.status = 'A'::bpcharLEFT JOIN doctor.m_doctor_master doctormasterip ON doctormasterip.doctor_id = admission.doctor_idLEFT JOIN adt.m_bed_master bedmstr ON dtl.bed_id = bedmstr.bed_idLEFT JOIN adt.m_ward_master wm ON wm.ward_id = dtl.ward_idLEFT JOIN m_employee_master employeemaster ON employeemaster.user_id = hemodialysismapper.technician_idLEFT JOIN m_item itemmaster ON itemmaster.id = hemodialysismapper.machine_idLEFT JOIN m_unit_master um ON hemodialysismapper.unit_id = um.unit_idWHERE orderdetail.status = 'A'::bpchar AND hemodialysismapper.workbench_acceptance = 'A'::bpchar;

-- public.get_healthpackage source
CREATE OR REPLACE VIEW public.get_healthpackageAS SELECT am.appointment_id,pim.uhid_number,pim.patientname,pim.age,pim.email,pim.mobile_number,sm.slot_id,sm.appointment_date,sm.from_time,status.appointment_status_desc,pim.patientaddress,pim.regdate,pim.gender_name,unit.unit_name,unit.unit_address,unit.unit_contact,unit.unit_country_code,unit.unit_contact_2,unit.unit_contact_3,unit.unit_website,unit.unit_email_id,sm.slot_type_id,pim.patient_id,od.is_package,od.package_id,om.order_id,packagetype.package_type,servicemaster.service_standard_name,abs(date_part('Year'::text, age(pim.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,um.user_name,am.created_date,unit.imageFROM opd.m_appointment_master amJOIN opd.m_slot_master sm ON am.slot_id = sm.slot_idLEFT JOIN patientinformation pim ON am.patient_id = pim.patient_idLEFT JOIN opd.m_appointment_status_master status ON am.appointment_status_id = status.appointment_status_idLEFT JOIN unitinformation unit ON am.unit_id = unit.unit_idLEFT JOIN service.m_package_master package ON am.ehc_package_id = package.package_master_idLEFT JOIN service.m_package_type_master packagetype ON package.package_type_id = packagetype.package_type_idLEFT JOIN opd.t_encounter_master em ON em.appointment_id = am.appointment_idLEFT JOIN t_order_master om ON em.encounter_id = om.encounter_idLEFT JOIN t_order_details od ON om.order_id = od.order_idLEFT JOIN service.m_service_master servicemaster ON package.service_id = servicemaster.service_master_idLEFT JOIN m_user_master um ON am.created_by = um.user_id;

-- public.get_implant_opening_balance source
CREATE OR REPLACE VIEW public.get_implant_opening_balanceAS SELECT ob.id,ob.opb_no,ob.added_date,m_store.store_name,m_status.status,um.user_name,m_item.code,m_item.name AS itemname,obd.batch_no,obd.expiry_date,obd.quantity,obd.cop,obd.mrp,obd.amount_cop,obd.markup_percentage,tax.name AS taxname,obd.tax_percentage,obd.tax_amount,obd.remark,unit.unit_name,unit.unit_address,unit.imageFROM inventory.t_opening_balance_implant obLEFT JOIN inventory.t_opening_balance_implant_detail obd ON ob.id = obd.opening_balance_implant_idLEFT JOIN m_store ON ob.store_id = m_store.store_idLEFT JOIN m_status ON ob.status_id = m_status.idLEFT JOIN m_user_master um ON ob.added_by = um.user_idLEFT JOIN m_item ON obd.item_id = m_item.idLEFT JOIN m_tax tax ON obd.tax_id = tax.idLEFT JOIN unitinformation unit ON ob.unit_id = unit.unit_id;

-- public.get_interim_handover source
CREATE OR REPLACE VIEW public.get_interim_handoverAS SELECT handover.id,handover.created_date,handover.ich_number,handover.cash_handover_by_id,handover.cash_handover_to_id,handover.cash_handover_amount,deno.denomination,deno.quantity,deno.amount,um.user_name AS userfrom,umto.user_name AS userto,unit.unit_id,unit.unit_name,unit.unit_address,handover.mode_of_transaction,unit.imageFROM t_interim_handover_details handoverLEFT JOIN t_denomination_details deno ON handover.id = deno.interim_handover_transaction_idLEFT JOIN m_user_master um ON handover.cash_handover_by_id = um.user_idLEFT JOIN m_user_master umto ON handover.cash_handover_to_id = umto.user_idLEFT JOIN unitinformation unit ON unit.unit_id = handover.unit_idWHERE deno.status::text = 'A'::text;

-- public.get_investigationslip source
CREATE OR REPLACE VIEW public.get_investigationslipAS SELECT concat(prefix.prefix_desc, '', p.first_name, ' ', p.middle_name, ' ', p.last_name) AS patientname,p.mobile_number,pd.address AS patientaddress,p.mobile_number AS phone_number,gm.gender_name,abs(date_part('Year'::text, age(to_char(p.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,p.uhid_number,tod.order_qty,sm.service_standard_name,ssp.sub_speciality_name,tod.order_date,tod.service_amt,tod.ord_concession,tod.ord_discount,tod.net_amount,CASEWHEN tom.admission_id IS NULL THEN rm.referral_nameELSE rm_adm.referral_nameEND AS referral_name,tod.order_id,tom.order_no,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.image,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,dtls.sample_collection_datetime,dtls.sample_accept_datetime,audittrail.created_date AS sample_receiving_time,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,CASEWHEN tom.admission_id IS NULL THEN opd_cm.company_descELSE cm.company_descEND AS company_desc,tod.ord_cancelled,pntmst.bed_desc,pntmst.billing_bed_desc,concat(dm.first_name, ' ', dm.last_name) AS doctorname,tom.admission_id,ta.admission_number,pp.intrim_bill_noFROM t_order_master tomJOIN t_order_details tod ON tom.order_id = tod.order_idJOIN service.m_service_master sm ON tod.service_id = sm.service_master_idJOIN patient.t_patient_registration p ON tom.patient_id = p.patient_idLEFT JOIN m_patient_visit_metadata pntmst ON pntmst.admission_id = tom.admission_idJOIN m_prefix_master prefix ON p.prefix_id = prefix.prefix_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = p.patient_idJOIN m_gender_master gm ON gm.gender_id = p.gender_idLEFT JOIN t_referal_details reffer ON tom.encounter_id = reffer.encounter_idLEFT JOIN adt.m_referral_master rm ON reffer.referral_id = rm.referral_idLEFT JOIN t_referal_details reffer_adm ON tom.admission_id = reffer_adm.admission_idLEFT JOIN adt.m_referral_master rm_adm ON reffer_adm.referral_id = rm_adm.referral_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = tod.ord_doc_idLEFT JOIN lab.t_lab_sample_dtls dtls ON dtls.order_details_id = tod.order_details_idLEFT JOIN lab.m_test_master tm ON dtls.test_id = tm.test_id AND tm.org_id = tom.org_idLEFT JOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_idLEFT JOIN lab.t_sample_audit_trail audittrail ON dtls.lab_sample_dtls_id = audittrail.sample_dtls_id AND audittrail.test_status_id = 14LEFT JOIN m_user_master um1 ON um1.user_id = tod.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = um1.user_idLEFT JOIN m_unit_master um ON tom.org_unit_id = um.unit_idLEFT JOIN opd.t_patient_sponsor_details psd ON tom.admission_id = psd.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN t_company_master cm ON psd.payee_id = cm.company_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details psd1 ON tom.encounter_id = psd1.encounter_id AND psd1.priority_id = 1 AND psd1.status = 'A'::bpcharLEFT JOIN t_company_master opd_cm ON psd1.payee_id = opd_cm.company_id AND psd1.priority_id = 1 AND psd1.status = 'A'::bpchar AND tod.ord_cancelled = 'N'::bpcharLEFT JOIN adt.t_admission ta ON ta.admission_id = tom.admission_idLEFT JOIN ( SELECT ib.order_details_id,ti.intrim_bill_noFROM billing.t_intrim_bill_details ibJOIN billing.t_intrim_bill ti ON ib.intrim_bill_id = ti.intrim_bill_id AND ti.intrim_bill_no::text &lt;&gt; ''::text AND ti.order_status = 'A'::bpchar) pp ON pp.order_details_id = tod.order_details_id;

-- public.get_invoicedetails source
CREATE OR REPLACE VIEW public.get_invoicedetailsAS SELECT cim.invoice_date,cim.invoice_number AS "invoiceNumber",mbillmstr.bill_date_time AS billdate,mbillmstr.bill_number AS "billNumber",pat.uhid_number AS "uhidNumber",COALESCE((((((pm.prefix_desc || ' '::text) || pat.first_name::text) || ' '::text) || pat.middle_name::text) || ' '::text) || pat.last_name::text) AS "patientName",mbillmstr.total_bill_amount AS "totalAmount",mbillmstr.net_amount AS "netAmount",mbillmstr.outstanding,( SELECT sum(COALESCE(t_company_invoice_service_details.received_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "receivedAmt",( SELECT sum(COALESCE(t_company_invoice_service_details.tds_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "tdsAmount",( SELECT sum(COALESCE(t_company_invoice_service_details.disallowed_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "disallowedAmount",( SELECT sum(COALESCE(t_company_invoice_service_details.other_deduction, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "otherDeduction",mbillmstr.billing_master_id AS "billId",mbillmstr.patient_id AS "patientId",mbillmstr.visit_type_id AS "visitTypeId",0 AS "billType",cm.company_desc,cim.company_invoice_id,um.unit_name,um.unit_address,um.imageFROM billing.m_company_invoice_master cimJOIN billing.t_company_invoice_details cid ON cim.company_invoice_id = cid.company_invoice_idJOIN billing.m_billing_master mbillmstr ON mbillmstr.billing_master_id = cid.bill_id AND mbillmstr.bill_cancelled = 'N'::bpcharJOIN patient.registration pat ON pat.patient_id = mbillmstr.patient_idJOIN m_prefix_master pm ON pm.prefix_id = pat.prefix_idLEFT JOIN t_company_master cm ON cim.payee_id = cm.company_idLEFT JOIN unitinformation um ON cim.unit_id = um.unit_idUNION ALLSELECT cim.invoice_date,cim.invoice_number AS "invoiceNumber",sale.added_date AS billdate,sale.bill_no AS "billNumber",pat.uhid_number AS "uhidNumber",CASEWHEN sale.patient_id &gt; 0 THEN COALESCE((((((pm.prefix_desc || ' '::text) || pat.first_name::text) || ' '::text) || pat.middle_name::text) || ' '::text) || pat.last_name::text)ELSE COALESCE((tpm.prefix_desc || ' '::text) || tpatient.patient_name::text)END AS "patientName",sale.total_amount AS "totalAmount",sale.net_amount AS "netAmount",sale.outstanding_amount AS outstanding,( SELECT sum(COALESCE(t_company_invoice_service_details.received_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "receivedAmt",( SELECT sum(COALESCE(t_company_invoice_service_details.tds_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "tdsAmount",( SELECT sum(COALESCE(t_company_invoice_service_details.disallowed_amount, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "disallowedAmount",( SELECT sum(COALESCE(t_company_invoice_service_details.other_deduction, 0::double precision)) AS sumFROM billing.t_company_invoice_service_detailsWHERE t_company_invoice_service_details.invoice_detail_id = cid.company_invoice_detail_id) AS "otherDeduction",sale.id::integer AS "billId",sale.patient_id AS "patientId",0 AS "visitTypeId",1 AS "billType",cm.company_desc,cim.company_invoice_id,um.unit_name,um.unit_address,um.imageFROM billing.m_company_invoice_master cimJOIN billing.t_company_invoice_details cid ON cim.company_invoice_id = cid.company_invoice_idJOIN pharmacy.t_sale sale ON sale.id = cid.t_sale_idLEFT JOIN patient.registration pat ON pat.patient_id = sale.patient_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pat.prefix_idLEFT JOIN pharmacy.t_temp_patient_registration tpatient ON sale.temp_patient_id = tpatient.idLEFT JOIN m_prefix_master tpm ON tpatient.prefix_id = tpm.prefix_idLEFT JOIN t_company_master cm ON cim.payee_id = cm.company_idLEFT JOIN unitinformation um ON cim.unit_id = um.unit_id;

-- public.get_inward source
CREATE OR REPLACE VIEW public.get_inwardAS SELECT inward.id,inward.added_date,inward.added_by,inward.approve_by,m_store.store_name,m_vendor.name AS vendor,m_asset_type.type AS assettype,inward.remark,m_status.status,m_item.code,m_item.name AS itemname,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,inwarddetails.batch_no,inwarddetails.approved_quantity,inwarddetails.received_qty,inwarddetails.reject_quantity,inwarddetails.cop,inwarddetails.mrp,inwarddetails.tax_amount,inwarddetails.net_amount,inwarddetails.specification,m_unit_master.unit_name,m_unit_master.unit_address,inward.inword_no,reqtype.type AS replacement,returnable_gatepass.ret_gp_no,returnable_gatepass.added_date AS gatepassdate,returnable_gatepass.total_amt,returnable_gatepass.total_tax_amount,returnable_gatepass.net_amount AS returnable_gatepass_netamount,m_unit_master.imageFROM inventory.t_material_inwards inwardJOIN inventory.t_material_inwards_detail inwarddetails ON inward.id = inwarddetails.material_inwards_idLEFT JOIN m_store ON inward.store_id = m_store.store_idLEFT JOIN m_vendor ON inward.vendor_id = m_vendor.idLEFT JOIN m_asset_type ON inward.asset_type_id = m_asset_type.idLEFT JOIN m_status ON inward.status_id = m_status.idLEFT JOIN m_item ON inwarddetails.item_id = m_item.idLEFT JOIN m_uom_type ON inwarddetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON inwarddetails.uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_master ON inward.unit_id = m_unit_master.unit_idLEFT JOIN m_request_type reqtype ON inward.request_type_id = reqtype.idLEFT JOIN inventory.t_returnable_gatepass returnable_gatepass ON inward.returnable_gatepass_id = returnable_gatepass.idWHERE inwarddetails.is_active = true;

-- public.get_ipdbill_new source
CREATE OR REPLACE VIEW public.get_ipdbill_newAS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pinf.age,pinf.gender_name,adt.doa,''::text AS pdd,''::character varying(100) AS discharge_desc,''::text AS discharge_date,pntmst.email,billdtls.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,pm.prefix_desc,(((((pm.prefix_desc || ''::text) || pntmst.first_name::text) || ' '::text) || pntmst.middle_name::text) || ' '::text) || pntmst.last_name::text AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,t_company_master.company_desc,m_payment_entitlement_master.payment_entitlement_desc,m_tariff_master.tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,COALESCE(t_associated_company_master.associated_company_name, ''::character varying) AS associated_company_name,m_company_contract_master.associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,m_bed_category_master.bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,sum(COALESCE(billdtls.self_payable, 0::double precision)) AS total_self_payable,sum(COALESCE(billdtls.credit_payable, 0::double precision)) AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,((('Dr.'::text || ' '::text) || admdoctor.first_name::text) || ' '::text) || admdoctor.last_name::text AS admdoctor,m_refferel.referral_name AS referral_contact_person,billdtls.payee_id,0 AS contract_id,t_company_master.company_id AS payeeidnew,billdtls.self_payable AS payee_amount,billdtls.credit_payable AS due_amount,t_company_master.company_desc AS payeedescnew,''::text AS contract_name_new,od.created_date::date AS orderdate,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,um.image,bedcatetory.billing_bed_desc AS orderbedcategory,COALESCE(bpdnhif.due_amount, 0::double precision) AS payeedueamount,COALESCE(bpdnhif.bill_amount, 0::double precision) AS bill_amount,max(discharge.discharge_date::date) AS discharge_date_new,max(discharge.discharge_time::time without time zone) AS discharge_time_new,COALESCE(selfpayee.due_amount, 0::double precision) AS due_self_amount,COALESCE(selfpayee.bill_amount, 0::double precision) AS payeebillamount,COALESCE(payment.amount, 0::double precision) AS paidamount,advforadmission(am.admission_id::double precision) AS deposit,servmst.service_master_id,COALESCE(depositcon.consumed_amount, 0::double precision) AS consumed_amount,od.package_consumption_amt,payment1.deposite_consumption_id,discharge.discharge_status_id,mrfdm.discharge_type_name,mbcm.bed_category_desc AS chargebedcategory,pd.address AS patientaddress,pntmst.mobile_number AS patientmobile,COALESCE(pharmacyservice_idnew(billmst.billing_master_id, billmst.unit_id), 0) AS pharmacyservice_id,billmst.bill_remark,od.ord_render_datetime,( SELECT ustm_1.service_codeFROM service.m_unit_service_tariff_master ustm_1WHERE ustm_1.visit_type_id = 2 AND ustm_1.status = 'A'::bpchar AND ustm_1.service_id = servmst.service_master_id AND ustm_1.tariff_id = t_patient_sponsor_details.tariff_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharORDER BY ustm_1.unit_service_tariff_id DESCLIMIT 1) AS service_standard_code,billdtls.ord_doc_id,( SELECT array_to_string(ARRAY( SELECT m_speciality_master.speciality_nameFROM doctor.t_doctor_speciality_mapperJOIN doctor.m_speciality_master ON t_doctor_speciality_mapper.speciality_id = m_speciality_master.speciality_idWHERE t_doctor_speciality_mapper.doctor_id = billdtls.ord_doc_id AND t_doctor_speciality_mapper.status = 'A'::bpchar), ', '::text) AS array_to_string) AS order_doctor_speciality,t_patient_sponsor_details.tariff_id,0 AS billing_bed_category_id,od.ward_id,spc.speciality_code::text AS service_codeFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN billing.t_bill_payee_details bpdnhif ON billmst.billing_master_id = bpdnhif.bill_id AND bpdnhif.payee_id &lt;&gt; 1JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = billmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idJOIN patient.t_patient_details pd ON pntmst.patient_id = pd.patient_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN adt.t_discharge discharge ON discharge.admission_id = am.admission_id AND discharge.status = 'A'::bpcharLEFT JOIN adt.m_reason_for_discharge_master mrfdm ON discharge.discharge_type_id = mrfdm.discharge_type_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idJOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON billdtls.ord_doc_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON am.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN patient.patientinformation pinf ON pntmst.patient_id = pinf.patient_idJOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_category_master ON adt.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master ON t_patient_sponsor_details.payee_id = t_company_master.company_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN t_associated_company_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON billmst.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idLEFT JOIN doctor.m_doctor_master admdoctor ON am.doctor_id = admdoctor.doctor_idLEFT JOIN t_referal_details admreff ON am.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_bed_master mbm ON od.bed_id = mbm.bed_idLEFT JOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN adt.m_bed_category_master mbcm ON mbm.bed_category_id = mbcm.bed_category_idLEFT JOIN adt.m_billing_bed_category_master bedcatetory ON od.bed_category_id = bedcatetory.billing_bed_category_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_idLEFT JOIN ( SELECT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0) payment1 ON billmst.billing_master_id = payment1.billing_master_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idLEFT JOIN billing.t_bill_payee_details selfpayee ON billmst.billing_master_id = selfpayee.bill_id AND selfpayee.payee_id = 1WHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND adt.nursing_acceptance = 'Y'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char" AND adt.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS maxFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = am.admission_id))GROUP BY t_patient_sponsor_details.status, t_patient_sponsor_details.priority_id, billmst.billing_master_id, pntmst.patient_id, pinf.age, pinf.gender_name, adt.doa, billdtls.billing_details_id, servmst.service_master_id, pm.prefix_id, m_organization_master.organization_id, m_doctor_master.doctor_id, spc.speciality_id, docsp.speciality_id, m_employee_master.employee_id, um.unit_id, um.unit_name, um.unit_address, um.unit_address_2, um.unit_email_id, um.unit_logo, um.post_code, um.unit_contact, um.unit_contact_2, um.unit_contact_3, um.unit_country_code, um.registration_number, um.unit_website, um.currency_name, um.sub_currency, t_company_master.company_desc, m_payment_entitlement_master.payment_entitlement_desc, m_tariff_master.tariff_desc, t_patient_sponsor_details.payment_entitlement_id, od.order_details_id, t_associated_company_master.associated_company_name, m_company_contract_master.associate_company_id, am.admission_number, m_billing_bed_category_master.billing_bed_desc, m_bed_category_master.bed_category_desc, t_patient_sponsor_details.insurance_number, m_company_contract_master.contract_name, servicedoc.first_name, servicedoc.last_name, t_patient_sponsor_details.insured_amount, groupmaster.speciality_name, admdoctor.first_name, admdoctor.last_name, m_refferel.referral_name, billstatusmaster.bill_status_desc, um.image, bedcatetory.billing_bed_desc, am.admission_id, selfpayee.due_amount, selfpayee.bill_amount, payment.amount, t_company_master.company_id, discharge.discharge_date, discharge.discharge_time, bpdnhif.bill_amount, bpdnhif.due_amount, depositcon.consumed_amount, od.package_consumption_amt, payment1.deposite_consumption_id, discharge.discharge_status_id, mrfdm.discharge_type_name, mbcm.bed_category_desc, pd.address, pntmst.mobile_number, (COALESCE(pharmacyservice_id(billmst.billing_master_id), 0)), billmst.bill_remark, od.ward_id, t_patient_sponsor_details.tariff_idORDER BY billmst.admission_id DESC;

-- public.get_ipdbill_new_1 source
CREATE OR REPLACE VIEW public.get_ipdbill_new_1AS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pr.uhid_number,''::text AS first_name,''::text AS middle_name,''::text AS last_name,age(pr.dob)::interval(6) AS age,gm.gender_name,adt.doa,''::text AS pdd,''::character varying(100) AS discharge_desc,''::text AS discharge_date,pr.email,billmst.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,''::text AS prefix_desc,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,um.unit_name::character varying(255) AS organization_name,um.unit_address AS organization_address,um.unit_contact::text AS organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,billmst.unit_id,um.unit_name,um.unit_address,um.unit_address AS unit_address_2,um.unit_email_id,''::text AS unit_logo,um.post_code,um.unit_contact,um.unit_contact AS unit_contact_2,um.unit_contact AS unit_contact_3,um.post_code AS unit_country_code,um.registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,cm.company_desc,''::text AS payment_entitlement_desc,''::text AS tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,''::character varying AS associated_company_name,0 AS associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,bed1.bed_desc AS bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,0::double precision AS total_self_payable,0::double precision AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,concat(m_doctor_master.first_name, ' ', m_doctor_master.last_name) AS admdoctor,rm.referral_name AS referral_contact_person,COALESCE(cm.company_id, 0) AS payee_id,0 AS contract_id,0 AS payeeidnew,billdtls.self_payable AS payee_amount,billdtls.credit_payable AS due_amount,cm.company_desc AS payeedescnew,''::text AS contract_name_new,od.created_date::date AS orderdate,od.is_package_service,od.package_id,od.is_package,''::text AS bill_status_desc,'\x'::bytea AS image,''::character varying(250) AS orderbedcategory,COALESCE(bpdnhif.due_amount, 0::double precision) AS payeedueamount,0::double precision AS bill_amount,max(discharge.discharge_date::date) AS discharge_date_new,max(discharge.discharge_time::time without time zone) AS discharge_time_new,COALESCE(selfpayee.due_amount, 0::double precision) AS due_self_amount,COALESCE(selfpayee.bill_amount, 0::double precision) AS payeebillamount,COALESCE(billmst.net_amount - billmst.outstanding) AS paidamount,( SELECT COALESCE(sum(dm.available_deposit)::integer, 0) AS "coalesce"FROM billing.m_deposit_master dmWHERE dm.admission_id = billmst.admission_id AND dm.status = 'A'::"char") AS deposit,servmst.service_master_id,sum(COALESCE(depositcon.consumed_amount, 0::double precision)) AS consumed_amount,od.package_consumption_amt,max(depositcon.dep_consumption_id) AS deposite_consumption_id,discharge.discharge_status_id,distype.discharge_type_name::text AS discharge_type_name,''::text AS chargebedcategory,pd.address AS patientaddress,pr.mobile_number AS patientmobile,bill.service_id AS pharmacyservice_id,billmst.bill_remark,COALESCE(od.ord_render_datetime, od.order_date)::date AS ord_render_datetime,''::character varying(50) AS service_standard_code,billdtls.ord_doc_id,''::text AS order_doctor_speciality,0 AS tariff_id,0 AS billing_bed_category_id,od.ward_id,spc.speciality_code::text AS service_code,m_company_contract_master.co_share_percentage,t_patient_sponsor_details.relation::character varying(100) AS relation_name,t_patient_sponsor_details.employee_name::character varying AS kinname,t_patient_sponsor_details.employee_no_manual,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenby,spc.speciality_id,t_patient_sponsor_details.medical_card_no,COALESCE(wm.ward_name, ''::character varying)::character varying(100) AS ward_name,um.image AS logo,COALESCE(bed.bed_number, ''::character varying)::character varying(400) AS bed_number,sspc.sub_speciality_id,sspc.sub_speciality_name,COALESCE(creditnote.cr_total_amount, 0::double precision) AS cr_total_amount,serdocdept.speciality_name AS orderdoc_specialityFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN billing.t_bill_payee_details bpdnhif ON billmst.billing_master_id = bpdnhif.bill_id AND bpdnhif.priority_id = 1 AND bpdnhif.status = 'A'::"char"LEFT JOIN t_company_master cm ON cm.company_id = bpdnhif.payee_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharLEFT JOIN adt.m_ward_master wm ON wm.ward_id = od.ward_idLEFT JOIN adt.m_bed_master bed ON bed.bed_id = od.bed_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN doctor.m_sub_speciality_master sspc ON sspc.sub_speciality_id = servmst.sub_speciality_idJOIN patient.t_patient_registration pr ON pr.patient_id = billmst.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN adt.t_discharge discharge ON discharge.admission_id = am.admission_id AND discharge.status = 'A'::bpcharLEFT JOIN adt.m_reason_for_discharge_master distype ON distype.discharge_type_id = discharge.discharge_type_idLEFT JOIN doctor.m_doctor_master ON am.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON am.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master serdocdept ON serdocdept.speciality_id = billdtls.ord_doc_spl_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idJOIN m_unit_master um ON um.unit_id = billmst.unit_idLEFT JOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_id AND depositcon.status = 'A'::bpcharLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_master bed1 ON bed1.bed_id = adt.bed_idLEFT JOIN t_referal_details rd ON rd.admission_id = am.admission_id AND rd.status = 'A'::bpcharLEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idLEFT JOIN ( SELECT DISTINCT COALESCE(bill_1.service_id, 0) AS service_id,bill_1.billing_master_idFROM billing.t_billing_details bill_1WHERE bill_1.service_id = (( SELECT t_unit_application_billing_configuration.pharmacy_service_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = bill_1.unit_id))) bill ON bill.billing_master_id = billmst.billing_master_idLEFT JOIN ( SELECT DISTINCT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0ORDER BY (COALESCE(prm.deposite_consumption_id, 0)) DESCLIMIT 1) payment1 ON billmst.billing_master_id = payment1.billing_master_idLEFT JOIN billing.t_bill_payee_details selfpayee ON billmst.billing_master_id = selfpayee.bill_id AND selfpayee.payee_id = 1LEFT JOIN billing.t_package_consumption_master pcm ON pcm.admission_id = billmst.admission_id AND od.package_id = pcm.package_id AND pcm.status = 'A'::"char"LEFT JOIN ( SELECT cn.bill_id,sum(cn.cr_net_amount) AS cr_total_amountFROM billing.m_credit_note_master cnWHERE cn.status = 'A'::bpcharGROUP BY cn.bill_id) creditnote ON creditnote.bill_id = billmst.billing_master_idWHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND t_patient_sponsor_details.status = 'A'::bpchar AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char" AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = am.admission_id))GROUP BY m_billing_bed_category_master.billing_bed_desc, bed1.bed_desc, um.image, od.ord_render_datetime, bill.service_id, m_doctor_master.first_name, m_doctor_master.last_name, pr.dob, pr.uhid_number, t_patient_sponsor_details.status, t_patient_sponsor_details.priority_id, billmst.billing_master_id, pr.patient_id, gm.gender_name, pr.first_name, pr.middle_name, pr.last_name, prefix.prefix_desc, adt.doa, billdtls.billing_details_id, servmst.service_master_id, m_doctor_master.doctor_id, spc.speciality_id, docsp.speciality_id, m_employee_master.employee_id, billmst.unit_id, um.unit_name, um.unit_address, pr.email, um.post_code, um.unit_contact, um.registration_number, um.unit_website, um.unit_email_id, cm.company_desc, od.order_details_id, am.admission_number, t_patient_sponsor_details.insurance_number, m_company_contract_master.contract_name, servicedoc.first_name, servicedoc.last_name, t_patient_sponsor_details.insured_amount, groupmaster.speciality_name, rm.referral_name, cm.company_id, t_patient_sponsor_details.payment_entitlement_id, billmst.admission_id, selfpayee.due_amount, selfpayee.bill_amount, discharge.discharge_date, discharge.discharge_time, bpdnhif.bill_amount, bpdnhif.due_amount, od.package_consumption_amt, discharge.discharge_status_id, distype.discharge_type_name, pd.address, pr.mobile_number, (COALESCE(pharmacyservice_id(billmst.billing_master_id), 0)), billmst.bill_remark, od.ward_id, t_patient_sponsor_details.tariff_id, m_company_contract_master.co_share_percentage, t_patient_sponsor_details.employee_name, t_patient_sponsor_details.relation, t_patient_sponsor_details.employee_no_manual, empprint.first_name, empprint.last_name, t_patient_sponsor_details.medical_card_no, pcm.package_applicable_date, wm.ward_name, bed.bed_number, sspc.sub_speciality_id, sspc.sub_speciality_name, creditnote.cr_total_amount, serdocdept.speciality_name;

-- public.get_ipdbill_new_2 source
CREATE OR REPLACE VIEW public.get_ipdbill_new_2AS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pntmst.uhid_number,''::text AS first_name,''::text AS middle_name,''::text AS last_name,pntmst.age,pntmst.gender_name,pntmst.doa,''::text AS pdd,''::character varying(100) AS discharge_desc,''::text AS discharge_date,pntmst.patientemail AS email,billdtls.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,''::text AS prefix_desc,pntmst.patientname,pntmst.organization_desc AS organization_name,pntmst.organization_address,pntmst.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,billmst.unit_id,pntmst.unit_name,pntmst.unit_address,pntmst.unit_address AS unit_address_2,pntmst.unit_email_id,''::text AS unit_logo,pntmst.post_code,pntmst.unit_contact,pntmst.unit_contact AS unit_contact_2,pntmst.unit_contact AS unit_contact_3,pntmst.post_code AS unit_country_code,pntmst.registration_number,pntmst.unit_website,pntmst.currency_name,pntmst.sub_currency,pntmst.company_desc,''::text AS payment_entitlement_desc,''::text AS tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,''::character varying AS associated_company_name,0 AS associate_company_id,pntmst.admission_number,CASEWHEN (( SELECT mbm.is_virtualFROM adt.t_admission_details tadJOIN adt.m_bed_master mbm ON mbm.bed_id = tad.bed_idWHERE tad.admission_id = billmst.admission_id AND mbm.is_virtual = 'Y'::bpchar)) = 'Y'::bpchar THEN (( SELECT mbcm.bed_category_descFROM adt.t_admission_details tadJOIN adt.m_bed_master mbm ON mbm.bed_id = tad.bed_idJOIN adt.m_bed_category_master mbcm ON mbm.bed_category_id = mbcm.bed_category_idWHERE (tad.admission_details_id IN ( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = billmst.admission_idORDER BY t_admission_details.admission_details_id DESC))ORDER BY mbcm.bed_category_descLIMIT 1))::character varyingELSE pntmst.bed_descEND::character varying(250) AS billing_bed_desc,CASEWHEN (( SELECT mbm.is_virtualFROM adt.t_admission_details tadJOIN adt.m_bed_master mbm ON mbm.bed_id = tad.bed_idWHERE tad.admission_id = billmst.admission_id AND mbm.is_virtual = 'Y'::bpchar)) = 'Y'::bpchar THEN ( SELECT mbm.bed_descFROM adt.t_admission_details tadJOIN adt.m_bed_master mbm ON mbm.bed_id = tad.bed_idWHERE (tad.admission_details_id IN ( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = billmst.admission_idORDER BY t_admission_details.admission_details_id DESC))ORDER BY mbm.bed_descLIMIT 1)ELSE pntmst.bed_descEND AS bed_category_desc,COALESCE(pntmst.insurance_number, ''::character varying) AS insurance_number,COALESCE(pntmst.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,pntmst.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,sum(COALESCE(billdtls.self_payable, 0::double precision)) AS total_self_payable,sum(COALESCE(billdtls.credit_payable, 0::double precision)) AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pntmst.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pntmst.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pntmst.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,pntmst.doctorname AS admdoctor,pntmst.referral_name AS referral_contact_person,billdtls.payee_id,0 AS contract_id,0 AS payeeidnew,billdtls.self_payable AS payee_amount,billdtls.credit_payable AS due_amount,pntmst.company_desc AS payeedescnew,''::text AS contract_name_new,od.created_date::date AS orderdate,od.is_package_service,od.package_id,od.is_package,''::text AS bill_status_desc,''::text AS image,''::character varying(250) AS orderbedcategory,COALESCE(bpdnhif.due_amount, 0::double precision) AS payeedueamount,COALESCE(bpdnhif.bill_amount, 0::double precision) AS bill_amount,max(discharge.discharge_date::date) AS discharge_date_new,max(discharge.discharge_time::time without time zone) AS discharge_time_new,COALESCE(selfpayee.due_amount, 0::double precision) AS due_self_amount,COALESCE(selfpayee.bill_amount, 0::double precision) AS payeebillamount,COALESCE(payment.amount, 0::double precision) AS paidamount,0 AS deposit,servmst.service_master_id,COALESCE(depositcon.consumed_amount, 0::double precision) AS consumed_amount,od.package_consumption_amt,payment1.deposite_consumption_id,discharge.discharge_status_id,''::text AS discharge_type_name,''::text AS chargebedcategory,pntmst.patientaddress,pntmst.patientmobile,COALESCE(pharmacyservice_idnew(billmst.billing_master_id, billmst.unit_id), 0) AS pharmacyservice_id,billmst.bill_remark,od.ord_render_datetime::date AS ord_render_datetime,( SELECT ustm_1.service_codeFROM service.m_unit_service_tariff_master ustm_1WHERE ustm_1.visit_type_id = 2 AND ustm_1.status = 'A'::bpchar AND ustm_1.service_id = servmst.service_master_id AND ustm_1.tariff_id = t_patient_sponsor_details.tariff_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharORDER BY ustm_1.unit_service_tariff_id DESCLIMIT 1) AS service_standard_code,billdtls.ord_doc_id,( SELECT array_to_string(ARRAY( SELECT m_speciality_master.speciality_nameFROM doctor.t_doctor_speciality_mapperJOIN doctor.m_speciality_master ON t_doctor_speciality_mapper.speciality_id = m_speciality_master.speciality_idWHERE t_doctor_speciality_mapper.doctor_id = billdtls.ord_doc_id AND t_doctor_speciality_mapper.status = 'A'::bpchar), ', '::text) AS array_to_string) AS order_doctor_speciality,0 AS tariff_id,0 AS billing_bed_category_id,od.ward_id,spc.speciality_code::text AS service_code,m_company_contract_master.co_share_percentage,( SELECT rm.relation_nameFROM m_kin_details kidJOIN m_relation_master rm ON kid.relation_id = rm.relation_id AND kid.patient_id = billmst.patient_idLIMIT 1) AS relation_name,( SELECT kid.kin_nameFROM m_kin_details kidWHERE kid.patient_id = billmst.patient_idLIMIT 1) AS kinname,pntmst.employee_no_manual,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenbyFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN billing.t_bill_payee_details bpdnhif ON billmst.billing_master_id = bpdnhif.bill_id AND bpdnhif.payee_id &lt;&gt; 1JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN m_patient_visit_metadata pntmst ON pntmst.admission_id = billmst.admission_idLEFT JOIN adt.t_discharge discharge ON discharge.admission_id = pntmst.admission_id AND discharge.status = 'A'::bpcharLEFT JOIN doctor.m_doctor_master ON billdtls.ord_doc_id = m_doctor_master.doctor_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN doctor.m_speciality_master docsp ON am.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_idLEFT JOIN ( SELECT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0) payment1 ON billmst.billing_master_id = payment1.billing_master_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idLEFT JOIN billing.t_bill_payee_details selfpayee ON billmst.billing_master_id = selfpayee.bill_id AND selfpayee.payee_id = 1WHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND t_patient_sponsor_details.status = 'A'::bpchar AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char"GROUP BY od.ord_render_datetime, pntmst.doctorname, pntmst.patientdob, pntmst.patientname, pntmst.uhid_number, t_patient_sponsor_details.status, t_patient_sponsor_details.priority_id, billmst.billing_master_id, pntmst.patient_id, pntmst.age, pntmst.gender_name, pntmst.doa, billdtls.billing_details_id, servmst.service_master_id, m_doctor_master.doctor_id, spc.speciality_id, docsp.speciality_id, m_employee_master.employee_id, billmst.unit_id, pntmst.unit_name, pntmst.unit_address, pntmst.patientemail, pntmst.post_code, pntmst.unit_contact, pntmst.registration_number, pntmst.unit_website, pntmst.currency_name, pntmst.sub_currency, pntmst.organization_desc, pntmst.organization_address, pntmst.organization_contact, pntmst.unit_email_id, pntmst.company_desc, od.order_details_id, pntmst.admission_number, pntmst.billing_bed_desc, pntmst.bed_desc, pntmst.insurance_number, pntmst.contract_name, servicedoc.first_name, servicedoc.last_name, pntmst.insured_amount, groupmaster.speciality_name, pntmst.referral_name, t_patient_sponsor_details.payment_entitlement_id, billmst.admission_id, selfpayee.due_amount, selfpayee.bill_amount, payment.amount, discharge.discharge_date, discharge.discharge_time, bpdnhif.bill_amount, bpdnhif.due_amount, depositcon.consumed_amount, od.package_consumption_amt, payment1.deposite_consumption_id, discharge.discharge_status_id, pntmst.patientaddress, pntmst.patientmobile, (COALESCE(pharmacyservice_id(billmst.billing_master_id), 0)), billmst.bill_remark, od.ward_id, t_patient_sponsor_details.tariff_id, m_company_contract_master.co_share_percentage, pntmst.employee_no_manual, empprint.first_name, empprint.last_name;

