ame,employee_no_manual,print_given_by,printgivenby,speciality_id,medical_card_no,ward_name,logo,bed_number,sub_speciality_id,sub_speciality_name,cr_total_amountFROM ( SELECT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pr.uhid_number,''::text AS first_name,''::text AS middle_name,''::text AS last_name,age(pr.dob)::interval(6) AS age,gm.gender_name,adt.doa,''::text AS pdd,''::character varying(100) AS discharge_desc,''::text AS discharge_date,pr.email,billmst.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,''::text AS prefix_desc,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,um.unit_name::character varying(255) AS organization_name,um.unit_address AS organization_address,um.unit_contact::text AS organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,billmst.unit_id,um.unit_name,um.unit_address,um.unit_address AS unit_address_2,um.unit_email_id,''::text AS unit_logo,um.post_code,um.unit_contact,um.unit_contact AS unit_contact_2,um.unit_contact AS unit_contact_3,um.post_code AS unit_country_code,um.registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,cm.company_desc,''::text AS payment_entitlement_desc,''::text AS tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,''::character varying AS associated_company_name,0 AS associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,bed1.bed_desc AS bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,0::double precision AS total_self_payable,0::double precision AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,concat(m_doctor_master.first_name, ' ', m_doctor_master.last_name) AS admdoctor,rm.referral_name AS referral_contact_person,COALESCE(cm.company_id, 0) AS payee_id,0 AS contract_id,0 AS payeeidnew,billdtls.self_payable AS payee_amount,billdtls.credit_payable AS due_amount,cm.company_desc AS payeedescnew,''::text AS contract_name_new,od.created_date::date AS orderdate,od.is_package_service,od.package_id,od.is_package,''::text AS bill_status_desc,'\x'::bytea AS image,''::character varying(250) AS orderbedcategory,COALESCE(bpdnhif.due_amount, 0::double precision) AS payeedueamount,0::double precision AS bill_amount,max(discharge.discharge_date::date) AS discharge_date_new,max(discharge.discharge_time::time without time zone) AS discharge_time_new,COALESCE(selfpayee.due_amount, 0::double precision) AS due_self_amount,COALESCE(selfpayee.bill_amount, 0::double precision) AS payeebillamount,COALESCE(billmst.net_amount - billmst.outstanding) AS paidamount,( SELECT COALESCE(sum(dm.available_deposit)::integer, 0) AS "coalesce"FROM billing.m_deposit_master dmWHERE dm.admission_id = billmst.admission_id AND dm.status = 'A'::"char") AS deposit,servmst.service_master_id,sum(COALESCE(depositcon.consumed_amount, 0::double precision)) AS consumed_amount,od.package_consumption_amt,max(depositcon.dep_consumption_id) AS deposite_consumption_id,discharge.discharge_status_id,distype.discharge_type_name::text AS discharge_type_name,''::text AS chargebedcategory,pd.address AS patientaddress,pr.mobile_number AS patientmobile,bill.service_id AS pharmacyservice_id,billmst.bill_remark,COALESCE(od.ord_render_datetime, od.order_date)::date AS ord_render_datetime,''::character varying(50) AS service_standard_code,billdtls.ord_doc_id,''::text AS order_doctor_speciality,0 AS tariff_id,0 AS billing_bed_category_id,od.ward_id,spc.speciality_code::text AS service_code,m_company_contract_master.co_share_percentage,t_patient_sponsor_details.relation::character varying(100) AS relation_name,t_patient_sponsor_details.employee_name::character varying AS kinname,t_patient_sponsor_details.employee_no_manual,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenby,spc.speciality_id,t_patient_sponsor_details.medical_card_no,COALESCE(wm.ward_name, ''::character varying)::character varying(100) AS ward_name,um.image AS logo,COALESCE(bed.bed_number, ''::character varying)::character varying(400) AS bed_number,sspc.sub_speciality_id,sspc.sub_speciality_name,COALESCE(creditnote.cr_total_amount, 0::double precision) AS cr_total_amountFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN billing.t_bill_payee_details bpdnhif ON billmst.billing_master_id = bpdnhif.bill_id AND bpdnhif.priority_id = 1 AND bpdnhif.status = 'A'::"char"LEFT JOIN t_company_master cm ON cm.company_id = bpdnhif.payee_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharLEFT JOIN adt.m_ward_master wm ON wm.ward_id = od.ward_idLEFT JOIN adt.m_bed_master bed ON bed.bed_id = od.bed_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN doctor.m_sub_speciality_master sspc ON sspc.sub_speciality_id = servmst.sub_speciality_idJOIN patient.t_patient_registration pr ON pr.patient_id = billmst.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN adt.t_discharge discharge ON discharge.admission_id = am.admission_id AND discharge.status = 'A'::bpcharLEFT JOIN adt.m_reason_for_discharge_master distype ON distype.discharge_type_id = discharge.discharge_type_idLEFT JOIN doctor.m_doctor_master ON am.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON am.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idJOIN m_unit_master um ON um.unit_id = billmst.unit_idLEFT JOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_id AND depositcon.status = 'A'::bpcharLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_master bed1 ON bed1.bed_id = adt.bed_idLEFT JOIN t_referal_details rd ON rd.admission_id = am.admission_id AND rd.status = 'A'::bpcharLEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idLEFT JOIN ( SELECT DISTINCT COALESCE(bill_1.service_id, 0) AS service_id,bill_1.billing_master_idFROM billing.t_billing_details bill_1WHERE bill_1.service_id = (( SELECT t_unit_application_billing_configuration.pharmacy_service_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = bill_1.unit_id))) bill ON bill.billing_master_id = billmst.billing_master_idLEFT JOIN ( SELECT DISTINCT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0ORDER BY (COALESCE(prm.deposite_consumption_id, 0)) DESCLIMIT 1) payment1 ON billmst.billing_master_id = payment1.billing_master_idLEFT JOIN billing.t_bill_payee_details selfpayee ON billmst.billing_master_id = selfpayee.bill_id AND selfpayee.payee_id = 1LEFT JOIN billing.t_package_consumption_master pcm ON pcm.admission_id = billmst.admission_id AND od.package_id = pcm.package_id AND pcm.status = 'A'::"char"LEFT JOIN ( SELECT cn.bill_id,sum(cn.cr_net_amount) AS cr_total_amountFROM billing.m_credit_note_master cnWHERE cn.status = 'A'::bpcharGROUP BY cn.bill_id) creditnote ON creditnote.bill_id = billmst.billing_master_idWHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND t_patient_sponsor_details.status = 'A'::bpchar AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char" AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = am.admission_id))GROUP BY m_billing_bed_category_master.billing_bed_desc, bed1.bed_desc, um.image, od.ord_render_datetime, bill.service_id, m_doctor_master.first_name, m_doctor_master.last_name, pr.dob, pr.uhid_number, t_patient_sponsor_details.status, t_patient_sponsor_details.priority_id, billmst.billing_master_id, pr.patient_id, gm.gender_name, pr.first_name, pr.middle_name, pr.last_name, prefix.prefix_desc, adt.doa, billdtls.billing_details_id, servmst.service_master_id, m_doctor_master.doctor_id, spc.speciality_id, docsp.speciality_id, m_employee_master.employee_id, billmst.unit_id, um.unit_name, um.unit_address, pr.email, um.post_code, um.unit_contact, um.registration_number, um.unit_website, um.unit_email_id, cm.company_desc, od.order_details_id, am.admission_number, t_patient_sponsor_details.insurance_number, m_company_contract_master.contract_name, servicedoc.first_name, servicedoc.last_name, t_patient_sponsor_details.insured_amount, groupmaster.speciality_name, rm.referral_name, cm.company_id, t_patient_sponsor_details.payment_entitlement_id, billmst.admission_id, selfpayee.due_amount, selfpayee.bill_amount, discharge.discharge_date, discharge.discharge_time, bpdnhif.bill_amount, bpdnhif.due_amount, od.package_consumption_amt, discharge.discharge_status_id, distype.discharge_type_name, pd.address, pr.mobile_number, (COALESCE(pharmacyservice_id(billmst.billing_master_id), 0)), billmst.bill_remark, od.ward_id, t_patient_sponsor_details.tariff_id, m_company_contract_master.co_share_percentage, t_patient_sponsor_details.employee_name, t_patient_sponsor_details.relation, t_patient_sponsor_details.employee_no_manual, empprint.first_name, empprint.last_name, t_patient_sponsor_details.medical_card_no, pcm.package_applicable_date, wm.ward_name, bed.bed_number, sspc.sub_speciality_id, sspc.sub_speciality_name, creditnote.cr_total_amount) aORDER BY orderdate, ord_render_datetime;

