CREATE OR REPLACE VIEW public.get_ipdbill_new_ssAS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pr.uhid_number,''::text AS first_name,''::text AS middle_name,''::text AS last_name,age(pr.dob)::interval(6) AS age,gm.gender_name,adt.doa,''::text AS pdd,''::character varying(100) AS discharge_desc,''::text AS discharge_date,pr.email,billmst.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,''::text AS prefix_desc,concat(prefix.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,um.unit_name::character varying(255) AS organization_name,um.unit_address AS organization_address,um.unit_contact::text AS organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,billmst.unit_id,um.unit_name,um.unit_address,um.unit_address AS unit_address_2,um.unit_email_id,''::text AS unit_logo,um.post_code,um.unit_contact,um.unit_contact AS unit_contact_2,um.unit_contact AS unit_contact_3,um.post_code AS unit_country_code,um.registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,cm.company_desc,''::text AS payment_entitlement_desc,''::text AS tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,''::character varying A