t time zone) AS discharge_time_new,COALESCE(selfpayee.due_amount, 0::double precision) AS due_self_amount,COALESCE(selfpayee.bill_amount, 0::double precision) AS payeebillamount,COALESCE(billmst.net_amount - billmst.outstanding) AS paidamount,( SELECT COALESCE(sum(dm.available_deposit)::integer, 0) AS "coalesce"FROM billing.m_deposit_master dmWHERE dm.admission_id = billmst.admission_id AND dm.status = 'A'::"char") AS deposit,servmst.service_master_id,sum(COALESCE(depositcon.consumed_amount, 0::double precision)) AS consumed_amount,od.package_consumption_amt,max(depositcon.dep_consumption_id) AS deposite_consumption_id,discharge.discharge_status_id,distype.discharge_type_name::text AS discharge_type_name,''::text AS chargebedcategory,pd.address AS patientaddress,pr.mobile_number AS patientmobile,bill.service_id AS pharmacyservice_id,billmst.bill_remark,COALESCE(od.ord_render_datetime, od.order_date)::date AS ord_render_datetime,''::character varying(50) AS service_standard_code,billdtls.ord_doc_id,''::text AS order_doctor_speciality,0 AS tariff_id,0 AS billing_bed_category_id,od.ward_id,spc.speciality_code::text AS service_code,m_company_contract_master.co_share_percentage,t_patient_sponsor_details.relation::character varying(100) AS relation_name,t_patient_sponsor_details.employee_name::character varying AS kinname,t_patient_sponsor_details.employee_no_manual,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenby,spc.speciality_id,t_patient_sponsor_details.medical_card_no,COALESCE(wm.ward_name, ''::character varying)::character varying(100) AS ward_name,um.image AS logo,COALESCE(bed.bed_number, ''::character varying)::character varying(400) AS bed_number,sspc.sub_speciality_id,sspc.sub_speciality_name,COALESCE(creditnote.cr_total_amount, 0::double precision) AS cr_total_amountFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN billing.t_bill_payee_details bpdnhif ON billmst.billing_master_id = bpdnhif.bill_id AND bpdnhif.priority_id = 1 AND bpdnhif.status = 'A'::"char"LEFT JOIN t_company_master cm ON cm.company_id = bpdnhif.payee_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharLEFT JOIN adt.m_ward_master wm ON wm.ward_id = od.ward_idLEFT JOIN adt.m_bed_master bed ON bed.bed_id = od.bed_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN doctor.m_sub_speciality_master sspc ON sspc.sub_speciality_id = servmst.sub_speciality_idJOIN patient.t_patient_registration pr ON pr.patient_id = billmst.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = pr.prefix_idJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN adt.t_discharge discharge ON discharge.admission_id = am.admission_id AND discharge.status = 'A'::bpcharLEFT JOIN adt.m_reason_for_discharge_master distype ON distype.discharge_type_id = discharge.discharge_type_idLEFT JOIN doctor.m_doctor_master ON am.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON am.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idJOIN m_unit_master um ON um.unit_id = billmst.unit_idLEFT JOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_id AND depositcon.status = 'A'::bpcharLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_master bed1 ON bed1.bed_id = adt.bed_idLEFT JOIN t_referal_details rd ON rd.admission_id = am.admission_id AND rd.status = 'A'::bpcharLEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idLEFT JOIN ( SELECT DISTINCT COALESCE(bill_1.service_id, 0) AS service_id,bill_1.billing_master_idFROM billing.t_billing_details bill_1WHERE bill_1.service_id = (( SELECT t_unit_application_billing_configuration.pharmacy_service_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = bill_1.unit_id))) bill ON bill.billing_master_id = billmst.billing_master_idLEFT JOIN ( SELECT DISTINCT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0ORDER BY (COALESCE(prm.deposite_consumption_id, 0)) DESCLIMIT 1) payment1 ON billmst.billing_master_id = payment1.billing_master_idLEFT JOIN billing.t_bill_payee_details selfpayee ON billmst.billing_master_id = selfpayee.bill_id AND selfpayee.payee_id = 1LEFT JOIN billing.t_package_consumption_master pcm ON pcm.admission_id = billmst.admission_id AND od.package_id = pcm.package_id AND pcm.status = 'A'::"char"LEFT JOIN ( SELECT cn.bill_id,sum(cn.cr_net_amount) AS cr_total_amountFROM billing.m_credit_note_master cnWHERE cn.status = 'A'::bpcharGROUP BY cn.bill_id) creditnote ON creditnote.bill_id = billmst.billing_master_idWHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND t_patient_sponsor_details.status = 'A'::bpchar AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char" AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = am.admission_id))GROUP BY m_billing_bed_category_master.billing_bed_desc, bed1.bed_desc, um.image, od.ord_render_datetime, bill.service_id, m_doctor_master.first_name, m_doctor_master.last_name, pr.dob, pr.uhid_number, t_patient_sponsor_details.status, t_patient_sponsor_details.priority_id, billmst.billing_master_id, pr.patient_id, gm.gender_name, pr.first_name, pr.middle_name, pr.last_name, prefix.prefix_desc, adt.doa, billdtls.billing_details_id, servmst.service_master_id, m_doctor_master.doctor_id, spc.speciality_id, docsp.speciality_id, m_employee_master.employee_id, billmst.unit_id, um.unit_name, um.unit_address, pr.email, um.post_code, um.unit_contact, um.registration_number, um.unit_website, um.unit_email_id, cm.company_desc, od.order_details_id, am.admission_number, t_patient_sponsor_details.insurance_number, m_company_contract_master.contract_name, servicedoc.first_name, servicedoc.last_name, t_patient_sponsor_details.insured_amount, groupmaster.speciality_name, rm.referral_name, cm.company_id, t_patient_sponsor_details.payment_entitlement_id, billmst.admission_id, selfpayee.due_amount, selfpayee.bill_amount, discharge.discharge_date, discharge.discharge_time, bpdnhif.bill_amount, bpdnhif.due_amount, od.package_consumption_amt, discharge.discharge_status_id, distype.discharge_type_name, pd.address, pr.mobile_number, (COALESCE(pharmacyservice_id(billmst.billing_master_id), 0)), billmst.bill_remark, od.ward_id, t_patient_sponsor_details.tariff_id, m_company_contract_master.co_share_percentage, t_patient_sponsor_details.employee_name, t_patient_sponsor_details.relation, t_patient_sponsor_details.employee_no_manual, empprint.first_name, empprint.last_name, t_patient_sponsor_details.medical_card_no, pcm.package_applicable_date, wm.ward_name, bed.bed_number, sspc.sub_speciality_id, sspc.sub_speciality_name, creditnote.cr_total_amount;

-- public.get_item_purchase source
CREATE OR REPLACE VIEW public.get_item_purchaseAS SELECT purchaserequest.id,purchaserequest.purchase_no,purchaserequest.added_date,purchaserequest.approved_date,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,(m_employee_master1.first_name::text || ' '::text) || m_employee_master1.last_name::text AS approvalusername,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,m_store.store_name,m_asset_type.type,m_request_type.type AS request_type,m_status.status,m_uom_type.type AS uom,m_uom_unit.unit AS uomunit,purchaserequestdetails.quantity,purchaserequestdetails.cop,purchaserequestdetails.approved_quantity,purchaserequestdetails.amount_cop,m_item.name,m_item.code,unitinformation.imageFROM procurement.t_purchase_request purchaserequestJOIN procurement.t_purchase_request_detail purchaserequestdetails ON purchaserequest.id = purchaserequestdetails.purchase_request_idLEFT JOIN m_user_master ON purchaserequest.added_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_unit_master unitinformation ON purchaserequest.unit_id = unitinformation.unit_idLEFT JOIN m_user_master m_user_master1 ON purchaserequest.approved_by = m_user_master1.user_idLEFT JOIN m_employee_master m_employee_master1 ON m_user_master1.user_id = m_employee_master1.user_idLEFT JOIN m_store ON purchaserequest.store_id = m_store.store_idLEFT JOIN m_asset_type ON purchaserequest.asset_type_id = m_asset_type.idLEFT JOIN m_request_type ON purchaserequest.request_type_id = m_request_type.idLEFT JOIN m_status ON purchaserequest.status_id = m_status.idLEFT JOIN m_item ON purchaserequestdetails.item_id = m_item.idLEFT JOIN m_uom_type ON purchaserequestdetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON purchaserequestdetails.uom_unit_id = m_uom_unit.idWHERE purchaserequestdetails.is_active = true;

-- public.get_item_request source
CREATE OR REPLACE VIEW public.get_item_requestAS SELECT itemrequest.id,itemrequest.request_no,itemrequest.added_date,itemrequest.added_by,itemrequest.approved_date,itemrequest.approved_by,itemrequestdetails.item_id,itemrequestdetails.item_name,itemrequestdetails.temp_manufacturer,itemrequestdetails.temp_vendor,itemrequestdetails.expected_price,itemrequestdetails.reason_item_creation,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,(m_employee_master1.first_name::text || ' '::text) || m_employee_master1.last_name::text AS approvalusername,m_status.status,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,m_asset_type.type,m_user_master.user_name,approstatus.status AS approstatus,m_manufacturer.name AS manufacturer,m_vendor.name AS vendor,unitinformation.imageFROM procurement.t_item_request itemrequestJOIN procurement.t_item_request_detail itemrequestdetails ON itemrequest.id = itemrequestdetails.item_request_idLEFT JOIN m_status ON itemrequest.status_id = m_status.idLEFT JOIN m_status approstatus ON itemrequest.approval_status_id = approstatus.idLEFT JOIN m_user_master ON itemrequest.added_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master m_user_master1 ON itemrequest.approved_by = m_user_master1.user_idLEFT JOIN m_employee_master m_employee_master1 ON m_user_master1.user_id = m_employee_master1.user_idLEFT JOIN m_unit_master unitinformation ON itemrequest.unit_id = unitinformation.unit_idLEFT JOIN m_asset_type ON itemrequest.asset_type_id = m_asset_type.idLEFT JOIN m_manufacturer ON itemrequestdetails.manufacturer_id = m_manufacturer.idLEFT JOIN m_vendor ON itemrequestdetails.vendor_id = m_vendor.idWHERE itemrequestdetails.is_active = true;

-- public.get_itemdetails source
CREATE OR REPLACE VIEW public.get_itemdetailsAS SELECT item.code,item.product_code,item.name AS itemname,generic.name AS genericname,prodcategory.category AS prodcategory,assetcatory.category AS assetcatory,formulation.type AS formulation,strength.unit AS strengthunitFROM m_item itemLEFT JOIN m_generic generic ON item.generic_id = generic.idLEFT JOIN m_product_category prodcategory ON generic.product_category_id = prodcategory.idLEFT JOIN m_asset_category assetcatory ON prodcategory.asset_category_id = assetcatory.idLEFT JOIN m_formulation_type formulation ON formulation.id = item.formulation_type_idLEFT JOIN m_strength_unit strength ON strength.id = item.storage_unit_id;

-- public.get_loan_in source
CREATE OR REPLACE VIEW public.get_loan_inAS SELECT loan.id,loan.added_date,loan.added_by,loan.approval_on,loan.approved_by,loan.inward_no,m_store.store_name,m_vendor.name AS vendor,m_asset_type.type AS assettype,loan.remark,m_status.status,m_item.code,m_item.name AS itemname,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,loandetails.batch_no,loandetails.quantity,loandetails.cop,loandetails.total_amount,loandetails.remark AS remark_details,loandetails.approved_quantity,unitinformation.unit_name,unitinformation.unit_address,unitinformation.imageFROM procurement.t_loan_in loanJOIN procurement.t_loan_in_detail loandetails ON loan.id = loandetails.loan_in_idJOIN m_store ON loan.store_id = m_store.store_idLEFT JOIN m_vendor ON loan.vendor_id = m_vendor.idLEFT JOIN m_asset_type ON loan.asset_type_id = m_asset_type.idLEFT JOIN m_status ON loan.status_id = m_status.idJOIN m_item ON loandetails.item_id = m_item.idLEFT JOIN m_uom_type ON loandetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON loandetails.uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_master unitinformation ON loan.unit_id = unitinformation.unit_idWHERE loandetails.is_active = true;

-- public.get_loan_inout source
CREATE OR REPLACE VIEW public.get_loan_inoutAS SELECT DISTINCT loan.id,loan.added_date,loan.added_by,loan.approval_on,loan.approved_by,loan.inward_no,m_store.store_name,m_vendor.name AS vendor,m_asset_type.type AS assettype,loan.remark,m_status.status,m_item.code,m_item.name AS itemname,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,loandetails.batch_no,loandetails.quantity,loandetails.cop,loandetails.total_amount,loandetails.remark AS remark_details,loandetails.approved_quantity,unitinformation.unit_name,unitinformation.unit_address,loaninout.id AS loaninout_id,loaninout.added_date AS loaninoutaddeddate,loaninout.loan_in_out_no,loaninoutdetail.return_quantity,loaninoutdetail.total_amount AS loaninout_totalamt,loaninoutdetail.remark AS loaninoutremarks,linoutstatus.status AS linoutstatus,loandetails.expiry_date,um.user_name,unitinformation.imageFROM procurement.t_loan_in loanJOIN procurement.t_loan_in_detail loandetails ON loan.id = loandetails.loan_in_idJOIN procurement.t_loan_in_out loaninout ON loan.id = loaninout.loan_in_idJOIN procurement.t_loan_in_out_detail loaninoutdetail ON loaninout.id = loaninoutdetail.loan_in_out_id AND loaninoutdetail.loan_in_detail_id = loandetails.idJOIN m_store ON loan.store_id = m_store.store_idLEFT JOIN m_vendor ON loan.vendor_id = m_vendor.idLEFT JOIN m_asset_type ON loan.asset_type_id = m_asset_type.idLEFT JOIN m_status ON loan.status_id = m_status.idLEFT JOIN m_status linoutstatus ON loaninout.status_id = linoutstatus.idJOIN m_item ON loandetails.item_id = m_item.idLEFT JOIN m_uom_type ON loandetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON loandetails.uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_master unitinformation ON loan.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON loaninout.added_by = um.user_idWHERE loandetails.is_active = true;

-- public.get_loan_out source
CREATE OR REPLACE VIEW public.get_loan_outAS SELECT loan.id,loan.added_date,loan.added_by,loan.approval_on,loan.approved_by,loan.dc_no,loan.loan_out_no,m_store.store_name,m_vendor.name AS vendor,m_asset_type.type AS assettype,loan.remark,m_status.status,m_item.code,m_item.name AS itemname,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,batch.batch_no,loandetails.loan_out_quantity,loandetails.cop,loandetails.total_amount,loandetails.remark AS remark_details,unitinformation.unit_name,unitinformation.unit_address,unitinformation.imageFROM procurement.t_loan_out loanJOIN procurement.t_loan_out_detail loandetails ON loan.id = loandetails.loan_out_idJOIN m_store ON loan.store_id = m_store.store_idLEFT JOIN m_vendor ON loan.vendor_id = m_vendor.idLEFT JOIN m_asset_type ON loan.asset_type_id = m_asset_type.idLEFT JOIN m_status ON loan.status_id = m_status.idJOIN inventory.t_batch batch ON loandetails.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_uom_type ON loandetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON loandetails.uom_unit_id = m_uom_unit.idLEFT JOIN m_unit_master unitinformation ON loan.unit_id = unitinformation.unit_idWHERE loandetails.is_active = true;

-- public.get_loan_outreceive source
CREATE OR REPLACE VIEW public.get_loan_outreceiveAS SELECT loanrec.id,loanrec.loanout_receive_no,loanrec.added_date,loanrec.loan_out_id,m_store.store_name,m_vendor.name AS vendor,m_status.status,assettype.type,um.user_name,loanrecdetails.total_amount,loanrecdetails.receive_quantity,loanrecdetails.remark,uomtype.type AS uomtype,uomunit.unit AS uomunit,m_item.code,m_item.name AS itemname,batch.expiry_date,batch.cop,unitmaster.unit_name,unitmaster.unit_address,loanrec.remark AS loanrecremark,batch.batch_no,unitmaster.imageFROM procurement.t_loanout_receive loanrecJOIN procurement.t_loanout_receive_detail loanrecdetails ON loanrec.id = loanrecdetails.loanout_receive_idJOIN m_store ON loanrec.store_id = m_store.store_idLEFT JOIN m_vendor ON loanrec.vendor_id = m_vendor.idLEFT JOIN m_status ON loanrec.status_id = m_status.idLEFT JOIN m_asset_type assettype ON loanrec.asset_type_id = assettype.idLEFT JOIN m_user_master um ON um.user_id = loanrec.added_byLEFT JOIN m_uom_type uomtype ON loanrecdetails.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON loanrecdetails.uom_unit_id = uomunit.idJOIN inventory.t_batch batch ON loanrecdetails.batch_id = batch.idJOIN m_item ON batch.item_id = m_item.idJOIN m_unit_master unitmaster ON loanrec.unit_id = unitmaster.unit_idWHERE loanrecdetails.is_active = true;

-- public.get_loyaltycard source
CREATE OR REPLACE VIEW public.get_loyaltycardAS SELECT card.loyalty_card_id,card.card_no,cardmapper.card_amount,pim.uhid_number,pim.patientname,unit.unit_name,unit.unit_address,dm.deposit_no,dm.deposit_date,dtm.deposite_type_desc,dm.deposit_amount,deposit_details.payment_mode_id,paymode.payment_mode_desc,bank.bank_desc,deposit_details.account_number,deposit_details.cheque_number,deposit_details.card_no AS bankcardno,deposit_details.card_holder_name,deposit_details.transaction_no,deposit_details.trans_transaction_date,deposit_details.amount,dm.deposit_master_idFROM m_loyalty_card cardLEFT JOIN patientinformation pim ON pim.patient_id = card.patient_idLEFT JOIN t_patient_loyalty_card_mppr cardmapper ON card.loyalty_card_id = cardmapper.loyalty_card_idLEFT JOIN unitinformation unit ON card.unit_id = unit.unit_idLEFT JOIN billing.m_deposit_master dm ON card.patient_id = dm.patient_idLEFT JOIN billing.m_deposite_type_master dtm ON dm.deposit_type_id = dtm.deposite_type_idLEFT JOIN billing.t_payment_deposit_details deposit_details ON dm.deposit_master_id = deposit_details.deposit_idLEFT JOIN m_payment_mode_master paymode ON deposit_details.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON deposit_details.bank_id = bank.bank_idLEFT JOIN billing.m_card_type_master bankcardtype ON deposit_details.card_type_id = bankcardtype.card_type_idLEFT JOIN billing.m_transaction_type_master transactiontype ON deposit_details.transaction_type_id = transactiontype.transaction_type_idWHERE dtm.deposite_type_id = 4;

-- public.get_material_issue source
CREATE OR REPLACE VIEW public.get_material_issueAS SELECT issue.issue_no,issue.added_date,indent.indent_no,fromstore.store_name AS fromstore,tostore.store_name AS tostore,m_item.name AS itemname,issue_detail.issue_quantity,indent_detail.indent_quantity,m_generic.name AS genericname,CASEWHEN COALESCE(issue_detail.store_indent_detail_id, 0) = 0 THEN uomtypemapper.typeELSE uomtype.typeEND AS uomtype,CASEWHEN COALESCE(issue_detail.store_indent_detail_id, 0) = 0 THEN uomunitmapper.unitELSE uomunit.unitEND AS uomunit,issue.id,priority.priority_desc,indenttype.type AS indenttype,m_status.status,m_item.code,unitinformation.unit_name,unitinformation.unit_address,unitinformation.image,issue_detail.id AS issuedetailid,indent_detail.id AS indentdetailid,materialmapper.batch_id,materialmapper.issue_quantity AS issueqty,materialmapper.accepted_quantity AS accqty,tb.cop,tb.rate,concat(empaddedby.first_name, ' ', empaddedby.last_name) AS empaddedby,concat(empupdated.first_name, ' ', empupdated.last_name) AS empupdated,issue.remarkFROM inventory.t_material_issue issueJOIN inventory.t_material_issue_detail issue_detail ON issue.id = issue_detail.material_issue_idLEFT JOIN inventory.t_store_indent indent ON issue.store_indent_id = indent.idLEFT JOIN inventory.t_store_indent_detail indent_detail ON issue_detail.store_indent_detail_id = indent_detail.idLEFT JOIN m_store fromstore ON issue.from_store_id = fromstore.store_idLEFT JOIN m_store tostore ON issue.to_store_id = tostore.store_idLEFT JOIN m_status ON issue.status_id = m_status.idLEFT JOIN m_item ON issue_detail.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type uomtype ON indent_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON indent_detail.uom_unit_id = uomunit.idLEFT JOIN inventory.t_material_issue_batch_mapper materialmapper ON issue_detail.id = materialmapper.material_issue_detail_idLEFT JOIN inventory.t_batch tb ON materialmapper.batch_id = tb.idLEFT JOIN m_uom_type uomtypemapper ON materialmapper.uom_type_id = uomtypemapper.idLEFT JOIN m_uom_unit uomunitmapper ON materialmapper.uom_unit_id = uomunitmapper.idLEFT JOIN adt.m_priority_master priority ON indent.priority_id = priority.priority_idLEFT JOIN inventory.m_indent_type indenttype ON indent.indent_type_id = indenttype.idLEFT JOIN m_unit_master unitinformation ON issue.unit_id = unitinformation.unit_idLEFT JOIN m_user_master umaddedby ON umaddedby.user_id = issue.added_byLEFT JOIN m_employee_master empaddedby ON empaddedby.user_id = umaddedby.user_idLEFT JOIN m_user_master umupdated ON umupdated.user_id = issue.added_byLEFT JOIN m_employee_master empupdated ON empupdated.user_id = umupdated.user_idWHERE issue_detail.is_active = true AND issue_detail.is_deleted = false;

-- public.get_material_picker source
CREATE OR REPLACE VIEW public.get_material_pickerAS SELECT DISTINCT picker.id,picker.added_date AS pickerdate,indent.indent_no,indent.added_date,fromstore.store_name AS fromstore,tostore.store_name AS tostore,priority.priority_desc,indenttype.type AS indenttype,m_status.status,m_item.name AS itemname,m_generic.name AS genericname,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,indentdetails.indent_quantity,indentdetails.pending_quantity,issuedetails.issue_quantity,pickerdetails.picker_quantity,unitinformation.unit_name,unitinformation.unit_address,m_item.code,unitinformation.imageFROM inventory.t_material_picker pickerJOIN inventory.t_material_picker_detail pickerdetails ON picker.id = pickerdetails.material_picker_idJOIN inventory.t_store_indent indent ON picker.store_indent_id = indent.idJOIN inventory.t_store_indent_detail indentdetails ON indent.id = indentdetails.store_indent_id AND indentdetails.id = pickerdetails.store_indent_detail_idJOIN m_store fromstore ON indent.from_store_id = fromstore.store_idJOIN m_store tostore ON indent.to_store_id = tostore.store_idLEFT JOIN adt.m_priority_master priority ON indent.priority_id = priority.priority_idLEFT JOIN inventory.m_indent_type indenttype ON indent.indent_type_id = indenttype.idLEFT JOIN m_status ON picker.status_id = m_status.idLEFT JOIN m_uom_type ON indentdetails.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON indentdetails.uom_unit_id = m_uom_unit.idLEFT JOIN inventory.t_material_issue issue ON picker.id = issue.material_picker_idLEFT JOIN inventory.t_material_issue_detail issuedetails ON issue.id = issuedetails.material_issue_id AND issuedetails.material_picker_detail_id = pickerdetails.material_picker_idLEFT JOIN m_item ON indentdetails.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idJOIN m_unit_master unitinformation ON picker.unit_id = unitinformation.unit_idWHERE pickerdetails.is_active = true;

-- public.get_misexpenses source
CREATE OR REPLACE VIEW public.get_misexpensesAS SELECT DISTINCT me.expense_id,me.bill_number,me.bill_date_time,me.amount AS meamount,me.name AS expencesname,me.account_head,er.expense_reciept_id,er.reciept_number,er.date_of_reciept,er.amount,er.reciept_cancelled,erd.payment_mode_id,paymode.payment_mode_desc,erd.amount AS amountdetail,acc.general_ledger_name AS hospital_account_desc,um.unit_name,um.unit_address,um.unit_contact,um.unit_email_id,um.unit_website,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,usermaster.user_id,um.unit_id,me.org_id,acc.general_ledger_id,me.bill_type,''::text AS status,0 AS outstanding,um.imageFROM billing.t_miscellaneous_expense meJOIN billing.t_miscellaneous_expense_reciept er ON me.expense_id = er.expense_idJOIN billing.t_miscellaneous_expense_reciept_details erd ON er.expense_reciept_id = erd.expense_reciept_idLEFT JOIN m_payment_mode_master paymode ON erd.payment_mode_id = paymode.payment_mode_idLEFT JOIN m_general_ledger_master acc ON me.account_head = acc.general_ledger_idJOIN m_unit_master um ON me.unit_id = um.unit_idJOIN m_user_master usermaster ON me.created_by = usermaster.user_idLEFT JOIN m_employee_master ON m_employee_master.user_id = usermaster.user_idWHERE me.is_cancelled = 'N'::bpchar AND er.reciept_cancelled = 'N'::bpchar AND me.status = 'A'::bpchar;

-- public.get_misexpenses_list source
CREATE OR REPLACE VIEW public.get_misexpenses_listAS SELECT DISTINCT me.expense_id,me.bill_number,me.bill_date_time,me.amount AS meamount,me.name AS expencesname,me.account_head,er.expense_reciept_id,er.reciept_number,er.date_of_reciept,er.amount,er.reciept_cancelled,erd.payment_mode_id,paymode.payment_mode_desc,erd.amount AS amountdetail,acc.general_ledger_name AS hospital_account_desc,um.unit_name,um.unit_address,um.unit_contact,um.unit_email_id,um.unit_website,usermaster.user_name,usermaster.user_id,um.unit_id,me.org_id,acc.general_ledger_id,CASEWHEN me.bill_type = 1 THEN 'Income'::textWHEN me.bill_type = 2 THEN 'Expense'::textELSE NULL::textEND AS bill_type,CASEWHEN me.bill_status = 1 THEN 'Pending'::textWHEN me.bill_status = 2 THEN 'Completed'::textWHEN me.bill_status = 3 THEN 'Cancelled'::textELSE NULL::textEND AS status,0 AS outstanding,concat(empreq.first_name, ' ', empreq.last_name) AS empreq,CASEWHEN trd.req_status = 1 THEN 'Pending'::textWHEN trd.req_status = 2 THEN 'Completed'::textELSE NULL::textEND AS req_status,me.bill_type AS billtypeid,me.bill_status AS billstatusid,me.remark,um.image,org.organization_nameFROM billing.t_miscellaneous_expense meJOIN billing.t_miscellaneous_expense_reciept er ON me.expense_id = er.expense_idJOIN billing.t_miscellaneous_expense_reciept_details erd ON er.expense_reciept_id = erd.expense_reciept_idLEFT JOIN m_payment_mode_master paymode ON erd.payment_mode_id = paymode.payment_mode_idLEFT JOIN m_general_ledger_master acc ON me.account_head = acc.general_ledger_idLEFT JOIN m_unit_master um ON me.unit_id = um.unit_idLEFT JOIN m_organization_master org ON um.organization_id = org.organization_idLEFT JOIN m_user_master usermaster ON me.created_by = usermaster.user_idLEFT JOIN billing.t_request_discount trd ON me.expense_id = trd.expense_idLEFT JOIN m_user_master umreqto ON trd.request_sent_to = umreqto.user_idLEFT JOIN m_employee_master empreq ON umreqto.user_id = empreq.user_idWHERE me.is_cancelled = 'N'::bpchar AND er.reciept_cancelled = 'N'::bpchar;

-- public.get_mlc_register source
CREATE OR REPLACE VIEW public.get_mlc_registerAS SELECT pr.uhid_number AS registration_no,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS name,mlc.created_date AS encounterdate,a.admission_number,mlc.fir_no,mlc.police_buckle_no,mlc.police_station_name,mlc.mlc_contact_no,u.unit_name,u.unit_address,u.unit_email_id,u.unit_contact,u.unit_id,u.imageFROM adt.t_medico_legal mlcJOIN adt.t_admission a ON mlc.admission_id = a.admission_idJOIN patient.t_patient_registration pr ON a.patient_id = pr.patient_idJOIN unitinformation u ON mlc.unit_id = u.unit_idUNIONSELECT upr.t_uhid AS registration_no,upr.patient_name AS name,mlc.created_date AS encounterdate,a.admission_number,mlc.fir_no,mlc.police_buckle_no,mlc.police_station_name,mlc.mlc_contact_no,u.unit_name,u.unit_address,u.unit_email_id,u.unit_contact,u.unit_id,u.imageFROM adt.t_medico_legal mlcJOIN adt.t_admission a ON mlc.admission_id = a.admission_idJOIN patient.m_unknown_patient_registration upr ON a.t_patient_id = upr.unknown_patient_idJOIN unitinformation u ON mlc.unit_id = u.unit_id;

-- public.get_modalityappointment source
CREATE OR REPLACE VIEW public.get_modalityappointmentAS SELECT am.appointment_id,pim.uhid_number,pim.patientname,pim.age,pim.email,pim.mobile_number,modmaster.modality_desc,sm.slot_id,sm.appointment_date,sm.from_time,status.appointment_status_desc,pim.patientaddress,pim.regdate,pim.gender_name,unit.unit_name,unit.unit_address,unit.unit_contact,unit.unit_country_code,unit.unit_contact_2,unit.unit_contact_3,specilitymaster.speciality_name,unit.unit_website,unit.unit_email_id,abs(date_part('Year'::text, age(pim.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,um.user_name,unit.imageFROM opd.m_appointment_master amJOIN opd.m_slot_master sm ON am.slot_id = sm.slot_idJOIN patientinformation pim ON am.patient_id = pim.patient_idJOIN opd.m_appointment_status_master status ON am.appointment_status_id = status.appointment_status_idLEFT JOIN t_unit_application_billing_configuration tuapbc ON sm.speciality_id = tuapbc.hemodialysis_speciality_idLEFT JOIN doctor.m_speciality_master specilitymaster ON specilitymaster.speciality_id = sm.speciality_idLEFT JOIN unitinformation unit ON am.unit_id = unit.unit_idLEFT JOIN m_user_master um ON am.created_by = um.user_idLEFT JOIN m_modality_master modmaster ON sm.modality_id = modmaster.modality_id;

-- public.get_narcoticsitem source
CREATE OR REPLACE VIEW public.get_narcoticsitemAS SELECT DISTINCT m_item.id,m_item.code,m_item.name AS itemname,m_generic.name AS genericname,batch.batch_no,storestock.available_qty,m_store.store_name,um.unit_name,um.unit_address,m_store.store_id,um.unit_id,um.image,batch.expiry_dateFROM m_itemJOIN m_generic ON m_item.generic_id = m_generic.idJOIN inventory.t_batch batch ON m_item.id = batch.item_idJOIN inventory.t_store_stock storestock ON storestock.batch_id = batch.idJOIN m_store ON m_store.store_id = storestock.store_idLEFT JOIN m_unit_master um ON m_item.unit_id = um.unit_idWHERE m_item.is_narcotic = true;

-- public.get_openingbal source
CREATE OR REPLACE VIEW public.get_openingbalAS SELECT bal.id,bal.opb_no,m_store.store_name,m_status.status,bal.added_by,bal.approved_by,um.user_name,uma.user_name AS usernameapproval,m_item.name AS itemname,baldetail.quantity,baldetail.batch_no,baldetail.approved_quantity,baldetail.cop,baldetail.mrp,baldetail.tax_amount,baldetail.remark,bal.added_date,bal.approved_date,unitinformation.unit_name,unitinformation.unit_address,baldetail.expiry_date,uom.unit AS uomunit,uomtype.type AS uomtype,unitinformation.imageFROM inventory.t_opening_balance balJOIN inventory.t_opening_balance_detail baldetail ON bal.id = baldetail.opening_balance_idLEFT JOIN m_store ON bal.store_id = m_store.store_idLEFT JOIN m_status ON bal.status_id = m_status.idLEFT JOIN m_item ON baldetail.item_id = m_item.idLEFT JOIN m_user_master um ON bal.added_by = um.user_idLEFT JOIN m_user_master uma ON bal.added_by = uma.user_idLEFT JOIN unitinformation ON bal.unit_id = unitinformation.unit_idLEFT JOIN m_uom_unit uom ON baldetail.uom_unit_id = uom.idLEFT JOIN m_uom_type uomtype ON baldetail.uom_type_id = uomtype.id;

-- public.get_ot_reservation source
CREATE OR REPLACE VIEW public.get_ot_reservationAS SELECT DISTINCT otr.ot_reservation_id,otr.ot_reservation_no,pim.patient_id,pim.patientname,theatre.theatre_name,ottable.table_name,staffschedule.created_date,staffschedule.f_time,visittype.visit_type_name,servicemaster.service_standard_name,om.is_primary_secondary,fordoctor.user_id,fordoctor.doctor,um.unit_name,um.unit_address,um.imageFROM otims.t_ot_reservation otrJOIN patientinformation pim ON otr.patient_id = pim.patient_idJOIN otims.t_procedure_ot_schedule staffschedule ON otr.schedule_id = staffschedule.procedure_schedule_idJOIN otims.m_operation_theatre theatre ON staffschedule.theatre_id = theatre.operation_theatre_idJOIN otims.m_operation_table ottable ON staffschedule.table_id = ottable.operation_table_idJOIN otims.t_procedure_req_mst reqmaster ON otr.pro_req_id = reqmaster.pro_req_idJOIN m_visit_type_master visittype ON reqmaster.visit_type_id = visittype.visit_type_idJOIN otims.t_procedure_order_master om ON om.pro_req_id = otr.pro_req_idJOIN service.m_service_master servicemaster ON om.service_id = servicemaster.service_master_idJOIN otims.t_procedure_order_staff orderstaff ON orderstaff.procedure_order_id = om.procedure_order_idLEFT JOIN unitinformation um ON otr.unit_id = um.unit_idJOIN ( SELECT DISTINCT doctorsched.pro_req_id,doctorsched.user_id,((('Dr.'::text || ''::text) || docmaster.first_name::text) || ' '::text) || docmaster.last_name::text AS doctorFROM otims.t_procedure_staff_schedule doctorschedLEFT JOIN doctor.m_doctor_master docmaster ON doctorsched.user_id = docmaster.user_idWHERE doctorsched.role_id = 3) fordoctor ON otr.pro_req_id = fordoctor.pro_req_id;

-- public.get_patient_consumable_pendingindent source
CREATE OR REPLACE VIEW public.get_patient_consumable_pendingindentAS SELECT DISTINCT issue.id,patindent.indent_no,visittype.visit_type_name,adm.admission_number,patinfo.uhid_number,patinfo.patientname,((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,sm.speciality_name,reqstore.store_name AS reqstore,tostore.store_name AS tostore,ward.ward_name,bed.bed_desc,item.code,item.name AS itemname,generic.name AS generic,uomtype.type AS uomtype,uom.unit AS uomunit,indentdetail.indent_quantity,um.unit_name,um.unit_address,m_status.status,patindent.added_date,item.id AS itemid,( SELECT COALESCE(sum(storestock.available_qty), 0::bigint) AS "coalesce"FROM inventory.t_batch batchJOIN inventory.t_store_stock storestock ON storestock.batch_id = batch.id AND storestock.is_deleted = false AND storestock.is_active = true AND storestock.unit_id = um.unit_idJOIN m_item item_1 ON item_1.id = batch.item_id AND item_1.is_deleted = false AND item_1.is_active = true AND item_1.unit_id = um.unit_idJOIN m_store store ON store.store_id = storestock.store_id AND store.is_deleted = false AND store.is_active = true AND store.unit_id = um.unit_id AND storestock.available_qty &gt; 0WHERE store.store_id = tostore.store_id AND item_1.id = indentdetail.item_id) AS stock,um.imageFROM pharmacy.t_patient_indent patindentJOIN pharmacy.t_patient_indent_detail indentdetail ON patindent.id = indentdetail.patient_indent_idJOIN m_item item ON indentdetail.item_id = item.idLEFT JOIN m_generic generic ON item.generic_id = generic.idLEFT JOIN m_uom_type uomtype ON indentdetail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uom ON indentdetail.uom_unit_id = uom.idLEFT JOIN m_store reqstore ON patindent.store_id = reqstore.store_idLEFT JOIN m_store tostore ON patindent.to_store_id = tostore.store_idJOIN adt.t_admission adm ON patindent.admission_id = adm.admission_idLEFT JOIN m_visit_type_master visittype ON patindent.visit_type_id = visittype.visit_type_idLEFT JOIN adt.m_ward_master ward ON patindent.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON patindent.bed_id = bed.bed_idJOIN patientinformation patinfo ON adm.patient_id = patinfo.patient_idLEFT JOIN doctor.m_doctor_master dm ON patindent.doctor_id = dm.doctor_idLEFT JOIN doctor.m_speciality_master sm ON dm.speciality_id = sm.speciality_idJOIN m_unit_master um ON patindent.unit_id = um.unit_idJOIN m_status ON patindent.status_id = m_status.idJOIN pharmacy.t_issue issue ON patindent.id = issue.patient_indent_id;

-- public.get_patient_indent source
CREATE OR REPLACE VIEW public.get_patient_indentAS SELECT indent.id,indent.indent_no,indent.added_date,indent.added_by,m_store.store_name,indent.visit_type_id,ward.ward_name,bed.bed_desc,pim.uhid_number,pim.patientname,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,m_item.code,m_item.name AS itemname,m_generic.name AS genericname,m_status.status,indent_detail.indent_quantity,indent_detail.pending_quantity,adm.admission_number,unitinformation.unit_name,unitinformation.unit_address,m_uom_type.type AS uomtype,m_uom_unit.unit AS uomunit,um.user_name,uma.user_name AS usernameupdatedFROM pharmacy.t_patient_indent indentJOIN pharmacy.t_patient_indent_detail indent_detail ON indent.id = indent_detail.patient_indent_idLEFT JOIN m_store ON indent.store_id = m_store.store_idLEFT JOIN adt.t_admission adm ON indent.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admdetail ON adm.admission_id = admdetail.admission_idLEFT JOIN adt.m_ward_master ward ON admdetail.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON admdetail.bed_id = bed.bed_idLEFT JOIN patientinformation pim ON indent.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master dm ON indent.doctor_id = dm.doctor_idLEFT JOIN m_item ON indent_detail.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type ON indent_detail.uom_type_id = m_uom_type.idLEFT JOIN m_uom_unit ON indent_detail.uom_unit_id = m_uom_unit.idLEFT JOIN unitinformation ON indent.unit_id = unitinformation.unit_idLEFT JOIN m_user_master um ON indent.added_by = um.user_idLEFT JOIN m_user_master uma ON indent.added_by = uma.user_idLEFT JOIN m_status ON indent.status_id = m_status.idWHERE admdetail.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adm.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1)) AND indent_detail.is_active = true;

-- public.get_patientconsumableissue source
CREATE OR REPLACE VIEW public.get_patientconsumableissueAS SELECT DISTINCT t_issue.id,t_issue.issue_no,t_issue.added_date,patindent.indent_no,visittype.visit_type_name,adm.admission_number,patinfo.uhid_number,patinfo.patientname,((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,sm.speciality_name,reqstore.store_name AS reqstore,tostore.store_name AS tostore,ward.ward_name,bed.bed_desc,item.code,item.name AS itemname,generic.name AS generic,batch.batch_no,uomtype.type AS uomtype,uom.unit AS uomunit,indentdetail.indent_quantity,stock.available_qty,batchmap.issue_quantity,um.unit_name,um.unit_addressFROM pharmacy.t_issue t_issueJOIN pharmacy.t_issue_detail issuedetail ON issuedetail.issue_id = t_issue.idJOIN pharmacy.t_patient_indent patindent ON t_issue.patient_indent_id = patindent.idJOIN pharmacy.t_patient_indent_detail indentdetail ON patindent.id = indentdetail.patient_indent_id AND indentdetail.id = issuedetail.patient_indent_detail_idJOIN m_item item ON indentdetail.item_id = item.idLEFT JOIN m_generic generic ON item.generic_id = generic.idJOIN pharmacy.t_issue_detail_batch_mapper batchmap ON issuedetail.id = batchmap.issue_detail_idJOIN inventory.t_batch batch ON batchmap.batch_id = batch.idLEFT JOIN m_uom_type uomtype ON indentdetail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uom ON indentdetail.uom_unit_id = uom.idLEFT JOIN m_store reqstore ON patindent.store_id = reqstore.store_idLEFT JOIN m_store tostore ON patindent.to_store_id = tostore.store_idJOIN inventory.t_store_stock stock ON batch.id = stock.batch_id AND stock.store_id = tostore.store_idLEFT JOIN m_visit_type_master visittype ON t_issue.visit_type_id = visittype.visit_type_idJOIN adt.t_admission adm ON t_issue.admission_id = adm.admission_idJOIN adt.t_admission_details admdetail ON adm.admission_id = admdetail.admission_idLEFT JOIN adt.m_ward_master ward ON admdetail.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON admdetail.bed_id = bed.bed_idJOIN patientinformation patinfo ON adm.patient_id = patinfo.patient_idLEFT JOIN doctor.m_doctor_master dm ON t_issue.doctor_id = dm.doctor_idLEFT JOIN doctor.m_speciality_master sm ON dm.speciality_id = sm.speciality_idJOIN m_unit_master um ON t_issue.unit_id = um.unit_idWHERE admdetail.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adm.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1)) AND issuedetail.is_active = true;

-- public.get_patientcount source
CREATE OR REPLACE VIEW public.get_patientcountAS WITH cte AS (SELECT pt.created_date::date AS created_date,'IP'::text AS type,count(*) AS totalFROM patient.t_patient_registration ptWHERE (pt.patient_id IN ( SELECT t_admission.patient_idFROM adt.t_admission))GROUP BY (pt.created_date::date), 'IP'::textUNIONSELECT pt.created_date::date AS created_date,'OP'::text AS type,count(*) AS totalFROM patient.t_patient_registration ptGROUP BY (pt.created_date::date), 'OP'::text)SELECT created_date,type,totalFROM cteORDER BY created_date;

-- public.get_patientcount_transactional_count source
CREATE OR REPLACE VIEW public.get_patientcount_transactional_countAS WITH cte AS (SELECT pt.created_date::date AS created_date,'IP'::text AS type,count(*) AS total,pt.unit_id,pt.organization_idFROM patient.t_patient_registration ptWHERE (pt.patient_id IN ( SELECT t_admission.patient_idFROM adt.t_admission))GROUP BY (pt.created_date::date), 'IP'::text, pt.unit_id, pt.organization_idUNIONSELECT pt.created_date::date AS created_date,'OP'::text AS type,count(*) AS total,pt.unit_id,pt.organization_idFROM patient.t_patient_registration ptGROUP BY (pt.created_date::date), 'OP'::text, pt.unit_id, pt.organization_idUNIONSELECT pt.created_date::date AS created_date,'NewReg'::text AS type,count(*) AS total,pt.unit_id,pt.organization_idFROM patient.t_patient_registration ptWHERE (( SELECT count(em.patient_id) AS countFROM opd.t_encounter_master emWHERE em.patient_id = pt.patient_id)) &lt;= 1GROUP BY (pt.created_date::date), 'NewReg'::text, pt.unit_id, pt.organization_idUNIONSELECT rm.date_of_reciept::date AS created_date,'Receipt'::text AS type,count(*) AS total,rm.unit_id,rm.orgnization_id AS organization_idFROM billing.t_payment_reciept_master rmWHERE COALESCE(rm.is_cancelled, 'N'::"char") = 'N'::"char"GROUP BY (rm.date_of_reciept::date), 'Receipt'::text, rm.unit_id, rm.orgnization_id)SELECT created_date,type,total,unit_id,organization_idFROM cteORDER BY created_date;

-- public.get_patientcount_transactional_count_totalpatient source
CREATE OR REPLACE VIEW public.get_patientcount_transactional_count_totalpatientAS WITH cte AS (SELECT pt.created_date::date AS created_date,'Total'::text AS type,count(*) AS total,1 AS srno,pt.organization_id,om.organization_nameFROM patient.t_patient_registration ptJOIN m_organization_master om ON pt.organization_id = om.organization_idGROUP BY (pt.created_date::date), 'OP'::text, pt.organization_id, om.organization_nameUNIONSELECT pt.created_date::date AS created_date,'OP'::text AS type,count(*) AS total,2 AS srno,pt.organization_id,om.organization_nameFROM patient.t_patient_registration ptJOIN m_organization_master om ON pt.organization_id = om.organization_idGROUP BY (pt.created_date::date), 'OP'::text, pt.organization_id, om.organization_nameUNIONSELECT pt.created_date::date AS created_date,'IP'::text AS type,count(*) AS total,3 AS srno,pt.organization_id,om.organization_nameFROM patient.t_patient_registration ptJOIN m_organization_master om ON pt.organization_id = om.organization_idWHERE (pt.patient_id IN ( SELECT t_admission.patient_idFROM adt.t_admission))GROUP BY (pt.created_date::date), 'IP'::text, pt.organization_id, om.organization_nameUNIONSELECT pt.created_date::date AS created_date,'NewReg'::text AS type,count(*) AS total,4 AS srno,pt.organization_id,om.organization_nameFROM patient.t_patient_registration ptJOIN m_organization_master om ON pt.organization_id = om.organization_idWHERE (( SELECT count(em.patient_id) AS countFROM opd.t_encounter_master emWHERE em.patient_id = pt.patient_id)) &lt;= 1GROUP BY (pt.created_date::date), 'NewReg'::text, pt.organization_id, om.organization_nameUNIONSELECT rm.date_of_reciept::date AS created_date,'Receipt'::text AS type,count(*) AS total,5 AS srno,rm.orgnization_id AS organization_id,om.organization_nameFROM billing.t_payment_reciept_master rmJOIN m_organization_master om ON rm.orgnization_id = om.organization_idWHERE COALESCE(rm.is_cancelled, 'N'::"char") = 'N'::"char"GROUP BY (rm.date_of_reciept::date), 'Receipt'::text, rm.orgnization_id, om.organization_nameUNIONSELECT DISTINCT en.consultation_stop_time::date AS created_date,'CaseSheet'::text AS type,count(en.encounter_id) AS total,6 AS srno,en.organization_id,om.organization_nameFROM opd.t_encounter_details enJOIN m_organization_master om ON en.organization_id = om.organization_idWHERE en.consultation_stop_time::date IS NOT NULLGROUP BY en.consultation_stop_time, 'CaseSheet'::text, en.organization_id, om.organization_name)SELECT created_date,type,total,srno,organization_id,organization_nameFROM cteORDER BY srno;

-- public.get_patientcountdetails source
CREATE OR REPLACE VIEW public.get_patientcountdetailsAS WITH cte AS (SELECT (((pt.first_name::text || ' '::text) || pt.middle_name::text) || ' '::text) || pt.last_name::text AS patientname,pt.created_date::date AS created_date,'OP'::text AS type,ptinfo.patientmobile,ptinfo.patientaddress,ptinfo.gender_name,um.unit_id,um.unit_name,ptinfo.gender_id,um.organization_idFROM patient.t_patient_registration ptJOIN patientinformation ptinfo ON pt.patient_id = ptinfo.patient_idJOIN unitinformation um ON ptinfo.unit_id = um.unit_idJOIN patient.t_patient_details pd ON pt.patient_id = pd.patient_idWHERE pd.status = 'A'::bpchar)SELECT created_date,type,patientname,patientmobile,patientaddress,gender_name,unit_id,unit_name,gender_id,organization_idFROM cteORDER BY created_date;

-- public.get_patientgatepass source
CREATE OR REPLACE VIEW public.get_patientgatepassAS SELECT DISTINCT visitoraga0_.visitor_patient_id,visitorpat1_.visitor_patient_mapper_id,visitoraga0_.pass_number,visitorpat1_.visitor_pass_type_id,visitorpat1_.expiry_date,visitorpas2_.visitor_pass_type_desc,visitoraga0_.organization_id,visitoraga0_.unit_id,um.unit_name,um.unit_address,um.image,pim.patientname,pim.ageyear,pim.gender_name,adm.created_date AS admdate,adm.admission_number,visitorpat1_.created_date,adtt.ward_id,wm.ward_name,concat(em.first_name, ' ', em.last_name) AS usernameFROM adt.t_visitor_against_patient visitoraga0_JOIN adt.t_visitor_patient_mapper visitorpat1_ ON visitoraga0_.visitor_patient_id = visitorpat1_.visitor_patient_idJOIN adt.t_admission adm ON visitoraga0_.admission_id = adm.admission_idJOIN adt.t_admission_details adtt ON adtt.admission_id = adm.admission_idJOIN patientinformation pim ON pim.patient_id = adm.patient_idJOIN adt.m_visitor_pass_type_master visitorpas2_ ON visitorpat1_.visitor_pass_type_id = visitorpas2_.visitor_pass_type_idJOIN unitinformation um ON visitoraga0_.unit_id = um.unit_idJOIN adt.m_ward_master wm ON wm.ward_id = adtt.ward_idLEFT JOIN m_user_master umm ON umm.user_id = visitoraga0_.created_byJOIN m_employee_master em ON em.user_id = umm.user_idWHERE visitoraga0_.status = 'A'::bpchar AND visitorpat1_.status = 'A'::bpchar;

-- public.get_pendig_assigning_picker source
CREATE OR REPLACE VIEW public.get_pendig_assigning_pickerAS SELECT DISTINCT picker.id,pres.id AS presid,pres.visit_type_id,visit.visit_type_name,pres.prescription_date,pim.uhid_number,pim.patientname,ward.ward_name,bed.bed_desc,m_status.status,m_item.name AS itemname,generic.name AS genericname,presdetail.order_qty,presdetail.pending_qty,pres.prescription_no,pickerdetail.issue_quantity AS pickerdetailissueqty,added_items.issue_quantity AS itemdetailsissueqty,batch.expiry_date,uomtype.type AS uomtype,uomunit.unit AS uomunit,um.unit_name,um.unit_addressFROM pharmacy.t_assign_picker pickerJOIN pharmacy.t_prescription pres ON picker.prescription_id = pres.idLEFT JOIN pharmacy.t_prescription_detail presdetail ON pres.id = presdetail.prescription_idLEFT JOIN m_item ON presdetail.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idJOIN m_visit_type_master visit ON pres.visit_type_id = visit.visit_type_idLEFT JOIN adt.t_admission adm ON pres.admission_id = adm.admission_idLEFT JOIN adt.t_admission_details admdetail ON adm.admission_id = admdetail.admission_idLEFT JOIN patientinformation pim ON pres.patient_id = pim.patient_idLEFT JOIN adt.m_ward_master ward ON admdetail.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON admdetail.bed_id = bed.bed_idLEFT JOIN m_status ON picker.status_id = m_status.idLEFT JOIN pharmacy.t_assign_picker_detail pickerdetail ON picker.id = pickerdetail.assign_picker_idLEFT JOIN pharmacy.t_assign_picker_detail_added_items added_items ON added_items.assign_picker_id = picker.idLEFT JOIN inventory.t_batch batch ON pickerdetail.batch_id = batch.idLEFT JOIN m_uom_type uomtype ON pickerdetail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON pickerdetail.uom_unit_id = uomunit.idLEFT JOIN m_unit_master um ON picker.unit_id = um.unit_idWHERE admdetail.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adm.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1)) AND pickerdetail.issue_quantity &lt;&gt; 0;

-- public.get_pharmacybillreport source
CREATE OR REPLACE VIEW public.get_pharmacybillreportAS SELECT DISTINCT t_sale.id,CASEWHEN saletype.id = 1 THEN concat('IP-', t_sale.admission_id)::character varyingELSE t_sale.bill_noEND::character varying(50) AS bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patientname,''::text AS address,registration.uhid_number AS temp_uhid,CASEWHEN m_doctor_master.doctor_id IS NULL THEN t_temp_doctor.doctor_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(cm.company_id, cmip.company_id) AS company_id,COALESCE(cm.company_desc, cmip.company_desc::character varying) AS company_desc,m_status.id AS status_id,m_store.store_nameFROM pharmacy.t_saleLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = t_sale.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = t_sale.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN t_company_master cm ON cm.company_id = spd.payee_idLEFT JOIN t_company_master cmip ON cmip.company_id = spdip.payee_idLEFT JOIN m_status ON t_sale.status_id = m_status.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_active = trueUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,t_temp_patient_registration.patient_name AS patientname,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD/Walking'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(cm.company_id, cmip.company_id) AS company_id,COALESCE(cm.company_desc, cmip.company_desc::character varying) AS company_desc,m_status.id AS status_id,m_store.store_nameFROM pharmacy.t_saleLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = t_sale.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = t_sale.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN t_company_master cm ON cm.company_id = spd.payee_idLEFT JOIN t_company_master cmip ON cmip.company_id = spdip.payee_idLEFT JOIN m_status ON t_sale.status_id = m_status.idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale.is_active = true;

-- public.get_pharmacybillreport_details source
CREATE OR REPLACE VIEW public.get_pharmacybillreport_detailsAS SELECT t_sale.id,CASEWHEN saletype.id = 1 THEN concat('IP-', t_sale.admission_id)::character varyingELSE t_sale.bill_noEND::character varying(50) AS bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patientname,''::text AS address,registration.uhid_number AS temp_uhid,CASEWHEN m_doctor_master.doctor_id IS NULL THEN t_temp_doctor.doctor_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(cm.company_id, cmip.company_id) AS company_id,COALESCE(cm.company_desc, cmip.company_desc::character varying) AS company_desc,m_status.id AS status_id,m_store.store_name,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,m_item.name,t_batch.batch_no,t_batch.expiry_date,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,storageunit.name AS storageunitFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = t_sale.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = t_sale.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN t_company_master cm ON cm.company_id = spd.payee_idLEFT JOIN t_company_master cmip ON cmip.company_id = spdip.payee_idLEFT JOIN m_status ON t_sale.status_id = m_status.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_active = trueUNIONSELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,t_temp_patient_registration.patient_name AS patientname,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD/Walking'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(cm.company_id, cmip.company_id) AS company_id,COALESCE(cm.company_desc, cmip.company_desc::character varying) AS company_desc,m_status.id AS status_id,m_store.store_name,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,t_sale_detail.net_amount AS net_amount_detail,m_item.name,t_batch.batch_no,t_batch.expiry_date,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,storageunit.name AS storageunitFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN opd.t_patient_sponsor_details spd ON spd.encounter_id = t_sale.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details spdip ON spdip.admission_id = t_sale.admission_id AND spdip.priority_id = 1 AND spdip.status = 'A'::bpcharLEFT JOIN t_company_master cm ON cm.company_id = spd.payee_idLEFT JOIN t_company_master cmip ON cmip.company_id = spdip.payee_idLEFT JOIN m_status ON t_sale.status_id = m_status.idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale.is_active = true;

-- public.get_pharmacycollection source
CREATE OR REPLACE VIEW public.get_pharmacycollectionAS (SELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,concat(registration.first_name, ' ', registration.last_name) AS patientname,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,COALESCE(CASEWHEN mode1.payment_mode_id = 1 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS cashamount,COALESCE(CASEWHEN mode1.payment_mode_id = 2 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS chequeamount,COALESCE(CASEWHEN mode1.payment_mode_id = 3 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS creditcardamount,COALESCE(CASEWHEN mode1.payment_mode_id = 4 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales'::text AS salestype,mode1.added_date AS receiptdate,'\x'::bytea AS image,salestype.type AS saletrantype,COALESCE(CASEWHEN mode1.payment_mode_id = 8 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS e_transfer,t_sale.organization_id,t_sale.patient_id,mode1.id AS receiptid,0::bigint AS advrefFROM pharmacy.t_saleLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN pharmacy.t_sale_payment_mode mode1 ON t_sale.id = mode1.sale_id AND mode1.is_active = trueLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type salestype ON t_sale.sale_type_id = salestype.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_deleted = falseUNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,t_temp_patient_registration.patient_name AS patientname,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD/Walking'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,COALESCE(CASEWHEN mode1.payment_mode_id = 1 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS cashamount,COALESCE(CASEWHEN mode1.payment_mode_id = 2 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS chequeamount,COALESCE(CASEWHEN mode1.payment_mode_id = 3 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS creditcardamount,COALESCE(CASEWHEN mode1.payment_mode_id = 4 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales'::text AS salestype,mode1.added_date AS receiptdate,'\x'::bytea AS image,salestype.type AS saletrantype,COALESCE(CASEWHEN mode1.payment_mode_id = 8 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS e_transfer,t_sale.organization_id,t_sale.temp_patient_id AS patient_id,mode1.id AS receiptid,0::bigint AS advrefFROM pharmacy.t_saleLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN pharmacy.t_sale_payment_mode mode1 ON t_sale.id = mode1.sale_id AND mode1.is_active = trueLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type salestype ON t_sale.sale_type_id = salestype.idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale.is_deleted = false) UNION ALLSELECT DISTINCT t_return.id,t_return.return_no AS bill_no,t_return.added_date,t_return.total_return_amt AS total_amount,0 AS discount,t_return.total_return_amt AS net_amount,0 AS tax_amount,t_sale.sale_type_id,CASEWHEN COALESCE(t_sale.patient_id, 0) = 0 THEN t_temp_patient_registration.patient_name::textELSE concat(registration.first_name, ' ', registration.last_name)END AS patientname,''::text AS address,''::character varying AS temp_uhid,''::text AS doctorname,0 AS store_id,''::character varying AS counter_desc,0 AS counter_id,'Sales Return'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,um.user_id,COALESCE(CASEWHEN tprd.payment_mode_id = 1 THEN t_return.total_return_amtELSE NULL::double precisionEND, 0::double precision) AS cashamount,COALESCE(CASEWHEN tprd.payment_mode_id = 2 THEN tprd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS chequeamount,COALESCE(CASEWHEN tprd.payment_mode_id = 3 THEN tprd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS creditcardamount,COALESCE(CASEWHEN tprd.payment_mode_id = 4 THEN tprd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales Return'::text AS salestype,t_return.added_date AS receiptdate,'\x'::bytea AS image,'Sales Return'::text AS saletrantype,COALESCE(CASEWHEN tprd.payment_mode_id = 8 THEN tprd.amountELSE NULL::bigint::double precisionEND, 0::double precision)::bigint AS e_transfer,t_return.organization_id,t_sale.patient_id,t_return.id AS receiptid,COALESCE(CASEWHEN tprd.payment_mode_id = 9 THEN tprd.amountELSE NULL::bigint::double precisionEND, 0::double precision)::bigint AS advrefFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN m_unit_master unitinformation ON t_return.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN billing.t_payment_refund_master prm ON t_sale.id = prm.t_pharmacy_return_idLEFT JOIN billing.t_payment_refund_details tprd ON prm.payment_refund_id = tprd.payment_refund_idLEFT JOIN m_user_master um ON t_return.added_by = um.user_id AND t_return.is_active = true AND t_return.is_deleted = falseLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE t_return.status_id &lt;&gt; 9UNION ALLSELECT DISTINCT dd.deposit_details_id AS id,dd.deposit_details_id::character varying(50) AS bill_no,dd.created_date AS added_date,dm.deposit_amount AS total_amount,0 AS discount,dm.deposit_amount AS net_amount,0 AS tax_amount,0 AS sale_type_id,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,''::text AS address,''::character varying AS temp_uhid,''::text AS doctorname,0 AS store_id,''::character varying AS counter_desc,0 AS counter_id,'Pharmacy Deposit'::text AS flag,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS username,um.user_id,COALESCE(CASEWHEN dd.payment_mode_id = 1 THEN dd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS cashamount,COALESCE(CASEWHEN dd.payment_mode_id = 2 THEN dd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS chequeamount,COALESCE(CASEWHEN dd.payment_mode_id = 3 THEN dd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS creditcardamount,COALESCE(CASEWHEN dd.payment_mode_id = 4 THEN dd.amountELSE NULL::double precisionEND, 0::double precision)::bigint AS debitcardamount,umm.unit_name,umm.unit_address,umm.unit_address_2,umm.unit_id,dm.visit_type_id,'Pharmacy Deposit'::text AS salestype,dd.created_date AS receiptdate,'\x'::bytea AS image,'Pharmacy Deposit'::text AS saletrantype,COALESCE(CASEWHEN dd.payment_mode_id = 8 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision)::bigint AS e_transfer,umm.organization_id,pm.patient_id,0 AS receiptid,0::bigint AS advrefFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dd.amount &lt;&gt; 0::double precision AND dm.deposit_type_id = 6UNION ALLSELECT DISTINCT dd.deposit_details_id AS id,dd.deposit_details_id::character varying(50) AS bill_no,dd.created_date AS added_date,dm.deposit_amount AS total_amount,0 AS discount,dm.deposit_amount AS net_amount,0 AS tax_amount,0 AS sale_type_id,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,''::text AS address,''::character varying AS temp_uhid,''::text AS doctorname,0 AS store_id,''::character varying AS counter_desc,0 AS counter_id,'Pharmacy Consumed'::text AS flag,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS username,um.user_id,COALESCE(CASEWHEN dd.payment_mode_id = 1 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision)::bigint AS cashamount,COALESCE(CASEWHEN dd.payment_mode_id = 2 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision)::bigint AS chequeamount,COALESCE(CASEWHEN dd.payment_mode_id = 3 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision)::bigint AS creditcardamount,COALESCE(CASEWHEN dd.payment_mode_id = 4 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision)::bigint AS debitcardamount,umm.unit_name,umm.unit_address,umm.unit_address_2,umm.unit_id,dm.visit_type_id,'Pharmacy Consumed'::text AS salestype,dd.created_date AS receiptdate,'\x'::bytea AS image,'Pharmacy Consumed'::text AS saletrantype,0 AS e_transfer,umm.organization_id,pm.patient_id,0 AS receiptid,0::bigint AS advrefFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dd.consumed_amount &lt;&gt; 0::double precision AND dm.deposit_type_id = 6;

