nt,COALESCE(CASEWHEN tprd.payment_mode_id = 3 THEN tprd.amountELSE NULL::double precisionEND, 0::double precision) AS creditcardamount,COALESCE(CASEWHEN tprd.payment_mode_id = 4 THEN tprd.amountELSE NULL::double precisionEND, 0::double precision) AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales Return'::text AS salestype,t_return.added_date AS receiptdate,'\x'::bytea AS image,'Sales Return'::text AS saletrantype,COALESCE(CASEWHEN tprd.payment_mode_id = 8 THEN tprd.amountELSE NULL::bigint::double precisionEND, 0::double precision) AS e_transfer,t_return.organization_id,t_sale.patient_id,t_return.id AS receiptid,COALESCE(CASEWHEN tprd.payment_mode_id = 9 THEN tprd.amountELSE NULL::bigint::double precisionEND, 0::double precision) AS advrefFROM pharmacy.t_returnJOIN pharmacy.t_return_detail ON t_return.id = t_return_detail.return_idJOIN pharmacy.t_sale ON t_sale.id = t_return.sale_idJOIN m_unit_master unitinformation ON t_return.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN billing.t_payment_refund_master prm ON t_sale.id = prm.t_pharmacy_return_idLEFT JOIN billing.t_payment_refund_details tprd ON prm.payment_refund_id = tprd.payment_refund_idLEFT JOIN m_user_master um ON t_return.added_by = um.user_id AND t_return.is_active = true AND t_return.is_deleted = falseLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE t_return.status_id &lt;&gt; 9UNION ALLSELECT DISTINCT dd.deposit_details_id AS id,dd.deposit_details_id::character varying(50) AS bill_no,dd.created_date AS added_date,dm.deposit_amount AS total_amount,0 AS discount,dm.deposit_amount AS net_amount,0 AS tax_amount,0 AS sale_type_id,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,''::text AS address,''::character varying AS temp_uhid,''::text AS doctorname,0 AS store_id,''::character varying AS counter_desc,0 AS counter_id,'Pharmacy Deposit'::text AS flag,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS username,um.user_id,COALESCE(CASEWHEN dd.payment_mode_id = 1 THEN dd.amountELSE NULL::double precisionEND, 0::double precision) AS cashamount,COALESCE(CASEWHEN dd.payment_mode_id = 2 THEN dd.amountELSE NULL::double precisionEND, 0::double precision) AS chequeamount,COALESCE(CASEWHEN dd.payment_mode_id = 3 THEN dd.amountELSE NULL::double precisionEND, 0::double precision) AS creditcardamount,COALESCE(CASEWHEN dd.payment_mode_id = 4 THEN dd.amountELSE NULL::double precisionEND, 0::double precision) AS debitcardamount,umm.unit_name,umm.unit_address,umm.unit_address_2,umm.unit_id,dm.visit_type_id,'Pharmacy Deposit'::text AS salestype,dd.created_date AS receiptdate,'\x'::bytea AS image,'Pharmacy Deposit'::text AS saletrantype,COALESCE(CASEWHEN dd.payment_mode_id = 8 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision) AS e_transfer,umm.organization_id,pm.patient_id,0 AS receiptid,0::bigint AS advrefFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dd.amount &lt;&gt; 0::double precision AND dm.deposit_type_id = 6 AND dm.status::text = 'A'::bpchar::textUNION ALLSELECT DISTINCT dd.deposit_details_id AS id,dd.deposit_details_id::character varying(50) AS bill_no,dd.created_date AS added_date,dm.deposit_amount AS total_amount,0 AS discount,dm.deposit_amount AS net_amount,0 AS tax_amount,0 AS sale_type_id,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,''::text AS address,''::character varying AS temp_uhid,''::text AS doctorname,0 AS store_id,''::character varying AS counter_desc,0 AS counter_id,'Pharmacy Consumed'::text AS flag,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS username,um.user_id,COALESCE(CASEWHEN dd.payment_mode_id = 1 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision) AS cashamount,COALESCE(CASEWHEN dd.payment_mode_id = 2 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision) AS chequeamount,COALESCE(CASEWHEN dd.payment_mode_id = 3 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision) AS creditcardamount,COALESCE(CASEWHEN dd.payment_mode_id = 4 THEN dd.consumed_amountELSE NULL::double precisionEND, 0::double precision) AS debitcardamount,umm.unit_name,umm.unit_address,umm.unit_address_2,umm.unit_id,dm.visit_type_id,'Pharmacy Consumed'::text AS salestype,dd.created_date AS receiptdate,'\x'::bytea AS image,'Pharmacy Consumed'::text AS saletrantype,0 AS e_transfer,umm.organization_id,pm.patient_id,0 AS receiptid,0::bigint AS advrefFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_idJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dd.consumed_amount &lt;&gt; 0::double precision AND dm.deposit_type_id = 6 AND dm.status::text = 'A'::bpchar::text) UNIONSELECT DISTINCT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,concat(registration.first_name, ' ', registration.last_name) AS patientname,t_patient_details.address,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,COALESCE(CASEWHEN mode1.payment_mode_id = 1 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision) AS cashamount,COALESCE(CASEWHEN mode1.payment_mode_id = 2 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision) AS chequeamount,COALESCE(CASEWHEN mode1.payment_mode_id = 3 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision) AS creditcardamount,COALESCE(CASEWHEN mode1.payment_mode_id = 4 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision) AS debitcardamount,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,t_sale.visit_type_id,'Sales'::text AS salestype,t_sale.added_date AS receiptdate,'\x'::bytea AS image,salestype.type AS saletrantype,COALESCE(CASEWHEN mode1.payment_mode_id = 8 THEN mode1.amountELSE NULL::double precisionEND, 0::double precision) AS e_transfer,t_sale.organization_id,t_sale.patient_id,mode1.id AS receiptid,t_sale.net_amount AS advrefFROM pharmacy.t_saleLEFT JOIN patient.t_patient_registration registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN patient.t_patient_details ON t_patient_details.patient_id = registration.patient_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN pharmacy.t_sale_payment_mode mode1 ON t_sale.id = mode1.sale_id AND mode1.is_active = trueLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idLEFT JOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type salestype ON t_sale.sale_type_id = salestype.idJOIN billing.t_payment_deposite_consumption deptcons ON t_sale.id = deptcons.sale_id AND deptcons.status = 'A'::bpcharWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_deleted = false;

-- public.get_physical_inspection_details source
CREATE OR REPLACE VIEW public.get_physical_inspection_detailsAS SELECT phi.id,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.inward_number,grn.inward_date,m_vendor.name AS vendorname,m_vendor.address,m_vendor.gst_no,m_store.store_name,m_item.name,grnd.batch_no,grnd.cop,grnd.mrp,grnd.discount,grnd.tax_percentage,grnd.tax_amount,grnd.total_discount,grnd.total_other_amount AS total_other_amount_detail,grnd.net_amount,m_store.store_id,grn.total_tax_ammount,grn.total_other_amount,grnd.grn_approved_quantity,grnd.grn_received_quantity,u.unit_name,u.unit_address,u.unit_address_2,u.unit_website,s.status,u.imageFROM procurement.t_physical_inspection phiJOIN procurement.t_physical_inspection_detail phid ON phi.id = phid.physical_inspection_idJOIN procurement.t_good_receipt_note grn ON phi.grn_id = grn.idJOIN procurement.t_good_receipt_note_detail grnd ON phid.grn_detail_id = grnd.idLEFT JOIN m_vendor ON m_vendor.id = grn.vendor_idLEFT JOIN inventory.t_batch tb ON grnd.batch_id = tb.idLEFT JOIN m_item ON tb.item_id = m_item.idJOIN m_store ON grn.store_id = m_store.store_idLEFT JOIN unitinformation u ON grn.unit_id = u.unit_idLEFT JOIN m_status s ON phi.status_id = s.id;

-- public.get_purchase_request source
CREATE OR REPLACE VIEW public.get_purchase_requestAS SELECT purreq.purchase_no,purreq.added_date,m_store.store_name,assettype.type AS assettype,reqtype.type AS reqtype,m_status.status,statusappro.status AS statusapproval,um.user_name,uma.user_name AS usernamea,m_item.code,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,reqdetail.quantity,reqdetail.specification,purreq.id,unit.unit_name,unit.unit_address,unit.imageFROM procurement.t_purchase_request purreqJOIN procurement.t_purchase_request_detail reqdetail ON purreq.id = reqdetail.purchase_request_idJOIN m_store ON purreq.store_id = m_store.store_idLEFT JOIN m_asset_type assettype ON purreq.asset_type_id = assettype.idLEFT JOIN m_request_type reqtype ON purreq.request_type_id = reqtype.idLEFT JOIN m_status ON purreq.status_id = m_status.idLEFT JOIN m_status statusappro ON purreq.approval_status_id = statusappro.idLEFT JOIN m_user_master um ON purreq.added_by = um.user_idLEFT JOIN m_user_master uma ON purreq.approved_by = uma.user_idLEFT JOIN m_item ON reqdetail.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON reqdetail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON reqdetail.uom_unit_id = uomunit.idLEFT JOIN m_unit_master unit ON purreq.unit_id = unit.unit_idWHERE reqdetail.is_active = true;

-- public.get_quotation_enquiry source
CREATE OR REPLACE VIEW public.get_quotation_enquiryAS SELECT request.qr_no,m_store.store_name,assettype.type AS assettype,reqtype.type AS reqtype,request.remark,statusappro.status AS statusappro,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,request_detail.quantity,request_detail.expected_payment,request_detail.pending_quantity,unit.unit_name,unit.unit_address,request.id,m_status.status,request.added_date,um.user_name,unit.imageFROM procurement.t_quotation_request requestJOIN procurement.t_quotation_request_detail request_detail ON request.id = request_detail.qr_idLEFT JOIN m_status ON request.status_id = m_status.idJOIN m_store ON request.store_id = m_store.store_idLEFT JOIN m_status statusappro ON request.approval_status_id = statusappro.idLEFT JOIN m_user_master um ON request.added_by = um.user_idLEFT JOIN m_item ON request_detail.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON request_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON request_detail.uom_unit_id = uomunit.idLEFT JOIN m_unit_master unit ON request.unit_id = unit.unit_idLEFT JOIN m_asset_type assettype ON request.asset_type_id = assettype.idLEFT JOIN m_request_type reqtype ON request.request_type_id = reqtype.idWHERE request_detail.is_active = true;

-- public.get_radio_test_countandrevenue source
CREATE OR REPLACE VIEW public.get_radio_test_countandrevenueAS SELECT pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS p_name,servmst.service_standard_name,billdtls.rate,billdtls.service_id,speciality_master.speciality_name,billmst.bill_number,billmst.bill_date_time,billdtls.ord_doc_id,''::text AS first_name,''::text AS last_name,billmst.visit_type_id,billmst.unit_id,billdtls.created_date AS orderdate,(((em.first_name::text || ' '::text) || em.middle_name::text) || ' '::text) || em.last_name::text AS username,u.unit_name,u.unit_address,u.unit_contact,ssm.sub_speciality_name,billdtls.net_amt,ssm.sub_speciality_id,speciality_master.speciality_id,u.imageFROM billing.m_billing_master billmstLEFT JOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_id AND billmst.bill_cancelled = 'N'::bpcharLEFT JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master speciality_master ON speciality_master.speciality_id = servmst.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON servmst.sub_speciality_id = ssm.sub_speciality_idJOIN patient.t_patient_registration pr ON billmst.patient_id = pr.patient_idLEFT JOIN m_employee_master em ON billdtls.created_by = em.user_idJOIN m_unit_master u ON billmst.unit_id = u.unit_idWHERE speciality_master.speciality_id = (( SELECT tu.radiology_speciality_idFROM t_unit_application_billing_configuration tuWHERE billmst.unit_id = tu.unit_id));
-- public.get_refer_doctorreport source
CREATE OR REPLACE VIEW public.get_refer_doctorreportAS SELECT DISTINCT em.encounter_id,em.encounter_number,em.encounter_date,sm.speciality_name,rm.referral_name,reffer.referral_type_id,rm.referral_id,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,CASEWHEN em.user_defined_visit_type_id = 1 THEN 'New Visit'::textWHEN em.user_defined_visit_type_id = 2 THEN 'Follow up'::textELSE 'New Visit'::textEND AS visit_type,bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.net_amount,pim.uhid_number,pim.patientname,um.unit_name,um.unit_address,um.unit_id,um.imageFROM opd.t_encounter_master emJOIN doctor.m_speciality_master sm ON em.dept_id = sm.speciality_idJOIN t_referal_details reffer ON em.encounter_id = reffer.encounter_idJOIN adt.m_referral_master rm ON reffer.referral_id = rm.referral_idLEFT JOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_idLEFT JOIN billing.m_billing_master bm ON em.encounter_id = bm.encounter_idJOIN patientinformation pim ON em.patient_id = pim.patient_idJOIN m_unit_master um ON em.unit_id = um.unit_idWHERE reffer.referral_type_id = 115;

-- public.get_referral_info source
CREATE OR REPLACE VIEW public.get_referral_infoAS SELECT COALESCE(m_refferel.referral_name::character varying) AS referral_contact_person,encounter.created_date,typemaster.referral_type_name,admreff.referral_remark,'OPD'::text AS opd,COALESCE(admreff.visit_type_id, 1) AS visit_type_id,pr.uhid_number,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,pr.bar_code,age(pr.dob) AS age,pr.mobile_number,typemaster.referral_type_id,um.unit_id,um.unit_name,um.unit_address,'\x'::bytea AS image,pd.address,m_refferel.referral_idFROM opd.t_encounter_master encounterJOIN t_referal_details admreff ON encounter.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_referral_type_master typemaster ON admreff.referral_type_id = typemaster.referral_type_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = encounter.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = pr.gender_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN m_unit_master um ON admreff.unit_id = um.unit_idUNION ALLSELECT COALESCE(m_refferel.referral_name) AS referral_contact_person,adm.created_date,typemaster.referral_type_name,admreff.referral_remark,'IPD'::text AS opd,admreff.visit_type_id,pr.uhid_number,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,pr.bar_code,age(pr.dob) AS age,pr.mobile_number,typemaster.referral_type_id,um.unit_id,um.unit_name,um.unit_address,'\x'::bytea AS image,pd.address,m_refferel.referral_idFROM adt.t_admission admJOIN t_referal_details admreff ON adm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_referral_type_master typemaster ON admreff.referral_type_id = typemaster.referral_type_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = adm.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = pr.gender_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN m_unit_master um ON admreff.unit_id = um.unit_id;

-- public.get_referral_info_billwise source
CREATE OR REPLACE VIEW public.get_referral_info_billwiseAS SELECT COALESCE(m_refferel.referral_name::character varying) AS referral_contact_person,encounter.created_date,typemaster.referral_type_name,admreff.referral_remark,'OPD'::text AS opd,COALESCE(admreff.visit_type_id, 1) AS visit_type_id,pr.uhid_number,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,pr.bar_code,age(pr.dob) AS age,pr.mobile_number,typemaster.referral_type_id,um.unit_id,um.unit_name,um.unit_address,'\x'::bytea AS image,pd.address,m_refferel.referral_id,bm.bill_number,bm.net_amount,bm.discount_amount,bm.total_bill_amountFROM opd.t_encounter_master encounterJOIN t_referal_details admreff ON encounter.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_referral_type_master typemaster ON admreff.referral_type_id = typemaster.referral_type_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = encounter.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = pr.gender_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN m_unit_master um ON admreff.unit_id = um.unit_idLEFT JOIN billing.m_billing_master bm ON bm.encounter_id = encounter.encounter_idUNION ALLSELECT COALESCE(m_refferel.referral_name) AS referral_contact_person,adm.created_date,typemaster.referral_type_name,admreff.referral_remark,'IPD'::text AS opd,admreff.visit_type_id,pr.uhid_number,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,gm.gender_name,pr.bar_code,age(pr.dob) AS age,pr.mobile_number,typemaster.referral_type_id,um.unit_id,um.unit_name,um.unit_address,'\x'::bytea AS image,pd.address,m_refferel.referral_id,bm.bill_number,bm.net_amount,bm.discount_amount,bm.total_bill_amountFROM adt.t_admission admJOIN t_referal_details admreff ON adm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_referral_type_master typemaster ON admreff.referral_type_id = typemaster.referral_type_idLEFT JOIN patient.t_patient_registration pr ON pr.patient_id = adm.patient_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pr.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = pr.gender_idLEFT JOIN m_prefix_master pm ON pm.prefix_id = pr.prefix_idLEFT JOIN m_unit_master um ON admreff.unit_id = um.unit_idLEFT JOIN billing.m_billing_master bm ON bm.admission_id = adm.admission_id;

-- public.get_refferdoctorvoucher source
CREATE OR REPLACE VIEW public.get_refferdoctorvoucherAS SELECT DISTINCT voucher.doc_share_vouche_id,voucher.voucher_no,voucher.total_doc_share_amout,voucher.processed_amt,voucher.due_share_amt,m_refferel.referral_name AS first_name,m_refferel.referral_name AS last_name,voucher.created_date,share.doc_id,unit.unit_name,unit.unit_address,m_refferel.referral_id,unit.unit_idFROM billing.t_doc_share_voucher voucherJOIN billing.t_doc_share_voucher_dtls voucherdetail ON voucher.doc_share_vouche_id = voucherdetail.doc_share_vouche_idLEFT JOIN billing.t_doctor_share share ON voucherdetail.doctor_share_id = share.doctor_share_idJOIN adt.m_referral_master m_refferel ON share.referral_id = m_refferel.referral_idLEFT JOIN unitinformation unit ON voucher.org_unit_id = unit.unit_id;

-- public.get_refund_list source
CREATE OR REPLACE VIEW public.get_refund_listAS SELECT DISTINCT t_payment_refund_master.payment_refund_id,t_payment_refund_master.payment_refund_voucher_no,t_payment_refund_master.date_of_refund,t_payment_refund_master.is_cn_or_deposit,t_payment_refund_master.t_refund_cn_id,t_payment_refund_master.amount_refunded,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,cm.currency_name,cm.sub_currency,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_payment_mode_master.payment_mode_desc,t_payment_refund_details.amount AS detail_amount,m_bank_master.bank_name,t_payment_refund_details.card_number,t_payment_refund_details.cheque_number,t_payment_refund_details.date AS chequedate,CASEWHEN COALESCE(t_payment_refund_master.patient_id, 0) &lt;&gt; 0 THEN t_patient_registration.uhid_numberELSE reg_deposit.uhid_numberEND AS uhid_number,CASEWHEN COALESCE(t_payment_refund_master.patient_id, 0) &lt;&gt; 0 THEN concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying))ELSE concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(reg_deposit.first_name, ''::character varying), ' ', COALESCE(reg_deposit.middle_name, ''::character varying), ' ', COALESCE(reg_deposit.last_name, ''::character varying))END AS patientname,m_credit_note_master.credit_note_no AS againstcreditnoteno,m_deposit_master.deposit_no AS againstdepositno,t_payment_refund_details.payment_mode_id,m_service_master.service_standard_name,t_billing_details.rate,t_billing_details.tax_amount,t_billing_details.tax_per,t_billing_details.quantity,t_billing_details.concession,t_billing_details.gross_amount,unitinformation.image,m_deposit_master.available_deposit,m_deposit_master.deposit_amount,m_deposit_master.consumed_deposit,m_credit_note_master.ce_remark,m_user_master.user_idFROM billing.t_payment_refund_masterLEFT JOIN billing.t_payment_refund_details ON t_payment_refund_master.payment_refund_id = t_payment_refund_details.payment_refund_idLEFT JOIN billing.t_refund_cn ON t_payment_refund_master.t_refund_cn_id = t_refund_cn.t_refund_cn_idLEFT JOIN billing.m_deposit_master ON t_refund_cn.deposit_id = m_deposit_master.deposit_master_idLEFT JOIN patient.t_patient_registration ON t_payment_refund_master.patient_id = t_patient_registration.patient_idLEFT JOIN patient.t_patient_registration reg_deposit ON m_deposit_master.patient_id = reg_deposit.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_user_master ON t_payment_refund_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master epm ON m_employee_master.prefix_id = epm.prefix_idJOIN m_unit_master unitinformation ON t_payment_refund_master.unit_id = unitinformation.unit_idLEFT JOIN m_currency_master cm ON cm.unit_id = t_payment_refund_master.unit_idLEFT JOIN m_payment_mode_master ON t_payment_refund_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON t_payment_refund_details.bank_id = m_bank_master.bank_idLEFT JOIN billing.m_credit_note_master ON t_payment_refund_master.credit_note_id = m_credit_note_master.credit_note_idLEFT JOIN billing.t_credit_note_detail ON t_refund_cn.t_refund_cn_id = t_credit_note_detail.credit_note_idLEFT JOIN billing.t_billing_details ON t_credit_note_detail.billing_details_id = t_billing_details.billing_details_idLEFT JOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idWHERE t_payment_refund_master.is_cn_or_deposit = 0;

-- public.get_rejected_material_acceptance source
CREATE OR REPLACE VIEW public.get_rejected_material_acceptanceAS SELECT reject.id,reject.return_no,reject.rejected_date,m_item.code,m_item.name,m_generic.name AS generic,rejectdetails.rejected_quantity,rejectdetails.accepted_quantity,rejectdetails.rejected_reject_quantity,m_reject_reason.reason,uomtype.type AS uomtype,uomunit.unit,batch.batch_no,batch.expiry_date,fromstore.store_name AS fromstore,tostore.store_name AS tostore,m_status.status,um.user_name,unitmaster.unit_name,unitmaster.unit_address,unitmaster.imageFROM inventory.t_reject rejectJOIN inventory.t_reject_detail rejectdetails ON reject.id = rejectdetails.reject_idJOIN inventory.t_material_issue materialissue ON reject.material_issue_id = materialissue.idJOIN inventory.t_material_issue_detail materialdetails ON materialissue.id = materialdetails.material_issue_idJOIN m_item ON materialdetails.item_id = m_item.idLEFT JOIN m_reject_reason ON rejectdetails.reject_reason_id = m_reject_reason.idLEFT JOIN inventory.t_store_indent indent ON materialissue.store_indent_id = indent.idLEFT JOIN inventory.t_store_indent_detail indent_detail ON materialdetails.store_indent_detail_id = indent_detail.idLEFT JOIN m_uom_type uomtype ON indent_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON indent_detail.uom_unit_id = uomunit.idLEFT JOIN inventory.t_material_issue_batch_mapper batchmapper ON materialdetails.id = batchmapper.material_issue_detail_idJOIN inventory.t_batch batch ON batch.id = batchmapper.batch_idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_store fromstore ON reject.from_store_id = fromstore.store_idLEFT JOIN m_store tostore ON reject.to_store_id = tostore.store_idLEFT JOIN m_user_master um ON reject.added_by = um.user_idLEFT JOIN m_status ON reject.status_id = m_status.idLEFT JOIN m_unit_master unitmaster ON reject.unit_id = unitmaster.unit_idWHERE rejectdetails.is_active = trueUNIONSELECT reject.id,reject.return_no,reject.rejected_date,m_item.code,m_item.name,m_generic.name AS generic,rejectdetails.rejected_quantity,rejectdetails.accepted_quantity,rejectdetails.rejected_reject_quantity,m_reject_reason.reason,uomtype.type AS uomtype,uomunit.unit,batch.batch_no,batch.expiry_date,fromstore.store_name AS fromstore,tostore.store_name AS tostore,m_status.status,um.user_name,unitmaster.unit_name,unitmaster.unit_address,unitmaster.imageFROM inventory.t_reject rejectJOIN inventory.t_reject_detail rejectdetails ON reject.id = rejectdetails.reject_idJOIN inventory.t_return_detail rd ON rd.id = rejectdetails.return_detail_idLEFT JOIN m_reject_reason ON rejectdetails.reject_reason_id = m_reject_reason.idLEFT JOIN inventory.t_material_issue_batch_mapper batchmapper ON rejectdetails.issue_batch_mapper_id = batchmapper.idLEFT JOIN inventory.t_batch batch ON batch.id = rd.batch_idJOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idLEFT JOIN m_uom_type uomtype ON rd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON rd.uom_unit_id = uomunit.idLEFT JOIN m_store fromstore ON reject.from_store_id = fromstore.store_idLEFT JOIN m_store tostore ON reject.to_store_id = tostore.store_idLEFT JOIN m_user_master um ON reject.added_by = um.user_idLEFT JOIN m_status ON reject.status_id = m_status.idLEFT JOIN m_unit_master unitmaster ON reject.unit_id = unitmaster.unit_idWHERE rejectdetails.is_active = true;

-- public.get_requestforassetdisposal source
CREATE OR REPLACE VIEW public.get_requestforassetdisposalAS SELECT sr.id,sr.request_no,m_store.store_name,assettype.type AS assettype,um.user_name,m_status.status,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,srd.scrap_quantity,srd.accepted_quantity,srd.amount_cop,m_generic.name AS genericname,batch.expiry_date,reason.reason,sr.added_date,m_item.code,unit.unit_name,unit.unit_address,unit.imageFROM inventory.t_scrap_request srJOIN inventory.t_scrap_request_detail srd ON sr.id = srd.scrap_request_idLEFT JOIN m_store ON sr.store_id = m_store.store_idLEFT JOIN m_asset_type assettype ON sr.asset_type_id = assettype.idLEFT JOIN m_user_master um ON sr.added_by = um.user_idLEFT JOIN m_status ON sr.status_id = m_status.idLEFT JOIN inventory.t_batch batch ON srd.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON srd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON srd.uom_unit_id = uomunit.idLEFT JOIN m_scrap_reason reason ON srd.scrap_reason_id = reason.idLEFT JOIN m_generic ON m_item.generic_id = m_generic.idJOIN m_unit_master unit ON sr.unit_id = unit.unit_idWHERE srd.is_active = true;

-- public.get_revenu source
CREATE OR REPLACE VIEW public.get_revenuAS SELECT sum(bd.net_amt) AS net_amount,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.middle_name, ' ', pim.last_name) AS patientname,bm.bill_number,bm.bill_date_time,sp.speciality_name,ssm.sub_speciality_name,um.unit_id,um.organization_id,um.unit_name,um.unit_address,bm.bill_cancelled,'\x'::bytea AS image,org.organization_nameFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN patient.t_patient_registration pim ON pim.patient_id = bm.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = pim.prefix_idLEFT JOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN m_unit_master um ON bm.unit_id = um.unit_idLEFT JOIN m_organization_master org ON um.organization_id = org.organization_idWHERE bd.status = 'A'::"char" AND bm.status = 'A'::"char" AND bd.package_consumption_amt = 0::double precisionGROUP BY prefix.prefix_desc, pim.first_name, pim.middle_name, pim.last_name, bm.bill_number, bm.bill_date_time, sp.speciality_name, ssm.sub_speciality_name, um.unit_id, um.organization_id, um.unit_name, um.unit_address, bm.bill_cancelled, um.image, org.organization_name;

-- public.get_revenue_classification_dashboard source
CREATE OR REPLACE VIEW public.get_revenue_classification_dashboardAS SELECT DISTINCT bm.visit_type_id,visit.visit_type_code,CASEWHEN bm.visit_type_id = 1 THEN smop.speciality_idELSE smip.speciality_idEND AS speciality_id,CASEWHEN bm.visit_type_id = 1 THEN smop.speciality_nameELSE smip.speciality_nameEND::character varying AS speciality_name,COALESCE(sp.speciality_id, 0) AS service_grp_id,COALESCE(sp.speciality_name, 'Other'::character varying) AS service_grp_name,sum(bd.net_amt) AS amount,bm.bill_date_time,bm.unit_id,bm.organisation_id,mp.is_surgical_code,mp.is_clinical_specialityFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idJOIN m_visit_type_master visit ON visit.visit_type_id = bm.visit_type_idJOIN t_unit_speciality_mapper mp ON mp.unit_id = bm.unit_id AND mp.speciality_id = sp.speciality_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = bm.encounter_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN doctor.m_speciality_master smop ON smop.speciality_id = em.dept_idLEFT JOIN doctor.m_speciality_master smip ON smip.speciality_id = ta.admitting_speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bd.status = 'A'::"char" AND bd.package_consumption_amt = 0::double precision AND bd.status = 'A'::"char"GROUP BY sp.speciality_name, bm.bill_date_time, bm.visit_type_id, visit.visit_type_code, sp.speciality_id, bm.unit_id, mp.is_surgical_code, mp.is_clinical_speciality, bm.organisation_id, smop.speciality_name, smip.speciality_name, smop.speciality_id, smip.speciality_id;

-- public.get_revenue_doctorwise_speciality_dashboard source
CREATE OR REPLACE VIEW public.get_revenue_doctorwise_speciality_dashboardAS SELECT DISTINCT bm.visit_type_id,visit.visit_type_code,sp.speciality_id,CASEWHEN mp.is_surgical_code = 'N'::bpchar AND mp.is_clinical_speciality = 'N'::bpchar THEN 'Other'::character varyingELSE sp.speciality_nameEND AS speciality_name,CASEWHEN bm.visit_type_id = 1 THEN dmopspl.speciality_idELSE dmipspl.speciality_idEND AS doctor_speciality_id,CASEWHEN bm.visit_type_id = 1 THEN concat(dmop.first_name, ' ', dmop.last_name)ELSE concat(dmip.first_name, ' ', dmip.last_name)END AS doctor_name,sum(bd.net_amt) AS amount,bm.bill_date_time,bm.unit_id,bm.organisation_id,mp.is_surgical_code,mp.is_clinical_speciality,CASEWHEN bm.visit_type_id = 1 THEN dmopspl.speciality_nameELSE dmipspl.speciality_nameEND AS doc_speciality,CASEWHEN bm.visit_type_id = 1 THEN dmop.doctor_idELSE dmip.doctor_idEND AS doctor_id,CASEWHEN bm.visit_type_id = 1 THEN doctypeop.doctor_category_descriptionELSE doctypeip.doctor_category_descriptionEND AS doctor_categoryFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = bm.encounter_idLEFT JOIN adt.t_admission ta ON ta.admission_id = bm.admission_idLEFT JOIN doctor.m_doctor_master dmop ON dmop.doctor_id = em.doctor_idLEFT JOIN doctor.m_doctor_master dmip ON dmip.doctor_id = ta.admitting_doctor_idLEFT JOIN doctor.m_speciality_master dmopspl ON dmopspl.speciality_id = em.dept_idLEFT JOIN doctor.m_speciality_master dmipspl ON dmipspl.speciality_id = ta.admitting_speciality_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idJOIN doctor.m_speciality_master sp ON msm.speciality_id = sp.speciality_idJOIN m_visit_type_master visit ON visit.visit_type_id = bm.visit_type_idLEFT JOIN m_doctor_category doctypeop ON doctypeop.doctor_category_id = dmop.doc_category_idLEFT JOIN m_doctor_category doctypeip ON doctypeip.doctor_category_id = dmip.doc_category_idJOIN t_unit_speciality_mapper mp ON mp.unit_id = bm.unit_id AND mp.speciality_id = sp.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bd.status = 'A'::"char" AND bd.package_consumption_amt = 0::double precision AND bd.status = 'A'::"char"GROUP BY sp.speciality_name, bm.bill_date_time, bm.visit_type_id, visit.visit_type_code, sp.speciality_id, bm.unit_id, mp.is_surgical_code, mp.is_clinical_speciality, bm.organisation_id, dmip.first_name, dmip.last_name, dmop.first_name, dmop.last_name, dmopspl.speciality_id, dmipspl.speciality_id, dmipspl.speciality_name, dmopspl.speciality_name, dmop.doctor_id, dmip.doctor_id, doctypeop.doctor_category_description, doctypeip.doctor_category_description;

-- public.get_salesdata_details source
CREATE OR REPLACE VIEW public.get_salesdata_detailsAS SELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount AS bill_discount_per,t_sale.total_discount_amount AS bill_discount_amt,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patientname,registration.mobile_number,''::text AS address,registration.uhid_number AS temp_uhid,CASEWHEN m_doctor_master.doctor_id IS NULL THEN t_temp_doctor.doctor_name::textELSE (m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::textEND AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(companyop.company_id, companyip.company_id) AS company_id,COALESCE(companyop.company_desc, companyip.company_desc, 'Self'::character varying) AS company_desc,m_status.id AS status_id,m_store.store_name,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage AS item_wise_gst_per,t_sale_detail.tax_amount AS item_wise_gst_amt,t_sale_detail.discount_amount AS item_wise_disc,t_sale_detail.discount_percentage AS item_wise_per,t_sale_detail.net_amount AS net_amount_detail,m_item.code AS item_code,m_item.name,t_batch.batch_no,t_batch.expiry_date,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,storageunit.name AS storageunit,t_sale_detail.id AS salesdetailid,t_sale_detail.item_id,''::character varying(250) AS insurance_desc,visit.visit_type_code,CASEWHEN psdop.encounter_id IS NULL THEN psdip.payment_entitlement_idELSE psdop.payment_entitlement_idEND AS payment_entitlement_id,CASEWHEN t_sale.is_consolidated_bill = true THEN 'Add to Bill'::textWHEN t_sale.is_consolidated_bill = false THEN 'Walk In'::textELSE NULL::textEND AS settle,mode1.payment_mode_id,mpm.payment_mode_desc,t_sale.total_discount_amount,t_sale_detail.product_category_id,mpc.category,m_transaction_type_master.transaction_type_name,pkg.is_package_service,muom.conversions,ft.type AS formulation_typeFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN m_visit_type_master visit ON visit.visit_type_id = t_sale.visit_type_idLEFT JOIN opd.t_patient_sponsor_details psdop ON psdop.encounter_id = t_sale.encounter_id AND psdop.priority_id = 1 AND psdop.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details psdip ON psdip.admission_id = t_sale.admission_id AND psdip.priority_id = 1 AND psdip.status = 'A'::bpcharLEFT JOIN t_company_master companyop ON companyop.company_id = psdop.payee_idLEFT JOIN t_company_master companyip ON companyip.company_id = psdip.payee_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN pharmacy.t_sale_payment_mode mode1 ON t_sale.id = mode1.sale_idLEFT JOIN m_payment_mode_master mpm ON mode1.payment_mode_id = mpm.payment_mode_idLEFT JOIN m_product_category mpc ON mpc.id = t_sale_detail.product_category_idLEFT JOIN billing.m_transaction_type_master ON mode1.transaction_type_id = m_transaction_type_master.transaction_type_idLEFT JOIN ( SELECT DISTINCT tod.is_package_service,tom.sale_idFROM t_order_master tomJOIN t_order_details tod ON tom.order_id = tod.order_idWHERE tom.is_pharmacy = 'Y'::bpchar AND tod.is_package_service = 'Y'::"char") pkg ON pkg.sale_id = t_sale.idLEFT JOIN m_unit_of_measurement muom ON m_item.id = muom.item_id AND muom.uom_type_id = 1 AND muom.is_active = trueLEFT JOIN m_uom_type uomt ON muom.uom_type_id = uomt.idLEFT JOIN m_uom_unit uomu ON muom.uom_unit_id = uomu.idLEFT JOIN m_formulation_type ft ON m_item.formulation_type_id = ft.idWHERE t_sale.patient_id IS NOT NULL AND t_sale.is_active = true AND unitinformation.unit_id = 114UNIONSELECT t_sale.id,t_sale.bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount AS bill_discount_per,t_sale.total_discount_amount AS bill_discount_amt,t_sale.net_amount,t_sale.tax_amount,t_sale.sale_type_id,t_temp_patient_registration.patient_name AS patientname,''::text AS mobile_number,t_temp_patient_registration.address,t_temp_patient_registration.temp_uhid,t_temp_doctor.doctor_name AS doctorname,t_sale.store_id,m_counter_master.counter_desc,m_counter_master.counter_id,'OPD/Walking'::text AS flag,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,saletype.type AS salestype,unitinformation.unit_id,''::text AS image,COALESCE(companyop.company_id, companyip.company_id) AS company_id,COALESCE(companyop.company_desc, companyip.company_desc, 'Self'::character varying) AS company_desc,m_status.id AS status_id,m_store.store_name,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage AS item_wise_gst_per,t_sale_detail.tax_amount AS item_wise_gst_amt,t_sale_detail.discount_amount AS item_wise_disc,t_sale_detail.discount_percentage AS item_wise_per,t_sale_detail.net_amount AS net_amount_detail,m_item.code AS item_code,m_item.name,t_batch.batch_no,t_batch.expiry_date,mfc.name AS mfcname,m_item.hsn_code,mfc.code,t_batch.cop,storageunit.name AS storageunit,t_sale_detail.id AS salesdetailid,t_sale_detail.item_id,''::character varying(250) AS insurance_desc,visit.visit_type_code,CASEWHEN psdop.encounter_id IS NULL THEN psdip.payment_entitlement_idELSE psdop.payment_entitlement_idEND AS payment_entitlement_id,CASEWHEN t_sale.is_consolidated_bill = true THEN 'Add to Bill'::textWHEN t_sale.is_consolidated_bill = false THEN 'Walk In'::textELSE NULL::textEND AS settle,mode1.payment_mode_id,mpm.payment_mode_desc,t_sale.total_discount_amount,t_sale_detail.product_category_id,mpc.category,m_transaction_type_master.transaction_type_name,''::"char" AS is_package_service,muom.conversions,ft.type AS formulation_typeFROM pharmacy.t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN m_storage_unit storageunit ON m_item.storage_unit_id = storageunit.idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN pharmacy.t_temp_patient_registration ON t_temp_patient_registration.id = t_sale.temp_patient_idLEFT JOIN pharmacy.t_temp_doctor ON t_temp_doctor.id = t_sale.temp_doctor_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idLEFT JOIN m_store ON t_sale.store_id = m_store.store_idLEFT JOIN m_counter_master ON m_counter_master.counter_id = t_sale.counter_idLEFT JOIN m_user_master ON m_user_master.user_id = t_sale.added_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN m_unit_master unitinformation ON t_sale.unit_id = unitinformation.unit_idLEFT JOIN pharmacy.m_sale_type saletype ON saletype.id = t_sale.sale_type_idLEFT JOIN m_visit_type_master visit ON visit.visit_type_id = t_sale.visit_type_idLEFT JOIN m_status ON t_sale.status_id = m_status.idLEFT JOIN opd.t_patient_sponsor_details psdop ON psdop.encounter_id = t_sale.encounter_id AND psdop.priority_id = 1 AND psdop.status = 'A'::bpcharLEFT JOIN opd.t_patient_sponsor_details psdip ON psdip.admission_id = t_sale.admission_id AND psdip.priority_id = 1 AND psdip.status = 'A'::bpcharLEFT JOIN t_company_master companyop ON companyop.company_id = psdop.payee_idLEFT JOIN t_company_master companyip ON companyip.company_id = psdip.payee_idLEFT JOIN pharmacy.t_sale_payment_mode mode1 ON t_sale.id = mode1.sale_idLEFT JOIN m_payment_mode_master mpm ON mode1.payment_mode_id = mpm.payment_mode_idLEFT JOIN m_product_category mpc ON mpc.id = t_sale_detail.product_category_idLEFT JOIN billing.m_transaction_type_master ON mode1.transaction_type_id = m_transaction_type_master.transaction_type_idLEFT JOIN m_unit_of_measurement muom ON m_item.id = muom.item_id AND muom.uom_type_id = 1 AND muom.is_active = trueLEFT JOIN m_uom_type uomt ON muom.uom_type_id = uomt.idLEFT JOIN m_uom_unit uomu ON muom.uom_unit_id = uomu.idLEFT JOIN m_formulation_type ft ON m_item.formulation_type_id = ft.idWHERE t_sale.temp_patient_id IS NOT NULL AND t_sale.is_active = true AND unitinformation.unit_id = 114;

-- public.get_schedulex source
CREATE OR REPLACE VIEW public.get_schedulexAS SELECT sm.schedule_id,sm.schedule_code,sm.schedule_description,sm.schedule_status,m_generic.name AS generic,m_item.name AS itemname,saledetail.id AS salesdetailid,sales.bill_no,sales.added_date,COALESCE((((((prefix1.prefix_desc || ''::text) || reg1.first_name::text) || ' '::text) || reg1.middle_name::text) || ' '::text) || reg1.last_name::text, ''::text) AS reg1patientname,COALESCE((prefix2.prefix_desc || ''::text) || reg2.patient_name::text, ''::text) AS reg2patientname,COALESCE(CASEWHEN reg1.first_name::text = ''::text THEN (prefix2.prefix_desc || ''::text) || reg2.patient_name::textELSE (((((prefix1.prefix_desc || ''::text) || reg1.first_name::text) || ' '::text) || reg1.middle_name::text) || ' '::text) || reg1.last_name::textEND, ''::text) AS patname,CASEWHEN reg1.first_name::text = ''::text THEN reg2.address::textELSE pd.addressEND AS pataddress,um.unit_name,um.unit_address,saledetail.quantity,saledetail.net_amount,CASEWHEN reg1.first_name::text = ''::text THEN reg2.mobile_numberELSE reg1.mobile_numberEND AS mobileno,um.unit_id,um.image,concat('Dr.', doctor.first_name, ' ', doctor.last_name) AS doctor,saletype.type AS saletype,m_item.code AS itemcode,batch.id AS batch_id,batch.batch_no,batch.expiry_date,m_item.id AS itemid,sales.id AS sale_id,sales.sale_type_id AS saletypeid,gsm.generic_id,CASEWHEN reg1.first_name::text = ''::text THEN reg2.temp_uhidELSE reg1.uhid_numberEND AS uhid_number,CASEWHEN reg1.first_name::text = ''::text THEN gm1.gender_nameELSE gm.gender_nameEND AS gender_name,ssm.speciality_id,ssm.speciality_name,m_item.manufacturer_id,manf.name AS manf,CASEWHEN reg1.first_name::text = ''::text THEN reg2.ageELSE abs(date_part('Year'::text, age(to_char(reg1.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integerEND AS ageyear,doctor.doctor_idFROM pharmacy.m_schedule_master smJOIN pharmacy.m_generic_schedule_master gsm ON sm.schedule_id = gsm.schedule_idJOIN m_generic ON gsm.generic_id = m_generic.idJOIN m_item ON m_generic.id = m_item.generic_idJOIN inventory.t_batch batch ON m_item.id = batch.item_idJOIN pharmacy.t_sale_detail saledetail ON batch.id = saledetail.batch_idJOIN pharmacy.t_sale sales ON saledetail.sale_id = sales.idJOIN pharmacy.m_sale_type saletype ON saletype.id = sales.sale_type_idLEFT JOIN m_manufacturer manf ON manf.id = m_item.manufacturer_idLEFT JOIN doctor.m_doctor_master doctor ON doctor.doctor_id = sales.doctor_idLEFT JOIN doctor.m_speciality_master ssm ON ssm.speciality_id = doctor.speciality_idLEFT JOIN patient.registration reg1 ON reg1.patient_id = sales.patient_idLEFT JOIN m_gender_master gm ON gm.gender_id = reg1.gender_idLEFT JOIN pharmacy.t_temp_patient_registration reg2 ON reg2.id = sales.temp_patient_idLEFT JOIN m_gender_master gm1 ON gm1.gender_id = reg2.gender_idLEFT JOIN m_prefix_master prefix1 ON reg1.prefix_id = prefix1.prefix_idLEFT JOIN m_prefix_master prefix2 ON reg2.prefix_id = prefix2.prefix_idLEFT JOIN patient.t_patient_details pd ON reg1.patient_id = pd.patient_idLEFT JOIN m_unit_master um ON gsm.unit_id = um.unit_id;

-- public.get_schedulex_ source
CREATE OR REPLACE VIEW public.get_schedulex_AS SELECT sm.schedule_id,sm.schedule_code,sm.schedule_description,sm.schedule_status,m_generic.name AS generic,m_item.name AS itemname,saledetail.id AS salesdetailid,CASEWHEN sales.sale_type_id = 1 THEN concat('IPD-', '', sales.id)::character varyingELSE sales.bill_noEND::character varying(50) AS bill_no,sales.added_date,COALESCE((((((prefix1.prefix_desc || ''::text) || reg1.first_name::text) || ' '::text) || reg1.middle_name::text) || ' '::text) || reg1.last_name::text, ''::text) AS reg1patientname,COALESCE((prefix2.prefix_desc || ''::text) || reg2.patient_name::text, ''::text) AS reg2patientname,COALESCE(CASEWHEN reg1.first_name::text = ''::text THEN (prefix2.prefix_desc || ''::text) || reg2.patient_name::textELSE (((((prefix1.prefix_desc || ''::text) || reg1.first_name::text) || ' '::text) || reg1.middle_name::text) || ' '::text) || reg1.last_name::textEND, ''::text) AS patname,CASEWHEN reg1.first_name::text = ''::text THEN reg2.address::textELSE pd.addressEND AS pataddress,um.unit_name,um.unit_address,saledetail.quantity,saledetail.net_amount,CASEWHEN reg1.first_name::text = ''::text THEN reg2.mobile_numberELSE reg1.mobile_numberEND AS mobileno,um.unit_id,um.image,concat('Dr.', doctor.first_name, ' ', doctor.last_name) AS doctor,saletype.type AS saletype,m_item.code AS itemcode,batch.id AS batch_id,batch.batch_no,batch.expiry_date,m_item.id AS itemid,sales.id AS sale_id,sales.sale_type_id AS saletypeidFROM pharmacy.t_sale salesJOIN pharmacy.t_sale_detail saledetail ON saledetail.sale_id = sales.idJOIN m_item ON m_item.id = saledetail.item_idJOIN m_generic ON m_generic.id = m_item.generic_idJOIN pharmacy.m_generic_schedule_master gsm ON gsm.generic_id = m_generic.idJOIN pharmacy.m_schedule_master sm ON sm.schedule_id = gsm.schedule_idJOIN inventory.t_batch batch ON batch.id = saledetail.batch_idJOIN pharmacy.m_sale_type saletype ON saletype.id = sales.sale_type_idLEFT JOIN doctor.m_doctor_master doctor ON doctor.doctor_id = sales.doctor_idLEFT JOIN patient.registration reg1 ON reg1.patient_id = sales.patient_idLEFT JOIN pharmacy.t_temp_patient_registration reg2 ON reg2.id = sales.temp_patient_idLEFT JOIN m_prefix_master prefix1 ON reg1.prefix_id = prefix1.prefix_idLEFT JOIN m_prefix_master prefix2 ON reg2.prefix_id = prefix2.prefix_idLEFT JOIN patient.t_patient_details pd ON reg1.patient_id = pd.patient_idLEFT JOIN m_unit_master um ON gsm.unit_id = um.unit_id;

-- public.get_scrap_request source
CREATE OR REPLACE VIEW public.get_scrap_requestAS SELECT scrap_request.id,scrap_request.request_no,scrap_request.remark,m_store.store_name,m_status.status,assettype.type AS assettype,approvalstatus.status AS approvalstatus,usermaster.user_name,scrap_request.added_date,scrap_request.approved_by,usermasterapp.user_name AS usermasterapp,scrap_request.approved_on,m_item.code,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,batch.batch_no,batch.expiry_date,request_detail.scrap_quantity,request_detail.accepted_quantity,request_detail.reject_quantity,batch.cop,reason.reason,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.imageFROM inventory.t_scrap_request scrap_requestJOIN inventory.t_scrap_request_detail request_detail ON scrap_request.id = request_detail.scrap_request_idLEFT JOIN m_store ON scrap_request.store_id = m_store.store_idLEFT JOIN m_status ON scrap_request.status_id = m_status.idLEFT JOIN m_status approvalstatus ON scrap_request.approval_status_id = approvalstatus.idLEFT JOIN m_asset_type assettype ON scrap_request.asset_type_id = assettype.idLEFT JOIN m_user_master usermaster ON scrap_request.added_by = usermaster.user_idLEFT JOIN m_user_master usermasterapp ON scrap_request.approved_by = usermasterapp.user_idLEFT JOIN inventory.t_batch batch ON request_detail.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON request_detail.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON request_detail.uom_unit_id = uomunit.idLEFT JOIN m_scrap_reason reason ON request_detail.scrap_reason_id = reason.idLEFT JOIN m_unit_master ON scrap_request.unit_id = m_unit_master.unit_idWHERE request_detail.is_active = true;

-- public.get_service_baseprice source
CREATE OR REPLACE VIEW public.get_service_basepriceAS SELECT speciality.speciality_name,ssp.sub_speciality_name,sm.service_standard_name,sp.base_price,sp.unit_id,sp.organisation_idFROM service.m_service_base_price_master spJOIN service.m_service_master sm ON sp.service_master_id = sm.service_master_idJOIN doctor.m_speciality_master speciality ON speciality.speciality_id = sm.speciality_idJOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_id;

-- public.get_servicedays source
CREATE OR REPLACE VIEW public.get_servicedaysAS SELECT adm.admission_id,adm.created_date AS admissiondate,dis.discharge_date,CASEWHEN (dis.discharge_date::date - adm.created_date::date) = 0 THEN 1ELSE dis.discharge_date::date - adm.created_date::dateEND AS admissiondays,sp.speciality_name,((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,sp.speciality_id,dm.doctor_id,unitmaster.unit_name,unitmaster.unit_address,adm.unit_id,unitmaster.imageFROM adt.t_admission admJOIN adt.t_discharge dis ON adm.admission_id = dis.admission_idJOIN doctor.m_speciality_master sp ON adm.speciality_id = sp.speciality_idJOIN doctor.m_doctor_master dm ON adm.admitting_doctor_id = dm.doctor_idLEFT JOIN m_unit_master unitmaster ON adm.unit_id = unitmaster.unit_idWHERE dis.discharge_id = (( SELECT max(d.discharge_id) AS discharge_idFROM adt.t_discharge dWHERE d.admission_id = dis.admission_id)) AND adm.visit_type_id &lt;&gt; 4;

-- public.get_shiftclosing source
CREATE OR REPLACE VIEW public.get_shiftclosingAS SELECT shiftmaster.id,shiftmaster.closing_number,shiftmaster.amount AS totalamount,shiftmaster.difference AS totaldiff,shiftmaster.handover_by,shiftmaster.handover_to,shiftmaster.cashier_name,balance.amount,balance.actual_amount,balance.ich_amount,balance.mode_of_payment,unit.unit_name,unit.unit_address,userhandover.user_name AS handover,userhandoverto.user_name AS handoverto,(((emphandover.first_name::text || ' '::text) || emphandover.middle_name::text) || ' '::text) || emphandover.last_name::text AS emphandover,(((emphandoverto.first_name::text || ' '::text) || emphandoverto.middle_name::text) || ' '::text) || emphandoverto.last_name::text AS emphandoverto,shiftmaster.created_date,unit.imageFROM billing.m_shift_close_master shiftmasterLEFT JOIN billing.m_shift_close_balance balance ON shiftmaster.handover_by = balance.created_byLEFT JOIN m_unit_master unit ON shiftmaster.unit_id = unit.unit_idLEFT JOIN m_user_master userhandover ON shiftmaster.handover_by = userhandover.user_idLEFT JOIN m_user_master userhandoverto ON shiftmaster.handover_to = userhandoverto.user_idLEFT JOIN m_employee_master emphandover ON emphandover.user_id = userhandover.user_idLEFT JOIN m_employee_master emphandoverto ON emphandoverto.user_id = userhandoverto.user_id;

-- public.get_stockledger source
CREATE OR REPLACE VIEW public.get_stockledgerAS SELECT DISTINCT st.id,st.doc_type,s.name,s.id AS docttypeid,item.id AS itemid,tb.quantity,st.current_bal,tb.cop,tb.rate,tb.lending_price,tb.actual_lending_price,tb.selling_price,item.name AS itemname,g.name AS genericname,tb.batch_no,s.name AS screenname,st.added_date,s.id AS doctypeid,unit.unit_name,unit.unit_address,st.quantity AS tranquantity,unit.unit_id,st.is_transit,st.batch_id,m_store.store_id,m_store.store_name,COALESCE(st.in_qty, 0) AS in_qty,COALESCE(st.out_qty, 0) AS out_qty,COALESCE(grnd.is_deleted, false) AS is_deleted,COALESCE(grnd.is_active, true) AS is_activeFROM inventory.t_stock_transaction stJOIN inventory.t_batch tb ON st.batch_id = tb.idJOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic g ON item.generic_id = g.idLEFT JOIN m_screen s ON st.doc_id = s.idLEFT JOIN m_store ON m_store.store_id = st.store_idJOIN m_unit_master unit ON st.unit_id = unit.unit_idLEFT JOIN procurement.t_good_receipt_note_detail grnd ON grnd.id = st.transaction_details_id AND st.transaction_id = grnd.grn_idWHERE st.is_deleted = falseORDER BY st.id DESC;

-- public.get_stockledger_swami source
CREATE OR REPLACE VIEW public.get_stockledger_swamiAS SELECT st.id,st.doc_type,s.name,s.id AS docttypeid,item.id AS itemid,tb.quantity,COALESCE(st.current_bal, 0) AS current_bal,tb.cop,tb.rate,tb.lending_price,tb.actual_lending_price,tb.selling_price,item.name AS itemname,g.name AS genericname,tb.batch_no,s.name AS screenname,st.added_date,s.id AS doctypeid,unit.unit_name,unit.unit_address,st.quantity AS tranquantity,unit.unit_id,st.is_transit,st.batch_id,m_store.store_id,m_store.store_name,COALESCE(st.in_qty, 0) AS in_qty,COALESCE(st.out_qty, 0) AS out_qty,CASEWHEN st.doc_id = ANY (ARRAY[1, 15]) THEN COALESCE(ts.bill_no, 'Walkin Sale'::character varying)WHEN st.doc_id = 85 THEN us.upload_noWHEN st.doc_id = 28 THEN bc.consumable_numberWHEN st.doc_id = 32 THEN issue.issue_noWHEN st.doc_id = 3 THEN bal.opb_noWHEN st.doc_id = 9 THEN tsissue.bill_noWHEN st.doc_id = 16 THEN tr.return_noWHEN st.doc_id = ANY (ARRAY[20, 29]) THEN missue.issue_noWHEN st.doc_id = 30 THEN 'IP Pharamacy'::character varyingELSE st.transit_noEND AS transit_no,ts.bill_no,tb.lot_no,tb.expiry_date,tb.tax_percentageFROM inventory.t_stock_transaction stJOIN inventory.t_batch tb ON st.batch_id = tb.idJOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic g ON item.generic_id = g.idLEFT JOIN m_screen s ON st.doc_id = s.idLEFT JOIN m_store ON m_store.store_id = st.store_idLEFT JOIN m_unit_master unit ON st.unit_id = unit.unit_idLEFT JOIN pharmacy.t_sale ts ON ts.id = st.transaction_id AND (st.doc_id = ANY (ARRAY[1, 15]))LEFT JOIN inventory.t_upload_stock us ON us.id = st.transaction_id AND st.doc_id = 85LEFT JOIN pharmacy.t_billable_consumption bc ON st.transaction_id = bc.id AND st.doc_id = 28LEFT JOIN pharmacy.t_issue issue ON issue.sale_id = st.transaction_id AND st.doc_id = 32LEFT JOIN inventory.t_opening_balance bal ON bal.id = st.transaction_id AND st.doc_id = 3LEFT JOIN pharmacy.t_sale tsissue ON tsissue.id = st.transaction_id AND st.doc_id = 9LEFT JOIN pharmacy.t_issue pissue ON pissue.sale_id = st.transaction_id AND st.doc_id = 30LEFT JOIN pharmacy.t_return tr ON tr.id = st.transaction_id AND st.doc_id = 16LEFT JOIN inventory.t_material_issue missue ON missue.id = st.transaction_id AND (st.doc_id = ANY (ARRAY[20, 29]))WHERE st.is_transit = falseORDER BY st.id DESC;

-- public.get_stoptransactionrpt source
CREATE OR REPLACE VIEW public.get_stoptransactionrptAS SELECT st.id,st.request_no,st.added_date,s.store_name,st.start_date_time,st.stop_date_time,(((em.first_name::text || ' '::text) || em.middle_name::text) || ' '::text) || em.last_name::text AS requestedby,item.name AS itemname,g.name AS genericname,tb.batch_no,tb.expiry_date,unit.unit,pc.category,u.unit_name,u.unit_address,u.unit_contact,tb.cop,tb.current_quantity,unit.unit AS uomunit,uomtype.type AS uomtype,item.code AS itemcode,tb.rate,storestock.available_qty,u.imageFROM inventory.t_stop_transaction stLEFT JOIN inventory.t_stop_transaction_item_detail std ON st.id = std.stop_transaction_idLEFT JOIN inventory.t_stop_transaction_product_category_exclusion_detail stpced ON st.id = stpced.stop_transaction_idLEFT JOIN inventory.t_stop_transaction_item_exclusion_detail stied ON st.id = stied.stop_transaction_idLEFT JOIN m_store s ON st.store_id = s.store_idLEFT JOIN m_employee_master em ON st.added_by = em.user_idLEFT JOIN inventory.t_batch tb ON std.batch_id = tb.idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic g ON item.generic_id = g.idLEFT JOIN m_uom_unit unit ON std.uom_unit_id = unit.idLEFT JOIN m_uom_type uomtype ON std.uom_type_id = uomtype.idLEFT JOIN m_product_category pc ON stpced.product_category_id = pc.idLEFT JOIN unitinformation u ON st.unit_id = u.unit_idJOIN inventory.t_store_stock storestock ON tb.id = storestock.batch_id AND s.store_id = storestock.store_idORDER BY item.name;

-- public.get_tariffwiserate source
CREATE OR REPLACE VIEW public.get_tariffwiserateAS SELECT DISTINCT patientcategory.patient_category,patienttype.visit_type_name,tariff.tariff_desc,categorymaster.billing_bed_desc,servicemaster.service_standard_name,tariffmaster.rate,tariffmaster.tariff_id,tariffmaster.visit_type_id,sp.speciality_name,ssm.sub_speciality_name,u.unit_name,u.unit_address,u.unit_contact,sp.speciality_id,ssm.sub_speciality_id,u.unit_id,''::text AS image,servicemaster.service_standard_code,lm.general_ledger_id,lm.general_ledger_name,smapper.is_rate_editable,smapper.is_doc_req,smapper.is_procedure,CASEWHEN smapper.is_package = 'I'::bpchar THEN 'N'::textELSE 'Y'::textEND AS is_package,servicemaster.service_master_id,max(tariffmaster.effective_date) AS effective_date,tariffmaster.outsource_vendor_rate,patientcategory.patient_category_idFROM service.m_unit_service_tariff_master tariffmasterJOIN service.m_service_master servicemaster ON tariffmaster.service_id = servicemaster.service_master_idJOIN service.m_tariff_master tariff ON tariff.tariff_id = tariffmaster.tariff_idJOIN m_visit_type_master patienttype ON tariffmaster.visit_type_id = patienttype.visit_type_idJOIN adt.m_billing_bed_category_master categorymaster ON tariffmaster.billing_bed_category_id = categorymaster.billing_bed_category_idJOIN m_patient_category_master patientcategory ON tariffmaster.patient_type_id = patientcategory.patient_category_idLEFT JOIN doctor.m_speciality_master sp ON servicemaster.speciality_id = sp.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON servicemaster.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN m_unit_master u ON tariffmaster.unit_id = u.unit_idLEFT JOIN m_general_ledger_master lm ON lm.general_ledger_id = servicemaster.general_ledger_idJOIN service.t_unit_service_master_details smapper ON smapper.service_master_id = servicemaster.service_master_idWHERE tariffmaster.rate &lt;&gt; 0::double precision AND tariffmaster.status = 'A'::bpcharGROUP BY patientcategory.patient_category, patienttype.visit_type_name, tariff.tariff_desc, categorymaster.billing_bed_desc, servicemaster.service_standard_name, tariffmaster.rate, tariffmaster.tariff_id, tariffmaster.visit_type_id, sp.speciality_name, ssm.sub_speciality_name, u.unit_name, u.unit_address, u.unit_contact, sp.speciality_id, ssm.sub_speciality_id, u.unit_id, servicemaster.service_standard_code, lm.general_ledger_id, lm.general_ledger_name, smapper.is_rate_editable, smapper.is_doc_req, smapper.is_procedure, smapper.is_package, servicemaster.service_master_id, tariffmaster.outsource_vendor_rate, patientcategory.patient_category_idORDER BY patientcategory.patient_category, servicemaster.service_standard_name;

-- public.get_tariffwiserate_elcura source
CREATE OR REPLACE VIEW public.get_tariffwiserate_elcuraAS SELECT DISTINCT patientcategory.patient_category,patienttype.visit_type_name,tariff.tariff_desc,CASEWHEN categorymaster.billing_bed_desc::text = 'OPD'::text AND patientcategory.patient_category_id = 23 THEN 'OPD-National'::character varyingWHEN categorymaster.billing_bed_desc::text = 'OPD'::text AND patientcategory.patient_category_id = 22 THEN 'OPD-International'::character varyingELSE categorymaster.billing_bed_descEND AS billing_bed_desc,servicemaster.service_standard_name,tariffmaster.rate,tariffmaster.tariff_id,tariffmaster.visit_type_id,sp.speciality_name,ssm.sub_speciality_name,u.unit_name,u.unit_address,u.unit_contact,sp.speciality_id,ssm.sub_speciality_id,u.unit_id,''::text AS image,servicemaster.service_standard_code,lm.general_ledger_id,lm.general_ledger_name,smapper.is_rate_editable,smapper.is_doc_req,smapper.is_procedure,CASEWHEN smapper.is_package = 'I'::bpchar THEN 'N'::textELSE 'Y'::textEND AS is_package,servicemaster.service_master_id,max(tariffmaster.effective_date) AS effective_date,tariffmaster.outsource_vendor_rateFROM service.m_unit_service_tariff_master tariffmasterJOIN service.m_service_master servicemaster ON tariffmaster.service_id = servicemaster.service_master_idJOIN service.m_tariff_master tariff ON tariff.tariff_id = tariffmaster.tariff_idJOIN m_visit_type_master patienttype ON tariffmaster.visit_type_id = patienttype.visit_type_idJOIN adt.m_billing_bed_category_master categorymaster ON tariffmaster.billing_bed_category_id = categorymaster.billing_bed_category_idJOIN m_patient_category_master patientcategory ON tariffmaster.patient_type_id = patientcategory.patient_category_idLEFT JOIN doctor.m_speciality_master sp ON servicemaster.speciality_id = sp.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON servicemaster.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN m_unit_master u ON tariffmaster.unit_id = u.unit_idLEFT JOIN m_general_ledger_master lm ON lm.general_ledger_id = servicemaster.general_ledger_idJOIN service.t_unit_service_master_details smapper ON smapper.service_master_id = servicemaster.service_master_idWHERE tariffmaster.rate &lt;&gt; 0::double precision AND tariffmaster.status = 'A'::bpcharGROUP BY patientcategory.patient_category_id, patientcategory.patient_category, patienttype.visit_type_name, tariff.tariff_desc, categorymaster.billing_bed_desc, servicemaster.service_standard_name, tariffmaster.rate, tariffmaster.tariff_id, tariffmaster.visit_type_id, sp.speciality_name, ssm.sub_speciality_name, u.unit_name, u.unit_address, u.unit_contact, sp.speciality_id, ssm.sub_speciality_id, u.unit_id, servicemaster.service_standard_code, lm.general_ledger_id, lm.general_ledger_name, smapper.is_rate_editable, smapper.is_doc_req, smapper.is_procedure, smapper.is_package, servicemaster.service_master_id, tariffmaster.outsource_vendor_rateORDER BY patientcategory.patient_category, servicemaster.service_standard_name;

-- public.get_technical_approval source
CREATE OR REPLACE VIEW public.get_technical_approvalAS SELECT DISTINCT ta.id,qr.qr_no,qr.added_date,m_store.store_name,reqtype.type AS reqtype,assettype.type AS assettype,m_status.status,qr.added_by,m_item.code,m_item.name AS itemname,uomtype.type AS uomtype,uomunit.unit AS uomunit,qrd.quantity,um.user_name,unit.unit_name,unit.unit_address,qrd.warranty_period,qrd.expected_support_term,qrd.expected_payment,qrd.expected_technical_specification,m_vendor.name AS vendor,qfd.vendor_warranty_period,qfd.expected_support_term AS expected_support_term_vendor,qfd.expected_technical_specification AS expected_technical_specification_vendor,qfd.expected_payment AS expected_payment_vendor,unit.imageFROM procurement.t_quotation_request qrLEFT JOIN procurement.t_quotation_request_detail qrd ON qr.id = qrd.qr_idLEFT JOIN m_store ON qr.store_id = m_store.store_idLEFT JOIN m_asset_type assettype ON qr.asset_type_id = assettype.idLEFT JOIN m_request_type reqtype ON qr.request_type_id = reqtype.idLEFT JOIN m_item ON qrd.item_id = m_item.idLEFT JOIN m_uom_type uomtype ON qrd.uom_type_id = uomtype.idLEFT JOIN m_uom_unit uomunit ON qrd.uom_unit_id = uomunit.idLEFT JOIN m_unit_master unit ON qr.unit_id = unit.unit_idLEFT JOIN procurement.t_quotation_vendor vq ON qr.id = vq.qr_idLEFT JOIN m_vendor ON vq.vendor_id = m_vendor.idLEFT JOIN m_user_master um ON vq.added_by = um.user_idLEFT JOIN procurement.t_technical_approval ta ON qr.id = ta.qr_idLEFT JOIN m_status ON ta.status_id = m_status.idJOIN procurement.t_quotation_fill_detail qfd ON qrd.id = qfd.qr_detail_idWHERE qrd.is_active = true;

-- public.get_tempdoctor_report source
CREATE OR REPLACE VIEW public.get_tempdoctor_reportAS SELECT pim.uhid_number,bm.bill_number,pim.patientname,sm.service_standard_name,bd.net_amt,concat(dm.first_name, ' ', dm.last_name) AS doctor,um.unit_id,um.unit_name,um.unit_address,um.image,bm.bill_date_timeFROM t_template_transaction temptranJOIN t_order_details od ON temptran.order_details_id = od.order_details_idJOIN patientinformation pim ON pim.patient_id = temptran.patient_idJOIN billing.t_billing_details bd ON od.order_details_id = bd.order_details_idJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm ON od.service_id = sm.service_master_idJOIN unitinformation um ON temptran.unit_id = um.unit_idJOIN doctor.m_doctor_master dm ON temptran.template_doctor_id = dm.doctor_idWHERE temptran.template_doctor_id &lt;&gt; 0 AND bm.bill_cancelled = 'N'::bpchar;

-- public.get_upload_stock source
CREATE OR REPLACE VIEW public.get_upload_stockAS SELECT us.id,us.upload_no,m_store.store_name,stoptran.request_no,stoptran.start_date_time,stoptran.stop_date_time,m_status.status,statusapp.status AS statusapp,us.added_date,unit.unit_name,unit.unit_address,tb.cop,tb.current_quantity,uomunit.unit AS uomunit,uomtype.type AS uomtype,item.code AS itemcode,tb.rate,item.name AS itemname,tb.batch_no,tb.expiry_date,tb.quantity,usd.approved_upload_quantity,unit.image,usd.variance_qty,usd.variance_cop,usd.variance_mrp,unit.unit_id,m_store.store_id,statusapp.id AS statusappid,tss.available_qty,usd.qty,item.id AS itemid,concat(emp.first_name, ' ', emp.last_name) AS emp,us.approved_date,concat(empa.first_name, ' ', empa.last_name) AS empaFROM inventory.t_upload_stock usLEFT JOIN inventory.t_upload_stock_detail usd ON us.id = usd.upload_stock_idLEFT JOIN m_store ON us.store_id = m_store.store_idLEFT JOIN inventory.t_stop_transaction stoptran ON us.stop_transaction_id = stoptran.idLEFT JOIN m_status ON us.status_id = m_status.idLEFT JOIN m_status statusapp ON us.approval_status_id = statusapp.idLEFT JOIN m_unit_master unit ON unit.unit_id = us.unit_idLEFT JOIN inventory.t_batch tb ON usd.batch_id = tb.idLEFT JOIN inventory.t_store_stock tss ON tss.batch_id = tb.id AND tss.store_id = us.store_idLEFT JOIN m_item item ON tb.item_id = item.idLEFT JOIN m_generic g ON item.generic_id = g.idLEFT JOIN m_uom_unit uomunit ON usd.uom_unit_id = uomunit.idLEFT JOIN m_uom_type uomtype ON usd.uom_type_id = uomtype.idLEFT JOIN m_user_master um ON um.user_id = us.added_byLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_user_master uma ON uma.user_id = us.approved_byLEFT JOIN m_employee_master empa ON uma.user_id = empa.user_idWHERE usd.is_active = true AND usd.approved_upload_quantity &lt;&gt; 0;

-- public.get_variance_approval source
CREATE OR REPLACE VIEW public.get_variance_approvalAS SELECT va.id,stoptran.request_no,stoptran.added_date,stoptran.start_date_time,stoptran.stop_date_time,stoptran.added_by,m_store.store_name,m_status.status,um.user_name,m_item.code,m_item.name AS itemname,batch.cop,batch.rate,usd.approved_upload_quantity,csd.variance_cop,csd.variance_price,csd.approved_quantity,unit.unit_name,unit.unit_address,batch.current_quantity,batch.batch_no,usd.qty,batch.cop * usd.approved_upload_quantity::double precision - batch.cop * usd.qty::double precision AS vcop,batch.rate * usd.approved_upload_quantity::double precision - batch.rate * usd.qty::double precision AS vmrp,batch.quantity AS batchqty,va.added_date AS vadate,m_item.id AS itemid,m_store.store_id,unit.unit_id,unit.imageFROM inventory.t_variance_approval vaJOIN inventory.t_variance_approval_detail vad ON va.id = vad.variance_approval_idJOIN inventory.t_upload_stock uploadstock ON va.upload_stock_id = uploadstock.idJOIN inventory.t_stop_transaction stoptran ON uploadstock.stop_transaction_id = stoptran.idJOIN inventory.t_upload_stock_detail usd ON vad.upload_stoock_detail_id = usd.idJOIN inventory.t_compute_stock_detail csd ON vad.compute_stock_detail_id = csd.idJOIN inventory.t_batch batch ON usd.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idJOIN m_store ON stoptran.store_id = m_store.store_idLEFT JOIN m_status ON stoptran.status_id = m_status.idLEFT JOIN m_user_master um ON stoptran.added_by = um.user_idLEFT JOIN m_unit_master unit ON va.unit_id = unit.unit_idWHERE vad.is_deleted = false;

-- public.get_vender_quotation_selection source
CREATE OR REPLACE VIEW public.get_vender_quotation_selectionAS SELECT DISTINCT vs.id,qr.qr_no,qr.added_date,m_store.store_name,assettype.type AS assettype,reqtype.type AS reqtype,um.user_name,qr.added_date AS reqdate,m_status.status,m_item.name AS itemname,qrd.quantity,qrd.expected_payment,qrd.expected_support_term,qrd.expected_technical_specification,qrd.warranty_period,qfd.vendor_cop,unit.unit_name,unit.unit_address,m_vendor.name AS vendor,unit.imageFROM procurement.t_vendor_selection vsLEFT JOIN procurement.t_vendor_selection_detail vsd ON vs.id = vsd.vendor_selection_idLEFT JOIN procurement.t_quotation_request qr ON vs.quotation_request_id = qr.idLEFT JOIN procurement.t_quotation_request_detail qrd ON qr.id = qrd.qr_idLEFT JOIN procurement.t_quotation_fill_detail qfd ON qfd.qr_detail_id = qrd.idLEFT JOIN procurement.t_quotation_fill qf ON qf.id = qfd.quotation_fill_idLEFT JOIN procurement.t_vendor_negociation vn ON qf.id = vn.qf_idLEFT JOIN m_vendor ON vn.vendor_id = m_vendor.idLEFT JOIN m_status ON vs.status_id = m_status.idLEFT JOIN m_store ON qr.store_id = m_store.store_idLEFT JOIN m_asset_type assettype ON qr.asset_type_id = assettype.idLEFT JOIN m_request_type reqtype ON qr.request_type_id = reqtype.idLEFT JOIN m_user_master um ON vs.added_by = um.user_idLEFT JOIN m_item ON qrd.item_id = m_item.idLEFT JOIN m_unit_master unit ON vs.unit_id = unit.unit_idWHERE vsd.is_active = true;

-- public.get_vendor_negotitation source
CREATE OR REPLACE VIEW public.get_vendor_negotitationAS SELECT DISTINCT vn.id,qr.qr_no,qr.added_date AS qrdate,vq.vq_number,vq.added_date AS vqdate,m_store.store_name,m_vendor.name AS vendor,reqtype.type AS reqtype,assettype.type AS assettype,um.user_name,m_status.status,m_item.name AS itemname,qrd.quantity,qrd.warranty_period,qrd.expected_support_term,qrd.expected_payment,qrd.expected_technical_specification,unit.unit_name,unit.unit_address,qfd.vendor_cop,unit.imageFROM procurement.t_vendor_negociation vnLEFT JOIN procurement.t_quotation_fill qf ON vn.qf_id = qf.idLEFT JOIN procurement.t_quotation_request qr ON qr.id = qf.qr_idLEFT JOIN procurement.t_vendor_negociation_detail vnd ON vn.id = vnd.vendor_negociation_idLEFT JOIN procurement.t_quotation_fill_detail qfd ON qf.id = qfd.quotation_fill_id AND vnd.qf_detail_id = qfd.idLEFT JOIN procurement.t_quotation_request_detail qrd ON qr.id = qrd.qr_id AND qfd.qr_detail_id = qrd.idLEFT JOIN procurement.t_quotation_vendor vq ON qr.id = vq.qr_idLEFT JOIN m_store ON vn.store_id = m_store.store_idLEFT JOIN m_vendor ON vn.vendor_id = m_vendor.idLEFT JOIN m_request_type reqtype ON qr.request_type_id = reqtype.idLEFT JOIN m_asset_type assettype ON vn.asset_type_id = assettype.idLEFT JOIN m_user_master um ON vn.added_by = um.user_idLEFT JOIN m_status ON vn.status_id = m_status.idLEFT JOIN m_item ON qrd.item_id = m_item.idLEFT JOIN m_unit_master unit ON vn.unit_id = unit.unit_idWHERE vnd.is_active = true;

-- public.get_visit_details source
CREATE OR REPLACE VIEW public.get_visit_detailsAS SELECT DISTINCT pr.uhid_number,(((((m_prefix_master.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS name,spm.speciality_name,em.encounter_date,em.encounter_time,u.unit_name,('Dr. '::text || (((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text)) || dm.last_name::text AS docname,pem.payment_entitlement_desc,m_encounter_type_master.encounter_type_name,u.unit_address,em.created_date,em.created_by,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS created_user,em.encounter_type_id,em.encounter_id,em.doctor_id,m_user_master.user_id,u.unit_id,dm.first_name,dm.last_name,spm.speciality_id,'\x'::bytea AS image,COALESCE(em.user_defined_visit_type_id, 0) AS user_defined_visit_type_id,pem.payment_entitlement_desc AS payment_entitlement_new,pr.mobile_numberFROM opd.t_encounter_master emJOIN patient.t_patient_registration pr ON em.patient_id = pr.patient_idLEFT JOIN doctor.m_speciality_master spm ON em.dept_id = spm.speciality_idJOIN m_unit_master u ON em.unit_id = u.unit_idLEFT JOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_idJOIN m_payment_entitlement_master pem ON em.payment_entitlement_type_id = pem.payment_entitlement_idLEFT JOIN m_encounter_type_master ON em.encounter_type_id = m_encounter_type_master.encounter_type_idLEFT JOIN m_prefix_master ON pr.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_user_master ON em.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idLEFT JOIN opd.t_patient_sponsor_details ON em.encounter_id = t_patient_sponsor_details.encounter_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master cm ON t_patient_sponsor_details.payee_id = cm.company_idORDER BY em.encounter_date;

-- public.get_wo_quotation_negotiation source
CREATE OR REPLACE VIEW public.get_wo_quotation_negotiationAS SELECT qn.id,woqr.work_order_quotation_request_no,woqr.added_date AS reqdate,woqsv.quotation_vendor_no,woqsv.added_date AS vqrdate,m_store.store_name,contract.description AS contract,reqtype.type AS reqtype,m_vendor.name AS vendor,m_status.status,um.user_name,m_item.code,m_item.name AS itemname,wod.quantity,wod.remark,unit.unit_name,unit.unit_address,unit.imageFROM procurement.t_wo_quotation_negotiation qnLEFT JOIN procurement.t_wo_quotation_send_to_vendor woqsv ON qn.vendor_quotation_id = woqsv.idLEFT JOIN procurement.t_work_order_quotation_request woqr ON woqr.id = woqsv.quotation_request_idLEFT JOIN m_store ON woqr.store_id = m_store.store_idLEFT JOIN procurement.m_contract_type contract ON woqr.contract_type_id = contract.idLEFT JOIN m_request_type reqtype ON woqr.request_type_id = reqtype.idLEFT JOIN m_vendor ON woqsv.vendor_id = m_vendor.idLEFT JOIN m_status ON qn.status_id = m_status.idLEFT JOIN m_user_master um ON qn.added_by = um.user_idLEFT JOIN procurement.t_work_order wo ON woqr.work_order_id = wo.idLEFT JOIN procurement.t_work_order_detail wod ON wo.id = wod.work_order_idLEFT JOIN m_item ON wod.item_id = m_item.idLEFT JOIN m_unit_master unit ON qn.unit_id = unit.unit_idWHERE woqsv.is_active = true;

-- public.get_wo_quotationsendvendor source
CREATE OR REPLACE VIEW public.get_wo_quotationsendvendorAS SELECT DISTINCT woqsv.id,woqr.work_order_quotation_request_no,woqr.added_date AS woqrdate,woqsv.quotation_vendor_no,woqsv.added_date AS woqsvdate,m_store.store_name,m_vendor.name AS vendor,contract.description AS contract,reqtype.type AS reqtype,woqsv.due_date,woqsv.remark,um.user_name,m_status.status,statusapp.status AS statusapp,woqrd.expected_inclusion,woqrd.specification,woqrd.quantity,woqrd.remark AS remarksdetail,m_item.code,m_item.name,unit.unit_name,unit.unit_address,unit.unit_id,unit.imageFROM procurement.t_wo_quotation_send_to_vendor woqsvLEFT JOIN procurement.t_work_order_quotation_request woqr ON woqsv.quotation_request_id = woqr.idLEFT JOIN procurement.t_work_order_quotation_request_detail woqrd ON woqrd.work_order_quotation_request_id = woqr.idLEFT JOIN procurement.t_wo_quotation_send_to_vendor_detail woqsvd ON woqrd.id = woqsvd.quotation_request_detail_idLEFT JOIN m_store ON woqr.store_id = m_store.store_idLEFT JOIN m_vendor ON woqsv.vendor_id = m_vendor.idLEFT JOIN procurement.m_contract_type contract ON woqr.contract_type_id = contract.idLEFT JOIN m_request_type reqtype ON woqr.request_type_id = reqtype.idLEFT JOIN m_user_master um ON woqsv.added_by = um.user_idLEFT JOIN m_status ON woqsv.status_id = m_status.idLEFT JOIN m_status statusapp ON woqsv.approval_status_id = statusapp.idLEFT JOIN m_item ON woqrd.item_id = m_item.idLEFT JOIN unitinformation unit ON woqsv.unit_id = unit.unit_id;

-- public.get_workorderquotationentry source
CREATE OR REPLACE VIEW public.get_workorderquotationentryAS SELECT woqe.id,woqr.work_order_quotation_request_no,woqr.added_date,woqsv.quotation_vendor_no,woqsv.added_date AS qsvaddeddate,m_store.store_name,m_vendor.name AS vendor,contract.description AS contracttype,woqe.remark,um.user_name,m_status.status,statusapp.status AS statusapp,m_item.code,m_item.name AS itemname,wod.quantity,wod.specification,woqed.vendor_cop,unit.unit_name,unit.unit_address,unit.unit_id,unit.imageFROM procurement.t_wo_quotation_entry woqeJOIN procurement.t_wo_quotation_entry_detail woqed ON woqe.id = woqed.quotation_entry_idLEFT JOIN procurement.t_wo_quotation_send_to_vendor woqsv ON woqe.vendor_quotation_id = woqsv.idLEFT JOIN procurement.t_work_order_quotation_request woqr ON woqsv.quotation_request_id = woqr.idLEFT JOIN procurement.t_work_order wo ON woqr.work_order_id = wo.idLEFT JOIN procurement.t_work_order_detail wod ON wo.id = wod.work_order_idLEFT JOIN m_store ON woqr.store_id = m_store.store_idLEFT JOIN m_vendor ON woqsv.vendor_id = m_vendor.idLEFT JOIN procurement.m_contract_type contract ON woqr.contract_type_id = contract.idLEFT JOIN m_user_master um ON woqe.added_by = um.user_idLEFT JOIN m_status ON woqe.status_id = m_status.idLEFT JOIN m_status statusapp ON woqe.approval_status_id = statusapp.idLEFT JOIN m_item ON wod.item_id = m_item.idJOIN m_unit_master unit ON woqe.unit_id = unit.unit_idWHERE woqed.is_active = true;

-- public.getadmissiondetails source
CREATE OR REPLACE VIEW public.getadmissiondetailsAS SELECT DISTINCT pr.uhid_number,adde.doa AS admission_date,dis.discharge_date,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS name,''::text AS address,gm.gender_name,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,pr.mobile_number,pim.bed_desc AS bed_number,''::character varying(100) AS user_name,pim.company_desc,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS docname,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,''::character varying(200) AS unit_logo,0::double precision AS deposit,0::double precision AS orderamount,ad.admission_id,rm.referral_name::text AS referral_contact_person,ad.admission_number,m_floor.floor_name,pr.first_name,dm.first_name AS docfirstname,dm.middle_name AS docmiddlename,dm.last_name AS doclastname,dm.doctor_id,''::character varying(255) AS visit_type_name,0 AS visit_type_id,0 AS speciality_id,sp.speciality_name,m_ward.ward_name,unitinformation.unit_id,''::text AS image,now()::date - pim.doa::date AS staydays,m_ward.ward_id,pr.gender_id,0 AS disstaydays,m_payment_entitlement_master.payment_entitlement_desc,m_payment_entitlement_master.payment_entitlement_id,cm.company_id,''::text AS referral_type_code,''::text AS username,ad.created_date,''::text AS room_desc,m_reason_master.reason_desc,ad.reason_id,adde.is_discharge,adde.is_cancel,tpd.district_id,tpd.state_id,tpd.city_id,statmas.state_name,dismas.district_name,city.city_name,m_payment_entitlement_master.payment_entitlement_desc AS payment_entitlement_new,admtype.admission_type_id,admtype.admission_type_desc,dis.discharge_time,ad.status AS admission_statusFROM adt.t_admission adJOIN patient.t_patient_registration pr ON ad.patient_id = pr.patient_idJOIN adt.t_admission_details adde ON ad.admission_id = adde.admission_idLEFT JOIN adt.m_admission_type_master admtype ON admtype.admission_type_id = adde.admission_type_idLEFT JOIN adt.t_discharge dis ON ad.admission_id = dis.admission_id AND dis.status = 'A'::bpcharJOIN m_gender_master gm ON pr.gender_id = gm.gender_idJOIN m_patient_visit_metadata pim ON ad.admission_id = pim.admission_idLEFT JOIN doctor.m_doctor_master dm ON ad.doctor_id = dm.doctor_idLEFT JOIN doctor.m_speciality_master sp ON sp.speciality_id = ad.speciality_idLEFT JOIN m_unit_master unitinformation ON ad.unit_id = unitinformation.unit_idLEFT JOIN adt.m_ward_master m_ward ON adde.ward_id = m_ward.ward_idLEFT JOIN adt.m_floor_master m_floor ON m_ward.floor_id = m_floor.floor_idLEFT JOIN opd.t_patient_sponsor_details ON ad.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master cm ON t_patient_sponsor_details.payee_id = cm.company_idLEFT JOIN adt.m_reason_master ON m_reason_master.reason_master_id = ad.reason_idLEFT JOIN t_referal_details rd ON rd.admission_id = ad.admission_id AND rd.status = 'A'::bpcharLEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idLEFT JOIN patient.t_patient_details tpd ON pr.patient_id = tpd.patient_idLEFT JOIN m_district_master dismas ON dismas.district_id = tpd.district_idLEFT JOIN m_state_master statmas ON statmas.state_id = tpd.state_idLEFT JOIN m_city_master city ON city.city_id = tpd.city_idWHERE adde.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS maxFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = ad.admission_id))ORDER BY adde.doa;

-- public.getadmittedpatientlist source
CREATE OR REPLACE VIEW public.getadmittedpatientlistAS SELECT DISTINCT pr.uhid_number,adde.doa AS admission_date,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS name,pd.address,gm.gender_name,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,pr.mobile_number,bm.bed_number::character varying(100) AS bed_number,um.user_name,cm.company_desc,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS docname,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_logo,0::double precision AS deposit,charges.orderedamount::double precision AS orderamount,ad.admission_id,m_refferel.referral_name AS referral_contact_person,ad.admission_number,m_floor.floor_name,COALESCE(deposit_master.depositamount, 0::double precision) AS depositamount,COALESCE(deposit_master.available, 0::double precision) AS available,deposit_master.consumed,now()::date - adde.doa::date AS staydays,unitinformation.unit_id,pr.first_name AS firstname,vtm.visit_type_name,vtm.visit_type_id,vtm.visit_type_code,ad.organization_id,'\x'::bytea AS image,dm.doctor_id,ad.created_date,m_ward.ward_id,m_ward.ward_name,m_payment_entitlement_master.payment_entitlement_desc,m_payment_entitlement_master.payment_entitlement_id,cm.company_id,charges.self_payable,charges.credit_payable,'\x'::bytea AS imglogo,m_ward.gender_id AS srno,sp.speciality_id,sp.speciality_nameFROM adt.t_admission adJOIN patient.t_patient_registration pr ON ad.patient_id = pr.patient_idJOIN adt.t_admission_details adde ON ad.admission_id = adde.admission_idJOIN patient.t_patient_details pd ON pr.patient_id = pd.patient_idLEFT JOIN m_gender_master gm ON pr.gender_id = gm.gender_idJOIN doctor.m_doctor_master dm ON ad.doctor_id = dm.doctor_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = ad.speciality_idLEFT JOIN adt.m_bed_master bm ON adde.bed_id = bm.bed_idLEFT JOIN m_user_master um ON ad.updated_by = um.user_idLEFT JOIN m_unit_master unitinformation ON ad.unit_id = unitinformation.unit_idLEFT JOIN t_referal_details admreff ON ad.admission_id = admreff.admission_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN adt.m_ward_master m_ward ON adde.ward_id = m_ward.ward_idLEFT JOIN adt.m_floor_master m_floor ON m_ward.floor_id = m_floor.floor_idLEFT JOIN m_visit_type_master vtm ON ad.visit_type_id = vtm.visit_type_idLEFT JOIN ( SELECT m_deposit_master.admission_id,sum(m_deposit_master.deposit_amount) AS depositamount,sum(m_deposit_master.available_deposit) AS available,sum(m_deposit_master.consumed_deposit) AS consumedFROM billing.m_deposit_masterWHERE m_deposit_master.visit_type_id &lt;&gt; 1GROUP BY m_deposit_master.admission_id) deposit_master ON ad.admission_id = deposit_master.admission_idLEFT JOIN opd.t_patient_sponsor_details ON ad.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master cm ON t_patient_sponsor_details.payee_id = cm.company_idLEFT JOIN ( SELECT sum(chargesdetail.net_amount) AS orderedamount,sum(chargesdetail.self_payable) AS self_payable,sum(chargesdetail.credit_payable) AS credit_payable,charges_1.admission_idFROM t_order_master charges_1JOIN t_order_details chargesdetail ON charges_1.order_id = chargesdetail.order_idWHERE charges_1.visit_type_id &lt;&gt; 1 AND chargesdetail.is_drug = 'N'::bpchar AND chargesdetail.service_is_billed = 0 AND chargesdetail.package_consumption_amt = 0::numeric AND chargesdetail.ord_cancelled = 'N'::bpcharGROUP BY charges_1.admission_id) charges ON charges.admission_id = ad.admission_idWHERE ad.doctor_id &lt;&gt; 0 AND ad.status = 'A'::bpchar AND adde.status = 'A'::bpchar AND adde.nursing_acceptance = 'Y'::bpcharORDER BY adde.doa DESC;

-- public.getbilldetails source
CREATE OR REPLACE VIEW public.getbilldetailsAS SELECT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,encmst.encounter_number,encmst.unit_token_number,m_tax.name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,billdtls.discount AS dtlsdiscount,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.encounter_id,doctorinformation.speciality_id,billmst.bill_date_time,company.company_desc,billdtls.payee_id,um.imageFROM billing.t_billing_details billdtlsLEFT JOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idLEFT JOIN m_general_ledger_master genledmst ON genledmst.general_ledger_id = spc.general_ledger_idLEFT JOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idLEFT JOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN m_unit_master um ON billmst.unit_id = um.unit_idLEFT JOIN m_tax ON billdtls.tax_id = m_tax.idLEFT JOIN doctor.doctorinformation ON billmst.encounter_id = doctorinformation.encounter_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idWHERE billmst.visit_type_id = 1ORDER BY billmst.billing_master_id DESC;

-- public.getbilldetails_medipark source
CREATE OR REPLACE VIEW public.getbilldetails_mediparkAS SELECT DISTINCT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,um.unit_name AS organization_name,um.unit_address AS organization_address,um.unit_contact::text AS organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,COALESCE(billdtls.concession, 0::double precision) AS concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,''::character varying(200) AS unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,''::text AS registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,encmst.encounter_number,encmst.unit_token_number,''::character varying(100) AS name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,COALESCE(billdtls.discount, 0::double precision) AS dtlsdiscount,doctorm.doctor_id,''::text AS doctorname,''::character varying(100) AS docgender,''::character varying(200) AS doctor_category_description,''::character varying(100) AS docspeciality,'00:00:00'::interval AS docage,'2021-01-01 00:00:00'::timestamp without time zone AS docdob,''::character varying AS country_calling_code,''::character varying AS docmobile,''::character varying(200) AS docemail,''::text AS doctor_image,''::text AS docreg,0 AS slot_time_span,0::double precision AS doctor_episod_time_span,billmst.encounter_id,0 AS speciality_id,billmst.bill_date_time,company.company_desc,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name,billdtls.order_details_id,billmst.bill_cancel_remark,od.is_package_service,od.package_id,od.is_package,''::character varying(200) AS bill_status_desc,billdtls.package_consumption_amt,servmst.service_master_id,mrm.referral_name,payment.amount AS paidamount,pntmst.mobile_number,gender.gender_name,abs(date_part('Year'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,um.image,abs(date_part('Month'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,((('Dr. '::text || ''::text) || doctorm1.first_name::text) || ' '::text) || doctorm1.last_name::text AS orderdocname,billmst.bill_remark,0 AS referral_id,qm.qualification_desc,t_patient_sponsor_details.employee_name::character varying(250) AS empname,( SELECT ustm.service_codeFROM service.m_unit_service_tariff_master ustmWHERE ustm.visit_type_id = 1 AND ustm.status = 'A'::bpchar AND ustm.service_id = servmst.service_master_id AND ustm.tariff_id = t_patient_sponsor_details.tariff_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharORDER BY ustm.unit_service_tariff_id DESCLIMIT 1) AS service_standard_code,t_patient_sponsor_details.tariff_id,od.bed_category_id,abs(date_part('Day'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenbyFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN m_patient_visit_metadata pim ON billmst.encounter_id = pim.encouter_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idJOIN m_gender_master gender ON pntmst.gender_id = gender.gender_idJOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idJOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN m_unit_master um ON billmst.unit_id = um.unit_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idLEFT JOIN m_qualification_master qm ON doctorm.qualification_id = qm.qualification_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idLEFT JOIN opd.t_patient_sponsor_details ON encmst.encounter_id = t_patient_sponsor_details.encounter_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.ord_cancelled = 'N'::bpcharLEFT JOIN t_referal_details reffdel ON reffdel.encounter_id = encmst.encounter_idLEFT JOIN adt.m_referral_master mrm ON mrm.referral_id = reffdel.referral_idLEFT JOIN doctor.m_doctor_master doctorm1 ON billdtls.ord_doc_id = doctorm1.doctor_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idWHERE billmst.visit_type_id = 1ORDER BY billmst.billing_master_id DESC;

-- public.getbilldetails_new source
CREATE OR REPLACE VIEW public.getbilldetails_newAS SELECT DISTINCT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,encmst.encounter_number,encmst.unit_token_number,m_tax.name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,billdtls.discount AS dtlsdiscount,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.encounter_id,doctorinformation.speciality_id,billmst.bill_date_time,company.company_desc,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name,billdtls.order_details_id,billmst.bill_cancel_remark,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,billdtls.package_consumption_amt,servmst.service_master_id,um.image,pim.patientmobile,pim.ageyear,pim.patientaddress,COALESCE(payment.amount, 0::double precision) AS paidamount,COALESCE(depcons.consumed_amount, 0::double precision) AS consumed_amount,abs(date_part('Month'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS months,pim.gender_nameFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idLEFT JOIN m_general_ledger_master genledmst ON genledmst.general_ledger_id = spc.general_ledger_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idLEFT JOIN m_tax ON billdtls.tax_id = m_tax.idLEFT JOIN doctor.doctorinformation ON billmst.encounter_id = doctorinformation.encounter_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_idJOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idJOIN patientinformation pim ON encmst.patient_id = pim.patient_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idLEFT JOIN ( SELECT sum(depcons_1.consumed_amount) AS consumed_amount,depcons_1.bill_idFROM billing.t_payment_deposite_consumption depcons_1JOIN billing.m_billing_master bm ON depcons_1.bill_id = bm.billing_master_idGROUP BY depcons_1.bill_id) depcons ON billmst.billing_master_id = depcons.bill_idWHERE billmst.visit_type_id = 1ORDER BY billmst.billing_master_id DESC;

-- public.getconcessionwisebilldetails source
CREATE OR REPLACE VIEW public.getconcessionwisebilldetailsAS SELECT bm.bill_number,bm.bill_date_time,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS name,bm.total_bill_amount,bm.gst,bm.discount_amount + bm.concession_amount AS discount,bm.net_amount,round(bm.outstanding) AS outstanding,bm.net_amount - bm.outstanding AS paid_amountFROM billing.m_billing_master bmJOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idWHERE bm.discount_amount &gt; 0::double precision OR bm.concession_amount &gt; 0::double precision;

-- public.getconsent source
CREATE OR REPLACE VIEW public.getconsentAS SELECT consent.consent_master_id,consent.admission_id,consent.template_desc,pim.uhid_number,pim.patientname,adm.admission_number,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,unitinformation.imageFROM t_patient_consent_mapper consentJOIN adt.t_admission adm ON consent.admission_id = adm.admission_idJOIN patientinformation pim ON adm.patient_id = pim.patient_idJOIN unitinformation ON consent.unit_id = unitinformation.unit_idJOIN doctor.m_doctor_master dm ON adm.admitting_doctor_id = dm.doctor_id;

-- public.getcreditbillreport source
CREATE OR REPLACE VIEW public.getcreditbillreportAS SELECT DISTINCT bm.bill_number,bm.bill_date_time,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,bm.total_bill_amount + bm.gst AS bill_amount,bm.discount_amount,bm.net_amount,bm.outstanding,um.user_name,vtm.visit_type_code,u.unit_name,u.unit_address_2,company.company_desc,u.unit_id,u.imageFROM patient.t_patient_registration prJOIN billing.m_billing_master bm ON pr.patient_id = bm.patient_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idJOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idJOIN unitinformation u ON pr.unit_id = u.unit_idJOIN opd.t_patient_sponsor_details sponsordetail ON sponsordetail.encounter_id = bm.encounter_idLEFT JOIN t_company_master company ON company.company_id = sponsordetail.payee_idWHERE bm.outstanding &gt; 0::double precision AND bm.bill_cancelled = 'N'::bpcharUNION ALLSELECT DISTINCT bm.bill_number,bm.bill_date_time,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,bm.total_bill_amount + bm.gst AS bill_amount,bm.discount_amount,bm.net_amount,bm.outstanding,um.user_name,vtm.visit_type_code,u.unit_name,u.unit_address_2,company.company_desc,u.unit_id,u.imageFROM patient.t_patient_registration prJOIN billing.m_billing_master bm ON pr.patient_id = bm.patient_idLEFT JOIN m_user_master um ON bm.created_by = um.user_idJOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idJOIN unitinformation u ON pr.unit_id = u.unit_idJOIN opd.t_patient_sponsor_details sponsordetail ON sponsordetail.admission_id = bm.admission_idLEFT JOIN t_company_master company ON company.company_id = sponsordetail.payee_idWHERE bm.outstanding &gt; 0::double precision AND bm.bill_cancelled = 'N'::bpchar;

-- public.getdischargecancelleddetails source
CREATE OR REPLACE VIEW public.getdischargecancelleddetailsAS SELECT DISTINCT d.discharge_id,ad.doa,d.discharge_date,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctor_name,bm.bed_number,pcm.patient_category,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,d.note_cancel,distype.discharge_type_name,a.admission_number,unitinformation.unit_id,'\x'::bytea AS image,concat(emp.first_name, ' ', emp.last_name) AS emp,um.user_id,d.updated_dateFROM adt.t_admission aJOIN adt.t_admission_details ad ON a.admission_id = ad.admission_idJOIN adt.t_discharge d ON ad.admission_id = d.admission_idJOIN patient.t_patient_registration pr ON a.patient_id = pr.patient_idJOIN doctor.m_doctor_master dm ON a.doctor_id = dm.doctor_idJOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_idJOIN m_patient_category_master pcm ON pr.patient_category_id = pcm.patient_category_idLEFT JOIN m_unit_master unitinformation ON d.unit_id = unitinformation.unit_idLEFT JOIN adt.m_reason_for_discharge_master distype ON distype.discharge_type_id = d.discharge_type_idLEFT JOIN m_user_master um ON um.user_id = d.updated_byLEFT JOIN m_employee_master emp ON emp.user_id = um.user_idWHERE d.discharge_status_id = 6;

-- public.getdischargedetails source
CREATE OR REPLACE VIEW public.getdischargedetailsAS SELECT DISTINCT ad.doa,d.discharge_date,pr.uhid_number,concat(prefix.prefix_desc, '', pr.first_name::text, ' ', pr.middle_name::text, ' ', pr.last_name::text) AS patient_name,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctor_name,bm.bed_number,pcm.patient_category,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,a.admission_number,m_discharge_status_master.discharge_desc,d.discharge_status_id,vtm.visit_type_name,vtm.visit_type_id,vtm.visit_type_code,a.organization_id,a.unit_id,a.patient_id,unitinformation.image,wm.ward_name,bm.bed_category_id,bm.floor_id,bm.bed_desc,adm_entilement.payment_entitlement_desc AS payment_entitlement,payeename.company_desc,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,gender.gender_name,d.discharge_date::date - ad.doa::date AS staydays,sp.speciality_name,state.state_name,district.district_name,d.discharge_time,wm.ward_id,dm.doctor_id,distype.discharge_type_id,distype.discharge_type_name,payeename.company_id,rm.referral_id,rm.referral_nameFROM adt.t_admission aJOIN adt.t_admission_details ad ON a.admission_id = ad.admission_idJOIN adt.t_discharge d ON ad.admission_id = d.admission_id AND d.status = 'A'::bpcharLEFT JOIN doctor.m_speciality_master sp ON a.speciality_id = sp.speciality_idJOIN patient.t_patient_registration pr ON a.patient_id = pr.patient_idJOIN m_prefix_master prefix ON pr.prefix_id = prefix.prefix_idLEFT JOIN patient.t_patient_details prd ON pr.patient_id = prd.patient_idLEFT JOIN m_state_master state ON prd.state_id = state.state_idLEFT JOIN m_district_master district ON prd.district_id = district.district_idJOIN m_gender_master gender ON pr.gender_id = gender.gender_idLEFT JOIN doctor.m_doctor_master dm ON a.doctor_id = dm.doctor_idJOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_idLEFT JOIN adt.m_ward_master wm ON ad.ward_id = wm.ward_idJOIN m_patient_category_master pcm ON pr.patient_category_id = pcm.patient_category_idLEFT JOIN adt.m_reason_for_discharge_master distype ON distype.discharge_type_id = d.discharge_type_idLEFT JOIN m_unit_master unitinformation ON d.unit_id = unitinformation.unit_idLEFT JOIN adt.m_discharge_status_master ON d.discharge_status_id = m_discharge_status_master.discharge_status_idLEFT JOIN m_visit_type_master vtm ON a.visit_type_id = vtm.visit_type_idLEFT JOIN opd.t_patient_sponsor_details ON a.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master adm_entilement ON t_patient_sponsor_details.payment_entitlement_id = adm_entilement.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = t_patient_sponsor_details.payee_idLEFT JOIN t_referal_details rd ON rd.admission_id = a.admission_id AND rd.status = 'A'::bpcharLEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idWHERE ad.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS maxFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = a.admission_id AND (t_admission_details.is_cancel IS NULL OR t_admission_details.is_cancel = 'N'::bpchar)));
-- public.getdoctorwiseservicelist source
CREATE OR REPLACE VIEW public.getdoctorwiseservicelistAS SELECT bm.billing_master_id,orderdetails.ord_doc_id,(((doctormaster.first_name::text || ' '::text) || doctormaster.middle_name::text) || ' '::text) || doctormaster.last_name::text AS doctorname,bm.bill_number,bm.bill_date_time::date AS billdate,pim.patientname,servicemaster.service_standard_name,bdet.net_amt,unitinformation.unit_name,unitinformation.unit_address,pim.uhid_number,doctormaster.first_name,doctormaster.middle_name,doctormaster.last_name,unitinformation.imageFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN service.m_service_master servicemaster ON bdet.service_id = servicemaster.service_master_idJOIN patientinformation pim ON bm.patient_id = pim.patient_idJOIN t_order_details orderdetails ON bdet.order_details_id = orderdetails.order_details_idLEFT JOIN doctor.m_doctor_master doctormaster ON orderdetails.ord_doc_id = doctormaster.doctor_idLEFT JOIN unitinformation ON bm.unit_id = unitinformation.unit_idORDER BY orderdetails.ord_doc_id DESC;

-- public.getdoctorwiseservicelist_1 source
CREATE OR REPLACE VIEW public.getdoctorwiseservicelist_1AS SELECT DISTINCT od.order_details_id AS doctor_share_id,bd.billing_details_id AS bill_dtl_id,od.order_details_id AS ord_dtl_id,bd.service_id,bd.gross_amount AS total_amount,bd.discount + bd.concession AS concession,bd.discount,bd.tax_amount AS tax_amt,bd.net_amt AS net_amount,0 AS share_per,0 AS due_share_amt,bd.net_amt AS hosp_share,0 AS doc_share,od.ord_doc_id AS doc_id,''::text AS alise_name,bm.bill_number,sm.service_standard_name,bm.visit_type_id,(((prefix.prefix_desc || ' '::text) || registration.first_name::text) || ' '::text) || registration.last_name::text AS patientname,od.order_date AS processed_share_date,registration.uhid_number,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_id,sm.service_master_id,em.encounter_number AS op_ip_number,concat(dmop.first_name, ' ', dmop.last_name) AS doctorname,bm.bill_status_id,'\x'::bytea AS image,smop.speciality_name AS speciality,concat(dmopservice.first_name, ' ', dmopservice.last_name) AS doctortret,bm.bill_date_time,sps.speciality_name AS servicespeciality,ssps.sub_speciality_name AS servicesubspeciality,bd.quantity,bpd.payment_entitlement_id,em.encounter_date AS admdate,em.encounter_date AS disdate,rm.referral_name,bm.total_bill_amount,concat(dmopservice.first_name, ' ', dmopservice.last_name) AS serdoc,smop.speciality_id AS docspeciality_id,dmop.doctor_id AS admittingdoc_id,bd.rate,cnm.credit_note_no,cnd.cr_net_amount,bm.billing_master_id,spm.speciality_name,dmopservice.doctor_idFROM billing.t_billing_details bdJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master sps ON sps.speciality_id = sm.speciality_idJOIN doctor.m_sub_speciality_master ssps ON ssps.sub_speciality_id = sm.sub_speciality_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN doctor.m_doctor_master dmop ON dmop.doctor_id = em.doctor_idLEFT JOIN doctor.m_speciality_master smop ON smop.speciality_id = em.dept_idJOIN patient.t_patient_registration registration ON bm.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idJOIN m_unit_master ON bm.unit_id = m_unit_master.unit_idJOIN t_order_details od ON bd.order_details_id = od.order_details_idLEFT JOIN doctor.m_doctor_master dmopservice ON dmopservice.doctor_id = od.ord_doc_idLEFT JOIN t_referal_details rd ON rd.encounter_id = bm.encounter_id AND rd.status = 'A'::bpchar AND rd.referral_type_id = 15LEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idJOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.priority_id = 1 AND bpd.status = 'A'::"char"LEFT JOIN billing.m_credit_note_master cnm ON cnm.bill_id = bm.billing_master_id AND cnm.status = 'A'::bpcharLEFT JOIN billing.t_credit_note_detail cnd ON cnd.order_detail_id = bd.order_details_id AND cnm.credit_note_id = cnd.credit_note_idLEFT JOIN doctor.t_doctor_speciality_mapper mp ON dmopservice.doctor_id = mp.doctor_idLEFT JOIN doctor.m_speciality_master spm ON spm.speciality_id = mp.speciality_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1 AND od.is_package_service = 'N'::"char"UNION ALLSELECT DISTINCT od.order_details_id AS doctor_share_id,bd.billing_details_id AS bill_dtl_id,od.order_details_id AS ord_dtl_id,bd.service_id,bd.gross_amount AS total_amount,bd.discount + bd.concession AS concession,bd.discount,bd.tax_amount AS tax_amt,bd.net_amt AS net_amount,0 AS share_per,0 AS due_share_amt,bd.net_amt AS hosp_share,0 AS doc_share,od.ord_doc_id AS doc_id,''::text AS alise_name,bm.bill_number,sm.service_standard_name,bm.visit_type_id,(((prefix.prefix_desc || ' '::text) || registration.first_name::text) || ' '::text) || registration.last_name::text AS patientname,od.order_date AS processed_share_date,registration.uhid_number,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_id,sm.service_master_id,ad.admission_number AS op_ip_number,concat(dmip.first_name, ' ', dmip.last_name) AS doctorname,bm.bill_status_id,'\x'::bytea AS image,smip.speciality_name AS speciality,concat(dmipadm.first_name, ' ', dmipadm.last_name) AS doctortret,bm.bill_date_time,sps.speciality_name AS servicespeciality,ssps.sub_speciality_name AS servicesubspeciality,bd.quantity,bpd.payment_entitlement_id,tad.doa AS admdate,d.discharge_date AS disdate,rm.referral_name,bm.total_bill_amount,concat(serdoc.first_name, ' ', serdoc.last_name) AS serdoc,smip.speciality_id AS docspeciality_id,dmipadm.doctor_id AS admittingdoc_id,bd.rate,cnm.credit_note_no,cnd.cr_net_amount,bm.billing_master_id,spm.speciality_name,serdoc.doctor_idFROM billing.t_billing_details bdJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master sps ON sps.speciality_id = sm.speciality_idJOIN doctor.m_sub_speciality_master ssps ON ssps.sub_speciality_id = sm.sub_speciality_idJOIN adt.t_admission ad ON bm.admission_id = ad.admission_idJOIN adt.t_admission_details tad ON tad.admission_id = ad.admission_idJOIN doctor.m_doctor_master dmip ON dmip.doctor_id = ad.doctor_idJOIN doctor.m_doctor_master dmipadm ON dmipadm.doctor_id = ad.admitting_doctor_idLEFT JOIN doctor.m_doctor_master serdoc ON bd.ord_doc_id = serdoc.doctor_idJOIN doctor.m_speciality_master smip ON smip.speciality_id = ad.speciality_idJOIN patient.t_patient_registration registration ON bm.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idJOIN m_unit_master ON bm.unit_id = m_unit_master.unit_idJOIN t_order_details od ON bd.order_details_id = od.order_details_idLEFT JOIN billing.m_credit_note_master cnm ON cnm.bill_id = bm.billing_master_id AND cnm.status = 'A'::bpcharLEFT JOIN billing.t_credit_note_detail cnd ON cnd.order_detail_id = bd.order_details_id AND cnm.credit_note_id = cnd.credit_note_idLEFT JOIN ( SELECT max(t_discharge.discharge_date) AS discharge_date,t_discharge.admission_idFROM adt.t_dischargeGROUP BY t_discharge.admission_id) d ON d.admission_id = ad.admission_idLEFT JOIN t_referal_details rd ON rd.admission_id = bm.admission_id AND rd.status = 'A'::bpchar AND rd.referral_type_id = 15LEFT JOIN adt.m_referral_master rm ON rm.referral_id = rd.referral_idJOIN billing.t_bill_payee_details bpd ON bpd.bill_id = bm.billing_master_id AND bpd.priority_id = 1 AND bpd.status = 'A'::"char"LEFT JOIN doctor.t_doctor_speciality_mapper mp ON serdoc.doctor_id = mp.doctor_idLEFT JOIN doctor.m_speciality_master spm ON spm.speciality_id = mp.speciality_idWHERE od.is_package_service = 'N'::"char" AND tad.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = ad.admission_id)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1;

-- public.getexpireditemlist source
CREATE OR REPLACE VIEW public.getexpireditemlistAS SELECT m_item.id,m_item.code,m_item.hsn_code,m_item.name,m_store.store_name,t_batch.quantity,t_batch.batch_no,t_batch.expiry_date,t_batch.current_quantity,t_batch.cop,t_batch.rate,t_batch.selling_price,t_batch.vendor_id,t_batch.id AS batchid,m_store.store_id,m_vendor.name AS vendorname,unitinformation.unit_name,unitinformation.unit_address_2,unitinformation.imageFROM inventory.t_store_stockLEFT JOIN inventory.t_batch ON t_store_stock.batch_id = t_batch.idJOIN m_item ON t_batch.item_id = m_item.idJOIN m_store ON t_store_stock.store_id = m_store.store_idLEFT JOIN m_vendor ON m_vendor.id = t_batch.vendor_idJOIN unitinformation ON t_store_stock.unit_id = unitinformation.unit_idWHERE t_batch.expiry_date &lt;= 'now'::text::date;

-- public.getgrnreturnsummery source
CREATE OR REPLACE VIEW public.getgrnreturnsummeryAS SELECT rg.added_date,grn.grn_number,rg.ret_gp_no,rg.request_type_id,rg.status_id,rg.approval_status_id,s.store_name,v.name AS vendorname,rg.net_amount,rg.total_tax_amount,rg.total_amt,u.unit_name,u.unit_address_2,atm.type,u.unit_id,u.imageFROM inventory.t_returnable_gatepass rgLEFT JOIN m_store s ON rg.store_id = s.store_idLEFT JOIN m_vendor v ON v.id = rg.vendor_idLEFT JOIN procurement.t_good_receipt_note grn ON rg.grn_id = grn.idJOIN unitinformation u ON rg.unit_id = u.unit_idLEFT JOIN m_asset_type atm ON rg.asset_type_id = atm.idWHERE rg.cancel_reason_id IS NULL;

-- public.gethistopatholgyreport source
CREATE OR REPLACE VIEW public.gethistopatholgyreportAS SELECT lsdel.lab_sample_dtls_id,pim.patient_id,pim.uhid_number,pim.patientname,pim.age,pim.gender_name,concat('Dr.', ' ', dm.first_name, ' ', dm.last_name) AS doctername,om.order_no,lsdel.sample_collection_datetime,CASEWHEN om.admission_id IS NULL THEN em.encounter_numberWHEN om.admission_id IS NOT NULL THEN adm.admission_numberELSE NULL::character varyingEND AS opipdno,lsm.sample_no,um.unit_id,um.unit_address,um.unit_address_2,um.unit_contact,um.unit_contact_2,um.unit_logo,um.unit_website,om.org_id,utm.user_id,utm.user_name,labdept.sub_speciality_name AS department_name,um.unit_name,ltr.report_no,ltr.template_result,ltr.created_date,testmaster.test_desc,abs(date_part('Year'::text, age(pim.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,um.imageFROM lab.t_template_result ltrJOIN lab.t_lab_sample_dtls lsdel ON ltr.lab_sample_dtls_id = lsdel.lab_sample_dtls_idJOIN lab.t_lab_sample_master lsm ON lsdel.lab_sample_id = lsm.lab_sample_idJOIN t_order_master om ON om.order_id = lsm.order_idLEFT JOIN adt.t_admission adm ON om.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON om.encounter_id = em.encounter_idLEFT JOIN lab.t_panel_master plm ON plm.panel_id = lsdel.profile_idLEFT JOIN patient.patientinformation pim ON lsm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master dm ON om.ord_doctor_id = dm.doctor_idLEFT JOIN unitinformation um ON um.unit_id = lsm.org_unit_idJOIN m_user_master utm ON ltr.created_by = utm.user_idLEFT JOIN lab.m_test_master testmaster ON lsdel.test_id = testmaster.test_idLEFT JOIN doctor.m_sub_speciality_master labdept ON lsdel.sub_dept_id = labdept.sub_speciality_id;

-- public.getipdadvanceamount source
CREATE OR REPLACE VIEW public.getipdadvanceamountAS SELECT um.unit_name,um.unit_address,um.registration_number,um.unit_contact,um.unit_contact_2,um.unit_country_code,um.currency_name,um.sub_currency,pr.patient_id,pr.uhid_number,dep.admission_id,adm.created_date::date AS admissiondate,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patientname,depdt.payment_mode_id AS modeid,pmode.payment_mode_desc AS mode,depdt.amount AS recamount,dep.deposit_date::date AS date,dep.deposit_master_id AS depositid,dep.org_id AS orgid,dep.unit_id AS unitid,depdt.card_no AS cardnumber,depdt.card_type_id AS cardtypeid,depdt.cheque_number AS chequenumber,depdt.cheque_date AS chequedate,bank.bank_name AS bankname,depdt.deposit_details_id AS depositdetailsid,userm.user_id,userm.user_name,dep.visit_type_id,um.unit_address_2,um.imageFROM patient.t_patient_registration prLEFT JOIN unitinformation um ON um.unit_id = pr.unit_idLEFT JOIN billing.m_deposit_master dep ON pr.patient_id = dep.patient_idLEFT JOIN billing.t_payment_deposit_details depdt ON depdt.deposit_id = dep.deposit_master_idJOIN m_payment_mode_master pmode ON pmode.payment_mode_id = depdt.payment_mode_idLEFT JOIN billing.m_bank_master bank ON bank.bank_id = depdt.bank_idJOIN m_user_master userm ON pr.user_id = userm.user_idJOIN adt.t_admission adm ON dep.admission_id = adm.admission_idWHERE dep.visit_type_id = 2;

-- public.getipdbilldetails source
CREATE OR REPLACE VIEW public.getipdbilldetailsAS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pinf.age,pinf.gender_name,adt.doa,''::text AS pdd,dcs.discharge_desc,dc.discharge_date,pntmst.email,billdtls.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,pm.prefix_desc,(((((pm.prefix_desc || '.'::text) || pntmst.first_name::text) || ' '::text) || pntmst.middle_name::text) || ' '::text) || pntmst.last_name::text AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,t_company_master.company_desc,m_payment_entitlement_master.payment_entitlement_desc,m_tariff_master.tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,COALESCE(t_associated_company_master.associated_company_name, ''::character varying) AS associated_company_name,m_company_contract_master.associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,m_bed_category_master.bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,( SELECT sum(test.self_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_self_payable,( SELECT sum(test.credit_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,((('Dr.'::text || ' '::text) || admdoctor.first_name::text) || ' '::text) || admdoctor.last_name::text AS admdoctor,m_refferel.referral_contact_person,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name AS contract_name_new,od.created_date AS orderdate,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,um.image,COALESCE(advforadmission(am.admission_id::double precision), 0::double precision) AS deposit,COALESCE(depositcon.consumed_amount, 0::double precision) AS consumed_amount,( SELECT dc_1.discharge_dateFROM adt.t_discharge dc_1WHERE dc_1.admission_id = am.admission_idLIMIT 1) AS disdate,( SELECT dc_1.discharge_timeFROM adt.t_discharge dc_1WHERE dc_1.admission_id = am.admission_idLIMIT 1) AS distime,( SELECT distype.discharge_type_nameFROM adt.t_discharge disJOIN adt.m_reason_for_discharge_master distype ON dis.discharge_type_id = distype.discharge_type_idWHERE dis.admission_id = am.admission_idORDER BY dis.discharge_date DESCLIMIT 1) AS distype,od.order_date AS orddate,subgroupmaster.sub_speciality_name,COALESCE(payment.amount, 0::double precision) AS paidamount,payment.deposite_consumption_idFROM billing.m_billing_master billmstLEFT JOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idLEFT JOIN patient.t_patient_registration pntmst ON pntmst.patient_id = billmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idLEFT JOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON billdtls.ord_doc_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN patient.patientinformation pinf ON pntmst.patient_id = pinf.patient_idLEFT JOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN ( SELECT t_discharge.admission_id,t_discharge.discharge_id,t_discharge.discharge_status_id,t_discharge.discharge_dateFROM adt.t_dischargeORDER BY t_discharge.discharge_id DESCLIMIT 1) dc ON am.admission_id = dc.admission_idLEFT JOIN adt.m_discharge_status_master dcs ON dc.discharge_status_id = dcs.discharge_status_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_category_master ON adt.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1LEFT JOIN t_company_master ON t_company_master.company_id = t_patient_sponsor_details.payee_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN t_associated_company_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON billmst.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idLEFT JOIN doctor.m_sub_speciality_master subgroupmaster ON servmst.sub_speciality_id = subgroupmaster.sub_speciality_idLEFT JOIN doctor.m_doctor_master admdoctor ON am.admitting_doctor_id = admdoctor.doctor_idLEFT JOIN t_referal_details admreff ON am.admission_id = admreff.admission_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idLEFT JOIN t_order_details od ON billdtls.order_details_id = od.order_details_idLEFT JOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_idLEFT JOIN ( SELECT prm.billing_master_id,prm.deposite_consumption_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id, prm.deposite_consumption_id) payment ON billmst.billing_master_id = payment.billing_master_idWHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND adt.nursing_acceptance = 'Y'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND payeemapper.payee_amount &lt;&gt; 0::numeric AND adt.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adt.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1))ORDER BY billmst.admission_id DESC;

-- public.getipdbilldetails_new source
CREATE OR REPLACE VIEW public.getipdbilldetails_newAS SELECT DISTINCT billmst.admission_id,billmst.visit_type_id,billmst.billing_master_id,billmst.patient_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pinf.age,pinf.gender_name,adt.doa,''::text AS pdd,dcs.discharge_desc,dc.discharge_date,pntmst.email,billdtls.created_date,billdtls.gross_amount AS amount,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,pm.prefix_desc,(((((pm.prefix_desc || '.'::text) || pntmst.first_name::text) || ' '::text) || pntmst.middle_name::text) || ' '::text) || pntmst.last_name::text AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || m_doctor_master.first_name::text) || ' '::text) || m_doctor_master.last_name::text AS consultant,spc.speciality_name,docsp.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,t_company_master.company_desc,m_payment_entitlement_master.payment_entitlement_desc,m_tariff_master.tariff_desc,t_patient_sponsor_details.payment_entitlement_id,billdtls.discount AS dtlsdiscount,billdtls.tax_amount,od.order_details_id,COALESCE(t_associated_company_master.associated_company_name, ''::character varying) AS associated_company_name,m_company_contract_master.associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,m_bed_category_master.bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,( SELECT sum(test.self_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_self_payable,( SELECT sum(test.credit_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,((('Dr.'::text || ' '::text) || admdoctor.first_name::text) || ' '::text) || admdoctor.last_name::text AS admdoctor,m_refferel.referral_contact_person,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name AS contract_name_new,( SELECT ods.created_date::date AS created_dateFROM t_order_details odsWHERE billdtls.order_details_id = ods.order_details_idORDER BY ods.created_date DESCLIMIT 1) AS orderdate,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,um.image,advforadmission(am.admission_id::double precision) AS deposit,depositcon.consumed_amountFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = billmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idLEFT JOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON billdtls.ord_doc_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN patient.patientinformation pinf ON pntmst.patient_id = pinf.patient_idLEFT JOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN ( SELECT t_discharge.admission_id,t_discharge.discharge_id,t_discharge.discharge_status_id,t_discharge.discharge_dateFROM adt.t_dischargeORDER BY t_discharge.discharge_id DESCLIMIT 1) dc ON am.admission_id = dc.admission_idLEFT JOIN adt.m_discharge_status_master dcs ON dc.discharge_status_id = dcs.discharge_status_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_category_master ON adt.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1LEFT JOIN t_company_master ON t_company_master.company_id = t_patient_sponsor_details.payee_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN t_associated_company_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON billmst.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idLEFT JOIN doctor.m_doctor_master admdoctor ON am.admitting_doctor_id = admdoctor.doctor_idLEFT JOIN t_referal_details admreff ON am.admission_id = admreff.admission_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idLEFT JOIN t_order_details od ON billdtls.order_details_id = od.order_details_idJOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_idWHERE (billmst.visit_type_id = ANY (ARRAY[2, 3, 4])) AND adt.nursing_acceptance = 'Y'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND payeemapper.payee_amount &lt;&gt; 0::numeric AND adt.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adt.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1))ORDER BY billmst.admission_id DESC;

