tract_master.associate_company_id,am.admission_number,m_billing_bed_category_master.billing_bed_desc,m_bed_category_master.bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0 AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,((('Dr.'::text || ' '::text) || servicedoc.first_name::text) || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0 AS authorization_amount,''::text AS authorization_date,''::text AS authorization_no,''::text AS is_final_submit,0 AS request_amount,''::text AS request_date,''::text AS request_no,( SELECT sum(test.self_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_self_payable,( SELECT sum(test.credit_payable) AS sumFROM billing.t_billing_details testWHERE test.billing_master_id = billmst.billing_master_id) AS total_credit_payable,groupmaster.speciality_name AS groupname,billmst.bill_date_time,billmst.is_interim_or_final_bill,abs(date_part('Year'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pntmst.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,((('Dr.'::text || ' '::text) || admdoctor.first_name::text) || ' '::text) || admdoctor.last_name::text AS admdoctor,m_refferel.referral_name AS referral_contact_person,billdtls.payee_id,0 AS contract_id,getpayeeid(billmst.billing_master_id) AS payeeidnew,billdtls.self_payable AS payee_amount,billdtls.credit_payable AS due_amount,getpayeename(billmst.billing_master_id)::character varying(100) AS payeedescnew,''::text AS contract_name_new,od.created_date::date AS orderdate,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,um.image,bedcatetory.billing_bed_desc AS orderbedcategory,dc.discharge_date AS discharge_date_new,dc.discharge_time AS discharge_time_new,0::double precision AS due_self_amount,0::double precision AS payeebillamount,COALESCE(payment.amount, 0::double precision) AS paidamount,advforadmission(am.admission_id::double precision) AS deposit,COALESCE(depositcon.consumed_amount, 0::double precision) AS consumed_amount,od.package_consumption_amt,payment1.deposite_consumption_id,dc.discharge_status_id,mrfdm.discharge_type_name,mbcm.bed_category_desc AS chargebedcategory,pd.address AS patientaddress,pntmst.mobile_number AS patientmobile,COALESCE(pharmacyservice_id(billmst.billing_master_id), 0) AS pharmacyservice_id,billmst.bill_remark,od.ord_render_datetime,servmst.service_standard_codeFROM billing.m_billing_master billmstJOIN billing.t_billing_details billdtls ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = billmst.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN m_gender_master gender ON pntmst.gender_id = gender.gender_idLEFT JOIN patient.t_patient_details pd ON pntmst.patient_id = pd.patient_idJOIN adt.t_admission am ON am.admission_id = billmst.admission_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idJOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON billdtls.ord_doc_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN adt.t_admission_details adt ON am.admission_id = adt.admission_idLEFT JOIN adt.t_discharge dc ON adt.admission_id = dc.admission_id AND dc.status = 'A'::bpcharLEFT JOIN adt.m_discharge_status_master dcs ON dc.discharge_status_id = dcs.discharge_status_idLEFT JOIN adt.m_reason_for_discharge_master mrfdm ON dc.discharge_type_id = mrfdm.discharge_type_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_category_master ON adt.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN opd.t_patient_sponsor_details ON am.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1LEFT JOIN t_company_master ON t_company_master.company_id = t_patient_sponsor_details.payee_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN t_associated_company_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON billmst.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON billdtls.ord_doc_id = servicedoc.doctor_idLEFT JOIN doctor.m_speciality_master groupmaster ON servmst.speciality_id = groupmaster.speciality_idLEFT JOIN doctor.m_doctor_master admdoctor ON am.admitting_doctor_id = admdoctor.doctor_idLEFT JOIN t_referal_details admreff ON am.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numericLEFT JOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN adt.m_billing_bed_category_master bedcatetory ON od.bed_category_id = bedcatetory.billing_bed_category_idLEFT JOIN adt.m_bed_master mbm ON od.bed_id = mbm.bed_idLEFT JOIN adt.m_bed_category_master mbcm ON mbm.bed_category_id = mbcm.bed_category_idLEFT JOIN billing.t_payment_deposite_consumption depositcon ON billmst.billing_master_id = depositcon.bill_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idLEFT JOIN ( SELECT COALESCE(prm.deposite_consumption_id, 0) AS deposite_consumption_id,prm.billing_master_idFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar AND prm.deposite_consumption_id &lt;&gt; 0) payment1 ON billmst.billing_master_id = payment1.billing_master_idWHERE billmst.visit_type_id &lt;&gt; 1 AND adt.nursing_acceptance = 'Y'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND adt.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adt.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1)) AND od.status = 'A'::bpchar AND billdtls.status = 'A'::"char";

