ncounter_master.dept_id = m_speciality_master.speciality_idWHERE m_billing_master.visit_type_id = 1 AND (m_service_master.service_master_id IN ( SELECT m_doctor_consultation_service_mapper_1.secondary_visit_service_idFROM doctor.m_doctor_consultation_service_mapper m_doctor_consultation_service_mapper_1));
