_id = patientinformation.patient_idLEFT JOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_idLEFT JOIN t_referal_details admreff ON t_encounter_master.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idWHERE m_billing_master.visit_type_id = 1 AND m_billing_master.bill_status_id = 3 AND m_billing_master.bill_cancelled = 'N'::bpchar;

