-- public.getopdconsultatationdoctorwise source
CREATE OR REPLACE VIEW public.getopdconsultatationdoctorwiseAS SELECT DISTINCT m_billing_master.billing_master_id,t_patient_registration.uhid_number,(t_patient_registration.first_name::text || ' '::text) || t_patient_registration.last_name::text AS patientname,t_patient_registration.mobile_number,t_patient_details.address,t_encounter_master.encounter_number,t_encounter_master.encounter_date,m_billing_master.bill_number,m_billing_master.bill_date_time,''::text AS doctorname,''::text AS first_name,''::text AS last_name,m_billing_master.total_bill_amount,m_billing_master.discount_amount,m_billing_master.net_amount,m_service_master.service_standard_name AS new_visit_service,0 AS doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,t_encounter_master.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,patientinformation.age,patientinformation.gender_name,t_encounter_master.encounter_time,0 AS new_visit_service_id,''::text AS speciality_name,0 AS speciality_id,t_encounter_master.user_defined_visit_type_id,t_patient_registration.organization_id,t_billing_details.gross_amount,t_billing_details.discount,t_billing_details.net_amt,m_refferel.referral_name,m_refferel.referral_id,payment.amount AS paidamount,unitinformation.image,payment.amountFROM patient.t_patient_registrationJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idJOIN opd.t_encounter_master ON t_patient_details.patient_id = t_encounter_master.patient_idJOIN billing.m_billing_master ON m_billing_master.encounter_id = t_encounter_master.encounter_idJOIN billing.t_billing_details ON m_billing_master.billing_master_id = t_billing_details.billing_master_idJOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN m_user_master ON m_user_master.user_id = m_billing_master.created_byLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN patient.patientinformation ON t_encounter_master.patient_id = patientinformation.patient_idLEFT JOIN t_referal_details admreff ON t_encounter_master.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN ( SELECT prm.billing_master_id,sum(prd.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.t_payment_reciept_details prd ON prm.payment_reciept_id = prd.payment_receipt_master_idJOIN billing.m_billing_master bm_1 ON prm.billing_master_id = bm_1.billing_master_idGROUP BY prm.billing_master_id) payment ON m_billing_master.billing_master_id = payment.billing_master_idWHERE m_billing_master.visit_type_id = 1 AND m_billing_master.bill_status_id = 3 AND m_billing_master.bill_cancelled = 'N'::bpchar;

