-- public.getpackagedetails source
CREATE OR REPLACE VIEW public.getpackagedetailsAS SELECT DISTINCT billmst.billing_master_id,servmst.service_standard_name,billdtls.service_id,od.order_details_id,packagemapper.package_id,billmst.bill_number,billmst.bill_date_time,servmst.speciality_id,spc.speciality_nameFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN t_order_details_package_mapper packagemapper ON billdtls.order_details_id = packagemapper.order_details_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idWHERE billmst.visit_type_id = 1 AND payeemapper.status = 'A'::bpchar AND od.is_package_service = 'Y'::"char" AND packagemapper.is_package_service = 'Y'::bpchar;

-- public.getpackagedetails_interimbill source
CREATE OR REPLACE VIEW public.getpackagedetails_interimbillAS SELECT DISTINCT ta.admission_id,servmst.service_standard_name,tod.service_id,tod.order_details_id,packagemapper.package_id,ta.admission_number,tod.package_consumption_amtFROM t_order_master omJOIN t_order_details tod ON tod.order_id = om.order_idJOIN adt.t_admission ta ON ta.admission_id = om.admission_idJOIN t_order_details_package_mapper packagemapper ON tod.order_details_id = packagemapper.order_details_idJOIN service.m_service_master servmst ON servmst.service_master_id = tod.service_idJOIN t_order_details_payee_mapper payeemapper ON tod.order_details_id = payeemapper.order_details_idWHERE om.visit_type_id = 2 AND payeemapper.status = 'A'::bpchar AND tod.is_package_service = 'Y'::"char" AND packagemapper.is_package_service = 'Y'::bpchar;

-- public.getpackagedetails_ip source
CREATE OR REPLACE VIEW public.getpackagedetails_ipAS SELECT DISTINCT billmst.billing_master_id,servmst.service_standard_name,billdtls.service_id,billdtls.order_details_id,packagemapper.package_id,billmst.bill_number,billmst.bill_date_time,billdtls.package_id AS bdpacageid,packagemapper.service_amount,billdtls.quantity AS package_qtyFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN t_order_details_package_mapper packagemapper ON packagemapper.order_details_id = billdtls.order_details_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN adt.t_admission adm ON billmst.admission_id = adm.admission_idWHERE billmst.visit_type_id &lt;&gt; 1 AND packagemapper.is_package_service = 'Y'::bpchar AND packagemapper.status = 'A'::bpchar;

-- public.getparametercount source
CREATE OR REPLACE VIEW public.getparametercountAS SELECT DISTINCT om.order_date,labsubdept.sub_speciality_name AS labdepartment,labsubdept.sub_speciality_id,labsampledetails.test_id,testmaster.test_desc,um.unit_id,um.unit_name,um.unit_address,testmaster.test_id AS mastertestid,parametermaster.parameter_id,parametermaster.parameter_name,bm.bill_date_time,bm.bill_status_idFROM lab.t_lab_sample_master samplemasterJOIN lab.t_lab_sample_dtls labsampledetails ON samplemaster.lab_sample_id = labsampledetails.lab_sample_idLEFT JOIN lab.m_test_master testmaster ON labsampledetails.test_id = testmaster.test_idLEFT JOIN lab.t_test_parameter_mppr testmapper ON testmaster.test_id = testmapper.test_id AND testmapper.is_deleted = 'N'::bpcharJOIN lab.m_parameter_master parametermaster ON parametermaster.parameter_id = testmapper.parameter_idLEFT JOIN doctor.m_sub_speciality_master labsubdept ON labsampledetails.sub_dept_id = labsubdept.sub_speciality_idLEFT JOIN unitinformation um ON um.unit_id = samplemaster.org_unit_idLEFT JOIN t_order_master om ON om.order_id = samplemaster.order_idLEFT JOIN t_order_details od ON om.order_id = od.order_idJOIN billing.t_billing_details billdetails ON od.order_details_id = billdetails.order_details_idJOIN billing.m_billing_master bm ON billdetails.billing_master_id = bm.billing_master_id;

-- public.getpatholgyreport source
CREATE OR REPLACE VIEW public.getpatholgyreportAS SELECT DISTINCT ldel.lab_res_dtls_id,lrm.lab_test_res_id,ltm.test_desc,ltm.test_alies,pim.patient_id,pim.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(pim.first_name, ''::character varying), ' ', COALESCE(pim.middle_name, ''::character varying), ' ', COALESCE(pim.last_name, ''::character varying)) AS patientname,age(pim.dob) AS age,gender.gender_name,concat(m_refferel.referral_name) AS doctername,om.order_no,lsdel.sample_collection_datetime,lrm.result_authorised_datetime,CASEWHEN om.admission_id IS NULL THEN em.encounter_numberWHEN om.admission_id IS NOT NULL THEN adm.admission_numberELSE NULL::character varyingEND AS opipdno,lsm.sample_no,lhm.header_code,lhm.header_desc,lhm.header_status,ldel.param_name,ldel.final_result AS result,ldel.parameter_min,ldel.parameter_max AS param_abnrml_max,ldel.param_unit,ldel.result_type_flag,um.unit_id,um.unit_address,um.unit_address_2,um.unit_contact,um.unit_contact_2,um.unit_logo,um.unit_website,om.org_id,utm.user_id,utm.user_name,ldel.textual_range_id,ldel.textual_range_name,ldel.multitextaul_range,ldel.refrange_type_id,labdept.sub_speciality_name AS department_name,lrm.foot_notes,um.unit_name,lrm.lab_sample_dtls_id,ltm.foot_note,date_part('year'::text, age(lsdel.patient_visit_age, pim.dob))::integer AS ageyear,param_textual.remark,pim.gender_id,ldel.parameter_id,seq.para_sequence,ltm.test_id,lrm.sample_status_id,um.image,tm.technique_name,date_part('month'::text, age(lsdel.patient_visit_age, pim.dob))::integer AS months,''::character varying(100) AS age_type_grp_name,param_multitext.remark AS multitextremark,um.unit_email_id,lsdel.dept_id,lsdel.sub_dept_id,em.encounter_id,ldel.remarks AS resultremark,testmaster.param_precision,CASEWHEN adm.admission_id IS NULL THEN concat('Dr.', '', dm.first_name, ' ', dm.last_name)ELSE concat('Dr.', '', dmipd.first_name, ' ', dmipd.last_name)END AS doctor,concat(emp.first_name, ' ', emp.last_name) AS emp,concat('Dr.', '', docsign.first_name, ' ', docsign.last_name) AS docsignname,docsign.doctor_id AS docsignid,lsdel.qr_image,COALESCE(CASEWHEN adm.admission_id IS NULL THEN dm.doctor_idELSE dmipd.doctor_idEND, 0) AS doctor_id,lsdel.updated_date AS created_date,lsdel.sample_accept_datetime,lrm.result_enter_datetime,lrm.result_validated_datetime,sampletype.sample_desc,adm.admission_id,ldel.is_abnormal,COALESCE(m_refferel.referral_id, 0) AS referral_id,mbm.bed_number,m_billing_bed_category_master.billing_bed_desc,lsdel.is_report_recall,lsdel.updated_date,lrm.order_details_id,om.order_date,lhm.headersequence,pim.identification_number,identy.identification_name,lsdel.srf_id,lsdel.icmr_id,mnm.nationality_name,mtm.technique_name AS para_technique,lsdel.internal_notes,CASEWHEN emp.user_id IS NOT NULL THEN concat(emp.first_name, ' ', emp.last_name)ELSE concat('Dr.', entrydoc.first_name, ' ', entrydoc.last_name)END AS entryemp,lrm.result_authorised_by,concat(entrydoc.first_name, ' ', entrydoc.last_name) AS entrydoc,concat('Dr.', '', docsignt.first_name, ' ', docsignt.last_name) AS docsignname1,docsignt.doctor_id AS docsignid1,replace(sm.codification_service_name::text, 'https'::text, 'http'::text)::character varying(1000) AS codification_service_name,date_part('day'::text, age(lsdel.patient_visit_age, pim.dob))::integer AS ageday,date_part('month'::text, age(lsdel.patient_visit_age, pim.dob))::integer AS agemonthFROM lab.t_lab_test_result lrmJOIN lab.t_lab_res_dtls ldel ON lrm.lab_test_res_id = ldel.lab_result_idJOIN lab.m_test_master ltm ON lrm.test_id = ltm.test_idJOIN t_order_details od ON od.order_details_id = lrm.order_details_idJOIN service.m_service_master sm ON sm.service_master_id = od.service_idJOIN lab.t_lab_sample_dtls lsdel ON lrm.lab_sample_dtls_id = lsdel.lab_sample_dtls_idJOIN lab.t_lab_sample_master lsm ON lsdel.lab_sample_id = lsm.lab_sample_idJOIN t_order_master om ON om.order_id = lsdel.order_idLEFT JOIN adt.t_admission adm ON om.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON om.encounter_id = em.encounter_idLEFT JOIN lab.m_header_master lhm ON ldel.header_id = lhm.header_idJOIN patient.t_patient_registration pim ON lsdel.patient_id = pim.patient_idJOIN patient.t_patient_details tpd ON tpd.patient_id = pim.patient_idLEFT JOIN m_prefix_master ON m_prefix_master.prefix_id = pim.prefix_idLEFT JOIN m_gender_master gender ON pim.gender_id = gender.gender_idLEFT JOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_idLEFT JOIN doctor.m_doctor_master dmipd ON adm.doctor_id = dmipd.doctor_idLEFT JOIN t_referal_details admreff ON em.encounter_id = admreff.encounter_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN m_unit_master um ON um.unit_id = lrm.org_unit_idLEFT JOIN m_user_master utm ON lrm.result_validated_by = utm.user_idLEFT JOIN m_user_master utmt ON lrm.result_authorised_by = utmt.user_idLEFT JOIN m_employee_master emp ON utm.user_id = emp.user_idLEFT JOIN doctor.m_doctor_master docsign ON utm.user_id = docsign.user_idLEFT JOIN doctor.m_doctor_master docsignt ON utmt.user_id = docsignt.user_idLEFT JOIN lab.m_param_textual_range param_textual ON ldel.parameter_id = param_textual.parameter_id AND pim.gender_id = param_textual.gender_id AND param_textual.is_deleted = 'N'::bpcharLEFT JOIN doctor.m_sub_speciality_master labdept ON lsdel.sub_dept_id = labdept.sub_speciality_idLEFT JOIN lab.m_technique_master tm ON ltm.technique_id = tm.technique_idJOIN lab.m_parameter_master testmaster ON ldel.parameter_id = testmaster.parameter_idLEFT JOIN lab.m_param_multitextual_range param_multitext ON ldel.parameter_id = param_multitext.parameter_id AND param_multitext.gender_id = pim.gender_id AND param_multitext.is_deleted = 'N'::bpcharJOIN lab.m_sample_master sampletype ON lsdel.sample_type_id = sampletype.sample_idLEFT JOIN adt.t_admission_details admd ON adm.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN adt.m_billing_bed_category_master ON admd.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_master mbm ON mbm.bed_id = admd.bed_idLEFT JOIN lab.t_test_parameter_mppr seq ON ldel.parameter_id = seq.parameter_id AND seq.test_id = ldel.test_id AND seq.is_deleted = 'N'::bpchar AND seq.test_para_status = 'A'::bpchar AND seq.header_id = ldel.header_idLEFT JOIN adt.m_identification_master identy ON pim.identification_type_id = identy.identification_idLEFT JOIN m_nationality_master mnm ON mnm.nationality_id = tpd.nationality_idLEFT JOIN lab.m_technique_master mtm ON mtm.technique_id = testmaster.technique_idLEFT JOIN m_user_master entryuser ON lrm.result_authorised_by = entryuser.user_idLEFT JOIN m_employee_master entryemp ON entryuser.user_id = entryemp.user_idLEFT JOIN doctor.m_doctor_master entrydoc ON entrydoc.user_id = lrm.result_authorised_byWHERE lrm.status = 'A'::bpcharORDER BY ldel.lab_res_dtls_id;

