d,pmm.payment_mode_desc,dd.amount,0::double precision AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_desc,transtype.transaction_type_desc,COALESCE(''::text) AS adm_visit_no,pmm.payment_mode_id,dd.card_no,dd.cheque_number,dd.transaction_no AS trannumberFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_id AND dm.status::text = 'A'::bpchar::textJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dm.encounter_id IS NULL AND dm.admission_id IS NULL AND dm.visit_type_id IS NULL AND dm.status = 'A'::"char"ORDER BY 1;

