_id,pmm.payment_mode_desc,dd.amount,0::double precision AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dd.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dm.deposit_no AS reciptno,countermaster.counter_id,countermaster.counter_desc,transtype.transaction_type_desc,COALESCE(''::text) AS adm_visit_no,pmm.payment_mode_id,dd.card_no,dd.cheque_number,dd.transaction_no AS trannumberFROM billing.t_payment_deposit_details ddJOIN billing.m_deposit_master dm ON dm.deposit_master_id = dd.deposit_id AND dm.status::text = 'A'::bpchar::textJOIN patient.t_patient_registration pr ON pr.patient_id = dm.patient_idJOIN m_payment_mode_master pmm ON dd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON dd.created_by = um.user_idJOIN m_employee_master ON m_employee_master.user_id = um.user_idJOIN m_unit_master umm ON dm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON dm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dm.counter_id = countermaster.counter_idLEFT JOIN billing.m_transaction_type_master transtype ON dd.transaction_type_id = transtype.transaction_type_idWHERE dm.encounter_id IS NULL AND dm.admission_id IS NULL AND dm.visit_type_id IS NULL AND dm.status = 'A'::"char"ORDER BY 1;

-- public.image_allcollectionsummary source
CREATE OR REPLACE VIEW public.image_allcollectionsummaryAS SELECT deposit_master_id,deposit,visit_type_code,CASEWHEN COALESCE(outstanding, 0::double precision) &lt;&gt; 0::double precision THEN 1ELSE visit_type_idEND AS visit_type_id,user_name,user_id,CASEWHEN COALESCE(outstanding, 0::double precision) &lt;&gt; 0::double precision THEN 13ELSE unit_idEND AS unit_id,COALESCE(organization_id, 0) AS organization_id,unit_name,patientname,patient_id,uhid_number,CASEWHEN COALESCE(outstanding, 0::double precision) &lt;&gt; 0::double precision THEN bill_date_timeELSE depositdateEND AS depositdate,unit_address,unit_contact_2,unit_contact,COALESCE(sum(CASEWHEN payment_mode_desc = 'Cash'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS cash,COALESCE(sum(CASEWHEN payment_mode_desc = 'Cheque'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS cheque,COALESCE(sum(CASEWHEN payment_mode_desc = 'Card Payment'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS creditcard,COALESCE(sum(CASEWHEN payment_mode_desc = 'Debit Card'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS debitcard,COALESCE(sum(consumed_amount), 0::double precision) AS patadvused,COALESCE(sum(tdsamt)::double precision, 0::double precision) AS tdsamt,amttype,reciptno,COALESCE(counter_id, 0) AS counter_id,counter_desc,COALESCE(sum(CASEWHEN payment_mode_desc = 'Mpesa'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS mpesa,COALESCE(sum(CASEWHEN payment_mode_desc = 'Loyalty Card'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS loyaltycard,COALESCE(sum(CASEWHEN payment_mode_desc = 'E-Transfer'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS e_transfer,COALESCE(sum(CASEWHEN payment_mode_desc = 'Available Fund'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS availablefund,COALESCE(sum(CASEWHEN payment_mode_desc = 'Doctor Credit'::text THEN amountELSE NULL::double precisionEND), 0::double precision) AS doctorcredit,total_bill_amount,discount_amount,net_amount,outstanding,paidamount,transaction_type_desc,bill_date_time,referral_nameFROM image_opdipdcollectionsummaryWHERE unit_id = ANY (ARRAY[13])GROUP BY deposit_master_id, deposit, visit_type_code, user_name, user_id, unit_id, organization_id, unit_name, patientname, patient_id, uhid_number, depositdate, unit_address, unit_contact_2, unit_contact, amttype, reciptno, visit_type_id, counter_id, counter_desc, total_bill_amount, discount_amount, net_amount, outstanding, paidamount, transaction_type_desc, bill_date_time, referral_name;

