CREATE OR REPLACE VIEW public.image_getbilldetails_newAS SELECT DISTINCT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,um.unit_name AS organization_name,um.unit_address AS organization_address,um.unit_contact::text AS organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,COALESCE(billdtls.concession, 0::double precision) AS concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,''::character varying(200) AS unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,''::text AS registration_number,um.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,encmst.encounter_number,encmst.unit_token_number,''::character varying(100) AS name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,COALESCE(billdtls.discount, 0::double precision) AS dtlsdiscount,doctorm.doctor_id,''::text AS doctorname,''::character varying(100) AS docgender,''::character varying(200) AS doctor_category_description,''::character varying(100) AS docspeciality,'00:00:00'::interval AS docage,'2021-01-01 00:00:00'::timestamp without time zone AS docdob,''::character varying AS country_calling_code,''::character varying AS docmobile,''::character varying(200) AS docemail,''::text AS doctor_image,''::text AS docreg,0 AS slot_time_span,0::double precision AS doctor_episod_time_span,billmst.encounter_id,0 AS speciality_id,billmst.bill_date_time,companynew.company_desc,billdtls.payee_id,0 AS contract_id,0 AS payeeidnew,(od.self_payable + od.credit_payable)::numeric(10,2) AS payee_amount,0::numeric(10,2) AS due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name,billdtls.order_details_id,billmst.bill_cancel_remark,od.is_package_service,od.package_id,od.is_package,''::character varying(200) AS bill_status_desc,billdtls.package_consumption_amt,servmst.service_master_id,mrm.referral_name,COALESCE(billmst.net_amount - billmst.outstanding, 0::double precision) AS paidamount,pntmst.mobile_number,gender.gender_name,abs(date_part('Year'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,um.image,abs(date_part('Month'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,((('Dr. '::text || ''::text) || doctorm1.first_name::text) || ' '::text) || doctorm1.last_name::text AS orderdocname,billmst.bill_remark,0 AS referral_id,qm.qualification_desc,t_patient_sponsor_details.employee_name::character varying(250) AS empname,( SELECT ustm.service_codeFROM service.m_unit_service_tariff_master ustmWHERE ustm.visit_type_id = 1 AND ustm.status = 'A'::bpchar AND ustm.service_id = servmst.service_master_id AND ustm.tariff_id = t_patient_sponsor_details.tariff_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharORDER BY ustm.unit_service_tariff_id DESCLIMIT 1) AS service_standard_code,t_patient_sponsor_details.tariff_id,od.bed_category_id,abs(date_part('Day'::text, age(to_char(pntmst.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenby,billdtls.billing_details_id,CASEWHEN t_patient_sponsor_details.payment_entitlement_id = 1 THEN encmst.encounter_date::date + 5ELSE encmst.encounter_date::date + 7END AS nextvisitdate,COALESCE(encmst.user_defined_visit_type_id, 0) AS user_defined_visit_type_id,sspc.sub_speciality_name,pd.address,((('Dr. '::text || ''::text) || dd.first_name::text) || ' '::text) || dd.last_name::text AS preferdocnameFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idJOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idJOIN doctor.m_sub_speciality_master sspc ON sspc.sub_speciality_id = servmst.sub_speciality_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idJOIN m_gender_master gender ON pntmst.gender_id = gender.gender_idJOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN patient.t_patient_details pd ON pd.patient_id = pntmst.patient_id AND pd.status = 'A'::bpcharLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idJOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN m_unit_master um ON billmst.unit_id = um.unit_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idLEFT JOIN m_qualification_master qm ON doctorm.qualification_id = qm.qualification_idLEFT JOIN billing.t_bill_payee_details bpd ON bpd.bill_id = billmst.billing_master_id AND bpd.priority_id = 1 AND bpd.status = 'A'::"char"LEFT JOIN t_company_master companynew ON bpd.payee_id = companynew.company_idLEFT JOIN opd.t_patient_sponsor_details ON encmst.encounter_id = t_patient_sponsor_details.encounter_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN service.m_company_contract_master contractmaster ON t_patient_sponsor_details.contract_id = contractmaster.contract_idJOIN t_order_details od ON billdtls.order_details_id = od.order_details_id AND od.ord_cancelled = 'N'::bpcharLEFT JOIN t_referal_details reffdel ON reffdel.encounter_id = encmst.encounter_id AND reffdel.status = 'A'::bpcharLEFT JOIN adt.m_referral_master mrm ON mrm.referral_id = reffdel.referral_idLEFT JOIN doctor.m_doctor_master doctorm1 ON billdtls.ord_doc_id = doctorm1.doctor_idLEFT JOIN doctor.m_doctor_master dd ON encmst.preferred_doc_id = dd.doctor_idWHERE billmst.visit_type_id = 1ORDER BY billmst.billing_master_id DESC;

