CREATE OR REPLACE VIEW public.image_getbilldetails_new_1AS SELECT DISTINCT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,COALESCE(billmst.discount_amount, 0::double precision) AS discount_amount,COALESCE(billmst.concession_amount, 0::double precision) AS concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,COALESCE(billdtls.concession, 0::double precision) AS concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,encmst.encounter_number,encmst.unit_token_number,m_tax.name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,COALESCE(billdtls.discount, 0::double precision) AS dtlsdiscount,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.encounter_id,doctorinformation.speciality_id,billmst.bill_date_time,company.company_desc,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name,billdtls.order_details_id,billmst.bill_cancel_remark,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,billdtls.package_consumption_amt,servmst.service_master_id,m_refferel.referral_name,payment.amount AS paidamount,pntmst.mobile_number,pim.gender_name,pim.ageyear,um.image,pim.agemonth,((('Dr. '::text || ''::text) || doctorm1.first_name::text) || ' '::text) || doctorm1.last_name::text AS orderdocname,billmst.bill_remark,CASEWHEN m_refferel.referral_id IS NULL THEN 0ELSE m_refferel.referral_idEND AS referral_id,qm.qualification_desc,t_patient_sponsor_details.employee_name::character varying(250) AS empname,''::text AS service_standard_code,t_patient_sponsor_details.tariff_id,od.bed_category_id,pim.ageday,billmst.print_given_by,(empprint.first_name::text || ' '::text) || empprint.last_name::text AS printgivenbyFROM billing.t_billing_details billdtlsJOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idJOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idLEFT JOIN m_general_ledger_master genledmst ON genledmst.general_ledger_id = spc.general_ledger_idJOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idJOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idJOIN patientinformation pim ON encmst.patient_id = pim.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idJOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idJOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_user_master umprint ON billmst.print_given_by = umprint.user_idLEFT JOIN m_employee_master empprint ON umprint.user_id = empprint.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idJOIN unitinformation um ON billmst.unit_id = um.unit_idLEFT JOIN m_tax ON billdtls.tax_id = m_tax.idLEFT JOIN doctor.doctorinformation ON billmst.encounter_id = doctorinformation.encounter_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idLEFT JOIN m_qualification_master qm ON doctorm.qualification_id = qm.qualification_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idLEFT JOIN opd.t_patient_sponsor_details ON encmst.encounter_id = t_patient_sponsor_details.encounter_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharJOIN t_order_details od ON billdtls.order_details_id = od.order_details_idLEFT JOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN t_referal_details admreff ON encmst.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN doctor.m_doctor_master doctorm1 ON billdtls.ord_doc_id = doctorm1.doctor_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idWHERE billmst.visit_type_id = 1;

-- public.image_groupwiserevenucount source
CREATE OR REPLACE VIEW public.image_groupwiserevenucountAS SELECT DISTINCT bm.bill_date_time::date AS bill_date_time,sp.speciality_id,sp.speciality_name,ssp.sub_speciality_id,ssp.sub_speciality_name,bd.net_amt,bm.patient_id,um.unit_id,bm.bill_cancelled,row_number() OVER (ORDER BY (bm.bill_date_time::date)) AS serialno,um.unit_name,um.unit_address,bm.organisation_id,bd.billing_details_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_idJOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_idJOIN unitinformation um ON bm.unit_id = um.unit_idWHERE bd.gross_amount &lt;&gt; 0::double precision AND bm.bill_cancelled = 'N'::bpchar;

