mary.depositdate,image_opipdbillsummary.patientname,image_opipdbillsummary.patient_id,image_opipdbillsummary.uhid_number,image_opipdbillsummary.amttype,image_opipdbillsummary.reciept_number AS reciptno,image_opipdbillsummary.counter_id,image_opipdbillsummary.counter_desc,image_opipdbillsummary.total_bill_amount,image_opipdbillsummary.discount_amount,image_opipdbillsummary.net_amount,image_opipdbillsummary.outstanding,image_opipdbillsummary.amount AS paidamount,image_opipdbillsummary.transaction_type_desc,image_opipdbillsummary.bill_date_time,image_opipdbillsummary.referral_name,image_opipdbillsummary.adm_visit_no,image_opipdbillsummary.payment_mode_id,image_opipdbillsummary.card_no,image_opipdbillsummary.patient_source_id,image_opipdbillsummary.patient_source_name,image_opipdbillsummary.check_number AS cheque_number,image_opipdbillsummary.bill_number,image_opipdbillsummary.trannumberFROM image_opipdbillsummaryUNION ALLSELECT image_opipdadvancerefund.id AS deposit_master_id,image_opipdadvancerefund.deposit,image_opipdadvancerefund.visit_type_code,image_opipdadvancerefund.visit_type_id,image_opipdadvancerefund.payment_mode_desc,image_opipdadvancerefund.amount,image_opipdadvancerefund.consumed_amount,image_opipdadvancerefund.tdsamt,image_opipdadvancerefund.user_name,image_opipdadvancerefund.user_id,image_opipdadvancerefund.unit_id,image_opipdadvancerefund.organization_id,image_opipdadvancerefund.unit_name,image_opipdadvancerefund.unit_address,image_opipdadvancerefund.unit_contact,image_opipdadvancerefund.unit_contact_2,image_opipdadvancerefund.depositdate,image_opipdadvancerefund.patientname,image_opipdadvancerefund.patient_id,image_opipdadvancerefund.uhid_number,image_opipdadvancerefund.amttype,image_opipdadvancerefund.reciptno,image_opipdadvancerefund.counter_id,image_opipdadvancerefund.counter_desc,0 AS total_bill_amount,0 AS discount_amount,0 AS net_amount,0 AS outstanding,0 AS paidamount,''::text AS transaction_type_desc,image_opipdadvancerefund.depositdate AS bill_date_time,''::character varying AS referral_name,image_opipdadvancerefund.adm_visit_no,image_opipdadvancerefund.payment_mode_id,image_opipdadvancerefund.card_no,0 AS patient_source_id,''::character varying AS patient_source_name,image_opipdadvancerefund.cheque_number,''::character varying AS bill_number,''::text AS trannumberFROM image_opipdadvancerefundUNION ALLSELECT DISTINCT me.expense_id AS deposit_master_id,CASEWHEN me.bill_type = 1 THEN 'Mis.Income'::textWHEN me.bill_type = 2 THEN 'Expenses'::textELSE NULL::textEND AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,paymode.payment_mode_desc,CASEWHEN me.bill_type = 1 THEN er.amountWHEN me.bill_type = 2 THEN er.amountELSE NULL::double precisionEND AS amount,0 AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,usermaster.user_id,um.unit_id,me.org_id AS organization_id,um.unit_name,um.unit_address,um.unit_contact,'-'::text AS unit_contact_2,er.date_of_reciept AS depositdate,me.name AS patientname,0 AS patient_id,'-'::character varying AS uhid_number,CASEWHEN me.bill_type = 1 THEN 'Mis.Income'::textWHEN me.bill_type = 2 THEN 'Expenses'::textELSE NULL::textEND AS amttype,me.expense_id::character varying AS reciptno,0 AS counter_id,''::character varying(50) AS counter_desc,me.amount AS total_bill_amount,0 AS discount_amount,me.amount AS net_amount,0 AS outstanding,0 AS paidamount,''::text AS transaction_type_desc,er.date_of_reciept AS bill_date_time,''::character varying AS referral_name,''::text AS adm_visit_no,0 AS payment_mode_id,erd.card_number AS card_no,0 AS patient_source_id,''::text AS patient_source_name,''::text AS cheque_number,''::text AS bill_number,''::text AS trannumberFROM billing.t_miscellaneous_expense meJOIN billing.t_miscellaneous_expense_reciept er ON me.expense_id = er.expense_idJOIN billing.t_miscellaneous_expense_reciept_details erd ON er.expense_reciept_id = erd.expense_reciept_i