-- public.image_opipdbillsummary source
CREATE OR REPLACE VIEW public.image_opipdbillsummaryAS SELECT DISTINCT bm.billing_master_id,vm.visit_type_code::text || 'D Bill'::text AS deposit,vm.visit_type_code,vm.visit_type_id,pmm.payment_mode_desc,prd.amount,dd.consumed_amount,0 AS tdsamt,CASEWHEN um.user_id IS NULL THEN concat(emp.first_name, ' ', emp.last_name)::character varying(100)ELSE concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100)END AS user_name,CASEWHEN um.user_id IS NULL THEN emp.user_idELSE m_employee_master.user_idEND AS user_id,bm.unit_id,bm.organisation_id AS organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,prd.date_of_transaction AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,rm.reciept_number,countermaster.counter_id,countermaster.counter_desc,bm.total_bill_amount,bm.discount_amount,bm.net_amount,bm.outstanding,bm.net_amount - bm.outstanding AS paidamount,trantype.transaction_type_desc,bm.bill_date_time,''::character varying(255) AS referral_name,COALESCE(adm.admission_number, enc.encounter_number, ''::character varying) AS adm_visit_no,prd.payment_reciept_details_id,pmm.payment_mode_id,prd.card_number AS card_no,sm.patient_source_id,sm.patient_source_name,prd.check_number,bm.bill_number,prd.transaction_no AS trannumberFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idLEFT JOIN billing.t_payment_reciept_master rm ON bm.billing_master_id = rm.billing_master_idLEFT JOIN billing.t_payment_reciept_details prd ON rm.payment_reciept_id = prd.payment_receipt_master_idLEFT JOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idLEFT JOIN billing.m_transaction_type_master trantype ON trantype.transaction_type_id = prd.transaction_type_idJOIN m_user_master mum ON mum.user_id = bm.created_byJOIN m_employee_master emp ON emp.user_id = mum.user_idLEFT JOIN m_user_master um ON rm.created_by = um.user_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idLEFT JOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON rm.counter_id = countermaster.counter_idLEFT JOIN adt.t_admission adm ON adm.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master enc ON enc.encounter_id = bm.encounter_idLEFT JOIN adt.m_patient_source_master sm ON enc.source_id = sm.patient_source_idLEFT JOIN ( SELECT sum(prdd.amount) AS consumed_amount,rmm.billing_master_idFROM billing.t_payment_reciept_master rmmJOIN billing.t_payment_reciept_details prdd ON rmm.payment_reciept_id = prdd.payment_receipt_master_idWHERE prdd.payment_mode_id = 10GROUP BY rmm.billing_master_id) dd ON dd.billing_master_id = rm.billing_master_idWHERE COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar AND COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar AND (bm.bill_status_id = ANY (ARRAY[2, 3])) AND prd.amount &gt;= 1::double precision;

