payment_mode_idLEFT JOIN billing.m_transaction_type_master trantype ON trantype.transaction_type_id = prd.transaction_type_idJOIN m_user_master mum ON mum.user_id = bm.created_byJOIN m_employee_master emp ON emp.user_id = mum.user_idLEFT JOIN m_user_master um ON rm.created_by = um.user_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idLEFT JOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON rm.counter_id = countermaster.counter_idLEFT JOIN adt.t_admission adm ON adm.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master enc ON enc.encounter_id = bm.encounter_idLEFT JOIN adt.m_patient_source_master sm ON enc.source_id = sm.patient_source_idLEFT JOIN ( SELECT sum(prdd.amount) AS consumed_amount,rmm.billing_master_idFROM billing.t_payment_reciept_master rmmJOIN billing.t_payment_reciept_details prdd ON rmm.payment_reciept_id = prdd.payment_receipt_master_idWHERE prdd.payment_mode_id = 10GROUP BY rmm.billing_master_id) dd ON dd.billing_master_id = rm.billing_master_idWHERE COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar AND COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar AND (bm.bill_status_id = ANY (ARRAY[2, 3])) AND prd.amount &gt;= 1::double precision;

