CREATE OR REPLACE VIEW public.image_radiologyreportAS SELECT DISTINCT template.template_transaction_id,template.created_date,template.created_by,template.encounter_id,template.patient_id,template.template_object,tpr.uhid_number,concat(prefix.prefix_desc, '', tpr.first_name, ' ', tpr.middle_name, ' ', tpr.last_name) AS patientname,gm.gender_name,age(tpr.dob) AS age,m_unit_master.unit_id,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_website,m_refferel.referral_name AS doctorname,doctormaster.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,servicemaster.service_standard_name,m_user_master.user_name,abs(date_part('Year'::text, age(to_char(tpr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,doctormaster.signture_img,concat('Dr.', doctormaster.first_name, ' ', doctormaster.last_name) AS orderdoctor,m_unit_master.image,ordermaster.order_no,concat(tempdoc.first_name, ' ', tempdoc.last_name) AS tempdoctor,tempdoc.doctor_id AS template_doctor_id,replace(tempdoc.signture_img, 'https'::text, 'http'::text) AS signture_img_new,qualification.qualification_desc,designation.employee_designation_description,tempdoc.registration_number,m_unit_master.unit_email_id,m_unit_master.unit_contact,abs(date_part('Month'::text, age(to_char(tpr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(to_char(tpr.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,dg.degree_desc,CASEWHEN ordermaster.visit_type_id = 1 THEN em.encounter_numberELSE adm.admission_numberEND AS opipno,adm.bed_desc,template.is_provisional_release,qualifdoctor.qualification_desc AS order_docqualification,dmg.degree_desc AS order_docdegreeFROM t_template_transaction templateJOIN patient.t_patient_registration tpr ON template.patient_id = tpr.patient_idJOIN m_prefix_master prefix ON prefix.prefix_id = tpr.prefix_idJOIN m_gender_master gm ON gm.gender_id = tpr.gender_idLEFT JOIN m_unit_master ON template.unit_id = m_unit_master.unit_idJOIN m_user_master ON m_user_master.user_id = template.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN t_order_details orderdetail ON template.order_details_id = orderdetail.order_details_idJOIN t_order_master ordermaster ON orderdetail.order_id = ordermaster.order_idLEFT JOIN doctor.m_doctor_master doctormaster ON orderdetail.ord_doc_id = doctormaster.doctor_idJOIN service.m_service_master servicemaster ON orderdetail.service_id = servicemaster.service_master_idLEFT JOIN t_referal_details admreff ON ordermaster.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN doctor.m_doctor_master tempdoc ON template.template_doctor_id = tempdoc.doctor_idLEFT JOIN m_degree_master dg ON dg.degree_id = tempdoc.degree_idLEFT JOIN doctor.t_doctor_doc_mapper qualification ON tempdoc.doctor_id = qualification.doctor_id AND qualification.status = 'A'::bpcharLEFT JOIN m_employee_designation designation ON designation.employee_designation_id = tempdoc.doc_designation_idLEFT JOIN m_patient_visit_metadata em ON em.encouter_id = ordermaster.encounter_idLEFT JOIN m_patient_visit_metadata adm ON adm.admission_id = ordermaster.admission_idLEFT JOIN doctor.t_doctor_doc_mapper qualifdoctor ON orderdetail.ord_doc_id = qualifdoctor.doctor_id AND qualifdoctor.status = 'A'::bpcharLEFT JOIN m_degree_master dmg ON dmg.degree_id = doctormaster.degree_id;

