r.docreg,doctormaster.slot_time_span,doctormaster.doctor_episod_time_span,doctormaster.speciality_id,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,m_organization_master.organization_address,m_organization_master.organization_contact,m_organization_master.organization_email_id,m_organization_master.organization_logo,m_organization_master.organization_desc,orderdetails.ord_cancelled,COALESCE(t_company_master.company_desc, ''::character varying) AS company_desc,COALESCE(m_payment_entitlement_master.payment_entitlement_desc, ''::text) AS payment_entitlement_desc,COALESCE(m_tariff_master.tariff_desc, ''::character varying) AS tariff_desc,COALESCE(t_patient_sponsor_details.payment_entitlement_id, 0) AS payment_entitlement_id,adm.admission_number,adt.doa,m_billing_bed_category_master.billing_bed_desc,m_bed_category_master.bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,t_associated_company_master.associated_company_name,m_company_contract_master.associate_company_id,''::text AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,(servicedoc.first_name::text || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,m_preauth_request_master.authorization_amount,m_preauth_request_master.authorization_date,m_preauth_request_master.authorization_no,m_preauth_request_master.is_final_submit,m_preauth_request_master.request_amount,m_preauth_request_master.request_date,m_preauth_request_master.request_no,credit.self_payable AS total_self_payable,credit.credit_payable AS total_credit_payable,0 AS sum_self_payable,0::numeric AS sum_credit_payable,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,COALESCE(m_refferel.referral_contact_person, '-'::character varying) AS referral_contact_person,unitinformation.image,advforadmission(adm.admission_id::double precision) AS deposit,0 AS depositamt,COALESCE(( SELECT sum(m_deposit_master.available_deposit) AS depFROM billing.m_deposit_masterWHERE m_deposit_master.patient_id = adm.patient_id), 0::double precision) AS depo,od.order_date AS odorderdate,m_sub_speciality_master.sub_speciality_id,m_sub_speciality_master.sub_speciality_name,orderdetails.is_package,orderdetails.package_id,orderdetails.package_consumption_amt,orderdetails.is_package_service,orderdetails.ord_render_datetimeFROM billing.t_intrim_bill_details orderdetailsJOIN billing.t_intrim_bill ordermaster ON orderdetails.intrim_bill_id = ordermaster.intrim_bill_idJOIN adt.t_admission adm ON adm.admission_id = ordermaster.admission_idLEFT JOIN adt.t_admission_details adt ON adm.admission_id = adt.admission_idJOIN patient.patientinformation patreg ON patreg.patient_id = adm.patient_idLEFT JOIN m_prefix_master prefix ON patreg.prefix_id = prefix.prefix_idJOIN service.m_service_master servicemaster ON orderdetails.service_id = servicemaster.service_master_idLEFT JOIN service.t_unit_service_master_details unitservic5_ ON servicemaster.service_master_id = unitservic5_.service_master_idLEFT JOIN doctor.doctorinformationipd doctormaster ON adm.admission_id = doctormaster.admission_idLEFT JOIN unitinformation ON adm.unit_id = unitinformation.unit_idLEFT JOIN m_organization_master ON adm.organization_id = m_organization_master.organization_idLEFT JOIN doctor.m_speciality_master ON servicemaster.speciality_id = m_speciality_master.speciality_idLEFT JOIN doctor.m_sub_speciality_master ON servicemaster.sub_speciality_id = m_sub_speciality_master.sub_speciality_idLEFT JOIN opd.t_patient_sponsor_details ON ordermaster.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master ON t_company_master.company_id = t_patient_sponsor_details.payee_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idLEFT JOIN adt.m_bed_category_master ON adt.bed_category_id = m_bed_category_master.bed_category_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN t_associated_company_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON ordermaster.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON orderdetails.ord_doc_id = servicedoc.doctor_idJOIN patient.t_patient_registration pr ON pr.patient_id = adm.patient_idLEFT JOIN t_referal_details admreff ON adm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN t_order_details od ON orderdetails.order_details_id = od.order_details_id AND od.status = 'A'::bpchar AND od.package_consumption_amt = 0::numericLEFT JOIN ( SELECT sum(od_1.self_payable) AS self_payable,sum(od_1.credit_payable) AS credit_payable,om.admission_idFROM t_order_details od_1JOIN t_order_master om ON om.order_id = od_1.order_idGROUP BY om.admission_id) credit ON credit.admission_id = ordermaster.admission_idWHERE orderdetails.service_is_billed = 0 AND orderdetails.ord_cancelled = 'N'::bpchar AND adt.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.status = 'A'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = adm.admission_id))ORDER BY ordermaster.admission_id;

