ompany_master ON m_company_contract_master.associate_company_id = t_associated_company_master.associated_company_master_idLEFT JOIN billing.m_preauth_request_master ON ordermaster.admission_id = m_preauth_request_master.admission_idLEFT JOIN doctor.m_doctor_master servicedoc ON orderdetails.ord_doc_id = servicedoc.doctor_idJOIN patient.t_patient_registration pr ON pr.patient_id = adm.patient_idJOIN m_gender_master mgm ON pr.gender_id = mgm.gender_idLEFT JOIN m_prefix_master prefix ON pr.prefix_id = prefix.prefix_idLEFT JOIN t_referal_details admreff ON adm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN t_order_details od ON orderdetails.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numericLEFT JOIN billing.t_package_consumption_master pcm ON pcm.admission_id = ordermaster.admission_id AND orderdetails.package_id = pcm.package_id AND pcm.status = 'A'::"char"LEFT JOIN ( SELECT sum(tibd.self_payable) AS self_payable,sum(tibd.credit_payable) AS credit_payable,tibd.intrim_bill_idFROM billing.t_intrim_bill_details tibdGROUP BY tibd.intrim_bill_id) credit ON credit.intrim_bill_id = ordermaster.intrim_bill_idWHERE orderdetails.service_is_billed = 0 AND orderdetails.ord_cancelled = 'N'::bpchar AND adt.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.status = 'A'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = adm.admission_id));
-- public.ipdintrimbiil_4 source
CREATE OR REPLACE VIEW public.ipdintrimbiil_4AS SELECT DISTINCT ordermaster.admission_id AS orderdadmission_id,orderdetails.created_date,orderdetails.order_details_id,orderdetails.service_id,pr.uhid_number,concat(((prefix.prefix_desc || pr.first_name::text) || pr.middle_name::text) || pr.last_name::text) AS patientname,mgm.gender_name,age(pr.dob::date::timestamp with time zone) AS age,pr.mobile_number,pr.email,pr.identification_number,ordermaster.intrim_bill_no AS order_no,orderdetails.order_qty,servicemaster.service_standard_name,( SELECT ustm_1.service_codeFROM service.m_unit_service_tariff_master ustm_1WHERE ustm_1.visit_type_id = 2 AND ustm_1.status = 'A'::bpchar AND ustm_1.service_id = servicemaster.service_master_id AND ustm_1.tariff_id = t_patient_sponsor_details.tariff_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharORDER BY ustm_1.unit_service_tariff_id DESCLIMIT 1) AS service_standard_code,orderdetails.order_date,orderdetails.order_sch_date,orderdetails.service_amt,orderdetails.ord_concession,orderdetails.ord_discount,orderdetails.net_amount,0 AS tax_id,0::numeric AS tax_per,0::numeric(15,2) AS tax_amount,0::numeric AS self_payable,0::numeric AS credit_payable,0 AS service_rendered,0 AS service_chargeable,0 AS discount_value,ordermaster.admission_id,0 AS doctor_id,pntmst.doctorname,''::character varying(100) AS docgender,''::character varying(200) AS doctor_category_description,''::character varying(100) AS docspeciality,m_speciality_master.speciality_name AS groupname,0 AS docage,''::text AS docdob,0 AS country_calling_code,0 AS docmobile,''::text AS docemail,''::text AS doctor_image,0 AS docreg,''::text AS slot_time_span,''::text AS doctor_episod_time_span,0 AS speciality_id,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,''::character varying(100) AS currency_name,''::text AS sub_currency,unitinformation.unit_address AS organization_address,unitinformation.unit_contact::text AS organization_contact,unitinformation.unit_email_id AS organization_email_id,unitinformation.unit_logo AS organization_logo,unitinformation.unit_name::character varying(255) AS organization_desc,orderdetails.ord_cancelled,COALESCE(t_company_master.company_desc, ''::character varying) AS company_desc,COALESCE(m_payment_entitlement_master.payment_entitlement_desc, ''::text) AS payment_entitlement_desc,COALESCE(m_tariff_master.tariff_desc, ''::character varying) AS tariff_desc,COALESCE(t_patient_sponsor_details.payment_entitlement_id, 0) AS payment_entitlement_id,adm.admission_number,adt.doa,CASEWHEN bed.is_virtual = 'Y'::bpchar THEN m_billing_bed_category_master.billing_bed_descELSE pntmst.billing_bed_descEND AS billing_bed_desc,CASEWHEN bed.is_virtual = 'Y'::bpchar THEN bed.bed_descELSE pntmst.billing_bed_descEND AS bed_category_desc,COALESCE(t_patient_sponsor_details.insurance_number, ''::character varying) AS insurance_number,''::text AS contract_name,''::character varying(200) AS associated_company_name,0 AS associate_company_id,''::text AS deposit_no,''::text AS deposit_date,0 AS encounter_deposite,''::text AS deposite_type_desc,(servicedoc.first_name::text || ' '::text) || servicedoc.last_name::text AS servicedocname,t_patient_sponsor_details.insured_amount,0::double precision AS authorization_amount,''::text AS authorization_date,''::character varying(100) AS authorization_no,0::character(1) AS is_final_submit,0::double precision AS request_amount,''::text AS request_date,''::character varying(50) AS request_no,0::numeric AS total_self_payable,0::numeric AS total_credit_payable,0 AS sum_self_payable,0::numeric AS sum_credit_payable,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,COALESCE(m_refferel.referral_contact_person, '-'::character varying) AS referral_contact_person,unitinformation.image,0::double precision AS deposit,0 AS depositamt,COALESCE(( SELECT sum(m_deposit_master.available_deposit) AS depFROM billing.m_deposit_masterWHERE m_deposit_master.admission_id = adm.admission_id), 0::double precision) AS depo,od.order_date AS odorderdate,0 AS sub_speciality_id,''::character varying(100) AS sub_speciality_name,orderdetails.is_package,orderdetails.package_id,orderdetails.package_consumption_amt,orderdetails.is_package_service,CASEWHEN orderdetails.package_id &lt;&gt; 0 THEN pcm.package_applicable_dateELSE orderdetails.ord_render_datetimeEND AS ord_render_datetime,m_speciality_master.speciality_code AS srno,servicemaster.service_master_id,ordermaster.intrim_bill_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,( SELECT rm.relation_nameFROM m_kin_details kidJOIN m_relation_master rm ON kid.relation_id = rm.relation_id AND kid.patient_id = ordermaster.patient_idLIMIT 1) AS relation_name,( SELECT kid.kin_nameFROM m_kin_details kidWHERE kid.patient_id = ordermaster.patient_idLIMIT 1) AS kinname,pntmst.employee_no_manual,docsp.speciality_name AS dept,pr.patient_idFROM billing.t_intrim_bill_details orderdetailsJOIN billing.t_intrim_bill ordermaster ON orderdetails.intrim_bill_id = ordermaster.intrim_bill_idJOIN adt.t_admission adm ON adm.admission_id = ordermaster.admission_idLEFT JOIN doctor.m_speciality_master docsp ON adm.speciality_id = docsp.speciality_idJOIN adt.t_admission_details adt ON adm.admission_id = adt.admission_idJOIN m_patient_visit_metadata pntmst ON pntmst.admission_id = ordermaster.admission_idJOIN m_user_master ON ordermaster.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idJOIN service.m_service_master servicemaster ON orderdetails.service_id = servicemaster.service_master_idLEFT JOIN service.t_unit_service_master_details unitservic5_ ON servicemaster.service_master_id = unitservic5_.service_master_idJOIN m_unit_master unitinformation ON adm.unit_id = unitinformation.unit_idLEFT JOIN doctor.m_speciality_master ON servicemaster.speciality_id = m_speciality_master.speciality_idJOIN opd.t_patient_sponsor_details ON ordermaster.admission_id = t_patient_sponsor_details.admission_id AND t_patient_sponsor_details.priority_id = 1 AND t_patient_sponsor_details.status = 'A'::bpcharLEFT JOIN t_company_master ON t_company_master.company_id = t_patient_sponsor_details.payee_idLEFT JOIN m_payment_entitlement_master ON t_patient_sponsor_details.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN service.m_tariff_master ON t_patient_sponsor_details.tariff_id = m_tariff_master.tariff_idLEFT JOIN adt.m_billing_bed_category_master ON adt.billing_bed_category_id = m_billing_bed_category_master.billing_bed_category_idJOIN adt.m_bed_master bed ON bed.bed_id = adt.bed_idLEFT JOIN service.m_company_contract_master ON t_patient_sponsor_details.contract_id = m_company_contract_master.contract_idLEFT JOIN doctor.m_doctor_master servicedoc ON orderdetails.ord_doc_id = servicedoc.doctor_idJOIN patient.t_patient_registration pr ON pr.patient_id = adm.patient_idJOIN m_gender_master mgm ON pr.gender_id = mgm.gender_idJOIN m_prefix_master prefix ON pr.prefix_id = prefix.prefix_idLEFT JOIN t_referal_details admreff ON adm.admission_id = admreff.admission_id AND admreff.status = 'A'::bpcharLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN t_order_details od ON orderdetails.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numericLEFT JOIN billing.t_package_consumption_master pcm ON pcm.admission_id = ordermaster.admission_id AND orderdetails.package_id = pcm.package_id AND pcm.status = 'A'::"char"WHERE orderdetails.service_is_billed = 0 AND orderdetails.ord_cancelled = 'N'::bpchar AND adt.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.status = 'A'::bpchar AND t_patient_sponsor_details.status = 'A'::bpchar AND ordermaster.order_status = 'A'::bpchar AND adt.admission_details_id = (( SELECT max(t_admission_details_1.admission_details_id) AS maxFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = adm.admission_id));
-- public.item_master source
CREATE OR REPLACE VIEW public.item_masterAS SELECT i.id AS item_id,i.organization_id,pc.category AS product_category,mft.type AS formulation_type,i.code,i.product_code,i.name AS brand_name,mg.name AS generic_name,i.strength,msu.unit,mpc.classification AS pharmacological_classification,mm.name AS manufacturer,t1.name AS p_tax,t2.name AS s_tax,i.hsn_code,msu2.name AS storage_unit,i.is_reusable,i.is_vaccin,i.is_combination,i.is_batch_required,i.is_high_risk_product,i.is_psychotropic,i.is_kit,i.is_infusion,i.is_narcotic,i.is_hospital_formulary,i.is_consumable,i.is_injection,uom_type1.type AS uom_type1,uu1.unit AS uom_unit1,uom1.conversions AS conversions1,uom_type2.type AS uom_type2,uu2.unit AS uom_unit2,uom2.conversions AS conversions2,uom_type3.type AS uom_type3,uu3.unit AS uom_unit3,uom3.conversions AS conversions3FROM m_item iLEFT JOIN m_formulation_type mft ON i.formulation_type_id = mft.idLEFT JOIN m_generic mg ON i.generic_id = mg.idLEFT JOIN m_product_category pc ON mg.product_category_id = pc.idLEFT JOIN m_strength_unit msu ON i.strength_unit_id = msu.idLEFT JOIN m_pharmacological_classification mpc ON i.pharmacological_classification_id = mpc.idLEFT JOIN m_manufacturer mm ON i.manufacturer_id = mm.idLEFT JOIN m_tax t1 ON i.p_tax_id = t1.idLEFT JOIN m_tax t2 ON i.s_tax_id = t2.idLEFT JOIN m_storage_unit msu2 ON i.storage_unit_id = msu2.idLEFT JOIN m_unit_of_measurement uom1 ON i.id = uom1.item_id AND uom1.uom_type_id = 1LEFT JOIN m_unit_of_measurement uom2 ON i.id = uom2.item_id AND uom2.uom_type_id = 2LEFT JOIN m_unit_of_measurement uom3 ON i.id = uom3.item_id AND uom3.uom_type_id = 3LEFT JOIN m_uom_unit uu1 ON uom1.uom_unit_id = uu1.idLEFT JOIN m_uom_unit uu2 ON uom2.uom_unit_id = uu2.idLEFT JOIN m_uom_unit uu3 ON uom3.uom_unit_id = uu3.idLEFT JOIN m_uom_type uom_type1 ON uom1.uom_type_id = uom_type1.idLEFT JOIN m_uom_type uom_type2 ON uom2.uom_type_id = uom_type2.idLEFT JOIN m_uom_type uom_type3 ON uom3.uom_type_id = uom_type3.idWHERE i.generic_id IS NOT NULL;

-- public.lock_monitor source
CREATE OR REPLACE VIEW public.lock_monitorAS SELECT COALESCE(blockingl.relation::regclass::text, blockingl.locktype) AS locked_item,now() - blockeda.query_start AS waiting_duration,blockeda.pid AS blocked_pid,blockeda.query AS blocked_query,blockedl.mode AS blocked_mode,blockinga.pid AS blocking_pid,blockinga.query AS blocking_query,blockingl.mode AS blocking_modeFROM pg_locks blockedlJOIN pg_stat_activity blockeda ON blockedl.pid = blockeda.pidJOIN pg_locks blockingl ON (blockingl.transactionid = blockedl.transactionid OR blockingl.relation = blockedl.relation AND blockingl.locktype = blockedl.locktype) AND blockedl.pid &lt;&gt; blockingl.pidJOIN pg_stat_activity blockinga ON blockingl.pid = blockinga.pid AND blockinga.datid = blockeda.datidWHERE NOT blockedl.granted AND blockinga.datname = current_database();
-- public.m_view_bed_variable_factor source
CREATE MATERIALIZED VIEW public.m_view_bed_variable_factorTABLESPACE pg_defaultAS SELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstbedtype.bed_type_id,tstbedtype.multiplication_factor,1 AS type_diffFROM service.m_service_tarrif_master mstmJOIN service.t_service_tarrif_bed_type_manager tstbedtype ON mstm.service_tarrif_master_id = tstbedtype.service_tarrif_idWHERE mstm.status = 'A'::"char"UNION ALLSELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstpatienttype.patient_category_id AS bed_type_id,tstpatienttype.multiplication_factor,2 AS type_diffFROM service.m_service_tarrif_master mstmLEFT JOIN service.t_service_tarrif_patient_category_manager tstpatienttype ON mstm.service_tarrif_master_id = tstpatienttype.service_tarrif_master_idWHERE mstm.status = 'A'::"char"UNION ALLSELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstpaymenttype.payment_entitlement_id AS bed_type_id,tstpaymenttype.multiplication_factor,3 AS type_diffFROM service.m_service_tarrif_master mstmLEFT JOIN service.t_service_tarrif_payment_entitlement_manager tstpaymenttype ON mstm.service_tarrif_master_id = tstpaymenttype.service_tarrif_master_idWHERE mstm.status = 'A'::"char"WITH NO DATA;

-- public.m_view_bed_variable_factor_nikhil source
CREATE OR REPLACE VIEW public.m_view_bed_variable_factor_nikhilAS SELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstbedtype.bed_type_id,tstbedtype.multiplication_factor,1 AS type_diffFROM service.m_service_tarrif_master mstmJOIN service.t_service_tarrif_bed_type_manager tstbedtype ON mstm.service_tarrif_master_id = tstbedtype.service_tarrif_idWHERE mstm.status = 'A'::"char"UNION ALLSELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstpatienttype.patient_category_id AS bed_type_id,tstpatienttype.multiplication_factor,2 AS type_diffFROM service.m_service_tarrif_master mstmLEFT JOIN service.t_service_tarrif_patient_category_manager tstpatienttype ON mstm.service_tarrif_master_id = tstpatienttype.service_tarrif_master_idWHERE mstm.status = 'A'::"char"UNION ALLSELECT mstm.service_tarrif_master_id,mstm.visit_type_id,mstm.unit_id,mstm.organisation_id,tstpaymenttype.payment_entitlement_id AS bed_type_id,tstpaymenttype.multiplication_factor,3 AS type_diffFROM service.m_service_tarrif_master mstmLEFT JOIN service.t_service_tarrif_payment_entitlement_manager tstpaymenttype ON mstm.service_tarrif_master_id = tstpaymenttype.service_tarrif_master_idWHERE mstm.status = 'A'::"char";

-- public.medicinelist source
CREATE OR REPLACE VIEW public.medicinelistAS SELECT t_sale.id,CASEWHEN t_sale.sale_type_id = 1 THEN concat('IP-', t_sale.admission_id)::character varyingELSE t_sale.bill_noEND::character varying(50) AS bill_no,t_sale.added_date,t_sale.total_amount,t_sale.discount,t_sale.net_amount,t_sale.tax_amount,t_sale_detail.quantity,t_sale_detail.rate,t_sale_detail.total_amount AS total_amount_details,t_sale_detail.tax_percentage,t_sale_detail.tax_amount AS tax_amount_detail,t_sale_detail.discount_amount,CASEWHEN t_sale_detail.net_amount = 0::double precision THEN t_sale_detail.package_consumption_amtELSE t_sale_detail.net_amountEND AS net_amount_detail,t_sale.sale_type_id,(registration.first_name::text || ' '::text) || registration.last_name::text::character varying::text AS patient_name,registration.uhid_number AS temp_uhid,(m_doctor_master.first_name::text || ' '::text) || m_doctor_master.last_name::text AS doctor_name,m_item.name,t_batch.batch_no,t_batch.expiry_date,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_contact,m_item.hsn_code,t_batch.cop,m_unit_master.unit_id,m_unit_master.image,CASEWHEN t_sale.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opidnumber,m_store.store_name,m_store.store_id,m_sale_type.type,mpc.classification,t_sale_detail.item_id,mm.name AS manufacturer,m_item.manufacturer_id,t_sale.patient_id,t_sale.visit_type_id,CASEWHEN t_sale.admission_id IS NULL THEN pntmst1.company_descELSE pntmst.company_descEND AS company,CASEWHEN t_sale.admission_id IS NULL THEN 'OPD No'::textELSE 'Adm No'::textEND AS opiplabel,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS issuedby,(((p_m1.prefix_desc || ' '::text) || empm.first_name::text) || ' '::text) || empm.last_name::text AS createdby,st.status,t_sale.status_idFROM pharmacy.t_sale t_saleJOIN pharmacy.t_sale_detail ON t_sale.id = t_sale_detail.sale_idLEFT JOIN adt.t_admission adm ON t_sale.admission_id = adm.admission_idLEFT JOIN opd.t_encounter_master em ON t_sale.encounter_id = em.encounter_idLEFT JOIN patient.registration ON registration.patient_id = t_sale.patient_idLEFT JOIN doctor.m_doctor_master ON m_doctor_master.doctor_id = t_sale.doctor_idJOIN inventory.t_batch ON t_batch.id = t_sale_detail.batch_idJOIN m_item ON t_batch.item_id = m_item.idLEFT JOIN m_store ON m_store.store_id = t_sale.store_idJOIN m_unit_master ON t_sale.unit_id = m_unit_master.unit_id AND t_sale.is_active = trueLEFT JOIN pharmacy.m_sale_type ON m_sale_type.id = t_sale.sale_type_idLEFT JOIN m_pharmacological_classification mpc ON mpc.id = m_item.pharmacological_classification_idLEFT JOIN m_manufacturer mm ON mm.id = m_item.manufacturer_idLEFT JOIN m_patient_visit_metadata pntmst ON pntmst.admission_id = t_sale.admission_idLEFT JOIN m_patient_visit_metadata pntmst1 ON pntmst1.encouter_id = t_sale.encounter_idLEFT JOIN m_user_master ON t_sale.added_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN pharmacy.t_prescription tp ON t_sale.prescription_id = tp.idLEFT JOIN m_user_master userm ON tp.added_by = userm.user_idLEFT JOIN m_employee_master empm ON userm.user_id = empm.user_idLEFT JOIN m_prefix_master p_m1 ON empm.prefix_id = p_m1.prefix_idLEFT JOIN m_status st ON st.id = t_sale.status_idWHERE t_sale.patient_id IS NOT NULL AND t_sale_detail.is_active = true;

-- public.mis_charges_cancellation_report source
