diagnosis_appo_mapper.unit_id = unitinformation.unit_idWHERE t_patient_diagnosis_appo_mapper.admission_id &lt;&gt; 0;

-- public.mis_expired_items_return_list source
CREATE OR REPLACE VIEW public.mis_expired_items_return_listAS SELECT DISTINCT rg.id,rg.unit_id,rg.ret_gp_no,st.store_name,rt.type,ven.name AS vendor,rg.total_amt,rg.total_tax_amount,rg.net_amount,rg.remark,rgd.batch_id,btc.batch_no,btc.expiry_date,itm.name,rg.added_date,u.unit_name,u.unit_address,rg.vendor_id,rg.store_id,rgd.return_qtyFROM inventory.t_returnable_gatepass rgLEFT JOIN inventory.t_returnable_gatepass_detail rgd ON rg.id = rgd.returnable_gatepass_idLEFT JOIN m_store st ON rg.store_id = st.store_idLEFT JOIN m_vendor ven ON rg.vendor_id = ven.idLEFT JOIN m_request_type rt ON rg.request_type_id = rt.idLEFT JOIN inventory.t_batch btc ON rgd.batch_id = btc.idLEFT JOIN m_item itm ON btc.item_id = itm.idLEFT JOIN unitinformation u ON rg.unit_id = u.unit_idWHERE rg.request_type_id = 7;

-- public.mis_group_wise_summary_report source
CREATE OR REPLACE VIEW public.mis_group_wise_summary_reportAS SELECT DISTINCT m_billing_master.visit_type_id,m_billing_master.patient_id,m_billing_master.bill_number,m_billing_master.bill_date_time,m_billing_master.encounter_id,m_billing_master.admission_id,t_billing_details.service_id,m_service_master.service_standard_name,m_speciality_master.speciality_name,m_sub_speciality_master.sub_speciality_name,t_billing_details.quantity,t_billing_details.rate,t_billing_details.concession,t_billing_details.gross_amount,t_billing_details.net_amt,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_id,(((m_prefix_master.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS user_name,m_user_master.user_id,m_speciality_master.speciality_id,m_sub_speciality_master.sub_speciality_id,((((pm.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || t_patient_registration.last_name::text AS patient_name,unitinformation.imageFROM billing.t_billing_detailsJOIN billing.m_billing_master ON m_billing_master.billing_master_id = t_billing_details.billing_master_idLEFT JOIN service.m_service_master ON t_billing_details.service_id = m_service_master.service_master_idLEFT JOIN doctor.m_speciality_master ON m_service_master.speciality_id = m_speciality_master.speciality_idLEFT JOIN doctor.m_sub_speciality_master ON m_service_master.sub_speciality_id = m_sub_speciality_master.sub_speciality_idLEFT JOIN unitinformation ON m_billing_master.unit_id = unitinformation.unit_idLEFT JOIN m_user_master ON m_billing_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master ON m_employee_master.prefix_id = m_prefix_master.prefix_idLEFT JOIN patient.t_patient_registration ON m_billing_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master pm ON t_patient_registration.prefix_id = pm.prefix_idWHERE m_billing_master.bill_status_id = 3;

-- public.mis_inpatient_issue_list_report source
CREATE OR REPLACE VIEW public.mis_inpatient_issue_list_reportAS SELECT DISTINCT issue.id,pim.uhid_number,pim.patientname,visitmaster.visit_type_name,issue.added_date,prescription.prescription_date,((('Dr.'::text || ' '::text) || doctormaster.first_name::text) || ' '::text) || doctormaster.last_name::text AS doctorname,ward.ward_name,bed.bed_decs,issue.issue_no,u.unit_name,u.unit_address,u.unit_id,ward.ward_idFROM pharmacy.t_issue issueJOIN pharmacy.t_issue_detail issuedetails ON issue.id = issuedetails.issue_idJOIN pharmacy.t_sale sales ON issue.sale_id = sales.idJOIN pharmacy.t_sale_detail salesdetails ON sales.id = salesdetails.sale_idJOIN patientinformation pim ON sales.patient_id = pim.patient_idJOIN m_visit_type_master visitmaster ON issue.visit_type_id = visitmaster.visit_type_idJOIN adt.t_admission admission ON issue.admission_id = admission.admission_idLEFT JOIN adt.t_admission_details admdetails ON admission.admission_id = admdetails.admission_idLEFT JOIN pharmacy.t_prescription prescription ON issue.prescription_id = prescription.idLEFT JOIN doctor.m_doctor_master doctormaster ON issue.doctor_id = doctormaster.doctor_idLEFT JOIN adt.m_ward_master ward ON admdetails.ward_id = ward.ward_idLEFT JOIN adt.m_bed_master bed ON admdetails.bed_id = bed.bed_idLEFT JOIN m_unit_master u ON issue.unit_id = u.unit_idWHERE admdetails.admission_details_id = (( SELECT t_admission_details.admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = admission.admission_idORDER BY t_admission_details.admission_details_id DESCLIMIT 1));
-- public.mis_inpatient_return_list_report source
CREATE OR REPLACE VIEW public.mis_inpatient_return_list_reportAS SELECT DISTINCT issuereturn.id,issuereturn.return_no,issuereturn.added_date,((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || pr.last_name::text AS patientname,issuereturn.admission_id,issuereturn.patient_id,wm.ward_name,u.unit_name,u.unit_address,u.unit_id,adm.admission_number,pr.uhid_numberFROM pharmacy.t_patient_issue_return issuereturnLEFT JOIN adt.t_admission adm ON issuereturn.admission_id = adm.admission_idLEFT JOIN patient.t_patient_registration pr ON issuereturn.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN adt.m_ward_master wm ON issuereturn.ward_id = wm.ward_idLEFT JOIN unitinformation u ON issuereturn.unit_id = u.unit_id;

-- public.mis_list_of_scheme_discount_and_free_item_report source
CREATE OR REPLACE VIEW public.mis_list_of_scheme_discount_and_free_item_reportAS SELECT DISTINCT grnd.id AS grnd_id,grnd.unit_id,grnd.grn_id,itm.name AS item_name,grnd.grn_approved_quantity,grnd.grn_received_quantity,uu.unit,grnd.bonus_approved_quantity,grnd.bonus_received_quantity,uu1.unit AS bonus_qty_uom,grnd.lot_number,grnd.batch_no,grnd.expiry_date,grnd.cop,grnd.mrp,grnd.discount,tx.name AS tax,grnd.tax_percentage,grnd.tax_amount,grnd.total_amount,grnd.total_discount,grnd.total_other_amount,grnd.net_amount,mnf.name AS manufacture,grnd.specification,grnd.remark,s.status,grn.grn_number,grn.invoice_number,grn.invoice_date,grn.dc_number,grn.dc_date,grn.inward_number,grn.inward_date,ven.name AS vendor,st.store_name,grn.total_amount AS grand_total,grn.total_discount AS grand_discount,grn.total_tax_ammount AS grand_tax_amount,grn.total_other_amount AS grand_other_amount,grn.round_off,grn.net_amount AS grand_net_amount,grn.added_date,grn.vendor_id,grn.store_id,u.unit_name,u.unit_addressFROM procurement.t_good_receipt_note_detail grndJOIN procurement.t_good_receipt_note grn ON grnd.grn_id = grn.idLEFT JOIN m_item itm ON grnd.item_id = itm.idLEFT JOIN m_uom_unit uu ON grnd.grn_uom_unit_id = uu.idLEFT JOIN m_uom_unit uu1 ON grnd.bonus_uom_unit_id = uu1.idLEFT JOIN m_tax tx ON grnd.tax_id = tx.idLEFT JOIN m_manufacturer mnf ON grnd.manufacturer_id = mnf.idLEFT JOIN m_status s ON grnd.status_id = s.idLEFT JOIN m_vendor ven ON grn.vendor_id = ven.idLEFT JOIN m_store st ON grn.store_id = st.store_idLEFT JOIN unitinformation u ON grnd.unit_id = u.unit_idWHERE grnd.bonus_received_quantity &lt;&gt; 0ORDER BY grnd.grn_id;

-- public.mis_receipt_register_report source
CREATE OR REPLACE VIEW public.mis_receipt_register_reportAS SELECT DISTINCT prm.reciept_number,'Payment Against Bill'::text AS lable,prm.date_of_reciept AS date,em.encounter_id,em.encounter_number,adm.admission_id,adm.admission_number,bm.patient_id,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patientname,prd.amount,0 AS consumed_amount,0 AS balance_amount,0 AS deposit_amount,pmm.payment_mode_desc,prd.payment_reciept_details_id AS id,(((upm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,u.unit_name,u.unit_address,u.unit_id,um.user_idFROM billing.t_payment_reciept_master prmLEFT JOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN patient.t_patient_registration pr ON bm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN billing.t_payment_reciept_details prd ON prm.payment_reciept_id = prd.payment_receipt_master_idLEFT JOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idLEFT JOIN m_user_master um ON prd.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master upm ON emp.prefix_id = upm.prefix_idLEFT JOIN unitinformation u ON prm.unit_id = u.unit_idUNION ALLSELECT DISTINCT dm.deposit_no AS reciept_number,CASEWHEN dm.deposit_type_id = 1 THEN 'Active Deposit'::textWHEN dm.deposit_type_id = 2 THEN 'Deposit Against Encounter'::textWHEN dm.deposit_type_id = 3 THEN 'Deposit At The Time of Reservation'::textELSE 'Loyalty Card'::textEND AS lable,dm.deposit_date AS date,em.encounter_id,em.encounter_number,adm.admission_id,adm.admission_number,dm.patient_id,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patientname,pdd.amount,pdd.consumed_amount,pdd.balance_amount,dm.deposit_amount,pmm.payment_mode_desc,pdd.deposit_details_id AS id,(((upm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,u.unit_name,u.unit_address,u.unit_id,um.user_idFROM billing.m_deposit_master dmLEFT JOIN billing.t_payment_deposit_details pdd ON dm.deposit_master_id = pdd.deposit_idLEFT JOIN opd.t_encounter_master em ON dm.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON dm.admission_id = adm.admission_idLEFT JOIN patient.t_patient_registration pr ON dm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN m_payment_mode_master pmm ON pdd.payment_mode_id = pmm.payment_mode_idLEFT JOIN m_user_master um ON pdd.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master upm ON emp.prefix_id = upm.prefix_idLEFT JOIN unitinformation u ON dm.unit_id = u.unit_idUNION ALLSELECT DISTINCT prm.payment_refund_voucher_no AS reciept_number,CASEWHEN prm.is_cn_or_deposit = 0 THEN 'Refund Against Deposit'::textELSE 'Refund Against Credit Note'::textEND AS lable,prm.date_of_refund AS date,rc.encounter_id,em.encounter_number,rc.admission_id,adm.admission_number,prm.patient_id,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patientname,prd.amount,0 AS consumed_amount,0 AS balance_amount,0 AS deposit_amount,pmm.payment_mode_desc,prd.payment_refund_details_id AS id,(((upm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,u.unit_name,u.unit_address,u.unit_id,um.user_idFROM billing.t_payment_refund_master prmLEFT JOIN billing.t_payment_refund_details prd ON prm.payment_refund_id = prd.payment_refund_idLEFT JOIN patient.t_patient_registration pr ON prm.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idLEFT JOIN billing.t_refund_cn rc ON prm.t_refund_cn_id = rc.t_refund_cn_idLEFT JOIN opd.t_encounter_master em ON rc.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON rc.admission_id = adm.admission_idLEFT JOIN m_user_master um ON prd.created_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_prefix_master upm ON emp.prefix_id = upm.prefix_idLEFT JOIN unitinformation u ON prm.unit_id = u.unit_idORDER BY 3 DESC;

-- public.mis_sales_credit_report source
CREATE OR REPLACE VIEW public.mis_sales_credit_reportAS SELECT DISTINCT sle.id,sle.bill_no,sle.encounter_id,sle.admission_id,slt.type AS sale_type,sle.added_date,s.status,sle.total_amount,sle.discount,sle.total_discount_amount,sle.net_amount,sle.tax_amount,sle.outstanding_amount,sle.paid_amount,sle.round_off,sle.total_self_payable,sle.total_credit_payable,sle.patient_id,sle.temp_patient_id,CASEWHEN sle.patient_id IS NULL THEN sle.temp_patient_idELSE sle.patient_idEND AS merge_patient_id,CASEWHEN sle.temp_patient_id IS NOT NULL THEN (pm1.prefix_desc || '. '::text) || pr1.patient_name::textELSE (((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::textEND AS patient_name,sle.visit_type_id,vtm.visit_type_name,u.unit_id,u.unit_name,u.unit_address,sle.sale_type_idFROM pharmacy.t_sale sleLEFT JOIN pharmacy.m_sale_type slt ON sle.sale_type_id = slt.idLEFT JOIN patient.t_patient_registration pr ON sle.patient_id = pr.patient_idLEFT JOIN pharmacy.t_temp_patient_registration pr1 ON sle.temp_patient_id = pr1.idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN m_prefix_master pm1 ON pr1.prefix_id = pm1.prefix_idLEFT JOIN m_status s ON sle.status_id = s.idLEFT JOIN opd.t_encounter_master enc ON sle.encounter_id = enc.encounter_idLEFT JOIN adt.t_admission adm ON sle.admission_id = adm.admission_idLEFT JOIN m_visit_type_master vtm ON sle.visit_type_id = vtm.visit_type_idLEFT JOIN m_unit_master u ON sle.unit_id = u.unit_idWHERE sle.is_active = true AND sle.is_deleted = false;

-- public.mis_sercies_wise_count_report source
CREATE OR REPLACE VIEW public.mis_sercies_wise_count_reportAS SELECT DISTINCT bd.billing_details_id,bd.service_id,bd.rate,bd.quantity,bd.concession,bd.gross_amount,bd.discount,bd.tax_amount,bd.net_amt,bm.billing_master_id,bm.encounter_id,bm.visit_type_id,bm.bill_number,bm.bill_date_time,bm.net_amount,bm.discount_amount,bm.is_credit_bill,bm.concession_amount,bm.gst,bm.total_bill_amount,bm.outstanding,bm.round_off,sm.service_standard_name,sm.speciality_id,sm.sub_speciality_id,vtm.visit_type_name,em.encounter_date,em.encounter_number,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,uni.unit_name,uni.unit_address,uni.unit_idFROM billing.t_billing_details bdJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idLEFT JOIN service.m_service_master sm ON bd.service_id = sm.service_master_idLEFT JOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN patient.t_patient_registration pr ON em.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN unitinformation uni ON bd.unit_id = uni.unit_idWHERE bm.visit_type_id = 1 AND bm.bill_status_id = 3UNION ALLSELECT DISTINCT bd.billing_details_id,bd.service_id,bd.rate,bd.quantity,bd.concession,bd.gross_amount,bd.discount,bd.tax_amount,bd.net_amt,bm.billing_master_id,bm.encounter_id,bm.visit_type_id,bm.bill_number,bm.bill_date_time,bm.net_amount,bm.discount_amount,bm.is_credit_bill,bm.concession_amount,bm.gst,bm.total_bill_amount,bm.outstanding,bm.round_off,sm.service_standard_name,sm.speciality_id,sm.sub_speciality_id,vtm.visit_type_name,ad.created_date AS encounter_date,ad.admission_number AS encounter_number,(((((pm.prefix_desc || ' '::text) || pr.first_name::text) || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patient_name,uni.unit_name,uni.unit_address,uni.unit_idFROM billing.t_billing_details bdJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idLEFT JOIN service.m_service_master sm ON bd.service_id = sm.service_master_idLEFT JOIN m_visit_type_master vtm ON bm.visit_type_id = vtm.visit_type_idLEFT JOIN adt.t_admission ad ON bm.encounter_id = ad.admission_idLEFT JOIN patient.t_patient_registration pr ON ad.patient_id = pr.patient_idLEFT JOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idLEFT JOIN unitinformation uni ON bd.unit_id = uni.unit_idWHERE bm.visit_type_id = 2 AND bm.bill_status_id = 3;

-- public.mis_supplier_address_report source
CREATE OR REPLACE VIEW public.mis_supplier_address_reportAS SELECT DISTINCT v.id,u.unit_id,u.unit_name,u.unit_address,mnf.name AS manufacturer,v.code,v.name AS vendor_name,v.contact_person_name,v.drug_license_no,v.gst_no,v.address,coun.country_name,st.state_name,cty.city_name,ar.area_name,v.phone_number,v.email_id,pmm.payment_mode_desc,v.payment_term,v.zip_codeFROM m_vendor vLEFT JOIN m_manufacturer mnf ON v.manufacturer_id = mnf.idLEFT JOIN unitinformation u ON v.unit_id = u.unit_idLEFT JOIN m_country_master coun ON v.country_id = coun.country_idLEFT JOIN m_state_master st ON v.state_id = st.state_idLEFT JOIN m_city_master cty ON v.city_id = cty.city_idLEFT JOIN m_area_master ar ON v.area_id = ar.area_idLEFT JOIN m_payment_mode_master pmm ON v.payment_mode_id = pmm.payment_mode_id;

-- public.mis_work_order_list_report source
CREATE OR REPLACE VIEW public.mis_work_order_list_reportAS SELECT DISTINCT woc.id,woc.unit_id,st.store_name,s.status,woc.added_date,woc.added_by,woc.total_amount,woc.total_discount,woc.total_tax,woc.net_amount,con.description AS contract_type,u.unit_name,u.unit_address,(((pm.prefix_desc || ' '::text) || emp.first_name::text) || ' '::text) || emp.last_name::text AS user_name,usm.user_id,v.name,woc.vendor_id,wocd.item_id,it.name AS item_name,t.name AS tax_description,wocd.wo_quantity,wocd.qo_bonus_quantity,wocd.amount AS details_amount,wocd.discount_amount AS details_discount,wocd.tax_amount AS details_tax,wocd.total_amount AS details_total_amount,wocd.net_amount AS details_net_amount,wocd.remark AS details_remarks,bat.batch_no,woc.work_order_no,wo.added_date AS work_order_dateFROM procurement.t_work_order_creation wocLEFT JOIN unitinformation u ON woc.unit_id = u.unit_idLEFT JOIN m_store st ON woc.store_id = st.store_idLEFT JOIN m_vendor v ON woc.vendor_id = v.idLEFT JOIN m_status s ON woc.status_id = s.idLEFT JOIN procurement.m_contract_type con ON woc.contract_type_id = con.idLEFT JOIN m_user_master usm ON woc.added_by = usm.user_idLEFT JOIN m_employee_master emp ON usm.user_id = emp.user_idLEFT JOIN m_prefix_master pm ON emp.prefix_id = pm.prefix_idLEFT JOIN procurement.t_work_order_creation_detail wocd ON woc.id = wocd.wo_creation_idLEFT JOIN m_item it ON wocd.item_id = it.idLEFT JOIN m_tax t ON wocd.tax_id = t.idLEFT JOIN inventory.t_batch bat ON wocd.batch_id = bat.idLEFT JOIN procurement.t_work_order wo ON woc.work_order_id = wo.id;

-- public.missed_tat_for_emergecy_samples source
CREATE OR REPLACE VIEW public.missed_tat_for_emergecy_samplesAS SELECT DISTINCT s.lab_sample_id,concat(pm.prefix_desc, '', p.first_name, ' ', p.middle_name, ' ', p.last_name) AS patient_name,t.test_alies,s.sample_accept_datetime AS received_time,st.result_enter_datetime AS processed_time,CASEWHEN (st.result_enter_datetime - s.sample_accept_datetime) &gt; '04:00:00'::interval THEN 'Delayed'::textELSE 'On Time'::textEND AS status,s.org_unit_id,s.sub_dept_id,ssm.sub_speciality_nameFROM lab.t_lab_sample_dtls sJOIN lab.t_lab_test_result st ON st.lab_sample_dtls_id = s.lab_sample_dtls_idJOIN doctor.m_sub_speciality_master ssm ON ssm.sub_speciality_id = s.sub_dept_idJOIN lab.m_test_master t ON s.test_id = t.test_idJOIN patient.t_patient_registration p ON s.patient_id = p.patient_idJOIN m_prefix_master pm ON pm.prefix_id = p.prefix_idJOIN m_unit_master um ON um.unit_id = s.org_unit_idWHERE st.result_enter_datetime IS NOT NULL AND st.result_enter_datetime &gt; (s.sample_accept_datetime + '01:00:00'::interval);
-- public.mortality_rate source
CREATE OR REPLACE VIEW public.mortality_rateAS SELECT td.discharge_id,td.discharge_date,concat(pm.prefix_desc, '', pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,pr.uhid_number,gm.gender_name,abs(date_part('Year'::text, age(pr.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,visit.visit_type_code,tad.doa,wm.ward_name,td.discharge_date - tad.doa AS duration,td.unit_idFROM adt.t_discharge tdJOIN adt.t_admission ta ON ta.admission_id = td.admission_idJOIN adt.t_admission_details tad ON tad.admission_id = ta.admission_idJOIN adt.m_ward_master wm ON wm.ward_id = tad.ward_idJOIN patient.t_patient_registration pr ON pr.patient_id = ta.patient_idJOIN m_prefix_master pm ON pr.prefix_id = pm.prefix_idJOIN m_gender_master gm ON gm.gender_id = pr.gender_idJOIN m_visit_type_master visit ON visit.visit_type_id = td.visit_type_idWHERE td.is_death = 'Y'::bpchar AND tad.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS maxFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = ta.admission_id));
-- public.narhar_getbilldetails_new source
CREATE OR REPLACE VIEW public.narhar_getbilldetails_newAS SELECT DISTINCT billmst.billing_master_id,pntmst.uhid_number,pntmst.first_name,pntmst.middle_name,pntmst.last_name,pntmst.email,billdtls.gross_amount AS amount,billdtls.created_date::date AS transactiondate,billmst.organisation_id AS orgid,billmst.unit_id AS unitid,servmst.service_standard_name,encmst.encounter_date,pm.prefix_desc,concat(COALESCE(pm.prefix_desc, ''::character varying::text), ' ', COALESCE(pntmst.first_name, ''::character varying), ' ', COALESCE(pntmst.middle_name, ''::character varying), ' ', COALESCE(pntmst.last_name, ''::character varying)) AS patientname,m_organization_master.organization_name,m_organization_master.organization_address,m_organization_master.organization_contact,billmst.bill_number,billmst.net_amount,billmst.discount_amount,billmst.concession_amount,billmst.gst,billmst.total_bill_amount,billmst.outstanding,billdtls.rate,billdtls.quantity,billdtls.net_amt,billdtls.gross_amount,billdtls.concession,((('Dr. '::text || ''::text) || doctorm.first_name::text) || ' '::text) || doctorm.last_name::text AS consultant,spc.speciality_name,speciality.speciality_name AS dept,(((p_m.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,um.unit_id,um.unit_name,um.unit_address,um.unit_address_2,um.unit_email_id,um.unit_logo,um.post_code,um.unit_contact,um.unit_contact_2,um.unit_contact_3,um.unit_country_code,um.registration_number,um.unit_website,um.currency_name,um.sub_currency,encmst.encounter_number,encmst.unit_token_number,m_tax.name,billdtls.tax_per,billdtls.tax_amount,billdtls.net_amt AS detailsnet_amt,billmst.net_amount AS mstnetamt,billdtls.discount AS dtlsdiscount,doctorinformation.doctor_id,doctorinformation.doctorname,doctorinformation.docgender,doctorinformation.doctor_category_description,doctorinformation.docspeciality,doctorinformation.docage,doctorinformation.docdob,doctorinformation.country_calling_code,doctorinformation.docmobile,doctorinformation.docemail,doctorinformation.doctor_image,doctorinformation.docreg,doctorinformation.slot_time_span,doctorinformation.doctor_episod_time_span,doctorinformation.encounter_id,doctorinformation.speciality_id,billmst.bill_date_time,company.company_desc,billdtls.payee_id,payeemapper.contract_id,payeemapper.payee_id AS payeeidnew,payeemapper.payee_amount,payeemapper.due_amount,companynew.company_desc AS payeedescnew,contractmaster.contract_name,billdtls.order_details_id,billmst.bill_cancel_remark,od.is_package_service,od.package_id,od.is_package,billstatusmaster.bill_status_desc,billdtls.package_consumption_amt,servmst.service_master_id,m_refferel.referral_name,payment.amount AS paidamount,pntmst.mobile_number,pim.gender_name,pim.ageyear,um.image,pim.agemonth,((('Dr. '::text || ''::text) || doctorm1.first_name::text) || ' '::text) || doctorm1.last_name::text AS orderdocname,um.unit_description,COALESCE(pharmacyservice_id(billmst.billing_master_id), 0) AS pharmacyservice_idFROM billing.t_billing_details billdtlsLEFT JOIN billing.m_billing_master billmst ON billmst.billing_master_id = billdtls.billing_master_idLEFT JOIN service.m_service_master servmst ON servmst.service_master_id = billdtls.service_idLEFT JOIN doctor.m_speciality_master spc ON spc.speciality_id = servmst.speciality_idLEFT JOIN m_general_ledger_master genledmst ON genledmst.general_ledger_id = spc.general_ledger_idLEFT JOIN opd.t_encounter_master encmst ON billmst.encounter_id = encmst.encounter_idLEFT JOIN patient.t_patient_registration pntmst ON pntmst.patient_id = encmst.patient_idLEFT JOIN patientinformation pim ON encmst.patient_id = pim.patient_idLEFT JOIN m_prefix_master pm ON pntmst.prefix_id = pm.prefix_idLEFT JOIN m_organization_master ON billmst.organisation_id = m_organization_master.organization_idLEFT JOIN doctor.m_doctor_master ON encmst.doctor_id = m_doctor_master.doctor_idLEFT JOIN doctor.m_speciality_master docsp ON m_doctor_master.speciality_id = docsp.speciality_idLEFT JOIN m_user_master ON billmst.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master p_m ON m_employee_master.prefix_id = p_m.prefix_idLEFT JOIN unitinformation um ON billmst.unit_id = um.unit_idLEFT JOIN m_tax ON billdtls.tax_id = m_tax.idLEFT JOIN doctor.doctorinformation ON billmst.encounter_id = doctorinformation.encounter_idLEFT JOIN t_company_master company ON billdtls.payee_id = company.company_idLEFT JOIN doctor.m_speciality_master speciality ON encmst.dept_id = speciality.speciality_idLEFT JOIN doctor.m_doctor_master doctorm ON encmst.doctor_id = doctorm.doctor_idLEFT JOIN billing.t_bill_details_payee_mapper payeemapper ON billdtls.billing_details_id = payeemapper.bill_details_idLEFT JOIN t_company_master companynew ON payeemapper.payee_id = companynew.company_idLEFT JOIN service.m_company_contract_master contractmaster ON payeemapper.contract_id = contractmaster.contract_idLEFT JOIN t_order_details od ON billdtls.order_details_id = od.order_details_idLEFT JOIN billing.m_billing_status_master billstatusmaster ON billmst.bill_status_id = billstatusmaster.bill_status_idLEFT JOIN t_referal_details admreff ON encmst.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idLEFT JOIN doctor.m_doctor_master doctorm1 ON billdtls.ord_doc_id = doctorm1.doctor_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON billmst.billing_master_id = payment.billing_master_idWHERE billmst.visit_type_id = 1ORDER BY billmst.billing_master_id DESC;

-- public.non_formulary source
CREATE OR REPLACE VIEW public.non_formularyAS SELECT 0 AS srno,concat(pr.prefix_desc, '', pinfo.first_name, ' ', pinfo.middle_name, ' ', pinfo.last_name) AS patientname,age(pinfo.dob) AS age,gm.gender_name,pinfo.uhid_number,em.encounter_number AS visitnumber,em.encounter_date AS visitdate,um.unit_id,um.unit_name,um.image AS unit_logo,um.unit_address,um.organization_id,presdtl.item_id AS "itemId",presdtl.item_name AS "itemName",prefredtl.dose AS "doseDesc",su.unit AS "strengthDesc",prefredtl.frequency_id AS "frequencyId",freq.description AS "frequencyDesc",prefredtl.route_id AS "roaId",presdtl.statflag,roa.description AS "roaDesc",prefredtl.start_date AS startdate,prefredtl.stop_date AS enddate,presdtl.instruction_id AS "instructionId",instr.instruction_desc AS "instructionDesc",presdtl.generic_name AS "genericName",pres.encounter_id,presdtl.order_qty AS qty,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_number,pinfo.patient_id,''::text AS unit_address_2,pres.id,pres.prescription_no,pres.prescription_date,tpd.address AS patientaddress,pinfo.mobile_number,pinfo.dob AS patientdob,abs(date_part('Year'::text, age(pinfo.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,'0'::text AS is_medication_stop,'2019-11-22 09:54:34'::timestamp without time zone AS updated_date,''::text AS justification_stop,pres.visit_type_id,true AS is_narcotic,um.unit_contact,um.unit_email_id,um.image,dm.doctor_id,''::text AS instruction_desc,''::text AS converted_text,1 AS language_idFROM pharmacy.t_prescription presJOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.idLEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.idLEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_idLEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_idLEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_idLEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.idJOIN patient.t_patient_registration pinfo ON pinfo.patient_id = pres.patient_idJOIN m_prefix_master pr ON pr.prefix_id = pinfo.prefix_idJOIN m_gender_master gm ON gm.gender_id = pinfo.gender_idJOIN patient.t_patient_details tpd ON tpd.patient_id = pinfo.patient_idJOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_idJOIN m_unit_master um ON um.unit_id = pres.unit_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_idWHERE presdtl.is_non_formulary = 'Y'::bpchar;

-- public.op_ip_revenue source
CREATE OR REPLACE VIEW public.op_ip_revenueAS SELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id = (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE msm.speciality_id &lt;&gt; (( SELECT t_unit_application_billing_configuration.consultation_speciality_idFROM t_unit_application_billing_configurationWHERE t_unit_application_billing_configuration.unit_id = 1)) AND bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 1 AS srno,'OP REVENUE'::text AS lebel,sum(tsd.net_amount) AS net,ts.added_date::date AS bill_date_time,ts.unit_idFROM pharmacy.t_sale tsJOIN pharmacy.t_sale_detail tsd ON ts.id = tsd.sale_idWHERE ts.is_active = true AND tsd.is_active = true AND ts.sale_type_id &lt;&gt; 1GROUP BY (ts.added_date::date), ts.unit_idUNIONSELECT 2 AS srno,'IP REVENUE'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.package_consumption_amt = 0::double precision AND bm.visit_type_id &lt;&gt; 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 3 AS srno,'General'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 1GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 4 AS srno,'Corporate'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 3GROUP BY (bm.bill_date_time::date), bm.unit_idUNIONSELECT 5 AS srno,'Insurance'::text AS lebel,sum(bd.net_amt) AS net,bm.bill_date_time::date AS bill_date_time,bm.unit_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master msm ON msm.service_master_id = bd.service_idLEFT JOIN opd.t_patient_sponsor_details psd ON psd.admission_id = bm.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN m_payment_entitlement_master pmop ON psd.payment_entitlement_id = pmop.payment_entitlement_idWHERE bd.package_consumption_amt = 0::double precision AND bm.bill_cancelled = 'N'::bpchar AND bm.visit_type_id &lt;&gt; 1 AND pmop.payment_entitlement_id = 2GROUP BY (bm.bill_date_time::date), bm.unit_idORDER BY 1;

-- public.op_ipcash source
CREATE OR REPLACE VIEW public.op_ipcashAS SELECT DISTINCT bm.bill_number,bm.bill_date_time,CASEWHEN bm.admission_id IS NULL THEN em.encounter_numberELSE adm.admission_numberEND AS opipnumber,pim.uhid_number,concat(pim.first_name, ' ', pim.last_name) AS patientname,''::text AS patientaddress,''::text AS patientmobile,CASEWHEN bm.admission_id IS NULL THEN refmasterop.referral_nameELSE refmasterip.referral_nameEND AS referral_name,CASEWHEN bm.admission_id IS NULL THEN refmasterop.referral_contactELSE refmasterip.referral_contactEND AS referral_contact,CASEWHEN bm.admission_id IS NULL THEN concat('Dr. ', dmopd.first_name, ' ', dmopd.last_name)ELSE concat('Dr. ', dmipd.first_name, ' ', dmipd.last_name)END AS doctorname,CASEWHEN bm.admission_id IS NULL THEN spopd.speciality_nameELSE spipd.speciality_nameEND AS department,0 AS consultation,0 AS followup_visit,dsp.speciality_name,dssp.sub_speciality_name,bd.gross_amount,COALESCE(bd.discount + bd.concession, 0::double precision) AS discount,bd.net_amt,bm.outstanding,um.unit_name,um.unit_address,um.unit_id,''::text AS image,visit.visit_type_id,COALESCE(bm.discount_amount + bm.concession_amount, 0::double precision) AS discount_amount,bm.total_bill_amount,bm.net_amount,bm.billing_master_id,''::text AS date_of_reciept,prr.amount,CASEWHEN bm.net_amount = 0::double precision THEN bm.bill_date_timeELSE prr.date_of_transactionEND AS date_of_transaction,bd.billing_details_id,bm.bill_cancelled,CASEWHEN bm.admission_id IS NULL THEN dmopd.doctor_idELSE dmipd.doctor_idEND AS doctor_id,dsp.speciality_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_id AND bd.status = 'A'::"char"JOIN t_order_details od ON bd.order_details_id = od.order_details_id AND od.package_consumption_amt = 0::numeric AND od.status = 'A'::bpcharJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN doctor.m_speciality_master dsp ON sm.speciality_id = dsp.speciality_idJOIN doctor.m_sub_speciality_master dssp ON sm.sub_speciality_id = dssp.sub_speciality_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idJOIN patient.t_patient_registration pim ON bm.patient_id = pim.patient_idLEFT JOIN doctor.m_doctor_master dmopd ON em.doctor_id = dmopd.doctor_idLEFT JOIN doctor.m_doctor_master dmipd ON adm.admitting_doctor_id = dmipd.doctor_idLEFT JOIN t_referal_details referop ON em.encounter_id = referop.encounter_idLEFT JOIN t_referal_details referip ON adm.admission_id = referip.admission_idLEFT JOIN adt.m_referral_master refmasterop ON referop.referral_id = refmasterop.referral_idLEFT JOIN adt.m_referral_master refmasterip ON referip.referral_id = refmasterip.referral_idLEFT JOIN m_visit_type_master visit ON bm.visit_type_id = visit.visit_type_idLEFT JOIN doctor.m_speciality_master spopd ON em.dept_id = spopd.speciality_idLEFT JOIN doctor.m_speciality_master spipd ON adm.speciality_id = spipd.speciality_idLEFT JOIN m_unit_master um ON bm.unit_id = um.unit_idLEFT JOIN ( SELECT sum(prd.amount) AS amount,pr.billing_master_id,pr.date_of_reciept AS date_of_transactionFROM billing.t_payment_reciept_master prJOIN billing.t_payment_reciept_details prd ON pr.payment_reciept_id = prd.payment_receipt_master_idWHERE pr.reciept_cancelled = 'N'::bpchar AND prd.payment_mode_id &lt;&gt; 10GROUP BY pr.billing_master_id, pr.date_of_reciept) prr ON bm.billing_master_id = prr.billing_master_idWHERE bm.bill_cancelled = 'N'::bpchar AND bd.status = 'A'::"char";

-- public.opdcovershit source
CREATE OR REPLACE VIEW public.opdcovershitAS SELECT em.encounter_id,um.unit_id,pr.patient_id,concat(pr.first_name, ' ', pr.middle_name, ' ', pr.last_name) AS patientname,age(pr.dob) AS age,pr.uhid_number,gm.gender_name,um.unit_name,um.unit_address,um.unit_contact,um.unit_contact_2,um.organization_idFROM patient.t_patient_registration prJOIN m_gender_master gm ON pr.gender_id = gm.gender_idJOIN m_unit_master um ON pr.unit_id = um.unit_idJOIN opd.t_encounter_master em ON pr.patient_id = em.patient_id;

-- public.opdipdcollectionsummary source
CREATE OR REPLACE VIEW public.opdipdcollectionsummaryAS (SELECT advancesummary.deposit_master_id,advancesummary.deposit,advancesummary.visit_type_code,advancesummary.visit_type_id,advancesummary.payment_mode_desc,advancesummary.amount,advancesummary.consumed_amount,advancesummary.tdsamt,advancesummary.user_name,advancesummary.user_id,advancesummary.unit_id,advancesummary.organization_id,advancesummary.unit_name,advancesummary.unit_address,advancesummary.unit_contact,advancesummary.unit_contact_2,advancesummary.depositdate,advancesummary.patientname,advancesummary.patient_id,advancesummary.uhid_number,advancesummary.amttype,advancesummary.reciptno,advancesummary.counter_id,advancesummary.counter_descFROM advancesummaryUNIONSELECT opipdbillsummary.billing_master_id AS deposit_master_id,opipdbillsummary.deposit,opipdbillsummary.visit_type_code,opipdbillsummary.visit_type_id,opipdbillsummary.payment_mode_desc,opipdbillsummary.amount,opipdbillsummary.consumed_amount,opipdbillsummary.tdsamt,opipdbillsummary.user_name,opipdbillsummary.user_id,opipdbillsummary.unit_id,opipdbillsummary.organization_id,opipdbillsummary.unit_name,opipdbillsummary.unit_address,opipdbillsummary.unit_contact,opipdbillsummary.unit_contact_2,opipdbillsummary.depositdate,opipdbillsummary.patientname,opipdbillsummary.patient_id,opipdbillsummary.uhid_number,opipdbillsummary.amttype,opipdbillsummary.reciept_number AS reciptno,opipdbillsummary.counter_id,opipdbillsummary.counter_descFROM opipdbillsummaryUNIONSELECT opipdadvancerefund.id AS deposit_master_id,opipdadvancerefund.deposit,opipdadvancerefund.visit_type_code,opipdadvancerefund.visit_type_id,opipdadvancerefund.payment_mode_desc,opipdadvancerefund.amount,opipdadvancerefund.consumed_amount,opipdadvancerefund.tdsamt,opipdadvancerefund.user_name,opipdadvancerefund.user_id,opipdadvancerefund.unit_id,opipdadvancerefund.organization_id,opipdadvancerefund.unit_name,opipdadvancerefund.unit_address,opipdadvancerefund.unit_contact,opipdadvancerefund.unit_contact_2,opipdadvancerefund.depositdate,opipdadvancerefund.patientname,opipdadvancerefund.patient_id,opipdadvancerefund.uhid_number,opipdadvancerefund.amttype,opipdadvancerefund.reciptno,opipdadvancerefund.counter_id,opipdadvancerefund.counter_descFROM opipdadvancerefund) UNION ALLSELECT DISTINCT get_misexpenses.expense_id AS deposit_master_id,CASEWHEN get_misexpenses.bill_type = 1 THEN 'Mis.Income'::textWHEN get_misexpenses.bill_type = 2 THEN 'Expenses'::textELSE NULL::textEND AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,get_misexpenses.payment_mode_desc,get_misexpenses.amount,0 AS consumed_amount,0 AS tdsamt,get_misexpenses.user_name,get_misexpenses.user_id,get_misexpenses.unit_id,get_misexpenses.org_id AS organization_id,get_misexpenses.unit_name,get_misexpenses.unit_address,get_misexpenses.unit_contact,'-'::text AS unit_contact_2,get_misexpenses.date_of_reciept AS depositdate,get_misexpenses.expencesname AS patientname,0 AS patient_id,'-'::character varying AS uhid_number,CASEWHEN get_misexpenses.bill_type = 1 THEN 'Mis.Income'::textWHEN get_misexpenses.bill_type = 2 THEN 'Expenses'::textELSE NULL::textEND AS amttype,get_misexpenses.bill_number AS reciptno,0 AS counter_id,''::character varying(50) AS counter_descFROM get_misexpenses;

-- public.opipdadvancerefund source
CREATE OR REPLACE VIEW public.opipdadvancerefundAS SELECT bm.payment_refund_id AS id,CASEWHEN brc.visit_type_id = 1 THEN vtm.visit_type_code::text || 'D Advance Refund'::textWHEN brc.visit_type_id IS NULL THEN 'Active Advance Refund'::textELSE vtm.visit_type_code::text || 'D Advance Refund'::textEND AS deposit,'Active patient'::character varying AS visit_type_code,3 AS visit_type_id,pmm.payment_mode_desc,brdet.amount,0 AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,brdet.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Refund'::text AS amttype,bm.payment_refund_voucher_no AS reciptno,countermaster.counter_id,countermaster.counter_descFROM billing.t_payment_refund_details brdetLEFT JOIN billing.t_payment_refund_master bm ON bm.payment_refund_id = brdet.payment_refund_idJOIN billing.t_refund_cn brc ON brc.t_refund_cn_id = bm.t_refund_cn_idLEFT JOIN m_visit_type_master vtm ON vtm.visit_type_id = brc.visit_type_idJOIN m_payment_mode_master pmm ON brdet.payment_mode_id = pmm.payment_mode_idJOIN m_unit_master umm ON brdet.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_user_master um ON brdet.created_by = um.user_idLEFT JOIN m_counter_master countermaster ON bm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idUNION ALLSELECT bm.payment_refund_id AS id,CASEWHEN billmst.visit_type_id = 1 THEN vtm.visit_type_code::text || 'D Refund bill'::textELSE vtm.visit_type_code::text || 'D Refund bill'::textEND AS deposit,vtm.visit_type_code,vtm.visit_type_id,pmm.payment_mode_desc,brdet.amount,0 AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,brdet.created_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Refund'::text AS amttype,bm.payment_refund_voucher_no AS reciptno,countermaster.counter_id,countermaster.counter_descFROM billing.t_payment_refund_details brdetJOIN billing.t_payment_refund_master bm ON bm.payment_refund_id = brdet.payment_refund_idJOIN billing.m_credit_note_master bcnid ON bm.credit_note_id = bcnid.credit_note_idJOIN billing.m_billing_master billmst ON billmst.billing_master_id = bcnid.bill_idJOIN m_visit_type_master vtm ON vtm.visit_type_id = billmst.visit_type_idJOIN m_payment_mode_master pmm ON brdet.payment_mode_id = pmm.payment_mode_idJOIN m_unit_master umm ON brdet.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_user_master um ON brdet.created_by = um.user_idLEFT JOIN m_counter_master countermaster ON bm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idORDER BY 1;

-- public.opipdbillsummary source
CREATE OR REPLACE VIEW public.opipdbillsummaryAS SELECT bm.billing_master_id,vm.visit_type_code::text || 'D Bill'::text AS deposit,vm.visit_type_code,vm.visit_type_id,pmm.payment_mode_desc,prd.amount,0 AS consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,prd.date_of_transaction AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,rm.reciept_number,countermaster.counter_id,countermaster.counter_desc,prd.payment_reciept_details_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN billing.t_payment_reciept_master rm ON bm.billing_master_id = rm.billing_master_idJOIN billing.t_payment_reciept_details prd ON rm.payment_reciept_id = prd.payment_receipt_master_idJOIN m_payment_mode_master pmm ON prd.payment_mode_id = pmm.payment_mode_idJOIN m_user_master um ON rm.created_by = um.user_idJOIN m_unit_master umm ON rm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON rm.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE COALESCE(rm.reciept_cancelled, 'N'::bpchar) = 'N'::bpchar AND COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpcharUNIONSELECT bm.billing_master_id,vm.visit_type_code::text || 'D Bill'::text AS deposit,vm.visit_type_code,vm.visit_type_id,'selfconsumed'::text AS payment_mode_desc,0 AS amount,dc.consumed_amount,0 AS tdsamt,concat(m_employee_master.first_name, ' ', m_employee_master.last_name)::character varying(100) AS user_name,um.user_id,umm.unit_id,umm.organization_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,dc.dep_consumption_date AS depositdate,concat(COALESCE(prefix.prefix_desc, ''::character varying::text), ' ', COALESCE(pm.first_name, ''::character varying), ' ', COALESCE(pm.middle_name, ''::character varying), ' ', COALESCE(pm.last_name, ''::character varying)) AS patientname,pm.patient_id,pm.uhid_number,'Income'::text AS amttype,dc.deposite_consumption_number AS reciept_number,countermaster.counter_id,countermaster.counter_desc,0 AS payment_reciept_details_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN billing.t_payment_deposite_consumption dc ON bm.billing_master_id = dc.bill_idJOIN m_user_master um ON dc.created_by = um.user_idJOIN m_unit_master umm ON dc.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN m_counter_master countermaster ON dc.counter_id = countermaster.counter_idLEFT JOIN m_employee_master ON m_employee_master.user_id = um.user_idWHERE COALESCE(bm.bill_cancelled, 'N'::bpchar) = 'N'::bpchar;

-- public.outstandingbills source
CREATE OR REPLACE VIEW public.outstandingbillsAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(prefix.prefix_desc, '', pm.first_name, ' ', pm.middle_name, ' ', pm.last_name) AS patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.bill_status_id,status_master.bill_status_desc,umm.image,umm.organization_id,org.organization_name,adm.admission_number,m_payment_entitlement_master.payment_entitlement_id,m_payment_entitlement_master.payment_entitlement_desc,COALESCE(bm.net_amount - bm.outstanding, 0::double precision) AS paidamount,payeename.company_desc,concat(encounterdoctor.first_name, ' ', encounterdoctor.last_name) AS doctor,encounterdoctor.doctor_id,vm.visit_type_name,payeename.company_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN m_organization_master org ON umm.organization_id = org.organization_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON adm.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_speciality_master sp ON sp.speciality_id = sm.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_id AND payeedetails.priority_id = 1 AND payeedetails.status = 'A'::"char"LEFT JOIN m_payment_entitlement_master ON payeedetails.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_idWHERE bm.visit_type_id &lt;&gt; 1 AND bm.outstanding &lt;&gt; 0::double precision AND bm.bill_status_id &lt;&gt; 3 AND bm.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(prefix.prefix_desc, '', pm.first_name, ' ', pm.middle_name, ' ', pm.last_name) AS patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.bill_status_id,status_master.bill_status_desc,umm.image,umm.organization_id,org.organization_name,em.encounter_number AS admission_number,m_payment_entitlement_master.payment_entitlement_id,m_payment_entitlement_master.payment_entitlement_desc,COALESCE(bm.net_amount - bm.outstanding, 0::double precision) AS paidamount,payeename.company_desc,concat(encounterdoctor.first_name, ' ', encounterdoctor.last_name) AS doctor,encounterdoctor.doctor_id,vm.visit_type_name,payeename.company_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idJOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idJOIN m_organization_master org ON umm.organization_id = org.organization_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_speciality_master sp ON sp.speciality_id = sm.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_id AND payeedetails.priority_id = 1 AND payeedetails.status = 'A'::"char"LEFT JOIN m_payment_entitlement_master ON payeedetails.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_idWHERE bm.visit_type_id = 1 AND bm.outstanding &lt;&gt; 0::double precision AND bm.bill_status_id &lt;&gt; 3 AND bm.bill_cancelled = 'N'::bpchar;

-- public.outstandingbills_bi source
CREATE OR REPLACE VIEW public.outstandingbills_biAS SELECT sum(bdet.net_amt) AS outstanding,bm.bill_date_time,sp.speciality_name,bm.visit_type_id,COALESCE(CASEWHEN bm.visit_type_id = 1 THEN spop.speciality_nameELSE spip.speciality_nameEND, 'HOSPITAL'::character varying) AS doctor_spl,COALESCE(CASEWHEN bm.visit_type_id = 1 THEN concat(docop.first_name, ' ', docop.last_name)ELSE concat(docip.first_name, ' ', docip.last_name)END, 'HOSPITAL'::text) AS doctor,bm.unit_id,sp.speciality_id,COALESCE(CASEWHEN bm.visit_type_id = 1 THEN spop.speciality_idELSE spip.speciality_idEND, 0) AS doctor_dept_id,vm.visit_type_name,COALESCE(CASEWHEN bm.visit_type_id = 1 THEN docop.doctor_idELSE docip.doctor_idEND, 0) AS doctor_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idJOIN service.m_service_master sm ON sm.service_master_id = bdet.service_idJOIN doctor.m_speciality_master sp ON sp.speciality_id = sm.speciality_idLEFT JOIN adt.t_admission ad ON ad.admission_id = bm.admission_idLEFT JOIN opd.t_encounter_master em ON em.encounter_id = bm.encounter_idLEFT JOIN doctor.m_speciality_master spop ON spop.speciality_id = em.dept_idLEFT JOIN doctor.m_speciality_master spip ON spip.speciality_id = ad.speciality_idLEFT JOIN doctor.m_doctor_master docop ON docop.doctor_id = em.doctor_idLEFT JOIN doctor.m_doctor_master docip ON docip.doctor_id = ad.doctor_idLEFT JOIN m_visit_type_master vm ON vm.visit_type_id = bm.visit_type_idWHERE bm.bill_cancelled = 'N'::bpchar AND bm.bill_status_id &lt;&gt; 3GROUP BY bm.unit_id, bm.bill_date_time, sp.speciality_name, bm.visit_type_id, spop.speciality_name, spip.speciality_name, docop.first_name, docop.last_name, docip.first_name, docip.last_name, sp.speciality_id, em.dept_id, vm.visit_type_name, docop.doctor_id, docip.doctor_id, spop.speciality_id, spip.speciality_id;

-- public.outstandingbills_company source
CREATE OR REPLACE VIEW public.outstandingbills_companyAS SELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.bill_status_id,status_master.bill_status_desc,umm.image,umm.organization_id,payeename.company_desc,payeedetails.payee_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON adm.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON adm.admission_id = sd.admission_id AND sd.status = 'A'::bpchar AND sd.priority_id = 1LEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_id AND payeedetails.payee_id &lt;&gt; 1WHERE (bm.visit_type_id = ANY (ARRAY[2, 3])) AND bm.outstanding &lt;&gt; 0::double precision AND bm.bill_status_id &lt;&gt; 3 AND bm.bill_cancelled = 'N'::bpcharUNIONSELECT DISTINCT bm.billing_master_id,bm.bill_number,bm.bill_date_time,bm.total_bill_amount,bm.concession_amount + bm.discount_amount AS totaldiscount,bm.net_amount,bm.cr_amount,bm.outstanding,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,pm.patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.bill_status_id,status_master.bill_status_desc,umm.image,umm.organization_id,payeename.company_desc,payeedetails.payee_idFROM billing.m_billing_master bmJOIN billing.t_billing_details bdet ON bm.billing_master_id = bdet.billing_master_idLEFT JOIN billing.t_payment_reciept_master reciept_master ON bm.billing_master_id = reciept_master.billing_master_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bdet.created_by = um.user_idJOIN m_unit_master umm ON bdet.unit_id = umm.unit_idJOIN patient.patientinformation pm ON bm.patient_id = pm.patient_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN doctor.m_doctor_master servicedoctor ON t_order_details.ord_doc_id = servicedoctor.doctor_idLEFT JOIN doctor.m_doctor_master encounterdoctor ON em.doctor_id = encounterdoctor.doctor_idLEFT JOIN doctor.m_sub_speciality_master ssm ON sm.sub_speciality_id = ssm.sub_speciality_idLEFT JOIN billing.m_billing_status_master status_master ON bm.bill_status_id = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON em.encounter_id = sd.encounter_id AND sd.status = 'A'::bpchar AND sd.priority_id = 1LEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN billing.t_bill_payee_details payeedetails ON bm.billing_master_id = payeedetails.bill_idLEFT JOIN t_company_master payeename ON payeename.company_id = payeedetails.payee_id AND payeedetails.payee_id &lt;&gt; 1WHERE bm.visit_type_id = 1 AND bm.outstanding &lt;&gt; 0::double precision AND bm.bill_status_id &lt;&gt; 3 AND bm.bill_cancelled = 'N'::bpchar;

-- public.package_healthplan_testcount source
CREATE OR REPLACE VIEW public.package_healthplan_testcountAS SELECT package.package_master_id,pim.uhid_number,pim.patientname,sm.service_standard_name,visit.visit_type_name,ptype.package_type,smtest.service_standard_name AS testservice,om.order_date,ssp.sub_speciality_name,om.order_id,samplemaster.sample_id,labsampledetails.test_id,testmaster.test_desc,um.unit_id,um.unit_name,um.unit_addressFROM service.m_package_master packageLEFT JOIN billing.t_package_consumption_master pcm ON package.package_master_id = pcm.package_idJOIN service.m_service_master sm ON package.service_id = sm.service_master_idLEFT JOIN patientinformation pim ON pcm.patient_id = pim.patient_idLEFT JOIN m_visit_type_master visit ON pcm.visit_type = visit.visit_type_idLEFT JOIN service.m_package_type_master ptype ON pcm.package_type_id = ptype.package_type_idLEFT JOIN t_order_details od ON pcm.order_detail_id = od.order_details_idLEFT JOIN t_order_master om ON od.order_id = om.order_idLEFT JOIN service.m_service_master smtest ON od.service_id = smtest.service_master_idLEFT JOIN doctor.m_sub_speciality_master ssp ON smtest.sub_speciality_id = ssp.sub_speciality_idLEFT JOIN lab.t_lab_sample_master samplemaster ON om.order_id = samplemaster.order_idJOIN lab.t_lab_sample_dtls labsampledetails ON samplemaster.lab_sample_id = labsampledetails.lab_sample_idLEFT JOIN lab.m_test_master testmaster ON labsampledetails.test_id = testmaster.test_idLEFT JOIN doctor.m_sub_speciality_master labsubdept ON labsampledetails.sub_dept_id = labsubdept.sub_speciality_idLEFT JOIN unitinformation um ON pcm.unit_id = um.unit_id;

-- public.pathologyreporttemplate source
CREATE OR REPLACE VIEW public.pathologyreporttemplateAS SELECT template.microbiology_template_id AS template_transaction_id,template.created_date,template.created_by,ordermaster.encounter_id,ordermaster.patient_id,template.template_object,patientinformation.uhid_number,patientinformation.patientname,patientinformation.gender_name,patientinformation.age,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,(doctormaster.first_name::text || ' '::text) || doctormaster.last_name::text AS doctorname,doctormaster.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,servicemaster.service_standard_name,m_user_master.user_name,tlsd.lab_sample_dtls_id,tm.test_alies,tlsd.sample_collection_datetime,template.report_entry_date AS result_enter_datetime,template.report_validation_date AS result_validated_datetime,lsm.sample_no,sampletype.sample_desc,patientinformation.ageyear,qm.qualification_desc,doctormaster.registration_number,tlsd.qr_imageFROM lab.t_microbiology_template templateJOIN lab.t_lab_sample_dtls tlsd ON template.lab_sample_dtls_id = tlsd.lab_sample_dtls_idLEFT JOIN lab.t_lab_sample_master lsm ON tlsd.lab_sample_id = lsm.lab_sample_idLEFT JOIN lab.m_sample_master sampletype ON tlsd.sample_type_id = sampletype.sample_idLEFT JOIN lab.m_test_master tm ON tm.test_id = tlsd.test_idLEFT JOIN m_unit_master unitinformation ON template.unit_id = unitinformation.unit_idLEFT JOIN m_user_master ON m_user_master.user_id = template.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN t_order_details orderdetail ON tlsd.order_details_id = orderdetail.order_details_idJOIN t_order_master ordermaster ON orderdetail.order_id = ordermaster.order_idJOIN patientinformation ON ordermaster.patient_id = patientinformation.patient_idLEFT JOIN doctor.m_doctor_master doctormaster ON ordermaster.ord_doctor_id = doctormaster.doctor_idLEFT JOIN m_qualification_master qm ON doctormaster.doctor_id = qm.qualification_idJOIN service.m_service_master servicemaster ON orderdetail.service_id = servicemaster.service_master_id;

-- public.patient_count_nb source
CREATE OR REPLACE VIEW public.patient_count_nbAS WITH cte AS (SELECT pt.created_date::date AS created_date,'Total'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM patient.t_patient_registration ptJOIN m_unit_master om ON pt.organization_id = om.unit_idGROUP BY (pt.created_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.encounter_date::date AS created_date,'Total Visit'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM opd.t_encounter_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idGROUP BY (pt.encounter_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.created_date::date AS created_date,'Total Admission'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM adt.t_admission ptJOIN m_unit_master om ON pt.unit_id = om.unit_idGROUP BY (pt.created_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.discharge_date::date AS created_date,'Total Discharge'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM adt.t_discharge ptJOIN m_unit_master om ON pt.unit_id = om.unit_idGROUP BY (pt.discharge_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.bill_date_time::date AS created_date,'TOTAL OP BILLS'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM billing.m_billing_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idWHERE pt.visit_type_id = 1GROUP BY (pt.bill_date_time::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.bill_date_time::date AS created_date,'TOTAL IP BILLS'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM billing.m_billing_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idWHERE pt.visit_type_id = 2GROUP BY (pt.bill_date_time::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.added_date::date AS created_date,'TOTAL OP PHARMACY BILLS'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM pharmacy.t_sale ptJOIN m_unit_master om ON pt.unit_id = om.unit_idWHERE pt.visit_type_id = 1GROUP BY (pt.added_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.added_date::date AS created_date,'TOTAL IP PHARMACY BILLS'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM pharmacy.t_sale ptJOIN m_unit_master om ON pt.unit_id = om.unit_idWHERE pt.visit_type_id = 2GROUP BY (pt.added_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.added_date::date AS created_date,'TOTAL GRN'::text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROM procurement.t_good_receipt_note ptJOIN m_unit_master om ON pt.unit_id = om.unit_idGROUP BY (pt.added_date::date), 'OP'::text, pt.unit_id, om.unit_nameUNION ALLSELECT pt.order_date::date AS created_date,'TOTAL LAB ORDER'::text AS type,count(*) AS total,1 AS srno,pt.org_unit_id,om.unit_nameFROM t_order_details ptJOIN m_unit_master om ON pt.org_unit_id = om.unit_idWHERE (pt.service_id IN ( SELECT msm.service_master_idFROM service.m_service_master msmWHERE msm.speciality_id = (( SELECT tlc.lab_speciality_idFROM t_lab_configuration tlcWHERE tlc.unit_id = pt.org_unit_id))))GROUP BY (pt.order_date::date), 'OP'::text, pt.org_unit_id, om.unit_nameUNION ALLSELECT pt.order_date::date AS created_date,'TOTAL RIS ORDER'::text AS type,count(*) AS total,1 AS srno,pt.org_unit_id,om.unit_nameFROM t_order_details ptJOIN m_unit_master om ON pt.org_unit_id = om.unit_idWHERE (pt.service_id IN ( SELECT msm.service_master_idFROM service.m_service_master msmWHERE msm.speciality_id = (( SELECT tlc.radiology_speciality_idFROM t_unit_application_billing_configuration tlcWHERE tlc.unit_id = pt.org_unit_id))))GROUP BY (pt.order_date::date), 'OP'::text, pt.org_unit_id, om.unit_name)SELECT created_date,type,total,srno,unit_id,unit_nameFROM cteWHERE created_date = '2023-09-18'::date AND unit_id = 11ORDER BY srno;

-- public.patient_ledger source
CREATE OR REPLACE VIEW public.patient_ledgerAS SELECT 1 AS rno,'Appointment'::text AS lebel,am.patient_id,am.token_number::character varying AS receiptno,am.appointment_date AS trdate,0 AS amount,am.unit_idFROM opd.m_appointment_master amUNIONSELECT 2 AS rno,'Encounter'::text AS lebel,em.patient_id,em.encounter_number AS receiptno,em.encounter_date AS trdate,0 AS amount,em.unit_idFROM opd.t_encounter_master emUNIONSELECT 3 AS rno,'Deposit'::text AS lebel,dm.patient_id,dm.deposit_no AS receiptno,dm.deposit_date AS trdate,dm.deposit_amount AS amount,dm.unit_idFROM billing.m_deposit_master dmUNIONSELECT 4 AS rno,'OPBILL'::text AS lebel,bm.patient_id,bm.bill_number AS receiptno,bm.bill_date_time AS trdate,bm.net_amount AS amount,bm.unit_idFROM billing.m_billing_master bmWHERE bm.is_dr_note = 'N'::bpchar AND bm.visit_type_id = 1UNIONSELECT 5 AS rno,'IPBILL'::text AS lebel,bm.patient_id,bm.bill_number AS receiptno,bm.bill_date_time AS trdate,bm.net_amount AS amount,bm.unit_idFROM billing.m_billing_master bmWHERE bm.is_dr_note = 'N'::bpchar AND bm.visit_type_id = 2UNIONSELECT 6 AS rno,'Credit Note'::text AS lebel,bm.patient_id,crnote.credit_note_no AS receiptno,crnote.credit_note_date AS trdate,crnote.cr_net_amount AS amount,crnote.unit_idFROM billing.m_credit_note_master crnoteJOIN billing.m_billing_master bm ON crnote.bill_id = bm.billing_master_idUNIONSELECT 7 AS rno,'Debit Note'::text AS lebel,bm.patient_id,bm.bill_number AS receiptno,bm.bill_date_time AS trdate,bm.net_amount AS amount,bm.unit_idFROM billing.m_billing_master bmWHERE (bm.billing_master_id IN ( SELECT bm_1.billing_master_idFROM billing.m_billing_master bm_1)) AND bm.is_dr_note = 'Y'::bpcharUNIONSELECT 8 AS rno,'Payments'::text AS lebel,bm.patient_id,prm.reciept_number AS receiptno,prm.date_of_reciept AS trdate,prm.amount,prm.unit_idFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idUNIONSELECT 9 AS rno,'Sales'::text AS lebel,sales.patient_id,sales.bill_no AS receiptno,sales.added_date AS trdate,sales.net_amount AS amount,sales.unit_idFROM pharmacy.t_sale salesUNIONSELECT 10 AS rno,'Sales Return'::text AS lebel,sales.patient_id,rn.return_no AS receiptno,rn.added_date AS trdate,rn.total_return_amt AS amount,rn.unit_idFROM pharmacy.t_return rnJOIN pharmacy.t_sale sales ON rn.sale_id = sales.idORDER BY 1, 5;

-- public.patient_return_acceptance source
CREATE OR REPLACE VIEW public.patient_return_acceptanceAS SELECT DISTINCT pir.id,pir.return_no AS bill_no,pir.added_date,COALESCE(pird.accept_qty, 0) AS quantity,batch.rate,CASEWHEN mapper.uom_type_id = 1 THEN (COALESCE(uom1.conversions, 1) * COALESCE(uom2.conversions, 1) * COALESCE(uom3.conversions, 1))::double precision * batch.rateWHEN mapper.uom_type_id = 2 THEN (COALESCE(uom1.conversions, 1) * COALESCE(uom2.conversions, 1))::double precision * batch.rateWHEN mapper.uom_type_id = 3 THEN COALESCE(uom2.conversions, 1)::double precision * batch.rateELSE NULL::double precisionEND AS total_amount_details,0 AS tax_percentage,0 AS tax_amount_detail,0 AS discount_amount,0 AS net_amount_detail,0 AS cop,m_item.name,batch.batch_no,batch.expiry_date,unitinformation.unit_name,unitinformation.unit_address,m_item.id AS itemid,unitinformation.unit_id,unitinformation.image,concat(pim.first_name, ' ', pim.last_name) AS patientname,'Patient Return Acceptance'::text AS lebel,m_store.store_id,m_store.store_name,pird.id AS detailid,2 AS orderid,COALESCE(tss.available_qty, 0) AS available_qty,mapper.batch_id,tss.t_qty,pim.mobile_number,CASEWHEN pim.gender_id = 1 THEN 'Male'::textELSE 'Female'::textEND AS gender,abs(date_part('Year'::text, age(to_char(pim.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,pim.uhid_number,concat('Dr.', '', dm.first_name, ' ', dm.last_name) AS doctor,cm.company_desc,cm.address AS comadderess,ta.admission_number,mwm.ward_name AS billing_bed_desc,mbm.bed_desc,m_item.code,mfc.name AS mfcname,msm.schedule_description,COALESCE(pird.return_qty, 0) AS return_qty,COALESCE(pird.reject_qty, 0) AS reject_qty,concat(emp.first_name, ' ', emp.last_name) AS emp,concat(empupdated.first_name, ' ', empupdated.last_name) AS empupdated,pir.status_idFROM pharmacy.t_patient_issue_return pirJOIN pharmacy.t_patient_issue_return_detail pird ON pir.id = pird.patient_issue_return_idLEFT JOIN adt.t_admission ta ON ta.admission_id = pir.admission_idLEFT JOIN adt.t_admission_details admd ON ta.admission_id = admd.admission_id AND admd.status = 'A'::bpcharLEFT JOIN adt.m_ward_master mwm ON mwm.ward_id = admd.ward_idLEFT JOIN adt.m_bed_master mbm ON admd.bed_id = mbm.bed_idLEFT JOIN patient.t_patient_registration pim ON ta.patient_id = pim.patient_idLEFT JOIN pharmacy.t_issue_detail_batch_mapper mapper ON pird.issue_batch_mapper_id = mapper.idJOIN pharmacy.t_issue_detail issuedetails ON issuedetails.id = mapper.issue_detail_idJOIN inventory.t_batch batch ON mapper.batch_id = batch.idLEFT JOIN m_item ON batch.item_id = m_item.idLEFT JOIN m_unit_of_measurement uom1 ON uom1.uom_type_id = 1 AND batch.item_id = uom1.item_idLEFT JOIN m_unit_of_measurement uom2 ON uom2.uom_type_id = 2 AND batch.item_id = uom2.item_idLEFT JOIN m_unit_of_measurement uom3 ON uom3.uom_type_id = 3 AND batch.item_id = uom3.item_idLEFT JOIN m_manufacturer mfc ON m_item.manufacturer_id = mfc.idLEFT JOIN m_unit_master unitinformation ON pir.unit_id = unitinformation.unit_idLEFT JOIN m_store ON pir.store_id = m_store.store_idLEFT JOIN m_user_master um ON pir.added_by = um.user_idLEFT JOIN m_employee_master emp ON um.user_id = emp.user_idLEFT JOIN m_user_master umupdated ON pir.updated_by = umupdated.user_idLEFT JOIN m_employee_master empupdated ON umupdated.user_id = empupdated.user_idLEFT JOIN m_generic generic ON m_item.generic_id = generic.idLEFT JOIN pharmacy.m_generic_schedule_master gsm ON generic.id = gsm.generic_idLEFT JOIN pharmacy.m_schedule_master msm ON gsm.schedule_id = msm.schedule_idLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idLEFT JOIN inventory.t_store_stock tss ON batch.id = tss.batch_id AND tss.store_id = m_store.store_idLEFT JOIN opd.t_patient_sponsor_details spd ON pir.admission_id = spd.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharLEFT JOIN t_company_master cm ON spd.payee_id = cm.company_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharWHERE pir.is_deleted = false AND pir.is_active = true AND pird.is_active = true;

-- public.patient_to_nurse source
CREATE OR REPLACE VIEW public.patient_to_nurseAS SELECT ward_name,admitted,critical,dis,newpat,doa,discharge_date,unit_idFROM ( SELECT wm.ward_name,count(*) AS admitted,COALESCE(er.critical, 0::bigint) AS critical,COALESCE(dis.dis, 0::bigint) AS dis,COALESCE(newpat.newpat, 0::bigint) AS newpat,ta.unit_id,tad.doa,dis.discharge_dateFROM adt.t_admission taJOIN adt.t_admission_details tad ON ta.admission_id = tad.admission_idJOIN adt.m_ward_master wm ON wm.ward_id = tad.ward_idLEFT JOIN ( SELECT count(*) AS critical,wm_1.ward_name,ta_1.admission_id,ta_1.unit_id,tad_1.doaFROM adt.t_admission ta_1JOIN adt.t_admission_details tad_1 ON ta_1.admission_id = tad_1.admission_idJOIN adt.m_ward_master wm_1 ON wm_1.ward_id = tad_1.ward_idWHERE ta_1.visit_type_id = 4 AND tad_1.admission_details_id = (( SELECT max(tad_2.admission_details_id) AS maxFROM adt.t_admission_details tad_2WHERE tad_2.admission_id = ta_1.admission_id))GROUP BY wm_1.ward_name, ta_1.admission_id, tad_1.doa) er ON er.admission_id = ta.admission_id AND er.unit_id = ta.unit_idLEFT JOIN ( SELECT count(*) AS dis,wm_1.ward_name,d.discharge_date,taa.unit_idFROM adt.t_admission taaJOIN adt.t_admission_details tad_1 ON taa.admission_id = tad_1.admission_idJOIN adt.m_ward_master wm_1 ON wm_1.ward_id = tad_1.ward_idJOIN adt.t_discharge d ON d.admission_id = taa.admission_idWHERE tad_1.admission_details_id = (( SELECT max(tad_2.admission_details_id) AS maxFROM adt.t_admission_details tad_2WHERE tad_2.admission_id = taa.admission_id)) AND d.discharge_id = (( SELECT max(t_discharge.discharge_id) AS maxFROM adt.t_dischargeWHERE t_discharge.admission_id = taa.admission_id))GROUP BY wm_1.ward_name, d.discharge_date, taa.unit_id) dis ON dis.ward_name::text = wm.ward_name::text AND dis.unit_id = ta.unit_idLEFT JOIN ( SELECT count(*) AS newpat,tanew.patient_id,wmnew.ward_name,tanew.unit_id,tadnew.doaFROM adt.t_admission tanewJOIN adt.t_admission_details tadnew ON tanew.admission_id = tadnew.admission_idJOIN adt.m_ward_master wmnew ON wmnew.ward_id = tadnew.ward_idWHERE tadnew.admission_details_id = (( SELECT max(tad_1.admission_details_id) AS maxFROM adt.t_admission_details tad_1WHERE tad_1.admission_id = tadnew.admission_id))GROUP BY tanew.patient_id, wmnew.ward_name, tanew.unit_id, tadnew.doaHAVING count(*) &lt; 2) newpat ON newpat.ward_name::text = wm.ward_name::text AND newpat.unit_id = ta.unit_idWHERE tad.admission_details_id = (( SELECT max(tad_1.admission_details_id) AS maxFROM adt.t_admission_details tad_1WHERE tad_1.admission_id = ta.admission_id))GROUP BY wm.ward_name, er.critical, dis.dis, newpat.newpat, ta.unit_id, tad.doa, dis.discharge_date) abc;

-- public.patientadvancereport source
CREATE OR REPLACE VIEW public.patientadvancereportAS SELECT DISTINCT um.unit_name,um.unit_address,um.registration_number,um.unit_contact,um.unit_contact_2,um.unit_country_code,cm.currency_name,cm.sub_currency,pr.patient_id,pr.uhid_number,dep.admission_id,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS patientname,dep.deposit_date::date AS date,dep.deposit_master_id AS depositid,dep.org_id AS orgid,dep.unit_id AS unitid,userm.user_id,userm.user_name,dep.visit_type_id,COALESCE(advamount(depdt.deposit_details_id, 1), 0::double precision) AS cash,COALESCE(advamount(depdt.deposit_details_id, 2), 0::double precision) AS cheque,COALESCE(advamount(depdt.deposit_details_id, 3), 0::double precision) AS credit_card,COALESCE(advamount(depdt.deposit_details_id, 4), 0::double precision) AS debit_card,counter.counter_desc,deptype.deposite_type_desc::text AS diposittype,um.unit_address_2,COALESCE(advamount(depdt.deposit_details_id, 6), 0::double precision) AS loyalty_card,COALESCE(advamount(depdt.deposit_details_id, 5), 0::double precision) AS mpesa,COALESCE(advamount(depdt.deposit_details_id, 8), 0::double precision) AS etransfer,0 AS payment_mode_id,dep.deposit_no,um.image,depdt.deposit_details_id,concat(emp.first_name, ' ', emp.last_name) AS emp,dep.remarks,COALESCE(advamount(depdt.deposit_details_id, 7), 0::double precision) AS availablefundFROM patient.t_patient_registration prLEFT JOIN billing.m_deposit_master dep ON pr.patient_id = dep.patient_idJOIN billing.t_payment_deposit_details depdt ON depdt.deposit_id = dep.deposit_master_idLEFT JOIN m_payment_mode_master pmode ON pmode.payment_mode_id = depdt.payment_mode_idJOIN m_unit_master um ON um.unit_id = dep.unit_idLEFT JOIN billing.m_deposite_type_master deptype ON deptype.deposite_type_id = dep.deposit_type_idLEFT JOIN m_currency_master cm ON cm.unit_id = um.unit_idLEFT JOIN m_user_master userm ON dep.created_by = userm.user_idLEFT JOIN m_employee_master emp ON emp.user_id = userm.user_idLEFT JOIN m_counter_master counter ON dep.counter_id = counter.counter_id;

-- public.patientdetails source
CREATE OR REPLACE VIEW public.patientdetailsAS SELECT t_patient_registration.prefix_id,t_patient_registration.uhid_number,pim.patientname,m_gender_master.gender_name,t_patient_registration.bar_code,age(t_patient_registration.dob) AS age,t_patient_registration.mobile_number,t_patient_registration.email,t_patient_registration.patient_id,t_encounter_master.encounter_id,um.unit_id,um.unit_address_2,um.unit_address,um.unit_name,((('Dr. '::text || ''::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS consultant,date_part('Year'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone))::integer AS ageyear,m_speciality_master.speciality_name,t_encounter_master.encounter_number,um.unit_contact,um.unit_email_id,um.unit_website,t_encounter_master.encounter_date,um.image,abs(date_part('month'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(CURRENT_TIMESTAMP, t_patient_registration.dob::timestamp with time zone)))::integer AS ageday,dm.doctor_id,qualification.qualification_desc,deg.degree_desc,dm.registration_numberFROM patient.t_patient_registrationJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idJOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idJOIN opd.t_encounter_master ON t_patient_registration.patient_id = t_encounter_master.patient_idJOIN m_unit_master um ON um.unit_id = t_encounter_master.unit_idLEFT JOIN doctor.m_doctor_master dm ON t_encounter_master.doctor_id = dm.doctor_idLEFT JOIN doctor.t_doctor_doc_mapper qualification ON dm.doctor_id = qualification.doctor_id AND qualification.status = 'A'::bpcharLEFT JOIN m_degree_master deg ON qualification.degree_id = deg.degree_id AND deg.status = 'A'::bpcharLEFT JOIN patientinformation pim ON t_encounter_master.patient_id = pim.patient_idLEFT JOIN doctor.m_speciality_master ON t_encounter_master.dept_id = m_speciality_master.speciality_id;

-- public.patientdetailsipd source
CREATE OR REPLACE VIEW public.patientdetailsipdAS SELECT DISTINCT t_patient_registration.prefix_id,t_patient_registration.uhid_number,(((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,m_gender_master.gender_name,t_patient_registration.bar_code,age(t_patient_registration.dob) AS age,t_patient_registration.mobile_number,t_patient_registration.email,t_patient_registration.patient_id,t_admission.admission_id,t_patient_registration.unit_id,um.unit_address_2,um.unit_address,um.unit_name,abs(date_part('Year'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(t_patient_registration.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,((('Dr.'::text || ' '::text) || dmt.first_name::text) || ' '::text) || dmt.last_name::text AS doctornametreating,um.unit_contact,um.unit_email_id,um.unit_website,t_admission.admission_number,t_admission.created_date,m_bed_master.bed_desc,((('Dr.'::text || ' '::text) || refdoctor.first_name::text) || ' '::text) || refdoctor.last_name::text AS refdoctor,t_admission.visit_type_id,rm.relation_name,kd.kin_name,patinfo.patientaddress,wm.ward_name,discharge.discharge_date,discharge.discharge_time,um.imageFROM patient.t_patient_registrationLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idJOIN adt.t_admission ON t_patient_registration.patient_id = t_admission.patient_idLEFT JOIN patientinformation patinfo ON t_patient_registration.patient_id = patinfo.patient_idJOIN m_unit_master um ON um.unit_id = t_admission.unit_idLEFT JOIN doctor.m_doctor_master dm ON t_admission.admitting_doctor_id = dm.doctor_idLEFT JOIN doctor.m_doctor_master dmt ON t_admission.doctor_id = dmt.doctor_idJOIN adt.t_admission_details ON t_admission.admission_id = t_admission_details.admission_idLEFT JOIN adt.m_bed_master ON t_admission_details.bed_id = m_bed_master.bed_idLEFT JOIN opd.t_consult_doctor cd ON t_admission.admission_id = cd.admission_idLEFT JOIN doctor.m_doctor_master refdoctor ON cd.ref_to_doctor_id = refdoctor.doctor_idLEFT JOIN m_kin_details kd ON kd.patient_id = t_admission.patient_idLEFT JOIN m_relation_master rm ON kd.relation_id = rm.relation_idLEFT JOIN adt.m_ward_master wm ON t_admission_details.ward_id = wm.ward_idLEFT JOIN ( SELECT max(t_discharge.admission_id) AS admission_id,t_discharge.discharge_date,t_discharge.discharge_timeFROM adt.t_dischargeGROUP BY t_discharge.discharge_date, t_discharge.discharge_timeORDER BY t_discharge.discharge_date) discharge ON t_admission.admission_id = discharge.admission_idWHERE t_admission_details.admission_details_id = (( SELECT t_admission_details_1.admission_details_idFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = t_admission.admission_idORDER BY t_admission_details_1.admission_details_id DESCLIMIT 1));
-- public.patientinformation source
CREATE OR REPLACE VIEW public.patientinformationAS SELECT DISTINCT COALESCE(t_patient_registration.prefix_id, 0) AS prefix_id,t_patient_registration.uhid_number,concat(COALESCE(m_prefix_master.prefix_desc, ''::character varying::text), ' ', COALESCE(t_patient_registration.first_name, ''::character varying), ' ', COALESCE(t_patient_registration.middle_name, ''::character varying), ' ', COALESCE(t_patient_registration.last_name, ''::character varying)) AS patientname,m_gender_master.gender_name,t_patient_registration.bar_code,age(t_patient_registration.dob) AS age,t_patient_registration.mobile_number,t_patient_registration.email,t_patient_registration.mobile_number AS patientmobile,t_patient_registration.email AS patientemail,m_patient_registration_type_master.reg_type,m_gender_master.gender_name AS patientgender,m_patient_category_master.patient_category,t_patient_registration.created_date AS regdate,t_patient_registration.is_vip,t_patient_registration.dob AS patientdob,t_patient_registration.identification_number,t_patient_registration.identification_expiry_date,t_patient_details.address AS patientaddress,t_patient_details.zip_code,t_patient_details.phone_number,t_patient_registration.patient_id,m_marital_status_master.marital_status_name,m_occupation_master.occupation_name,'\x'::bytea AS image,m_unit_master.unit_name,m_unit_master.unit_address,m_gender_master.gender_id,abs(date_part('Year'::text, age(to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageyear,t_patient_registration.image AS patientimage,createbarcodecode128(t_patient_registration.patient_id::character varying) AS barcode,abs(date_part('Month'::text, age(to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(to_char(t_patient_registration.dob, 'YYYY-MM-DD'::text)::timestamp with time zone)))::integer AS ageday,m_unit_master.unit_id,distmaster.district_name,m_city_master.city_nameFROM patient.t_patient_registrationJOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idJOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_patient_category_master ON t_patient_registration.patient_category_id = m_patient_category_master.patient_category_idLEFT JOIN patient.m_patient_registration_type_master ON t_patient_registration.registration_type_id = m_patient_registration_type_master.idJOIN patient.t_patient_details ON t_patient_registration.patient_id = t_patient_details.patient_idLEFT JOIN m_marital_status_master ON t_patient_details.marital_status_id = m_marital_status_master.marital_status_idLEFT JOIN m_occupation_master ON t_patient_registration.occupation_id = m_occupation_master.occupation_idLEFT JOIN m_district_master distmaster ON t_patient_details.district_id = distmaster.district_idLEFT JOIN m_unit_master ON t_patient_registration.unit_id = m_unit_master.unit_idLEFT JOIN m_city_master ON m_city_master.city_id = t_patient_details.city_id;

-- public.pendinglabtest source
CREATE OR REPLACE VIEW public.pendinglabtestAS SELECT DISTINCT sample_dtls.sample_status_id,sample_dtls.test_id,testmaster.test_desc,sample_dtls.sample_collection_datetime,sample_dtls.org_unit_id,um.unit_name,um.unit_address,um.unit_id,'\x'::bytea AS image,um.unit_contact,um.unit_website,um.unit_email_id,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.last_name) AS patientname,pim.uhid_number,'IPD'::text AS opipno,tom.order_date,pim.patient_id,concat('Dr.', adm_doc.first_name, ' ', adm_doc.last_name) AS adm_en_doc,visit.visit_type_code,visit.visit_type_id,wm.ward_id,wm.ward_nameFROM lab.t_lab_sample_dtls sample_dtlsJOIN lab.m_test_master testmaster ON sample_dtls.test_id = testmaster.test_idJOIN patient.t_patient_registration pim ON pim.patient_id = sample_dtls.patient_idJOIN t_order_master tom ON tom.order_id = sample_dtls.order_idJOIN m_visit_type_master visit ON visit.visit_type_id = tom.visit_type_idJOIN m_prefix_master prefix ON pim.prefix_id = prefix.prefix_idJOIN m_unit_master um ON sample_dtls.org_unit_id = um.unit_idJOIN adt.t_admission adm ON tom.admission_id = adm.admission_idJOIN adt.t_admission_details admd ON admd.admission_id = adm.admission_idJOIN adt.m_ward_master wm ON wm.ward_id = admd.ward_idJOIN doctor.m_doctor_master adm_doc ON adm.doctor_id = adm_doc.doctor_idWHERE sample_dtls.sample_status_id = 2 AND tom.visit_type_id &lt;&gt; 1 AND admd.admission_details_id = (( SELECT max(t_admission_details.admission_details_id) AS admission_details_idFROM adt.t_admission_detailsWHERE t_admission_details.admission_id = adm.admission_id))UNION ALLSELECT DISTINCT sample_dtls.sample_status_id,sample_dtls.test_id,testmaster.test_desc,sample_dtls.sample_collection_datetime,sample_dtls.org_unit_id,um.unit_name,um.unit_address,um.unit_id,'\x'::bytea AS image,um.unit_contact,um.unit_website,um.unit_email_id,concat(prefix.prefix_desc, '', pim.first_name, ' ', pim.last_name) AS patientname,pim.uhid_number,'OPD'::text AS opipno,tom.order_date,pim.patient_id,concat('Dr.', en_doc.first_name, ' ', en_doc.last_name) AS adm_en_doc,visit.visit_type_code,visit.visit_type_id,0 AS ward_id,''::text AS ward_nameFROM lab.t_lab_sample_dtls sample_dtlsJOIN lab.m_test_master testmaster ON sample_dtls.test_id = testmaster.test_idJOIN patient.t_patient_registration pim ON pim.patient_id = sample_dtls.patient_idJOIN t_order_master tom ON tom.order_id = sample_dtls.order_idJOIN m_visit_type_master visit ON visit.visit_type_id = tom.visit_type_idJOIN m_prefix_master prefix ON pim.prefix_id = prefix.prefix_idJOIN m_unit_master um ON sample_dtls.org_unit_id = um.unit_idJOIN opd.t_encounter_master em ON tom.encounter_id = em.encounter_idJOIN doctor.m_doctor_master en_doc ON en_doc.doctor_id = em.doctor_idWHERE sample_dtls.sample_status_id = 2 AND tom.visit_type_id = 1;

-- public.pharmacycollectionsummary source
CREATE OR REPLACE VIEW public.pharmacycollectionsummaryAS SELECT get_pharmacycollection.id::integer AS deposit_master_id,get_pharmacycollection.salestype AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,get_pharmacycollection.username::character varying(100) AS user_name,get_pharmacycollection.user_id,get_pharmacycollection.unit_id,get_pharmacycollection.organization_id,get_pharmacycollection.unit_name,get_pharmacycollection.patientname,get_pharmacycollection.patient_id,get_pharmacycollection.temp_uhid AS uhid_number,get_pharmacycollection.receiptdate AS depositdate,get_pharmacycollection.unit_address,''::text AS unit_contact_2,''::character varying(200) AS unit_contact,COALESCE(get_pharmacycollection.cashamount, 0::bigint::double precision) AS cash,COALESCE(get_pharmacycollection.chequeamount, 0::bigint) AS cheque,COALESCE(get_pharmacycollection.creditcardamount, 0::bigint) AS creditcard,COALESCE(get_pharmacycollection.debitcardamount, 0::bigint) AS debitcard,0 AS patadvused,0 AS tdsamt,'Income'::text AS amttype,get_pharmacycollection.bill_no AS reciptno,COALESCE(get_pharmacycollection.counter_id, 0) AS counter_id,''::character varying(50) AS counter_desc,0 AS mpesa,0 AS loyaltycard,COALESCE(get_pharmacycollection.e_transfer, 0::bigint) AS e_transfer,0 AS availablefund,0 AS doctorcredit,0 AS total_bill_amount,0 AS discount_amount,0 AS net_amount,0 AS outstanding,''::text AS transaction_type_desc,get_pharmacycollection.receiptdate::date AS bill_date_time,''::character varying AS referral_name,get_pharmacycollection.receiptdate::time without time zone AS trantime,get_pharmacycollection.receiptdate::date AS trantime1,''::character varying AS adm_visit_noFROM get_pharmacycollectionWHERE get_pharmacycollection.salestype = 'Sales'::textUNION ALLSELECT get_pharmacycollection.id::integer AS deposit_master_id,get_pharmacycollection.salestype AS deposit,'Other'::character varying AS visit_type_code,0 AS visit_type_id,get_pharmacycollection.username::character varying(100) AS user_name,get_pharmacycollection.user_id,get_pharmacycollection.unit_id,get_pharmacycollection.organization_id,get_pharmacycollection.unit_name,get_pharmacycollection.patientname,get_pharmacycollection.patient_id,get_pharmacycollection.temp_uhid AS uhid_number,get_pharmacycollection.receiptdate AS depositdate,get_pharmacycollection.unit_address,''::text AS unit_contact_2,''::character varying(200) AS unit_contact,COALESCE(get_pharmacycollection.cashamount, 0::bigint::double precision) AS cash,COALESCE(get_pharmacycollection.chequeamount, 0::bigint) AS cheque,COALESCE(get_pharmacycollection.creditcardamount, 0::bigint) AS creditcard,COALESCE(get_pharmacycollection.debitcardamount, 0::bigint) AS debitcard,0 AS patadvused,0 AS tdsamt,'Refund'::text AS amttype,get_pharmacycollection.bill_no AS reciptno,COALESCE(get_pharmacycollection.counter_id, 0) AS counter_id,''::character varying(50) AS counter_desc,0 AS mpesa,0 AS loyaltycard,COALESCE(get_pharmacycollection.e_transfer, 0::bigint) AS e_transfer,0 AS availablefund,0 AS doctorcredit,0 AS total_bill_amount,0 AS discount_amount,0 AS net_amount,0 AS outstanding,''::text AS transaction_type_desc,get_pharmacycollection.receiptdate::date AS bill_date_time,''::character varying AS referral_name,get_pharmacycollection.receiptdate::time without time zone AS trantime,get_pharmacycollection.receiptdate::date AS trantime1,''::character varying AS adm_visit_noFROM get_pharmacycollectionWHERE get_pharmacycollection.salestype = 'Sales Return'::text;

-- public.pl_admission source
CREATE OR REPLACE VIEW public.pl_admissionAS SELECT adm.admission_number,adm.created_date AS admdate,((('Dr.'::text || ' '::text) || dm.first_name::text) || ' '::text) || dm.last_name::text AS doctorname,((('Dr.'::text || ' '::text) || dmt.first_name::text) || ' '::text) || dmt.last_name::text AS doctornametreating,m_bed_master.bed_desc,ward.ward_name,admtype.admission_type_desc,admdetails.is_medico_legal,adm.patient_id,visit.visit_type_nameFROM adt.t_admission admLEFT JOIN doctor.m_doctor_master dm ON adm.admitting_doctor_id = dm.doctor_idLEFT JOIN doctor.m_doctor_master dmt ON adm.doctor_id = dmt.doctor_idJOIN adt.t_admission_details admdetails ON adm.admission_id = admdetails.admission_idLEFT JOIN adt.m_bed_master ON admdetails.bed_id = m_bed_master.bed_idLEFT JOIN adt.m_ward_master ward ON admdetails.ward_id = ward.ward_idLEFT JOIN adt.m_admission_type_master admtype ON admdetails.admission_type_id = admtype.admission_type_idLEFT JOIN m_visit_type_master visit ON adm.visit_type_id = visit.visit_type_idWHERE admdetails.admission_details_id = (( SELECT t_admission_details_1.admission_details_idFROM adt.t_admission_details t_admission_details_1WHERE t_admission_details_1.admission_id = adm.admission_idORDER BY t_admission_details_1.admission_details_id DESCLIMIT 1));
-- public.pl_appointment source
CREATE OR REPLACE VIEW public.pl_appointmentAS SELECT 1 AS rno,'Appointment'::text AS lebel,am.patient_id,am.token_number::character varying AS receiptno,am.appointment_date AS trdate,0 AS amount,am.unit_id,sm.from_time,sm.to_time,daym.day,concat('Dr.', ' ', docmaster.first_name, ' ', docmaster.last_name) AS doctername,speciality.speciality_name,slotstatus.slot_status_descFROM opd.m_appointment_master amJOIN opd.m_slot_master sm ON am.slot_id = sm.slot_idLEFT JOIN m_day_master daym ON sm.day_id = daym.day_idLEFT JOIN doctor.m_doctor_master docmaster ON sm.doctor_id = docmaster.doctor_idLEFT JOIN doctor.m_speciality_master speciality ON sm.speciality_id = speciality.speciality_idLEFT JOIN opd.m_slot_status_master slotstatus ON sm.slot_status_id = slotstatus.slot_status_id;

-- public.pl_bills source
CREATE OR REPLACE VIEW public.pl_billsAS SELECT 4 AS rno,visittype.visit_type_name AS lebel,bm.patient_id,bm.bill_number AS receiptno,bm.bill_date_time AS trdate,bm.net_amount,bm.unit_id,bm.total_bill_amount,bm.discount_amount,bm.concession_amount,bm.gst,billstatus.bill_status_desc,bm.bill_cancelled,bm.is_intermediate_billFROM billing.m_billing_master bmJOIN billing.m_billing_status_master billstatus ON bm.bill_status_id = billstatus.bill_status_idLEFT JOIN m_visit_type_master visittype ON bm.visit_type_id = visittype.visit_type_idWHERE bm.is_dr_note = 'N'::bpchar;

-- public.pl_creditnote source
CREATE OR REPLACE VIEW public.pl_creditnoteAS SELECT 6 AS rno,'Credit Note'::text AS lebel,bm.patient_id,crnote.credit_note_no AS receiptno,crnote.credit_note_date AS trdate,crnote.cr_net_amount,crnote.unit_id,bm.bill_number,crnote.cr_total_amount,crnote.cr_tax_amount,crnote.cr_deu_amount,sm.service_standard_name,bdm.rate,bdm.quantity,bdm.net_amt,bdm.gross_amount,crnotedetail.cr_net_amount AS cr_net_amount_detailsFROM billing.m_credit_note_master crnoteJOIN billing.m_billing_master bm ON crnote.bill_id = bm.billing_master_idJOIN billing.t_credit_note_detail crnotedetail ON crnote.credit_note_id = crnotedetail.credit_note_idLEFT JOIN billing.t_billing_details bdm ON crnotedetail.billing_details_id = bdm.billing_details_idLEFT JOIN service.m_service_master sm ON bdm.service_id = sm.service_master_idLEFT JOIN billing.t_credit_note_discount_detail cndd ON crnotedetail.billing_details_id = cndd.credit_note_detail_idLEFT JOIN t_company_master tcm ON crnote.bill_payee_id = tcm.company_id;

-- public.pl_debitnote source
CREATE OR REPLACE VIEW public.pl_debitnoteAS SELECT 7 AS rno,'Debit Note'::text AS lebel,bm.patient_id,bm.bill_number AS receiptno,bm.bill_date_time AS trdate,bm.net_amount AS amount,bm.unit_id,sm.service_standard_name,bd.rate,bd.quantity,bd.net_amt,bd.gross_amountFROM billing.m_billing_master bmJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idWHERE bm.is_dr_note = 'Y'::bpchar;

-- public.pl_deposit source
CREATE OR REPLACE VIEW public.pl_depositAS SELECT 3 AS rno,'Deposit'::text AS lebel,dm.patient_id,dm.deposit_no AS receiptno,dm.deposit_date AS trdate,dm.unit_id,cm.company_desc,deposittype.deposite_type_desc,dm.deposit_amount,dm.available_deposit,dm.consumed_deposit,dm.remarks,paymode.payment_mode_desc,depositpay.amount,bank.bank_desc,depositpay.account_number,depositpay.cheque_date,depositpay.cheque_number,depositpay.card_no,depositpay.card_holder_name,depositpay.expiry_date,cardtype.card_type_name,dm.refund_amountFROM billing.m_deposit_master dmLEFT JOIN m_visit_type_master visittype ON dm.visit_type_id = visittype.visit_type_idLEFT JOIN t_company_master cm ON dm.payee_id = cm.company_idLEFT JOIN billing.m_deposite_type_master deposittype ON dm.deposit_type_id = deposittype.deposite_type_idJOIN billing.t_payment_deposit_details depositpay ON dm.deposit_master_id = depositpay.deposit_idLEFT JOIN m_payment_mode_master paymode ON depositpay.payment_mode_id = paymode.payment_mode_idLEFT JOIN billing.m_bank_master bank ON depositpay.bank_id = bank.bank_idLEFT JOIN billing.m_card_type_master cardtype ON depositpay.card_type_id = cardtype.card_type_id;

-- public.pl_encounter source
CREATE OR REPLACE VIEW public.pl_encounterAS SELECT 2 AS rno,'Encounter'::text AS lebel,em.patient_id,em.encounter_number AS receiptno,em.encounter_date AS trdate,0 AS amount,em.unit_id,concat(dm.first_name, ' ', dm.last_name) AS doctername,sm.speciality_name,em.user_defined_visit_type_idFROM opd.t_encounter_master emLEFT JOIN doctor.m_speciality_master sm ON em.dept_id = sm.speciality_idLEFT JOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_id;

-- public.pl_payments source
CREATE OR REPLACE VIEW public.pl_paymentsAS SELECT 8 AS rno,'Payments'::text AS lebel,bm.patient_id,prm.reciept_number AS receiptno,prm.date_of_reciept AS trdate,prm.amount,prm.unit_id,prm.receipt_type,prm.received_from,prm.remark,prm.status AS payment_status,prm.created_date AS payment_created_date,bm.bill_number,bm.bill_date_time,bm.net_amount,bm.discount_amount,bm.created_date,bm.concession_amount,bm.gst,bm.total_bill_amount,bm.settlement_date,bm.bill_cancelled,bm.bill_cancel_reason_id,bm.bill_cancel_datetime,bm.bill_cancel_by,bm.bill_cancel_remark,bm.is_interim_or_final_bill,m_payment_mode_master.payment_mode_desc,prd.payment_mode_id,prd.amount AS paymentamount,m_bank_master.bank_name,prd.check_number,prd.cheque_date,prd.card_holder_name,prd.date_of_transaction,prd.card_number,prd.expiry_date,m_visit_type_master.visit_type_name,prd.transaction_no,prm.payment_reciept_idFROM billing.t_payment_reciept_master prmJOIN billing.t_payment_reciept_details prd ON prm.payment_reciept_id = prd.payment_receipt_master_idJOIN billing.m_billing_master bm ON prm.billing_master_id = bm.billing_master_idLEFT JOIN m_payment_mode_master ON prd.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN billing.m_bank_master ON prd.bank_id = m_bank_master.bank_idLEFT JOIN m_visit_type_master ON bm.visit_type_id = m_visit_type_master.visit_type_id;

-- public.pl_phama source
CREATE OR REPLACE VIEW public.pl_phamaAS SELECT 'Sales'::text AS lebel,sales.patient_id,sales.bill_no AS receiptno,sales.added_date AS trdate,sales.net_amount,sales.unit_id,sales.discount,sales.total_amount,sales.total_discount_amountFROM pharmacy.t_sale salesUNIONSELECT 'Sales Return'::text AS lebel,sales.patient_id,rn.return_no AS receiptno,rn.added_date AS trdate,rn.total_return_amt AS net_amount,rn.unit_id,sales.discount,sales.total_amount,sales.total_discount_amountFROM pharmacy.t_return rnJOIN pharmacy.t_sale sales ON rn.sale_id = sales.id;

-- public.prescriptioncasesheetdetails source
CREATE OR REPLACE VIEW public.prescriptioncasesheetdetailsAS SELECT DISTINCT 0 AS srno,pinfo.patientname,pinfo.age,pinfo.gender_name,pinfo.uhid_number,em.encounter_number AS visitnumber,em.encounter_date AS visitdate,um.unit_id,um.unit_name,um.unit_logo,um.unit_address,um.organization_id,presdtl.item_id AS "itemId",itm.name AS "itemName",prefredtl.dose AS "doseDesc",su.unit AS "strengthDesc",prefredtl.frequency_id AS "frequencyId",freq.description AS "frequencyDesc",prefredtl.route_id AS "roaId",presdtl.statflag,roa.description AS "roaDesc",prefredtl.start_date AS startdate,prefredtl.stop_date AS enddate,presdtl.instruction_id AS "instructionId",instr.instruction_desc AS "instructionDesc",gen.name AS "genericName",pres.encounter_id,presdtl.order_qty AS qty,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_number,pinfo.patient_id,um.unit_address_2,pres.id,pres.prescription_no,pres.prescription_dateFROM pharmacy.t_prescription presJOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.idJOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.idJOIN m_strength_unit su ON prefredtl.dose_unit_id = su.idJOIN m_item itm ON itm.id = presdtl.item_idJOIN m_route_of_administration roa ON roa.id = prefredtl.route_idJOIN m_generic gen ON itm.generic_id = gen.idJOIN m_frequency freq ON freq.id = prefredtl.frequency_idLEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_idJOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_idJOIN opd.t_encounter_master em ON em.encounter_id = pres.encounter_idJOIN m_unit_master um ON um.unit_id = pres.unit_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_idWHERE pres.is_medication_stop = 'N'::bpcharUNIONSELECT DISTINCT 0 AS srno,pinfo.patientname,pinfo.age,pinfo.gender_name,pinfo.uhid_number,em.admission_number AS visitnumber,em.created_date AS visitdate,um.unit_id,um.unit_name,um.unit_logo,um.unit_address,um.organization_id,presdtl.item_id AS "itemId",itm.name AS "itemName",prefredtl.dose AS "doseDesc",su.unit AS "strengthDesc",prefredtl.frequency_id AS "frequencyId",freq.description AS "frequencyDesc",prefredtl.route_id AS "roaId",presdtl.statflag,roa.description AS "roaDesc",prefredtl.start_date AS startdate,prefredtl.stop_date AS enddate,presdtl.instruction_id AS "instructionId",instr.instruction_desc AS "instructionDesc",gen.name AS "genericName",pres.encounter_id,presdtl.order_qty AS qty,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_number,pinfo.patient_id,um.unit_address_2,pres.id,pres.prescription_no,pres.prescription_dateFROM pharmacy.t_prescription presJOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.idJOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.idJOIN m_strength_unit su ON prefredtl.dose_unit_id = su.idJOIN m_item itm ON itm.id = presdtl.item_idJOIN m_route_of_administration roa ON roa.id = prefredtl.route_idJOIN m_generic gen ON itm.generic_id = gen.idJOIN m_frequency freq ON freq.id = prefredtl.frequency_idLEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_idJOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_idJOIN adt.t_admission em ON em.admission_id = pres.admission_idJOIN m_unit_master um ON um.unit_id = pres.unit_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_idWHERE pres.is_medication_stop = 'N'::bpchar;

-- public.prescriptioncasesheetipd source
CREATE OR REPLACE VIEW public.prescriptioncasesheetipdAS SELECT row_number() OVER (PARTITION BY pres.patient_id ORDER BY itm.name) AS srno,pinfo.patientname,pinfo.age,pinfo.gender_name,pinfo.uhid_number,em.admission_number AS visitnumber,em.created_date AS visitdate,um.unit_id,um.unit_name,um.unit_logo,um.unit_address,um.organization_id,presdtl.item_id AS "itemId",itm.name AS "itemName",prefredtl.dose AS "doseDesc",su.unit AS "strengthDesc",prefredtl.frequency_id AS "frequencyId",freq.description AS "frequencyDesc",prefredtl.route_id AS "roaId",presdtl.statflag,roa.description AS "roaDesc",prefredtl.start_date AS startdate,prefredtl.stop_date AS enddate,presdtl.instruction_id AS "instructionId",instr.instruction_desc AS "instructionDesc",gen.name AS "genericName",pres.encounter_id,presdtl.order_qty AS qty,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_number,pinfo.patient_id,um.unit_address_2,pres.admission_id,presdtl.is_medication_stop,presdtl.updated_date,presdtl.justification_stopFROM pharmacy.t_prescription presJOIN pharmacy.t_prescription_detail presdtl ON presdtl.prescription_id = pres.idLEFT JOIN pharmacy.t_prescription_frequency_detail prefredtl ON prefredtl.prescription_detail_id = presdtl.idLEFT JOIN m_strength_unit su ON prefredtl.dose_unit_id = su.idJOIN m_item itm ON itm.id = presdtl.item_idLEFT JOIN m_route_of_administration roa ON roa.id = prefredtl.route_idJOIN m_generic gen ON itm.generic_id = gen.idLEFT JOIN m_frequency freq ON freq.id = prefredtl.frequency_idLEFT JOIN m_instruction instr ON instr.instruction_id = presdtl.instruction_idJOIN patient.patientinformation pinfo ON pinfo.patient_id = pres.patient_idJOIN adt.t_admission em ON em.admission_id = pres.admission_idJOIN m_unit_master um ON um.unit_id = pres.unit_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = pres.doctor_idWHERE pres.status_id &lt;&gt; 9;

-- public.radiologyreport source
CREATE OR REPLACE VIEW public.radiologyreportAS SELECT template.template_transaction_id,template.created_date,template.created_by,template.encounter_id,template.patient_id,template.template_object,patientinformation.uhid_number,patientinformation.patientname,patientinformation.gender_name,patientinformation.age,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_website,(doctormaster.first_name::text || ' '::text) || doctormaster.last_name::text AS doctorname,doctormaster.doctor_id,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,m_user_master.user_id,servicemaster.service_standard_name,m_user_master.user_nameFROM t_template_transaction templateJOIN patientinformation ON template.patient_id = patientinformation.patient_idLEFT JOIN m_unit_master unitinformation ON template.unit_id = unitinformation.unit_idLEFT JOIN m_user_master ON m_user_master.user_id = template.created_byLEFT JOIN m_employee_master ON m_employee_master.user_id = m_user_master.user_idJOIN t_order_details orderdetail ON template.order_details_id = orderdetail.order_details_idJOIN t_order_master ordermaster ON orderdetail.order_id = ordermaster.order_idLEFT JOIN doctor.m_doctor_master doctormaster ON ordermaster.ord_doctor_id = doctormaster.doctor_idJOIN service.m_service_master servicemaster ON orderdetail.service_id = servicemaster.service_master_id;

-- public.refferaldoctorshare source
CREATE OR REPLACE VIEW public.refferaldoctorshareAS SELECT share.doctor_share_id,share.bill_dtl_id,share.ord_dtl_id,share.service_id,share.total_amount,share.concession,share.discount,share.tax_amt,share.net_amount,share.share_per,share.due_share_amt,share.hosp_share,share.doc_share,share.doc_id,''::text AS alise_name,bm.bill_number,sm.service_standard_name,share.visit_type_id,(((prefix.prefix_desc || ' '::text) || registration.first_name::text) || ' '::text) || registration.last_name::text AS patientname,share.processed_share_date,registration.uhid_number,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,sm.service_master_id,em.encounter_number AS op_ip_number,m_refferel.referral_name AS doctorname,bm.bill_status_id,ssp.sub_speciality_name,bm.bill_date_time,ssp.sub_speciality_id,m_refferel.referral_id,bm.billing_master_id,sp.speciality_id,ssp.refdocperFROM billing.t_doctor_share shareJOIN t_referal_details admreff ON share.visit_id = admreff.encounter_idJOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN billing.t_billing_details bd ON share.bill_dtl_id = bd.billing_details_idJOIN billing.m_billing_master bm ON bd.billing_master_id = bm.billing_master_idJOIN service.m_service_master sm ON share.service_id = sm.service_master_idJOIN opd.t_encounter_master em ON share.visit_id = em.encounter_idJOIN patient.t_patient_registration registration ON em.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN unitinformation ON share.org_unit_id = unitinformation.unit_idJOIN t_order_details od ON share.ord_dtl_id = od.order_details_idJOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_idJOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_id;

-- public.refferaldoctorsharebills source
CREATE OR REPLACE VIEW public.refferaldoctorsharebillsAS SELECT DISTINCT bm.billing_master_id AS doctor_share_id,bd.billing_details_id AS bill_dtl_id,od.order_details_id AS ord_dtl_id,bd.service_id,bd.gross_amount AS total_amount,bd.concession,bd.discount,bd.tax_amount AS tax_amt,bd.net_amt AS net_amount,0 AS share_per,0 AS due_share_amt,0 AS hosp_share,od.ref_doc_share_per AS doc_share,od.ord_doc_id AS doc_id,''::text AS alise_name,bm.bill_number,sm.service_standard_name,em.visit_type_id,registration.patientname,od.created_date AS processed_share_date,registration.uhid_number,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_id,sm.service_master_id,em.encounter_number AS op_ip_number,concat(m_refferel.referral_name) AS doctorname,bm.bill_status_id,ssp.sub_speciality_name,bm.bill_date_time,ssp.sub_speciality_id,m_refferel.referral_id,bm.billing_master_id,sp.speciality_id,ssp.refdocper,mapperd.ref_share_per AS refsharedocper,mapperd.unit_id AS unit_idd,bm.unit_id AS unit_idb,payment.amount AS paidamount,bm.outstandingFROM billing.m_billing_master bmJOIN opd.t_encounter_master em ON bm.encounter_id = em.encounter_idJOIN t_referal_details admreff ON em.encounter_id = admreff.encounter_idJOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idJOIN billing.t_billing_details bd ON bm.billing_master_id = bd.billing_master_idJOIN t_order_details od ON bd.order_details_id = od.order_details_idJOIN service.m_service_master sm ON bd.service_id = sm.service_master_idJOIN patientinformation registration ON em.patient_id = registration.patient_idLEFT JOIN m_prefix_master prefix ON registration.prefix_id = prefix.prefix_idLEFT JOIN unitinformation ON bm.unit_id = unitinformation.unit_idJOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_idJOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_idJOIN service.t_unit_service_mapper mapper ON bd.service_id = mapper.service_idJOIN service.t_unit_service_master_details mapperd ON mapper.service_id = mapperd.service_master_idLEFT JOIN ( SELECT prm.billing_master_id,sum(prm.amount) AS amountFROM billing.t_payment_reciept_master prmJOIN billing.m_billing_master bm_1 ON prm.billing_master_id = bm_1.billing_master_idWHERE COALESCE(prm.reciept_cancelled, ' '::bpchar) = 'N'::bpchar OR prm.reciept_cancelled IS NULLGROUP BY prm.billing_master_id) payment ON bm.billing_master_id = payment.billing_master_idWHERE bm.bill_status_id = 3 AND od.service_rendered = 1;

-- public.rpt_getbedtransferdetails source
CREATE OR REPLACE VIEW public.rpt_getbedtransferdetailsAS SELECT DISTINCT tt.transfer_id,ta.admission_id,patreg.uhid_number,patreg.patientname,patreg.gender_name,frombed.bed_code AS from_bed_code,frombed.bed_number AS from_bed_number,fromwm.ward_name AS from_ward,tobed.bed_code AS to_bed_code,tobed.bed_number AS to_bed_number,towm.ward_name AS to_ward,ttr.note,ttr.created_date,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) AS doctorname,ta.admission_number,(m_employee_master.first_name::text || ' '::text) || m_employee_master.last_name::text AS username,unitinformation.image,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_email_id,m_reason_master.reason_desc,unitinformation.unit_websiteFROM adt.t_admission taJOIN patient.patientinformation patreg ON patreg.patient_id = ta.patient_idJOIN adt.t_transfer tt ON ta.admission_id = tt.admission_idLEFT JOIN adt.t_transfer_request ttr ON ttr.transfer_request_id = tt.transfer_request_idJOIN adt.m_bed_master frombed ON frombed.bed_id = tt.from_bed_idLEFT JOIN adt.m_ward_master fromwm ON fromwm.ward_id = tt.from_ward_idLEFT JOIN adt.m_bed_master tobed ON tobed.bed_id = tt.to_bed_idLEFT JOIN adt.m_ward_master towm ON towm.ward_id = tt.to_ward_idLEFT JOIN doctor.m_doctor_master doctormaster ON ta.admitting_doctor_id = doctormaster.doctor_idLEFT JOIN m_user_master ON tt.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_unit_master unitinformation ON tt.unit_id = unitinformation.unit_idLEFT JOIN adt.m_reason_master ON ttr.reason_id = m_reason_master.reason_master_id;

-- public.rptbaddebitlist source
CREATE OR REPLACE VIEW public.rptbaddebitlistAS SELECT DISTINCT bm.req_disc_id,bm.request_number,bm.request_date,bm.net_amount,bm.req_dis_amt,bm.approved_disc_amt,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(prefix.prefix_desc, '', pm.first_name, ' ', pm.last_name) AS patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.req_status,status_master.bill_status_desc,umm.image,umm.organization_id,org.organization_name,adm.admission_number,pm.mobile_numberFROM billing.t_request_discount bmJOIN billing.t_request_discount_details bdet ON bm.req_disc_id = bdet.req_disc_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idLEFT JOIN m_organization_master org ON bm.organization_id = org.organization_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN adt.t_admission adm ON bm.admission_id = adm.admission_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN billing.m_billing_status_master status_master ON bm.req_status = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON adm.admission_id = sd.admission_id AND sd.priority_id = 1 AND sd.status = 'A'::bpcharLEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = sd.payee_idWHERE bm.visit_type_id &lt;&gt; 1UNIONSELECT DISTINCT bm.req_disc_id,bm.request_number,bm.request_date,bm.net_amount,bm.req_dis_amt,bm.approved_disc_amt,vm.visit_type_id,umm.unit_name,umm.unit_address,umm.unit_contact,umm.unit_contact_2,concat(prefix.prefix_desc, '', pm.first_name, ' ', pm.last_name) AS patientname,pm.patient_id,pm.uhid_number,umm.unit_id,bm.req_status,status_master.bill_status_desc,umm.image,umm.organization_id,org.organization_name,adm.encounter_number AS admission_number,pm.mobile_numberFROM billing.t_request_discount bmJOIN billing.t_request_discount_details bdet ON bm.req_disc_id = bdet.req_disc_idJOIN m_visit_type_master vm ON bm.visit_type_id = vm.visit_type_idJOIN m_user_master um ON bm.created_by = um.user_idJOIN m_unit_master umm ON bm.unit_id = umm.unit_idLEFT JOIN m_organization_master org ON bm.organization_id = org.organization_idJOIN patient.t_patient_registration pm ON bm.patient_id = pm.patient_idLEFT JOIN m_prefix_master prefix ON pm.prefix_id = prefix.prefix_idLEFT JOIN service.m_service_master sm ON bdet.service_id = sm.service_master_idLEFT JOIN opd.t_encounter_master adm ON bm.encounter_id = adm.encounter_idLEFT JOIN t_order_details ON bdet.order_details_id = t_order_details.order_idLEFT JOIN billing.m_billing_status_master status_master ON bm.req_status = status_master.bill_status_idLEFT JOIN opd.t_patient_sponsor_details sd ON adm.encounter_id = sd.encounter_id AND sd.priority_id = 1 AND sd.status = 'A'::bpcharLEFT JOIN t_company_master ON t_company_master.company_id = sd.payee_idLEFT JOIN m_payment_entitlement_master ON sd.payment_entitlement_id = m_payment_entitlement_master.payment_entitlement_idLEFT JOIN t_company_master payeename ON payeename.company_id = sd.payee_idWHERE bm.visit_type_id = 1;

-- public.selfsettenmentreciptipd source
CREATE OR REPLACE VIEW public.selfsettenmentreciptipdAS SELECT t_payment_reciept_master.payment_reciept_id,t_payment_reciept_master.amount,t_payment_reciept_master.reciept_number,t_payment_reciept_master.date_of_reciept,t_payment_reciept_master.receipt_type,t_payment_reciept_master.counter_id,t_payment_reciept_master.settlement_id,t_payment_reciept_master.payee_id,t_payment_reciept_master.received_from,t_payment_reciept_master.identification_number,t_payment_reciept_master.remark,t_payment_reciept_master.is_printed,t_payment_reciept_master.is_financial_clearance,t_payment_reciept_master.status AS payment_status,t_payment_reciept_master.created_date AS payment_created_date,t_payment_reciept_master.created_by AS payment_created_by,t_payment_reciept_master.pharmacy_sale_id,m_billing_master.billing_master_id,m_billing_master.encounter_id,m_billing_master.visit_type_id,m_billing_master.patient_id,m_billing_master.bill_number,m_billing_master.bill_date_time,m_billing_master.net_amount,m_billing_master.discount_amount,m_billing_master.is_credit_bill,m_billing_master.unit_id,m_billing_master.organisation_id,m_billing_master.created_date,m_billing_master.created_by,m_billing_master.updated_date,m_billing_master.concession_amount,m_billing_master.gst,m_billing_master.total_bill_amount,m_billing_master.outstanding,m_billing_master.round_off,m_billing_master.status,m_billing_master.updated_by,m_billing_master.bill_status_id,m_billing_master.admission_id,m_billing_master.cr_amount,m_billing_master.settlement_date,m_billing_master.bill_cancelled,m_billing_master.bill_cancel_reason_id,m_billing_master.bill_cancel_datetime,m_billing_master.bill_cancel_by,m_billing_master.bill_cancel_remark,m_billing_master.is_interim_or_final_bill,m_billing_master.is_doctor_referral_posted,m_billing_master.is_invoice_creation,m_billing_master.is_dr_note,m_billing_master.dr_note_against_billid,m_billing_master.is_addendum_bill,m_billing_master.old_bill_id,m_payment_mode_master.payment_mode_desc,t_patient_registration.uhid_number,(((((m_prefix_master.prefix_desc || ' '::text) || t_patient_registration.first_name::text) || ' '::text) || t_patient_registration.middle_name::text) || ' '::text) || t_patient_registration.last_name::text AS patientname,m_organization_master.organization_name,m_unit_master.unit_name,m_unit_master.registration_number,m_organization_master.organization_address,m_organization_master.organization_contact,m_organization_master.organization_email_id,m_organization_master.organization_logo,m_organization_master.organization_desc,t_payment_reciept_details.payment_mode_id,COALESCE(t_payment_reciept_details.amount, 0::double precision) AS paymentamount,m_bank_master.bank_name,t_payment_reciept_details.check_number,t_payment_reciept_details.cheque_date,t_payment_reciept_details.card_holder_name,t_payment_reciept_details.date_of_transaction,t_payment_reciept_details.card_number,t_payment_reciept_details.expiry_date,m_unit_master.unit_address,pinfo.patientaddress,(((pm.prefix_desc || ' '::text) || m_employee_master.first_name::text) || ' '::text) || m_employee_master.last_name::text AS username,( SELECT COALESCE(sum(dm.available_deposit), 0::double precision) AS depositamtFROM billing.m_deposit_master dmWHERE dm.patient_id = m_billing_master.patient_id) AS depositamt,( SELECT COALESCE(sum(dc.consumed_amount), 0::double precision) AS "coalesce"FROM billing.t_payment_deposite_consumption dcWHERE dc.bill_id = m_billing_master.billing_master_id) AS consumedamount,m_unit_master.unit_address_2FROM billing.t_payment_reciept_masterLEFT JOIN billing.t_payment_reciept_details ON t_payment_reciept_master.payment_reciept_id = t_payment_reciept_details.payment_receipt_master_idLEFT JOIN billing.m_billing_master ON t_payment_reciept_master.billing_master_id = m_billing_master.billing_master_idLEFT JOIN m_payment_mode_master ON t_payment_reciept_details.payment_mode_id = m_payment_mode_master.payment_mode_idLEFT JOIN patient.t_patient_registration ON m_billing_master.patient_id = t_patient_registration.patient_idLEFT JOIN m_prefix_master ON t_patient_registration.prefix_id = m_prefix_master.prefix_idLEFT JOIN m_gender_master ON t_patient_registration.gender_id = m_gender_master.gender_idLEFT JOIN m_organization_master ON m_billing_master.organisation_id = m_organization_master.organization_idLEFT JOIN m_unit_master ON m_billing_master.unit_id = m_unit_master.unit_idLEFT JOIN billing.m_bank_master ON t_payment_reciept_details.bank_id = m_bank_master.bank_idLEFT JOIN m_user_master ON t_payment_reciept_master.created_by = m_user_master.user_idLEFT JOIN m_employee_master ON m_user_master.user_id = m_employee_master.user_idLEFT JOIN m_prefix_master pm ON m_employee_master.prefix_id = pm.prefix_idJOIN patient.patientinformation pinfo ON pinfo.patient_id = t_patient_registration.patient_idWHERE m_billing_master.visit_type_id = 2;

-- public.tokennumberprint source
CREATE OR REPLACE VIEW public.tokennumberprintAS SELECT COALESCE(m_appointment_master.token_number::text, 'Please pick a token number within an hour prior to the appointment time.'::text) AS token_number,m_appointment_master.appointment_date,m_appointment_master.arrival_time,unitinformation.unit_id,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_address_2,unitinformation.unit_email_id,unitinformation.unit_logo,unitinformation.post_code,unitinformation.unit_contact,unitinformation.unit_contact_2,unitinformation.unit_contact_3,unitinformation.unit_country_code,unitinformation.registration_number,unitinformation.unit_website,unitinformation.currency_name,unitinformation.sub_currency,m_appointment_master.appointment_idFROM opd.m_appointment_masterJOIN unitinformation ON m_appointment_master.unit_id = unitinformation.unit_idORDER BY m_appointment_master.appointment_id DESC;

-- public.unitinformation source
CREATE OR REPLACE VIEW public.unitinformationAS SELECT DISTINCT m_unit_master.unit_id,m_unit_master.unit_name,m_unit_master.unit_address,m_unit_master.unit_address_2,m_unit_master.unit_email_id,m_unit_master.unit_logo,m_unit_master.post_code,m_unit_master.unit_contact,m_unit_master.unit_contact_2,m_unit_master.unit_contact_3,m_unit_master.unit_country_code,m_unit_master.registration_number,m_unit_master.unit_website,m_currency_master.currency_name,m_currency_master.sub_currency,m_unit_master.image,m_unit_master.organization_id,m_unit_master.unit_descriptionFROM m_unit_masterLEFT JOIN m_currency_master ON m_unit_master.unit_id = m_currency_master.unit_id;

-- public.v_transation_log source
CREATE OR REPLACE VIEW public.v_transation_logAS SELECT 'Billing'::text AS transtype,bm.bill_number AS transno,bm.created_date,bm.created_date::date AS crdate,um.user_id AS createduserid,um.user_name AS createdusername,bm.updated_date,bm.updated_date::date AS udate,uum.user_id AS updateduserid,uum.user_name AS updatedusernameFROM billing.m_billing_master bmLEFT JOIN m_user_master um ON um.user_id = bm.created_byLEFT JOIN m_user_master uum ON uum.user_id = bm.updated_byUNIONSELECT 'CreditNote'::text AS transtype,cm.credit_note_no AS transno,cm.created_date,cm.created_date::date AS crdate,um.user_id AS createduserid,um.user_name AS createdusername,cm.updated_date,cm.updated_date::date AS udate,uum.user_id AS updateduserid,uum.user_name AS updatedusernameFROM billing.m_credit_note_master cmLEFT JOIN m_user_master um ON um.user_id = cm.created_byLEFT JOIN m_user_master uum ON uum.user_id = cm.updated_byUNIONSELECT 'Deposit'::text AS transtype,depo.deposit_no AS transno,depo.created_date,depo.created_date::date AS crdate,um.user_id AS createduserid,um.user_name AS createdusername,depo.updated_date,depo.updated_date::date AS udate,uum.user_id AS updateduserid,uum.user_name AS updatedusernameFROM billing.m_deposit_master depoLEFT JOIN m_user_master um ON um.user_id = depo.created_byLEFT JOIN m_user_master uum ON uum.user_id = depo.updated_byUNIONSELECT 'Refund'::text AS transtype,refund.payment_refund_voucher_no AS transno,refund.created_date,refund.created_date::date AS crdate,um.user_id AS createduserid,um.user_name AS createdusername,refund.updated_date,refund.updated_date::date AS udate,uum.user_id AS updateduserid,uum.user_name AS updatedusernameFROM billing.t_payment_refund_master refundLEFT JOIN m_user_master um ON um.user_id = refund.created_byLEFT JOIN m_user_master uum ON uum.user_id = refund.updated_by;

-- public.vaccination_master_chart source
CREATE OR REPLACE VIEW public.vaccination_master_chartAS SELECT DISTINCT mapper.remarks,mapper.planned_date,mapper.actual_date,mapper.location,mapper.calculated_date,vmaster.abbreviation,patientinformation.age,vmaster.max_age,vmaster.min_age,vmaster.max_day,vmaster.min_day,m_generic.name AS generic,site.site_name,concat(vmaster.dose_id, '', dose.unit) AS dose_desc,m_item.name AS itemname,route.description AS route,unitinformation.unit_name,unitinformation.unit_address,patientinformation.uhid_number,patientinformation.patientname,patientinformation.gender_name,patientinformation.patientdob,patientinformation.patientmobile,vmaster.uom_id,mapper.patient_id,mapper.vaccine_immunization_mapper_id,unitinformation.imageFROM opd.t_vaccine_immunization_mapper mapperLEFT JOIN lab.m_vaccination_master vmaster ON mapper.vaccination_id = vmaster.vaccination_idLEFT JOIN m_generic ON m_generic.id = vmaster.generic_idLEFT JOIN m_site_of_admininstration site ON vmaster.site_id = site.site_idLEFT JOIN m_strength_unit dose ON vmaster.uom_id = dose.idLEFT JOIN m_item ON vmaster.vaccine_code = m_item.idLEFT JOIN m_route_of_administration route ON vmaster.administration_id = route.idLEFT JOIN unitinformation ON mapper.unit_id = unitinformation.unit_idLEFT JOIN patientinformation ON mapper.patient_id = patientinformation.patient_idWHERE m_item.is_vaccin = true;

-- public.view_for_patient_footfall_cnt_new source
CREATE OR REPLACE VIEW public.view_for_patient_footfall_cnt_newAS SELECT ta.created_date,ta.patient_id,ta.unit_id,ta.organization_id,'IP'::text AS visittype,sp.speciality_name AS departmentwise,concat(dm.first_name, ' ', dm.last_name) AS doctorFROM adt.t_admission taJOIN doctor.m_speciality_master sp ON sp.speciality_id = ta.speciality_idJOIN doctor.m_doctor_master dm ON dm.doctor_id = ta.doctor_idUNION ALLSELECT tem.created_date,tem.patient_id,tem.unit_id,tem.organization_id,'OP'::text AS visittype,CASEWHEN tem.encounter_type_id = 1 THEN 'DOCTOR CONSULTATION'::textWHEN tem.encounter_type_id = 2 THEN 'RADIOLOGY'::textWHEN tem.encounter_type_id = 3 THEN 'EHC'::textWHEN tem.encounter_type_id = 4 THEN 'LAB'::textWHEN tem.encounter_type_id = 6 THEN 'REVIEW APPOINTMENT'::textWHEN tem.encounter_type_id = 7 THEN 'HOSPITAL VISIT'::textWHEN tem.encounter_type_id = 9 THEN 'FREE VISIT'::textELSE NULL::textEND AS departmentwise,concat(dm.first_name, ' ', dm.last_name) AS doctorFROM opd.t_encounter_master temLEFT JOIN doctor.m_doctor_master dm ON dm.doctor_id = tem.doctor_id;

-- public.view_index source
CREATE OR REPLACE VIEW public.view_indexAS SELECT n.nspname AS schema,t.relname AS "table",c.relname AS index,pg_get_indexdef(i.indexrelid) AS defFROM pg_class cJOIN pg_namespace n ON n.oid = c.relnamespaceJOIN pg_index i ON i.indexrelid = c.oidJOIN pg_class t ON i.indrelid = t.oidWHERE c.relkind = 'i'::"char" AND (n.nspname &lt;&gt; ALL (ARRAY['pg_catalog'::name, 'pg_toast'::name])) AND pg_table_is_visible(c.oid)ORDER BY n.nspname, t.relname, c.relname;

-- public.vw_labinvestprescrition source
CREATE OR REPLACE VIEW public.vw_labinvestprescritionAS SELECT pr.patient_id,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS fullname,pim.age,um.unit_address,um.unit_logo,em.encounter_number AS visitno,em.encounter_date AS visitdate,am.allergy_desc,um.unit_id,um.organization_id,em.encounter_id,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_numberFROM patient.t_patient_registration prJOIN opd.t_encounter_master em ON pr.patient_id = em.patient_idJOIN m_unit_master um ON pr.unit_id = um.unit_idJOIN patient.t_allergy_patient_mapper pam ON pr.patient_id = pam.patient_idJOIN emr.m_allergy_master am ON pam.allergy_id = am.allergy_idJOIN patient.patientinformation pim ON pr.patient_id = pim.patient_idJOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_id;

-- public.vw_newprescriptioncasesheet source
CREATE OR REPLACE VIEW public.vw_newprescriptioncasesheetAS SELECT row_number() OVER (PARTITION BY pr.patient_id ORDER BY im.name) AS srno,pr.patient_id,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS fullname,pim.age,um.unit_address,um.unit_logo,em.encounter_number AS visitno,em.encounter_date AS visitdate,um.unit_id,um.organization_id,em.encounter_id,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_number,upper(im.name::text) AS brandname,upper(gn.name::text) AS genric,pfd.dose,stu.unit,pfd.start_date,pfd.stop_date,pfd.instructions,upper(fry.description::text) AS frequency,pd.order_qty AS qtyFROM patient.t_patient_registration prJOIN opd.t_encounter_master em ON pr.patient_id = em.patient_idJOIN m_unit_master um ON pr.unit_id = um.unit_idJOIN patient.patientinformation pim ON pr.patient_id = pim.patient_idJOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_idJOIN pharmacy.t_prescription pres ON pres.encounter_id = em.encounter_idLEFT JOIN pharmacy.t_prescription_detail pd ON pres.id = pd.prescription_idJOIN m_item im ON pd.item_id = im.idJOIN m_generic gn ON im.generic_id = gn.idJOIN pharmacy.t_prescription_frequency_detail pfd ON pd.prescription_id = pfd.prescription_detail_idJOIN m_frequency fry ON pfd.frequency_id = fry.idLEFT JOIN m_strength_unit stu ON pfd.dose_unit_id = stu.id;

-- public.vw_patientallergy source
CREATE OR REPLACE VIEW public.vw_patientallergyAS SELECT DISTINCT pam.encounter_id,CASEWHEN COALESCE(pam.allergy_id, 0) = 0 THEN m_generic.nameELSE am.allergy_descEND AS allergy_desc,pam.allergy_patient_mapp_idFROM patient.t_patient_registration prJOIN opd.t_encounter_master em ON pr.patient_id = em.patient_idJOIN patient.t_allergy_patient_mapper pam ON em.encounter_id = pam.encounter_idLEFT JOIN emr.m_allergy_master am ON pam.allergy_id = am.allergy_idLEFT JOIN m_generic ON pam.generic_id = m_generic.id;

-- public.vw_rediologyinvestpresction source
CREATE OR REPLACE VIEW public.vw_rediologyinvestpresctionAS SELECT pr.patient_id,pr.uhid_number,(((pr.first_name::text || ' '::text) || pr.middle_name::text) || ' '::text) || pr.last_name::text AS fullname,pim.age,um.unit_address,um.unit_logo,em.encounter_number AS visitno,em.encounter_date AS visitdate,am.allergy_desc,um.unit_id,um.organization_id,em.encounter_id,(((dm.first_name::text || ' '::text) || dm.middle_name::text) || ' '::text) || dm.last_name::text AS doctorname,dm.registration_numberFROM patient.t_patient_registration prJOIN opd.t_encounter_master em ON pr.patient_id = em.patient_idJOIN m_unit_master um ON pr.unit_id = um.unit_idJOIN patient.t_allergy_patient_mapper pam ON pr.patient_id = pam.patient_idJOIN emr.m_allergy_master am ON pam.allergy_id = am.allergy_idJOIN patient.patientinformation pim ON pr.patient_id = pim.patient_idJOIN doctor.m_doctor_master dm ON em.doctor_id = dm.doctor_id;-- DROP FUNCTION public.aaa(bool, timestamp, timestamp);
CREATE OR REPLACE FUNCTION public.aaa(usedaterange boolean, starttime timestamp without time zone, endtime timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$beginif usedaterange =truethen else if EXISTS(select * from public.t_synctimestamp)thenstarttime=(select startdate from public.t_synctimestamp where enddate=(select max(enddate) from public.t_synctimestamp));
endtime=(select current_timestamp );
elsestarttime =(select current_timestamp - interval '30 day');
endtime=(select current_timestamp );
end if ;end if ;--declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
--------start postopcomlationdata --------------------------begin create or replace temporary view ipbillself as select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,crm.organisation_id as orgid, crm.unit_id as unitid,pReceiptDtls.date_of_transaction as transdate, crm.company_receipt_date as recieptdate,pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, crm.other_deduction as otherdeductionfrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_idinner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_idinner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_receipt_detail_idinner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere bill.visit_type_id = 1 and pReceiptMst.payee_id != 1;------- Insert cash start ---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId , 'IP',usedaterangefrom ipbillselfwhere ipbillself.modeid = 1 and ipbillself.transdate between starttime and endtimegroup by ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno),usedaterangefrom ipbillselfwhere ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate between starttime and endtime;------------------- tds ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Receipt', 'TDS', ipbillself.recieptdate, sum(ipbillself.tds) ,0, ipbillself.unitid , ipbillself.orgid, 'IP',usedaterangefrom ipbillselfwhere ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate;--------------------------------------------*------------------- disallowed amount ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Receipt', 'Disallowed amount', ipbillself.recieptdate, sum(ipbillself.disallowedamount) , 0,ipbillself.unitid , ipbillself.orgid, 'IP',usedaterangefrom ipbillself where ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate having sum(ipbillself.disallowedamount) !=0;--------------------------------------------------------------- other deductions ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Receipt', 'Other deductions', ipbillself.recieptdate, sum(ipbillself.otherdeduction) , 0, ipbillself.unitid , ipbillself.orgid, 'IP',usedatarangefrom ipbillself where ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate having sum(ipbillself.otherdeduction) !=0;---------------------------------------------------------- insert company wise details ---------------------------with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date as dateoftrans, sum(crd.total_amount) as amount,crd.organisation_id as orgId, crd.unit_id as unitIdfrom billing.t_company_receipt_detail crdinner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_idleft join billing.m_billing_master bm on bm.billing_master_id = cid.bill_idinner join public.t_company_master cm on cm.company_id = cid.bill_payee_idwhere crd.created_date between starttime and endtime and bm.visit_type_id =1group by crd.created_date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cr.amount, cr.unitId, cr.orgId, 'IP',usedatarange from company_receipt cr;end;-----------------------------------------------end postopcomlationdata --------------------------------------------start depositdata-----------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin----------- Create view --------------------------create or replace temporary viewdepositas select depdt.payment_mode_id as modeid, pmode.payment_mode_desc as mode, depdt.amount as recamount,dep.deposit_date ,dep.deposit_master_id as depositid, dep.org_id as orgid, dep.unit_id as unitid,depdt.card_no as cardnumber, depdt.card_type_id as cardtypeid, depdt.cheque_number as chequenumber, depdt.cheque_date as chequedate, bank.bank_name as bankname, depdt.deposit_details_id as depositdetailsidfrom billing.m_deposit_master depinner join billing.t_payment_deposit_details depdton depdt.deposit_id = dep.deposit_master_idinner join public.m_payment_mode_master pmodeon pmode.payment_mode_id = depdt.payment_mode_idleft join billing.m_bank_master bankon bank.bank_id = depdt.bank_id;------------------xxx-------------------------------------------- Insert cash deposits ------------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Sales', dep.mode, dep.date, sum(dep.recamount), 0, dep.unitid, dep.orgid ,'OP',usedatarangefrom deposit depwhere dep.date between starttime and endtimegroup by dep.modeid, dep.mode, dep.orgid, dep.unitid, dep.date;-------------------xxx------------------------/*----------------- Insert other payment mode deposits------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Sales', dep.mode, dep.date, dep.recamount, 0, dep.unitid, dep.orgid, dep.depositdetailsid,coalesce(dep.chequedate,dep.date), 'OP', dep.bankname, coalesce(dep.chequenumber,dep.cardnumber) from deposit depwhere dep.modeid != 1 and dep.date = dateoftrans;------------------------xxx----------------------------------------*/----------------- Insert Patient advance credit ----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Sales', 'Patient Advance', dep.date , 0, sum(dep.recamount), dep.unitid, dep.orgid, 'OP',usedatarangefrom deposit dep where dep.date between starttime and endtimegroup by dep.date, dep.unitid, dep.orgid;end ;------------------------xxx----------------------------------------end depositdata----------------------------------------------------------------start postopfadata------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
declare nextVoucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin ----------- Create view ---------------------------create or replace temporary view opbillAS(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid, billMst.unit_id as unitid,pReceiptDtls.date_of_transaction as transdate, billMst.bill_date_time as billdate,pReceiptDtls.trans_transaction_date as transferdatefrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere billMst.visit_type_id = 1);
------- Insert cash start ---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId , 'OP',usedatarangefrom opbillwhere opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate between starttime and endtimegroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)select voucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno),usedatarangefrom opbillwhere opbill.transdate= opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate between starttime and endtime;------- Insert others start------------------------------------- Company amount --------------------------------with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger, sum(billDtls.credit_payable) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join public.t_company_master comp on comp.company_id = billDtls.payee_id where billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1 and billDtls.payee_id &lt;&gt; 1group by billDtls.payee_id,comp.company_desc, billDtls.created_date, billMst.organisation_id, billMst.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, comp.orgId,'OP',usedatarange from comp;------------------------------Package consumption ---------------------------------with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date as createdDatefrom billing.t_billing_details dtls inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = dtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_idwhere dtls.created_date between starttime and endtime and bill.visit_type_id = 1 and ordt.is_package_service = 'Y'group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date, bill.organisation_id, bill.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'OP',usedatarange from pack;---------------------------------------------------------------------- Insert deposit consumption --------------------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount,unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales', 'Patient Advance', pdc.created_date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP',usedatarangefrom billing.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pdon pd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master billon bill.billing_master_id = pd.bill_idwhere pdc.created_date between starttime and endtime and bill.visit_type_id = 1group by pdc.organization_id, pdc.unit_id,pdc.created_date;-------------------xxx-------------------------------------------- Insert outstanding start---------------with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time as billDatefrom billing.m_billing_master billwhere bill.bill_date_time between starttime and endtime and bill.visit_type_id = 1group by bill.organisation_id, bill.unit_id, bill.bill_date_time),cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitIdfrom billing.t_billing_details billdt inner join billing.m_billing_master billon bill.billing_master_id = billdt.billing_master_idwhere bill.bill_date_time between starttime and endtime and bill.visit_type_id = 1group by billdt.organization_id, billdt.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales','Patient Credit', outst.billDate, outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP',usedatarange from outst , credwhere (outst.outstanding - cred.creditpayable) &gt; 0;------- Insert outstanding end----------------------------------- Discount --------------------------with gen as (select sum(billDtls.discount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by billDtls.created_date, billMst.organisation_id, billMst.unit_id having sum(billDtls.discount) &gt; 0)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId,'OP',usedatarange from gen;------------------------------------------------------------ Ledger start -------------------------with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger, sum(billDtls.gross_amount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by genLedMSt.general_ledger_id, billDtls.created_date, billMst.organisation_id, billMst.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type,findatavaluerange)select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId,'OP',usedatarange from gen;------------ Ledger end --------------------------------------------- Tax ---------------------------with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.m_tax tax on tax.id = billDtls.tax_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by billDtls.tax_id, tax."name", billDtls.created_date, billMst.organisation_id, billMst.unit_idhaving sum(billDtls.tax_amount) &gt; 0)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0,gen.amount, gen.unitId, gen.orgId, 'OP',usedatarange from gen;------------------------------------------------------------------------Previous date settlement start cash-----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId, 'OP',usedatarange from opbillwhere opbill.transdate != opbill.billdate and opbill.modeid = 1 and opbill.transdate between starttime and endtime--cashgroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;--------------------------------------------------Previous date settlement start others-----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno),usedatarangefrom opbillwhere opbill.transdate != opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate between starttime and endtime;--------------------------------------------------------------Credit insert start--------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select nextVoucherno, 'Sales', 'Patient Credit', opbill.transdate,0, sum(opbill.rcptamount), opbill.unitid, opbill.orgid, 'OP',usedatarangefrom opbill where opbill.transdate between starttime and endtime and opbill.transdate != opbill.billdategroup by opbill.transdate, opbill.unitid, opbill.orgid; end;-----------------------------------end postopfadata------------------------------------------------------startdate postadvancerefund------------------------------------------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin -- insert cash mode advance refund amountinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Payment', 'Patient Advance', prm.created_date, sum(prm.amount_refunded), 0 , prm.unit_id, prm.orgnisation_id, 'IP',usedatarangefrom billing.t_payment_refund_master prm where prm.is_cn_or_deposit = 0 and prm.created_date between starttime and endtimegroup by prm.orgnisation_id, prm.unit_id,prm.created_date;--- xxx--- create view for payment detailscreate or replace temporary view refundpaydtlsas select prd.payment_refund_details_id as id, prd.payment_mode_id as modeid, pmod.payment_mode_desc as mode, prd.amount as amount,prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd.date as chequedate,prd.orgnisation_id as orgid, prd.unit_id as unitid, prd.created_date as date, bank.bank_name as banknamefrom billing.t_payment_refund_details prdinner join public.m_payment_mode_master pmod on pmod.payment_mode_id = prd.payment_mode_idinner join billing.t_payment_refund_master prm on prm.payment_refund_id = prd.payment_refund_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere prm.is_cn_or_deposit = 0;--xxx--- insert cash mode transactionsinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'IP',usedatarangefrom refundpaydtls rpdwhere rpd.date between starttime and endtime and rpd.modeid = 1group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;---xxx--- insert other mode transactionsinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)select voucherno, 'Payment', rpd.mode, rpd.date, 0, rpd.amount , rpd.unitid, rpd.orgid, rpd.id,coalesce(rpd.chequedate,rpd.date), 'IP', rpd.bankname,coalesce(rpd.chequenumber, rpd.cardnumber),usedatarangefrom refundpaydtls rpdwhere rpd.date between starttime and endtime and rpd.modeid != 1;end;------------------------------End enddate-------------------------------------------------------------------------------start creditnotes--------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begincreate or replace temporary viewcreditnotes as select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, refd.date_of_refund as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid from billing.m_credit_note_master crdinner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_idinner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_idinner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_idinner join service.m_service_master srv on srv.service_master_id = bdt.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_idinner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id where crd.cr_deu_amount = 0 and billmst.visit_type_id = 1group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund, crd.cr_net_amount;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,hospital_id, tran_type,findatavaluerange)select voucherno, 'Payment', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP',usedatarangefrom creditnotes crd where crd.refunddate between starttime and endtimegroup by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;-------------- Insert credit notes into tally interface end--------------------------------------------------- refund details view --------------------------------------create or replace temporary viewcreditnoterefunds as select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id = 1;-----------------------------xxx--------------------------------------------------------- insert cash mode transactions ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type,findatavaluerange)select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP',usedatarangefrom creditnoterefunds rfdwhere rfd.refunfdate between starttime and endtime and rfd.modeid = 1group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions ----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number,findatavaluerange)select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber),usedatarangefrom creditnoterefunds rfdwhere rfd.refunfdate between starttime and endtime and rfd.modeid != 1group by rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;end;insert into public.t_synctimestamp(startDate,Enddate) values(starttime,endtime);
----------------------end postcreditnotes-------------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.advamount(int4, int4);
CREATE OR REPLACE FUNCTION public.advamount(pid integer, mid integer)RETURNS double precisionLANGUAGE plpgsqlAS $function$declare Amount double precision;beginselect depdt.amount into Amount from billing.m_deposit_master dep join billing.t_payment_deposit_details depdt ON depdt.deposit_id = dep.deposit_master_idleft JOIN m_payment_mode_master pmode ON pmode.payment_mode_id = depdt.payment_mode_idwhere depdt.deposit_details_id = Pid and depdt.payment_mode_id= Mid;return Amount;end;$function$;

-- DROP FUNCTION public.advforadmission(float8);
CREATE OR REPLACE FUNCTION public.advforadmission(admid double precision)RETURNS double precisionLANGUAGE plpgsqlAS $function$DECLARE passed double precision;BEGINSelect coalesce(sum(dm.deposit_amount-dm.refund_amount),0) as Amount into passed FROM billing.m_deposit_master dm where visit_type_id=2 and admission_id = Admid ;RETURN passed;END;$function$;

-- DROP FUNCTION public.after_insert_ord_doc_dept();
CREATE OR REPLACE FUNCTION public.after_insert_ord_doc_dept()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.admission_id is not null thenUPDATE public.t_order_masterSET ord_doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id and visit_type_id!=4),ord_doc_spl_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id and visit_type_id!=4)WHERE order_id=new.order_idand visit_type_id!=4;END IF;IF NEW.encounter_id is not null thenUPDATE public.t_order_masterSET ord_doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id),ord_doc_spl_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)WHERE order_id=new.order_id and (select encounter_type_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)!=3;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.after_insert_product_category();
CREATE OR REPLACE FUNCTION public.after_insert_product_category()RETURNS triggerLANGUAGE plpgsqlAS $function$beginINSERT INTO pharmacy.t_pharmacy_tariff(organization_id, unit_id, asset_category_id, product_category_id, payment_entitlement_id, mark_up_down, mark_up_down_per, status)select organization_id,unit_id,new.asset_category_id,new.id,1,0,0,'A' from m_unit_master mum where organization_id = new.organization_id and mum.status='A';INSERT INTO pharmacy.t_pharmacy_tariff(organization_id, unit_id, asset_category_id, product_category_id, payment_entitlement_id, mark_up_down, mark_up_down_per, status)select organization_id,unit_id,new.asset_category_id,new.id,2,0,0,'A' from m_unit_master mum where organization_id = new.organization_id and mum.status='A';INSERT INTO pharmacy.t_pharmacy_tariff(organization_id, unit_id, asset_category_id, product_category_id, payment_entitlement_id, mark_up_down, mark_up_down_per, status)select organization_id,unit_id,new.asset_category_id,new.id,3,0,0,'A' from m_unit_master mum where organization_id = new.organization_id and mum.status='A';RETURN NEW;END;$function$;

-- DROP FUNCTION public.after_update_ord_details();
CREATE OR REPLACE FUNCTION public.after_update_ord_details()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.ord_doc_id is not null thenUPDATE billing.t_billing_details bdSET ord_doc_id=(select od.ord_doc_id from t_order_details od where od.order_details_id=bd.order_details_id),ord_doc_spl_id = (select ord_doc_spl_id from t_order_details od where od.order_details_id=bd.order_details_id)WHERE bd.order_details_id=new.order_details_id;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.akeys(hstore);
CREATE OR REPLACE FUNCTION public.akeys(hstore)RETURNS text[]LANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_akeys$function$;

-- DROP FUNCTION public.appointment_log_procedure();
CREATE OR REPLACE FUNCTION public.appointment_log_procedure()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF (NEW.appointment_status_id=3 OR NEW.appointment_status_id=2 ) AND (NEW.appointment_type_id=1 AND NEW.is_appointment_from_my_life!='R') thenINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
END IF;IF (NEW.appointment_status_id=5 AND NEW.appointment_type_id=1) thenINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
END IF;IF NEW.appointment_type_id=1 AND NEW.appointment_status_id=6 thenINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,appointment_status_id,org_id)VALUES('AppointmentMaster', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',NEW.appointment_status_id,new.organization_id);
INSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)VALUES('AppointmentDetails', 'PENDING', now(), NEW.appointment_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',new.organization_id);
END IF;RETURN NEW;END;$function$;

