-- DROP FUNCTION public.billconsultantdoctorname(int4, int4);
CREATE OR REPLACE FUNCTION public.billconsultantdoctorname(id integer, visitid integer)RETURNS character varyingLANGUAGE plpgsqlAS $function$DECLARE passed varchar(100);
BEGIN if VisitId = 2 thenselect DocMaster.first_name || ' ' || DocMaster.last_name as DoctorName into passed from billing.m_billing_master BMinner join adt.t_admission AD on BM.admission_id = AD.admission_idinner join doctor.m_doctor_master DocMaster on AD.doctor_id = DocMaster.doctor_idwhere BM.visit_type_id=VisitId and AD.Admission_id=Id;elseif VisitId = 1 thenselect DocMaster.first_name || ' ' || DocMaster.last_name as DoctorName into passed from billing.m_billing_master BMinner join opd.t_encounter_master EM on BM.encounter_id = EM.encounter_idinner join doctor.m_doctor_master DocMaster on EM.doctor_id = DocMaster.doctor_idwhere BM.visit_type_id=VisitId and EM.encounter_id=Id;end if;RETURN passed;END;$function$;

-- DROP PROCEDURE public.bulkservicesave(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.bulkservicesave(IN servicearray json, INOUT failedrecret character varying)LANGUAGE plpgsqlAS $procedure$--failedRecRet varchardeclareserviceArray json := serviceArray;failedrecordjson json[];isServiceMappedToUnit boolean:=false;patCatCount integer;obj json;obj1 json;obj2 json;visitMap json;flag boolean;availServId Integer:=null;failedRec varchar:='';tariffDataJson json;tariffWithBillBedWiseRate json;patCatJson json;billBedVisitMapper json;allPatCat json;serviceTariffId integer:=null;orgId integer:=null;unitId integer:=null;deptId integer:=null;subDeptId integer:=null;ledgerId integer:=null;serviceId integer:=null;validFrm timestamp:=null;validTo timestamp:=null;isExist BOOLEAN;orgName varchar;unitName varchar;deptName varchar;subDeptName varchar;ledgerName varchar;serviceCode varchar;serviceName varchar;serviceBasePrice decimal;validFrom varchar;validTill varchar;visitTypeId integer;failedReason varchar:='';--unit service tariff mastertariffName varchar;paymentEntitlement varchar;tariffId integer:=null;paymentEntitlementId integer :=null;patCatId integer :=null;billBedCatId integer:=null;---service flagsisOutsource bpchar:='N';isPackage bpchar:='N';isRateEditable bpchar :='N';minRateEditable decimal :=0;maxRateEditable decimal :=0;isTaxApplicable bpchar :='N';isRefDoctorShare bpchar :='N';isDiscount bpchar :='N';discountValue decimal=0;isAllowMultipleQuantity bpchar :='N';isProcedure bpchar :='N';isPanel bpchar :='N';isDiscountApplicable bpchar :='N';isDoctorRequired bpchar :='N';isBedSide bpchar :='N';isPOC bpchar :='N';isPeriodicity bpchar :='N';isAutorender bpchar :='N';isAppointable bpchar :='N';gender integer:=0;isPacReq bpchar :='N';refSharePer decimal :=0;isReviewApplicable bpchar :='N';reviewTime integer:=0;billOfMaterial bpchar :='N';docRefPer decimal:=0;createdBy integer;createdDate timestamp :=now();
status bpchar :='A';updatedBy integer;updatedDate timestamp :=now();
beginFOR obj IN SELECT * FROM json_array_elements(serviceArray)loop-- RAISE NOTICE 'output from space %', obj-&gt;&gt;'type';--orgName:=obj-&gt;&gt;'orgName';unitName:=obj-&gt;&gt;'unitName';createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
 orgId:=cast(obj-&gt;&gt;'organizationId' as integer);
 unitId:=cast(obj-&gt;&gt;'unitId' as integer);
deptName:=obj-&gt;&gt;'departmentName';subDeptName:=obj-&gt;&gt;'subDepartmentName';ledgerName:=obj-&gt;&gt;'ledgerName';serviceCode:=obj-&gt;&gt;'serviceCode';serviceBasePrice:=obj-&gt;&gt;'basePrice';serviceName:=obj-&gt;&gt;'serviceName';paymentEntitlement:=1; validFrm=now();
validTo=now();
flag:=false;failedReason:='';isServiceMappedToUnit=false;with getLedgerIdByName as (select general_ledger_id from public.m_general_ledger_master glmwhere glm.organisation_id =orgId and lower(glm.general_ledger_name) = lower(ledgerName))select general_ledger_id into ledgerId from getLedgerIdByName;if ledgerId is null thenfailedReason:='ledger not exist';with ledgerSave as(insert into public.m_general_ledger_master(general_ledger_code,general_ledger_name,status,created_by,created_date,updated_by,updated_date,unit_id,organisation_id)values(ledgerName,ledgerName,status,createdBy,createdDate,updatedBy,updatedDate,unitId,orgId)returning general_ledger_id)select general_ledger_id into ledgerId from ledgerSave;-- return;--continue;end if;with getDeptIdByName as (select speciality_id from doctor.m_speciality_master smwhere sm.organization_id=orgId and lower(sm.speciality_name) = lower(deptName))select speciality_id into deptId from getDeptIdByName;if deptId is null then--if dept not exist then save it-- with departmentSave as (insert into doctor.m_speciality_master(speciality_name,speciality_code,is_surgical_code,created_by,created_date,status,general_ledger_id,updated_by,updated_date,organization_id,--is_clinical_speciality,is_rendering_speciality,dept_wise_appointment,is_kiosk_dept,is_nursing_assessment_required,allowed_overbooking_slots)-- values(deptName,deptName,'N',createdBy,createdDate,status,ledgerId,updatedBy,updatedDate,orgId,-- 'N','N','N','N','N',0)returning speciality_id)--select speciality_id into deptId from departmentSave;failedReason:=concat(failedReason,'Department not exist,');
flag:=true;-- return;--continue;end if;with getSubDeptIdByName as (select sub_speciality_id from doctor.m_sub_speciality_master subsmwhere subsm.organization_id=orgId and lower(subsm.sub_speciality_name) = lower(subDeptName) and subsm.speciality_id=deptId)select sub_speciality_id into subDeptId from getSubDeptIdByName;if subDeptId is null thenfailedReason:=concat(failedReason,'Sub Department not exist,');
-- with subDepartmentSave as (insert into doctor.m_sub_speciality_master (sub_speciality_code,sub_speciality_name,created_by,created_date,status,speciality_id,-- updated_by,updated_date,organization_id,is_modality,general_ledger_id) -- values(subDeptName,subDeptName,createdBy,createdDate,status,deptId,updatedBy,updatedDate,orgId,'N',ledgerId) returning sub_speciality_id)-- select sub_speciality_id into subDeptId from subDepartmentSave;-- return;--continue;flag:=true;end if;--------Check service exist and return service id if exist--availServId :=checkServiceExistAgainstOrg(deptName,serviceName,subDeptName,orgId);
if (deptId is not null) and (subDeptId is not null) thenwith getServIdIfExist as(SELECT sm.service_master_id as idfrom service.m_service_master sminner join doctor.m_speciality_master msm on msm.speciality_id=sm.speciality_id inner join doctor.m_sub_speciality_master mssm on mssm.sub_speciality_id =sm.sub_speciality_id WHERE lower(sm.service_standard_name) = lower(serviceName) and sm.organization_id =orgid and sm.status ='A'and msm.speciality_id = deptId and mssm.sub_speciality_id=subDeptId )select id into availServId from getServIdIfExist;end if;if availServId is not null thenisServiceMappedToUnit=exists(select unitServMap.service_id from service.t_unit_service_mapper unitServMap where unitServMap.service_id=availServId and unitServMap.unit_id=unitId);
--flag=true;--failedReason:=concat(failedReason,' service already exist');
end if;----service master start if flag=false then----- service master save if(availServId is null) thenwith servicesave as (insert into service.m_service_master (organization_id,service_standard_code,service_standard_name,is_available_for_package,is_outsource_service,is_ot_procedure,is_order_set,is_rate_editable,min_rate_editable,max_rate_editable,is_discount_applicable,is_allow_multiple_quantity,is_doctor_required,is_tax_applicable,is_autorendered,created_by,created_date,status,updated_by,updated_date,speciality_id,sub_speciality_id,is_required_schedule,is_on_bed,valid_from,valid_till,general_ledger_id)values(orgId,serviceCode,serviceName,'I','I','I','I','I',0,0,'I','I','I','I','I',createdBy,createdDate,status,updatedBy,updatedDate,deptId,subDeptId,'N','N',validFrm,validTo,ledgerId) returning service_master_id)select service_master_id into serviceId from servicesave;end if;---- service unit mapping if isServiceMappedToUnit=false theninsert into service.t_unit_service_mapper(service_id,unit_id,orgnisation_id,status,created_by,created_date,updated_by,updated_date) values(serviceId,unitId,orgId,status,createdBy,createdDate,updatedBy,updatedDate);
------------unit service master detailinsert into service.t_unit_service_master_details(service_master_id ,is_outsource,is_package ,is_rate_editable,rate_editble_min_value ,rate_editable_max_value,is_tax_applicable ,is_ref_doctor_share,is_discount,unit_id,organization_id ,status ,created_by ,created_date ,updated_by ,updated_date ,discount_value ,is_panel,is_allow_multiple_quantity ,is_procedure,is_doc_req ,is_bed_side ,is_poc ,is_periodicity ,is_auto_render ,is_appointable,gender,is_pacs_req,ref_share_per,is_review_applicable,review_time,bill_of_material,doc_ref_per) values(serviceId,isOutsource,isPackage,isRateEditable,minRateEditable,maxRateEditable,isTaxApplicable,isRefDoctorShare,isDiscount,unitId,orgId,status,createdBy,createdDate,updatedBy,updatedDate,discountValue,isPanel,isAllowMultipleQuantity,isProcedure,isDoctorRequired,isBedSide,isPOC,isPeriodicity,isAutorender,isAppointable,gender,isPacReq,refSharePer,isReviewApplicable,reviewTime,billOfMaterial,docRefPer);
-------service base priceinsert into service.m_service_base_price_master (service_master_id,visit_type_id,base_price,from_date,to_date ,status,unit_id,organisation_id,created_by,created_date,updated_by,updated_date)values(serviceId,1,serviceBasePrice,validFrm,validTo,status,unitId,orgId,createdBy,createdDate,updatedBy,updatedDate);
end if;end if;--service master end --service tariff master startwith getAllPatCategories as(SELECT array_to_json(array_agg(row_to_json(data))) from(selectmpcm.patient_category_id as patcatidfromm_patient_category_master mpcmwherempcm.organization_id = orgIdand mpcm.status = 'A') data)select * into allPatCat from getAllPatCategories;--with getPaymentEntitleIdByName as (select payment_entitlement_id from m_payment_entitlement_master mpem where lower(mpem.payment_entitlement_desc)=lower(paymentEntitlement) and mpem.organization_id=orgId and mpem.status='A')--select payment_entitlement_id into paymentEntitlementId from getPaymentEntitleIdByName;--Billbedcategorywise rate iteration--patcategory wise iteration startpatCatCount=1;FOR patCatJson IN SELECT * FROM json_array_elements(allPatCat)loopFOR tariffDataJson IN SELECT * FROM json_array_elements((obj-&gt;&gt;'tariffData')::json)loopFOR tariffWithBillBedWiseRate IN SELECT * FROM json_array_elements((tariffDataJson-&gt;&gt;'tariffWithBillBedCatWiseRate')::json)loop--get tarriff idif (tariffDataJson-&gt;&gt;'tariffName')='' and patCatCount=1 thenflag=true;failedReason:=concat(failedReason,'Tariff name can not be blank,');
elsewith getTariffIdByName as (select tariff_id from service.m_tariff_master mtm where lower(mtm.tariff_desc)=lower(tariffDataJson-&gt;&gt;'tariffName') and mtm.organization_id=orgId )select tariff_id into tariffId from getTariffIdByName;if tariffId is null thenflag=true;failedReason:=concat(failedReason,(tariffDataJson-&gt;&gt;'tariffName'),' not exist,');
end if;end if;---------------------Billing bed category check---------------if (tariffWithBillBedWiseRate-&gt;&gt;'billingBedCategory')='' and patCatCount=1 thenflag=true;failedReason:=concat(failedReason,'Billing bed category name can not be blank,');
elsewith getBillBedCatByName as (select billing_bed_category_id from adt.m_billing_bed_category_master bbcm where lower(bbcm.billing_bed_desc) =lower(tariffWithBillBedWiseRate-&gt;&gt;'billingBedCategory') and bbcm.organization_id =orgId)select billing_bed_category_id into billBedCatId from getBillBedCatByName;if billBedCatId is null and patCatCount=1 thenflag=true;failedReason:=concat(failedReason,(tariffWithBillBedWiseRate-&gt;&gt;'billingBedCategory'),' not exist,');
else--get all visit type mapped with billing bed categorywith visitMapper as(SELECT array_to_json(array_agg(row_to_json(data))) from(selectbbvtm.visit_type_id as idfrom adt.t_billing_bed_visit_type_mapper bbvtm wherebbvtm.billing_bed_category_id =billBedCatIdand bbvtm.status = 'A'and bbvtm.organization_id =orgIdand bbvtm.unit_id =unitId) data)select * into visitMap from visitMapper;if visitMap is null and patCatCount=1 thenflag=true;failedReason:=concat(failedReason,'Visit type not mapped with billing bed category,');
--failedRe:='bill bed category not map to visit type';end if;end if;end if;if(tariffWithBillBedWiseRate-&gt;&gt;'rate') = '' and patCatCount=1 thenflag=true;failedReason:=concat(failedReason,'Rate can not be blank',' for ',(tariffDataJson-&gt;&gt;'tariffName'),' ',(tariffWithBillBedWiseRate-&gt;&gt;'billingBedCategory'),',');
end if;if (serviceId is not null) and (tariffId is not null) and (billBedCatId is not null) and (visitMap is not null) and (allPatCat is not null) and (tariffWithBillBedWiseRate-&gt;&gt;'rate' &lt;&gt; '') thenFOR billBedVisitMapper IN SELECT * FROM json_array_elements(visitMap)loopwith checkUnitServiceTariffDefined as (select ustm.unit_service_tariff_id as id from service.m_unit_service_tariff_master ustmwhere ustm.service_id =serviceId and ustm.tariff_id =tariffId and ustm.billing_bed_category_id =billBedCatId and ustm.patient_type_id =cast(patCatJson-&gt;&gt;'patcatid' as integer) and ustm.visit_type_id =cast(billBedVisitMapper-&gt;&gt;'id' as integer) and ustm.status='A')select id into serviceTariffId from checkUnitServiceTariffDefined;--if serviceTariffId is null thenINSERT INTO service.m_unit_service_tariff_master(organization_id, unit_id, service_id, tariff_id, payment_entitlement_id, visit_type_id, patient_type_id, billing_bed_category_id,rate,stat_per,effective_date)VALUES(orgId, unitId, serviceId, tariffId, 1, cast(billBedVisitMapper-&gt;&gt;'id' as integer), cast(patCatJson-&gt;&gt;'patcatid' as integer), billBedCatId, cast( tariffWithBillBedWiseRate-&gt;&gt;'rate' as numeric(10,2)), 0, now());
--end if;end loop ; --end of visit type list jsonend if;end loop ;--end of tariffwithbillbedwiseratearrayend loop ;--end of tariff arraypatCatCount=2;end loop;--end of patcatarrayif flag=true thenif(failedReason!='') thenfailedReason=substring(failedReason,0,length(failedReason));
end if;failedRec:=obj::varchar;failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
continue;end if;end loop;--end of service arrayfailedRecRet :=failedRecordJson::varchar;failedRecRet:=substring(failedRecRet,2,(length(failedRecRet)-2));
failedRecRet:=concat('{"failedRecordJson":[','',failedRecRet,'',']}');
failedRecRet= replace(replace(failedRecRet, '"{', '{'),'}"','}');
failedRecRet= replace(failedRecRet,'\','');
EXCEPTION when OTHERS then failedRecRet='failed to insert records';COMMIT;END;$procedure$;-- DROP FUNCTION public.calculate_age(timestamptz);
CREATE OR REPLACE FUNCTION public.calculate_age(dob timestamp with time zone)RETURNS character varyingLANGUAGE plpgsqlAS $function$DECLAREage_text VARCHAR;BEGIN-- Calculate years, months, and days from dob to current timestampSELECT CASE WHEN EXTRACT(YEAR FROM AGE(NOW(), dob)) &gt;= 14 THENCONCAT(EXTRACT(YEAR FROM AGE(NOW(), dob)), 'Y')WHEN EXTRACT(YEAR FROM AGE(NOW(), dob)) &gt;= 1 AND EXTRACT(YEAR FROM AGE(NOW(), dob)) &lt; 14 THENCONCAT(EXTRACT(YEAR FROM AGE(NOW(), dob)), 'Y') || CONCAT(EXTRACT(MONTH FROM AGE(NOW(), dob)), 'M')WHEN EXTRACT(MONTH FROM AGE(NOW(), dob)) &gt;= 1 THENCONCAT(EXTRACT(MONTH FROM AGE(NOW(), dob)), 'M') || CONCAT(EXTRACT(DAY FROM AGE(NOW(), dob)), 'D')ELSECONCAT(EXTRACT(DAY FROM AGE(NOW(), dob)), 'D')ENDINTO age_text;RETURN age_text;END;$function$;

-- DROP FUNCTION public.call_metadatainsert();
CREATE OR REPLACE FUNCTION public.call_metadatainsert()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif NEW.visit_type_id != 1 then if (select count(spd.admission_id) from opd.t_patient_sponsor_details spd where spd.admission_id = NEW.admission_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharhaving count(spd.admission_id)=1 )=1 then --update public.m_patient_visit_metadata set status='I' where admission_id = NEW.admission_id; delete from public.m_patient_visit_metadata where admission_id = NEW.admission_id; INSERT INTO public.m_patient_visit_metadata(patient_id,admission_id,encouter_id,visit_type_id, admission_number,encounter_number,encounter_date,created_date, doa, uhid_number, patientname, gender_name, bar_code, age, patientmobile, patientemail, reg_type, patientgender, patient_category, regdate, patientdob, identification_number, identification_expiry_date, patientaddress, zip_code,marital_status_name, doctorname, unit_name, unit_address, unit_email_id, post_code, unit_contact, registration_number, unit_website, currency_name, sub_currency, organization_address, organization_contact, organization_email_id,organization_logo, organization_desc, company_desc, referral_name, ageyear, agemonth, ageday, billing_bed_desc, bed_desc, contract_name, authorization_amount, authorization_date, authorization_no, is_final_submit, request_amount, request_date, request_no,insurance_number, insured_amount, employee_no_manual)selectdistinct adm.patient_id,adm.admission_id,0,2,adm.admission_number,null,now(),now(),adt.doa,patreg.uhid_number,concat(prefix.prefix_desc, '', patreg.first_name, ' ', patreg.middle_name, ' ', patreg.last_name) as patientname,--patreg.patientname,gm.gender_name,patreg.bar_code,age(patreg.dob) as age,patreg.mobile_number as patientmobile,patreg.email as patientemail,'' as reg_type,gm.gender_name as patientgender,'' as patient_category,patreg.created_date as regdate,patreg.dob as patientdob,patreg.identification_number,patreg.identification_expiry_date,tpd.address as patientaddress,tpd.zip_code,'' as marital_status_name ,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) as doctorname,unitinformation.unit_name,unitinformation.unit_address,unitinformation.unit_email_id,unitinformation.post_code,unitinformation.unit_contact,unitinformation.registration_number,unitinformation.unit_website,'' currency_name,'' sub_currency,m_organization_master.organization_address,m_organization_master.organization_contact,m_organization_master.organization_email_id,m_organization_master.organization_logo,m_organization_master.organization_desc,cm.company_desc,m_refferel.referral_name,abs(date_part('Year'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as ageyear,abs(date_part('month'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as agemonth,abs(date_part('Day'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as ageday,bedcat.billing_bed_desc ,bed.bed_desc,coalesce(m_company_contract_master.contract_name, ''::text) as contract_name,m_preauth_request_master.authorization_amount,m_preauth_request_master.authorization_date,m_preauth_request_master.authorization_no,m_preauth_request_master.is_final_submit,m_preauth_request_master.request_amount,m_preauth_request_master.request_date,m_preauth_request_master.request_no,psd.insurance_number,psd.insured_amount,psd.employee_no_manualfromadt.t_admission admleft join adt.t_admission_details adt onadm.admission_id = adt.admission_id-- left JOIN patient.patientinformation patreg ON patreg.patient_id = adm.patient_idleft join patient.t_patient_registration patreg onpatreg.patient_id = adm.patient_idleft join m_gender_master gm onpatreg.gender_id = gm.gender_idleft join m_prefix_master prefix onprefix.prefix_id = patreg.prefix_idjoin patient.t_patient_details tpd ontpd.patient_id = patreg.patient_idleft join doctor.m_doctor_master doctormaster onadm.admitting_doctor_id = doctormaster.doctor_idleft join adt.m_billing_bed_category_master bedcat onadt.billing_bed_category_id = bedcat.billing_bed_category_idleft join adt.m_bed_master bed onadt.bed_id = bed.bed_idleft join m_unit_master unitinformation onadm.unit_id = unitinformation.unit_idleft join m_organization_master onadm.organization_id = m_organization_master.organization_idleft join opd.t_patient_sponsor_details psd onadm.admission_id = psd.admission_idand psd.priority_id = 1and psd.status = 'A'::bpcharleft join billing.m_preauth_request_master onadm.admission_id = m_preauth_request_master.admission_idand m_preauth_request_master.status = 'A'::"char"and billing.m_preauth_request_master.is_final_submit = 'Y'left join service.m_company_contract_master onpsd.contract_id = m_company_contract_master.contract_idleft join t_company_master cm oncm.company_id = psd.payee_idleft join t_referal_details admreff onadm.admission_id = admreff.admission_idleft join adt.m_referral_master m_refferel onadmreff.referral_id = m_refferel.referral_idwhere adm.admission_id = NEW.admission_id andadt.admission_details_id = (select max(admission_details_id) from adt.t_admission_details where admission_id = adm.admission_id);
end if ;end if;if NEW.visit_type_id = 1 then if (select count(spd.encounter_id) from opd.t_patient_sponsor_details spd where spd.encounter_id = NEW.encounter_id AND spd.priority_id = 1 AND spd.status = 'A'::bpcharhaving count(spd.encounter_id)=1 )=1 then --update public.m_patient_visit_metadata set status='I' where public.m_patient_visit_metadata.encouter_id = NEW.encounter_id;delete from public.m_patient_visit_metadata where encouter_id = NEW.encounter_id; INSERT INTO public.m_patient_visit_metadata(patient_id,admission_id,encouter_id,visit_type_id, admission_number,encounter_number,encounter_date,created_date, doa, uhid_number, patientname, gender_name, bar_code, age, patientmobile, patientemail, reg_type, patientgender, patient_category, regdate, patientdob, identification_number, identification_expiry_date, patientaddress, zip_code,marital_status_name, doctorname, unit_name, unit_address, unit_email_id, post_code, unit_contact, registration_number, unit_website, currency_name, sub_currency, organization_address, organization_contact, organization_email_id,organization_logo, organization_desc, company_desc, referral_name, ageyear, agemonth, ageday, billing_bed_desc, bed_desc, contract_name, authorization_amount, authorization_date, authorization_no, is_final_submit, request_amount, request_date, request_no,insurance_number, insured_amount, employee_no_manual)select distinct em.patient_id, 0, em.encounter_id, 1, null, em.encounter_number, em.encounter_date, now(), em.created_date,patreg.uhid_number, concat(prefix.prefix_desc,'',patreg.first_name,' ',patreg.middle_name,' ',patreg.last_name) as patientname, gm.gender_name,patreg.bar_code ,age(patreg.dob) AS age, patreg.mobile_number as patientmobile, patreg.email as patientemail,'' as reg_type, gm.gender_name as patientgender, '' as patient_category, patreg.created_date as regdate,patreg.dob as patientdob, patreg.identification_number, patreg.identification_expiry_date,tpd.address as patientaddress, tpd.zip_code, '' as marital_status_name ,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) as doctorname,unitinformation.unit_name, unitinformation.unit_address, unitinformation.unit_email_id, unitinformation.post_code,unitinformation.unit_contact, unitinformation.registration_number, unitinformation.unit_website, '' as currency_name,'' as sub_currency, m_organization_master.organization_address, m_organization_master.organization_contact,m_organization_master.organization_email_id, m_organization_master.organization_logo, m_organization_master.organization_desc,cm.company_desc, m_refferel.referral_name,abs(date_part('Year'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as ageyear,abs(date_part('month'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as agemonth,abs(date_part('Day'::text, age(patreg.dob, 'now'::text::date::timestamp without time zone)))::integer as ageday,null , null, coalesce(m_company_contract_master.contract_name, ''::text) as contract_name,0, now(), null, null, 0, now(), null, psd.insurance_number, psd.insured_amount, psd.employee_no_manualfromopd.t_encounter_master emjoin patient.t_patient_registration patreg on patreg.patient_id = em.patient_idjoin m_gender_master gm on patreg.gender_id = gm.gender_idjoin m_prefix_master prefix on prefix.prefix_id = patreg.prefix_id join patient.t_patient_details tpd on tpd.patient_id = patreg.patient_id --join patientinformation patreg on-- patreg.patient_id = em.patient_idleft join doctor.m_doctor_master doctormaster onem.doctor_id = doctormaster.doctor_idleft join m_unit_master unitinformation onem.unit_id = unitinformation.unit_idleft join m_organization_master onem.organization_id = m_organization_master.organization_idleft join opd.t_patient_sponsor_details psd onem.encounter_id = psd.encounter_idand psd.priority_id = 1and psd.status = 'A'::bpcharleft join service.m_company_contract_master onpsd.contract_id = m_company_contract_master.contract_idleft join t_company_master cm oncm.company_id = psd.payee_idleft join t_referal_details admreff onem.encounter_id = admreff.encounter_idleft join adt.m_referral_master m_refferel onadmreff.referral_id = m_refferel.referral_idwhere em.encounter_id = NEW.encounter_id;end if;end if;--select * from patient.t_patient_details where patient_id--select * from opd.t_encounter_master em where em.encounter_id=17800--select * from billing.m_preauth_request_master--if (select count(admission_id) from adt.t_admission_details tad where tad.admission_id = NEW.admission_id having count(admission_id)&gt;1 )&gt;1 then ----update public.m_patient_visit_metadata set billing_bed_desc = bedmaster.billing_bed_desc,--bed_desc = bedmaster.bed_desc--from --(select tad.admission_details_id,bedcat.billing_bed_desc ,bed.bed_desc from adt.t_admission_details tad -- JOIN adt.m_billing_bed_category_master bedcat ON tad.billing_bed_category_id = bedcat.billing_bed_category_id-- join adt.m_bed_master bed on tad.bed_id = bed.bed_id--where tad.admission_details_id =(SELECT max(t_admission_details_1.admission_details_id) AS admission_details_id-- FROM adt.t_admission_details t_admission_details_1-- WHERE t_admission_details_1.admission_id = NEW.admission_id)) as bedmaster--where admission_id = NEW.admission_id;--end if;--PERFORM metadatainsert(NEW.admission_id);
RETURN NEW;END;$function$;

-- DROP FUNCTION public.call_metadataupdate();
CREATE OR REPLACE FUNCTION public.call_metadataupdate()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif (select count(admission_id) from adt.t_transfer tad where tad.admission_id = NEW.admission_id having count(admission_id)&gt;1 )&gt;1 then update public.m_patient_visit_metadata set billing_bed_desc = bedmaster.billing_bed_desc,bed_desc = bedmaster.bed_descfrom (select bedcat.billing_bed_desc ,bed.bed_desc from adt.t_transfer tt join adt.t_admission ta on tt.admission_id = ta.admission_id left JOIN adt.m_billing_bed_category_master bedcat ON tt.from_billing_bed_category_id = bedcat.billing_bed_category_idleft join adt.m_bed_master bed on tt.from_bed_id = bed.bed_idwhere ta.admission_id = NEW.admission_id order by 1 asc limit 1) as bedmasterwhere admission_id = NEW.admission_id and public.m_patient_visit_metadata.status='A';end if;RETURN NEW;END;$function$;

-- DROP FUNCTION public.call_payeeupdate();
CREATE OR REPLACE FUNCTION public.call_payeeupdate()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif NEW.visit_type_id = 1 thenupdate public.m_patient_visit_metadata set company_desc = payee.company_desc,contract_name = payee.contract_namefrom (select psd.encounter_id,cm.company_desc,contract.contract_name from opd.t_patient_sponsor_details psd LEFT JOIN service.m_company_contract_master contract ON psd.contract_id = contract.contract_idLEFT JOIN t_company_master cm ON cm.company_id = psd.payee_idwhere psd.encounter_id=NEW.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar) as payeewhere public.m_patient_visit_metadata.encouter_id =NEW.encounter_id and public.m_patient_visit_metadata.status='A';end if ;if NEW.visit_type_id != 1 thenupdate public.m_patient_visit_metadata set company_desc = payee.company_desc,contract_name = payee.contract_namefrom (select psd.admission_id,cm.company_desc,contract.contract_name from opd.t_patient_sponsor_details psd LEFT JOIN service.m_company_contract_master contract ON psd.contract_id = contract.contract_idLEFT JOIN t_company_master cm ON cm.company_id = psd.payee_idwhere psd.admission_id=NEW.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar) as payeewhere public.m_patient_visit_metadata.admission_id =NEW.admission_id and public.m_patient_visit_metadata.status='A';end if;RETURN NEW;END;$function$;

-- DROP FUNCTION public.call_regisrationupdate();
CREATE OR REPLACE FUNCTION public.call_regisrationupdate()RETURNS triggerLANGUAGE plpgsqlAS $function$beginupdate public.m_patient_visit_metadata set patientname = pim.patientname,patientdob = pim.dob,ageyear = pim.ageyear,agemonth = pim.agemonth,ageday = pim.ageday,patientgender = pim.gender_name,gender_name= pim.gender_namefrom (select pt.patient_id,concat(prefix.prefix_desc,' ',pt.first_name,' ',pt.middle_name,' ',pt.last_name) patientname,pt.dob,abs(date_part('Year'::text, age(pt.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(pt.dob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(pt.dob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,gm.gender_name from patient.t_patient_registration pt join m_prefix_master prefix on pt.prefix_id = prefix.prefix_id join m_gender_master gm on gm.gender_id = pt.gender_id where pt.patient_id =NEW.patient_id) as pimwhere public.m_patient_visit_metadata.patient_id =NEW.patient_id and public.m_patient_visit_metadata.status='A';RETURN NEW;END;$function$;

-- DROP FUNCTION public.casepapercount(date, int4, int4);
CREATE OR REPLACE FUNCTION public.casepapercount(encdate date, doctorid integer, unitid integer)RETURNS booleanLANGUAGE plpgsqlAS $function$declare casecount integer;begin select coalesce(count(encounter_id),0) into casecount from opd.t_encounter_master em where em.doctor_id = doctorid and em.encounter_date::date = encdate and em.unit_id = unitid ;return casecount;end;$function$;

-- DROP FUNCTION public.casepapercount(timestamp, int4, int4);
CREATE OR REPLACE FUNCTION public.casepapercount(encdate timestamp without time zone, doctorid integer, unitid integer)RETURNS booleanLANGUAGE plpgsqlAS $function$declare casecount integer;begin select coalesce(count(encounter_id),0) into casecount from opd.t_encounter_master em where em.doctor_id = doctorid and em.encounter_date::date = encdate and em.unit_id = unitid ;return casecount;end;$function$;

-- DROP FUNCTION public.ceo_dashboard(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.ceo_dashboard(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$--declare unitMasterId integer;begin--truncate m_bill_statstruncate m_bill_stats;-- FOR unitMasterId IN SELECT unit.unit_id FROM m_unit_master unit where unit.unit_id in(unitArray) -- loop-- begin-- bill statINSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, payment_mode_id, payment_mode, amount) select prd.orgnization_id,prd.unit_id,bm.visit_type_id,vtm.visit_type_code,prd.payment_mode_id,pm.payment_mode_code, sum (prd.amount) from billing.t_payment_reciept_details prd inner join billing.t_payment_reciept_master prm on prm.payment_reciept_id=prd.payment_receipt_master_idinner join billing.m_billing_master bm on bm.billing_master_id= prm.billing_master_idinner join public.m_visit_type_master vtm on bm.visit_type_id= vtm.visit_type_idinner join public.m_payment_mode_master pm on pm.payment_mode_id= prd.payment_mode_idwhere prd.date_of_transaction::date=dateoftrans --and prd.unit_id = unitMasterIdgroup by bm.visit_type_id, prd.payment_mode_id,prd.payment_mode_id,prd.orgnization_id,prd.unit_id,vtm.visit_type_code, pm.payment_mode_code;-- bill stat-- bed countsINSERT INTO public.m_bill_stats(organization_id, unit_id, bed_category_id,bed_category,occupied_count,houskeeping_count,bed_vacant_count) selectbedcategor0_.organization_id,bedcategor0_.unit_id,bedcategor0_.bed_category_id ,bedcategor0_.bed_category_desc,(select count(bedmaster1_.bed_id)fromadt.m_bed_master bedmaster1_inner join adt.t_bed_log_status listbedlog2_ onbedmaster1_.bed_id = listbedlog2_.bed_idwherelistbedlog2_.bed_status_id = 3and bedmaster1_.bed_category_id = bedcategor0_.bed_category_id--and bedmaster1_.organization_id =1--and bedmaster1_.unit_id =1and listbedlog2_.status = 'A'and listbedlog2_.updated_date::date=dateoftrans) ,(select count(bedmaster3_.bed_id)fromadt.m_bed_master bedmaster3_inner join adt.t_bed_log_status listbedlog4_ onbedmaster3_.bed_id = listbedlog4_.bed_idwherelistbedlog4_.bed_status_id = 2and bedmaster3_.bed_category_id = bedcategor0_.bed_category_id--and bedmaster3_.organization_id =1--and bedmaster3_.unit_id =1and listbedlog4_.status = 'A'and listbedlog4_.updated_date::date=dateoftrans) ,(select count(bedmaster5_.bed_id)fromadt.m_bed_master bedmaster5_inner join adt.t_bed_log_status listbedlog6_ onbedmaster5_.bed_id = listbedlog6_.bed_idwherelistbedlog6_.bed_status_id = 5and bedmaster5_.bed_category_id = bedcategor0_.bed_category_id--and bedmaster5_.organization_id =1--and bedmaster5_.unit_id =1and listbedlog6_.status = 'A'and listbedlog6_.updated_date::date=dateoftrans)fromadt.m_bed_category_master bedcategor0_where--bedcategor0_.organization_id =1--and bedcategor0_.unit_id =1bedcategor0_.status = 'A'--and bedcategor0_.unit_id = unitMasterIdorder bybedcategor0_.bed_category_id;-- bed counts-- procedure countINSERT INTO public.m_bill_stats(organization_id, unit_id, procedure_count) selectorg_id,org_unit_id, count(order_details_id)fromt_order_detailswhereservice_id in (select service_master_idfromservice.t_unit_service_master_detailswhereis_procedure = 'Y')and service_rendered = 1and service_is_billed = 1and ord_render_datetime::date= dateoftrans--and org_unit_id = unitMasterIdgroup byorg_unit_id,org_id;--EHC CountINSERT INTO public.m_bill_stats(organization_id, unit_id, ehc_count) selectorganization_id,unit_id,count(encounter_id)fromopd.t_encounter_masterwhereencounter_type_id = 3and encounter_date::date = dateoftrans --and unit_id = unitMasterIdgroup byunit_id,organization_id;--Diagnostics Count--Lab CountINSERT INTO public.m_bill_stats(organization_id, unit_id,visit_type_id, visit_type, lab_count) selectod.org_id,od.org_unit_id,om.visit_type_id,vtm.visit_type_code,count(od.order_details_id)fromt_order_details odinner join t_order_master om onom.order_id = od.order_idinner join service.m_service_master ser onser.service_master_id = od.service_idinner join public.m_visit_type_master vtm on om.visit_type_id= vtm.visit_type_idwhereod.service_rendered = 1and od.ord_render_datetime::date= dateoftrans--and od.org_unit_id = unitMasterIdand ser.speciality_id in (select lab_speciality_idfromt_lab_configurationwhereunit_id = od.org_unit_idand status = 'A')group byom.visit_type_id,vtm.visit_type_code,od.org_unit_id,od.org_id;--Radiology CountINSERT INTO public.m_bill_stats(organization_id, unit_id,visit_type_id, visit_type, radiology_count) selectod.org_id,od.org_unit_id,om.visit_type_id,vtm.visit_type_code,count(od.order_details_id)fromt_order_details odinner join t_order_master om onom.order_id = od.order_idinner join service.m_service_master ser onser.service_master_id = od.service_idinner join public.m_visit_type_master vtm onom.visit_type_id= vtm.visit_type_idwhereod.service_rendered = 1and od.ord_render_datetime::date= dateoftrans--and od.org_unit_id = unitMasterIdand ser.speciality_id in(select radiology_speciality_idfromt_unit_application_billing_configuration where unit_id= od.org_unit_idand status = 'A')group byom.visit_type_id,vtm.visit_type_code,od.org_unit_id,od.org_id;--Admission CountINSERT INTO public.m_bill_stats(organization_id, unit_id,visit_type_id, visit_type, admission_count)selectorganization_id,unit_id,visit_type_id,visit_type_code,count(unit_id) frompublic.getadmittedpatientlistwhere--unit_id = 1admission_date::date = dateoftrans--and unit_id = unitMasterIdgroup byvisit_type_id, visit_type_code, organization_id, unit_idunion select organization_id,unit_id,1 as visit_type_id,'OP' as visit_type_code,count(unit_id) from opd.t_encounter_masterwhere encounter_date::date = dateoftrans--and unit_id = unitMasterIdgroup byvisit_type_id, visit_type_code, organization_id, unit_id; --Discharge CountINSERT INTO public.m_bill_stats(organization_id, unit_id,visit_type_id, visit_type, discharge_count) selectorganization_id,unit_id,visit_type_id,visit_type_code,count(unit_id)frompublic.getdischargedetailswheredischarge_Date::date = dateoftrans--and unit_id = unitMasterIdgroup byvisit_type_id, visit_type_code, organization_id, unit_id;--Death CountINSERT INTO public.m_bill_stats(organization_id, unit_id,visit_type_id, visit_type, death_count) select dch.organization_id,dch.unit_id,dch.visit_type_id,vtm.visit_type_code,count(unit_id)fromadt.t_discharge dchinner join public.m_visit_type_master vtm on vtm.visit_type_id=dch.visit_type_idwheredch.discharge_type_id = 2and dch.status = 'A'and dch.discharge_status_id = 5and dch.created_date::date= dateoftrans--and dch.unit_id = unitMasterIdgroup by dch.organization_id,dch.unit_id,vtm.visit_type_code,dch.visit_type_id;--total out patients visit countINSERT INTO public.m_bill_stats(organization_id, unit_id,user_defined_visit_type_id, totat_pat_count) select organization_id,unit_id,user_defined_visit_type_id ,count(unit_id)from public.getopdconsultatationdoctorwise where bill_date_time::date=dateoftrans--and unit_id = unitMasterIdgroup by user_defined_visit_type_id,organization_id,unit_id;-----discountINSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, discount_count) selectbm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code,sum(bm.discount_amount)from billing.m_billing_master bminner join public.m_visit_type_master vtm on bm.visit_type_id=vtm.visit_type_idwherebm.bill_date_time::date=dateoftrans--and bm.unit_id = unitMasterIdgroup bybm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code;-----discount----credit notesINSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, credit_note_count) selectcrd.organisation_id ,crd.unit_id ,bill.visit_type_id,vtm.visit_type_code,sum(crd.cr_net_amount)frombilling.m_credit_note_master crdinner join billing.m_billing_master bill onbill.billing_master_id = crd.bill_idinner join public.m_visit_type_master vtm onbill.visit_type_id = vtm.visit_type_idwherebill.bill_date_time :: date= dateoftrans--and crd.unit_id = unitMasterIdgroup bybill.visit_type_id,vtm.visit_type_code,crd.organisation_id,crd.unit_id;----credi notes----refund INSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, refund_count) selectprd.orgnisation_id,prd.unit_id,billmst.visit_type_id,vtm.visit_type_code,sum(prd.amount) as amountfrombilling.t_payment_refund_master prminner join billing.t_payment_refund_details prd onprd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm oncnm.credit_note_id = prm.credit_note_idinner join billing.m_billing_master billmst onbillmst.billing_master_id = cnm.bill_id inner join public.m_visit_type_master vtm onbillmst.visit_type_id = vtm.visit_type_id whereprm.date_of_refund::date =dateoftrans--and prd.unit_id = unitMasterIdgroup bybillmst.visit_type_id,vtm.visit_type_code,prd.orgnisation_id,prd.unit_id;----refund------insuranceINSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, company_type_id, company_type, insurance_count) selectbm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code,com.company_type_id,'Insurance',sum(bpd.bill_amount)frombilling.t_bill_payee_details bpdinner join billing.m_billing_master bm onbpd.bill_id = bm.billing_master_idinner join t_company_master com oncom.company_id = bpd.payee_idinner join m_company_type_master ctm oncom.company_type_id = ctm.company_type_idinner join public.m_visit_type_master vtm onbm.visit_type_id = vtm.visit_type_idwherecom.company_type_id = 2and bm.bill_date_time::date= dateoftrans--and bm.unit_id = unitMasterIdgroup bybm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code,com.company_type_id,ctm.company_type_code;------insurance-----companyINSERT INTO public.m_bill_stats(organization_id, unit_id, visit_type_id, visit_type, company_type_id, company_type, corporate_company_count) selectbm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code,com.company_type_id,'Company',sum(bpd.bill_amount)frombilling.t_bill_payee_details bpdinner join billing.m_billing_master bm onbpd.bill_id = bm.billing_master_idinner join t_company_master com oncom.company_id = bpd.payee_idinner join m_company_type_master ctm oncom.company_type_id = ctm.company_type_idinner join public.m_visit_type_master vtm onbm.visit_type_id = vtm.visit_type_idwherecom.company_type_id = 3and bm.bill_date_time::date= dateoftrans--and bm.unit_id = unitMasterIdgroup bybm.organisation_id,bm.unit_id,bm.visit_type_id,vtm.visit_type_code,com.company_type_id,ctm.company_type_code;-----company--end;--end loop;return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.checkserviceexist(varchar);
CREATE OR REPLACE FUNCTION public.checkserviceexist(servname character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$BEGINRETURN EXISTS (SELECT *from service.m_service_masterWHERE lower(service_standard_name) = lower(servName) );
END$function$;

-- DROP FUNCTION public.checkserviceexistcall(varchar);
CREATE OR REPLACE FUNCTION public.checkserviceexistcall(servname character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$DECLARE servId integer :=null;BEGINwith serviceChk as (SELECT service_master_id from service.m_service_masterWHERE lower(service_standard_name) = lower(servName) )select service_master_id into servId from serviceChk;if servId is not null thenreturn true;else return false;end if;END$function$;

-- DROP FUNCTION public.checkserviceexistcall1(varchar);
CREATE OR REPLACE FUNCTION public.checkserviceexistcall1(servname character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$DECLARE servId integer :=null;BEGINreturn exists (SELECT service_master_id from service.m_service_masterWHERE lower(service_standard_name) = lower(servName) );
END$function$;

-- DROP FUNCTION public.checktable(varchar, varchar);
CREATE OR REPLACE FUNCTION public.checktable(tname character varying, cname character varying)RETURNS character varyingLANGUAGE plpgsqlAS $function$declare tbname VARCHAR;clname VARCHAR; beginSELECT column_name into cname FROM information_schema.columnsWHERE table_name= tname and column_name='patient_id';return cname;end; $function$;

-- DROP FUNCTION public.collection_sms(text, int4);
CREATE OR REPLACE FUNCTION public.collection_sms(todays_date text, unit integer)RETURNS TABLE(self_adm_count bigint, credit_adm_count bigint, self_dis_count bigint, credit_dis_count bigint, new_visit_count bigint, follow_up_visit_count bigint, deth_count bigint, total_amt numeric, refund_amt numeric, deposit_amt numeric)LANGUAGE plpgsqlAS $function$DECLARE beginRETURN QUERY select (select count(adm.admission_id) from opd.t_patient_sponsor_details psd inner join adt.t_admission adm on adm.admission_id = psd.admission_idwhere psd.admission_id is not null and psd.unit_id=unitand psd.priority_id = 1 and psd.payee_id = ( select self_payee_id from t_unit_application_billing_configuration tuabc where unit_id = unit and status = 'A' limit 1) and to_char (adm.created_date,'yyyy-mm-dd')=todays_dateand adm.status='A')as self_adm_count,(select count(adm.admission_id) from opd.t_patient_sponsor_details psd inner join adt.t_admission adm on adm.admission_id = psd.admission_idwhere psd.admission_id is not null and psd.priority_id = 1 and psd.unit_id=unitand psd.payee_id != ( select self_payee_id from t_unit_application_billing_configuration tuabc where unit_id = unit and status = 'A' limit 1) and to_char (adm.created_date,'yyyy-mm-dd') =todays_dateand adm.status='A') as credit_adm_count,(select count(adm.admission_id) from opd.t_patient_sponsor_details psd inner join adt.t_admission adm on adm.admission_id = psd.admission_idinner join adt.t_discharge dis on dis.admission_id = adm.admission_idwhere psd.admission_id is not null and psd.priority_id = 1 and psd.payee_id = ( select self_payee_id from t_unit_application_billing_configuration tuabc where unit_id = unit and status = 'A' limit 1)and psd.unit_id=unitand to_char (dis.created_date,'yyyy-mm-dd') =todays_dateand dis.discharge_status_id = 5)as self_dis_count,(select count(adm.admission_id) from opd.t_patient_sponsor_details psd inner join adt.t_admission adm on adm.admission_id = psd.admission_idinner join adt.t_discharge dis on dis.admission_id = adm.admission_idwhere psd.admission_id is not null and psd.priority_id = 1 and psd.payee_id != ( select self_payee_id from t_unit_application_billing_configuration tuabc where unit_id = unit and status = 'A' limit 1)and psd.unit_id=unitand to_char (dis.created_date,'yyyy-mm-dd') =todays_dateand dis.discharge_status_id = 5)as creditDisCount,(select count(encounter_id) from opd.t_encounter_master where user_defined_visit_type_id = 1 and unit_id=unit and to_char(created_date,'yyyy-mm-dd') = todays_date )as newVisitCount,(select count(encounter_id) from opd.t_encounter_master where user_defined_visit_type_id != 1 and unit_id=unit and to_char(created_date,'yyyy-mm-dd') = todays_date ) as followUpVisitCount,(select count(admission_id) from adt.t_discharge where discharge_type_id=3 and unit_id=unit and status='A' and discharge_status_id=5 and to_char(created_date,'yyyy-mm-dd') = todays_date)as dethCount,(SELECT SUM(amount) as total_amt FROM( selectcoalesce(cast(sum(prm.amount) as numeric(10, 2)), 0)AS amountfrombilling.t_payment_reciept_master prmwhereto_char(prm.date_of_reciept, 'yyyy-mm-dd')= todays_dateand prm.unit_id = unitUNION all selectcoalesce(cast(sum(ts.amount) as numeric(10, 2)), 0)AS amountfrompharmacy.t_sale_payment_mode tswhereto_char(ts.added_date, 'yyyy-mm-dd')= todays_date and is_active = trueand is_deleted = falseand ts.unit_id = unit) x )as total_amt,(select coalesce(cast(sum(prm.amount_refunded) as numeric(10,2)),0) from billing.t_payment_refund_master prm WHERE to_char(prm.created_date,'yyyy-mm-dd')=todays_date and prm.unit_id=unit) as refund_amt,(select coalesce(cast(sum(dp.deposit_amount) as numeric(10,2)),0) from billing.m_deposit_master dp WHERE to_char(dp.created_date,'yyyy-mm-dd')=todays_date and dp.unit_id=unit ) as deposit_amt;END;$function$;

-- DROP FUNCTION public.createbarcodecode128(varchar);
CREATE OR REPLACE FUNCTION public.createbarcodecode128(barcode character varying)RETURNS character varyingLANGUAGE plpgsqlAS $function$declare site_value integer;v_data_to_encode VARCHAR;check_digit_char VARCHAR;check_digit INT8;start_character VARCHAR(0203);
 stop_character varchar(0206);
current_value bigint; encoded_string VARCHAR(1000);
weight_total int8;mrLen BIGINT;begin site_value = 1;v_data_to_encode = Barcode;-- Calcuation variablesstart_character = '0203';stop_character = '0206';weight_total = ASCII(start_character) - 100;mrLen := length(v_data_to_encode);
case when site_value &lt;= mrLen then current_value = CAST(ASCII(SUBSTRING (v_data_to_encode, site_value, 1)) AS BIGINT);
 if current_value &lt; 135 THEN current_value = (current_value - 32);
 ELSEif current_value &gt;= 135 THEN current_value = (current_value - 100);
 end if; current_value = current_value * site_value;weight_total = weight_total + current_value;site_value = site_value+1; end case;check_digit = (weight_total % 103);
BEGINif check_digit &lt; 95 and check_digit &gt; 0 THENcheck_digit_char = cast((check_digit + 32) as varchar);
ELSEif check_digit &gt;= 95 THENcheck_digit_char = cast((check_digit + 100) as varchar);
elseif check_digit = 0 THENcheck_digit_char = cast((194) as varchar);
end if; encoded_string = replace(v_data_to_encode,' ',cast((194) as varchar));
return CONCAT (start_character,encoded_string,check_digit_char,stop_character);
end; end;$function$;

