-- DROP FUNCTION public.fasyncprocessor(bool, timestamp, timestamp);
CREATE OR REPLACE FUNCTION public.fasyncprocessor(usedaterange boolean, starttime timestamp without time zone, endtime timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declareerr_context text;beginif usedaterange= true then else if EXISTS(select * from public.t_synctimestamp where enddate=endtime ) thenstarttime=(select startdate from public.t_synctimestamp where enddate=(select max(enddate) from public.t_synctimestamp));
endtime=(select current_timestamp);
elsestarttime =(select current_timestamp - interval '30 day');
endtime=(select current_timestamp );
end if ;end if;--declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
--------start postopcomlationdata --------------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin create or replace temporary view ipbillself as select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,crm.organisation_id as orgid, crm.unit_id as unitid,pReceiptDtls.date_of_transaction as transdate, crm.company_receipt_date as recieptdate,pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, crm.other_deduction as otherdeductionfrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_idinner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_idinner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_receipt_detail_idinner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere bill.visit_type_id = 1 and pReceiptMst.payee_id != 1;------- Insert cash start ---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId , 'IP'from ipbillselfwhere ipbillself.modeid = 1 and ipbillself.transdate between starttime and endtimegroup by ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount,unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)from ipbillselfwhere ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate between starttime and endtime;------------------- tds ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'TDS', ipbillself.recieptdate, sum(ipbillself.tds) ,0, ipbillself.unitid , ipbillself.orgid, 'IP'from ipbillselfwhere ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate;--------------------------------------------*------------------- disallowed amount ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Disallowed amount', ipbillself.recieptdate,sum(ipbillself.disallowedamount) , 0,ipbillself.unitid , ipbillself.orgid, 'IP'from ipbillself where ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate having sum(ipbillself.disallowedamount) !=0;--------------------------------------------------------------- other deductions ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Receipt', 'Other deductions', ipbillself.recieptdate, sum(ipbillself.otherdeduction) , 0, ipbillself.unitid , ipbillself.orgid, 'IP'from ipbillself where ipbillself.recieptdate between starttime and endtimegroup by ipbillself.orgid, ipbillself.unitid , ipbillself.recieptdate having sum(ipbillself.otherdeduction) !=0;---------------------------------------------------------- insert company wise details ---------------------------with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date as dateoftrans, sum(crd.total_amount) as amount,crd.organisation_id as orgId, crd.unit_id as unitIdfrom billing.t_company_receipt_detail crdinner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_idleft join billing.m_billing_master bm on bm.billing_master_id = cid.bill_idinner join public.t_company_master cm on cm.company_id = cid.bill_payee_idwhere crd.created_date between starttime and endtime and bm.visit_type_id =1group by crd.created_date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cr.amount, cr.unitId, cr.orgId, 'IP' from company_receipt cr;end;-----------------------------------------------end postopcomlationdata --------------------------------------------start depositdata-----------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin----------- Create view --------------------------create or replace temporary viewdepositas select depdt.payment_mode_id as modeid, pmode.payment_mode_desc as mode, depdt.amount as recamount,dep.deposit_date ,dep.deposit_master_id as depositid, dep.org_id as orgid, dep.unit_id as unitid,depdt.card_no as cardnumber, depdt.card_type_id as cardtypeid, depdt.cheque_number as chequenumber, depdt.cheque_date as chequedate, bank.bank_name as bankname, depdt.deposit_details_id as depositdetailsidfrom billing.m_deposit_master depinner join billing.t_payment_deposit_details depdton depdt.deposit_id = dep.deposit_master_idinner join public.m_payment_mode_master pmodeon pmode.payment_mode_id = depdt.payment_mode_idleft join billing.m_bank_master bankon bank.bank_id = depdt.bank_id;------------------xxx-------------------------------------------- Insert cash deposits ------------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', dep.mode, dep.deposit_date, sum(dep.recamount), 0, dep.unitid, dep.orgid ,'OP'from deposit depwhere dep.deposit_date between starttime and endtimegroup by dep.modeid, dep.mode, dep.orgid, dep.unitid, dep.deposit_date;-------------------xxx------------------------/*----------------- Insert other payment mode deposits------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Sales', dep.mode, dep.date, dep.recamount, 0, dep.unitid, dep.orgid, dep.depositdetailsid,coalesce(dep.chequedate,dep.date), 'OP', dep.bankname, coalesce(dep.chequenumber,dep.cardnumber) from deposit depwhere dep.modeid != 1 and dep.date = dateoftrans;------------------------xxx----------------------------------------*/----------------- Insert Patient advance credit ----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', 'Patient Advance', dep.deposit_date, 0, sum(dep.recamount), dep.unitid, dep.orgid, 'OP'from deposit dep where dep.deposit_date between starttime and endtimegroup by dep.deposit_date, dep.unitid, dep.orgid;end ;------------------------xxx----------------------------------------end depositdata----------------------------------------------------------------start postopfadata------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
declare nextVoucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin ----------- Create view ---------------------------create or replace temporary view opbillAS(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid, billMst.unit_id as unitid,pReceiptDtls.date_of_transaction as transdate, billMst.bill_date_time as billdate,pReceiptDtls.trans_transaction_date as transferdatefrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere billMst.visit_type_id = 1);
------- Insert cash start ---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId , 'OP'from opbillwhere opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate between starttime and endtimegroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)from opbillwhere opbill.transdate= opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate between starttime and endtime;------- Insert others start------------------------------------- Company amount --------------------------------with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger, sum(billDtls.credit_payable) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join public.t_company_master comp on comp.company_id = billDtls.payee_id where billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1 and billDtls.payee_id &lt;&gt; 1group by billDtls.payee_id,comp.company_desc, billDtls.created_date, billMst.organisation_id, billMst.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, comp.orgId,'OP'from comp;------------------------------Package consumption ---------------------------------with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date as createdDatefrom billing.t_billing_details dtls inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = dtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_idwhere dtls.created_date between starttime and endtime and bill.visit_type_id = 1 and ordt.is_package_service = 'Y'group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date, bill.organisation_id, bill.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'OP' from pack;---------------------------------------------------------------------- Insert deposit consumption --------------------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount,unit_id, hospital_id,tran_type)select voucherno, 'Sales', 'Patient Advance', pdc.created_date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP'from billing.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pdon pd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master billon bill.billing_master_id = pd.bill_idwhere pdc.created_date between starttime and endtime and bill.visit_type_id = 1group by pdc.organization_id, pdc.unit_id,pdc.created_date;-------------------xxx-------------------------------------------- Insert outstanding start---------------with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time as billDatefrom billing.m_billing_master billwhere bill.bill_date_time between starttime and endtime and bill.visit_type_id = 1group by bill.organisation_id, bill.unit_id, bill.bill_date_time),cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitIdfrom billing.t_billing_details billdt inner join billing.m_billing_master billon bill.billing_master_id = billdt.billing_master_idwhere bill.bill_date_time between starttime and endtime and bill.visit_type_id = 1group by billdt.organization_id, billdt.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales','Patient Credit', outst.billDate, outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP'from outst , cred where (outst.outstanding - cred.creditpayable) &gt; 0;------- Insert outstanding end----------------------------------- Discount --------------------------with gen as (select sum(billDtls.discount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by billDtls.created_date, billMst.organisation_id, billMst.unit_id having sum(billDtls.discount) &gt; 0)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,hospital_id,tran_type)select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId,'OP' from gen;------------------------------------------------------------ Ledger start -------------------------with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger, sum(billDtls.gross_amount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by genLedMSt.general_ledger_id, billDtls.created_date, billMst.organisation_id, billMst.unit_id)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId,'OP' from gen;------------ Ledger end --------------------------------------------- Tax ---------------------------with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,billDtls.created_date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.m_tax tax on tax.id = billDtls.tax_idwhere billDtls.created_date between starttime and endtime and billMst.visit_type_id = 1group by billDtls.tax_id, tax."name", billDtls.created_date, billMst.organisation_id, billMst.unit_idhaving sum(billDtls.tax_amount) &gt; 0)insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0,gen.amount, gen.unitId, gen.orgId, 'OP' from gen;------------------------------------------------------------------------Previous date settlement start cash-----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId, 'OP'from opbillwhere opbill.transdate != opbill.billdate and opbill.modeid = 1 and opbill.transdate between starttime and endtime--cashgroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;--------------------------------------------------Previous date settlement start others-----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)from opbillwhere opbill.transdate != opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate between starttime and endtime;--------------------------------------------------------------Credit insert start--------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextVoucherno, 'Sales', 'Patient Credit', opbill.transdate,0, sum(opbill.rcptamount), opbill.unitid, opbill.orgid, 'OP'from opbill where opbill.transdate between starttime and endtime and opbill.transdate != opbill.billdategroup by opbill.transdate, opbill.unitid, opbill.orgid; end;-----------------------------------end postopfadata------------------------------------------------------startdate postadvancerefund------------------------------------------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begin -- insert cash mode advance refund amountinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', 'Patient Advance', prm.created_date, sum(prm.amount_refunded), 0 , prm.unit_id, prm.orgnisation_id, 'IP'from billing.t_payment_refund_master prm where prm.is_cn_or_deposit = 0 and prm.created_date between starttime and endtimegroup by prm.orgnisation_id, prm.unit_id,prm.created_date;--- xxx--- create view for payment detailscreate or replace temporary view refundpaydtlsas select prd.payment_refund_details_id as id, prd.payment_mode_id as modeid, pmod.payment_mode_desc as mode, prd.amount as amount,prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd.date as chequedate,prd.orgnisation_id as orgid, prd.unit_id as unitid, prd.created_date as date, bank.bank_name as banknamefrom billing.t_payment_refund_details prdinner join public.m_payment_mode_master pmod on pmod.payment_mode_id = prd.payment_mode_idinner join billing.t_payment_refund_master prm on prm.payment_refund_id = prd.payment_refund_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere prm.is_cn_or_deposit = 0;--xxx--- insert cash mode transactionsinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'IP'from refundpaydtls rpdwhere rpd.date between starttime and endtime and rpd.modeid = 1group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;---xxx--- insert other mode transactionsinsert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Payment', rpd.mode, rpd.date, 0, rpd.amount , rpd.unitid, rpd.orgid, rpd.id,coalesce(rpd.chequedate,rpd.date), 'IP', rpd.bankname,coalesce(rpd.chequenumber, rpd.cardnumber)from refundpaydtls rpdwhere rpd.date between starttime and endtime and rpd.modeid != 1;end;------------------------------End enddate-------------------------------------------------------------------------------start creditnotes--------------------declare voucherno integer = nextval('public.t_finaccial_tally_interface_seq');
begincreate or replace temporary viewcreditnotes as select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, refd.date_of_refund as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid from billing.m_credit_note_master crdinner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_idinner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_idinner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_idinner join service.m_service_master srv on srv.service_master_id = bdt.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_idinner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id where crd.cr_deu_amount = 0 and billmst.visit_type_id = 1group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund, crd.cr_net_amount;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id,hospital_id, tran_type)select voucherno, 'Payment', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP'from creditnotes crd where crd.refunddate between starttime and endtimegroup by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;-------------- Insert credit notes into tally interface end--------------------------------------------------- refund details view --------------------------------------create or replace temporary viewcreditnoterefunds as select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id = 1;-----------------------------xxx--------------------------------------------------------- insert cash mode transactions ------------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'from creditnoterefunds rfdwhere rfd.refunfdate between starttime and endtime and rfd.modeid = 1group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions ----------------------insert into public.t_finaccial_tally_interface (voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Payment', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate between starttime and endtime and rfd.modeid != 1group by rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;end;insert into public.t_synctimestamp(startDate,Enddate) values(starttime,endtime);
----------------------end postcreditnotes-------------------------------------return true;EXCEPTION when OTHERS then GET STACKED DIAGNOSTICS err_context = PG_EXCEPTION_CONTEXT;RAISE INFO 'Error Name:%',SQLERRM;RAISE INFO 'Error State:%', SQLSTATE;RAISE INFO 'Error Context:%', err_context;return false;COMMIT;end;$function$;

-- DROP FUNCTION public.fetchval(hstore, text);
CREATE OR REPLACE FUNCTION public.fetchval(hstore, text)RETURNS textLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_fetchval$function$;

-- DROP PROCEDURE public.fixedassetitemssaveproc(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.fixedassetitemssaveproc(IN itemarray json, INOUT failedrecres character varying)LANGUAGE plpgsqlAS $procedure$declareobj json;obj1 json;obj2 json;failedRecordJson json[];failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=2;isItemCodeExist boolean;isProductCodeExist boolean;isItemNameExist boolean;orgName varchar;unitName varchar;assetCategory varchar;productCategory varchar;formulationType varchar;itemCode varchar;productCode varchar;itemName varchar;genericName varchar;strength double precision;strengthUnitName varchar;pharmClass varchar;manufacture varchar;purchaseTax varchar;saleTax varchar;HSNCode varchar;storageUnit varchar;errorRemark varchar:=null;orgId integer:=null;unitId integer:=null;itemId integer:=null;createdBy integer:=null;updatedBy integer:=null;assetCatId integer:=null;prodCatId integer:=null;manufactureId integer:=null;purchasetaxId integer:=null;saleTaxId integer:=null;strengthUnitId integer:=null;storageUnitId integer:=null;isCSSD boolean=false;isModality boolean=false;isChargeableEquipment boolean=false;isAccessories boolean=false;isSpares boolean=false;isDialyser boolean=false;beginFOR obj IN SELECT * FROM json_array_elements(itemArray)loopflag:=false;failedRecordReason='';orgId:=obj-&gt;&gt;'organizationId';unitId:=obj-&gt;&gt;'unitId';createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
assetCategory:=obj-&gt;&gt;'assetCategory';productCategory:=obj-&gt;&gt;'productCategory';itemCode:=obj-&gt;&gt;'itemCode';productCode:=obj-&gt;&gt;'productCode';itemName:=obj-&gt;&gt;'assetName';manufacture:=obj-&gt;&gt;'manufacture';isCSSD =(case when (lower(obj-&gt;&gt;'isCSSD')='yes') then true else false end);
isModality =(case when (lower(obj-&gt;&gt;'isModality')='yes') then true else false end);
isChargeableEquipment =(case when (lower('sChargeableEquipment')='yes') then true else false end);
isAccessories =(case when (lower(obj-&gt;&gt;'isAccessories')='yes') then true else false end);
isSpares =(case when (lower(obj-&gt;&gt;'isSpares')='yes') then true else false end);
isDialyser =(case when (lower(obj-&gt;&gt;'isDialyser')='yes') then true else false end);
--avaiItemId :=checkItemExistAgainstOrg(itemName,itemCode,productCode,orgId);
---Check for unique itemif itemCode='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Item Code can not be blank,');
elseif itemCode!='' and length(itemCode)&lt;=10 thenisItemCodeExist=exists(select item.id from public.m_item item where lower(item.code)=lower(itemCode)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isItemCodeExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Item Code already exist,');
end if;elseif length(itemCode)&gt;10 thenflag=true;failedRecordReason=concat(failedRecordReason,'Item Code can not be greater than 10 characters,');
end if;---Product code checkif productCode='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Product Code can not be blank,');
elseif productCode!='' and length(productCode)&lt;=50 thenisProductCodeExist=exists(select item.id from public.m_item item where lower(item.product_code)=lower(productCode)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isProductCodeExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Product Code already exist,');
end if;elseif length(productCode)&gt;50 thenflag=true;failedRecordReason=concat(failedRecordReason,'Product Code can not be greater than 50 characters,');
end if;----Item Name check---Product code checkif itemName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset Name can not be blank,');
elseif itemName!='' and length(itemName)&lt;=500 thenisItemNameExist=exists(select item.id from public.m_item item where lower(item.name)=lower(itemName)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isItemNameExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset Name already exist,');
end if;elseif length(itemName)&gt;500 thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset Name can not be greater than 500 characters,');
end if;--asset categoryif assetCategory='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset category can not be blank,');
elsewith getAssetCatId as (select mac.id as id from public.m_asset_category mac where lower(mac.category)=lower(assetCategory) and mac.organization_id =orgId and mac.is_active=true and mac.is_deleted=false and mac.asset_type_id=assetTypeId limit 1)select id into assetCatId from getAssetCatId;if assetCatId is null thenwith assetCategorySave as (insert into public.m_asset_category (organization_id,unit_id,asset_type_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values (orgId,unitId,assetTypeId,((select count(mac.id) from public.m_asset_category mac where mac.organization_id =orgId )+1),assetCategory,true,updatedBy,now(),createdBy,now(),false) returning id)select id into assetCatId from assetCategorySave; end if;end if;--product categoryif productCategory='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Product category can not be blank,');
elsewith getProdCatId as (select pc.id as id from public.m_product_category pc where lower(pc.category)=lower(productCategory) and pc.asset_category_id =assetCatId and pc.organization_id=orgId and pc.is_active =true and pc.is_deleted=false limit 1)select id into prodCatId from getProdCatId;if prodCatId is null thenwith productCategorySave as (insert into public.m_product_category (organization_id,unit_id,asset_category_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,assetCatId,((select count(pc.id) from public.m_product_category pc where pc.organization_id=orgId)+1),productCategory,true,updatedBy,now(),createdBy,now(),false) returning id )select id into prodCatId from productCategorySave; end if;end if;--Maufactureif manufacture='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Manufacture can not be blank,');
elsewith getManufactureId as (select mm.id as id from public.m_manufacturer mm where lower(mm.name)=lower(manufacture) and mm.organization_id=orgIdand mm.is_active =true and mm.is_deleted =false limit 1)select id into manufactureId from getManufactureId;if manufactureId is null thenwith manufacturesave as(insert into public.m_manufacturer (organization_id,unit_id,code,name,address,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values (orgId,unitId,((select count(mm.id) from public.m_manufacturer mm where mm.organization_id=orgId)+1),manufacture,'',true,updatedBy,now(),createdBy,now(),false) returning id)select id into manufactureId from manufacturesave;end if;end if; ---Insert call for item masterif flag=false then with itemmasterSave as (insert into public.m_item (organization_id,unit_id,manufacturer_id,code,name,product_code,hsn_code,is_reusable,is_vaccin,is_otc,is_combination,is_batch_required,is_high_risk_product,is_psychotropic,is_kit,is_infusion,is_narcotic,is_active,updated_by,updated_date,added_by,added_date,is_deleted,is_consignment,is_consumable,is_hospital_formulary,product_category_id,is_cssd,is_modality,is_chargeable_equpiment,is_sterilize,is_implant,is_ot,is_critical,is_accessories,is_spares,is_injection,is_dialyser,reusable_percentage)values(orgId,unitId,manufactureId,itemCode,itemName,productCode,HSNCode,false,false,false,false,false,false,false,false,false,false,true,updatedBy,now(),createdBy,now(),false,false,false,false,prodCatId,isCSSD,isModality,isChargeableEquipment,false,false,false,false,isAccessories,isSpares,false,isDialyser,'[]')returning id)select id into itemId from itemmasterSave;end if;if flag=true thenfailedRec:=obj::varchar;if(failedRecordReason!='') thenfailedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
end if;failedRec:=concat(substring(failedRec,1,(length(failedRec)-1)),',"remark":','"',failedRecordReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
end if;end loop;failedRecRes :=failedRecordJson::varchar;failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
failedRecRes= replace(failedRecRes,'\','');
EXCEPTION when OTHERS then failedRecRes='failed to insert records';COMMIT;END;$procedure$;-- DROP PROCEDURE public.fixedassetopeningbalance(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.fixedassetopeningbalance(IN itemarray json, INOUT failedrecres character varying)LANGUAGE plpgsqlAS $procedure$declareobj json;obj1 json;obj2 json;taxDetailJson json;itemUomMapper json;failedRecordJson json[];storeItemMapperId integer:=null;isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;orgId integer:=null;unitId integer:=null;createdBy integer:=null;updatedBy integer:=null;storeName varchar;storeId integer;assetName varchar;itemId integer;vendorName varchar;serialNo varchar;expiryDate timestamp;quantity integer;manufactureYear integer;serviceProvider varchar;warrantyFrom date;warrantyTo date;pmsFrequency varchar;workingCondition varchar;specifications varchar;orgIdFlag integer:=null;storeIdFlag integer:=null;openingBalanceId integer;openingBalanceDetailId integer;opbNo varchar:= concat('OPB-',nextval('inventory.t_opening_balance_id_seq'));
screenId integer:=3;insertflag integer:=1;vendorId integer:=null;manufactureId integer:=null;freqId integer:=null;workingCondId integer:=null;beginFOR obj IN SELECT * FROM json_array_elements(itemArray)looporgId:=obj-&gt;&gt;'organizationId';unitId:=obj-&gt;&gt;'unitId';createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
storeName:=obj-&gt;&gt;'storeName';itemId:=obj-&gt;&gt;'itemId'; assetName:=obj-&gt;&gt;'assetName';serialNo:=obj-&gt;&gt;'serialNo';manufactureYear:=cast(obj-&gt;&gt;'manufactureYear' as integer);
vendorName:=obj-&gt;&gt;'vendor';serviceProvider:=obj-&gt;&gt;'serviceProvider';warrantyFrom=cast(obj-&gt;&gt;'warrantyFrom' as date);
warrantyTo=cast(obj-&gt;&gt;'warrantyTo' as date);
pmsFrequency:=obj-&gt;&gt;'pmsFrequency';workingCondition:=obj-&gt;&gt;'workingCondition';specifications:=obj-&gt;&gt;'specifications'; quantity:=cast(obj-&gt;&gt;'quantity' as integer);
 flag=false;failedRecordReason='';----Item name is exist and blank checkif assetName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset name can not be blank,');
elsewith getItemIdByName as (select mi.id as id from public.m_item mi where lower(mi.name)=lower(assetName) and mi.organization_id =orgId)select id into itemId from getItemIdByName;if itemId is null then failedRecordReason=concat(failedRecordReason,'Asset name not exist,');
flag=true;end if;end if;-------store name is exist and blank checkif storeName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Store name can not be blank,');
elsewith getStoreIdByName as (SELECT s.store_id as id FROM public.m_store sWHERE lower(s.store_name)=lower(storeName) and s.organization_id=orgId)select id into storeId from getStoreIdByName;if storeId is null then failedRecordReason=concat(failedRecordReason,'Store name not exist,');
flag=true;end if;end if;--check is item map to storeif storeId is not null and itemId is not null then with itemStoreMapping as(select msim.id from public.m_store_item_mapper msim where msim.item_id=itemId and msim.store_id=storeId and msim.organization_id=orgId limit 1)select mm.id into storeItemMapperId from itemStoreMapping mm;if storeItemMapperId is null theninsert into public.m_store_item_mapper(organization_id,unit_id,store_id,item_id,max_qty,min_qty,is_active,updated_by,updated_date,added_by,added_date,is_deleted) values(orgId,unitId,storeId,itemId,9999,1,true,updatedBy,now(),createdBy,now(),false);
end if;end if;----------Check vendor exist or notif vendorName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Vendor name can not be blank,');
elsewith getVendorIdByName as(select mv.id as id from public.m_vendor mv where lower(mv.name)=lower(vendorName) and mv.organization_id =orgId and mv.unit_id =unitId and mv.is_active=true and mv.is_deleted=false limit 1)select id into vendorId from getVendorIdByName;if vendorId is null then failedRecordReason=concat(failedRecordReason,'Vendor name not exist,');
flag=true;end if;end if;----------Check service Provider if serviceProvider='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Service provider can not be blank,');
elsewith getManufactureIdByName as(select mv.id as manufId from public.m_vendor mv where mv.is_service_provider =trueand lower(mv.name)=lower(serviceProvider) and mv.organization_id =orgIdand mv.unit_id =unitId and mv.is_active =true and mv.is_deleted =false limit 1)select manufId into manufactureId from getManufactureIdByName;if manufactureId is null then failedRecordReason=concat(failedRecordReason,'Service provider not exist,');
flag=true;end if;end if;---------------Check frequency exist or notif pmsFrequency='' then flag=true;failedRecordReason=concat(failedRecordReason,'PMS frequency can not be blank,');
elsewith getFrequencyIdByName as( select mf.id as id from inventory.m_pms_frequency mf where lower(mf.description)=lower(pmsFrequency)and mf.organization_id =orgId and mf.unit_id =unitId and mf.is_active =true and mf.is_deleted =false)select id into freqId from getFrequencyIdByName;if freqId is null then failedRecordReason=concat(failedRecordReason,'PMS frequency not exist,');
flag=true;end if;end if;---------------------Check working condition exist or notif workingCondition='' then flag=true;failedRecordReason=concat(failedRecordReason,'Working condition can not be blank,');
elsewith getworkingCondIdByName as(select mwc.id as id from inventory.m_working_condition mwc where lower(description)=lower(workingCondition) and mwc.is_active =true and mwc.is_deleted=false)select id into workingCondId from getworkingCondIdByName;if workingCondId is null then failedRecordReason=concat(failedRecordReason,'Working condition is not available,');
flag=true;end if;end if;--if orgIdFlag &lt;&gt; orgId or storeIdFlag &lt;&gt; storeId then if flag=false thenif insertflag=1 thenwith openingBalanceSave as (insert into inventory.t_opening_balance (organization_id,unit_id,store_id,status_id,opb_no,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,storeId,1,opbNo,true,updatedBy,now(),createdBy,now(),false) returning id)select id into openingBalanceId from openingBalanceSave;orgIdFlag:=orgId;storeIdFlag:=storeId;insertflag=2;end if;with openingBalanceDetailSave as(insert into inventory.t_opening_balance_detail (organization_id,unit_id,opening_balance_id,item_id,status_id,quantity,is_active,updated_by,updated_date,added_by,added_date,is_deleted,serial_number,vendor_id,service_provider_id,warranty_from,warranty_to,pms_frequency_id,year_of_manufacture,working_condition_id,remark)values(orgId,unitId,openingBalanceId,itemId,1,quantity,true,updatedBy,now(),createdBy,now(),false,serialNo,vendorId,manufactureId,warrantyFrom,warrantyTo,freqId,manufactureYear,workingCondId,specifications) returning id)select id into openingBalanceDetailId from openingBalanceDetailSave;end if;if flag=true thenif(failedRecordReason!='') thenfailedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
end if;failedRec:=obj::varchar;failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedRecordReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
end if;end loop;failedRecRes :=failedRecordJson::varchar;failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
failedRecRes= replace(failedRecRes,'\','');
EXCEPTION when OTHERS then failedRecRes='failed to insert records';COMMIT;END;$procedure$;-- DROP FUNCTION public.fun_crash_cart_after_insert_doc_dept();
CREATE OR REPLACE FUNCTION public.fun_crash_cart_after_insert_doc_dept()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.admission_id is not null thenUPDATE pharmacy.t_crash_cart_requestSET doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id),doc_spl_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id)WHERE id=new.id;END IF;IF NEW.encounter_id is not null thenUPDATE pharmacy.t_crash_cart_requestSET doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id),doc_spl_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)WHERE id=new.id;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.fun_issue_after_insert_doc_dept();
CREATE OR REPLACE FUNCTION public.fun_issue_after_insert_doc_dept()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.admission_id is not null thenUPDATE pharmacy.t_issueSET doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id),doc_spl_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id)WHERE id=new.id;END IF;IF NEW.encounter_id is not null thenUPDATE pharmacy.t_issueSET doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id),doc_spl_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)WHERE id=new.id;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.fun_prescription_after_insert_doc_dept();
CREATE OR REPLACE FUNCTION public.fun_prescription_after_insert_doc_dept()RETURNS triggerLANGUAGE plpgsqlAS $function$ begin IF NEW.admission_id is not null then UPDATE pharmacy.t_prescription SET doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id), dept_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id) WHERE id=new.id; END IF; IF NEW.encounter_id is not null then UPDATE pharmacy.t_prescription SET doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id), dept_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id) WHERE id=new.id; END IF; RETURN NEW; END; $function$;

-- DROP FUNCTION public.fun_sale_after_insert_doc_dept();
CREATE OR REPLACE FUNCTION public.fun_sale_after_insert_doc_dept()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.admission_id is not null thenUPDATE pharmacy.t_saleSET doctor_id=(select doctor_id from adt.t_admission where admission_id=NEW.admission_id),doc_spl_id = (select speciality_id from adt.t_admission where admission_id=NEW.admission_id)WHERE id=new.id;END IF;IF NEW.encounter_id is not null thenUPDATE pharmacy.t_saleSET doctor_id=(select doctor_id from opd.t_encounter_master where encounter_id=NEW.encounter_id),doc_spl_id = (select dept_id from opd.t_encounter_master where encounter_id=NEW.encounter_id)WHERE id=new.id;END IF;RETURN NEW;END;$function$;

