-- DROP FUNCTION public.get_masters_vender(date);
CREATE OR REPLACE FUNCTION public.get_masters_vender(p_date date)RETURNS TABLE(vender_id integer, hospital_id integer, unit_id integer, manufacturer_id integer, code character varying, name character varying, contact_person_name character varying, drug_license_no character varying, gst_no character varying, address character varying, country_id integer, phone_number integer, email_id character varying, payment_mode_id integer)LANGUAGE plpgsqlAS $function$DECLAREBEGINRETURN QUERY SELECT v.id as vender_id,v.organization_id as hospital_id,v.unit_id ,v.manufacturer_id ,v.code ,v."name",v.contact_person_name,v.drug_license_no,v.gst_no,v.address,v.country_id,v.phone_number,v.email_id,v.payment_mode_idFROM public.m_vendor vWHERE (v.updated_date::DATE&gt;='2019-01-01' OR v.added_date::DATE&gt;='2019-07-12')AND v.is_deleted = FALSE;END;$function$;

-- DROP FUNCTION public.get_mortality_rate(date);
CREATE OR REPLACE FUNCTION public.get_mortality_rate(param_date date)RETURNS TABLE(no_of_deaths integer)LANGUAGE plpgsqlAS $function$ declare v_no_of_deaths integer;v_no_of_discharge integer;v_mortality_rate real;beginselect (select count(*) as no_of_deaths from adt.t_discharge where discharge_type_id = 3)::real /((select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3) *100)as ration;end;$function$;

-- DROP FUNCTION public.get_mortality_rate();
CREATE OR REPLACE FUNCTION public.get_mortality_rate()RETURNS realLANGUAGE plpgsqlAS $function$ declare v_ration real;beginselect ((select count(*) as no_of_deaths from adt.t_discharge where discharge_type_id = 3)::real /(select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3)::real *100)into v_ration;return v_ration;end;$function$;

-- DROP FUNCTION public.get_mortality_rate(date, date);
CREATE OR REPLACE FUNCTION public.get_mortality_rate(fromdate date, todate date)RETURNS realLANGUAGE plpgsqlAS $function$ declare v_ration real;beginselect ((select count(*) as no_of_deaths from adt.t_discharge where discharge_type_id = 3 and discharge_date between fromDate and toDate)::real /(select count(*) as other_than_death from adt.t_discharge where discharge_type_id != 3 and discharge_date between fromDate and toDate)::real *100)into v_ration;return v_ration;end;$function$;

-- DROP FUNCTION public.get_records_without_icd(date);
CREATE OR REPLACE FUNCTION public.get_records_without_icd(p_date date)RETURNS TABLE(patient_id integer, first_name text, last_name text, ward_name character varying, bed_number character varying, admission_date date, discharge_date date, data_summary_released text, diagnosis_code character varying)LANGUAGE plpgsqlAS $function$BEGINRETURN QUERYselect distinct p.patient_id,p.first_name,p.last_name,wm.ward_name,bm.bed_number,a.created_date as "Admission Date",d.discharge_date as "Discharge Date",CASEWHEN tr.discharge_summary_note is null THEN'NO'ELSE'YES'endas "Discharge Summary Released",dm.code as "Diagnosis Code"from patient.t_patient_registration p INNER JOIN patient.t_patient_diagnosis_appo_mapper pd on p.patient_id=pd.patient_idINNER JOIN emr.m_diagnosis_master dm on pd.diagnosis_id=dm.diagnosis_idINNER JOIN adt.t_admission a on p.patient_id=a.patient_idINNER JOIN adt.t_admission_details ad on a.admission_id=ad.admission_idLEFT JOIN adt.m_ward_master wm ON ad.ward_id = wm.ward_idLEFT JOIN adt.m_bed_master bm ON ad.bed_id = bm.bed_idINNER JOIN adt.t_discharge d on a.admission_id=d.admission_idINNER JOIN adt.t_transfer_of_care_request tr on d.admission_id=tr.admission_id -- 1.Comment this line to see records as there are no common admission ids.where (a.created_date ::Date &gt;= p_date or a.updated_date:: Date&gt;=p_date ) and dm.code is null -- 2. Also, comment this line or set as not null, because there are no records with code null.and p.status='A';END;$function$;

-- DROP FUNCTION public.get_transactional_data(date, int4);
CREATE OR REPLACE FUNCTION public.get_transactional_data(created_date_param date, unit_id_param integer)RETURNS TABLE(created_date date, type text, total integer, srno integer, unit_id integer, unit_name text)LANGUAGE plpgsqlAS $function$ BEGIN RETURN QUERYSELECTpt.created_date :: date AS created_date,'Total' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMpatient.t_patient_registration ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.created_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.encounter_date :: date AS created_date,'Total Visit' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMopd.t_encounter_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.encounter_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.created_date :: date AS created_date,'Total Admission' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMadt.t_admission ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.created_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.discharge_date :: date AS created_date,'Total Discharge' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMadt.t_discharge ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.discharge_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.bill_date_time :: date AS created_date,'TOTAL OP BILLS' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMBilling.m_billing_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.visit_type_id = 1and pt.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.bill_date_time :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.bill_date_time :: date AS created_date,'TOTAL IP BILLS' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMBilling.m_billing_master ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.visit_type_id = 2and pt.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.bill_date_time :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.added_date :: date AS created_date,'TOTAL OP PHARMACY BILLS' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMpharmacy.t_sale ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.visit_type_id = 1and pt.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.added_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.added_date :: date AS created_date,'TOTAL IP PHARMACY BILLS' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMpharmacy.t_sale ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.visit_type_id = 2and pt.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.added_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.added_date :: date AS created_date,'TOTAL GRN' :: text AS type,count(*) AS total,1 AS srno,pt.unit_id,om.unit_nameFROMprocurement.t_good_receipt_note ptJOIN m_unit_master om ON pt.unit_id = om.unit_idwherept.created_date = created_date_paramand pt.unit_id = unit_id_paramGROUP BY(pt.added_date :: date),'OP' :: text,pt.unit_id,om.unit_nameunion allSELECTpt.order_date :: date AS created_date,'TOTAL LAB ORDER' :: text AS type,count(*) AS total,1 AS srno,pt.org_unit_id,om.unit_nameFROMt_order_details ptJOIN m_unit_master om ON pt.org_unit_id = om.unit_idwherept.service_id in (selectservice_master_idfromservice.m_service_master msmwheremsm.speciality_id = (selecttlc.lab_speciality_idfromt_lab_configuration tlcwheretlc.unit_id = pt.org_unit_idand tlc.status = 'A'))and pt.created_date = created_date_paramand pt.org_unit_id = unit_id_paramGROUP BY(pt.order_date :: date),'OP' :: text,pt.org_unit_id,om.unit_nameunion allSELECTpt.order_date :: date AS created_date,'TOTAL RIS ORDER' :: text AS type,count(*) AS total,1 AS srno,pt.org_unit_id,om.unit_nameFROMt_order_details ptJOIN m_unit_master om ON pt.org_unit_id = om.unit_idwherept.service_id in (selectservice_master_idfromservice.m_service_master msmwheremsm.speciality_id = (selecttlc.radiology_speciality_idfromt_unit_application_billing_configuration tlcwheretlc.unit_id = pt.org_unit_idand tlc.status = 'A'))and pt.created_date = created_date_paramand pt.org_unit_id = unit_id_paramGROUP BY(pt.order_date :: date),'OP' :: text,pt.org_unit_id,om.unit_name;END;$function$;

-- DROP FUNCTION public.get_two_decimal_places(float8);
CREATE OR REPLACE FUNCTION public.get_two_decimal_places(value double precision)RETURNS numericLANGUAGE plpgsqlAS $function$beginRETURN ROUND(value::numeric, 2);
