-- DROP FUNCTION public.icu_utilization(int4);
CREATE OR REPLACE FUNCTION public.icu_utilization(unitid integer)RETURNS booleanLANGUAGE plpgsqlAS $function$beginINSERT INTO adt.t_icu_utilization( from_ward_id,organization_id,unit_id,transfer_date,utilization_count)select from_ward_id,organization_id,unit_id,from_date::date ,count(*) as utilization_count from (select tt.transfer_id,tt.admission_id,tt.from_ward_id,tt.to_ward_id,tt.from_date,tt.to_date,tt.unit_id,tt.organization_idfrom adt.t_transfer ttinner join adt.m_ward_master wm on wm.ward_id = tt.from_ward_idwhere wm.is_icu = 'Y' and wm.status = 'A' and tt.from_date::date = CURRENT_DATE - INTERVAL '1 day'and tt.unit_id = unitid)icu_utilizationgroup by from_ward_id,organization_id,unit_id,from_date::Date ;return true;EXCEPTIONwhen OTHERS thenreturn false;COMMIT;end;$function$;

