CREATE OR REPLACE PROCEDURE public.insert_order_details_package_mapper(IN admission_id_param integer, IN unitid integer, IN orgid integer, IN visittypeids integer)LANGUAGE plpgsqlAS $procedure$BEGININSERT INTO public.t_order_details_package_mapper( order_details_id, service_id, package_id, is_package_service, is_cap_service, payee_id,service_amount, package_amount, unit_id, organization_id, status, t_sale_details_id,item_id, package_consumption_master_id, package_consumption_cap_details_id,pacakge_consumption_service_detail_id, package_qty, pacakge_consumtion_eo_detail_id,package_consumtion_eo_detail_id, tax_percentage, concession)SELECT order_details_id, service_id, NULL, 'N', 'N', NULL,service_id, service_amt, unitId, orgId, 'A', NULL, NULL,NULL, NULL, NULL, order_qty, NULL, NULL, 0.0, 0.0FROM t_order_details todWHERE order_id IN (SELECT order_idFROM t_order_master tomWHERE (visitTypeIds = 1 AND tom.encounter_id = admission_id_param)OR (visitTypeIds &lt;&gt; 1 AND tom.admission_id = admission_id_param))AND order_details_id NOT IN (SELECT order_details_idFROM t_order_details_package_mapper todpmWHERE order_details_id IN (SELECT order_details_idFROM t_order_details todWHERE order_id IN (SELECT order_idFROM t_order_master tomWHERE (visitTypeIds = 1 AND tom.encounter_id = admission_id_param)OR (visitTypeIds &lt;&gt; 1 AND tom.admission_id = admission_id_param))));
END;$procedure$;-- DROP FUNCTION public.insert_organization_and_unit_new(text, text, int4, int4, int4, int4, int4, int4, varchar, text, text, varchar, int4);
