-- DROP FUNCTION public.insert_subscription_data();
CREATE OR REPLACE FUNCTION public.insert_subscription_data()RETURNS voidLANGUAGE plpgsqlAS $function$ DECLAREunit_data RECORD;config RECORD;ekey varchar :='ssshhhhhhhhhhh!!!!';BEGINFOR unit_data IN SELECT u.* FROM m_unit_master u WHERE u.status = 'A' LOOPINSERT INTO public.m_unit_subscription_config(subscription_config_id, unit_id, organization_id, subscription_amount, subscription_discount, subscription_net_amount, subscription_tax, status, subscription_type, created_by, updated_by, created_date, updated_date)VALUES (nextval('public.m_unit_subscription_config_seq'), unit_data.unit_id, unit_data.organization_id, 1000.0, 0.0, 1000.0, 0.0, 'A', 'YEARLY', 230, 230, '2024-08-05 10:55:00.000', '2024-07-05 10:55:00.000');
SELECT * INTO config FROM public.m_unit_subscription_config WHERE unit_id = unit_data.unit_id;INSERT INTO public.t_unit_subscription_details(subscription_id, subscription_config_id, subscription_type, subscription_amount, subscription_discount, subscription_tax, subscription_net_amount, paid_amount, amount_paid_status, subscription_start_date, subscription_end_date, payment_order_id, subscription_status, payment_type, final_reminder_count, reminder_count, created_by, updated_by, status, created_date, updated_date, organization_id, unit_id, remark)VALUES(nextval('public.t_unit_subscription_details_seq'), config.subscription_config_id, config.subscription_type, pgp_sym_encrypt((config.subscription_amount::varchar),ekey), pgp_sym_encrypt((config.subscription_discount ::varchar),ekey), pgp_sym_encrypt((config.subscription_tax ::varchar),ekey), pgp_sym_encrypt((config.subscription_net_amount ::varchar),ekey), pgp_sym_encrypt((config.subscription_net_amount ::varchar),ekey), 'PAID', pgp_sym_encrypt(to_char(now(),'YYYY-MM-DD'),ekey), pgp_sym_encrypt(TO_CHAR(NOW() + INTERVAL '1 year', 'YYYY-MM-DD'),ekey), NULL, 'ACTIVE', 'BANK', 3, 3, 230, 230, 'A', CURRENT_DATE, CURRENT_DATE, unit_data.organization_id, unit_data.unit_id, 'Paid by abc');
END LOOP;END;$function$;

-- DROP FUNCTION public.insertdailystock(varchar);
CREATE OR REPLACE FUNCTION public.insertdailystock(unitid character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$begin if (select added_date::date from inventory.t_current_stock order by id desc limit 1) != now()::date thenINSERT INTO inventory.t_current_stock( batch_id,organization_id,unit_id,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount, is_active,updated_by,added_by,lcop)select id ,organization_id ,unit_id ,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount,is_active,updated_by,added_by,lcop from inventory.t_batch where current_quantity &lt;&gt; 0 and is_active = true ; end if;return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.insertdailystock(int4);
CREATE OR REPLACE FUNCTION public.insertdailystock(unitid integer)RETURNS booleanLANGUAGE plpgsqlAS $function$begin if (select added_date::date from inventory.t_current_stock order by id desc limit 1) != now()::date thenINSERT INTO inventory.t_current_stock( batch_id,organization_id,unit_id,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount, is_active,updated_by,added_by,lcop)select id ,organization_id ,unit_id ,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount,is_active,updated_by,added_by,lcop from inventory.t_batch where current_quantity &lt;&gt; 0 and is_active = true and unit_id = unitid; end if;return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.insertdailystock();
CREATE OR REPLACE FUNCTION public.insertdailystock()RETURNS booleanLANGUAGE plpgsqlAS $function$begin if (select added_date::date from inventory.t_current_stock order by id desc limit 1) != now()::date thenINSERT INTO inventory.t_current_stock( batch_id,organization_id,unit_id,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount, is_active,updated_by,added_by,lcop)select id ,organization_id ,unit_id ,uom_unit_id ,item_id ,batch_no ,lot_no ,current_quantity ,expiry_date ,cop ,rate , lending_price , tax_id ,tax_percentage ,tax_amount,is_active,updated_by,added_by,lcop from inventory.t_batch where current_quantity &lt;&gt; 0 and is_active = true; end if;return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.insertinto_patient_visit_metadata();
CREATE OR REPLACE FUNCTION public.insertinto_patient_visit_metadata()RETURNS booleanLANGUAGE plpgsqlAS $function$begintruncate table public.m_patient_visit_metadata;INSERT INTO public.m_patient_visit_metadata(patient_id,admission_id,encouter_id,visit_type_id, admission_number,encounter_number,encounter_date,created_date, doa, uhid_number, patientname, gender_name, bar_code, age, patientmobile, patientemail, reg_type, patientgender, patient_category, regdate, patientdob, identification_number, identification_expiry_date, patientaddress, zip_code,marital_status_name, doctorname, unit_name, unit_address, unit_email_id, post_code, unit_contact, registration_number, unit_website, currency_name, sub_currency, organization_address, organization_contact, organization_email_id,organization_logo, organization_desc, company_desc, referral_name, ageyear, agemonth, ageday, billing_bed_desc, bed_desc, contract_name, authorization_amount, authorization_date, authorization_no, is_final_submit, request_amount, request_date, request_no,insurance_number, insured_amount, employee_no_manual)select distinct adm.patient_id,adm.admission_id,0,2,adm.admission_number,NULL,now(),now(),adt.doa,patreg.uhid_number, patreg.patientname, patreg.gender_name, patreg.bar_code, patreg.age,patreg.patientmobile, patreg.patientemail, patreg.reg_type,patreg.patientgender, patreg.patient_category, patreg.regdate, patreg.patientdob,patreg.identification_number, patreg.identification_expiry_date, patreg.patientaddress, patreg.zip_code,patreg.marital_status_name ,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) AS doctorname,unitinformation.unit_name, unitinformation.unit_address, unitinformation.unit_email_id, unitinformation.post_code, unitinformation.unit_contact, unitinformation.registration_number, unitinformation.unit_website, unitinformation.currency_name,unitinformation.sub_currency, m_organization_master.organization_address, m_organization_master.organization_contact,m_organization_master.organization_email_id, m_organization_master.organization_logo, m_organization_master.organization_desc,cm.company_desc,m_refferel.referral_name,abs(date_part('Year'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,bedcat.billing_bed_desc ,bed.bed_desc,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,m_preauth_request_master.authorization_amount,m_preauth_request_master.authorization_date,m_preauth_request_master.authorization_no,m_preauth_request_master.is_final_submit,m_preauth_request_master.request_amount,m_preauth_request_master.request_date,m_preauth_request_master.request_no,psd.insurance_number,psd.insured_amount,psd.employee_no_manualfrom adt.t_admission adm left JOIN adt.t_admission_details adt ON adm.admission_id = adt.admission_id left JOIN patient.patientinformation patreg ON patreg.patient_id = adm.patient_idleft JOIN doctor.m_doctor_master doctormaster ON adm.admitting_doctor_id = doctormaster.doctor_idleft JOIN adt.m_billing_bed_category_master bedcat ON adt.billing_bed_category_id = bedcat.billing_bed_category_idleft join adt.m_bed_master bed on adt.bed_id = bed.bed_idleft JOIN unitinformation ON adm.unit_id = unitinformation.unit_idleft JOIN m_organization_master ON adm.organization_id = m_organization_master.organization_idleft JOIN opd.t_patient_sponsor_details psd ON adm.admission_id = psd.admission_id AND psd.priority_id = 1 AND psd.status = 'A'::bpcharLEFT JOIN billing.m_preauth_request_master ON adm.admission_id = m_preauth_request_master.admission_id AND m_preauth_request_master.status = 'A'::"char" and billing.m_preauth_request_master.is_final_submit='Y'LEFT JOIN service.m_company_contract_master ON psd.contract_id = m_company_contract_master.contract_idLEFT JOIN t_company_master cm ON cm.company_id = psd.payee_idLEFT JOIN t_referal_details admreff ON adm.admission_id = admreff.admission_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_idwhere adt.admission_details_id = (select max(admission_details_id) from adt.t_admission_details where admission_id = adm.admission_id);
INSERT INTO public.m_patient_visit_metadata(patient_id,admission_id,encouter_id,visit_type_id, admission_number,encounter_number,encounter_date,created_date, doa, uhid_number, patientname, gender_name, bar_code, age, patientmobile, patientemail, reg_type, patientgender, patient_category, regdate, patientdob, identification_number, identification_expiry_date, patientaddress, zip_code,marital_status_name, doctorname, unit_name, unit_address, unit_email_id, post_code, unit_contact, registration_number, unit_website, currency_name, sub_currency, organization_address, organization_contact, organization_email_id,organization_logo, organization_desc, company_desc, referral_name, ageyear, agemonth, ageday, billing_bed_desc, bed_desc, contract_name, authorization_amount, authorization_date, authorization_no, is_final_submit, request_amount, request_date, request_no,insurance_number, insured_amount, employee_no_manual)select distinct em.patient_id, 0,em.encounter_id,1,NULL,em.encounter_number,em.encounter_date,now(),em.created_date,patreg.uhid_number, patreg.patientname, patreg.gender_name, patreg.bar_code, patreg.age,patreg.patientmobile, patreg.patientemail, patreg.reg_type,patreg.patientgender, patreg.patient_category, patreg.regdate, patreg.patientdob,patreg.identification_number, patreg.identification_expiry_date, patreg.patientaddress, patreg.zip_code,patreg.marital_status_name ,concat('Dr.', ' ', doctormaster.first_name, ' ', doctormaster.last_name) AS doctorname,unitinformation.unit_name, unitinformation.unit_address, unitinformation.unit_email_id, unitinformation.post_code, unitinformation.unit_contact, unitinformation.registration_number, unitinformation.unit_website, unitinformation.currency_name,unitinformation.sub_currency, m_organization_master.organization_address, m_organization_master.organization_contact,m_organization_master.organization_email_id, m_organization_master.organization_logo, m_organization_master.organization_desc,cm.company_desc,m_refferel.referral_name,abs(date_part('Year'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageyear,abs(date_part('month'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS agemonth,abs(date_part('Day'::text, age(patreg.patientdob, 'now'::text::date::timestamp without time zone)))::integer AS ageday,NULL ,NULL,COALESCE(m_company_contract_master.contract_name, ''::text) AS contract_name,0, now(), NULL, NULL, 0, now(),NULL,psd.insurance_number,psd.insured_amount,psd.employee_no_manualfrom opd.t_encounter_master em JOIN patientinformation patreg ON patreg.patient_id = em.patient_id left JOIN doctor.m_doctor_master doctormaster ON em.doctor_id = doctormaster.doctor_id left JOIN unitinformation ON em.unit_id = unitinformation.unit_idleft JOIN m_organization_master ON em.organization_id = m_organization_master.organization_idleft JOIN opd.t_patient_sponsor_details psd ON em.encounter_id = psd.encounter_id AND psd.priority_id = 1 AND psd.status = 'A'::bpchar LEFT JOIN service.m_company_contract_master ON psd.contract_id = m_company_contract_master.contract_idLEFT JOIN t_company_master cm ON cm.company_id = psd.payee_idLEFT JOIN t_referal_details admreff ON em.encounter_id = admreff.encounter_idLEFT JOIN adt.m_referral_master m_refferel ON admreff.referral_id = m_refferel.referral_id;return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.isdefined(hstore, text);
CREATE OR REPLACE FUNCTION public.isdefined(hstore, text)RETURNS booleanLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_defined$function$;

