CREATE OR REPLACE FUNCTION public.isexists(hstore, text)RETURNS booleanLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_exists$function$;

-- DROP PROCEDURE public.itemopeningbalanceproc(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.itemopeningbalanceproc(IN itemarray json, INOUT failedrecres character varying)LANGUAGE plpgsqlAS $procedure$declareobj json;obj1 json;obj2 json;taxDetailJson json;itemUomMapper json;failedRecordJson json[];storeItemMapperId integer:=null;isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;orgId integer:=null;unitId integer:=null;createdBy integer:=null;updatedBy integer:=null;storeName varchar;storeId integer;itemId integer;itemUOM varchar;batchNo varchar;expiryDate timestamp:=null;quantity integer;copPrice double precision;mrpPrice double precision;mrpUom varchar;taxPer double precision;markupPer double precision;taxId integer;taxAmount double precision;orgIdFlag integer:=null;storeIdFlag integer:=null;openingBalanceId integer;openingBalanceDetailId integer;itemUomTypeId integer;itemUomUnitId integer;mrpUomTypeId integer;isExceptionOccur boolean=false;opbNo varchar:='';totalAmount double precision;screenId integer:=3;lcopAmount double precision;insertflag integer:=1;itemUomType varchar;itemName varchar;beginFOR obj IN SELECT * FROM json_array_elements(itemArray)loopbeginorgId:=cast(obj-&gt;&gt;'organizationId' as integer);
unitId:=cast(obj-&gt;&gt;'unitId'as integer);
createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
storeName:=obj-&gt;&gt;'storeName';itemId:=obj-&gt;&gt;'itemId'; batchNo:=obj-&gt;&gt;'batchNo';--quantity:=cast(obj-&gt;&gt;'quantity' as integer);
 --copPrice:=cast(obj-&gt;&gt;'COP' as double precision);
mrpPrice:=cast(obj-&gt;&gt;'MRP' as double precision);
mrpUom:=obj-&gt;&gt;'mrpUom';--taxPer:=cast(obj-&gt;&gt;'taxPer' as double precision);
markupPer:=cast(obj-&gt;&gt;'markupPer' as double precision);
itemName:=obj-&gt;&gt;'itemName';--taxAmount:=cast(obj-&gt;&gt;'taxAmount' as double precision);
itemUomType:=obj-&gt;&gt;'itemUomType';itemUOM:=obj-&gt;&gt;'uomUnit';flag=false;failedRecordReason:='';isExceptionOccur=false;if batchNo='' thenbatchNo='NA';end if;if (obj-&gt;&gt;'expiryDate')='' thenexpiryDate=null;elseexpiryDate:=TO_TIMESTAMP(obj-&gt;&gt;'expiryDate', 'YYYY-MM-DD');
end if;-- if (batchNo='' or lower(batchNo)=lower('NA')) then -- expiryDate:=null;-- else-- expiryDate:=TO_TIMESTAMP(obj-&gt;&gt;'expiryDate', 'YYYY-MM-DD');
-- end if;----Item name is exist and blank checkif itemName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Item name can not be blank,');
elsewith getItemIdByName as (select mi.id as id from public.m_item mi where lower(mi.name)=lower(itemName) and mi.organization_id =orgId)select id into itemId from getItemIdByName;if itemId is null then failedRecordReason=concat(failedRecordReason,'Item name not exist,');
flag=true;elsewith getTaxIdFromItem as (SELECT mt.id as id,mt.tax_percentage as per FROM public.m_item item inner join public.m_tax mt on mt.id=item.s_tax_id WHERE item.id=itemId and mt.organization_id=orgId and item.is_active=true and item.is_deleted=false limit 1)select id,per into taxId,taxPer from getTaxIdFromItem;--select taxper into taxPer from getTaxIdFromItem;end if;end if;-------store name is exist and blank checkif storeName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Store name can not be blank,');
elsewith getStoreIdByName as (SELECT s.store_id as id FROM public.m_store sWHERE lower(s.store_name)=lower(storeName) and s.organization_id=orgId)select id into storeId from getStoreIdByName;if storeId is null then failedRecordReason=concat(failedRecordReason,'Store name not exist,');
flag=true;end if;end if;--check is item map to storeif storeId is not null and itemId is not null then with itemStoreMapping as(select msim.id from public.m_store_item_mapper msim where msim.item_id=itemId and msim.store_id=storeId and msim.organization_id=orgId limit 1)select mm.id into storeItemMapperId from itemStoreMapping mm;if storeItemMapperId is null theninsert into public.m_store_item_mapper(organization_id,unit_id,store_id,item_id,max_qty,min_qty,is_active,updated_by,updated_date,added_by,added_date,is_deleted) values(orgId,unitId,storeId,itemId,9999,1,true,updatedBy,now(),createdBy,now(),false);
end if;end if;if batchNo='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Batch Number can not be blank,');
end if;------------------Check quantityif (obj-&gt;&gt;'quantity')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Quantity can not be blank,');
elsequantity:=NULLIF(regexp_replace(obj-&gt;&gt;'quantity', '\D','','g'), '')::integer;if quantity is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Incorrect Quantity,');
elsequantity=cast(replace(obj-&gt;&gt;'quantity',',','') as integer);
end if;end if;-------------------Check COP Priceif (obj-&gt;&gt;'cop')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'COP can not be blank,');
elsecopPrice:=NULLIF(regexp_replace(obj-&gt;&gt;'cop', '\D','','g'), '')::integer;if copPrice is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Incorrect COP,');
elsecopPrice=cast(replace(obj-&gt;&gt;'cop',',','') as double precision);
end if;end if;-------------------Check MRP Priceif (obj-&gt;&gt;'mrp')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'MRP can not be blank,');
elsemrpPrice:=NULLIF(regexp_replace(obj-&gt;&gt;'mrp', '\D','','g'), '')::integer;if mrpPrice is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Incorrect MRP,');
elsemrpPrice=cast(replace(obj-&gt;&gt;'mrp',',','') as double precision);
end if;end if;-------------------Check Markup Percentageif (obj-&gt;&gt;'markupPer')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Markup % can not be blank,');
elsemarkupPer:=NULLIF(regexp_replace(obj-&gt;&gt;'markupPer', '\D','','g'), '')::integer;if markupPer is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Incorrect Markup %,');
elsemarkupPer=cast(obj-&gt;&gt;'markupPer' as double precision);
end if;end if;------Tax percentage check-- if (obj-&gt;&gt;'taxPercentage')='' then-- flag=true;-- failedRecordReason=concat(failedRecordReason,'Tax % can not be blank,');
-- else-- --purchaseTaxPer:=cast(obj-&gt;&gt;'purchaseTaxPer' as float8) ;-- taxPer:=NULLIF(regexp_replace(obj-&gt;&gt;'taxPercentage', '\D','','g'), '')::float8;-- -- if taxPer is null then-- flag=true;-- failedRecordReason=concat(failedRecordReason,'Inccorrect Tax %,');
-- else-- taxPer=cast(obj-&gt;&gt;'taxPercentage' as double precision);
-- with getTaxIdByPer as (SELECT mt.id as id FROM public.m_tax mt -- WHERE mt.tax_percentage=taxPer and mt.organization_id=orgId and mt.is_active=true and mt.is_deleted=false limit 1)-- select id into taxId from getTaxIdByPer;-- -- if taxId is null then-- flag=true;-- failedRecordReason=concat(failedRecordReason,'Tax % not exist,',taxPer,orgId);
-- end if;-- -- end if;-- -- end if;-- -------------MRP Price and COP Price check if mrpPrice is not null and copPrice is not null then if (mrpPrice &lt; copPrice) thenflag=true;failedRecordReason=concat(failedRecordReason,'MRP price should be equal or greater than COP price,');
end if;end if;--------calculation of total amount and tax amountif quantity is not null and mrpPrice is not null and copPrice is not null and taxId is not null then totalAmount:=quantity*copPrice;taxAmount:=(totalAmount*taxPer)/100;lcopAmount:=(totalAmount+taxAmount)/quantity;end if; -------------Check UOM Unitif itemUOM='' thenflag=true;failedRecordReason=concat(failedRecordReason,'UOM Unit can not be blank,');
else with getUOMUnitId as (SELECT uu.id as id,muom.uom_type_id as typeid FROM public.m_uom_unit uuinner join public.m_unit_of_measurement muom on muom.uom_unit_id=uu.idWHERE lower(uu.unit)=lower(itemUOM) and uu.is_active =true and uu.is_deleted =false and muom.item_id=itemId order by muom.id desc limit 1)select id,typeid into itemUomUnitId,itemUomTypeId from getUOMUnitId;--select typeid into itemUomTypeId from getUOMUnitId;if itemUomUnitId is null then flag=true;failedRecordReason=concat(failedRecordReason,'UOM Unit not exist,');
end if;end if;---------------get mrp uom type id by unit---------------if mrpUom='' thenflag=true;failedRecordReason=concat(failedRecordReason,'MRP UOM Unit can not be blank,');
else with getMrpUnitByType as (SELECT uu.id as id,muom.uom_type_id as typeid FROM public.m_uom_unit uuinner join public.m_unit_of_measurement muom on muom.uom_unit_id=uu.idWHERE lower(uu.unit)=lower(mrpUom) and uu.is_active =true and uu.is_deleted =false and muom.item_id=itemId order by muom.id desc limit 1)select typeid into mrpUomTypeId from getMrpUnitByType;if mrpUomTypeId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'MRP UOM Unit not exist,');
end if;end if;--if orgIdFlag &lt;&gt; orgId or storeIdFlag &lt;&gt; storeId then if flag=false thenif insertflag=1 thenopbNo=concat('OPB-',(select last_value from inventory.t_opening_balance_id_seq)+1);
with openingBalanceSave as (insert into inventory.t_opening_balance (organization_id,unit_id,store_id,status_id,opb_no,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,storeId,1,opbNo,true,updatedBy,now(),createdBy,now(),false) returning id)select id into openingBalanceId from openingBalanceSave;orgIdFlag:=orgId;storeIdFlag:=storeId;insertflag=2;end if;with openingBalanceDetailSave as(insert into inventory.t_opening_balance_detail (organization_id,unit_id,opening_balance_id,item_id,uom_type_id,uom_unit_id,batch_no,expiry_date,quantity,cop,mrp,amount_cop,markup,tax_id,tax_percentage,tax_amount,status_id,is_active,updated_by,updated_date,added_by,added_date,is_deleted,mrp_uom_type_id,lcop)values(orgId,unitId,openingBalanceId,itemId,itemUomTypeId,itemUomUnitId,batchNo,expiryDate,quantity,copPrice,mrpPrice,totalAmount,markupPer,taxId,taxPer,taxAmount,1,true,updatedBy,now(),createdBy,now(),false,mrpUomTypeId,lcopAmount) returning id)select id into openingBalanceDetailId from openingBalanceDetailSave;with getTaxDetail as(SELECT array_to_json(array_agg(row_to_json(data))) from(selectmtd.tax_component_id as id,mtd.tax_percentage as taxperfrom public.m_tax_detail mtd wheremtd.tax_id =taxIdand mtd.is_active=trueand mtd.organization_id =orgId) data)select * into taxDetailJson from getTaxDetail;--save tax component wiseFOR obj1 IN SELECT * FROM json_array_elements(taxDetailJson)loopinsert into inventory.t_opb_tax_component(opb_detail_id,tax_component_id,percentage,amount,is_active,updated_by,updated_date,added_by,added_date,is_deleted,organization_id,unit_id)values(openingBalanceDetailId,cast(obj1-&gt;&gt;'id' as integer),cast(obj1-&gt;&gt;'taxper' as double precision),((totalAmount*(cast(obj1-&gt;&gt;'taxper' as double precision)))/100),true,updatedBy,now(),createdBy,now(),false,orgId,unitId);
end loop;--get all item uom mapperwith getItemUomMapper as(SELECT array_to_json(array_agg(row_to_json(data))) from(selectuom.uom_type_id as typeid,uom.uom_unit_id as uomunitid,uom.conversions as conv,uom.ip_uom as ipuom,uom.op_uom as opuom,uom.store_uom as storeuomfrom public.m_unit_of_measurement uom whereuom.item_id=itemIdand uom.is_active=trueand uom.organization_id =orgId) data)select * into itemUomMapper from getItemUomMapper;FOR obj2 IN SELECT * FROM json_array_elements(itemUomMapper)loop---insert into opb uom mapperinsert into inventory.t_opb_uom_mapper (organization_id,unit_id,opb_detail_id,uom_type_id,uom_unit_id,conversions,ip_uom,op_uom,store_uom,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,openingBalanceDetailId,cast(obj2-&gt;&gt;'typeid' as integer),cast(obj2-&gt;&gt;'uomunitid' as integer),cast(obj2-&gt;&gt;'conv' as integer),cast(obj2-&gt;&gt;'ipuom' as boolean),cast(obj2-&gt;&gt;'opuom' as boolean),cast(obj2-&gt;&gt;'storeuom' as boolean),true,updatedBy,now(),createdBy,now(),false);
end loop;end if;if flag=true thenif(failedRecordReason!='') thenfailedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
end if;failedRec:=obj::varchar;failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedRecordReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
end if;exceptionwhen OTHERS then failedRecordReason:=concat((replace(sqlerrm,'"',''))::varchar,'');
--failedRecordReason:='';failedRec:=obj::varchar;failedRec:=concat(substring(failedRec,1,(length(failedRec)-2)),',"remark":','"',failedRecordReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
 isExceptionOccur=true;-- commit;end; end loop;--select substring('{{"a"},{"b"}}',2,length('{{"a"},{"b"}}')-2)failedRecRes :=failedRecordJson::varchar;failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
failedRecRes= replace(failedRecRes,'\','');
if isExceptionOccur thencommit;end if;EXCEPTION when OTHERS then -- failedRecRes='failed to insert records';COMMIT;END;$procedure$;-- DROP PROCEDURE public.nonpharmacyitemssaveproc(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.nonpharmacyitemssaveproc(IN itemarray json, INOUT failedrecres character varying)LANGUAGE plpgsqlAS $procedure$declareobj json;obj1 json;obj2 json;failedrecordjson json[];failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;isItemCodeExist boolean;isProductCodeExist boolean;isItemNameExist boolean;orgName varchar;unitName varchar;assetCategory varchar;productCategory varchar;formulationType varchar;itemCode varchar;productCode varchar;itemName varchar;genericName varchar;strength double precision;strengthUnitName varchar;pharmClass varchar;manufacture varchar;purchaseTax varchar;saleTax varchar;HSNCode varchar;storageUnit varchar;errorRemark varchar:=null;--All flagsitemReusable boolean=false;isVaccine boolean=false;isCombination boolean=false;batchReq boolean=false;highRisk boolean=false;psychotropic boolean=false;isKit boolean=false;isInfusion boolean=false;isNarcotic boolean=false;hospitalFormulary boolean=false;isConsumable boolean=false;isInjection boolean=false;purchaseUOMUnit varchar;purchaseUOMQty integer:=null;stockUOMUnit varchar;stockUOMQty integer:=null;dispenseUOMUnit varchar;dispenseUOMQty integer:=null;ipUOM varchar;opUOM varchar;storeUOM varchar;orgId integer:=null;unitId integer:=null;itemId integer:=null;createdBy integer:=null;updatedBy integer:=null;assetCatId integer:=null;prodCatId integer:=null;genericId integer:=null;pharmacologyClassId integer:=null;manufactureId integer:=null;formulationTypeId integer:=null;purchasetaxId integer:=null;saleTaxId integer:=null;strengthUnitId integer:=null;storageUnitId integer:=null;purchaseUomUnitId integer:=null;stockUomUnitId integer:=null;dispenseUomUnitId integer:=null;ipUomTypeId integer:=null;opUomTypeId integer:=null;storeUomTypeId integer:=null;purchaseTaxPer float8;saleTaxPer float8;beginFOR obj IN SELECT * FROM json_array_elements(itemArray)loopflag:=false;failedRecordReason='';-- RAISE NOTICE 'output from space %', obj-&gt;&gt;'type';orgId:=obj-&gt;&gt;'organizationId';unitId:=obj-&gt;&gt;'unitId';createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
