CREATE OR REPLACE FUNCTION public.ord_visible_dept_function()RETURNS triggerLANGUAGE plpgsqlAS $function$BEGINIF NEW.is_order_visible_dept = 'I' THENUPDATE t_order_detailsSET is_order_visible_dept = 'A'WHERE order_details_id = NEW.order_details_idAND service_id IN (SELECT service_master_idFROM service.M_Service_masterWHERE speciality_id IN (SELECT lab_speciality_idFROM t_lab_configurationWHERE status = 'A')OR speciality_id IN (SELECT radiology_speciality_idFROM t_unit_application_billing_configurationWHERE status = 'A'));
END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.orderedamountforadmittedpatient(float8);
CREATE OR REPLACE FUNCTION public.orderedamountforadmittedpatient(admid double precision)RETURNS double precisionLANGUAGE plpgsqlAS $function$DECLARE passed double precision;BEGIN select sum(chargesdetail.net_amount) as OrderedAmount into passed from public.t_order_master Charges inner join public.t_order_details ChargesDetail on charges.order_id = ChargesDetail.order_idwhere charges.visit_type_id=2 and ChargesDetail.is_drug='N' and ChargesDetail.service_is_billed =0 and ChargesDetail.package_consumption_amt = 0 and ChargesDetail.ord_cancelled = 'N'and charges.Admission_id=Admid;RETURN passed;END;$function$;

-- DROP FUNCTION public.patient_document_procedure();
CREATE OR REPLACE FUNCTION public.patient_document_procedure()RETURNS triggerLANGUAGE plpgsqlAS $function$beginINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)VALUES('PatientDocumentMapper', 'PENDING', now(),new.encounter_doc_id, 'NORMAL', 0, new.created_by, now(), 'INSERT', 'HIS',new.organisation_id);
RETURN NEW;END;$function$;

-- DROP FUNCTION public.patient_document_update_procedure();
CREATE OR REPLACE FUNCTION public.patient_document_update_procedure()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif new.status='A' thenINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)VALUES('PatientDocumentMapper', 'PENDING', now(),new.encounter_doc_id, 'NORMAL', 0, new.created_by, now(), 'INSERT', 'HIS',new.organisation_id);
elseINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)VALUES('PatientDocumentMapper', 'PENDING', now(),new.encounter_doc_id, 'NORMAL', 0, new.created_by, now(), 'UPDATE', 'HIS',new.organisation_id);
end if;RETURN NEW;END;$function$;

