-- DROP FUNCTION public.patient_registration_procedure();
CREATE OR REPLACE FUNCTION public.patient_registration_procedure()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.registration_type_id=1 thenINSERT INTO public.t_schedule_logs(table_name, status, date_time, record_id, priority, error_count, added_by, added_date, "action", application,org_id)VALUES('PatientRegistration', 'PENDING', now(), NEW.patient_id, 'NORMAL', 0, NEW.created_by, now(), 'INSERT', 'HIS',new.organization_id);
END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.percentage_of_medical_records(out numeric);
CREATE OR REPLACE FUNCTION public.percentage_of_medical_records(OUT percentage numeric)RETURNS numericLANGUAGE plpgsqlAS $function$declarev_percentage numeric:=0;beginwith not_discharge as ( select count(1) as ntdis_count from adt.t_admission adwhere ad.admission_id not in (select dis.admission_id from adt.t_discharge dis )and ad.status='A' ) select (a.ntdis_count/(select count(1) as disc_count from adt.t_admission adwhere ad.admission_id in (select dis.admission_id from adt.t_discharge dis )and ad.status='A' )) *100 into v_percentagefrom not_discharge a;raise notice 'v_percentage%',v_percentage;percentage:=v_percentage;end;$function$;

