-- DROP PROCEDURE public.pharmacyitemssaveproc(in json, inout varchar);
CREATE OR REPLACE PROCEDURE public.pharmacyitemssaveproc(IN itemarray json, INOUT failedrecres character varying)LANGUAGE plpgsqlAS $procedure$--INOUT failedrecordjson json[]declareobj json;obj1 json;obj2 json;failedrecordjson json[];failedRecordReason varchar:='';failedRec varchar;failedRec1 varchar;isExist BOOLEAN;avaiItemId integer:=null;flag boolean;assetTypeId integer:=1;isItemCodeExist boolean;isProaductCodeExist boolean;isItemNameExist boolean;isProductCodeExist boolean;orgName varchar;unitName varchar;assetCategory varchar;productCategory varchar;formulationType varchar;itemCode varchar;productCode varchar;itemName varchar;genericName varchar;strength double precision;strengthUnitName varchar;pharmClass varchar;manufacture varchar;purchaseTax varchar;saleTax varchar;HSNCode varchar;storageUnit varchar;errorRemark varchar:=null;--All flagsitemReusable boolean=false;isVaccine boolean=false;isCombination boolean=false;batchReq boolean=false;highRisk boolean=false;psychotropic boolean=false;isKit boolean=false;isInfusion boolean=false;isNarcotic boolean=false;hospitalFormulary boolean=false;isConsumable boolean=false;isInjection boolean=false;purchaseUOMUnit varchar;purchaseUOMQty integer:=null;stockUOMUnit varchar;stockUOMQty integer:=null;dispenseUOMUnit varchar;dispenseUOMQty integer:=null;ipUOM varchar;opUOM varchar;storeUOM varchar;orgId integer:=null;unitId integer:=null;itemId integer:=null;createdBy integer:=null;updatedBy integer:=null;assetCatId integer:=null;prodCatId integer:=null;genericId integer:=null;pharmacologyClassId integer:=null;manufactureId integer:=null;formulationTypeId integer:=null;purchasetaxId integer:=null;saleTaxId integer:=null;strengthUnitId integer:=null;storageUnitId integer:=null;purchaseUomUnitId integer:=null;stockUomUnitId integer:=null;dispenseUomUnitId integer:=null;ipUomTypeId integer:=null;opUomTypeId integer:=null;storeUomTypeId integer:=null;purchaseTaxPer float8:=null;saleTaxPer float8:=null;begin-- for counter in 1..10 loop--raise notice 'counter: %', counter;FOR obj IN SELECT * FROM json_array_elements(itemArray)loopflag:=false; failedRecordReason:='';-- RAISE NOTICE 'output from space %', obj-&gt;&gt;'type';orgId:=obj-&gt;&gt;'organizationId';unitId:=obj-&gt;&gt;'unitId';createdBy:=cast(obj-&gt;&gt;'createdBy' as integer);
updatedBy:=cast(obj-&gt;&gt;'createdBy' as integer);
assetCategory:=obj-&gt;&gt;'assetCategory';productCategory:=obj-&gt;&gt;'productCategory';formulationType:=obj-&gt;&gt;'formulationType';itemCode:=obj-&gt;&gt;'itemCode';productCode:=obj-&gt;&gt;'productCode';itemName:=obj-&gt;&gt;'itemName';genericName:=obj-&gt;&gt;'genericName';strengthUnitName:=obj-&gt;&gt;'strengthUnitName';pharmClass:=obj-&gt;&gt;'pharmacologyClassification';manufacture:=obj-&gt;&gt;'manufacture';-- purchaseTaxPer:=cast(obj-&gt;&gt;'purchaseTaxPer' as float8) ;saleTaxPer:=cast(obj-&gt;&gt;'saleTaxPer' as float8);
HSNCode:=obj-&gt;&gt;'HSNCode';storageUnit:=obj-&gt;&gt;'storageUnit';purchaseUOMUnit:=obj-&gt;&gt;'purchaseUOMUnit';purchaseUOMQty:=obj-&gt;&gt;'purchaseToStockConvQty';stockUOMUnit:=obj-&gt;&gt;'stockUOMUnit';stockUOMQty:=obj-&gt;&gt;'stockToDispenseConvQty';dispenseUOMUnit:=obj-&gt;&gt;'dispenseUOMUnit';dispenseUOMQty:=obj-&gt;&gt;'dispenseUOMQty';ipUOM:=obj-&gt;&gt;'ipUOM';opUOM:=obj-&gt;&gt;'opUOM';storeUOM:=obj-&gt;&gt;'storeUOM';isVaccine =(case when (lower(obj-&gt;&gt;'isVaccine')='yes') then true else false end);
isCombination =(case when (lower(obj-&gt;&gt;'isCombination')='yes') then true else false end);
batchReq =(case when (lower(obj-&gt;&gt;'batchRequired')='yes') then true else false end);
isKit =(case when (lower(obj-&gt;&gt;'isKit')='yes') then true else false end);
isInfusion =(case when (lower(obj-&gt;&gt;'isInfusion')='yes') then true else false end);
isNarcotic =(case when (lower(obj-&gt;&gt;'isNarcotic')='yes') then true else false end);
hospitalFormulary =(case when (lower(obj-&gt;&gt;'hospitalFormulary')='yes') then true else false end);
isConsumable =(case when (lower(obj-&gt;&gt;'isConsumable')='yes') then true else false end);
isInjection =(case when (lower(obj-&gt;&gt;'isInjection')='yes') then true else false end);
--avaiItemId :=checkItemExistAgainstOrg(itemName,itemCode,productCode,orgId);
---Check for unique itemif itemCode='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Item code can not be blank,');
elseif itemCode!='' and length(itemCode)&lt;=10 thenisItemCodeExist=exists(select item.id from public.m_item item where lower(item.code)=lower(itemCode)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isItemCodeExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Item code already exist,');
end if;elseif length(itemCode)&gt;10 thenflag=true;failedRecordReason=concat(failedRecordReason,'Item code can not be greater than 10 characters,');
end if;---Product code checkif productCode='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Product code can not be blank,');
elseif productCode!='' and length(productCode)&lt;=50 thenisProductCodeExist=exists(select item.id from public.m_item item where lower(item.product_code)=lower(productCode)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isProductCodeExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Product code already exist,');
end if;elseif length(productCode)&gt;50 thenflag=true;failedRecordReason=concat(failedRecordReason,'Product code can not be greater than 50 characters,');
end if;----Item Name check---Product code checkif itemName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Item name can not be blank,');
elseif itemName!='' and length(itemName)&lt;=500 thenisItemNameExist=exists(select item.id from public.m_item item where lower(item.name)=lower(itemName)and item.organization_id=orgId --and item.unit_id=unitId and item.is_active=true and item.is_deleted=false limit 1);
if isItemNameExist thenflag=true;failedRecordReason=concat(failedRecordReason,'Item name already exist,');
end if;elseif length(itemName)&gt;500 thenflag=true;failedRecordReason=concat(failedRecordReason,'Item name can not be greater than 500 characters,');
end if;--asset categoryif assetCategory='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Asset category can not be blank,');
elsewith getAssetCatId as (select mac.id as id from public.m_asset_category mac where lower(mac.category)=lower(assetCategory) and mac.organization_id =orgId and mac.is_active=true and mac.is_deleted=false and mac.asset_type_id=assetTypeId limit 1)select id into assetCatId from getAssetCatId;if assetCatId is null thenwith assetCategorySave as (insert into public.m_asset_category (organization_id,unit_id,asset_type_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values (orgId,unitId,assetTypeId,((select count(mac.id) from public.m_asset_category mac where mac.organization_id =orgId )+1),assetCategory,true,updatedBy,now(),createdBy,now(),false) returning id)select id into assetCatId from assetCategorySave; end if;end if;--product categoryif productCategory='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Product category can not be blank,');
elsewith getProdCatId as (select pc.id as id from public.m_product_category pc where lower(pc.category)=lower(productCategory) and pc.asset_category_id =assetCatId and pc.organization_id=orgId and pc.is_active =true and pc.is_deleted=false limit 1)select id into prodCatId from getProdCatId;if prodCatId is null thenwith productCategorySave as (insert into public.m_product_category (organization_id,unit_id,asset_category_id,code,category,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,assetCatId,((select count(pc.id) from public.m_product_category pc where pc.organization_id=orgId)+1),productCategory,true,updatedBy,now(),createdBy,now(),false) returning id )select id into prodCatId from productCategorySave; end if;end if;--Formulation Typeif formulationType='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Formulation type can not be blank,');
elsewith getFormulationTypeId as (select mft.id as id from public.m_formulation_type mft where lower(mft.type)=lower(formulationType) and mft.organization_id =orgId and mft.is_active =true and mft.is_deleted =false limit 1)select id into formulationTypeId from getFormulationTypeId;if formulationTypeId is null thenwith formulationTypeSave as (insert into public.m_formulation_type (organization_id,unit_id,code,type,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,((select count(mft.id) from public.m_formulation_type mft where mft.organization_id =orgId)+1),formulationType,true,updatedBy,now(),createdBy,now(),false) returning id)select id into formulationTypeId from formulationTypeSave;end if;end if;--Generic Nameif genericName='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Generic name can not be blank,');
elsewith getGenericId as (select mg.id as id from public.m_generic mg where lower(mg.name)=lower(genericName) and mg.product_category_id=prodCatId and mg.organization_id=orgId and mg.is_active =true and mg.is_deleted =false limit 1)select id into genericId from getGenericId;if genericId is null thenwith genericSave as (insert into public.m_generic (organization_id,unit_id,product_category_id,code,name,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,prodCatId,((select count(mg.id) from public.m_generic mg where mg.organization_id=orgId )+1),genericName,true,updatedBy,now(),createdBy,now(),false) returning id)select id into genericId from genericSave;end if;end if;-------Strength is non mandatory fieldif (obj-&gt;&gt;'strength')!='' then--strength:=cast(obj-&gt;&gt;'strength' as double precision);
strength:=NULLIF(regexp_replace(obj-&gt;&gt;'strength', '\D','','g'), '')::double precision;if strength is null then-- flag=true;-- failedRecordReason=concat(failedRecordReason,'Inccorrect strength,');
end if;end if;--Strength unit name--It is non mandatoryif strengthUnitName!='' thenwith getStrengthUnitId as (select msu.id as id from public.m_strength_unit msu where lower(msu.unit)=lower(strengthUnitName) and msu.is_active =true and msu.is_deleted =false limit 1)select id into strengthUnitId from getStrengthUnitId;end if;--pharmacological classificationif pharmClass='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Pharmacological classification can not be blank,');
elsewith getPharmacologicalClassId as (select mpc.id as id from public.m_pharmacological_classification mpc where lower(mpc.classification)=lower(pharmClass) and mpc.organization_id =orgIdand mpc.is_active=true and mpc.is_deleted =false limit 1)select id into pharmacologyClassId from getPharmacologicalClassId;if pharmacologyClassId is null thenwith pharmacologiClassificationSave as(insert into m_pharmacological_classification (organization_id,unit_id,code,classification,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,((select count(mpc.id) from public.m_pharmacological_classification mpc where mpc.organization_id =orgId)+1),pharmClass,true,updatedBy,now(),createdBy,now(),false) returning id)select id into pharmacologyClassId from pharmacologiClassificationSave;end if;end if;--Maufactureif manufacture='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Manufacture can not be blank,');
elsewith getManufactureId as (select mm.id as id from public.m_manufacturer mm where lower(mm.name)=lower(manufacture) and mm.organization_id=orgIdand mm.is_active =true and mm.is_deleted =false limit 1)select id into manufactureId from getManufactureId;if manufactureId is null thenwith manufacturesave as(insert into public.m_manufacturer (organization_id,unit_id,code,name,address,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values (orgId,unitId,((select count(mm.id) from public.m_manufacturer mm where mm.organization_id=orgId)+1),manufacture,'',true,updatedBy,now(),createdBy,now(),false) returning id)select id into manufactureId from manufacturesave;end if;end if; --Purchase taxif (obj-&gt;&gt;'purchaseTaxPer')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Purchase Tax % can not be blank,');
else--purchaseTaxPer:=cast(obj-&gt;&gt;'purchaseTaxPer' as float8) ;purchaseTaxPer:=NULLIF(regexp_replace(obj-&gt;&gt;'purchaseTaxPer', '\D','','g'), '')::float8;if purchaseTaxPer is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Inccorrect Purchase Tax %,');
elsepurchaseTaxPer=cast(obj-&gt;&gt;'purchaseTaxPer' as float8);
with getPurchaseTaxId as (select mt.id as id from public.m_tax mt where cast(mt.tax_percentage as float8)=purchaseTaxPer and mt.organization_id =orgId and mt.is_active=true and mt.is_deleted =false limit 1)select id into purchasetaxId from getPurchaseTaxId;if purchasetaxId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Purchase Tax not exist,');
-- with purchaseTaxSave as (Insert into public.m_tax (organization_id,unit_id,code,name,tax_percentage,is_active,updated_by,updated_date,added_by,added_date,is_deleted)--values(orgId,unitId,purchaseTax,purchaseTax,purchaseTax,true,updatedBy,now(),createdBy,now(),false) returning id)--select id into purchasetaxId from purchaseTaxSave;end if;end if;end if;--Sale taxif (obj-&gt;&gt;'saleTaxPer')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Sale Tax % can not be blank,');
else --saleTaxPer:=cast(obj-&gt;&gt;'saleTaxPer' as float8) ;saleTaxPer:=NULLIF(regexp_replace(obj-&gt;&gt;'saleTaxPer', '\D','','g'), '')::float8;if saleTaxPer is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Inccorrect Sale Tax %,');
elsesaleTaxPer=cast(obj-&gt;&gt;'saleTaxPer' as float8);
with getSaleTaxId as (select mt.id as id from public.m_tax mt where mt.tax_percentage=saleTaxPer and mt.organization_id =orgId and mt.is_active=true and mt.is_deleted =false limit 1)select id into saleTaxId from getSaleTaxId;if saleTaxId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Sale Tax not exist,');
end if;end if;end if;--Storage unitif storageUnit='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Storage Unit can not be blank,');
elsewith getStorageUnitId as (select msu.id as id from public.m_storage_unit msu where lower(msu.name)=lower(storageUnit) and msu.organization_id =orgId and msu.is_active =true and msu.is_deleted =false limit 1)select id into storageUnitId from getStorageUnitId;if storageUnitId is null thenwith storeUnitSave as (insert into public.m_storage_unit (organization_id,unit_id,code,name,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,((select count(msu.id) from public.m_storage_unit msu where msu.organization_id=orgId)+1),storageUnit,true,updatedBy,now(),createdBy,now(),false) returning id)select id into storageUnitId from storeUnitSave;end if;end if;--Purchase UOM--uom type id 1-for purchase 2-stock 3-dispenseif (obj-&gt;&gt;'purchaseToStockConvQty')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Purchase To Stock Conversion Qty can not be blank,');
else--saleTaxPer:=cast(obj-&gt;&gt;'saleTaxPer' as float8) ;purchaseUOMQty:=NULLIF(regexp_replace(obj-&gt;&gt;'purchaseToStockConvQty', '\D','','g'), '')::integer;if purchaseUOMQty is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Inccorrect Purchase To Stock Conversion Qty,');
end if;end if;if purchaseUOMUnit='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Purchase UOM Unit can not be blank,');
elsewith getPurchaseUOMUnitId as (SELECT uu.id as id FROM public.m_uom_unit uuWHERE lower(uu.unit)=lower(purchaseUOMUnit) and uu.organization_id =orgId and uu.is_active =true and uu.is_deleted =false limit 1)select id into purchaseUomUnitId from getPurchaseUOMUnitId;if purchaseUomUnitId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Purchase UOM Unit not exist,');
--with purchaseUomUnitSave as(insert into public.m_uom_unit (organization_id,unit_id,code,unit,is_active,updated_by,updated_date,added_by,added_date,is_deleted) --values(orgId,unitId,purchaseUOMUnit,purchaseUOMUnit,true,updatedBy,now(),createdBy,now(),false) returning id)--select id into purchaseUomUnitId from purchaseUomUnitSave; end if;end if;--stock uom unitif (obj-&gt;&gt;'stockToDispenseConvQty')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Stock To Dispense Conversion Qty can not be blank,');
else--saleTaxPer:=cast(obj-&gt;&gt;'saleTaxPer' as float8) ;stockUOMQty:=NULLIF(regexp_replace(obj-&gt;&gt;'stockToDispenseConvQty', '\D','','g'), '')::integer;if stockUOMQty is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Inccorrect Stock To Dispense Conversion Qty,');
end if;end if;if stockUOMUnit='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Stock To Dispense Conversion Qty can not be blank,');
elsewith getStockUOMUnitId as (SELECT uu.id as id FROM public.m_uom_unit uuWHERE lower(uu.unit)=lower(stockUOMUnit) and uu.is_active =true and uu.is_deleted =false limit 1)select id into stockUomUnitId from getStockUOMUnitId;if stockUomUnitId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Stock UOM Unit not exist,');
end if;end if;--Dispense uom unitif (obj-&gt;&gt;'dispenseUOMQty')='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Dispense UOM Qty can not be blank,');
else--saleTaxPer:=cast(obj-&gt;&gt;'saleTaxPer' as float8) ;dispenseUOMQty:=NULLIF(regexp_replace(obj-&gt;&gt;'dispenseUOMQty', '\D','','g'), '')::integer;if dispenseUOMQty is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Inccorrect Dispense UOM Qty,');
end if;end if;if dispenseUOMUnit='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Dispense UOM Unit can not be blank,');
elsewith getDispenseUOMUnitId as (SELECT uu.id as id FROM public.m_uom_unit uuWHERE lower(uu.unit)=lower(dispenseUOMUnit) and uu.is_active =true and uu.is_deleted =false limit 1)select id into dispenseUomUnitId from getDispenseUOMUnitId;if dispenseUomUnitId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Dispense UOM Unit not exist,');
end if;end if;--Ip uom typeif ipUOM='' thenflag=true;failedRecordReason=concat(failedRecordReason,'IP UOM Type can not be blank,');
else with getIpUomTypeId as (select mut.id as id from m_uom_type mut where lower(mut.type)=lower(ipUOM) and mut.is_active =true and mut.is_deleted =false limit 1)select id into ipUomTypeId from getIpUomTypeId;if ipUomTypeId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'IP UOM Type not exist,');
end if;end if;--Op uom typeif opUOM='' thenflag=true;failedRecordReason=concat(failedRecordReason,'OP UOM Type can not be blank,');
else with getOpUomTypeId as (select mut.id as id from m_uom_type mut where lower(mut.type)=lower(opUOM) and mut.is_active =true and mut.is_deleted =false limit 1)select id into opUomTypeId from getOpUomTypeId;if opUomTypeId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'OP UOM Type not exist,');
end if;end if;--store uom typeif storeUOM='' thenflag=true;failedRecordReason=concat(failedRecordReason,'Store UOM Type can not be blank,');
else with getStoreUomTypeId as (select mut.id as id from m_uom_type mut where lower(mut.type)=lower(storeUOM) and mut.is_active =true and mut.is_deleted =false limit 1)select id into storeUomTypeId from getStoreUomTypeId;if storeUomTypeId is null thenflag=true;failedRecordReason=concat(failedRecordReason,'Store UOM Type not exist,');
end if;end if;---Insert call for item masterif flag=false then with itemmasterSave as (insert into public.m_item (organization_id,unit_id,storage_unit_id ,generic_id,pharmacological_classification_id,manufacturer_id,code,name,product_code,strength,hsn_code,is_reusable,is_vaccin,is_otc,is_combination,is_batch_required,is_high_risk_product,is_psychotropic,is_kit,is_infusion,is_narcotic,is_active,updated_by,updated_date,added_by,added_date,is_deleted,formulation_type_id,s_tax_id,p_tax_id,strength_unit_id ,is_consignment,is_consumable,is_hospital_formulary,product_category_id,is_cssd,is_modality,is_chargeable_equpiment,is_sterilize,is_implant,is_ot,is_critical,is_accessories,is_spares,is_injection,is_dialyser,reusable_percentage)values(orgId,unitId,storageUnitId,genericId,pharmacologyClassId,manufactureId,itemCode,itemName,productCode,strength,HSNCode,false,isVaccine,false,isCombination,batchReq,false,false,isKit,isInfusion,isNarcotic,true,updatedBy,now(),createdBy,now(),false,formulationTypeId,saleTaxId,purchasetaxId,strengthUnitId ,false,isConsumable,hospitalFormulary,prodCatId,false,false,false,false,false,false,false,false,false,isInjection,false,'[]')returning id)select id into itemId from itemmasterSave;---Insert call for unit of measurementif(purchaseUomUnitId is not null) and (purchaseUOMQty is not null) theninsert into public.m_unit_of_measurement (organization_id,unit_id,item_id,uom_type_id,uom_unit_id,conversions,ip_uom,op_uom,store_uom,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,itemId,1,purchaseUomUnitId,purchaseUOMQty,(case when ipUomTypeId=1 then true else false end),(case when opUomTypeId=1 then true else false end),(case when storeUomTypeId=1 then true else false end),true,updatedBy,now(),createdBy,now(),false);
end if;if(stockUomUnitId is not null) and (stockUOMQty is not null) theninsert into public.m_unit_of_measurement (organization_id,unit_id,item_id,uom_type_id,uom_unit_id,conversions,ip_uom,op_uom,store_uom,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,itemId,2,stockUomUnitId,stockUOMQty, (case when ipUomTypeId=2 then true else false end),(case when opUomTypeId=2 then true else false end), (case when storeUomTypeId=2 then true else false end),true,updatedBy,now(),createdBy,now(),false);
end if;if(dispenseUomUnitId is not null) and (dispenseUOMQty is not null) theninsert into public.m_unit_of_measurement (organization_id,unit_id,item_id,uom_type_id,uom_unit_id,conversions,ip_uom,op_uom,store_uom,is_active,updated_by,updated_date,added_by,added_date,is_deleted)values(orgId,unitId,itemId,3,dispenseUomUnitId,dispenseUOMQty, (case when ipUomTypeId=3 then true else false end),(case when opUomTypeId=3 then true else false end), (case when storeUomTypeId=3 then true else false end),true,updatedBy,now(),createdBy,now(),false);
end if;end if;if flag=true thenif(failedRecordReason!='') thenfailedRecordReason=substring(failedRecordReason,0,length(failedRecordReason));
end if;failedRec:=obj::varchar;failedRec:=concat(substring(failedRec,1,(length(failedRec)-1)),',"remark":','"',failedRecordReason,'"}');
failedRecordJson := array_append(failedRecordJson,failedRec::json);
end if;end loop;failedRecRes :=failedRecordJson::varchar;failedRecRes:=substring(failedRecRes,2,(length(failedRecRes)-2));
failedRecRes:=concat('{"failedRecordJson":[','',failedRecRes,'',']}');
failedRecRes= replace(replace(failedRecRes, '"{', '{'),'}"','}');
failedRecRes= replace(failedRecRes,'\','');
EXCEPTION when OTHERS then failedRecRes='failed to insert records';COMMIT;END;$procedure$;-- DROP FUNCTION public.pharmacyservice_id(int4);
CREATE OR REPLACE FUNCTION public.pharmacyservice_id(bid integer)RETURNS integerLANGUAGE plpgsqlAS $function$declare id integer;begin select distinct coalesce(bill.service_id,0) into id from billing.t_billing_details bill WHERE EXISTS ( select pharmacy_service_id from t_unit_application_billing_configuration where unit_id=38 and pharmacy_service_id= bill.service_id ) and bill.billing_master_id = bid limit 1 ;return id;end;$function$;

-- DROP FUNCTION public.pharmacyservice_idnew(int4, int4);
CREATE OR REPLACE FUNCTION public.pharmacyservice_idnew(bid integer, unitid integer)RETURNS integerLANGUAGE plpgsqlAS $function$declare id integer;begin select distinct coalesce(bill.service_id,0) into id from billing.t_billing_details bill WHERE EXISTS ( select pharmacy_service_id from t_unit_application_billing_configuration where unit_id= unitid and pharmacy_service_id= bill.service_id ) and bill.billing_master_id = bid limit 1 ;return id;end;$function$;

-- DROP FUNCTION public.populate_record(anyelement, hstore);
CREATE OR REPLACE FUNCTION public.populate_record(anyelement, hstore)RETURNS anyelementLANGUAGE cIMMUTABLE PARALLEL SAFEAS '$libdir/hstore', $function$hstore_populate_record$function$;

-- DROP FUNCTION public.post_advance_refund(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_advance_refund(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucherno_ip integer = nextval('public.tally_voucher_no_seq');
begin create or replace temporary view refundvouchers as select prm.amount_refunded as amount_refunded, prm.is_cn_or_deposit as is_cn_or_deposit, refcn.balance_amount as balance_amount,dep.visit_type_id as visit_type_id,dep.deposit_type_id as deposit_type_id,refcn.created_date as created_date,refcn.organization_id as orgnisation_id,refcn.unit_id as unit_idfrom billing.t_refund_cn refcninner join billing.m_deposit_master dep on dep.deposit_master_id=refcn.deposit_idinner join billing.t_payment_refund_master prm on refcn.t_refund_cn_id=prm.t_refund_cn_id ;--where to_char(prm.created_date,'yyyy-mm-dd')::date=dateoftrans;--- create view for payment detailscreate or replace temporary view refundpaydtlsas selectprd.payment_refund_details_id as id,prd.payment_mode_id as modeid,pmod.ledger_name as mode,prd.amount as amount,prd.card_number as cardnumber,prd.cheque_number as chequenumber,prd.date::date as chequedate,prd.orgnisation_id as orgid,prd.unit_id as unitid,prd.created_date::date as date,bank.bank_name as bankname,dep.visit_type_id as visit_type_id,dep.deposit_type_id as deposit_type_id from billing.t_refund_cn refcninner join billing.m_deposit_master dep on dep.deposit_master_id=refcn.deposit_idinner join billing.t_payment_refund_master prm on refcn.t_refund_cn_id=prm.t_refund_cn_idinner join billing.t_payment_refund_details prd on prd.payment_refund_id=prm.payment_refund_idinner join public.m_payment_mode_master pmod onpmod.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank onbank.bank_id = prd.bank_idwhereprm.is_cn_or_deposit = 0;--and to_char(prm.created_date,'yyyy-mm-dd')::date=dateoftrans;--xxx-- insert cash mode advance refund amountinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', 'Patient Advance', prm.created_date::date, sum(prm.amount_refunded), 0 , prm.unit_id, prm.orgnisation_id, 'OP'from refundvouchers prm where prm.is_cn_or_deposit = 0 and prm.created_date::date = dateoftrans and ( prm.deposit_type_id = 1 or prm.visit_type_id = 1)group by prm.orgnisation_id, prm.unit_id,prm.created_date::date,prm.amount_refunded;--- xxx--- insert cash mode transactionsinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'OP'from refundpaydtls rpdwhere rpd.date = dateoftrans and ( rpd.deposit_type_id = 1 or rpd.visit_type_id = 1)group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;---xxx-- 2. IP datainsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno_ip, 'Payment', 'Patient Advance', prm.created_date::date, sum(prm.amount_refunded), 0 , prm.unit_id, prm.orgnisation_id, 'IP'from refundvouchers prm where prm.is_cn_or_deposit = 0 and prm.created_date::date = dateoftrans and prm.deposit_type_id =2 and prm.visit_type_id = 2group by prm.orgnisation_id, prm.unit_id,prm.created_date::date,prm.amount_refunded;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno_ip, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'IP'from refundpaydtls rpdwhere rpd.date = dateoftrans and rpd.deposit_type_id =2 and rpd.visit_type_id = 2group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;-- IP data endreturn true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.post_company_settlement(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_company_settlement(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin --------&lt;-----1. OP------- create or replace temporary view ipbillcomp as select pMode.payment_mode_id as modeid, pMode.ledger_name as mode, pReceiptDtls.amount as rcptamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,crm.organisation_id as orgid, crm.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate, crm.company_receipt_date :: date as recieptdate,pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, crm.other_deduction as otherdeduction, comany.company_id as companyid ,comany.company_desc as companyDesc,crm.receipt_amount as comNetAmountfrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_idinner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_idinner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_invoice_detail_idinner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_idinner join t_company_master comany on comany.company_id=crm.payee_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere bill.visit_type_id = 1 and pReceiptMst.payee_id != (select self_payee_id from t_unit_application_billing_configuration where unit_id = pReceiptMst.unit_id and status='A');
------- Insert companies total collection start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Receipt',ipbillself.companyDesc,ipbillself.transdate, 0, cast(sum(ipbillself.comNetAmount) as numeric(10,2)) , ipbillself.unitId, ipbillself.orgId,'OP'from ipbillcomp ipbillself where ipbillself.transdate::date = dateoftransgroup by ipbillself.companyid, ipbillself.companyDesc,ipbillself.transdate, ipbillself.orgid,ipbillself.unitid;------- Insert companies total collection end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, cast(ipbillself.rcptamount as numeric(10,2)), 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'OP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)from ipbillcomp ipbillselfwhere ipbillself.transdate= dateoftrans and ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate = dateoftrans;------------------- tds ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'TDS', ipbc.recieptdate, cast(sum(ipbc.tds) as numeric(10,2)) , 0, ipbc.unitid , ipbc.orgid, 'OP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- disallowed amount ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Disallowed amount', ipbc.recieptdate, cast(sum(ipbc.disallowedamount) as numeric(10,2) ), 0, ipbc.unitid , ipbc.orgid, 'OP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- other deductions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Other deductions', ipbc.recieptdate, cast(sum(ipbc.otherdeduction) as numeric(10,2) ), 0, ipbc.unitid , ipbc.orgid, 'OP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;---------------------------------------------------------- insert company wise details ---------------------------with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date::date as dateoftrans, sum(crd.net_receipt_amount) as amount,crd.organisation_id as orgId, crd.unit_id as unitIdfrom billing.t_company_receipt_detail crdinner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_idleft join billing.m_billing_master bm on bm.billing_master_id = cid.bill_idinner join public.t_company_master cm on cm.company_id = cid.bill_payee_idwhere crd.created_date::date = dateoftrans and bm.visit_type_id =1group by crd.created_date::date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cast(cr.amount as numeric(10,2)), cr.unitId, cr.orgId, 'OP' from company_receipt cr;-----------------------------------------------1. OP ----&gt;---------&lt;----2. IP ---------create or replace temporary view ipbillcomp as select pMode.payment_mode_id as modeid, pMode.ledger_name as mode, pReceiptDtls.amount as rcptamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,crm.organisation_id as orgid, crm.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate, crm.company_receipt_date :: date as recieptdate,pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, crm.other_deduction as otherdeduction, comany.company_id as companyid ,comany.company_desc as companyDesc,crm.receipt_amount as comNetAmountfrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_idinner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_idinner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_invoice_detail_idinner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_idinner join t_company_master comany on comany.company_id=crm.payee_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere bill.visit_type_id = 2 and pReceiptMst.payee_id != (select self_payee_id from t_unit_application_billing_configuration where unit_id = pReceiptMst.unit_id and status='A');
------- Insert companies total collection start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Receipt',ipbillself.companyDesc,ipbillself.transdate, 0, cast(sum(ipbillself.comNetAmount) as numeric(10,2)) , ipbillself.unitId, ipbillself.orgId,'IP'from ipbillcomp ipbillself where ipbillself.transdate::date = dateoftransgroup by ipbillself.companyid, ipbillself.companyDesc,ipbillself.transdate, ipbillself.orgid,ipbillself.unitid;------- Insert companies total collection end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, cast(ipbillself.rcptamount as numeric(10,2)), 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)from ipbillcomp ipbillselfwhere ipbillself.transdate= dateoftrans and ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate = dateoftrans;------------------- tds ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'TDS', ipbc.recieptdate, cast(sum(ipbc.tds) as numeric(10,2)) , 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- disallowed amount ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Disallowed amount', ipbc.recieptdate, cast(sum(ipbc.disallowedamount) as numeric(10,2) ), 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- other deductions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Other deductions', ipbc.recieptdate, cast(sum(ipbc.otherdeduction) as numeric(10,2) ), 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;---------------------------------------------------------- insert company wise details ---------------------------with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date::date as dateoftrans, sum(crd.net_receipt_amount) as amount,crd.organisation_id as orgId, crd.unit_id as unitIdfrom billing.t_company_receipt_detail crdinner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_idleft join billing.m_billing_master bm on bm.billing_master_id = cid.bill_idinner join public.t_company_master cm on cm.company_id = cid.bill_payee_idwhere crd.created_date::date = dateoftrans and bm.visit_type_id = 2 group by crd.created_date::date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cast(cr.amount as numeric(10,2)), cr.unitId, cr.orgId, 'IP' from company_receipt cr;-----------------------------------------------2. IP ----&gt;-----return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.post_credit_notes(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_credit_notes(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucher_ip integer = nextval('public.tally_voucher_no_seq');
begin-----&lt;---- 1.OP -------------create or replace temporary viewcreditnotes as selectgenl.general_ledger_id ledgerid,genl.general_ledger_name as ledger,crdt.cr_net_amount as amount,crd.credit_note_date::date as refunddate,crd.organisation_id as orgid,crd.unit_id as unitidfrombilling.m_credit_note_master crdinner join billing.t_credit_note_detail crdt oncrdt.credit_note_id = crd.credit_note_idinner join billing.m_billing_master bill on bill.billing_master_id=crd.bill_idinner join t_order_details od on od.order_details_id=crdt.order_dtl_id_oldinner join service.m_service_master srv onsrv.service_master_id = od.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl ongenl.general_ledger_id = spc.general_ledger_idwhere bill.visit_type_id = 1;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP'from creditnotes crd where crd.refunddate::date = dateoftrans group by crd.orgid, crd.unitid,crd.refunddate, crd.ledger;-------------- Insert credit notes into tally interface end-------------------------------------------Insert patient credit--------------create or replace temporary viewcreditnotedueamt as selectsum(crd.cr_deu_amount) as amount,crd.credit_note_date::date as credit_note_date,crd.organisation_id as orgid,crd.unit_id as unitidfrombilling.m_credit_note_master crdinner join billing.m_billing_master billmst onbillmst.billing_master_id = crd.bill_idwhere billmst.visit_type_id = 1group bycrd.organisation_id,crd.unit_id,crd.cr_deu_amount,crd.credit_note_date;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', 'Patient Credit', crd.credit_note_date, 0, sum(amount), crd.unitid, crd.orgid, 'OP'from creditnotedueamt crd where crd.credit_note_date::date = dateoftransgroup by crd.orgid, crd.unitid,crd.credit_note_date,crd.amounthaving crd.amount &gt; 0;--------------Insert patient credit----------------------------Discount round off start----------------with roundoff as (selectsum(bm.discount_roundoff) as round_off_amount,bm.unit_id as unitId,bm.organisation_id as orgId,bm.created_date::date as transactionDatefrombilling.m_credit_note_master bminner join billing.m_billing_master bill on bill.billing_master_id=bm.bill_idwherebm.created_date::date = dateoftransand bill.visit_type_id = 1group bybm.organisation_id,bm.unit_id,bm.created_date::datehavingsum(bm.discount_roundoff) is not null) insertintopublic.t_tally_interface (voucher_no,voucher_type,ledger,voucher_date,debit_amount,credit_amount,unit_id,hospital_id,tran_type) selectvoucherno,'Credit Note','Discount round-off',roundoff.transactionDate,case when roundoff.round_off_amount&lt;0 then 0else cast(roundoff.round_off_amount as numeric(10, 2)) end,case when roundoff.round_off_amount&gt;0 then 0else cast(-roundoff.round_off_amount as numeric(10, 2)) end ,roundoff.unitId,roundoff.orgId,'OP'fromroundoffwhere roundoff.round_off_amount &gt;0 or roundoff.round_off_amount &lt;0 ;--------------Discount round off start-------------------------------------- refund details view --------------------------------------create or replace temporary viewcreditnoterefunds as select prd.payment_mode_id as modeid, pm.ledger_name as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,cnm.credit_note_date as ceditnotedate,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id = 1 and prm.is_cn_or_deposit = 1;-----------------------------xxx--------------------------------------------------------- insert cash mode transactions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'from creditnoterefunds rfdwhere rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid = 1group by rfd.orgid, rfd.unitid,rfd.refunfdate, rfd.mode;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions ----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid != 1group by rfd.orgid,rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;-------------------------xxx-------------------------------------------------------Previous date settlement start cash-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid = 1 and rfd.refunfdate::date=dateoftransgroup by rfd.orgid,rfd.unitid,rfd.refunfdate, rfd.mode;--------------------------------------------------Previous date settlement start others-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid != 1 and rfd.refunfdate::date=dateoftransgroup by rfd.orgid, rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;--------------------------------------------------------------Credit insert start--------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', 'Patient Credit', rfd.refunfdate,sum(rfd.amount),0, rfd.unitid, rfd.orgid, 'OP'from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.refunfdate::date=dateoftransgroup by rfd.orgid, rfd.unitid,rfd.refunfdatehaving sum(rfd.amount) &gt; 0;------------------------------Credit insert stop----------------------------------- 1.OP ----&gt;---------------&lt;--- 2.IP -------------create or replace temporary viewcreditnotes as selectgenl.general_ledger_id ledgerid,genl.general_ledger_name as ledger,crdt.cr_net_amount as amount,crd.credit_note_date::date as refunddate,crd.organisation_id as orgid,crd.unit_id as unitidfrombilling.m_credit_note_master crdinner join billing.t_credit_note_detail crdt oncrdt.credit_note_id = crd.credit_note_idinner join billing.m_billing_master bill on bill.billing_master_id=crd.bill_idinner join t_order_details od on od.order_details_id=crdt.order_dtl_id_oldinner join service.m_service_master srv onsrv.service_master_id = od.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl ongenl.general_ledger_id = spc.general_ledger_idwhere bill.visit_type_id = 2;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucher_ip, 'Credit Note', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'IP'from creditnotes crd where crd.refunddate::date = dateoftrans group by crd.orgid, crd.unitid,crd.refunddate,crd.ledger;-------------- Insert credit notes into tally interface end-------------------------------------------Insert patient credit--------------create or replace temporary viewcreditnotedueamt as selectsum(crd.cr_deu_amount) as amount,crd.credit_note_date::date as credit_note_date,crd.organisation_id as orgid,crd.unit_id as unitidfrombilling.m_credit_note_master crdinner join billing.m_billing_master billmst onbillmst.billing_master_id = crd.bill_idwhere billmst.visit_type_id = 2group bycrd.organisation_id,crd.unit_id,crd.cr_deu_amount,crd.credit_note_date;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucher_ip, 'Credit Note', 'Patient Credit', crd.credit_note_date, 0, sum(amount), crd.unitid, crd.orgid, 'IP'from creditnotedueamt crd where crd.credit_note_date::date = dateoftransgroup by crd.orgid, crd.unitid,crd.credit_note_date,crd.amounthaving crd.amount &gt; 0;--------------Insert patient credit----------------------------Discount round off start----------------with roundoff as (selectsum(bm.discount_roundoff) as round_off_amount,bm.unit_id as unitId,bm.organisation_id as orgId,bm.created_date::date as transactionDatefrombilling.m_credit_note_master bminner join billing.m_billing_master bill on bill.billing_master_id=bm.bill_idwherebm.created_date::date = dateoftransand bill.visit_type_id = 2group bybm.organisation_id,bm.unit_id,bm.created_date::datehavingsum(bm.discount_roundoff) is not null) insertintopublic.t_tally_interface (voucher_no,voucher_type,ledger,voucher_date,debit_amount,credit_amount,unit_id,hospital_id,tran_type) selectvoucher_ip,'Credit Note','Discount round-off',roundoff.transactionDate,case when roundoff.round_off_amount&lt;0 then 0else cast(roundoff.round_off_amount as numeric(10, 2)) end,case when roundoff.round_off_amount&gt;0 then 0else cast(-roundoff.round_off_amount as numeric(10, 2)) end ,roundoff.unitId,roundoff.orgId,'IP'fromroundoffwhere roundoff.round_off_amount &gt;0 or roundoff.round_off_amount &lt;0 ;--------------Discount round off start-------------------------------------- refund details view --------------------------------------create or replace temporary viewcreditnoterefunds as select prd.payment_mode_id as modeid, pm.ledger_name as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,cnm.credit_note_date as ceditnotedate,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id = 2 and prm.is_cn_or_deposit = 1;-----------------------------xxx--------------------------------------------------------- insert cash mode transactions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'from creditnoterefunds rfdwhere rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid = 1group by rfd.orgid,rfd.unitid,rfd.refunfdate,rfd.mode;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions ----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate::date = rfd.ceditnotedate::date and rfd.refunfdate::date = dateoftrans and rfd.modeid != 1group by rfd.orgid, rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;-------------------------xxx-------------------------------------------------------Previous date settlement start cash-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid = 1 and rfd.refunfdate::date=dateoftransgroup by rfd.orgid,rfd.unitid,rfd.refunfdate,rfd.mode;--------------------------------------------------Previous date settlement start others-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucher_ip, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.modeid != 1 and rfd.refunfdate::date=dateoftransgroup by rfd.orgid, rfd.unitid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;--------------------------------------------------------------Credit insert start--------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucher_ip, 'Credit Note', 'Patient Credit', rfd.refunfdate,sum(rfd.amount),0, rfd.unitid, rfd.orgid, 'IP'from creditnoterefunds rfdwhere rfd.refunfdate::date != rfd.ceditnotedate::date and rfd.refunfdate::date=dateoftransgroup by rfd.orgid, rfd.unitid,rfd.refunfdatehaving sum(rfd.amount) &gt; 0;------------------------------Credit insert stop----------------------------------- 2.IP ----&gt;---------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.post_deposit_data(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_deposit_data(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
patient_names text;begin----------- Create view --------------------------create or replace temporary viewdepositas select depdt.payment_mode_id as modeid, pmode.ledger_name as mode, depdt.amount as recamount,dep.deposit_date::date as date ,dep.deposit_master_id as depositid, dep.org_id as orgid, dep.unit_id as unitid,depdt.card_no as cardnumber, depdt.card_type_id as cardtypeid, depdt.cheque_number as chequenumber, depdt.cheque_date as chequedate, bank.bank_name as bankname, depdt.deposit_details_id as depositdetailsid,dep.patient_id AS patientid, (patient.uhid_number||'-'||patient.first_name || ' ' || patient.last_name||'-'||dep.deposit_no||'-'||pmode.payment_mode_desc) AS patientnamefrom billing.m_deposit_master depinner join billing.t_payment_deposit_details depdton depdt.deposit_id = dep.deposit_master_idinner join public.m_payment_mode_master pmodeon pmode.payment_mode_id = depdt.payment_mode_idleft join billing.m_bank_master bankon bank.bank_id = depdt.bank_idLEFT JOIN patient.t_patient_registration patientON patient.patient_id = dep.patient_id;------------------xxx-------------------------------------------- Insert cash deposits ------------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', dep.mode, dep.date, sum(dep.recamount), 0, dep.unitid, dep.orgid , 'OP'from deposit depwhere dep.modeid = 1 and dep.date = dateoftransgroup by dep.modeid, dep.mode, dep.orgid, dep.unitid, dep.date;-------------------xxx----------------------------------------- Insert other payment mode deposits------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', dep.mode, dep.date, dep.recamount, 0, dep.unitid, dep.orgid, dep.depositdetailsid,coalesce(dep.chequedate,dep.date), 'OP', dep.bankname, coalesce(dep.chequenumber,dep.cardnumber) from deposit depwhere dep.modeid != 1 and dep.date = dateoftrans;------------------------xxx--------------------------------------------------------- Insert Patient advance credit ----------------------SELECT string_agg(DISTINCT patientname, ' | ') INTO patient_namesFROM (SELECT DISTINCT patientid, patientnameFROM depositWHERE date = dateoftrans) subquery;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration)select voucherno, 'Receipt', 'Patient Advance', dep.date , 0, sum(dep.recamount), dep.unitid, dep.orgid, 'OP', patient_namesfrom deposit dep where dep.date = dateoftransgroup by dep.date, dep.unitid, dep.orgid;------------------------xxx--------------------------------------------- Inset Company Advance Debit --------------------------insertintopublic.t_tally_interface (voucher_no,voucher_type,ledger,voucher_date,vou_narration,unique_number,instrument_date,bank_name,company_name,unit_id,hospital_id,debit_amount,credit_amount,patient_specific,tran_type)selectvoucher_no,voucher_type,ledger,voucher_date,vou_narration,unique_number,instrument_date,bank_name,company_name,unit_id,hospital_id,debit_amount,credit_amount,'Y' as patient_specific,'OP' as tran_typefrom(selecttcre.company_receipts_expense_id unique_number,concat('CADV-', tcre.company_receipts_expense_id) as voucher_no ,'Receipt' as voucher_type,tcrer.date_of_reciept::date as voucher_date ,concat(tcre.name , ' ' , coalesce (tcre.remark, ''), ' ', coalesce(tcre.bill_number, ''), ' ', tcre.bill_date_time::date ) vou_narration,tcre.org_id hospital_id,tcre.unit_id ,tcrerd.trans_transaction_date::date as instrument_date,tcm.company_desc company_name,sum(tcrerd.amount) debit_amount,0 as credit_amount ,mpmm.payment_mode_id ,mpmm.ledger_name as ledger ,coalesce(mbm.bank_name , '') bank_namefrombilling.t_company_receipts_expense_reciept_details tcrerdinner join m_payment_mode_master mpmmonmpmm.payment_mode_id = tcrerd.payment_mode_idinner join billing.t_company_receipts_expense_reciept tcrerontcrer.company_receipts_expense_reciept_id = tcrerd.company_receipts_expense_reciept_idinner join billing.t_company_receipts_expense tcreontcre.company_receipts_expense_id = tcrer.company_receipts_expense_idinner join t_company_master tcm ontcm.company_id = tcre.company_idleft join billing.m_bank_master mbm onmbm.bank_id = tcrerd.bank_idwheretcrer.date_of_reciept::date = dateoftransgroup bytcrer.date_of_reciept::date ,tcrerd.trans_transaction_date::date ,tcre.company_receipts_expense_id,tcm.company_desc ,mpmm.payment_mode_id ,mpmm.ledger_name ,mbm.bank_nameorder bytcre.company_receipts_expense_id) Debit;----------- Create Company Advance Credit view --------------------------insertintopublic.t_tally_interface(voucher_no,voucher_type,ledger,voucher_date,vou_narration,unique_number,bank_name,company_name,unit_id,hospital_id,debit_amount,credit_amount,patient_specific,tran_type)selectvoucher_no,voucher_type,ledger,voucher_date,vou_narration,unique_number,bank_name,company_name,unit_id,hospital_id,debit_amount,credit_amount,'Y' as patient_specific,'OP' as tran_typefrom(selecttcre.company_receipts_expense_id unique_number,concat('CADV-', tcre.company_receipts_expense_id) as voucher_no ,'Receipt' as voucher_type,tcrer.date_of_reciept::date as voucher_date ,concat(tcre.name , ' ' , coalesce (tcre.remark, ''), ' ', coalesce(tcre.bill_number, ''), ' ', tcre.bill_date_time::date ) vou_narration,tcre.org_id hospital_id,tcre.unit_id ,tcm.company_desc company_name,sum(tcrerd.amount) credit_amount,0 as debit_amount ,tcm.company_desc as ledger ,'' bank_namefrombilling.t_company_receipts_expense_reciept_details tcrerdinner join m_payment_mode_master mpmmonmpmm.payment_mode_id = tcrerd.payment_mode_idinner join billing.t_company_receipts_expense_reciept tcrerontcrer.company_receipts_expense_reciept_id = tcrerd.company_receipts_expense_reciept_idinner join billing.t_company_receipts_expense tcreontcre.company_receipts_expense_id = tcrer.company_receipts_expense_idinner join t_company_master tcm ontcm.company_id = tcre.company_idleft join billing.m_bank_master mbm onmbm.bank_id = tcrerd.bank_idwheretcrer.date_of_reciept::date = dateoftransgroup bytcrer.date_of_reciept::date ,tcre.company_receipts_expense_id ,tcm.company_descorder bytcre.company_receipts_expense_id) Credit ;------------------------xxx----------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.post_doc_share_data(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_doc_share_data(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare voucherno_ip integer = nextval('public.tally_voucher_no_seq');
begin -------&lt;---- 1. OP --------------------------------------- Group wise doctor share posting start -------------------------with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join service.m_service_master sm on sm.service_master_id = ds.service_idinner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_idwhere log.created_date:: date = dateoftrans and ds.visit_type_id=1group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Journal', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid,'Doctor Share' from gen;------------ Group wise doctor share posting end -------------------------------- Doctor share start ---------------with docshare as (select concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans and ds.visit_type_id=1 group by ledger, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Journal', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'Doctor Share' from docshare;------- Doctor share end ---------------------- Retainship amount start ---------------with docretainship as (select sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans and ds.visit_type_id=1group by log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Journal', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'Doctor Share' from docretainship;------- Retainship amount end ---------------------- OP -----&gt;------------&lt;---- 2. IP --------------------------------------- Group wise doctor share posting start -------------------------with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join service.m_service_master sm on sm.service_master_id = ds.service_idinner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_idwhere log.created_date:: date = dateoftrans and ds.visit_type_id=2group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno_ip, 'Journal', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid,'Doctor Share' from gen;------------ Group wise doctor share posting end -------------------------------- Doctor share start ---------------with docshare as (select concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans and ds.visit_type_id=2 group by ledger, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno_ip, 'Journal', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'Doctor Share' from docshare;------- Doctor share end ---------------------- Retainship amount start ---------------with docretainship as (select sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans and ds.visit_type_id=2group by log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno_ip, 'Journal', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'Doctor Share' from docretainship;------- Retainship amount end ---------------------- IP -----&gt;-------------------------------------Round Off-------------------------create or replacetemporary view TallyRound as (selectvoucher_date::date,voucher_no,sum(debit_amount) debt,sum(credit_amount) crd,sum(debit_amount) - sum(credit_amount) difffromt_tally_interfacegroup byvoucher_no ,voucher_date::datehavingsum(debit_amount) &lt;&gt; sum(credit_amount)and sum(debit_amount) - sum(credit_amount) &gt; -1and sum(debit_amount) - sum(credit_amount) &lt; 1order by1 desc ) ;updatet_tally_interface as t setcredit_amount = round(t.credit_amount),debit_amount = round(t.debit_amount)fromTallyRound as rwherer.voucher_no = t.voucher_no ;----------------------------------------------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.post_everyday();
CREATE OR REPLACE FUNCTION public.post_everyday()RETURNS booleanLANGUAGE plpgsqlAS $function$ begin -----------------------when effective date match with todays date then previous all entries status should be inactive-------------------------HIS-25714update service.m_unit_service_tariff_master set status = 'I' where status = 'A' ;update service.m_unit_service_tariff_master as dset status = 'A'from(select unit_service_tariff_idfrom service.m_unit_service_tariff_master ajoin(select max(effective_date) effective_date ,organization_id , unit_id , service_id , tariff_id , payment_entitlement_id , visit_type_id , patient_type_id , billing_bed_category_idfrom service.m_unit_service_tariff_masterwhereeffective_date &lt;= now()group byorganization_id , unit_id , service_id , tariff_id , payment_entitlement_id , visit_type_id , patient_type_id , billing_bed_category_id) bona.effective_date = b.effective_date and a.organization_id = b.organization_id and a.unit_id = b.unit_id and a.service_id = b.service_id and a.tariff_id = b.tariff_id and a.payment_entitlement_id = b.payment_entitlement_id anda.visit_type_id = b.visit_type_id and a.patient_type_id = b.patient_type_id anda.billing_bed_category_id = b.billing_bed_category_id) c where d.unit_service_tariff_id = c.unit_service_tariff_id ;-------------------------------------------------------------------------------------------------------------------------------return true;exceptionwhen others then return false;end;$function$;

-- DROP FUNCTION public.post_grn_notes(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_grn_notes(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$ begin create or replacetemporary view grn as (selectgrn.id,'Purchase' as voucherType,pc.category::character varying(255) as Ledger,grn.added_date as transactionDate,sum(grnd.total_amount) as debitNote,0::double precision as creditNote,grn.remark,grn.unit_id,grn.organization_id,grn.invoice_number,'Inventory' as tran_typefromprocurement.t_good_receipt_note_detail grndinner join procurement.t_good_receipt_note grn ongrn.id = grnd.grn_idinner join public.m_item item onitem.id = grnd.item_idleft join public.m_generic generic ongeneric.id = item.generic_idleft join public.m_product_category pc on(casewhen item.product_category_id is not null then pc.id = item.product_category_idelse pc.id = generic.product_category_idend)group bygrn.organization_id,grn.unit_id,grn.added_date,pc.category,grn.id,grn.remark,grn.invoice_numberorder bygrn.id)union all (selectgrn.id,'Purchase' as voucherType,'Discount' as Ledger,grn.added_date as transactionDate,0::double precision as debitNote,sum(grnd.total_discount) as creditNote,grn.remark,grn.unit_id,grn.organization_id,grn.invoice_number,'Inventory' as tran_typefromprocurement.t_good_receipt_note_detail grndinner join procurement.t_good_receipt_note grn ongrn.id = grnd.grn_idinner join public.m_item item onitem.id = grnd.item_idleft join public.m_generic generic ongeneric.id = item.generic_idleft join public.m_product_category pc on(casewhen item.product_category_id is not null then pc.id = item.product_category_idelse pc.id = generic.product_category_idend)group bygrn.organization_id,grn.unit_id,grn.added_date,pc.category,grn.id,grn.remark,grn.invoice_numberorder bygrn.id)union all (select temp.grn_id, temp.voucherType, temp.Ledger,temp.transactionDate, --temp.tax_component_id ,sum(temp.debitNote) debitNote, temp.creditNote, temp.remark, temp.unit_id, temp.organization_id, temp.invoice_number, temp.tran_typefrom(select distinct tax_component_details_id ,grn.id grn_id, 'Purchase' as voucherType, concat(ttcd.tax_component_name,'-', ttcd.tax_component_percentage,'%') as Ledger,grn.added_date as transactionDate, tax_component_id ,ttcd.tax_component_amount as debitNote, 0::double precision as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Inventory' as tran_typefrompharmacy.t_tax_component_details ttcd inner join procurement.t_good_receipt_note grn on grn.id = ttcd.grn_idinner join procurement.t_good_receipt_note_detail tgrnd on tgrnd.grn_id = grn.idinner join public.m_store_item_mapper msim on msim.item_id = tgrnd.item_id wherettcd.tax_component_amount &gt; 0 order bygrn.id ) temp inner join pharmacy.t_tax_component_details ttcd on ttcd.tax_component_details_id = temp.tax_component_details_idgroup by temp.grn_id, temp.voucherType, temp.Ledger,temp.transactionDate, temp.tax_component_id ,temp.creditNote, temp.remark, temp.unit_id, temp.organization_id, temp.invoice_number, temp.tran_typeorder by temp.grn_id)union all (selectdistinct(grn.id), 'Purchase' as voucherType, vendor."name"::character varying(255) as Ledger, grn.added_date as transactionDate, 0::double precision as debitNote, grn.net_amount as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Inventory' as tran_typefromprocurement.t_good_receipt_note_detail grndinner join procurement.t_good_receipt_note grn ongrn.id = grnd.grn_idinner join public.m_vendor vendor onvendor.id = grn.vendor_idorder bygrn.id)union all (selectdistinct (grn.id), 'Purchase' as voucherType, 'Round off'::character varying(255) as Ledger, grn.added_date as transactionDate, grn.round_off as debitNote, 0::double precision as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Inventory' as tran_typefromprocurement.t_good_receipt_note_detail grndinner join procurement.t_good_receipt_note grn ongrn.id = grnd.grn_idwheregrn.round_off &gt; 0 order bygrn.id)union all (selectdistinct (grn.id), 'Purchase' as voucherType, 'Round off'::character varying(255) as Ledger, grn.added_date as transactionDate, 0::double precision as debitNote, (grn.round_off * -1) as creditNote, grn.remark, grn.unit_id, grn.organization_id, grn.invoice_number, 'Inventory' as tran_typefromprocurement.t_good_receipt_note_detail grndinner join procurement.t_good_receipt_note grn ongrn.id = grnd.grn_idwheregrn.round_off &lt; 0 order bygrn.id)order byid;-----Create Voucher Number ----create or replacetemporary view grn_voucher asselectdistinct(id) as grnId,concat('V000', id) as voucherNofromgrnorder bygrnId;------insert grn into tally interface start--------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, ref_no_type, ref_number, tran_type)selectgrnv.voucherno,grn.vouchertype,grn.Ledger,grn.transactionDate,grn.debitNote as debitnote,grn.creditNote as creditNote,grn.unit_id,grn.organization_id,'New Ref',grn.invoice_number,tran_typefromgrn grninner join grn_voucher grnv ongrn.id = grnv.grnIdwheregrn.transactionDate::date = dateoftransorder bygrnv.voucherno,grn.debitnote;------------GRN Return --------create or replacetemporary view grnreturn as (selectreturndetail.returnable_gatepass_id as id,'Purchase' as voucherType,pc.category as ledger,grnreturn.added_date as transacionDate,0::double precision as debitNote,sum(returndetail.net_amount) as creditAmount,grnreturn.unit_id,grnreturn.organization_idfrominventory.t_returnable_gatepass_detail returndetailinner join inventory.t_returnable_gatepass grnreturn ongrnreturn.id = returndetail.returnable_gatepass_idinner join inventory.t_batch batch onbatch.id = returndetail.batch_idinner join public.m_item item onitem.id = batch.item_idleft join public.m_generic generic ongeneric.id = item.generic_idleft join public.m_product_category pc on(casewhen item.product_category_id is not null then pc.id = item.product_category_idelse pc.id = generic.product_category_idend)group bygrnreturn.organization_id,grnreturn.unit_id,grnreturn.added_date,returndetail.returnable_gatepass_id,pc.categoryorder byreturndetail.returnable_gatepass_id)union all (selectreturndetail.returnable_gatepass_id as id,'Purchase' as voucherType,'Discount' as Ledger,grnreturn.added_date as transacionDate,0::double precision as debitNote,sum(returndetail.total_discount) as creditNote,grnreturn.unit_id,grnreturn.organization_idfrominventory.t_returnable_gatepass_detail returndetailinner join inventory.t_returnable_gatepass grnreturn ongrnreturn.id = returndetail.returnable_gatepass_idinner join inventory.t_batch batch onbatch.id = returndetail.batch_idinner join public.m_item item onitem.id = batch.item_idleft join public.m_generic generic ongeneric.id = item.generic_idleft join public.m_product_category pc on(casewhen item.product_category_id is not null then pc.id = item.product_category_idelse pc.id = generic.product_category_idend)group bygrnreturn.organization_id,grnreturn.unit_id,grnreturn.added_date,returndetail.returnable_gatepass_id,pc.categoryhaving sum(returndetail.total_discount) &gt; 0 order byreturndetail.returnable_gatepass_id)union all (selectdistinct (grnreturn.id), 'Purchase' as voucherType, concat(ttcd.tax_component_name,'-', ttcd.tax_component_percentage,'%') as Ledger,grnreturn.added_date as transactionDate, ttcd.tax_component_amount as debitNote, 0::double precision as creditNote, grnreturn.unit_id, grnreturn.organization_idfrompharmacy.t_tax_component_details ttcd inner join inventory.t_returnable_gatepass grnreturn on grnreturn.id = ttcd.grn_retrun_id wheregrnreturn.total_tax_amount &gt; 0 order bygrnreturn.id)union all (selectdistinct(returndetail.returnable_gatepass_id) as id, 'Purchase' as voucherType, vendor.name as ledger, grnreturn.added_date as transacionDate,--sum(grnreturn.total_amt) as debitNote, (grnreturn.net_amount) as debitNote, 0::double precision as creditNote, grnreturn.unit_id, grnreturn.organization_idfrominventory.t_returnable_gatepass_detail returndetailinner join inventory.t_returnable_gatepass grnreturn ongrnreturn.id = returndetail.returnable_gatepass_idinner join public.m_vendor vendor onvendor.id = grnreturn.vendor_id--group by returndetail.returnable_gatepass_id, vendor.name , grnreturn.added_date, grnreturn.unit_id, grnreturn.organization_idorder by returndetail.returnable_gatepass_id )order byid;-----Create Voucher Number ----create or replacetemporary view grnreturn_voucher asselectdistinct(id) as grnreturnId,concat('V000', id) as voucherNofromgrnreturnorder bygrnreturnId;------insert grn into tally interface start--------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, ref_no_type, tran_type)selectgrnv.voucherno,grn.vouchertype,grn.Ledger,grn.transacionDate,grn.debitNote as debitnote,grn.creditAmount as creditNote,grn.unit_id,grn.organization_id,'Inventory','Inventory'fromgrnreturn grninner join grnreturn_voucher grnv ongrn.id = grnv.grnreturnIdwheregrn.transacionDate::date = dateoftransorder bygrnv.voucherno,grn.creditAmount;return true;exceptionwhen others then return false;end;$function$;

-- DROP FUNCTION public.post_sale_cogs(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_sale_cogs(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$ begin --create or replace--temporary view --COGS as --(--select-- ts.id ,-- ts.bill_no ,-- ts.organization_id ,-- ts.unit_id ,-- ts.store_id ,-- ms.store_name ,-- mst.type as Saletype ,-- ts.added_date :: date as transdate,-- ts.remark ,-- sum (cast((tsd.quantity * tb.actual_lending_price) as decimal(10, 2))) as COGS--from-- pharmacy.t_sale_detail tsd--inner join pharmacy.t_sale ts on-- ts.id = tsd.sale_id--inner join inventory.t_batch tb on-- tsd.batch_id = tb.id-- and tsd.item_id = tb.item_id--inner join public.m_store ms on-- ms.store_id = ts.store_id--inner join pharmacy.m_sale_type mst on-- ts.sale_type_id = mst.id--group by-- ts.id ,-- ts.bill_no ,-- ts.organization_id ,-- ts.unit_id ,-- ts.store_id ,-- ms.store_name ,-- mst.type-- --) ;--------------------Inset Sale Debit------------------------insert-- into-- public.t_tally_interface--(voucher_no,-- voucher_type,-- ledger,-- voucher_date,-- vou_narration,-- tran_type,-- unit_id,-- hospital_id,-- debit_amount,-- credit_amount,-- patient_specific,-- his_trans_type)----select-- bill_no,-- 'Sales',-- 'COGS',-- transdate,-- remark,-- 'Inventory',-- COGS.unit_id,-- COGS.organization_id,-- COGS,-- 0,-- 'Y',-- 'COGS'--from-- COGS--where --transdate = dateoftrans --and bill_no notnull and bill_no &lt;&gt; '' ;------------------------Inset sale Credit------------------------insert-- into-- public.t_tally_interface--(voucher_no,-- voucher_type,-- ledger,-- voucher_date,-- vou_narration,-- tran_type,-- unit_id,-- hospital_id,-- debit_amount,-- credit_amount,-- patient_specific,-- his_trans_type)----select-- bill_no,-- 'Sales',-- store_name,-- transdate,-- remark,-- 'Inventory',-- COGS.unit_id,-- COGS.organization_id,-- 0, -- COGS,-- 'Y',-- 'COGS'--from-- COGS--where--transdate = dateoftrans --and bill_no notnull and bill_no &lt;&gt; '' ;----------------------Inset Issue Debit------------------------insert-- into-- public.t_tally_interface--(voucher_no,-- voucher_type,-- ledger,-- voucher_date,-- vou_narration,-- tran_type,-- unit_id,-- hospital_id,-- debit_amount,-- credit_amount,-- patient_specific,-- his_trans_type)----select-- ti.issue_no ,-- 'Sales',-- 'COGS',-- transdate,-- COGS.remark,-- 'Inventory',-- COGS.unit_id,-- COGS.organization_id,-- COGS,-- 0,-- 'Y',-- 'COGS'--from--pharmacy.t_issue ti --inner join COGS on ti.sale_id = COGS.id--where--transdate = dateoftrans ;----------------------Inset Issue Credit------------------------insert-- into-- public.t_tally_interface--(voucher_no,-- voucher_type,-- ledger,-- voucher_date,-- vou_narration,-- tran_type,-- unit_id,-- hospital_id,-- debit_amount,-- credit_amount,-- patient_specific,-- his_trans_type)----select-- ti.issue_no ,-- 'Sales',-- store_name,-- transdate,-- COGS.remark,-- 'Inventory',-- COGS.unit_id,-- COGS.organization_id,-- 0, -- COGS,-- 'Y',-- 'COGS'--from--pharmacy.t_issue ti --inner join COGS on ti.sale_id = COGS.id--where--transdate = dateoftrans ;----------------------Tally Round Off--------------------------create or replace--temporary view TallyRound as (--select-- voucher_date::date,-- voucher_no,-- sum(debit_amount) debt,-- sum(credit_amount) crd,-- sum(debit_amount) - sum(credit_amount) diff--from-- t_tally_interface--group by-- voucher_no ,-- voucher_date::date--having-- sum(debit_amount) &lt;&gt; sum(credit_amount)-- and sum(debit_amount) - sum(credit_amount) &gt; -1-- and sum(debit_amount) - sum(credit_amount) &lt; 1-- order by-- 1 desc ) ;----update-- t_tally_interface as t --set-- credit_amount = round(t.credit_amount),-- debit_amount = round(t.debit_amount)--from-- TallyRound as r--where-- r.voucher_no = t.voucher_no ;-------------------------------------------------------- --update-- t_tally_interface as t --set-- credit_amount = credit_amount + m.diff--from--(--select --min(tally_transaction_id) id , --voucher_no,voucher_date::date , hospital_id , unit_id ,--sum(debit_amount) - sum(credit_amount) diff --from t_tally_interface tti where voucher_no in --(--select voucher_no --from t_tally_interface--group by voucher_no,voucher_date::date , hospital_id , unit_id --having sum(debit_amount) &lt;&gt; sum(credit_amount) --and sum(debit_amount) - sum(credit_amount) &lt; 0 --and sum(debit_amount) - sum(credit_amount) &gt; -10--order by 1 desc--) --group by voucher_no,voucher_date::date , hospital_id , unit_id --) m --where-- m.id = t.tally_transaction_id ;--update-- t_tally_interface as t --set-- credit_amount = credit_amount + m.diff --from--(--select --max(tally_transaction_id) id , --voucher_no,voucher_date::date , hospital_id , unit_id ,--sum(debit_amount) - sum(credit_amount) diff --from t_tally_interface tti where voucher_no in --(--select voucher_no --from t_tally_interface--group by voucher_no,voucher_date::date , hospital_id , unit_id --having sum(debit_amount) &lt;&gt; sum(credit_amount) --and sum(debit_amount) - sum(credit_amount) &gt; 0 --and sum(debit_amount) - sum(credit_amount) &lt; 10--order by 1 desc--) --group by voucher_no,voucher_date::date , hospital_id , unit_id --) m --where-- m.id = t.tally_transaction_id ;--------------Credit Plus Round Off------------------- create or replace temporary view credit as(select voucher_date::date,voucher_no, sum(debit_amount) debt, sum(credit_amount) crd, hospital_id , unit_id , sum(debit_amount) - sum(credit_amount) diff from t_tally_interfacegroup by voucher_no,voucher_date::date , hospital_id , unit_id having sum(debit_amount) &lt;&gt; sum(credit_amount) and (sum(debit_amount) - sum(credit_amount)) &gt; 0.0001 and (sum(debit_amount) - sum(credit_amount)) &lt; 10.1);
 create or replace temporary view credit_update as(select max(tally_transaction_id) id , voucher_date::date , voucher_no , hospital_id , unit_id from t_tally_interface where debit_amount = 0 and voucher_no in (select voucher_no from credit) group by voucher_date::date , voucher_no , hospital_id , unit_id );
create or replace temporary view credit_new as(select credit_update.id , credit.voucher_date::date , credit.voucher_no , credit.hospital_id , credit.unit_id , difffrom credit_update join credit on credit.voucher_date::date = credit_update.voucher_date::date and credit.voucher_no = credit_update.voucher_no and credit.hospital_id = credit_update.hospital_id and credit.unit_id = credit_update.unit_id);
---------------Update Credit Plus---------------------updatet_tally_interface as t setcredit_amount = credit_amount + credit_new.diff fromcredit_new where t.tally_transaction_id = credit_new.id ;--------------Credit Minus Round Off------------------- create or replace temporary view credit as(select voucher_date::date,voucher_no, sum(debit_amount) debt, sum(credit_amount) crd, hospital_id , unit_id , sum(debit_amount) - sum(credit_amount) diff from t_tally_interfacegroup by voucher_no,voucher_date::date , hospital_id , unit_id having sum(debit_amount) &lt;&gt; sum(credit_amount) and (sum(debit_amount) - sum(credit_amount)) &lt; 0.0001 and (sum(debit_amount) - sum(credit_amount)) &gt; -10.1);
 create or replace temporary view credit_update as(select max(tally_transaction_id) id , voucher_date::date , voucher_no , hospital_id , unit_id from t_tally_interface where debit_amount = 0 and voucher_no in (select voucher_no from credit) group by voucher_date::date , voucher_no , hospital_id , unit_id );
create or replace temporary view credit_new as(select credit_update.id , credit.voucher_date::date , credit.voucher_no , credit.hospital_id , credit.unit_id , difffrom credit_update join credit on credit.voucher_date::date = credit_update.voucher_date::date and credit.voucher_no = credit_update.voucher_no and credit.hospital_id = credit_update.hospital_id and credit.unit_id = credit_update.unit_id);
---------------Update Credit Minus---------------------updatet_tally_interface as t setcredit_amount = credit_amount + credit_new.diff fromcredit_new where t.tally_transaction_id = credit_new.id ;------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------return true;exceptionwhen others then return false;end;$function$;

-- DROP FUNCTION public.post_sale_notes(timestamp, varchar);
CREATE OR REPLACE FUNCTION public.post_sale_notes(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$begin--------------------------------------OPD SALE BILL DEBIT &amp; CREDIT---------------------------------------------------create or replace temporary viewsale_op as(select --mglm.general_ledger_name as ledger, tcm.company_desc as ledger,date(ts.added_date) as transactionDate, net_amount as debitNote,0::numeric as creditNote, ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id--,mglm.general_ledger_code as gl_code , ms.plant_code from pharmacy.t_sale tsjoin opd.t_patient_sponsor_details tpsd on tpsd.encounter_id = ts.encounter_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id --join m_general_ledger_master mglm on mglm.general_ledger_id = tcm.general_ledger_id join m_store ms on ms.store_id = ts.store_id )union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinct --mglm.general_ledger_name as ledger, mpc.category as ledger,date(ts.added_date) as transactionDate, 0::numeric as debitNote,(case when ms.is_tax_appllicable = 'Y' then tsd.net_amount / (1+ (tsd.tax_percentage/100))else (tsd.net_amount) end )as creditNote, tsd.tax_percentage , tsd.id , --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_code from pharmacy.t_sale tsjoin opd.t_patient_sponsor_details tpsd on tpsd.encounter_id = ts.encounter_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id join pharmacy.t_sale_detail tsd on tsd.sale_id = ts.idjoin m_item mi on mi.id = tsd.item_idjoin m_generic mg on mg.id = mi.generic_idjoin m_product_category mpc on mpc.id = mg.product_category_id--join m_general_ledger_master mglm on mglm.general_ledger_id = mpc.general_ledger_id join m_store ms on ms.store_id = ts.store_id ) temp join pharmacy.t_sale_detail tsd on temp.id = tsd.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_code) union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinctconcat(mtc.component,'-', t.percentage,'%') as Ledger ,--mglm.general_ledger_name as Ledger ,date(ts.added_date) as transactionDate, 0::numeric as debitNote,t.amount creditNote ,t.percentage , t.id , --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_code from pharmacy.t_sale_detail_tax_componenet tjoin m_tax_component mtc on t.tax_component_id = mtc.idjoin m_tax_detail mtd on mtd.tax_component_id = mtc.id and mtd.tax_percentage = t.percentage--join m_general_ledger_master mglm on mglm.general_ledger_id = mtd.sale_ledger_id join pharmacy.t_sale_detail tsd on t.sale_detail_id = tsd.id join pharmacy.t_sale ts on tsd.sale_id = ts.id join opd.t_patient_sponsor_details tpsd on tpsd.encounter_id = ts.encounter_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id join m_store ms on ms.store_id = ts.store_id and ms.is_tax_appllicable = 'Y') temp join pharmacy.t_sale_detail_tax_componenet t on temp.id = t.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_code) order by sale_id ; create or replace temporary viewsale_op_vou as select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_op.sale_idfrom sale_opgroup by sale_op.sale_id;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id , tran_type , his_trans_type --, gl_code, plant_code)select sov.voucher, 'Sale' as voucherType, so.ledger, so.transactionDate, so.debitNote, so.creditNote, so.sale_no as voucherNarration, so.unit_id, so.organization_id , 'Inventory' as tran_type , 'Sale' --, gl_code , plant_codefrom sale_op sojoin sale_op_vou sov on so.sale_id = sov.sale_idwhere so.visit_type_id = 1 and date(so.transactionDate) = dateoftrans order by so.sale_id, sov.sale_id, so.debitNote desc, so.creditNote desc;--------------------------------------IPD SALE BILL DEBIT &amp; CREDIT---------------------------------------------------create or replace temporary viewsale_ip as(select --mglm.general_ledger_name as ledger, tcm.company_desc as ledger, date(ts.added_date) as transactionDate, net_amount as debitNote,0::numeric as creditNote, ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id --,mglm.general_ledger_code as gl_code , ms.plant_code from pharmacy.t_sale tsjoin opd.t_patient_sponsor_details tpsd on tpsd.admission_id = ts.admission_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id--join m_general_ledger_master mglm on mglm.general_ledger_id = tcm.general_ledger_id join m_store ms on ms.store_id = ts.store_id )union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinct--mglm.general_ledger_name as ledger, mpc.category as ledger,date(ts.added_date) as transactionDate, 0::numeric as debitNote,(case when ms.is_tax_appllicable = 'Y' then tsd.net_amount / (1+ (tsd.tax_percentage/100))else (tsd.net_amount) end )as creditNote, tsd.tax_percentage , tsd.id, --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_codefrom pharmacy.t_sale tsjoin opd.t_patient_sponsor_details tpsd on tpsd.admission_id = ts.admission_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id join pharmacy.t_sale_detail tsd on tsd.sale_id = ts.idjoin m_item mi on mi.id = tsd.item_idjoin m_generic mg on mg.id = mi.generic_idjoin m_product_category mpc on mpc.id = mg.product_category_id--join m_general_ledger_master mglm on mglm.general_ledger_id = mpc.general_ledger_id join m_store ms on ms.store_id = ts.store_id ) temp join pharmacy.t_sale_detail tsd on temp.id = tsd.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_code)union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinctconcat(mtc.component,'-', t.percentage,'%') as Ledger ,--mglm.general_ledger_name as Ledger ,date(ts.added_date) as transactionDate, 0::numeric as debitNote,t.amount creditNote ,t.percentage , t.id , --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_code from pharmacy.t_sale_detail_tax_componenet tjoin m_tax_component mtc on t.tax_component_id = mtc.idjoin m_tax_detail mtd on mtd.tax_component_id = mtc.id and mtd.tax_percentage = t.percentage--join m_general_ledger_master mglm on mglm.general_ledger_id = mtd.sale_ledger_id join pharmacy.t_sale_detail tsd on t.sale_detail_id = tsd.id join pharmacy.t_sale ts on tsd.sale_id = ts.id join opd.t_patient_sponsor_details tpsd on tpsd.admission_id = ts.admission_id and tpsd.priority_id = 1 and tpsd.status ='A'join public.t_company_master tcm on tcm.company_id = tpsd.payee_id join m_store ms on ms.store_id = ts.store_id and ms.is_tax_appllicable = 'Y') temp join pharmacy.t_sale_detail_tax_componenet t on temp.id = t.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_code)order by sale_id ; create or replace temporary viewsale_ip_vou as select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, sale_ip.sale_idfrom sale_ipgroup by sale_ip.sale_id;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id , tran_type , his_trans_type --, gl_code , plant_code )select siv.voucher, 'Sale' as voucherType, si.ledger, si.transactionDate, si.debitNote, si.creditNote, si.sale_no as voucherNarration, si.unit_id, si.organization_id , 'Inventory' as tran_type , 'Sale' --, gl_code , plant_codefrom sale_ip sijoin sale_ip_vou siv on si.sale_id = siv.sale_idwhere si.visit_type_id = 2 and date(si.transactionDate) = dateoftransorder by si.sale_id, siv.sale_id , si.debitNote desc, si.creditNote desc;--------------------------------------WALK IN SALE BILL DEBIT &amp; CREDIT---------------------------------------------------create or replace temporary viewsale_wi as(select --mglm.general_ledger_name as ledger, tcm.company_desc as ledger, date(ts.added_date) as transactionDate, net_amount as debitNote,0::numeric as creditNote, ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id --,mglm.general_ledger_code as gl_code , ms.plant_code from pharmacy.t_sale ts join t_unit_application_billing_configuration tuabc onts.unit_id = tuabc.unit_id and ts.visit_type_id is null join t_company_master tcm on tcm.company_id = tuabc.self_payee_id join m_store ms on ms.store_id = ts.store_id left join m_general_ledger_master mglm on tcm.general_ledger_id = mglm.general_ledger_id )union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinct--mglm.general_ledger_name as ledger, mpc.category as ledger, date(ts.added_date) as transactionDate, 0::numeric as debitNote,(case when ms.is_tax_appllicable = 'Y' then tsd.net_amount / (1+ (tsd.tax_percentage/100))else (tsd.net_amount) end )as creditNote, tsd.tax_percentage , tsd.id, --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_code from pharmacy.t_sale ts join pharmacy.t_sale_detail tsd on tsd.sale_id = ts.id and ts.visit_type_id is null join m_item mi on mi.id = tsd.item_idjoin m_generic mg on mg.id = mi.generic_idjoin m_product_category mpc on mpc.id = mg.product_category_id--join m_general_ledger_master mglm on mglm.general_ledger_id = mpc.general_ledger_id join m_store ms on ms.store_id = ts.store_id ) temp join pharmacy.t_sale_detail tsd on temp.id = tsd.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_code)union all (select ledger, transactionDate, 0::numeric as debitNote,ROUND((sum(creditNote))::numeric,2 ) creditNote ,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , visit_type_id --, temp.gl_code , temp.plant_codefrom (select distinctconcat(mtc.component,'-', t.percentage,'%') as Ledger ,--mglm.general_ledger_name as Ledger ,date(ts.added_date) as transactionDate, 0::numeric as debitNote,t.amount creditNote ,t.percentage , t.id , --mglm.general_ledger_code as gl_code , ts.unit_id, ts.organization_id ,ts.id sale_id, bill_no sale_no , ts.visit_type_id , ms.plant_code from pharmacy.t_sale_detail_tax_componenet tjoin m_tax_component mtc on t.tax_component_id = mtc.idjoin m_tax_detail mtd on mtd.tax_component_id = mtc.id and mtd.tax_percentage = t.percentage--join m_general_ledger_