 join pharmacy.t_return_detail trd on temp.return_detail_id = trd.id group by ledger, transactionDate,temp.unit_id, temp.organization_id ,temp.sale_id, sale_no , temp.return_id, return_no , visit_type_id --, temp.gl_code , temp.plant_code)order by return_id ; create or replace temporary viewreturn_wi_vou as select concat('VOU-', nextval('public.tally_voucher_no_seq')) as voucher, return_wi.return_idfrom return_wigroup by return_wi.return_id;insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, vou_narration, unit_id, hospital_id , tran_type , his_trans_type --, gl_code , plant_code)select rwv.voucher, 'Credit Note' as voucherType, rw.ledger, rw.transactionDate, rw.debitNote, rw.creditNote, rw.return_no as voucherNarration, rw.unit_id, rw.organization_id , 'Inventory' as tran_type , 'Sale Return' --, gl_code , plant_codefrom return_wi rwjoin return_wi_vou rwv on rw.return_id = rwv.return_idwhere rw.visit_type_id is null and date(rw.transactionDate) = dateoftransorder by rw.return_id, rwv.return_id , rw.creditNote desc , rw.debitNote desc;--------------------------------------SALE ROUND OFF DEBIT &amp; CREDIT---------------------------------------------------updatet_tally_interface as t setcredit_amount = credit_amount + m.difffrom(select max(tally_transaction_id) id , voucher_no , voucher_type , sum(debit_amount) - sum(credit_amount) diff from t_tally_interface tti where voucher_no in (select voucher_nofrom t_tally_interfacegroup by voucher_no,voucher_date::date , hospital_id , unit_id having sum(debit_amount) &lt;&gt; sum(credit_amount) order by 1 desc )group by voucher_no , voucher_type having sum(debit_amount) - sum(credit_amount) &lt; 0 and sum(debit_amount) - sum(credit_amount) &gt; -5and voucher_type in ('Sale', 'Credit Note')) as mwherem.id = t.tally_transaction_id ;updatet_tally_interface as t set-- debit_amount = debit_amount - m.diff credit_amount = credit_amount + m.difffrom(select max(tally_transaction_id) id , voucher_no , voucher_type , sum(debit_amount) - sum(credit_amount) diff from t_tally_interface tti where voucher_no in (select voucher_nofrom t_tally_interfacegroup by voucher_no,voucher_date::date , hospital_id , unit_id having sum(debit_amount) &lt;&gt; sum(credit_amount) order by 1 desc )group by voucher_no , voucher_type having sum(debit_amount) - sum(credit_amount) &gt; 0 and sum(debit_amount) - sum(credit_amount) &lt; 5and voucher_type in ('Sale', 'Credit Note')) as mwherem.id = t.tally_transaction_id ;-----------------------------------------update plant_code------------------------------------------------update t_tally_interface --set plant_code = (select plant_code from m_store where is_pharmacy = true order by store_id limit 1)--where tran_type = 'Inventory' and plant_code = '0' ; --update t_tally_interface --set plant_code = (select plant_code from m_unit_master where unit_id = 1)--where tran_type &lt;&gt; 'Inventory' and plant_code = '0' ; -------------------------------------------------------------------------------------------------------return true;EXCEPTION when OTHERS then return false;end;$function$;

