CREATE OR REPLACE FUNCTION public.post_visit_fa_data(dateoftrans timestamp without time zone, unitarray character varying)RETURNS booleanLANGUAGE plpgsqlAS $function$ begin----------- Create view ---------------------------create or replacetemporary view opbillPatientSpecific as (selectpMode.payment_mode_id as modeid,pMode.ledger_name as mode,pReceiptDtls.amount as rcptamount,billMst.outstanding as outstanding,billMst.net_amount as billnetamount,bank.bank_name as bankname,pReceiptDtls.card_number as cardnumber,pReceiptDtls.card_type_id as cardtypeid,pReceiptDtls.check_number as chequenumber,pReceiptDtls.cheque_date::date as chequedate,pReceiptDtls.transaction_no as transactionno,pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid,billMst.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate,billMst.bill_date_time :: date as billdate,pReceiptDtls.trans_transaction_date as transferdate,pReceiptDtls.available_fund as availableFund,pat.patient_id as patientId,concat(pat.first_name, ' ', pat.last_name) as patientname,pReceiptMst.reciept_number as recieptnumber,billMst.bill_number as billnumber,billMst.billing_master_id as billId,trans.transaction_type_desc as transactionType,(casewhen billMst.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode onpMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst onpReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_idinner join billing.m_billing_master billMst onpReceiptMst.billing_master_id = billMst.billing_master_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idleft join billing.m_bank_master bank onbank.bank_id = pReceiptDtls.bank_idleft join billing.m_transaction_type_master trans onpReceiptDtls.transaction_type_id = trans.transaction_type_idwherepReceiptDtls.status = 'A'and pReceiptMst.status = 'A'and billMst.status = 'A');
------- Insert cash start ---------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, tran_type, vou_narration, patient_specific)selectconcat(opbill.billnumber),'Receipt',opbill.mode,opbill.transdate,cast(sum(opbill.rcptamount) as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId ,opbill.billId,opbill.visittype,(selectnarrationfrompublic.getnurrationname(opbill.billId)),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate = opbill.billdateand opbill.modeid = 1and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billId,opbill.billnumber,opbill.patientname,opbill.paymentreceiptdetailId,opbill.modeid,opbill.mode,opbill.visittype;------- Insert cash end ---------------------- Insert Cheque start ---------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)selectconcat(opbill.billnumber),'Receipt',-- opbill.mode,tuabc.cheque_ledger_name as mode,opbill.transdate,cast(opbill.rcptamount as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.billId,coalesce(opbill.chequedate, opbill.transferdate),opbill.visittype,opbill.bankname,coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),concat((select narration from public.getnurrationname(opbill.billId)), ' | ', opbill.transactionType),'Y'fromopbillPatientSpecific as opbill inner join t_unit_application_billing_configuration tuabc on opbill.orgId = tuabc.organization_id and opbill.unitId = tuabc.unit_id whereopbill.transdate = opbill.billdateand opbill.modeid = 2and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billId,opbill.billnumber,opbill.patientname,opbill.modeid,opbill.mode,tuabc.cheque_ledger_name ,opbill.rcptamount,opbill.paymentreceiptdetailId,opbill.chequedate,opbill.transferdate,opbill.bankname,opbill.chequenumber,opbill.cardnumber,opbill.transactionno,opbill.transactionType,opbill.visittype;------- Insert Cheque End ---------------------- Insert others start where transaction-date = bill-date---------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)selectconcat(opbill.billnumber),'Receipt',opbill.mode,opbill.transdate,cast(opbill.rcptamount as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.billId,coalesce(opbill.chequedate, opbill.transferdate),opbill.visittype,opbill.bankname,coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),concat((select narration from public.getnurrationname(opbill.billId)), ' | ', opbill.transactionType),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate = opbill.billdateand opbill.modeid not in (1,2)and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billId,opbill.billnumber,opbill.patientname,opbill.modeid,opbill.mode,opbill.rcptamount,opbill.paymentreceiptdetailId,opbill.chequedate,opbill.transferdate,opbill.bankname,opbill.chequenumber,opbill.cardnumber,opbill.transactionno,opbill.transactionType,opbill.visittype;------- Insert others start---------------with roundoff as (selectbm.bill_number as billno,sum(bm.round_off) as round_off_amount,bm.unit_id as unitId,bm.organisation_id as orgId,bm.created_date::date as transactionDate,pat.patient_id as patientid,concat(concat(pat.first_name, ' ', pat.last_name) , ' | ', coalesce(bm.bill_number, ''))as patientname,bm.billing_master_id as billid,(casewhen bm.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.m_billing_master bminner join patient.t_patient_registration pat onpat.patient_id = bm.patient_idwherebm.created_date::date = dateoftransand bm.visit_type_id = 1and bm.bill_cancelled = 'N'and bm.status = 'A'group bybm.organisation_id,bm.unit_id,bm.created_date::date,bm.billing_master_id,bm.bill_number,pat.patient_idhavingsum(bm.round_off) &lt;&gt; 0)insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectroundoff.billno,'Receipt','Discount round-off',roundoff.transactionDate,casewhen roundoff.round_off_amount&lt;0 then cast(-roundoff.round_off_amount as numeric(10, 2))else 0end,casewhen roundoff.round_off_amount&gt;0 then cast(roundoff.round_off_amount as numeric(10, 2))else 0end ,roundoff.unitId,roundoff.orgId,roundoff.visittype,(selectnarrationfrompublic.getnurrationname(roundoff.billid)),'Y',roundoff.billidfromroundoffwhereroundoff.round_off_amount &gt;0or roundoff.round_off_amount &lt;0 ;---------------------- Company amount --------------------------------with comp as (selecttbpd.payee_id as ledgerId,comp.company_desc as ledger,--sum(mpr.payee_amount) as amount,sum(tbpd.bill_amount) as amount,billMst.bill_date_time ::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billid,(casewhen billMst.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.m_billing_master billMst inner join billing.t_bill_payee_details tbpd on tbpd.bill_id = billMst.billing_master_idinner join public.t_company_master comp oncomp.company_id = tbpd.payee_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_id-- billing.t_bill_details_payee_mapper mpr--inner join billing.t_billing_details billDtls on-- mpr.bill_details_id = billDtls.billing_details_id--inner join billing.m_billing_master billMst on-- billMst.billing_master_id = billDtls.billing_master_id--inner join public.t_company_master