l.organisation_id as orgId,bill.unit_id as unitId,bill.bill_date_time::date as billDate,concat(pat.first_name, ' ', pat.last_name) as patientname,bill.bill_number as billno,bill.billing_master_id as billid,(casewhen bill.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.m_billing_master billinner join billing.t_bill_payee_details tbpd onbill.billing_master_id = tbpd.bill_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwherebill.bill_date_time::date = dateoftrans--and bill.visit_type_id = 1and bill.bill_cancelled = 'N'and tbpd.payee_id = (selectself_payee_idfromt_unit_application_billing_configuration tuabcwhereunit_id = bill.unit_id )group bybill.organisation_id,bill.unit_id,bill.bill_date_time::date,bill.billing_master_id,bill.bill_number,pat.patient_id )insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectoutst.billno,'Receipt','Patient Credit',outst.billDate,cast((outst.outstanding) as numeric(10, 2)),0,outst.unitId,outst.orgId,outst.visittype,(selectnarrationfrompublic.getnurrationname(outst.billid)),'Y',outst.billidfromoutstwhere(outst.outstanding) &gt; 0;with outstand as (selectsum(coalesce(tprm.amount)) as outstanding,bill.organisation_id as orgId,bill.unit_id as unitId,bill.bill_date_time::date as billDate,concat(pat.first_name, ' ', pat.last_name) as patientname,bill.bill_number as billno,bill.billing_master_id as billid,(casewhen bill.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.t_payment_reciept_master tprminner join billing.m_billing_master bill onbill.billing_master_id = tprm.billing_master_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwherebill_date_time::date != tprm.date_of_reciept::dateand bill.bill_date_time::date = dateoftrans--and bill.visit_type_id = 1and bill.bill_cancelled = 'N'group bybill.organi