---------------- Ledger start -------------------------with gen as (selectgenLedMSt.general_ledger_id as ledgerId,genLedMSt.general_ledger_name as ledger,--sum(billDtls.net_amt) as amount,sum(billDtls.net_amt + concession + discount) as amount,billMst.bill_date_time::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billid,(casewhen billMst.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.t_billing_details billDtlsinner join billing.m_billing_master billMst onbillMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst onservMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst ongenLedMst.general_ledger_id = servMst.general_ledger_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillMst.bill_date_time :: date = dateoftrans--and billMst.visit_type_id = 1and billMst.bill_cancelled = 'N'and billDtls.status = 'A'and billDtls.package_consumption_amt = 0group bybillMst.organisation_id,billMst.unit_id,billMst.bill_date_time::date,billMst.billing_master_id,billMst.bill_number,pat.patient_id,genLedMSt.general_ledger_id )insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectgen.billno,'Receipt',gen.ledger,gen.transactionDate,0,cast(gen.amount as numeric(10, 2)),gen.unitId,gen.orgId,gen.visittype,(selectnarrationfrompublic.getnurrationname(gen.billid)),'Y',gen.billidfromgen;------------ Ledger end --------------------------------------------- Tax ---------------------------with gen as (selectbillDtls.tax_id,tax."name" as taxname,sum(billDtls.tax_amount) as amount,billMst.bill_date_time::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billid,(casewhen billMst.visit_type_id = 1 then 'OP'else 'IP'end) as visittypefrombilling.t_billing_details billDtlsinner join billing.m_billing_master billMst onbillMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst onservMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst ongenLedMst.general_ledger_id = servMst.general_ledger_idinner join public.m_tax tax ontax.id = billDtls.tax_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillMst.bill_date_time::date = dateoftransand billMst.visit_type_id = 1and billMst.bill_cancelled = 'N'and billDtls.status = 'A'group bybillMst.organisation_id,billMst.unit_id,billMst.bill_date_time::date,billMst.billing_master_id,billMst.bill_number,pat.patient_id,billDtls.tax_id,tax."name"havingsum(billDtls.tax_amount) &gt; 0)insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectgen.billno,'Receipt',gen.taxname,gen.transactionDate,0,cast(gen.amount as numeric(10, 2)),gen.unitId,gen.orgId,gen.visittype,(selectnarrationfrompublic.getnurrationname(gen.billid)),'Y',gen.billidfromgen;------------------------------------------------------------------------Previous date settlement start cash-----------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectopbill.recieptnumber,-- opbill.billnumber, 'Receipt',opbill.mode,opbill.transdate,cast(sum(opbill.rcptamount) as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.visittype,(selectnarrationfrompublic.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbillwhereopbill.transdate != opbill.billdateand opbill.modeid = 1and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.recieptnumber,-- opbill.billnumber, opbill.patientname,opbill.modeid,opbill.mode,opbill.visittype;--------------------------------------------------Previous date settlement start others-----------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)selectopbill.recieptnumber,-- opbill.billnumber, 'Receipt',opbill.mode,opbill.transdate,cast(opbill.rcptamount as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.billid,coalesce(opbill.chequedate, opbill.transferdate),opbill.visittype,opbill.bankname,coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),(selectnarrationfrompublic.getnurrationname(opbill.billid)),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate != opbill.billdateand opbill.modeid &lt;&gt; 1and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.recieptnumber,-- opbill.billnumber, opbill.patientname,opbill.modeid,opbill.mode,opbill.rcptamount,opbill.paymentreceiptdetailId,opbill.chequedate,opbill.transferdate,opbill.bankname,opbill.chequenumber,opbill.cardnumber,opbill.transactionno,opbill.visittype;--------------------------------------------------------------Credit insert start--------------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectopbill.recieptnumber,-- opbill.billnumber, 'Receipt','Patient Credit',opbill.transdate,0,cast(sum(coalesce(opbill.rcptamount,0)-coalesce(opbill.availableFund,0)) as numeric(10, 2)),opbill.unitid,opbill.orgid,opbill.visittype,(selectnarrationfrompublic.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbillwhereopbill.transdate = dateoftransand opbill.transdate != opbill.billdategroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.recieptnumber,-- opbill.billnumber, opbill.patientname,opbill.visittype;insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific, unique_number)selectopbill.billnumber,'Receipt','Available Fund',opbill.transdate,0,cast(sum(opbill.availableFund) as numeric(10, 2)),opbill.unitid,opbill.orgid,opbill.visittype,(selectnarrationfrompublic.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbillwhereopbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.billnumber,opbill.patientname,opbill.visittypehavingsum(opbill.availableFund) &gt; 0;------- INCOME EXPENCES DETAILS----------------------------------------------------------------------------------------------------------------insert into public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number,instrument_number)---Income --- select distinct tme.expense_id,'Receipt' ,mglm.general_ledger_name ,tme.bill_date_time::Date,0,tme.amount,tme.unit_id ,tme.org_id ,'OP',concat(tme."name",'- ',coalesce(tme.bill_number,'')) Narraton,'Y',tme.expense_id ,'' as instrumentnumberfrom billing.t_miscellaneous_expense tme inner join m_general_ledger_master mglm on mglm.general_ledger_id = tme.account_head where tme.is_cancelled = 'N' and tme.bill_type = 1 and tme.bill_date_time::Date = dateoftransunion allselect distinct tme.expense_id,'Receipt' ,mpmm.ledger_name,tme.bill_date_time::Date,tmerd.amount,0 ,tme.unit_id ,tme.org_id ,'OP',concat("name",'- ',coalesce(bill_number,'')) Narraton,'Y',tme.expense_id,concat(coalesce(tmerd.check_number,'') ,'', coalesce(tmerd.card_number,''),'', coalesce(tmerd.transaction_no,'')) as instrumentnumberfrom billing.t_miscellaneous_expense tme inner join billing.t_miscellaneous_expense_reciept tmer on tmer.expense_id = tme.expense_id inner join billing.t_miscellaneous_expense_reciept_details tmerd on tmerd .expense_reciept_id = tmer.expense_reciept_id inner join m_payment_mode_master mpmm on mpmm.payment_mode_id = tmerd .payment_mode_id where tme.is_cancelled = 'N' and tme.bill_type = 1 and tme.bill_date_time::Date = dateoftrans---Income End---union all ---Expenace---select distinct tme.expense_id,'Payment' ,mglm.general_ledger_name ,tme.bill_date_time::Date,tme.amount,0,tme.unit_id ,tme.org_id ,'OP',concat(tme."name",'- ',coalesce(tme.bill_number,'')) Narraton,'Y',tme.expense_id ,'' as instrumentnumberfrom billing.t_miscellaneous_expense tme inner join m_general_ledger_master mglm on mglm.general_ledger_id = tme.account_head where tme.is_cancelled = 'N' and tme.bill_type = 2 and tme.bill_date_time::Date = dateoftransunion allselect distinct tme.expense_id,'Payment' ,mpmm.ledger_name,tme.bill_date_time::Date,0,tmerd.amount,tme.unit_id ,tme.org_id ,'OP',concat("name",'- ',coalesce(bill_number,'')) Narraton,'Y',tme.expense_id,concat(coalesce(tmerd.check_number,'') ,'', coalesce(tmerd.card_number,''),'', coalesce(tmerd.transaction_no,'')) as instrumentnumberfrom billing.t_miscellaneous_expense tme inner join billing.t_miscellaneous_expense_reciept tmer on tmer.expense_id = tme.expense_id inner join billing.t_miscellaneous_expense_reciept_details tmerd on tmerd .expense_reciept_id = tmer.expense_reciept_id inner join m_payment_mode_master mpmm on mpmm.payment_mode_id = tmerd .payment_mode_id where tme.is_cancelled = 'N' and tme.bill_type = 2 and tme.bill_date_time::Date = dateoftrans;--Expenace end ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------Insert Refund Patient wise--insert into public.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, --unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number,instrument_number)----select-- concat(mcnm.credit_note_id,'-',credit_note_no ) voucher_no ,'Payment' as voucher_type,mglm.general_ledger_name ,mcnm.created_date::date,-- sum(tcnd.cr_net_amount) debitamount ,0 as creditAmount,mcnm.unit_id ,mcnm.organisation_id,'OP',-- concat(concat(public.getnurrationname(mcnm.bill_id) ,'-' , credit_note_no) ,' | ', coalesce(credit_note_remark,''))as Narration-- ,'Y',mcnm.credit_note_id,'' as instrument_number--from-- billing.m_credit_note_master mcnm -- inner join billing.m_billing_master mbm on mbm.billing_master_id = mcnm.bill_id -- inner join billing.t_credit_note_detail tcnd on tcnd.credit_note_id = mcnm.credit_note_id -- inner join billing.t_billing_details tbd on tbd.order_details_id = tcnd.order_detail_id -- inner join service.m_service_master msm on msm.service_master_id = tbd.service_id -- inner join m_general_ledger_master mglm on mglm.general_ledger_id = msm.general_ledger_id --where mcnm.is_approved = 'Y' and mcnm.created_date::date = dateoftrans--group by mcnm.credit_note_id,mcnm.created_date::date,mglm.general_ledger_name ----union all-- --select distinct -- concat(mcnm.credit_note_id,'-',credit_note_no ) voucher_no ,'Payment' as voucher_type,mpmm.ledger_name as ledger_name ,mcnm.created_date::date,-- 0 as debitamount ,tprd.amount as creditAmount,mcnm.unit_id ,mcnm.organisation_id,'OP',-- concat(concat(public.getnurrationname(mcnm.bill_id) ,'-' , credit_note_no) ,' | ', coalesce(credit_note_remark,''))as Narration-- ,'Y',mcnm.credit_note_id, concat(coalesce(tprd.cheque_number ,'') ,'', coalesce(tprd.card_number ,''),'', coalesce(tprd.transaction_no ,'')) as instrumentnumber -- from-- billing.m_credit_note_master mcnm -- inner join billing.t_payment_refund_master prm on prm.credit_note_id = mcnm.credit_note_id -- inner join billing.t_payment_refund_details tprd on tprd.payment_refund_id = prm.payment_refund_id -- inner join m_payment_mode_master mpmm on mpmm.payment_mode_id = tprd.payment_mode_id ----where mcnm.is_approved = 'Y' and mcnm.created_date::date = dateoftrans----order by 1 desc;------------------------------------------------------------------------------------------return true;exceptionwhen others then return false;commit;end;$function$;

-- DROP FUNCTION public.post_visit_fa_data_patientwise(timestamp);
CREATE OR REPLACE FUNCTION public.post_visit_fa_data_patientwise(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$begin ------&lt;----1. OP--------------- ----------- Create view ---------------------------create or replace temporary view opbillPatientSpecificAS(selectpMode.payment_mode_id as modeid,pMode.payment_mode_desc as mode,pReceiptDtls.amount as rcptamount,billMst.outstanding as outstanding,billMst.net_amount as billnetamount,bank.bank_name as bankname,pReceiptDtls.card_number as cardnumber,pReceiptDtls.card_type_id as cardtypeid,pReceiptDtls.check_number as chequenumber,pReceiptDtls.cheque_date::date as chequedate,pReceiptDtls.transaction_no as transactionno,pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid,billMst.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate,billMst.bill_date_time :: date as billdate,pReceiptDtls.trans_transaction_date as transferdate,pReceiptDtls.available_fund as availableFund,pat.patient_id as patientId,concat(pat.first_name,' ',pat.last_name) as patientname,pReceiptMst.reciept_number as recieptnumber,billMst.bill_number as billnumber,billMst.billing_master_id as billId,trans.transaction_type_desc as transactionTypefrombilling.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode onpMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst onpReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_idinner join billing.m_billing_master billMst onpReceiptMst.billing_master_id = billMst.billing_master_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_id left join billing.m_bank_master bank onbank.bank_id = pReceiptDtls.bank_idleft join billing.m_transaction_type_master trans onpReceiptDtls.transaction_type_id = trans.transaction_type_id wherebillMst.visit_type_id = 1and pReceiptDtls.status = 'A'and pReceiptMst.status = 'A'and billMst.status = 'A');
------- Insert cash start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number, tran_type,vou_narration, patient_specific)selectconcat(opbill.billnumber),'Receipts',opbill.mode,opbill.transdate,cast(sum(opbill.rcptamount) as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId ,opbill.billId,'OP',(select narration from public.getnurrationname(opbill.billId)),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate = opbill.billdateand opbill.modeid = 1and opbill.transdate = dateoftransgroup by opbill.orgid,opbill.unitid,opbill.transdate,opbill.billId,opbill.billnumber,opbill.patientname,opbill.paymentreceiptdetailId,opbill.modeid,opbill.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)selectopbill.billnumber,'Receipts',opbill.mode,opbill.transdate,cast(opbill.rcptamount as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.billId,coalesce(opbill.chequedate, opbill.transferdate),'OP',opbill.bankname,coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),concat((select narration from public.getnurrationname(opbill.billId)),' | ',opbill.transactionType),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate = opbill.billdateand opbill.modeid &lt;&gt; 1and opbill.orgid!=10and opbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billId,opbill.billnumber,opbill.patientname,opbill.modeid,opbill.mode,opbill.rcptamount,opbill.paymentreceiptdetailId,opbill.chequedate,opbill.transferdate,opbill.bankname,opbill.chequenumber, opbill.cardnumber, opbill.transactionno,opbill.transactionType;------- Insert others start--------------- with roundoff as (selectbm.bill_number as billno,sum(bm.round_off) as round_off_amount,bm.unit_id as unitId,bm.organisation_id as orgId,bm.created_date::date as transactionDate,pat.patient_id as patientid,concat(concat(pat.first_name,' ',pat.last_name) ,' | ', coalesce(bm.bill_number,''))as patientname,bm.billing_master_id as billidfrombilling.m_billing_master bminner join patient.t_patient_registration pat onpat.patient_id = bm.patient_id wherebm.created_date::date = dateoftransand bm.visit_type_id = 1and bm.bill_cancelled = 'N'and bm.status = 'A'group bybm.organisation_id,bm.unit_id,bm.created_date::date,bm.billing_master_id,bm.bill_number,pat.patient_idhavingsum(bm.round_off) &lt;&gt;0)insertintopublic.t_tally_interface (voucher_no,voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type,vou_narration, patient_specific,unique_number)selectroundoff.billno,'Receipts','Discount round-off',roundoff.transactionDate,casewhen roundoff.round_off_amount&lt;0 then cast(-roundoff.round_off_amount as numeric(10, 2))else 0end,casewhen roundoff.round_off_amount&gt;0 then cast(roundoff.round_off_amount as numeric(10, 2))else 0end ,roundoff.unitId,roundoff.orgId,'OP',(select narration from public.getnurrationname(roundoff.billid)),'Y',roundoff.billidfromroundoffwhereroundoff.round_off_amount &gt;0or roundoff.round_off_amount &lt;0 ;---------------------- Company amount --------------------------------with comp as (selectmpr.payee_id as ledgerId,comp.company_desc as ledger,sum(mpr.payee_amount) as amount,billDtls.created_date::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billidfrombilling.t_bill_details_payee_mapper mprinner join billing.t_billing_details billDtls onmpr.bill_details_id = billDtls.billing_details_idinner join billing.m_billing_master billMst onbillMst.billing_master_id = billDtls.billing_master_idinner join public.t_company_master comp oncomp.company_id = mpr.payee_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillDtls.created_date::date = dateoftransand billMst.visit_type_id = 1and mpr.status = 'A'and billMst.bill_cancelled = 'N'and mpr.payee_id &lt;&gt; (selectself_payee_idfromt_unit_application_billing_configurationwhereunit_id = billMst.unit_idand status = 'A')group bybillMst.organisation_id,billMst.unit_id,billDtls.created_date::date,billMst.billing_master_id, billMst.bill_number,pat.patient_id,mpr.payee_id,comp.company_desc )insertintopublic.t_tally_interface (voucher_no,voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectcomp.billno,'Receipts',comp.ledger,comp.transactionDate,cast(comp.amount as numeric(10, 2)),0,comp.unitId,comp.orgId,'OP',(select narration from public.getnurrationname(comp.billid)),'Y',comp.billidfromcomp;------------------------------Package consumption ---------------------------------/*with pack as (selectgenLedMst.general_ledger_id,genLedMst.general_ledger_name as ledger,sum(dtls.gross_amount) as amount ,bill.organisation_id as orgId,bill.unit_id as unitId,dtls.created_date::date as createdDate,concat(pat.first_name, ' ', pat.last_name) as patientname,bill.bill_number as billno,bill.billing_master_id as billidfrombilling.t_billing_details dtlsinner join billing.m_billing_master bill onbill.billing_master_id = dtls.billing_master_idinner join service.m_service_master servMst onservMst.service_master_id = dtls.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst ongenLedMst.general_ledger_id = spc.general_ledger_idinner join public.t_order_details ordt onordt.order_details_id = dtls.order_details_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwheredtls.created_date::date = dateoftransand bill.visit_type_id = 1and ordt.is_package_service = 'Y'and bill.bill_cancelled = 'N'group bybill.organisation_id,bill.unit_id,dtls.created_date::date,bill.billing_master_id,bill.bill_number,pat.patient_id,genLedMSt.general_ledger_id,genLedMst.general_ledger_name)insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific)selectpack.billno,'Receipts',pack.ledger,pack.createdDate,cast(pack.amount as numeric(10, 2)),0,pack.unitId,pack.orgId,'OP',(select narration from public.getnurrationname(pack.billid)),'Y'frompack;*/---------------------------------------------------------------------- Insert deposit consumption --------------------------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectbill.bill_number,'Receipts','Patient Advance',pdc.created_date::date,cast(sum(pdc.consumed_amount) as numeric(10, 2)),0,pdc.unit_id,pdc.organization_id,'OP',(select narration from public.getnurrationname(bill.billing_master_id)),'Y',bill.billing_master_id frombilling.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pd onpd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master bill onbill.billing_master_id = pd.bill_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwherepdc.created_date::date = dateoftransand bill.visit_type_id = 1and bill.bill_cancelled = 'N'group bypdc.organization_id,pdc.unit_id,pdc.created_date::date, bill.billing_master_id,bill.bill_number,pat.patient_id;-------------------xxx-------------------------------------------- Insert outstanding start---------------with outst as (selectcoalesce(sum(tbpd.due_amount), 0) as outstanding,bill.organisation_id as orgId,bill.unit_id as unitId,bill.bill_date_time::date as billDate,concat(pat.first_name, ' ', pat.last_name) as patientname,bill.bill_number as billno,bill.billing_master_id as billidfrombilling.m_billing_master billinner join billing.t_bill_payee_details tbpd onbill.billing_master_id = tbpd.bill_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwherebill.bill_date_time::date = dateoftransand bill.visit_type_id = 1and bill.bill_cancelled = 'N'and tbpd.payee_id = (selectself_payee_idfromt_unit_application_billing_configuration tuabcwhereunit_id = bill.unit_id )group bybill.organisation_id,bill.unit_id,bill.bill_date_time::date,bill.billing_master_id,bill.bill_number,pat.patient_id )insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectoutst.billno,'Receipts','Patient Credit',outst.billDate,cast((outst.outstanding) as numeric(10, 2)),0,outst.unitId,outst.orgId,'OP',(select narration from public.getnurrationname(outst.billid)),'Y',outst.billidfromoutstwhere(outst.outstanding) &gt; 0;with outstand as (selectcoalesce(tprm.amount- (select available_fund from billing.t_payment_reciept_details tprd where tprd.payment_receipt_master_id = tprm.payment_reciept_id), 0) as outstanding,bill.organisation_id as orgId,bill.unit_id as unitId,bill.bill_date_time::date as billDate,concat(pat.first_name, ' ', pat.last_name) as patientname,bill.bill_number as billno,bill.billing_master_id as billidfrombilling.t_payment_reciept_master tprminner join billing.m_billing_master bill onbill.billing_master_id = tprm.billing_master_idinner join patient.t_patient_registration pat onpat.patient_id = bill.patient_idwherebill_date_time::date != tprm.date_of_reciept::dateand bill.bill_date_time::date = dateoftransand bill.visit_type_id = 1and bill.bill_cancelled = 'N'group bybill.organisation_id,bill.unit_id,bill.bill_date_time::date,bill.billing_master_id,bill.bill_number,pat.patient_id,tprm.amount,tprm.payment_reciept_id )insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectoutstand.billno,'Receipts','Patient Credit ',outstand.billDate,cast((outstand.outstanding) as numeric(10, 2)),0,outstand.unitId,outstand.orgId,'OP',(select narration from public.getnurrationname(outstand.billid)),'Y',outstand.billidfromoutstandwhere(outstand.outstanding) &gt; 0;------- Insert outstanding end----------------------------------- Discount --------------------------with gen as (selectsum(billMst.discount_amount + billMst.concession_amount) as amount,billMst.created_date::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billidfrombilling.m_billing_master billMstinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillMst.created_date::date = dateoftransand billMst.visit_type_id = 1and billMst.bill_cancelled = 'N'group bybillMst.organisation_id,billMst.unit_id,billMst.created_date::date,billMst.billing_master_id,billMst.bill_number,pat.patient_idhavingsum(billMst.discount_amount) &gt; 0)insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectgen.billno,'Receipts','Discount',gen.transactionDate,cast(gen.amount as numeric(10, 2)),0,gen.unitId,gen.orgId,'OP',(select narration from public.getnurrationname(gen.billid)),'Y',gen.billidfromgen;------------------------------------------------------------ Ledger start -------------------------with gen as (selectgenLedMSt.general_ledger_id as ledgerId,genLedMSt.general_ledger_name as ledger,sum(billDtls.gross_amount) as amount,billMst.bill_date_time::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billidfrombilling.t_billing_details billDtlsinner join billing.m_billing_master billMst onbillMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst onservMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst ongenLedMst.general_ledger_id = servMst.general_ledger_id inner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillMst.bill_date_time :: date = dateoftransand billMst.visit_type_id = 1and billMst.bill_cancelled = 'N'and billDtls.status = 'A'and billDtls.package_consumption_amt = 0group bybillMst.organisation_id,billMst.unit_id,billMst.bill_date_time::date,billMst.billing_master_id,billMst.bill_number,pat.patient_id,genLedMSt.general_ledger_id )insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectgen.billno,'Receipts',gen.ledger,gen.transactionDate,0,cast(gen.amount as numeric(10, 2)),gen.unitId,gen.orgId,'OP',(select narration from public.getnurrationname(gen.billid)),'Y',gen.billidfromgen;------------ Ledger end --------------------------------------------- Tax ---------------------------with gen as (selectbillDtls.tax_id,tax."name" as taxname,sum(billDtls.tax_amount) as amount,billMst.bill_date_time::date as transactionDate,billMst.organisation_id as orgId,billMst.unit_id as unitId,concat(pat.first_name, ' ', pat.last_name) as patientname,billMst.bill_number as billno,billMst.billing_master_id as billidfrombilling.t_billing_details billDtlsinner join billing.m_billing_master billMst onbillMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst onservMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc onspc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst ongenLedMst.general_ledger_id = servMst.general_ledger_id inner join public.m_tax tax ontax.id = billDtls.tax_idinner join patient.t_patient_registration pat onpat.patient_id = billMst.patient_idwherebillMst.bill_date_time::date = dateoftransand billMst.visit_type_id = 1and billMst.bill_cancelled = 'N'and billDtls.status = 'A'group bybillMst.organisation_id,billMst.unit_id,billMst.bill_date_time::date,billMst.billing_master_id,billMst.bill_number,pat.patient_id,billDtls.tax_id,tax."name"havingsum(billDtls.tax_amount) &gt; 0)insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectgen.billno,'Receipts',gen.taxname,gen.transactionDate,0,cast(gen.amount as numeric(10, 2)),gen.unitId,gen.orgId,'OP',(select narration from public.getnurrationname(gen.billid)),'Y',gen.billidfromgen;------------------------------------------------------------------------Previous date settlement start cash-----------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectopbill.billnumber,'Receipt',opbill.mode,opbill.transdate,cast(sum(opbill.rcptamount) as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,'OP',(select narration from public.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbillwhereopbill.transdate != opbill.billdateand opbill.modeid = 1and opbill.transdate = dateoftransgroup by opbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.billnumber,opbill.patientname,opbill.modeid,opbill.mode;--------------------------------------------------Previous date settlement start others-----------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, unique_number, instrument_date, tran_type, bank_name, instrument_number, vou_narration, patient_specific)selectopbill.billnumber,'Receipt',opbill.mode,opbill.transdate,cast(opbill.rcptamount as numeric(10, 2)),0 ,opbill.unitId,opbill.orgId,opbill.billid,coalesce(opbill.chequedate, opbill.transferdate),'OP',opbill.bankname,coalesce(opbill.chequenumber, opbill.cardnumber, opbill.transactionno),(select narration from public.getnurrationname(opbill.billid)),'Y'fromopbillPatientSpecific as opbillwhereopbill.transdate != opbill.billdateand opbill.modeid &lt;&gt; 1and opbill.transdate = dateoftransgroup by opbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.billnumber,opbill.patientname,opbill.modeid,opbill.mode,opbill.rcptamount,opbill.paymentreceiptdetailId,opbill.chequedate,opbill.transferdate,opbill.bankname,opbill.chequenumber,opbill.cardnumber,opbill.transactionno;--------------------------------------------------------------Credit insert start--------------------------insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectopbill.billnumber,'Receipt','Patient Credit',opbill.transdate,0,cast(sum(opbill.rcptamount) as numeric(10, 2)),opbill.unitid,opbill.orgid,'OP',(select narration from public.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbillwhereopbill.transdate = dateoftransand opbill.transdate != opbill.billdategroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.billnumber,opbill.patientname;insertintopublic.t_tally_interface (voucher_no, voucher_type, ledger, voucher_date, debit_amount, credit_amount, unit_id, hospital_id, tran_type, vou_narration, patient_specific,unique_number)selectopbill.billnumber,'Receipts','Available Fund',opbill.transdate,0,cast(sum(opbill.availableFund) as numeric(10, 2)),opbill.unitid,opbill.orgid,'OP',(select narration from public.getnurrationname(opbill.billid)),'Y',opbill.billidfromopbillPatientSpecific as opbill whereopbill.transdate = dateoftransgroup byopbill.orgid,opbill.unitid,opbill.transdate,opbill.billid,opbill.billnumber,opbill.patientnamehavingsum(opbill.availableFund) &gt; 0;----------1. OP----&gt;----------- return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postadvancerefund(timestamp);
CREATE OR REPLACE FUNCTION public.postadvancerefund(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin -- insert cash mode advance refund amountinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', 'Patient Advance', prm.created_date::date, sum(prm.amount_refunded), 0 , prm.unit_id, prm.orgnisation_id, 'IP'from billing.t_payment_refund_master prm where prm.is_cn_or_deposit = 0 and prm.created_date::date = dateoftransgroup by prm.orgnisation_id, prm.unit_id,prm.created_date::date;--- xxx--- create view for payment detailscreate or replace temporary view refundpaydtlsas select prd.payment_refund_details_id as id, prd.payment_mode_id as modeid, pmod.payment_mode_desc as mode, prd.amount as amount,prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd.date::date as chequedate,prd.orgnisation_id as orgid, prd.unit_id as unitid, prd.created_date::date as date, bank.bank_name as banknamefrom billing.t_payment_refund_details prdinner join public.m_payment_mode_master pmod on pmod.payment_mode_id = prd.payment_mode_idinner join billing.t_payment_refund_master prm on prm.payment_refund_id = prd.payment_refund_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere prm.is_cn_or_deposit = 0;--xxx--- insert cash mode transactionsinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid , 'IP'from refundpaydtls rpdwhere rpd.date = dateoftrans group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;---xxx/*--- insert other mode transactionsinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Payment', rpd.mode, rpd.date, 0, sum(rpd.amount) , rpd.unitid, rpd.orgid, rpd.id,coalesce(rpd.chequedate,rpd.date), 'IP', rpd.bankname, coalesce(rpd.chequenumber, rpd.cardnumber)from refundpaydtls rpdwhere rpd.date = dateoftrans and rpd.modeid != 1group by rpd.mode , rpd.orgid, rpd.unitid, rpd.date;*/return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postbillrefund(timestamp);
CREATE OR REPLACE FUNCTION public.postbillrefund(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare nextvoucherno integer = nextval('public.tally_voucher_no_seq');
begincreate or replace temporary viewbillrefundsledger as select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, refd.date_of_refund::date as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid from billing.m_credit_note_master crdinner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_idinner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_idinner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_idinner join service.m_service_master srv on srv.service_master_id = bdt.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_idinner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id inner join public.t_company_master cmp on cmp.company_id = bdt.payee_idwhere crd.cr_deu_amount = 0 and billmst.visit_type_id != 1group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund::date, crd.cr_net_amount;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'IP'from billrefundsledger crd where crd.refunddate = dateoftransgroup by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;-------------- Insert credit notes into tally interface end-------------------------------- create view for payee wise detailscreate or replace temporary viewpayeewisedtls as select bdt.payee_id as payeeid, bdt.net_amt as amount, cmp.company_desc as companyname, bdt.organization_id as orgid, bdt.unit_id as unitid, bdt.created_date::date as date,bdt.self_payable as selfpay, bdt.credit_payable as creditpayfrom billing.t_billing_details bdtinner join billing.m_billing_master bm on bm.billing_master_id = bdt.billing_master_idinner join billing.m_credit_note_master crd on crd.bill_id = bm.billing_master_idinner join public.t_company_master cmp on cmp.company_id = bdt.payee_idinner join billing.t_credit_note_detail cnd on cnd.billing_details_id = bdt.billing_details_idwhere bm.visit_type_id != 1 and crd.cr_deu_amount = 0;--- xxx--- insert payee wise details for selfinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', 'IPB', pwd.date, 0, sum(pwd.selfpay), pwd.unitid, pwd.orgid, 'IP'from payeewisedtls pwd where pwd.date = dateoftrans and pwd.payeeid = 1group by pwd.date, pwd.unitid, pwd.orgid;--- xxx--- insert payee wise details for companyinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Payment', pwd.companyname, pwd.date, 0, sum(pwd.creditpay), pwd.unitid, pwd.orgid, 'IP'from payeewisedtls pwd where pwd.date = dateoftrans and pwd.payeeid != 1 group by pwd.companyname, pwd.unitid, pwd.orgid, pwd.date;--- xxx---- data for debit --- insert payee wise details for self for debit sectioninsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextvoucherno, 'Receipt', 'IPB', pwd.date, sum(pwd.selfpay), 0, pwd.unitid, pwd.orgid, 'IP'from payeewisedtls pwd where pwd.date = dateoftrans and pwd.payeeid = 1group by pwd.date, pwd.unitid, pwd.orgid;--- xxx--- insert payee wise details for company for debit sectioninsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextvoucherno, 'Receipt', pwd.companyname, pwd.date, sum(pwd.creditpay), 0, pwd.unitid, pwd.orgid, 'IP'from payeewisedtls pwd where pwd.date = dateoftrans and pwd.payeeid != 1group by pwd.companyname, pwd.unitid, pwd.orgid, pwd.date;--- xxx--- create view for refunds at credit sidecreate or replace temporary viewpayeewiserefunds as select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id != 1 and cnm.cr_deu_amount = 0;--- xxx--- insert cash mode transactions for refundsinsert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextvoucherno, 'Receipt', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'IP'from payeewiserefunds rfdwhere rfd.refunfdate = dateoftrans and rfd.modeid = 1group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions for refunds ----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select nextvoucherno, 'Receipt', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'IP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from payeewiserefunds rfdwhere rfd.refunfdate = dateoftrans and rfd.modeid != 1group by rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;-------------------------xxx---------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postcreditnotes(timestamp);
CREATE OR REPLACE FUNCTION public.postcreditnotes(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begincreate or replace temporary viewcreditnotes as select genl.general_ledger_id ledgerid, genl.general_ledger_name as ledger, crd.cr_net_amount as amount, refd.date_of_refund::date as refunddate, crd.organisation_id as orgid, crd.unit_id as unitid from billing.m_credit_note_master crdinner join billing.t_credit_note_detail crdt on crdt.credit_note_id = crd.credit_note_idinner join billing.t_billing_details bdt on bdt.billing_details_id = crdt.billing_details_idinner join billing.m_billing_master billmst on billmst.billing_master_id = bdt.billing_master_idinner join service.m_service_master srv on srv.service_master_id = bdt.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = srv.speciality_idinner join public.m_general_ledger_master genl on genl.general_ledger_id = spc.general_ledger_idinner join billing.t_payment_refund_master refd on refd.credit_note_id = crd.credit_note_id where crd.cr_deu_amount = 0 and billmst.visit_type_id = 1group by crd.organisation_id, crd.unit_id, genl.general_ledger_id,refd.date_of_refund::date, crd.cr_net_amount;-------------- Insert credit notes into tally interface start----------------------------- insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', crd.ledger, crd.refunddate, sum(crd.amount), 0, crd.unitid, crd.orgid, 'OP'from creditnotes crd where crd.refunddate = dateoftransgroup by crd.ledger, crd.orgid, crd.unitid,crd.refunddate;-------------- Insert credit notes into tally interface end--------------------------------------------------- refund details view --------------------------------------create or replace temporary viewcreditnoterefunds as select prd.payment_mode_id as modeid, pm.payment_mode_desc as mode, prd.amount as amount, prm.credit_note_id as creditnoteid,prm.date_of_refund::date as refunfdate, prd.card_number as cardnumber, prd.cheque_number as chequenumber, prd."date"::date as chequedate,prd.payment_refund_details_id as refunddetailsid, prd.orgnisation_id as orgid, prd.unit_id as unitid,bank.bank_name as banknamefrom billing.t_payment_refund_master prminner join billing.t_payment_refund_details prd on prd.payment_refund_id = prm.payment_refund_idinner join billing.m_credit_note_master cnm on cnm.credit_note_id = prm.credit_note_id inner join billing.m_billing_master billmst on billmst.billing_master_id = cnm.bill_idinner join public.m_payment_mode_master pm on pm.payment_mode_id = prd.payment_mode_idleft join billing.m_bank_master bank on bank.bank_id = prd.bank_idwhere billmst.visit_type_id = 1;-----------------------------xxx--------------------------------------------------------- insert cash mode transactions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, sum(rfd.amount), rfd.unitid, rfd.orgid, 'OP'from creditnoterefunds rfdwhere rfd.refunfdate = dateoftrans and rfd.modeid = 1group by rfd.mode, rfd.unitid, rfd.orgid, rfd.refunfdate;-------------------------xxx----------------------------------------------------------------------- insert other mode transactions ----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Credit Note', rfd.mode, rfd.refunfdate,0, rfd.amount, rfd.unitid, rfd.orgid, rfd.refunddetailsid,rfd.chequedate, 'OP', rfd.bankname, coalesce(rfd.cardnumber,rfd.chequenumber)from creditnoterefunds rfdwhere rfd.refunfdate = dateoftrans and rfd.modeid != 1group by rfd.unitid, rfd.orgid, rfd.refunfdate, rfd.mode, rfd.amount,rfd.refunddetailsid,rfd.chequedate, rfd.bankname, rfd.cardnumber,rfd.chequenumber;-------------------------xxx---------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postdepositdata(timestamp);
CREATE OR REPLACE FUNCTION public.postdepositdata(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin----------- Create view --------------------------create or replace temporary viewdepositas select depdt.payment_mode_id as modeid, pmode.payment_mode_desc as mode, depdt.amount as recamount,dep.deposit_date::date as date ,dep.deposit_master_id as depositid, dep.org_id as orgid, dep.unit_id as unitid,depdt.card_no as cardnumber, depdt.card_type_id as cardtypeid, depdt.cheque_number as chequenumber, depdt.cheque_date as chequedate, bank.bank_name as bankname, depdt.deposit_details_id as depositdetailsidfrom billing.m_deposit_master depinner join billing.t_payment_deposit_details depdton depdt.deposit_id = dep.deposit_master_idinner join public.m_payment_mode_master pmodeon pmode.payment_mode_id = depdt.payment_mode_idleft join billing.m_bank_master bankon bank.bank_id = depdt.bank_id;------------------xxx-------------------------------------------- Insert cash deposits ------------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', dep.mode, dep.date, sum(dep.recamount), 0, dep.unitid, dep.orgid , 'OP'from deposit depwhere dep.modeid = 1 and dep.date = dateoftransgroup by dep.modeid, dep.mode, dep.orgid, dep.unitid, dep.date;-------------------xxx----------------------------------------- Insert other payment mode deposits------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Sales', dep.mode, dep.date, dep.recamount, 0, dep.unitid, dep.orgid, dep.depositdetailsid,coalesce(dep.chequedate,dep.date), 'OP', dep.bankname, coalesce(dep.chequenumber,dep.cardnumber) from deposit depwhere dep.modeid != 1 and dep.date = dateoftrans;------------------------xxx--------------------------------------------------------- Insert Patient advance credit ----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', 'Patient Advance', dep.date , 0, sum(dep.recamount), dep.unitid, dep.orgid, 'OP'from deposit dep where dep.date = dateoftransgroup by dep.date, dep.unitid, dep.orgid;------------------------xxx----------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postdocsharedata(timestamp);
CREATE OR REPLACE FUNCTION public.postdocsharedata(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin ----------- Create view --------------------------------------- Group wise doctor share posting start -------------------------with gen as (select ds.service_id, speMst.speciality_name as ledger, sum(dsvd.processed_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join service.m_service_master sm on sm.service_master_id = ds.service_idinner join doctor.m_speciality_master speMst on speMst.speciality_id = sm.speciality_idwhere log.created_date:: date = dateoftrans group by ds.service_id, speMst.speciality_name, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id)select voucherno, 'General Vouchers', gen.ledger, gen.trans_date, gen.amount, 0, gen.unitid, gen.orgid from gen;------------ Group wise doctor share posting end -------------------------------- Doctor share start ---------------with docshare as (select concat('Dr. ', dm.first_name, ' ', dm.middle_name, ' ', dm.last_name) as ledger, sum(log.paid_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans group by ledger, log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'General Vouchers', docshare.ledger, docshare.trans_date, 0, docshare.amount, docshare.unitid, docshare.orgid, 'Doctor Share' from docshare;------- Doctor share end ---------------------- Retainship amount start ---------------with docretainship as (select sum(log.retainer_ship_amt) as amount, log.created_date:: date as trans_date,log.org_id as orgid, log.org_unit_id as unitidfrom billing.t_doc_share_voucher dsvinner join billing.t_doc_share_voucher_dtls dsvd on dsvd.doc_share_vouche_id = dsv.doc_share_vouche_idinner join billing.t_doctor_share ds on ds.doctor_share_id = dsvd.doctor_share_idinner join billing.t_doc_share_payment_voucher_logger log on log.voucher_no = dsv.voucher_noinner join doctor.m_doctor_master dm on dm.doctor_id = ds.doc_idwhere dsv.created_date:: date = dateoftrans group by log.created_date:: date, log.org_id, log.org_unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'General Vouchers', 'Retainership Fee', docretainship.trans_date, 0, docretainship.amount, docretainship.unitid, docretainship.orgid, 'Doctor Share' from docretainship;------- Retainship amount end ---------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postipbcompcollectiondata(timestamp);
CREATE OR REPLACE FUNCTION public.postipbcompcollectiondata(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin create or replace temporary view ipbillcomp as select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,crm.organisation_id as orgid, crm.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate, crm.company_receipt_date :: date as recieptdate,pReceiptDtls.trans_transaction_date as transferdate, crm.tds_amount as tds, crm.disallowed_amount as disallowedamount, crm.other_deduction as otherdeductionfrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_company_receipt_master crm on crm.receipt_id = pReceiptMst.payment_reciept_idinner join billing.t_company_receipt_detail crd on crd.company_receipt_id = crm.company_receipt_idinner join billing.t_company_invoice_details cid on cid.company_invoice_detail_id = crd.company_receipt_detail_idinner join billing.m_billing_master bill on bill.billing_master_id = cid.bill_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere bill.visit_type_id != 1 and pReceiptMst.payee_id != 1;------- Insert cash start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId , 'IP'from ipbillselfwhere ipbillself.transdate = ipbillself.billdate and ipbillself.modeid = 1 and ipbillself.transdate = dateoftrans--cashgroup by ipbillself.modeid, ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)from ipbillselfwhere ipbillself.transdate= ipbillself.billdate and ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate = dateoftrans;------------------- tds ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'TDS', ipbc.recieptdate, sum(ipbc.tds) , 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- disallowed amount ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Disallowed amount', ipbc.recieptdate, sum(ipbc.disallowedamount) , 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;--------------------------------------------------------------- other deductions ------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Other deductions', ipbc.recieptdate, sum(ipbc.otherdeduction) , 0, ipbc.unitid , ipbc.orgid, 'IP'from ipbillcomp ipbc where ipbc.recieptdate::date = dateoftransgroup by ipbc.orgid, ipbc.unitid , ipbc.recieptdate;---------------------------------------------------------- insert company wise details ---------------------------with company_receipt as (select cm.company_id, cm.company_desc as ledger, crd.created_date::date as dateoftrans, sum(crd.net_receipt_amount) as amount,crd.organisation_id as orgId, crd.unit_id as unitIdfrom billing.t_company_receipt_detail crdinner join billing.t_company_invoice_details cid on cid.company_invoice_id = crd.company_invoice_detail_idleft join billing.m_billing_master bm on bm.billing_master_id = cid.bill_idinner join public.t_company_master cm on cm.company_id = cid.bill_payee_idwhere crd.created_date::date = dateoftrans and bm.visit_type_id !=1group by crd.created_date::date, crd.organisation_id, crd.unit_id, cm.company_id, cm.company_desc)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', cr.ledger, cr.dateoftrans, 0, cr.amount, cr.unitId, cr.orgId, 'IP' from company_receipt cr;---------------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postipbselfcollectiondata(timestamp);
CREATE OR REPLACE FUNCTION public.postipbselfcollectiondata(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
begin create or replace temporary view ipbillselfAS(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid, billMst.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate, billMst.bill_date_time :: date as billdate,pReceiptDtls.trans_transaction_date as transferdatefrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_id inner join opd.t_patient_sponsor_details spd on spd.admission_id=billMst.admission_idwhere billMst.visit_type_id = 2 and spd.payment_entitlement_id = 1 );
------- Insert cash start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, sum(ipbillself.rcptamount), 0 , ipbillself.unitId, ipbillself.orgId, 'IP' from ipbillselfwhere ipbillself.transdate = ipbillself.billdate and ipbillself.transdate = dateoftrans--cashgroup by ipbillself.modeid, ipbillself.transdate, ipbillself.orgid,ipbillself.unitid,ipbillself.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------/*insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Receipt', ipbillself.mode, ipbillself.transdate, ipbillself.rcptamount, 0 , ipbillself.unitId, ipbillself.orgId, ipbillself.paymentreceiptdetailId,coalesce(ipbillself.chequedate,ipbillself.transferdate), 'IP', ipbillself.bankname, coalesce(ipbillself.chequenumber,ipbillself.cardnumber,ipbillself.transactionno)from ipbillselfwhere ipbillself.transdate= ipbillself.billdate and ipbillself.modeid &lt;&gt; 1 and ipbillself.transdate = dateoftrans;*/------------------------------Package consumption ---------------------------------with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date::date as createdDatefrom billing.t_billing_details dtls inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = dtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere dtls.created_date::date = dateoftrans and self_payable = 0 and credit_payable = 0 and bill.visit_type_id = 2group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date::date, bill.organisation_id, bill.unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'IP' from pack;---------------------------------------------------------------------- Insert deposit consumption --------------------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Patient Advance', pdc.created_date::date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id, 'IP'from billing.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pdon pd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master billon bill.billing_master_id = pd.bill_idwhere pdc.created_date::date = dateoftrans and bill.visit_type_id = 2group by pdc.dep_consumption_id, pdc.organization_id, pdc.unit_id,pdc.created_date::date;-------------------- Discount --------------------------with gen as (select sum(billDtls.discount) as amount,billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 2group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id having sum(billDtls.discount) &gt; 0)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId, 'IP' from gen;--------------------------- IPBR CREDIT POSTING START --------------------------------------- CALCULATED SUM OF CASH RECEIVED, DEPOSITE CONSUMED, DISCOUNNT GIVEN, PACKAGE CONSUMPTION --------------create or replace temporary view IPBREVERSEas(select sum(ipbillself.rcptamount) as amount, ipbillself.unitId, ipbillself.orgId , ipbillself.transdate as transdatefrom ipbillselfwhere ipbillself.transdate= ipbillself.billdate group by ipbillself.unitId, ipbillself.orgId, ipbillself.transdate)union(select sum(pdc.consumed_amount) as amount, pdc.unit_id, pdc.organization_id, pdc.created_date::date as transdatefrom billing.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pd on pd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master bill on bill.billing_master_id = pd.bill_idwhere bill.visit_type_id = 2group by pdc.dep_consumption_id, pdc.organization_id, pdc.unit_id,pdc.created_date::date)union(select sum(billDtls.discount) as amount, billMst.unit_id as unitId, billMst.organisation_id as orgId, billDtls.created_date::date as transdatefrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idwhere billMst.visit_type_id = 2group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)union(select sum(dtls.gross_amount) as amount , bill.unit_id as unitId, bill.organisation_id as orgId, dtls.created_date::date as transdatefrom billing.t_billing_details dtls inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_idwhere self_payable = 0 and credit_payable = 0 and bill.visit_type_id = 2group by bill.organisation_id, bill.unit_id, dtls.created_date::date);
insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Receipt', 'IPB', ipbr.transdate, 0, sum(ipbr.amount), ipbr.unitId, ipbr.orgId , 'IP'from IPBREVERSE ipbr where ipbr.transdate = dateoftransgroup by unitid, orgid, ipbr.transdate;--------------------------- IPBR CREDIT POSTING END -------------------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postipcompservledger(timestamp);
CREATE OR REPLACE FUNCTION public.postipcompservledger(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare salesvoucherno integer = nextval('public.tally_voucher_no_seq');
begin create or replace temporary view compipservas select bm.admission_id,bd.payee_id as payeeid,spd.payment_entitlement_id, bd.net_amt as amount, bd.service_id as serviceid,bm.bill_date_time::date as billdate, gn.general_ledger_name as generalledger,gn.general_ledger_id as generalledgerid, bd.organization_id as orgid, bd.unit_id as unitid,cmp.company_desc as companyfrom billing.t_billing_details bdinner join billing.m_billing_master bm on bm.billing_master_id = bd.billing_master_idinner join opd.t_patient_sponsor_details spd on spd.admission_id=bm.admission_id inner join service.m_service_master srv on srv.service_master_id = bd.service_idinner join public.m_general_ledger_master gn on gn.general_ledger_id = srv.general_ledger_idinner join public.t_company_master cmp on cmp.company_id = bd.payee_idwhere bm.visit_type_id = 2 and spd.payment_entitlement_id!=1and spd.payee_id=bd.payee_id;---------- company bill amount -----------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select salesvoucherno, 'Sales', cip.company, cip.billdate, sum(cip.amount), 0 , cip.unitid, cip.orgid, 'IP'from compipserv cipwhere cip.billdate = dateoftransgroup by cip.billdate, cip.unitid, cip.orgid, cip.company ;----------- xxx ------------------------------- inser ip bill service wise ledger data -------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select salesvoucherno, 'Sales', cip.generalledger, cip.billdate, 0, sum(cip.amount) , cip.unitid, cip.orgid , 'IP'from compipserv cipwhere cip.billdate = dateoftrans group by cip.billdate, cip.unitid, cip.orgid, cip.generalledger ;--------------xxx-----------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postipselfservledger(timestamp);
CREATE OR REPLACE FUNCTION public.postipselfservledger(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare salesvoucherno integer = nextval('public.tally_voucher_no_seq');
begin create or replace temporary view selfipservas select bm.admission_id,bd.payee_id as payeeid,spd.payment_entitlement_id, bd.net_amt as amount, bd.service_id as serviceid,bm.bill_date_time::date as billdate, gn.general_ledger_name as generalledger,gn.general_ledger_id as generalledgerid, bd.organization_id as orgid, bd.unit_id as unitid,cmp.company_desc as companyfrom billing.t_billing_details bdinner join billing.m_billing_master bm on bm.billing_master_id = bd.billing_master_idinner join opd.t_patient_sponsor_details spd on spd.admission_id=bm.admission_id inner join service.m_service_master srv on srv.service_master_id = bd.service_idinner join public.m_general_ledger_master gn on gn.general_ledger_id = srv.general_ledger_idinner join public.t_company_master cmp on cmp.company_id = bd.payee_idwhere bm.visit_type_id = 2 and spd.payment_entitlement_id=1and spd.payee_id=bd.payee_id;------ insert ip bill total service amount grouped ------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select salesvoucherno, 'Sales', 'IPB', sip.billdate, sum(sip.amount), 0 , sip.unitid, sip.orgid, 'IP' from selfipserv sipwhere sip.billdate = dateoftrans and sip.payeeid = 1group by sip.billdate, sip.unitid, sip.orgid ;--------------xxx----------------------------------- inser ip bill service wise ledger data -------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select salesvoucherno, 'Sales', sip.generalledger, sip.billdate, 0, sum(sip.amount) , sip.unitid, sip.orgid, 'IP'from selfipserv sipwhere sip.billdate = dateoftrans and sip.payeeid = 1group by sip.billdate, sip.unitid, sip.orgid, sip.generalledger ;--------------xxx-----------------------------return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.postopfadata(timestamp);
CREATE OR REPLACE FUNCTION public.postopfadata(dateoftrans timestamp without time zone)RETURNS booleanLANGUAGE plpgsqlAS $function$declare voucherno integer = nextval('public.tally_voucher_no_seq');
declare nextVoucherno integer = nextval('public.tally_voucher_no_seq');
begin ----------- Create view ---------------------------create or replace temporary view opbillAS(select pMode.payment_mode_id as modeid, pMode.payment_mode_desc as mode, pReceiptDtls.amount as rcptamount, billMst.outstanding as outstanding, billMst.net_amount as billnetamount, bank.bank_name as bankname, pReceiptDtls.card_number as cardnumber, pReceiptDtls.card_type_id as cardtypeid, pReceiptDtls.check_number as chequenumber, pReceiptDtls.cheque_date::date as chequedate, pReceiptDtls.transaction_no as transactionno, pReceiptDtls.payment_reciept_details_id as paymentreceiptdetailId,billMst.organisation_id as orgid, billMst.unit_id as unitid,pReceiptDtls.date_of_transaction :: date as transdate, billMst.bill_date_time :: date as billdate,pReceiptDtls.trans_transaction_date as transferdatefrom billing.t_payment_reciept_details pReceiptDtlsinner join public.m_payment_mode_master pMode on pMode.payment_mode_id = pReceiptDtls.payment_mode_idinner join billing.t_payment_reciept_master pReceiptMst on pReceiptMst.payment_reciept_id = pReceiptDtls.payment_receipt_master_id inner join billing.m_billing_master billMst on pReceiptMst.billing_master_id = billMst.billing_master_idleft join billing.m_bank_master bank on bank.bank_id = pReceiptDtls.bank_idwhere billMst.visit_type_id = 1);
------- Insert cash start ---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId , 'OP'from opbillwhere opbill.transdate = opbill.billdate and opbill.modeid = 1 and opbill.transdate = dateoftrans--cashgroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;------- Insert cash end ---------------------- Insert others start where transaction-date = bill-date---------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select voucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)from opbillwhere opbill.transdate= opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate = dateoftrans;------- Insert others start------------------------------------- Company amount --------------------------------with comp as (select billDtls.payee_id as ledgerId, comp.company_desc as ledger, sum(billDtls.credit_payable) as amount,billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join public.t_company_master comp on comp.company_id = billDtls.payee_id where billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 1 and billDtls.payee_id &lt;&gt; 1group by billDtls.payee_id,comp.company_desc, billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales',comp.ledger, comp.transactionDate, comp.amount, 0, comp.unitId, comp.orgId,'OP' from comp;------------------------------Package consumption ---------------------------------with pack as (select genLedMst.general_ledger_id, genLedMst.general_ledger_name as ledger, sum(dtls.gross_amount) as amount , bill.organisation_id as orgId, bill.unit_id as unitId, dtls.created_date::date as createdDatefrom billing.t_billing_details dtls inner join billing.m_billing_master bill on bill.billing_master_id = dtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = dtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.t_order_details ordt on ordt.order_details_id = dtls.order_details_idwhere dtls.created_date::date = dateoftrans and bill.visit_type_id = 1 and ordt.is_package_service = 'Y'group by genLedMSt.general_ledger_id,genLedMst.general_ledger_name, dtls.created_date::date, bill.organisation_id, bill.unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales',pack.ledger, pack.createdDate, pack.amount, 0, pack.unitId, pack.orgId, 'OP' from pack;---------------------------------------------------------------------- Insert deposit consumption --------------------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', 'Patient Advance', pdc.created_date::date, sum(pdc.consumed_amount), 0, pdc.unit_id, pdc.organization_id,'OP'from billing.t_payment_deposite_consumption_details pdcinner join billing.t_payment_deposite_consumption pdon pd.dep_consumption_id = pdc.dep_consumption_idinner join billing.m_billing_master billon bill.billing_master_id = pd.bill_idwhere pdc.created_date::date = dateoftrans and bill.visit_type_id = 1group by pdc.organization_id, pdc.unit_id,pdc.created_date::date;-------------------xxx-------------------------------------------- Insert outstanding start---------------with outst as (select sum(bill.net_amount) as amount, coalesce(sum(bill.outstanding),0) as outstanding, bill.organisation_id as orgId, bill.unit_id as unitId, bill.bill_date_time::date as billDatefrom billing.m_billing_master billwhere bill.bill_date_time::date = dateoftrans and bill.visit_type_id = 1group by bill.organisation_id, bill.unit_id, bill.bill_date_time::date),cred as (select coalesce(sum (billdt.credit_payable),0) as creditPayable, billdt.organization_id as orgId, billdt.unit_id as unitIdfrom billing.t_billing_details billdt inner join billing.m_billing_master billon bill.billing_master_id = billdt.billing_master_idwhere bill.bill_date_time::date = dateoftrans and bill.visit_type_id = 1group by billdt.organization_id, billdt.unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales','Patient Credit', outst.billDate, outst.outstanding - cred.creditpayable, 0, outst.unitId, outst.orgId, 'OP' from outst , credwhere (outst.outstanding - cred.creditpayable) &gt; 0;------- Insert outstanding end----------------------------------- Discount --------------------------with gen as (select sum(billDtls.discount) as amount,billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date::date = dateOfTrans and billMst.visit_type_id = 1group by billDtls.created_date::date, billMst.organisation_id, billMst.unit_id having sum(billDtls.discount) &gt; 0)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', 'Discount', gen.transactionDate, gen.amount, 0, gen.unitId, gen.orgId,'OP' from gen;------------------------------------------------------------ Ledger start -------------------------with gen as (select genLedMSt.general_ledger_id as ledgerId, genLedMSt.general_ledger_name as ledger, sum(billDtls.gross_amount) as amount,billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idwhere billDtls.created_date::date = dateoftrans and billMst.visit_type_id = 1group by genLedMSt.general_ledger_id, billDtls.created_date::date, billMst.organisation_id, billMst.unit_id)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,tran_type)select voucherno, 'Sales', gen.ledger, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId,'OP' from gen;------------ Ledger end --------------------------------------------- Tax ---------------------------with gen as (select billDtls.tax_id, tax."name" as taxname, sum(billDtls.tax_amount) as amount,billDtls.created_date::date as transactionDate, billMst.organisation_id as orgId, billMst.unit_id as unitIdfrom billing.t_billing_details billDtlsinner join billing.m_billing_master billMst on billMst.billing_master_id = billDtls.billing_master_idinner join service.m_service_master servMst on servMst.service_master_id = billDtls.service_idinner join doctor.m_speciality_master spc on spc.speciality_id = servMst.speciality_idinner join public.m_general_ledger_master genLedMst on genLedMst.general_ledger_id = spc.general_ledger_idinner join public.m_tax tax on tax.id = billDtls.tax_idwhere billDtls.created_date::date = dateOfTrans and billMst.visit_type_id = 1group by billDtls.tax_id, tax."name", billDtls.created_date::date, billMst.organisation_id, billMst.unit_idhaving sum(billDtls.tax_amount) &gt; 0)insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select voucherno, 'Sales', gen.taxname, gen.transactionDate, 0, gen.amount, gen.unitId, gen.orgId, 'OP' from gen;------------------------------------------------------------------------Previous date settlement start cash-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, sum(opbill.rcptamount), 0 , opbill.unitId, opbill.orgId, 'OP' from opbillwhere opbill.transdate != opbill.billdate and opbill.modeid = 1 and opbill.transdate = dateoftrans--cashgroup by opbill.modeid, opbill.transdate, opbill.orgid,opbill.unitid,opbill.mode;--------------------------------------------------Previous date settlement start others-----------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id,unique_number,instrument_date,tran_type,bank_name,instrument_number)select nextVoucherno, 'Sales', opbill.mode, opbill.transdate, opbill.rcptamount, 0 , opbill.unitId, opbill.orgId, opbill.paymentreceiptdetailId,coalesce(opbill.chequedate,opbill.transferdate), 'OP', opbill.bankname, coalesce(opbill.chequenumber,opbill.cardnumber,opbill.transactionno)from opbillwhere opbill.transdate != opbill.billdate and opbill.modeid &lt;&gt; 1 and opbill.transdate = dateoftrans;--------------------------------------------------------------Credit insert start--------------------------insert into public.t_tally_interface(voucher_no, voucher_type, ledger, voucher_date,debit_amount, credit_amount, unit_id, hospital_id, tran_type)select nextVoucherno, 'Sales', 'Patient Credit', opbill.transdate, 0, sum(opbill.rcptamount), opbill.unitid, opbill.orgid, 'OP'from opbill where opbill.transdate = dateoftrans and opbill.transdate != opbill.billdategroup by opbill.transdate, opbill.unitid, opbill.orgid; return true;EXCEPTION when OTHERS then return false;COMMIT;end;$function$;

-- DROP FUNCTION public.reset_balance_amount_proc();
CREATE OR REPLACE FUNCTION public.reset_balance_amount_proc()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF NEW.balance_amount &gt; NEW.authorized_amount thenupdate billing.m_preauth_master set balance_amount = authorized_amount where preauth_id=NEW.preauth_id;END IF;RETURN NEW;END;$function$;

-- DROP PROCEDURE public.servicemasterproc(in varchar, in varchar, in varchar, in varchar, in varchar, in varchar, in varchar, in numeric, in varchar, in varchar, inout varchar);
CREATE OR REPLACE PROCEDURE public.servicemasterproc(IN orgname character varying, IN unitname character varying, IN deptname character varying, IN subdeptname character varying, IN ledgername character varying, IN servicecode character varying, IN servicename character varying, IN servicebaseprice numeric, IN validfrom character varying, IN validtill character varying, INOUT msg character varying)LANGUAGE plpgsqlAS $procedure$declareorgId integer:=null;unitId integer:=null;deptId integer:=null;subDeptId integer:=null;ledgerId integer:=null;serviceId integer:=null;validFrm timestamp:=null;validTo timestamp:=null;isExist BOOLEAN;begin--if valid from and validTill param is varchar then conversion will be validFrm=TO_TIMESTAMP(concat(validFrom,' 00:00:00'), 'YYYY-MM-DD');
validTo=TO_TIMESTAMP(concat(validTill,' 00:00:00'), 'YYYY-MM-DD');
isExist :=checkServiceExistCall1(serviceName);
--dbms_output.put_line(isExist);
msg:=concat('service already exist','',serviceName,cast(isExist as varchar));
return;if isExist=TRUE thenmsg:='service already exist';return;end if;with getOrgId as (select organization_id from m_organization_master mom where lower(mom.organization_name) = lower(orgName) )select organization_id into orgId from getOrgId;if orgId is null thenmsg:='org not exist';return;end if;with getUnitIdByName as (select unit_id from public.m_unit_master um where lower(um.unit_name) = lower(unitName) and um.organization_id=orgId )select unit_id into unitId from getUnitIdByName;with getDeptIdByName as (select speciality_id from doctor.m_speciality_master smwhere sm.organization_id=orgId and lower(sm.speciality_name) = lower(deptName))select speciality_id into deptId from getDeptIdByName;with getSubDeptIdByName as (select sub_speciality_id from doctor.m_sub_speciality_master subsmwhere subsm.organization_id=orgId and lower(subsm.sub_speciality_name) = lower(subDeptName))select sub_speciality_id into subDeptId from getSubDeptIdByName;with getLedgerIdByName as (select general_ledger_id from public.m_general_ledger_master glmwhere glm.organisation_id =orgId and lower(glm.general_ledger_name) = lower(ledgerName))select general_ledger_id into ledgerId from getLedgerIdByName;----- service master save with servicesave as (insert into service.m_service_master (organization_id,service_standard_code,service_standard_name,is_available_for_package,is_outsource_service,is_ot_procedure,is_order_set,is_rate_editable,min_rate_editable,max_rate_editable,is_discount_applicable,is_allow_multiple_quantity,is_doctor_required,is_tax_applicable,is_autorendered,created_by,created_date,status,updated_by,updated_date,speciality_id,sub_speciality_id,is_required_schedule,is_on_bed,valid_from,valid_till,general_ledger_id)values(orgId,serviceCode,serviceName,'I','I','I','I','I',0,0,'I','I','I','I','I',1,now(),'A',1,now(),deptId,subDeptId,'N','N',now(),now(),ledgerId) returning service_master_id)select service_master_id into serviceId from servicesave;---- service unit mapping insert into service.t_unit_service_mapper(service_id,unit_id,orgnisation_id,status,created_by,created_date,updated_by,updated_date) values(serviceId,unitId,orgId,'A',1,now(),1,now());
------------unit service master detailinsert into service.t_unit_service_master_details(service_master_id ,is_outsource,is_package ,is_rate_editable,rate_editble_min_value ,rate_editable_max_value,is_tax_applicable ,is_ref_doctor_share,is_discount,unit_id,organization_id ,status ,created_by ,created_date ,updated_by ,updated_date ,discount_value ,is_panel,is_allow_multiple_quantity ,is_procedure,is_doc_req ,is_bed_side ,is_poc ,is_periodicity ,is_auto_render ,is_appointable,gender,review_time) values(serviceId,'N','I','N',0,0,'N','N','N',unitId,orgId,'A',1,now(),1,now(),0,'N','N','N','N','N','N','N','N','N',0,0);
-------service base priceinsert into service.m_service_base_price_master (service_master_id,visit_type_id,base_price,from_date,to_date ,status,unit_id,organisation_id,created_by,created_date,updated_by,updated_date)values(serviceId,1,serviceBasePrice,validFrm,validTo,'A',unitId,orgId,1,now(),1,now());
-- 500,now(),now(),'A',unitId,orgId,1,now(),1,now());
msg:=concat('Inserted Successfully');
end ;$procedure$;-- DROP FUNCTION public.skeys(hstore);
CREATE OR REPLACE FUNCTION public.skeys(hstore)RETURNS SETOF textLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_skeys$function$;

-- DROP FUNCTION public.slice(hstore, _text);
CREATE OR REPLACE FUNCTION public.slice(hstore, text[])RETURNS hstoreLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_slice_to_hstore$function$;

