CREATE OR REPLACE FUNCTION public.slice_array(hstore, text[])RETURNS text[]LANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_slice_to_array$function$;

-- DROP FUNCTION public.svals(hstore);
CREATE OR REPLACE FUNCTION public.svals(hstore)RETURNS SETOF textLANGUAGE cIMMUTABLE PARALLEL SAFE STRICTAS '$libdir/hstore', $function$hstore_svals$function$;

-- DROP FUNCTION public.t_generate_prefix_number(int4, int4, int4);
CREATE OR REPLACE FUNCTION public.t_generate_prefix_number(p_store_id integer, p_unit_id integer, p_screen_id integer)RETURNS TABLE(new_running_number character varying)LANGUAGE plpgsqlAS $function$DECLARE p_running_number INTEGER;p_current_running_number INTEGER;p_reset_id INTEGER;p_length INTEGER;p_format_id INTEGER;p_generated_code VARCHAR;p_new_running_number VARCHAR;p_prefix_running_id INTEGER;p_prefix_id INTEGER;p_store_code VARCHAR;p_unit_code VARCHAR;p_organization_id INTEGER;BEGINSELECT id, prn.running_number, prn.reset_id, prn.length, prn.format_id, prn.generated_code, prn.organization_idINTO p_prefix_id, p_running_number, p_reset_id, p_length, p_format_id, p_generated_code, p_organization_idFROM public.m_prefix_configuration AS prn WHERE prn.screen_id = p_screen_id AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id LIMIT 1;IF p_prefix_id IS NOT NULL AND p_prefix_id&gt;0 thenSELECT id, current_running INTO p_prefix_running_id, p_current_running_numberFROM public.t_prefix_running_number AS prn WHERE (prn.store_id=p_store_id or p_store_id = 0 ) AND prn.screen_id = p_screen_id AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id LIMIT 1;IF p_prefix_running_id IS NOT NULL AND p_prefix_running_id&gt;0 THENIF p_current_running_number IS NOT NULL AND p_current_running_number&gt;0 THENp_running_number := p_current_running_number + 1 ;END IF;UPDATE public.t_prefix_running_numberSET current_running=p_running_numberWHERE id=p_prefix_running_id;ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id&lt;1) AND p_running_number&gt;0 THEN if (p_store_id &gt; 0) then INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
elseINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
END IF;ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id&lt;1) THENp_running_number := 1;if (p_store_id &gt; 0) thenINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
elseINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
END IF;END IF;SELECT m_store.store_code INTO p_store_codeFROM public.m_storeWHERE (m_store.store_id = p_store_id or p_store_id = 0 )AND m_store.unit_id=p_unit_id;if p_store_code IS NULL THENselect 'AB' INTO p_store_code;end if;SELECT m_unit_master.unit_code INTO p_unit_codeFROM public.m_unit_masterWHERE m_unit_master.unit_id=p_unit_id;SELECT REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (p_generated_code, '[YY]', to_char(CURRENT_TIMESTAMP, 'YY')), '[YYYY]', to_char(CURRENT_TIMESTAMP, 'YYYY')), '[MM]', to_char(CURRENT_TIMESTAMP, 'MM')),'[MMM]', to_char(CURRENT_TIMESTAMP, 'FMMON')),'[MMMM]', to_char(CURRENT_TIMESTAMP, 'FMMONTH')),'[DD]', to_char(CURRENT_TIMESTAMP, 'DD')),'[/]', '/'),'[-]', '-'),'[SF]', p_running_number::VARCHAR),'[UC]', p_unit_code),'[SC]', p_store_code),'|', ''),'}', ''), '{', '')INTO p_new_running_number;ELSE IF p_screen_id = 1 THENp_new_running_number := 'WLS-001';ELSIF p_screen_id = 16 THENp_new_running_number := 'SR-001';ELSIF p_screen_id = 30 THENp_new_running_number := 'PI-001';ELSIF p_screen_id = 32 THENp_new_running_number := 'REJ-001';ELSIF p_screen_id = 33 THENp_new_running_number := 'REJ-001';ELSIF p_screen_id = 27 THENp_new_running_number := 'PATIND-001';ELSIF p_screen_id = 28 THENp_new_running_number := 'BC-001';ELSIF p_screen_id = 64 THENp_new_running_number := 'RBC-001';ELSIF p_screen_id = 68 THENp_new_running_number := 'CCR-001';ELSIF p_screen_id = 17 THENp_new_running_number := 'IR-001';ELSIF p_screen_id = 4 THENp_new_running_number := 'PR-001';ELSIF p_screen_id = 5 THENp_new_running_number := 'LPR-001';ELSIF p_screen_id = 10 THENp_new_running_number := 'POC-001';ELSIF p_screen_id = 12 THENp_new_running_number := 'GRN-001';ELSIF p_screen_id = 37 THENp_new_running_number := 'QE-001';ELSIF p_screen_id = 38 THENp_new_running_number := 'ESTV-001';ELSIF p_screen_id = 92 THENp_new_running_number := 'WOR-001';ELSIF p_screen_id = 97 THENp_new_running_number := 'WOQR-001';ELSIF p_screen_id = 98 THENp_new_running_number := 'WOQSV-001';ELSIF p_screen_id = 92 THENp_new_running_number := 'WOC-001';ELSIF p_screen_id = 73 THENp_new_running_number := 'LI-001';ELSIF p_screen_id = 74 THENp_new_running_number := 'LIO-001';ELSIF p_screen_id = 75 THENp_new_running_number := 'LO-001';ELSIF p_screen_id = 79 THENp_new_running_number := 'LOR-001';ELSIF p_screen_id = 54 THENp_new_running_number := 'PIR-001';ELSIF p_screen_id = 120 THENp_new_running_number := 'ConInw-001';ELSIF p_screen_id = 122 THENp_new_running_number := 'ImpInd-001';ELSIF p_screen_id = 129 THENp_new_running_number := 'ImpRet-001';ELSIF p_screen_id = 132 THENp_new_running_number := 'PR-001';ELSIF p_screen_id = 66 THENp_new_running_number := 'INW-001';ELSIF p_screen_id = 77 THENp_new_running_number := 'DR-001';ELSIF p_screen_id = 137 THENp_new_running_number := 'OPB-001';END IF;END IF;RETURN QUERY SELECT p_new_running_number AS new_running_number;END;$function$;

-- DROP FUNCTION public.t_generate_prefix_number_2(int4, int4, int4);
CREATE OR REPLACE FUNCTION public.t_generate_prefix_number_2(p_store_id integer, p_unit_id integer, p_screen_id integer)RETURNS TABLE(new_running_number character varying)LANGUAGE plpgsqlAS $function$DECLARE p_running_number INTEGER;p_current_running_number INTEGER;p_reset_id INTEGER;p_length INTEGER;p_format_id INTEGER;p_generated_code VARCHAR;p_new_running_number VARCHAR;p_prefix_running_id INTEGER;p_prefix_id INTEGER;p_store_code VARCHAR;p_unit_code VARCHAR;p_organization_id INTEGER;BEGINSELECT id, prn.running_number, prn.reset_id, prn.length, prn.format_id, prn.generated_code, prn.organization_idINTO p_prefix_id, p_running_number, p_reset_id, p_length, p_format_id, p_generated_code, p_organization_idFROM public.m_prefix_configuration AS prn WHERE prn.screen_id = p_screen_id AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id LIMIT 1;IF p_prefix_id IS NOT NULL AND p_prefix_id&gt;0 thenSELECT id, current_running INTO p_prefix_running_id, p_current_running_numberFROM public.t_prefix_running_number AS prn WHERE (prn.store_id=p_store_id or p_store_id = 0 ) AND prn.screen_id = p_screen_id AND prn.is_active = true AND prn.is_deleted = false AND prn.unit_id = p_unit_id LIMIT 1;IF p_prefix_running_id IS NOT NULL AND p_prefix_running_id&gt;0 THENIF p_current_running_number IS NOT NULL AND p_current_running_number&gt;0 THENp_running_number := p_current_running_number + 1 ;END IF;UPDATE public.t_prefix_running_numberSET current_running=p_running_numberWHERE id=p_prefix_running_id;ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id&lt;1) AND p_running_number&gt;0 THEN if (p_store_id &gt; 0) then INSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
elseINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
END IF;ELSIF (p_prefix_running_id IS NULL OR p_prefix_running_id&lt;1) THENp_running_number := 1;if (p_store_id &gt; 0) thenINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, store_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_store_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
elseINSERT INTO public.t_prefix_running_number(organization_id, unit_id, screen_id, current_running, is_active, updated_by, updated_date, added_by, added_date, is_deleted)VALUES (p_organization_id, p_unit_id, p_screen_id, p_running_number, true, 1, CURRENT_TIMESTAMP,1, CURRENT_TIMESTAMP, false);
END IF;END IF;SELECT m_store.store_code INTO p_store_codeFROM public.m_storeWHERE (m_store.store_id = p_store_id or p_store_id = 0 )AND m_store.unit_id=p_unit_id;if p_store_code IS NULL THENselect 'AB' INTO p_store_code;end if;SELECT m_unit_master.unit_code INTO p_unit_codeFROM public.m_unit_masterWHERE m_unit_master.unit_id=p_unit_id;SELECT REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (REPLACE (p_generated_code, '[YY]', to_char(CURRENT_TIMESTAMP, 'YY')), '[YYYY]', to_char(CURRENT_TIMESTAMP, 'YYYY')), '[MM]', to_char(CURRENT_TIMESTAMP, 'MM')),'[MMM]', to_char(CURRENT_TIMESTAMP, 'FMMON')),'[MMMM]', to_char(CURRENT_TIMESTAMP, 'FMMONTH')),'[DD]', to_char(CURRENT_TIMESTAMP, 'DD')),'[/]', '/'),'[-]', '-'),'[SF]', p_running_number::VARCHAR),'[UC]', p_unit_code),'[SC]', p_store_code),'|', ''),'}', ''), '{', '')INTO p_new_running_number;ELSE IF p_screen_id = 1 THENp_new_running_number := 'WLS-001';ELSIF p_screen_id = 2 THENp_new_running_number := 'ST-IND-001';ELSIF p_screen_id = 16 THENp_new_running_number := 'SR-001';ELSIF p_screen_id = 30 THENp_new_running_number := 'PI-001';ELSIF p_screen_id = 32 THENp_new_running_number := 'REJ-001';ELSIF p_screen_id = 33 THENp_new_running_number := 'REJ-001';ELSIF p_screen_id = 27 THENp_new_running_number := 'PATIND-001';ELSIF p_screen_id = 28 THENp_new_running_number := 'BC-001';ELSIF p_screen_id = 64 THENp_new_running_number := 'RBC-001';ELSIF p_screen_id = 68 THENp_new_running_number := 'CCR-001';ELSIF p_screen_id = 17 THENp_new_running_number := 'IR-001';ELSIF p_screen_id = 4 THENp_new_running_number := 'PR-001';ELSIF p_screen_id = 5 THENp_new_running_number := 'LPR-001';ELSIF p_screen_id = 10 THENp_new_running_number := 'POC-001';ELSIF p_screen_id = 12 THENp_new_running_number := 'GRN-001';ELSIF p_screen_id = 37 THENp_new_running_number := 'QE-001';ELSIF p_screen_id = 38 THENp_new_running_number := 'ESTV-001';ELSIF p_screen_id = 92 THENp_new_running_number := 'WOR-001';ELSIF p_screen_id = 97 THENp_new_running_number := 'WOQR-001';ELSIF p_screen_id = 98 THENp_new_running_number := 'WOQSV-001';ELSIF p_screen_id = 92 THENp_new_running_number := 'WOC-001';ELSIF p_screen_id = 73 THENp_new_running_number := 'LI-001';ELSIF p_screen_id = 74 THENp_new_running_number := 'LIO-001';ELSIF p_screen_id = 75 THENp_new_running_number := 'LO-001';ELSIF p_screen_id = 79 THENp_new_running_number := 'LOR-001';ELSIF p_screen_id = 54 THENp_new_running_number := 'PIR-001';ELSIF p_screen_id = 120 THENp_new_running_number := 'ConInw-001';ELSIF p_screen_id = 122 THENp_new_running_number := 'ImpInd-001';ELSIF p_screen_id = 129 THENp_new_running_number := 'ImpRet-001';ELSIF p_screen_id = 132 THENp_new_running_number := 'PR-001';ELSIF p_screen_id = 66 THENp_new_running_number := 'INW-001';ELSIF p_screen_id = 77 THENp_new_running_number := 'DR-001';ELSIF p_screen_id = 137 THENp_new_running_number := 'OPB-001';END IF;END IF;RETURN QUERY SELECT p_new_running_number AS new_running_number;END;$function$;

-- DROP FUNCTION public.t_order_master_visit_type_id_update();
CREATE OR REPLACE FUNCTION public.t_order_master_visit_type_id_update()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif(selectta.admission_idfromadt.t_admission tainner join t_order_master tomontom.admission_id = ta.admission_idwheretom.visit_type_id &lt;&gt; ta.visit_type_idlimit 1 ) &gt; 0thenupdatet_order_master tomsetvisit_type_id = A.visit_type_idfrom(selectta.admission_id ,ta.visit_type_idfromadt.t_admission tainner join t_order_master tomontom.admission_id = ta.admission_idwheretom.visit_type_id &lt;&gt; ta.visit_type_id) AwhereA.admission_id = tom.admission_id ;end if ;return new;end;$function$;

