CREATE OR REPLACE FUNCTION public.t_unit_service_master_details_function()RETURNS triggerLANGUAGE plpgsqlAS $function$beginIF( NEW.is_tax_applicable &lt;&gt; old.is_tax_applicable ORnew.is_discount&lt;&gt;old.is_discount ORnew.is_rate_editable&lt;&gt;old.is_rate_editable ORnew.discount_value&lt;&gt;old.discount_value ornew.is_doc_req&lt;&gt;old.is_doc_req ornew.is_ref_doctor_share&lt;&gt;old.is_ref_doctor_share ornew.is_allow_multiple_quantity&lt;&gt;old.is_allow_multiple_quantity)THENINSERT INTO t_unit_service_master_details_audit(unit_service_master_details_id ,service_master_id ,is_outsource,is_package ,is_rate_editable ,rate_editble_min_value ,rate_editable_max_value ,is_tax_applicable ,is_ref_doctor_share ,is_discount,gst_type_id ,otc_gst_type_id ,unit_id ,organization_id ,status,created_date,created_by ,updated_date ,updated_by ,discount_value,is_panel ,ord_doc_spl_id,is_allow_multiple_quantity,is_procedure ,is_doc_req ,is_bed_side ,is_poc,is_periodicity ,is_auto_render ,is_appointable ,gender ,ref_share_amt,procedure_type_id,is_pacs_req ,ref_share_per ,is_review_applicable ,review_time ,bill_of_material,product_category_id,bed_category_id ,doc_ref_per ,is_cyclic ,sample_collection ,surgery_grade_id ,is_doc_share_per_wise ,is_ref_share_per_wise ,lab_auto_mail_exclusion ,is_outsource_job ,pre_requisite ,pre_requisite_details ,edit_time )VALUES (old.unit_service_master_details_id ,old.service_master_id ,old.is_outsource ,old.is_package,old.is_rate_editable,old.rate_editble_min_value ,old.rate_editable_max_value,old.is_tax_applicable ,old.is_ref_doctor_share ,old.is_discount ,old.gst_type_id ,old.otc_gst_type_id,old.unit_id ,old.organization_id,old.status,old.created_date ,old.created_by,old.updated_date ,old.updated_by ,old.discount_value,old.is_panel ,old.ord_doc_spl_id ,old.is_allow_multiple_quantity ,old.is_procedure ,old.is_doc_req ,old.is_bed_side ,old.is_poc ,old.is_periodicity ,old.is_auto_render ,old.is_appointable ,old.gender ,old.ref_share_amt ,old.procedure_type_id ,old.is_pacs_req,old.ref_share_per,old.is_review_applicable ,old.review_time ,old.bill_of_material ,old.product_category_id ,old.bed_category_id,old.doc_ref_per ,old.is_cyclic ,old.sample_collection,old.surgery_grade_id ,old.is_doc_share_per_wise ,old.is_ref_share_per_wise ,old.lab_auto_mail_exclusion ,old.is_outsource_job ,old.pre_requisite ,old.pre_requisite_details ,now());
end if;RETURN NEW;END;$function$;

