-- DROP FUNCTION public.trigger_autoindnet();
CREATE OR REPLACE FUNCTION public.trigger_autoindnet()RETURNS triggerLANGUAGE plpgsqlAS $function$DECLAREcurrentQty int;minQty int;maxQty int;indentId int;itemId int;uomType int;uomUnit int;indentNumber character varying;assetType int;isConsignment boolean;-- added by minesh for consignmentBatch (if consignment batch then do not to gen auto indent).batchNo character varying;lotNo character varying;consignmentBatchCount int;inventorystoreid int;BEGINcurrentQty = 0;minQty = 0;consignmentBatchCount = 0;inventorystoreid=0;select available_qty into currentQty from inventory.t_store_stock where store_id = old.store_id and batch_id = old.batch_id;/* select item_id into itemId from inventory.t_batch where id = old.batch_id; */-- origin commented above and added this by mineshselect item_id, batch_no, lot_no into itemId, batchNo,lotNo from inventory.t_batch where id = old.batch_id;select count(*) into consignmentBatchCount from inventory.t_batch as batch where batch.batch_no = batchNo and batch.lot_no = lot_no and is_consignment = true;select sim.min_qty, sim.max_qty into minQty, maxQty from public.m_store_item_mapper as sim where sim.store_id = old.store_id and sim.item_id = itemId;select uom_type_id, uom_unit_id into uomType, uomUnit from public.m_unit_of_measurement where item_id = itemId and store_uom = true;select inventory_store_id into inventorystoreid from public.m_application_configuration where organization_id=old.organization_id and unit_id=old.unit_id;select is_consignment into isConsignment from public.m_item where id = itemId;select assetCategory.asset_type_id into assetType from public.m_item iteminner join public.m_generic generic on generic.id = item.generic_idinner join public.m_product_category productCategory on productCategory.id = generic.product_category_idinner join public.m_asset_category assetCategory on assetCategory.id = productCategory.asset_category_idwhere item.id = itemId;/* if currentQty &lt;= minQty and assetType = 1 then */-- origin commented above and added this by mineshif currentQty &lt;= minQty and assetType = 1 and consignmentBatchCount = 0 thenselect * into indentNumber from public.t_generate_prefix_number(old.store_id, old.unit_id, 2);
--insert into inventory.t_store_indent (priority_id, unit_id, organization_id, indent_no, from_store_id, to_store_id, indent_type_id, status_id, approval_status_id, added_by, updated_by, is_consignment)--values (1, old.unit_id, old.organization_id, indentNumber, old.store_id,inventorystoreid, 2, 1, 1, 1, 1, isConsignment) returning id into indentId;--insert into inventory.t_store_indent_detail(unit_id, organization_id, store_indent_id, item_id, uom_type_id, uom_unit_id, status_id,indent_quantity, pending_quantity, updated_by, added_by)--values (old.unit_id, old.organization_id, indentId, itemId, uomType, uomUnit, 1,maxQty, maxQty, 1, 1);
END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.trigger_check_and_fix_mismatch();
CREATE OR REPLACE FUNCTION public.trigger_check_and_fix_mismatch()RETURNS triggerLANGUAGE plpgsqlAS $function$DECLAREv_total_debit NUMERIC;v_total_credit NUMERIC;v_diff NUMERIC;BEGIN-- Only for allowed units and backdated entriesIF NEW.voucher_date &lt; CURRENT_DATE AND NEW.unit_id IN (38, 99, 107, 114, 121) THEN-- Get current totals for the voucher groupSELECT SUM(debit_amount), SUM(credit_amount)INTO v_total_debit, v_total_creditFROM t_tally_interfaceWHERE voucher_no = NEW.voucher_no AND unit_id = NEW.unit_id;v_diff := v_total_debit - v_total_credit;-- If mismatch, fix the last rowIF v_diff &lt;&gt; 0 THENUPDATE t_tally_interfaceSETdebit_amount = CASEWHEN v_diff &lt; 0 THEN debit_amount + ABS(v_diff)ELSE debit_amountEND,credit_amount = CASEWHEN v_diff &gt; 0 THEN credit_amount + ABS(v_diff)ELSE credit_amountENDWHERE tally_transaction_id = (SELECT MAX(tally_transaction_id)FROM t_tally_interfaceWHERE voucher_no = NEW.voucher_no AND unit_id = NEW.unit_id);
-- 🔍 Log the mismatchINSERT INTO t_tally_mismatch_log (voucher_no, voucher_date, unit_id,total_debit, total_credit, diff) VALUES (NEW.voucher_no, NEW.voucher_date, NEW.unit_id,v_total_debit, v_total_credit, v_diff);
RAISE NOTICE '✅ Mismatch corrected and logged for voucher %', NEW.voucher_no;END IF;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.update_due_amount();
CREATE OR REPLACE FUNCTION public.update_due_amount()RETURNS triggerLANGUAGE plpgsqlAS $function$BEGINIF NEW.outstanding_amount = 0 THENUPDATE pharmacy.t_pharmacy_bill_payee_detailsSET due_amount = 0WHERE t_sale_id = NEW.id;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.update_orderdetails();
CREATE OR REPLACE FUNCTION public.update_orderdetails()RETURNS triggerLANGUAGE plpgsqlAS $function$beginif new.service_id = 3480 thenUPDATE public.t_order_detailsSET service_rendered = 1 WHERE order_details_id = new.order_details_id;END IF;RETURN NEW;END;$function$;

-- DROP FUNCTION public.update_reportgroupheader1(int4, int4);
CREATE OR REPLACE FUNCTION public.update_reportgroupheader1(fromorg integer, toorg integer)RETURNS integerLANGUAGE plpgsqlAS $function$Declarea1 cursor for select * from m_reportgroupheader_master where organization_id=fromorg order by reportgroupheader_id ;a2 cursor(x int) for Select * from m_reports_master where organization_id=fromorg and reportgroupheader_id = x order by report_id ;a3 cursor(y int) for Select * from m_reports_details where organization_id =fromorg and report_id = y order by report_detail_id ;r1 m_reportgroupheader_master%rowtype;r2 m_reports_master%rowtype;r3 m_reports_details%rowtype;cnt int:=0;cnt1 int:=0; cnt2 int:=0;section_seq int; section_seq1 int;last int:= (select coalesce(max(reportgroupheader_id),0) from m_reportgroupheader_master);
last1 int:= (select coalesce(max(report_id),0) from m_reports_master);
last2 int:= (select coalesce(max(report_detail_id),0) from m_reports_details);
begin open a1;cnt:=last+1;Loop fetch a1 into r1;exit when not found;INSERT INTO public.m_reportgroupheader_master(reportgroupheader_id, reportgroupheader_name, status, organization_id, unit_id, created_by, created_date, updated_by, updated_date)VALUES(cnt, r1.reportgroupheader_name, r1.status, toorg, r1.unit_id, r1.created_by, r1.created_date, r1.updated_by, r1.updated_date);
open a2(r1.reportgroupheader_id);
cnt1:=last1+1; loopfetch a2 into r2;exit when not found;select nextval('m_reports_master_seq') into section_seq; INSERT INTO public.m_reports_master(report_id, report_name, "action", status, organization_id, unit_id, created_by, created_date, updated_by, updated_date, reportgroupheader_id)VALUES(section_seq, r2.report_name, r2.action , r2.status, toorg, 1, 1, r2.created_date, r2.updated_by, r2.updated_date, cnt);
open a3(r2.report_id);
cnt2:=last2+1;loop fetch a3 into r3;exit when not found;select nextval('m_reports_details_seq') into section_seq1; INSERT INTO public.m_reports_details(report_detail_id, report_id, parameter_name, parameter_id, control_name, view_name, status, organization_id, unit_id, created_by, created_date, updated_by, updated_date, is_compulsory, paramtype, lable)VALUES(section_seq1, section_seq, r3.parameter_name, r3.parameter_id, r3.control_name, r3.view_name, r3.status, toorg, r3.unit_id, r3.created_by, r3.created_date, r3.updated_by, r3.updated_date, r3.is_compulsory, r3.paramtype, r3.lable);
cnt2:= cnt2 +1;End loop;close a3;end loop;close a2;cnt:= cnt +1;end loop;close a1;return cnt;end;$function$;

