-- service.get_servicemaster source
CREATE OR REPLACE VIEW service.get_servicemasterAS SELECT sm.service_master_id,sm.service_standard_code,sm.service_standard_name,sp.speciality_name,ssp.sub_speciality_name,sm.created_date,sm.created_by,sm.updated_by,sm.updated_date,(emadded.first_name::text || ' '::text) || emadded.last_name::text AS addedusername,(emupdated.first_name::text || ' '::text) || emupdated.last_name::text AS updatedusername,sm.statusFROM service.m_service_master smLEFT JOIN doctor.m_speciality_master sp ON sm.speciality_id = sp.speciality_idLEFT JOIN doctor.m_sub_speciality_master ssp ON sm.sub_speciality_id = ssp.sub_speciality_idLEFT JOIN m_user_master umadded ON umadded.user_id = sm.created_byLEFT JOIN m_employee_master emadded ON emadded.user_id = umadded.user_idLEFT JOIN m_user_master umupdated ON umupdated.user_id = sm.updated_byLEFT JOIN m_employee_master emupdated ON emupdated.user_id = umupdated.user_idORDER BY sm.service_standard_name;-- DROP SCHEMA sso;
